insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (20066, 'Il segnale blu e rotondo con una freccia bianca indica una direzione che devi seguire per forza. In questo caso, la freccia punta a sinistra, quindi sei obbligato a svoltare a sinistra.', 'La parola ''obbligo'' significa che non hai scelta, devi fare così.', 'Freccia blu rotonda = devi andare lì.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
