insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (20080, 'No, è falso. I segnali di divieto sono rotondi con un bordo rosso e un simbolo nero (es. ''Divieto di accesso''). Questo è un segnale di obbligo, è blu con un simbolo bianco.', 'La parola ''divieto'' significa ''non puoi fare''. Questo segnale invece ti dice ''devi fare''.', 'Blu rotondo = obbligo. Rosso rotondo = divieto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
