insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (20082, 'No, è falso. Questo segnale non indica un senso unico parallelo. Indica solo che devi svoltare a sinistra. I segnali di senso unico sono diversi (sono quadrati blu con una freccia dritta).', 'La frase ''senso unico parallelo'' è un concetto che non ha relazione con questo segnale.', 'Freccia blu rotonda = svolta, non senso unico parallelo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
