    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (20083, 'Il segnale blu con la freccia a sinistra indica che sei obbligato a svoltare in quella direzione. Non puoi andare dritto o a destra, l''unica scelta è svoltare a sinistra.', 'La parola ''soltanto'' è fondamentale: significa che non ci sono altre opzioni, solo la svolta a sinistra.', 'Freccia blu a sinistra = Solo a sinistra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
