    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (20084, 'Se il segnale ti obbliga a svoltare a sinistra, significa che non puoi continuare ad andare dritto. La direzione ''dritto'' è vietata in questo punto.', 'La frase ''non è consentito'' significa che è proibito, non si può fare.', 'Obbligo a sinistra = Dritto vietato.')
