    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (20087, 'La freccia nel segnale punta chiaramente a sinistra. Questo significa che l''obbligo è di svoltare a sinistra, non di proseguire dritto.', 'La frase ''proseguire diritto'' è l''opposto di quanto indicato dalla freccia.', 'La freccia indica la direzione obbligatoria.')
