insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22356, 'È vero. Anche le macchine operatrici con pneumatici (gommate) non possono superare i 40 km/h.', 'Non ci sono parole trappola evidenti. È un dato preciso da ricordare.', 'Macchina operatrice gommata: 40 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
