insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22357, 'Questa affermazione è VERA. Per i neopatentati, cioè chi ha la patente da meno di 3 anni, il limite di velocità in autostrada è ridotto a 100 km/h, invece dei normali 130 km/h.', 'La frase chiave è ''meno di 3 anni'', che identifica i neopatentati e i loro limiti speciali.', 'Neopatentati: Autostrada 100.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22358, 'Questa affermazione è VERA. Anche sulle strade extraurbane principali, i neopatentati (chi ha la patente da meno di 3 anni) devono rispettare un limite di 90 km/h, invece dei normali 110 km/h.', 'Ancora una volta, ''meno di 3 anni'' è la condizione che cambia il limite di velocità.', 'Neopatentati: Extraurbane principali 90.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22359, 'Questa affermazione è VERA. Andare molto veloce fa consumare più benzina o diesel e, di conseguenza, aumenta l''inquinamento dell''aria.', 'Le parole ''incide sul'' significano che ha un effetto o una conseguenza.', 'Veloce = più benzina, più smog.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22360, 'Questa affermazione è VERA. Accelerare e frenare spesso e in modo improvviso (brusche variazioni) fa consumare molto più carburante rispetto a una guida fluida e costante.', 'Le parole ''Brusche variazioni'' indicano cambiamenti improvvisi e non graduali.', 'Guida fluida = risparmio carburante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22361, 'Questa affermazione è VERA. La velocità con cui affronti una curva è molto importante. Se vai troppo veloce, il veicolo potrebbe perdere aderenza e non ''tenere'' bene la strada, rischiando di sbandare.', 'La ''tenuta di strada'' è la capacità del veicolo di rimanere stabile e aderente alla strada.', 'Curva: velocità giusta = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22362, 'Questa affermazione è VERA. Se si entra in curva a una velocità troppo alta, le forze che agiscono sul veicolo possono essere così forti da farlo perdere il controllo e, nei casi più gravi, farlo ribaltare, cioè capovolgere.', 'L''''eccessiva velocità'' significa andare troppo forte, oltre il limite di sicurezza. ''Ribaltamento'' significa che il veicolo si capovolge.', 'Curva troppo veloce = ribaltamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22363, 'Questa affermazione è FALSA. In curva, è fondamentale avere il veicolo in marcia (con una marcia inserita) per poter controllare la velocità con il motore e avere la massima stabilità. Tenere il pedale della frizione abbassato significa che il motore è scollegato dalle ruote, e questo fa perdere il controllo del veicolo, rendendolo molto pericoloso.', 'La frase ''pedale della frizione abbassato'' significa che la frizione è premuta, e il veicolo è ''in folle'' o ''a ruota libera''. Questo è pericoloso in curva.', 'In curva: MAI frizione abbassata!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22364, 'Questa affermazione è FALSA. Come abbiamo visto, per i neopatentati (chi ha la patente da meno di tre anni) il limite di velocità in autostrada è di 100 km/h, non 110 km/h.', 'Attenzione al numero ''110 km/h'', che è il limite sbagliato per i neopatentati in autostrada.', 'Autostrada neopatentati = 100, non 110.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22365, 'Questa affermazione è FALSA. Per i neopatentati (chi ha la patente da meno di 3 anni), il limite di velocità sulle strade extraurbane principali è di 90 km/h, non 110 km/h. I 110 km/h sono il limite per gli altri conducenti.', 'Il numero ''110 km/h'' è il limite normale, ma non quello per i neopatentati su questo tipo di strada.', 'Extraurbane principali neopatentati = 90, non 110.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22366, 'Un carrello appendice è un piccolo rimorchio leggero che non cambia il limite di velocità dell''autovettura. Quindi, in autostrada, il limite rimane 130 km/h per l''autovettura con carrello appendice, se non ci sono condizioni particolari come la pioggia.', 'La parola ''ordinariamente'' significa ''normalmente'', cioè in condizioni meteo buone. ''Carrello appendice'' è diverso da ''rimorchio'', che invece riduce la velocità.', 'Carrello appendice = stessa velocità dell''auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22367, 'Quando un''autovettura traina un rimorchio (più grande di un carrello appendice), la velocità massima consentita in autostrada è ridotta a 80 km/h per motivi di sicurezza.', 'La parola chiave è ''rimorchio''. Ricorda che ''rimorchio'' e ''carrello appendice'' hanno limiti diversi.', 'Auto + rimorchio in autostrada = 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22368, 'I motocicli, come le autovetture, possono raggiungere la velocità massima di 130 km/h sulle autostrade, in condizioni normali.', 'Anche qui ''ordinariamente'' indica condizioni normali. I motocicli hanno gli stessi limiti delle autovetture sulle autostrade.', 'Moto in autostrada = 130 km/h (come l''auto).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22369, 'Gli autocaravan (i camper) che hanno una massa complessiva fino a 3,5 tonnellate sono considerati veicoli leggeri e seguono gli stessi limiti di velocità delle autovetture, quindi 130 km/h in autostrada.', 'La condizione ''fino a 3,5 tonnellate'' è fondamentale. Se superano questa massa, i limiti cambiano. ''Ordinariamente'' significa in condizioni normali.', 'Camper leggeri (fino a 3.5t) = velocità auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22370, 'Un caravan è un tipo di rimorchio (la roulotte). Quindi, un''autovettura che traina un caravan ha lo stesso limite di velocità di un''autovettura con rimorchio in autostrada, cioè 80 km/h.', 'La parola ''caravan'' è un sinonimo di ''rimorchio'' in questo contesto, quindi il limite è lo stesso.', 'Auto + caravan in autostrada = 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22371, 'Sulle strade extraurbane principali, il limite massimo di velocità per i motocicli è di 110 km/h, come per le autovetture, in condizioni normali.', 'Attenzione al tipo di strada: ''strade extraurbane principali''. ''Ordinariamente'' indica condizioni normali.', 'Moto su extraurbane principali = 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22372, 'Anche sulle strade extraurbane principali, il carrello appendice non modifica il limite di velocità dell''autovettura, che rimane 110 km/h.', 'Ricorda che il ''carrello appendice'' non riduce la velocità del veicolo che lo traina.', 'Carrello appendice = stessa velocità dell''auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22373, 'Quando un''autovettura traina un rimorchio, anche se è per il trasporto di imbarcazioni, il limite di velocità sulle strade extraurbane principali è di 70 km/h.', 'La parola chiave è ''rimorchio'', non importa cosa trasporta. ''Strade extraurbane principali'' è il tipo di strada.', 'Auto + rimorchio su extraurbane principali = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22374, 'Sulle strade extraurbane secondarie, il limite massimo di velocità per i motocicli è di 90 km/h, come per le autovetture.', 'Attenzione al tipo di strada: ''strade extraurbane secondarie''.', 'Moto su extraurbane secondarie = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22375, 'Un caravan è un rimorchio. Sulle strade extraurbane secondarie, il limite per un''autovettura che traina un rimorchio (come un caravan) è di 70 km/h, indipendentemente dalla sua massa se rientra nei limiti di traino.', 'La parola ''caravan'' indica un rimorchio. La massa di ''900 chilogrammi'' è un dettaglio che non cambia il limite per questa categoria di veicoli su questo tipo di strada.', 'Auto + caravan su extraurbane secondarie = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22376, 'Falso! Le autovetture con rimorchio in autostrada hanno un limite di velocità di 80 km/h, non 130 km/h. Il rimorchio riduce sempre la velocità massima consentita.', 'La frase ''con rimorchio'' è la parola trappola. Non puoi andare a 130 km/h con un rimorchio in autostrada.', 'Auto + rimorchio in autostrada = 80 km/h (non 130!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22377, 'Falso! I motocicli in autostrada possono andare fino a 130 km/h, come le autovetture. Il limite di 90 km/h è per le strade extraurbane secondarie.', 'Il valore ''90 km/h'' è la parola trappola, perché è il limite per un altro tipo di strada.', 'Moto in autostrada = 130 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22378, 'Falso! Gli autocaravan (camper) fino a 3,5 tonnellate hanno il limite di 130 km/h in autostrada. Solo quelli più pesanti hanno limiti diversi, ma non 90 km/h in autostrada.', 'Il valore ''90 km/h'' è la parola trappola. Ricorda che i camper leggeri (fino a 3.5t) seguono i limiti delle auto.', 'Camper leggeri (fino a 3.5t) = 130 km/h in autostrada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22379, 'Falso! Un''autovettura che traina un caravan (che è un rimorchio) in autostrada ha un limite di 80 km/h, non 70 km/h. Il limite di 70 km/h è per le strade extraurbane principali e secondarie con rimorchio.', 'Il valore ''70 km/h'' è la parola trappola, perché è il limite per un altro tipo di strada.', 'Auto + caravan in autostrada = 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22380, 'Falso! In caso di pioggia, il limite di velocità sulle autostrade scende a 110 km/h per tutti i veicoli che normalmente possono andare a 130 km/h, inclusi quelli con carrello appendice. Non è 120 km/h.', 'Il valore ''120 km/h'' è la parola trappola. La condizione ''in caso di pioggia'' è importante e riduce il limite.', 'Pioggia in autostrada = 110 km/h per tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22381, 'Falso! Sulle strade extraurbane principali, il limite per i motocicli è di 110 km/h, non 100 km/h.', 'Il valore ''100 km/h'' è la parola trappola. Ricorda bene i limiti per ogni tipo di strada.', 'Moto su extraurbane principali = 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22382, 'Falso! Sulle strade extraurbane principali, il limite per autovetture con rimorchio (anche per imbarcazioni) è di 70 km/h, non 80 km/h. Il limite di 80 km/h è per auto con rimorchio in autostrada.', 'Il valore ''80 km/h'' è la parola trappola, perché è il limite per un altro tipo di strada (''autostrade'').', 'Auto + rimorchio su extraurbane principali = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22383, 'Falso! Sulle strade extraurbane secondarie, il limite per i motocicli è di 90 km/h, non 70 km/h. Il limite di 70 km/h è per auto con rimorchio su queste strade.', 'Il valore ''70 km/h'' è la parola trappola, perché è il limite per un''altra categoria di veicoli su questa strada.', 'Moto su extraurbane secondarie = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22384, 'È vero. La velocità deve essere sempre adeguata per non creare problemi agli altri veicoli. Guidare troppo lentamente può bloccare il traffico, proprio come guidare troppo velocemente.', 'La parola ''intralcio'' significa ostacolo o impedimento. Non solo la velocità eccessiva, ma anche quella troppo bassa può causare intralcio alla circolazione.', 'Né troppo veloce, né troppo lento: sii fluido!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22385, 'È vero. Quando arrivi a un incrocio e non hai la precedenza, devi rallentare o, se necessario, fermarti completamente per far passare i veicoli che hanno il diritto di passare prima di te. Questo è fondamentale per la sicurezza.', 'La frase ''all''occorrenza'' significa ''se necessario'' o ''se serve''. Non sempre devi fermarti, ma solo se la situazione lo richiede per dare la precedenza in sicurezza.', 'Precedenza? Rallenta o fermati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22386, 'È falso. Non esiste una regola che ti obbliga a ridurre la velocità o a fermarti in base all''ora del giorno, come mezz''ora prima del tramonto o dopo l''alba. La velocità si regola in base alle condizioni della strada, del traffico e della visibilità, non all''orario.', 'La parola ''obbligatorio'' è molto forte. Non è un obbligo di legge ridurre la velocità solo per l''ora del giorno. Si accendono le luci, ma la velocità si adatta ad altri fattori.', 'L''ora del giorno non impone la velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22387, 'È falso. La velocità con cui guidi non dipende dal tipo di motore della tua auto (benzina, diesel, elettrico, ecc.). La velocità deve essere regolata in base ai limiti, alle condizioni della strada, del traffico e della visibilità.', 'La frase ''tipo di alimentazione del motore'' è un dettaglio tecnico dell''auto che non ha alcuna influenza sulle regole di comportamento e sulla velocità da tenere in strada.', 'Carburante non è velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22388, 'È falso. Devi regolare la tua velocità in base a chi ti precede, alle condizioni della strada, al traffico e ai limiti di velocità, non in base a chi ti segue. Chi ti segue deve mantenere la distanza di sicurezza e adattarsi alla tua velocità (se corretta).', 'La frase ''veicoli che seguono'' è la parola trappola. La tua responsabilità principale è verso chi ti sta davanti e le condizioni della strada, non verso chi è dietro di te.', 'Guida per te, non per chi ti segue.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22389, 'È falso. Che la tua auto abbia un cambio manuale o automatico non cambia le regole su come devi regolare la velocità. La velocità si adatta sempre alle condizioni esterne (strada, traffico, meteo) e ai limiti, non al meccanismo interno dell''auto.', 'La frase ''tipo di cambio di velocità'' è un altro dettaglio tecnico del veicolo che non influenza le decisioni sulla velocità da tenere in strada.', 'Cambio manuale o automatico, la velocità è la stessa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22390, 'Quando la strada non ti permette di vedere bene (ad esempio in curva o su un dosso), devi guidare più lentamente. Questo ti dà più tempo per reagire se c''è un pericolo improvviso.', 'La frase chiave è ''visuale non libera''. Significa che non vedi bene la strada davanti a te. In questi casi, la velocità deve essere sempre ridotta.', 'Non vedi? Rallenta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22391, 'La tua velocità deve essere sempre sicura per te e per gli altri. Non devi mai guidare così veloce da creare un pericolo per la circolazione, per le persone o per le cose.', 'La parte importante è ''non costituisca pericolo''. Questo è un principio fondamentale: la sicurezza è sempre la priorità numero uno.', 'Sicurezza prima di tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22392, 'Devi guidare a una velocità che ti permetta di frenare o fare una manovra in sicurezza se succede qualcosa di inaspettato, come un bambino che attraversa la strada o un ostacolo improvviso.', 'Le parole ''intervenire con sicurezza in caso di imprevisti'' sono cruciali. Significa essere sempre pronti a reagire senza rischiare incidenti.', 'Pronto a frenare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22393, 'Se sei stanco, non ti senti bene o sei distratto, devi guidare più lentamente del solito. La tua condizione fisica e mentale influenza la tua capacità di guidare in sicurezza.', 'Il termine ''proprie condizioni psicofisiche'' si riferisce a come stai tu, il conducente. Se non sei al 100%, devi adattare la velocità.', 'Stanco? Vai piano!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22394, 'Un veicolo molto carico frena più lentamente e si comporta in modo diverso. Per questo, se hai un carico pesante, devi ridurre la velocità per mantenere il controllo e frenare in tempo.', 'La parola ''carico del veicolo'' è importante. Più il veicolo è pesante, più spazio serve per frenare e più difficile è controllarlo.', 'Carico pesante? Velocità prudente!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22395, 'FALSO. La velocità non dipende da quanto tempo hai a disposizione. Non puoi guidare più veloce solo perché sei in ritardo. La velocità deve essere sempre sicura e rispettare i limiti, non la tua fretta.', 'La frase ''tempo che abbiamo a disposizione'' è la parola trappola. La fretta non è mai una buona ragione per aumentare la velocità e mettere a rischio la sicurezza.', 'La fretta è cattiva consigliera!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22396, 'FALSO. Fuori dai centri abitati, i limiti di velocità sono generalmente più alti (ad esempio 90 km/h sulle strade normali). Non è obbligatorio andare sempre a una velocità ''moderata'' (cioè lenta), ma a una velocità ''adeguata'' alle condizioni della strada e del traffico, rispettando i limiti.', 'La parola ''moderata'' è la trappola. Fuori città non devi andare per forza piano, ma alla velocità giusta, che può essere anche alta se le condizioni lo permettono e rispetti i limiti. ''Adeguata'' è la parola corretta, non ''moderata''.', 'Fuori città non è sempre ''piano'', ma ''giusto''!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22397, 'Sì, è vero. In Italia, su alcuni tratti di autostrada che hanno caratteristiche speciali (ad esempio, tre corsie più corsia di emergenza per senso di marcia) e solo se c''è un segnale specifico che lo indica, la velocità massima può essere aumentata a 150 km/h. Non è la regola generale, ma un''eccezione.', 'Le parole ''può essere'', ''apposito segnale'' e ''particolari caratteristiche'' sono importanti. Indicano che non è sempre così, ma solo in condizioni molto specifiche e con un cartello che lo permette.', '150 km/h: solo autostrada ''super'' e con segnale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22398, 'Sì, è vero. La velocità massima normale sulle autostrade è di 130 km/h. Questo limite vale se non ci sono segnali che indicano una velocità diversa, ad esempio per lavori, traffico intenso o maltempo.', 'La frase ''Salvo diversa segnalazione'' è chiave. Significa che questo è il limite standard, ma un cartello può cambiarlo (quasi sempre abbassandolo).', 'Autostrada: 130 km/h (base).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22399, 'Sì, è vero. Nei centri abitati, cioè nelle città e nei paesi, il limite massimo di velocità è di 50 km/h. Questo serve per la sicurezza di pedoni e altri veicoli. Solo in casi eccezionali e con un segnale specifico, il limite può essere diverso.', 'Anche qui, ''Salvo diversa segnalazione'' è importante. Il limite di 50 km/h è la regola generale, ma un segnale può indicare un limite inferiore (es. 30 km/h) o, molto raramente, superiore su strade particolari.', 'Centri abitati: 50 km/h (base).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22400, 'Sì, è vero. I ciclomotori (come gli scooter 50cc) hanno un limite massimo di velocità di 45 km/h. Questo limite è stabilito dalla legge per la loro categoria e non può essere superato.', 'La frase ''Salvo diversa segnalazione'' in questo caso si riferisce a un limite che potrebbe essere inferiore (ad esempio, 30 km/h in una zona specifica), ma il ciclomotore non può comunque superare i 45 km/h per le sue caratteristiche tecniche.', 'Ciclomotori: massimo 45 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22401, 'Sì, è vero. Le macchine agricole (come i trattori) e le macchine operatrici (come gli escavatori) che hanno pneumatici (cioè ruote normali) non possono superare i 40 km/h. Sono veicoli lenti e pesanti, quindi hanno un limite di velocità più basso per la sicurezza.', 'La frase ''Salvo diversa segnalazione'' indica che un cartello potrebbe imporre un limite ancora più basso, ma 40 km/h è il loro limite massimo standard.', 'Macchine agricole/operatrici: 40 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22402, 'Sì, è vero. Quando piove, la strada diventa scivolosa e la visibilità diminuisce. Per questo motivo, in autostrada il limite di velocità scende da 130 km/h a 110 km/h per aumentare la sicurezza.', 'La condizione ''in caso di pioggia'' è la parola chiave. È la situazione che fa cambiare il limite standard.', 'Autostrada + Pioggia = 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22403, 'Sì, è vero. Anche in caso di grandine, come per la pioggia, le condizioni della strada e la visibilità peggiorano molto. Sulle strade extraurbane principali, il limite di velocità scende da 110 km/h a 90 km/h per garantire maggiore sicurezza.', 'La condizione ''in caso di grandine'' è la parola chiave. Il maltempo riduce i limiti di velocità per sicurezza.', 'Extraurbana principale + Maltempo = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22404, 'Sì, è vero. Normalmente nei centri abitati il limite è 50 km/h. Tuttavia, su alcune strade urbane particolari, che sono larghe, ben illuminate e senza incroci a raso (come alcune tangenziali urbane), se c''è un segnale specifico, il limite può essere aumentato a 70 km/h.', 'Le parole ''appositi segnali'' e ''particolari caratteristiche'' sono fondamentali. Indicano che è un''eccezione alla regola generale dei 50 km/h nei centri abitati.', 'Città 70 km/h: solo con segnale e strada ''speciale''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22405, 'Sì, è vero. Le strade extraurbane principali sono strade a doppia carreggiata (come le superstrade) e il loro limite di velocità standard è di 110 km/h, se non ci sono segnali che indicano un limite diverso.', 'La frase ''Salvo diversa segnalazione'' è importante. Significa che questo è il limite di base, ma può essere modificato da un cartello (ad esempio, a 90 km/h in caso di pioggia o per lavori).', 'Extraurbana principale: 110 km/h (base).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22406, 'No, è falso. Le strade urbane sono le strade che si trovano all''interno dei centri abitati. Il limite massimo di velocità consentito nei centri abitati è di 50 km/h, non 80 km/h. Andare a 80 km/h in città è troppo pericoloso.', 'La parola ''urbane'' si riferisce ai centri abitati. Il limite di 80 km/h è la trappola, perché è molto più alto del limite reale di 50 km/h.', 'Strade urbane = 50 km/h, non 80 km/h!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22407, 'No, è falso. I quadricicli non leggeri (come i quad o le ''minicar'' più potenti) hanno un limite massimo di velocità di 80 km/h fuori dai centri abitati. Il limite di 70 km/h non è corretto per questa categoria di veicoli.', 'La trappola è il numero ''70 km/h''. È importante ricordare il limite specifico di ''80 km/h'' per i quadricicli non leggeri.', 'Quadricicli non leggeri: 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22408, 'No, è falso. Il limite di 150 km/h non è consentito su ''qualsiasi'' autostrada. È un''eccezione molto rara, possibile solo su tratti specifici di autostrada che hanno particolari caratteristiche e solo se c''è un segnale che lo indica. La regola generale in autostrada è 130 km/h.', 'La parola ''qualsiasi'' è la trappola. Rende la frase falsa perché il limite di 150 km/h non è universale per tutte le autostrade, ma solo per alcune, in condizioni specifiche.', '150 km/h non è per ''qualsiasi'' autostrada, ma solo per alcune speciali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22409, 'Sulle strade extraurbane principali, le autovetture possono viaggiare fino a un massimo di 110 km/h, a meno che non ci siano segnali diversi. Quindi, l''affermazione è VERA.', 'Nessuna parola trappola particolare. Ricorda bene il tipo di strada e il veicolo.', 'Auto su extraurbana principale = 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22410, 'Quando un''autovettura traina un rimorchio, come una caravan, il limite di velocità sulle strade extraurbane principali scende a 70 km/h. Non importa il peso della caravan, se traini un rimorchio, il limite è ridotto. Quindi, l''affermazione è VERA.', 'La frase ''traina caravan'' è la chiave: indica un veicolo con rimorchio.', 'Auto + Rimorchio = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22411, 'La categoria ''autoveicoli fino a 3,5t'' include le autovetture e i motocicli, per i quali il limite è 110 km/h. Anche se ci sono altri veicoli in questa categoria con limiti diversi (come autocaravan o autocarri), la domanda è generica e il limite di 110 km/h è valido per una parte significativa di essi. Quindi, l''affermazione è VERA.', 'La parola ''autoveicoli'' è generica. In questo contesto, si riferisce ai veicoli più veloci della categoria.', 'Autoveicoli leggeri (generico) = 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22412, 'Gli autotreni sono veicoli molto lunghi e pesanti, formati da una motrice e un rimorchio. Per motivi di sicurezza, hanno limiti di velocità più bassi. Sulle strade extraurbane principali, il limite per gli autotreni è di 70 km/h. Quindi, l''affermazione è VERA.', 'La parola ''autotreni'' indica un veicolo complesso e con limiti specifici.', 'Autotreni = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22413, 'Per gli autocarri con massa complessiva fino a 3,5 tonnellate, il limite di velocità sulle strade extraurbane principali è di 80 km/h, non 100 km/h. I 100 km/h sono il limite per gli autocarri leggeri in autostrada. Quindi, l''affermazione è FALSA.', 'Il valore ''100 km/h'' è la parola trappola, perché è il limite per gli autocarri leggeri in autostrada, non su extraurbane principali.', 'Autocarri leggeri su extraurbana principale = 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22414, 'Per gli autocaravan (i camper) con massa complessiva fino a 3,5 tonnellate, il limite di velocità sulle strade extraurbane principali è di 90 km/h, non 100 km/h. I 100 km/h sono il limite per gli autocaravan leggeri in autostrada. Quindi, l''affermazione è FALSA.', 'Il valore ''100 km/h'' è la parola trappola, perché è il limite per gli autocaravan leggeri in autostrada, non su extraurbane principali.', 'Autocaravan leggeri su extraurbana principale = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22415, 'Le autovetture che trainano un rimorchio, anche se leggero, hanno un limite di velocità ridotto. Sulle strade extraurbane principali, questo limite è di 70 km/h, non 80 km/h. Quindi, l''affermazione è FALSA.', 'Il valore ''80 km/h'' è la parola trappola. ''Rimorchio leggero'' non cambia il limite di 70 km/h per le auto.', 'Auto + Rimorchio (anche leggero) = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22416, 'I motocicli, come le autovetture, possono raggiungere una velocità massima di 110 km/h sulle strade extraurbane principali, a meno che non ci siano segnali diversi. Il limite di 100 km/h è sbagliato per i motocicli su questo tipo di strada. Quindi, l''affermazione è FALSA.', 'Il valore ''100 km/h'' è la parola trappola. I motocicli hanno lo stesso limite delle autovetture.', 'Moto su extraurbana principale = 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22417, 'Un carrello appendice è considerato un tipo di rimorchio. Perciò, un''autovettura che traina un carrello appendice ha lo stesso limite di velocità di un''autovettura con rimorchio, cioè 70 km/h sulle strade extraurbane principali. Il limite di 100 km/h è sbagliato. Quindi, l''affermazione è FALSA.', 'La frase ''carrello appendice'' è importante: è un rimorchio. Il valore ''100 km/h'' è la parola trappola.', 'Auto + Carrello appendice = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22418, 'Sulle strade extraurbane secondarie, i motocicli possono viaggiare fino a un massimo di 90 km/h, proprio come le autovetture. Questo è il limite generale per molti veicoli su queste strade.', 'Nessuna parola trappola evidente. La domanda è diretta.', 'Moto e auto = 90 km/h su secondarie.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22419, 'Un''autovettura con un carrello appendice mantiene lo stesso limite di velocità di un''autovettura normale, cioè 90 km/h sulle strade extraurbane secondarie. Il carrello appendice non è considerato un rimorchio che abbassa il limite.', 'La parola ''carrello appendice'' è importante. Non confonderlo con un ''rimorchio'' vero e proprio.', 'Carrello appendice non cambia il limite (90 km/h).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22420, 'Quando un''autovettura traina un rimorchio, come quello per il trasporto di imbarcazioni, il limite di velocità sulle strade extraurbane secondarie si abbassa a 70 km/h per maggiore sicurezza.', 'La frase ''con rimorchio'' è la chiave. Indica che il limite è più basso.', 'Auto + rimorchio = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22421, 'Gli autocaravan (i camper) che hanno una massa complessiva fino a 3,5 tonnellate sono considerati veicoli leggeri e possono viaggiare fino a 90 km/h sulle strade extraurbane secondarie, come le autovetture.', 'La specifica ''fino a 3,5t'' è fondamentale. Per veicoli più pesanti il limite sarebbe diverso.', 'Camper leggeri (fino a 3.5t) = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22422, 'Anche gli autocarri con una massa complessiva fino a 3,5 tonnellate rientrano nella categoria dei veicoli leggeri e possono raggiungere i 90 km/h sulle strade extraurbane secondarie.', 'Anche qui, ''fino a 3,5t'' è la parte importante. Oltre questo peso, il limite cambia.', 'Autocarri leggeri (fino a 3.5t) = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22423, 'Gli autotreni sono veicoli molto lunghi e pesanti, composti da un trattore stradale e un rimorchio. Per la loro complessità e dimensione, hanno un limite di velocità ridotto a 70 km/h sulle strade extraurbane secondarie.', 'La parola ''autotreni'' indica un veicolo complesso e pesante, che ha limiti speciali.', 'Autotreni = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22424, 'I ciclomotori hanno un limite massimo di velocità di 45 km/h su tutte le strade, sia in città che fuori. Quindi, 70 km/h è un limite sbagliato per loro.', 'Il valore ''70 km/h'' è la parola trappola, perché non è il limite per i ciclomotori.', 'Ciclomotori = sempre 45 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22425, 'I quadricicli non leggeri (come i quad) hanno un limite massimo di velocità di 80 km/h fuori dai centri abitati, non 90 km/h. Quindi, l''affermazione è falsa.', 'Il valore ''90 km/h'' è la parola trappola, perché il limite corretto è 80 km/h.', 'Quadricicli non leggeri = 80 km/h (fuori città).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22426, 'I motocicli, come le autovetture, possono andare fino a 90 km/h sulle strade extraurbane secondarie. Il limite di 80 km/h è sbagliato per loro.', 'Il valore ''80 km/h'' è la parola trappola, perché il limite corretto è 90 km/h.', 'Moto = 90 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22427, 'Il limite di 100 km/h per le autovetture è valido sulle strade extraurbane principali. Sulle strade extraurbane secondarie, il limite è di 90 km/h.', 'Il valore ''100 km/h'' è la parola trappola, perché confonde le strade principali con le secondarie.', 'Secondarie = 90, Principali = 100.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22428, 'Un''autovettura che traina una caravan (che è un tipo di rimorchio) ha un limite di velocità di 70 km/h sulle strade extraurbane secondarie, non 80 km/h.', 'Il valore ''80 km/h'' è la parola trappola. ''Caravan'' indica un rimorchio.', 'Auto + rimorchio = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22429, 'Il limite di 100 km/h è per le strade extraurbane principali. Sulle strade extraurbane secondarie, per gli autoveicoli fino a 3,5 tonnellate (come autovetture o autocaravan leggeri), il limite è 90 km/h.', 'Il valore ''100 km/h'' è la parola trappola, perché è il limite delle strade principali, non secondarie.', 'Secondarie = 90, Principali = 100.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22430, 'Le autovetture con carrello appendice mantengono il limite di 90 km/h sulle strade extraurbane secondarie. Il carrello appendice non abbassa il limite di velocità, quindi 80 km/h è sbagliato.', 'Il valore ''80 km/h'' è la parola trappola. Ricorda che il ''carrello appendice'' non modifica il limite dell''auto.', 'Carrello appendice non cambia il limite (90 km/h).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22431, 'Questi adesivi (contrassegni) che mostrano un limite di velocità (60, 80, 100) sono messi dietro ad alcuni veicoli, come i mezzi pesanti o gli autobus, per indicare la loro velocità massima consentita. Quindi, è VERO.', 'La frase ''alcune categorie di veicoli'' è importante: significa che non tutti i veicoli li hanno, ma solo quelli specifici che hanno limiti di velocità particolari.', 'Contrassegni dietro = limiti speciali per il veicolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22432, 'Sì, questi adesivi servono proprio a dire qual è la velocità massima che quel veicolo può raggiungere. Non sono i limiti della strada, ma i limiti che il veicolo stesso non può superare. Quindi, è VERO.', 'La parte chiave è ''velocità massime consentite al veicolo'': indica che il limite è specifico per il mezzo, non per la strada in generale.', 'Numero sul contrassegno = velocità massima del veicolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22433, 'Sì, gli autobus, specialmente quelli più grandi o che fanno servizio di linea, devono avere questi contrassegni che indicano le loro velocità massime. Quindi, è VERO.', 'Anche qui, ''alcuni autobus'' è la parola chiave: non tutti gli autobus, ma quelli che rientrano nelle categorie previste dalla legge per avere questi limiti speciali.', 'Autobus grandi = contrassegno velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22434, 'Quando ci sono tanti tipi diversi di utenti sulla strada (macchine, bici, pedoni, animali) o veicoli che vanno a velocità diverse, è più difficile guidare in sicurezza. Per questo, devi andare più piano per evitare pericoli. Quindi, è VERO.', '''Traffico misto'' significa che ci sono tanti elementi diversi e imprevedibili sulla strada, che richiedono maggiore attenzione e una velocità ridotta.', 'Traffico misto = rallenta, più attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22435, 'Se la strada non è perfetta (ci sono buche, è bagnata, ci sono foglie), la tua auto potrebbe perdere aderenza o potresti non riuscire a frenare bene. Per questo, devi andare più piano per mantenere il controllo. Quindi, è VERO.', '''Regolare la velocità'' significa adattarla alle condizioni, non solo diminuirla, ma scegliere la velocità giusta per la situazione specifica del fondo stradale.', 'Fondo stradale brutto = velocità ridotta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22436, 'Questi contrassegni sono obbligatori per gli autocarri che superano le 3,5 tonnellate di massa complessiva. Gli autocarri più piccoli (fino a 3,5 tonnellate) seguono i limiti di velocità normali per le automobili e non hanno bisogno di questi adesivi speciali. Quindi, è FALSO.', 'La trappola è ''fino a 3,5 tonnellate''. I limiti speciali e i contrassegni sono per i veicoli *oltre* le 3,5 tonnellate.', 'Contrassegni velocità = veicoli pesanti (oltre 3,5t).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22437, 'Come per gli autocarri, anche gli autocaravan (camper) che pesano fino a 3,5 tonnellate non devono avere questi contrassegni. Seguono i limiti di velocità delle auto. Solo gli autocaravan più pesanti (oltre 3,5 tonnellate) li devono avere. Quindi, è FALSO.', 'Anche qui, ''fino a 3,5 tonnellate'' è la trappola. Sotto questa soglia, non sono necessari i contrassegni speciali.', 'Camper leggeri (fino a 3,5t) = no contrassegni speciali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22438, 'I motocicli, indipendentemente dalla loro cilindrata, non devono avere questi contrassegni di velocità. Questi adesivi sono per veicoli pesanti come autobus e autocarri. Quindi, è FALSO.', 'La parola ''motocicli'' è la chiave. I motocicli non rientrano nelle categorie di veicoli che devono esporre questi contrassegni.', 'Motocicli = no contrassegni velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22439, 'È vero. In prossimità di un incrocio ci sono molti pericoli, come altri veicoli che arrivano da diverse direzioni o pedoni che attraversano. Andare piano ti dà più tempo per vedere e reagire, evitando incidenti.', 'La frase ''particolarmente moderata'' significa che non basta rallentare un po'', ma bisogna essere molto prudenti e andare a una velocità bassa.', 'Incrocio = rallenta sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22440, 'È vero. Una strettoia è un tratto di strada dove c''è poco spazio per i veicoli. Andando piano, puoi manovrare meglio, evitare di toccare altri veicoli o ostacoli e passare in sicurezza.', 'La parola ''strettoie'' indica un luogo dove lo spazio è limitato, quindi richiede maggiore attenzione.', 'Strettoia = spazio ridotto, velocità ridotta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22441, 'È vero. Se la strada è stretta o ci sono ostacoli che rendono difficile il passaggio con un altro veicolo, devi andare piano. Questo ti permette di avere il controllo e di evitare collisioni.', 'L''espressione ''difficoltoso l''incrocio'' significa che è complicato passare senza problemi, quindi serve prudenza.', 'Difficoltà = prudenza e lentezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22442, 'È vero. Quando non puoi vedere bene cosa c''è più avanti (come in una curva cieca o su un dosso), devi ridurre la velocità. Così, se c''è un pericolo improvviso, hai più tempo per frenare o sterzare.', 'La frase ''manca la visibilità'' è la chiave: se non vedi, non puoi prevedere, quindi devi essere cauto.', 'Non vedi = non corri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22443, 'È vero. Se i pedoni camminano sulla strada perché non c''è un marciapiede, sono molto più vulnerabili. Devi andare molto piano per proteggerli e avere il tempo di fermarti se si muovono improvvisamente.', 'La condizione ''in mancanza di marciapiedi'' spiega perché i pedoni sono sulla carreggiata, rendendo la situazione più rischiosa.', 'Pedoni in strada = massima attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22444, 'È vero. Quando la strada è scivolosa (viscida) a causa di acqua, neve, ghiaccio, foglie o fango, le gomme del veicolo fanno meno presa. Diminuire la velocità ti aiuta a mantenere il controllo e a non sbandare.', 'La parola ''viscida'' significa scivolosa. È un segnale che le condizioni di aderenza sono ridotte.', 'Strada scivolosa = velocità bassa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22445, 'È falso. Non è vero che devi moderare la velocità *solo* subito dopo il tramonto. Devi essere prudente e moderare la velocità ogni volta che la visibilità diminuisce, quindi durante il tramonto, di notte e in condizioni di scarsa luce. La frase è troppo specifica e limitante.', 'L''espressione ''subito dopo'' è una trappola. La prudenza è necessaria per tutto il periodo di scarsa visibilità, non solo per un breve momento.', 'Buio = sempre prudenza, non solo ''subito dopo''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22446, 'È falso. La velocità deve essere moderata *in prossimità* dell''incrocio (cioè prima e mentre lo attraversi) per prevenire pericoli. *Dopo* aver superato l''incrocio, se la strada è libera e sicura, puoi riprendere la tua velocità normale.', 'La frase ''subito dopo'' è la parola trappola. La prudenza è richiesta *prima* e *durante* l''incrocio, non quando lo hai già superato.', 'Incrocio: prudenza *prima*, non *dopo*.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22447, 'È falso. La velocità deve essere regolata in base alla sicurezza, alle condizioni della strada, del traffico, del veicolo e del meteo. La tua fretta non è mai un buon motivo per andare più veloce, anzi, può causare incidenti.', 'La ''fretta del conducente'' non è un criterio valido per regolare la velocità. La sicurezza viene prima di tutto.', 'Fretta = pericolo, non velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22448, 'È falso. Le tue condizioni di salute sono importanti, ma non sono l''unico fattore da considerare. Devi tenere conto anche delle condizioni della strada, del traffico, del veicolo e del meteo. La parola ''solo'' rende la frase sbagliata.', 'La parola ''solo'' è una trappola. Indica che è l''unica cosa da considerare, ma ci sono molti altri fattori importanti per la sicurezza.', '''Solo'' = attenzione, spesso è falso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22449, 'È falso. Ci sono molte situazioni in cui devi andare più piano di 30 km/h, ad esempio in zone residenziali, in parcheggi, in caso di traffico molto intenso, scarsa visibilità o manovre particolari. La parola ''sempre'' rende la frase sbagliata.', 'L''espressione ''sempre superiore'' è una generalizzazione falsa. Non esiste una velocità minima fissa per tutte le situazioni.', '''Sempre'' o ''mai'' = quasi sempre falso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22450, 'È falso. Non c''è nessuna regola che ti obbliga a diminuire la velocità solo perché un autobus di linea ti sta seguendo. Devi mantenere la velocità adeguata alle condizioni della strada, del traffico e della sicurezza generale, non in base a chi ti sta dietro.', 'La frase ''seguiti da un autobus di linea'' è irrilevante. Il tipo di veicolo che ti segue non determina la tua velocità.', 'Chi ti segue non decide la tua velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22451, 'È importante adattare la velocità del veicolo alle condizioni della strada. Se la strada è rovinata, sporca o con buche, è più sicuro andare più piano per evitare incidenti o danni al veicolo.', 'Non ci sono parole trappola evidenti in questa domanda. È una regola di buon senso per la sicurezza.', 'Strada brutta, velocità ridotta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22452, 'Un forte vento che soffia di lato può spingere la tua auto e farti perdere il controllo. Diminuire la velocità ti aiuta a mantenere la stabilità e la direzione del veicolo.', 'Non ci sono parole trappola evidenti. ''Vento laterale'' è la condizione chiave.', 'Vento forte, meno velocità per stare in rotta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22453, 'Quando il sole ti abbaglia, non riesci a vedere bene la strada e gli altri veicoli. Rallentare ti dà più tempo per reagire a eventuali pericoli e riduce il rischio di incidenti.', 'La parola chiave è ''abbagliamento'', che significa essere accecati temporaneamente dalla luce.', 'Sole negli occhi, rallenta e non fai pasticci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22454, 'In caso di nebbia molto fitta, quando non si vede bene (meno di 100 metri), per la tua sicurezza e quella degli altri, le autorità possono imporre un limite di velocità molto basso, massimo 50 km/h, anche su strade dove normalmente si andrebbe più veloci.', 'Le parole chiave sono ''nebbia fitta'', ''visibilità inferiore a 100 m'' e ''non superiori a 50 km/h''. ''Possono essere imposti'' significa che non è sempre così, ma è una possibilità per la sicurezza.', 'Nebbia fitta (<100m), 50 km/h è il limite massimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22455, 'Questa affermazione è FALSA. Il limite massimo di velocità sulle strade extraurbane principali, se non ci sono altri segnali, è di 110 km/h, non 100 km/h. I 100 km/h sono il limite per le strade extraurbane secondarie.', 'La parola trappola è ''100 km/h''. Il limite corretto per le ''strade extraurbane principali'' è 110 km/h. Non confondere ''principali'' con ''secondarie''.', 'Principali = 110, Secondarie = 90.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22456, 'Questa affermazione è FALSA. Il limite massimo di velocità nei centri abitati è di 50 km/h, non 60 km/h. Inoltre, il limite finisce quando incontri il segnale di ''fine centro abitato'', non un chilometro dopo.', 'Ci sono due errori: ''60 km/h'' (il limite è 50) e ''valido fino ad un chilometro dopo l''uscita del paese'' (il limite finisce al segnale di fine centro abitato).', 'Centro abitato = 50. Il limite finisce al cartello, non dopo un chilometro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22457, 'Questa affermazione è FALSA. I segnali di indicazione (come quelli che ti dicono la direzione o la distanza di una città) servono a darti informazioni, ma non ti obbligano a rallentare. Devi diminuire la velocità solo se ci sono segnali di pericolo, di stop, di dare precedenza o specifici limiti di velocità.', 'La parola trappola è ''ogni qualvolta'' (ogni volta). Non tutti i segnali richiedono di rallentare. ''Segnale stradale di indicazione'' è la tipologia di segnale che non richiede un rallentamento automatico.', 'Indicazione = informazione, non rallentamento automatico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22458, 'È VERO. Le autovetture che trainano un rimorchio, come quello per i cavalli, hanno limiti di velocità ridotti. In autostrada, il limite massimo per loro è di 80 km/h.', 'La frase ''per il trasporto di cavalli'' è un dettaglio che non cambia la regola generale per le autovetture con rimorchio.', 'Autostrada + Rimorchio = 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22459, 'È VERO. Anche sulle strade extraurbane secondarie, le autovetture che trainano un rimorchio (come quello per i motocicli) devono rispettare un limite di velocità inferiore, che è di 70 km/h.', 'La frase ''per il trasporto di motocicli'' è un dettaglio, la regola vale per qualsiasi rimorchio.', 'Extraurbana secondaria + Rimorchio = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22460, 'È VERO. Quando ci sono lavori in corso sulla strada, è fondamentale rallentare e regolare la velocità per la sicurezza degli operai e per la tua.', 'L''espressione ''in particolare'' sottolinea l''importanza, ma la regola è sempre valida.', 'Lavori in corso = rallenta, massima attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22461, 'È VERO. Il triangolo mobile di pericolo segnala un ostacolo o un veicolo fermo. Quando lo vedi, devi subito ridurre la velocità per evitare incidenti.', 'L''espressione ''in particolare'' rafforza l''obbligo. ''Triangolo mobile di pericolo'' è il nome del segnale.', 'Triangolo di pericolo = rallenta subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22462, 'È VERO. In situazioni di traffico intenso, quando si formano file parallele, può capitare che la corsia di destra scorra più velocemente di quella di sinistra, ad esempio se la corsia di sinistra è bloccata da veicoli che devono svoltare.', 'La frase ''è possibile che'' indica una situazione che può verificarsi, non una regola fissa.', 'Traffico a file parallele: la destra può essere più veloce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22463, 'È VERO. Le corsie di canalizzazione servono a indirizzare il traffico verso diverse direzioni. In queste situazioni, il flusso di veicoli può essere diverso tra le corsie, e la corsia di destra può scorrere a una velocità superiore rispetto a quella di sinistra.', 'La frase ''è possibile che'' indica una possibilità, non una certezza. ''Corsie di canalizzazione'' sono quelle che dividono il traffico per destinazione.', 'Canalizzazione: la destra può essere più veloce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22464, 'È VERO. Quando il traffico è ''canalizzato'', cioè diviso in corsie per diverse direzioni, è normale che le velocità tra le corsie possano variare. Quindi, la corsia di destra può effettivamente scorrere più velocemente.', 'La frase ''è possibile che'' indica una possibilità. ''Traffico canalizzato'' significa che le corsie sono separate per diverse direzioni.', 'Traffico canalizzato: la destra può essere più veloce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22465, 'È FALSO. Il limite massimo di velocità sulle autostrade in Italia è di 130 km/h, indipendentemente dal numero di corsie. Non esiste un limite di 170 km/h.', 'Il numero ''170 km/h'' è la parola trappola, perché è un limite inesistente. ''A quattro corsie'' è un dettaglio irrilevante per il limite.', 'Autostrada = max 130 km/h, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22466, 'È FALSO. Il limite di 130 km/h in autostrada è fisso e non può essere superato, né di giorno né di notte. L''uso dei proiettori abbaglianti non ti autorizza a superare il limite, anzi, di notte la prudenza deve essere maggiore.', 'Le espressioni ''nelle ore notturne'' e ''purché si usino i proiettori a luce abbagliante'' sono trappole che suggeriscono una deroga, che non esiste.', 'Limite autostrada = 130 km/h, giorno e notte. Gli abbaglianti non cambiano il limite.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22467, 'È FALSO. In autostrada, il limite massimo di velocità è di 130 km/h per le autovetture, anche nella corsia di sorpasso. 110 km/h è il limite per le strade extraurbane principali.', 'La negazione ''non è consentito'' e il valore ''110 km/h'' sono le parole trappola, perché il limite è più alto.', 'Autostrada = 130 km/h, anche in sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22468, 'È FALSO. Il limite massimo di velocità in autostrada è di 130 km/h, sia di giorno che di notte. Non esiste un limite di 150 km/h in Italia.', 'Il valore ''150 km/h'' è la velocità trappola. La distinzione tra ''ore diurne'' e ''notturne'' per limiti diversi è falsa.', 'Autostrada = 130 km/h, sempre (giorno e notte).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22469, 'È FALSO. Il limite massimo di velocità sulle strade extraurbane principali è di 110 km/h. Il limite di 130 km/h è solo per le autostrade. Le ''particolari caratteristiche'' non modificano il limite legale.', 'La frase ''particolari caratteristiche costruttive e di sicurezza'' è una trappola per farti pensare a un limite più alto. ''130 km/h'' è il limite dell''autostrada, non dell''extraurbana principale.', 'Extraurbana principale = max 110 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22470, 'È FALSO. Il limite di 110 km/h sulle strade extraurbane principali è un limite massimo e non può essere superato, nemmeno in discesa. Anzi, in discesa è spesso necessario rallentare per mantenere il controllo del veicolo.', 'La frase ''ma solo nei tratti di strada in discesa'' è una condizione trappola che suggerisce una deroga, che non esiste.', 'Limite extraurbana principale = 110 km/h, sempre. La discesa non è una scusa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22471, 'È FALSO. Per le autovetture che trainano un rimorchio, il limite di velocità sulle strade extraurbane secondarie è di 70 km/h, non 90 km/h. Il limite di 90 km/h è per le autovetture senza rimorchio su queste strade.', 'Il valore ''90 km/h'' è la velocità trappola. ''Per il trasporto di gommoni o alianti'' è un dettaglio irrilevante.', 'Extraurbana secondaria + Rimorchio = 70 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22472, 'È FALSO. Le macchine agricole e le macchine operatrici hanno limiti di velocità molto più bassi. Sulle strade extraurbane secondarie, il limite è di 40 km/h per entrambe (con alcune eccezioni per le operatrici). 70 km/h è un limite troppo alto per questi veicoli. Il dispositivo a luce gialla lampeggiante serve solo a segnalare la loro presenza, non ad aumentare la velocità massima consentita.', 'Il valore ''70 km/h'' è la velocità trappola, troppo alta. La condizione ''se hanno in funzione il dispositivo a luce gialla lampeggiante'' è un dettaglio trappola che non modifica il limite di velocità.', 'Macchine agricole/operatrici = molto lente (max 40 km/h su extraurbane secondarie). La luce gialla non aumenta il limite.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22473, 'Anche se hai la precedenza, devi sempre guidare con prudenza. Se vai troppo veloce e c''è un incidente, potresti avere una parte di colpa (concorso di colpa), perché non hai fatto tutto il possibile per evitarlo. Quindi, è possibile che tu abbia una parte di responsabilità.', 'La frase ''non può escludersi'' significa ''è possibile che ci sia''. ''Concorso di colpa'' significa che la colpa è divisa tra più persone, non è solo di uno.', 'Precedenza non è mai via libera totale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22474, 'Ogni paese in Europa ha le sue regole. I limiti di velocità in autostrada o sulle strade fuori città possono essere diversi da un paese all''altro. Per esempio, in Germania ci sono tratti senza limiti, mentre in Italia il limite è 130 km/h.', 'La frase ''non sono identici'' significa ''sono diversi''. È importante capire che le regole non sono uguali ''in tutti gli stati d''Europa''.', 'Limiti velocità: ogni paese, sua regola.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22475, 'Anche se hai la precedenza, non puoi andare troppo veloce. Se causi un incidente andando a forte velocità, hai comunque una responsabilità, non sei ''completamente privo di responsabilità''. Devi sempre guidare con attenzione e prudenza.', 'La parola trappola è ''completamente privi di responsabilità''. Significa ''senza nessuna colpa''. Questo è quasi sempre falso in situazioni di incidente se non si è stati prudenti.', 'Precedenza + velocità = possibile colpa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22476, 'Non è vero che la responsabilità sarà ''solo'' dell''altro. Anche se hai la precedenza, se vai troppo veloce e non fai attenzione, puoi avere una parte di colpa nell''incidente. La responsabilità può essere divisa tra i conducenti.', 'La parola ''solo'' è la trappola. Raramente la colpa è ''solo'' di uno se anche l''altro ha avuto un comportamento non prudente.', '''Solo'' colpa altrui? Quasi mai se sei imprudente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22477, 'Anche se hai la precedenza, devi sempre rallentare e fare attenzione quando ti avvicini a un incrocio. Questo ti permette di vedere se qualcuno non rispetta la precedenza e di frenare in tempo per evitare un incidente. La prudenza è sempre obbligatoria.', 'La frase ''non si ha alcun obbligo'' è la trappola. Significa ''non devi fare niente''. Invece, devi sempre essere prudente e rallentare.', 'Incrocio = rallenta, anche con precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22478, 'Non è vero che la responsabilità è di chi entra per primo nell''incrocio, specialmente se tu hai la precedenza ma vai troppo veloce. La responsabilità dipende da chi non ha rispettato le regole e da chi non ha guidato con prudenza. Se hai la precedenza ma vai ad alta velocità, puoi avere una parte di colpa.', 'La frase ''responsabilità sarà del conducente del veicolo che ha impegnato per primo l''incrocio'' è la trappola. Non è chi entra per primo, ma chi non rispetta le regole e la prudenza.', 'Precedenza e prudenza contano più di ''chi entra prima''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22479, 'Se il veicolo si ferma sui binari di un passaggio a livello, la prima cosa da fare è cercare di spostarlo subito, spingendolo fuori dai binari. Questo è fondamentale per evitare un incidente con il treno.', 'La frase "quanto prima" significa "il più presto possibile" e sottolinea l''urgenza di agire rapidamente.', 'Binari = pericolo immediato, sposta subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22480, 'Se non riesci a spostare il veicolo dai binari, la priorità è mettere in salvo le persone a bordo, facendole scendere subito. Dopo, devi avvisare la stazione ferroviaria per segnalare il pericolo e fermare i treni.', 'Le parole "immediatamente" e "subito" indicano l''urgenza di queste azioni. "Avvisare la stazione ferroviaria" è l''azione corretta per segnalare il pericolo.', 'Non si sposta? Salva persone, poi avvisa stazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22481, 'È molto importante che i macchinisti dei treni siano informati del pericolo in anticipo. Questo permette loro di frenare o fermarsi in tempo, evitando una collisione. Avvisare la stazione ferroviaria serve proprio a questo.', 'La frase "in tempo utile" significa "abbastanza presto" per permettere al macchinista di agire e prevenire l''incidente.', 'Avvisa i treni per tempo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22482, 'Il servosterzo è un sistema che rende il volante leggero e facile da girare. Funziona grazie al motore. Se il motore è spento, il servosterzo non funziona e girare il volante diventa molto più difficile e pesante.', 'La parola "difficoltoso" significa "difficile". "Servosterzo" è il sistema che rende leggero il volante.', 'Motore spento = servosterzo spento = sterzo duro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22483, 'Il servofreno (o freno assistito) usa la depressione creata dal motore per rendere la frenata più facile. Se il motore è spento, il servofreno non funziona bene e devi premere il pedale del freno con molta più forza per frenare.', 'Anche qui, "difficoltoso" significa "difficile". "Servofreno" è il sistema che aiuta a frenare con meno sforzo.', 'Motore spento = servofreno spento = freni duri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22484, 'Se sterzare e frenare sono più difficili a causa del motore spento e del cambio in folle, è molto più facile perdere il controllo del veicolo e causare un incidente. Per questo, il rischio aumenta.', 'La frase "aumenta il rischio" indica che la situazione diventa più pericolosa.', 'Folle + motore spento in discesa = pericolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22485, 'Senza il servosterzo (perché il motore è spento), il volante è molto pesante. Questo rende quasi impossibile fare manovre veloci, come girare rapidamente lo sterzo per evitare un ostacolo improvviso sulla strada.', 'Le espressioni "girare rapidamente" e "schivare un ostacolo" si riferiscono alla necessità di una reazione veloce per evitare un pericolo.', 'Senza servosterzo, non schivi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22486, 'Se il servofreno non funziona bene (perché il motore è spento), devi premere il pedale con più forza e il veicolo impiega più strada per fermarsi. Questa distanza maggiore si chiama "spazio di frenatura" e diventa pericolosamente lunga.', 'La frase "aumenta pericolosamente" sottolinea la gravità della situazione. Lo "spazio di frenatura" è la distanza percorsa dal momento in cui si frena fino all''arresto.', 'Motore spento = frenata lunga e pericolosa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22487, 'Quando il motore è spento, la riserva di depressione del servofreno si esaurisce man mano che si frena. Questo significa che ogni frenata successiva diventa ancora più difficile della precedente, rendendo sempre più complicato fermare il veicolo.', 'La frase "sempre più difficoltoso" indica un peggioramento progressivo della capacità di frenare.', 'Senza motore, il freno peggiora.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22488, 'Se il motore è spento, non produce corrente elettrica. Quindi, non ci può essere nessun "sovraccarico di corrente elettrica". Anzi, la batteria potrebbe scaricarsi se si usano accessori elettrici.', 'La parola "sovraccarico" è la trappola. Non c''è sovraccarico, semmai il contrario o nessun effetto diretto sulla corrente.', 'Motore spento = niente sovraccarico elettrico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22489, 'Il differenziale è un componente meccanico che permette alle ruote di girare a velocità diverse, ad esempio in curva. Andare in folle o a motore spento non causa nessun problema o "anomalia" al differenziale.', 'La frase "anomalia al differenziale" è una distrazione tecnica che non ha relazione con la situazione descritta.', 'Folle e motore spento non rompono il differenziale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22490, 'Percorrere una discesa con il cambio in folle e il motore spento è una pratica estremamente pericolosa, non "conveniente per la sicurezza". Il piccolo risparmio di carburante non giustifica l''enorme rischio di incidenti.', 'Le parole "maggiore sicurezza" e "risparmiando così anche carburante" sono le trappole. La sicurezza è compromessa, non aumentata.', 'Sicurezza prima del risparmio! Mai folle in discesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22491, 'Estrarre la chiave di accensione mentre il veicolo è in movimento blocca il volante (bloccasterzo). Questo rende impossibile guidare il veicolo e causerebbe un incidente gravissimo. È una pratica estremamente pericolosa e illegale.', 'La frase "conviene estrarre la chiave" è la trappola, suggerendo un''azione che è invece estremamente pericolosa.', 'Chiave fuori = volante bloccato = incidente sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22492, 'Il servofreno a depressione funziona grazie al motore. Se il motore è spento, la depressione si esaurisce e la forza frenante diminuisce drasticamente. Non si ottiene affatto la stessa forza frenante che si ha con il motore acceso, ma molta meno.', 'La frase "stessa forza frenante" è la trappola. La forza frenante è molto minore e la frenata diventa molto più difficile.', 'Motore spento = meno forza frenante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22493, 'Se ti trovi sui binari e le barriere del passaggio a livello iniziano a chiudersi, la cosa più importante è mantenere la calma e fare tutto il possibile per spostare il tuo veicolo dai binari. Questo serve a evitare un incidente con il treno.', 'La frase "in qualunque modo" significa che devi usare ogni mezzo a tua disposizione per liberare i binari, perché la sicurezza è la priorità assoluta.', 'Sui binari, via subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22494, 'Se sei sui binari e le barriere si chiudono, la tua vita e quella delle persone sul treno sono più importanti delle barriere. Se non c''è altro modo per uscire dai binari, devi sfondare le barriere per metterti in salvo.', 'La parte cruciale è "se necessario anche sfondando le barriere". Questo indica che la sicurezza delle persone ha la precedenza sul danno materiale alle barriere.', 'Vita > Barriera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22495, 'Se il tuo veicolo si rompe e rimane bloccato sui binari di un passaggio a livello, devi agire subito per toglierlo. Chiedere aiuto ad altri automobilisti per farti trainare è un buon modo per farlo velocemente.', '"adoperarsi per rimuovere il veicolo al più presto" sottolinea l''urgenza. "ad esempio facendosi trainare" è un esempio pratico di come agire.', 'Guasto sui binari? Sposta subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22496, 'Se la tua auto si ferma sui binari per un guasto, devi fare di tutto per spostarla il più velocemente possibile. Chiedere aiuto ad altre persone per spingere il veicolo fuori dai binari è un''azione corretta e necessaria.', 'Anche qui, "adoperarsi per rimuovere il veicolo al più presto" indica l''urgenza. "facendosi aiutare da altri utenti a spingere" è un''azione concreta per risolvere la situazione.', 'Guasto sui binari? Spingi via!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22497, 'Quando ti avvicini a un passaggio a livello, devi essere molto attento e andare piano. Questo ti aiuta a evitare incidenti che potrebbero rovinare le barriere, i semafori o altre attrezzature del passaggio a livello.', '"massima prudenza e moderare la velocità" sono le regole d''oro per affrontare i passaggi a livello. "danneggiamento delle attrezzature" è una conseguenza da evitare.', 'Passaggio a livello: piano e attento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22498, 'Ai passaggi a livello è fondamentale guidare con molta attenzione e a bassa velocità. In questo modo, eviti di sbattere contro le barriere, il che è molto pericoloso e può causare gravi danni.', 'Ancora una volta, "massima prudenza e moderare la velocità" sono i comportamenti corretti. "collisione con le barriere" è il pericolo specifico da prevenire.', 'Passaggio a livello: piano e attento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22499, 'Non rispettare le regole al passaggio a livello è estremamente pericoloso. Un incidente con un treno può causare feriti o morti a molte persone che viaggiano sul treno, non solo a te.', '"può mettere in pericolo l''incolumità di molte persone" evidenzia che le conseguenze di un errore non riguardano solo il conducente, ma un numero elevato di individui.', 'Regole al passaggio a livello = sicurezza di tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22500, 'Cercare di attraversare un passaggio a livello in modo rischioso per guadagnare qualche secondo è molto pericoloso. Non metti a rischio solo te stesso, ma anche le persone sul treno e chiunque si trovi nelle vicinanze.', '"manovra azzardata per guadagnare tempo" descrive il comportamento sbagliato. "pericolo per molti individui, oltre che per il conducente" rafforza il concetto di responsabilità estesa.', 'Non rischiare per un minuto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22501, 'Se il tuo veicolo rimane bloccato tra le barriere chiuse di un passaggio a livello, dopo aver tentato di spostarlo, la cosa più importante è avvisare subito i treni che potrebbero arrivare. Questo può salvare molte vite.', '"adoperarsi in ogni modo per presegnalare il pericolo" indica l''urgenza e la necessità di avvisare i treni in transito per prevenire una tragedia.', 'Bloccato? Avvisa il treno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22502, 'Se sei sui binari e le barriere si chiudono, la prima cosa da fare è cercare di spostare il veicolo, anche sfondando le barriere. Abbandonare il veicolo sui binari è molto pericoloso perché il treno lo colpirebbe, causando un disastro. Devi prima provare a salvarlo.', 'La parola trappola è "abbandonare rapidamente il veicolo". Non devi abbandonare il veicolo sui binari, ma fare il possibile per rimuoverlo.', 'Non abbandonare il veicolo sui binari!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22503, 'Anche se stai trainando un rimorchio e ti trovi sui binari con le barriere che si chiudono, l''obiettivo è sgomberare completamente i binari. Abbandonare il rimorchio sui binari è pericoloso quanto abbandonare l''auto, perché il treno lo colpirebbe comunque. Devi cercare di spostare tutto il convoglio.', 'L''espressione "sganciarlo rapidamente e abbandonarlo sui binari" è la parte sbagliata. Non si deve mai lasciare nulla sui binari.', 'Non lasciare nulla sui binari!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22504, 'Se il tuo veicolo si guasta e rimane bloccato sui binari, la priorità assoluta è togliere il veicolo (e il suo carico) dai binari il più velocemente possibile. Scaricare il carico richiederebbe troppo tempo e lascerebbe comunque il veicolo in una posizione pericolosa.', 'La frase "scaricare rapidamente il veicolo per salvare almeno il carico" è sbagliata. La priorità non è il carico, ma la sicurezza e lo sgombero immediato dei binari.', 'Salva la vita, non il carico!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22505, 'Se la tua auto si blocca sui binari, svuotare il serbatoio è un''operazione che richiede tempo prezioso e non è la priorità. Inoltre, il carburante sparso potrebbe aumentare il rischio di incendio, non diminuirlo. La cosa più importante è spostare il veicolo.', 'L''azione di "svuotare rapidamente il serbatoio" è inutile e potenzialmente pericolosa in una situazione di emergenza come questa.', 'Sposta il veicolo, non svuotare il serbatoio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22506, 'I passaggi a livello devono essere affrontati con prudenza e a velocità moderata. Andare molto veloce è pericoloso perché potresti non riuscire a fermarti in tempo se le barriere si abbassano o se c''è un ostacolo.', 'La frase "velocità molto elevata" è l''esatto contrario del comportamento richiesto. Bisogna sempre moderare la velocità.', 'Passaggio a livello: piano, non veloce!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22507, 'Non devi mai affrontare un passaggio a livello a velocità elevata. Se le barriere sono abbassate, devi fermarti. Sfondarle è una soluzione estrema solo se sei già sui binari e non hai altra scelta per la tua sicurezza, non un motivo per andare veloce.', 'L''idea di andare a "velocità molto elevata per essere in grado di sfondare le barriere" è una logica completamente sbagliata e pericolosa. Le barriere si sfondano solo per emergenza, non per scelta.', 'Non correre per sfondare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22508, 'Non rispettare le regole al passaggio a livello è estremamente pericoloso e può causare incidenti gravissimi, mettendo a rischio la vita di molte persone sul treno e non solo. Le conseguenze non sono solo una "lieve sanzione".', 'Le parole trappola sono "esclusivamente una lieve sanzione amministrativa" e "non comporta reali pericoli per gli altri utenti". Queste frasi minimizzano un pericolo molto grave.', 'Passaggio a livello: pericolo reale, non solo multa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22509, 'Una manovra azzardata al passaggio a livello è pericolosa in qualsiasi momento, sia di giorno che di notte. Il rischio di un treno in arrivo o di un incidente non dipende dall''ora del giorno.', 'La limitazione "solo nelle ore notturne" è falsa. Il pericolo è costante, indipendentemente dall''illuminazione o dall''ora.', 'Pericolo sempre, non solo di notte!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22510, 'Spegnere il motore e far scendere i passeggeri sono azioni importanti per la sicurezza, ma non sono l''UNICO obbligo. L''obbligo principale è cercare di spostare il veicolo e, se non possibile, presegnalare il pericolo al treno.', 'La parola trappola è "unico obbligo". Ci sono altri obblighi più importanti e urgenti da considerare in questa situazione.', 'Non solo scendere, ma agire!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22511, 'Allontanarsi dal veicolo è importante per la propria sicurezza, ma solo dopo aver fatto tutto il possibile per spostare il veicolo o per avvisare il treno. Abbandonare subito il veicolo senza fare nulla è sbagliato e irresponsabile.', 'L''azione di "allontanarsi di almeno cento metri il prima possibile" è corretta per la propria incolumità, ma non come prima e unica azione, senza aver tentato di risolvere la situazione o avvisare.', 'Prima agisci, poi allontanati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22512, 'In un passaggio a livello, la priorità assoluta è sempre sgomberare i binari, anche se ci sono feriti. I feriti vanno soccorsi, ma i veicoli devono essere spostati immediatamente per evitare un disastro con il treno, che causerebbe ancora più danni e feriti.', 'La frase "non si devono spostare i veicoli dai binari qualora vi siano stati feriti" è la trappola. La regola generale di non spostare i veicoli in caso di feriti non vale sui binari, dove il pericolo del treno è imminente e prioritario.', 'Sui binari, sposta sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22513, 'Se vedi un pallone rotolare in strada, devi subito diminuire la velocità. Questo ti dà più tempo per reagire e fermarti in sicurezza, perché un bambino potrebbe correre dietro al pallone.', 'La parola ''subito'' non significa frenare di colpo, ma agire prontamente e senza esitazione per la sicurezza.', 'Pallone = bambino = rallenta subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22514, 'È fondamentale rallentare per essere pronti a fermarsi. Se un bambino dovesse correre in strada per prendere il pallone, tu devi essere in grado di bloccare il veicolo in tempo.', 'La frase ''se necessario'' sottolinea che devi essere preparato a fermarti completamente, non solo a rallentare un po''.', 'Rallenta per fermarti, sempre pronto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22515, 'Quando vedi un pallone, devi pensare che ci sia un bambino nelle vicinanze. I bambini spesso non guardano la strada e potrebbero attraversare all''improvviso. La prudenza è d''obbligo.', 'La parola ''prevedere'' significa immaginare in anticipo cosa potrebbe succedere, è un comportamento di guida preventiva.', 'Pallone = bambino in arrivo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22516, 'Rallentare in modo graduale è importante per la tua sicurezza e quella di chi ti segue. Se freni di colpo, il veicolo dietro di te potrebbe non avere il tempo di frenare e tamponarti.', 'La parola ''progressivamente'' è la chiave: significa rallentare piano piano, non di colpo, per dare il tempo anche agli altri di reagire.', 'Rallenta piano, evita il tamponamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22517, 'Sterzare bruscamente è molto pericoloso. Potresti perdere il controllo del veicolo, finire fuori strada o invadere la corsia opposta, causando un incidente grave. La priorità è rallentare e fermarsi, non fare manovre improvvise.', 'La parola ''bruscamente'' indica un''azione improvvisa e pericolosa. Le manovre improvvise sono quasi sempre sbagliate.', 'Mai sterzare di colpo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22518, 'Invadere la corsia opposta è estremamente pericoloso, specialmente in un centro abitato. Potrebbe arrivare un altro veicolo e causare un incidente frontale. La sicurezza delle persone è più importante di un pallone.', 'La frase ''anche invadendo la corsia opposta'' rende la risposta falsa. Non si deve mai invadere la corsia opposta se non in condizioni di massima sicurezza e visibilità.', 'Non invadere mai l''altra corsia per un pallone.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22519, 'Questa affermazione è falsa e molto pericolosa. La sicurezza di un bambino è la priorità assoluta. Devi sempre rallentare. Il rischio di un tamponamento si gestisce rallentando progressivamente, non ignorando il pericolo.', 'La negazione ''non occorre rallentare'' è la trappola. È sempre necessario rallentare in queste situazioni.', 'Rallenta sempre, la sicurezza prima di tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22520, 'Le luci di emergenza (le ''quattro frecce'') si usano quando il veicolo è fermo o procede molto lentamente in situazioni di pericolo. Quando vedi un pallone, la prima cosa da fare è rallentare e osservare, non accendere subito le luci di emergenza.', 'La parola ''immediatamente'' è la trappola. L''azione principale non è accendere le luci, ma rallentare e prestare attenzione.', 'Luci di pericolo per veicolo fermo, non per un pallone.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22521, 'È VERO. Se ci sono persone dentro un''auto parcheggiata, c''è il rischio che aprano una portiera all''improvviso senza guardare, causando un incidente. Per questo è importante mantenere una distanza di sicurezza.', 'La frase ''possibile apertura imprudente'' indica un rischio che può accadere, non che accade sempre, ma è sufficiente per rendere la situazione pericolosa.', 'Persone in auto = porta che si apre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22522, 'È VERO. Le auto parcheggiate possono coprire la visuale. Potresti non vedere chi sta per attraversare, specialmente persone più difficili da notare come chi è in carrozzella o chi spinge un passeggino. Mantenere la distanza ti dà più tempo per vedere e reagire.', 'Le parole ''impedire la vista'' e i riferimenti a ''disabile in carrozzella'' o ''pedone che spinge un passeggino'' sottolineano i pericoli specifici e le categorie più vulnerabili.', 'Auto parcheggiate = ostacolo alla vista.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22523, 'È FALSO. Anche se vai piano, se qualcuno apre una portiera all''improvviso, l''incidente può comunque succedere. La velocità bassa riduce la gravità, ma non elimina il pericolo di scontrarsi con la portiera.', 'La parola ''non'' e la condizione ''se avviene a bassa velocità'' sono le trappole. Il pericolo esiste sempre, a qualsiasi velocità.', 'Pericolo porta = sempre, anche piano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22524, 'È FALSO. Il pericolo non c''è ''solo'' se la portiera è già aperta. Il vero rischio è proprio che la portiera venga aperta all''improvviso mentre stai passando. Quindi, il pericolo esiste anche se la portiera è chiusa.', 'La parola ''solo'' è una parola trappola molto comune. Spesso, quando vedi ''solo'', la risposta è FALSO perché il pericolo o la situazione non si limita a quella singola condizione.', '''Solo'' = quasi sempre FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22525, 'È FALSO. Il pericolo maggiore è quando le persone sono ''ancora a bordo'' e possono aprire una portiera. Se sono già scese, il rischio di un''apertura improvvisa della portiera è molto più basso (a meno che non ci siano altre persone dentro). Anche qui, la parola ''solo'' rende la frase falsa.', 'Anche in questo caso, la parola ''solo'' è la trappola. Il pericolo è proprio quando le persone sono DENTRO l''auto.', '''Solo'' = quasi sempre FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22526, 'È FALSO. Come abbiamo visto, il pericolo di una portiera che si apre esiste a qualsiasi velocità, non ''solo'' ad alta velocità. Anche a bassa velocità, un''apertura improvvisa può causare un incidente.', 'Ancora una volta, la parola ''solo'' è la trappola. Il pericolo non dipende solo dalla velocità, ma dalla possibilità che una portiera si apra.', '''Solo'' = quasi sempre FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22527, 'Se mantieni la giusta distanza dal veicolo che ti precede, hai il tempo necessario per frenare in sicurezza e non urtarlo in caso di frenata improvvisa. Questo è lo scopo principale della distanza di sicurezza.', 'La frase ''evita la collisione'' è il punto chiave. È proprio per questo che si mantiene la distanza di sicurezza.', 'Distanza = spazio per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22528, 'Più vai veloce, più spazio ti serve per fermarti. Per questo, la distanza di sicurezza deve aumentare con l''aumentare della tua velocità.', 'La parola ''anche'' indica che la velocità è uno dei tanti fattori importanti, ma non l''unico.', 'Più veloce vai, più spazio tieni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22529, 'Se sei stanco, distratto o hai riflessi meno pronti, ti serve più tempo per reagire a un pericolo. Per compensare, devi aumentare la distanza di sicurezza.', 'La ''propria prontezza di riflessi'' è un fattore personale del conducente che influisce sul tempo di reazione.', 'Riflessi lenti? Distanza aumenta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22530, 'In condizioni di traffico intenso, le frenate improvvise sono più frequenti. Mantenere una distanza adeguata ti permette di reagire senza causare un tamponamento.', 'Le ''condizioni del traffico'' sono un fattore esterno che richiede maggiore attenzione e spazio.', 'Traffico fitto? Distanza attenta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22531, 'Se la strada è in discesa, il veicolo frena più lentamente. Se ci sono curve, la visibilità è ridotta. In questi casi, è necessario aumentare la distanza di sicurezza.', 'L''''andamento planoaltimetrico'' si riferisce a salite, discese e curve della strada, che influenzano la frenata e la visibilità.', 'Discesa o curva? Più distanza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22532, 'Con pioggia, neve, ghiaccio o nebbia, la strada è più scivolosa e la visibilità è ridotta. Questo aumenta lo spazio di frenata e rende più difficile vedere i pericoli, quindi serve molta più distanza.', 'Le ''condizioni atmosferiche'' sono un fattore cruciale che può raddoppiare o triplicare lo spazio di frenata.', 'Maltempo? Distanza raddoppia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22533, 'Un veicolo pesante, come un camion, ha bisogno di molto più spazio per frenare rispetto a un''auto piccola. Per questo, il tipo di veicolo che guidi influenza la distanza di sicurezza.', 'Il ''tipo di veicolo'' si riferisce alle sue caratteristiche (peso, dimensioni) che influenzano la frenata.', 'Veicolo grande? Distanza maggiore!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22534, 'Se la tua auto ha freni usurati, pneumatici consumati o altri problemi, frena meno bene. Per compensare questa minore efficienza, devi aumentare la distanza di sicurezza.', 'Lo ''stato di efficienza del veicolo'' include freni, pneumatici, ammortizzatori, ecc. che influenzano la sicurezza.', 'Auto non perfetta? Distanza extra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22535, 'Un veicolo molto carico è più pesante e, per le leggi della fisica, ha bisogno di più spazio per fermarsi completamente. Quindi, se trasporti un carico pesante, aumenta la distanza.', 'L''''entità del carico'' si riferisce al peso trasportato, che aumenta l''inerzia del veicolo.', 'Carico pesante? Frenata lunga!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22536, 'Le macchine sgombraneve sono veicoli speciali che lavorano sulla strada. Per la tua sicurezza e per non intralciare il loro lavoro, è obbligatorio mantenere una distanza di almeno 20 metri.', 'Il valore ''20 metri'' è una distanza minima specifica da ricordare per questi veicoli.', 'Sgombraneve = 20 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22537, 'Anche le macchine spanditrici di sale sono veicoli speciali in azione. Come per le sgombraneve, è necessario mantenere una distanza di sicurezza di almeno 20 metri per evitare pericoli.', 'Il valore ''20 metri'' è lo stesso per le spanditrici di sale, è un dato da memorizzare.', 'Spandisale = 20 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22538, 'Non devi considerare solo la tua velocità, ma anche quella del veicolo che ti precede. Se va molto lento o molto veloce, devi adattare la tua distanza per evitare di avvicinarti troppo o di essere troppo lontano.', 'La ''velocità del veicolo che lo precede'' è un fattore dinamico che richiede un adattamento costante della distanza.', 'Occhio a chi ti precede!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22539, 'Freni efficienti ti permettono di fermarti in uno spazio minore. Se i tuoi freni non sono in perfette condizioni, devi aumentare la distanza di sicurezza per compensare.', 'L''''efficienza dei freni'' è un aspetto fondamentale dello stato di efficienza del veicolo.', 'Freni ok? Distanza giusta. Freni no? Distanza extra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22540, 'Pneumatici usurati, sgonfi o non adatti alle condizioni della strada riducono l''aderenza e allungano lo spazio di frenata. Per questo, è essenziale aumentare la distanza di sicurezza.', 'La ''condizione dei pneumatici'' è cruciale per l''aderenza e la capacità di frenata del veicolo.', 'Gomme lisce? Distanza doppia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22541, 'I veicoli pesanti (oltre 3,5 tonnellate) hanno spazi di frenata molto lunghi. Su strade extraurbane a corsia unica e con divieto di sorpasso, devono mantenere una distanza di almeno 100 metri per garantire la sicurezza.', 'Ricorda i tre elementi chiave: ''trasporto di merci di massa complessiva superiore a 3,5 tonnellate'', ''divieto di sorpasso'' e ''almeno 100 metri''.', 'Camion pesanti + divieto sorpasso = 100 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22542, 'Il tipo di carburante che usa il motore (benzina, diesel, GPL, elettrico) non ha alcuna influenza sullo spazio di frenata o sulla tua capacità di reazione. Non è un fattore per la distanza di sicurezza.', 'La ''tipo di alimentazione del motore'' è la parola trappola. Non c''entra con la sicurezza stradale.', 'Benzina o diesel? Non cambia la distanza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22543, 'La cilindrata del motore (la sua dimensione interna) non è un fattore che influenza direttamente lo spazio di frenata o la tua reazione. Conta la velocità, il peso, l''efficienza dei freni, non la cilindrata.', 'La ''cilindrata del veicolo'' è un dato tecnico del motore, non un fattore di sicurezza per la distanza.', 'Cilindrata? Non è un fattore di sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22544, 'La potenza del motore ti permette di accelerare più velocemente, ma non ti fa frenare meglio o in meno spazio. Quindi, non è un fattore per calcolare la distanza di sicurezza.', 'La ''potenza del motore'' è un''altra caratteristica del motore che non influisce sulla distanza di sicurezza.', 'Potenza non frena, la distanza sì.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22545, 'La larghezza della strada (carreggiata) non ha alcuna relazione con la distanza di sicurezza, che è lo spazio che devi mantenere tra il tuo veicolo e quello che ti precede.', 'L''''ampiezza della carreggiata'' è un fattore irrilevante per la distanza di sicurezza tra veicoli.', 'Larghezza strada? Non conta per la distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22546, 'La larghezza del tuo veicolo non influenza lo spazio di frenata o il tempo di reazione. La distanza di sicurezza si misura in lunghezza, non in larghezza.', 'La ''larghezza del veicolo'' è un fattore irrilevante, come l''ampiezza della carreggiata.', 'Larghezza auto? Non serve per la distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22547, 'Tu sei responsabile della distanza di sicurezza dal veicolo che ti precede. Non hai l''obbligo di controllare o di essere responsabile per il veicolo che ti segue. Ognuno è responsabile della propria condotta.', 'Le parole ''veicolo che lo segue'' e ''obbligo di controllare'' sono la trappola. La tua responsabilità è sempre verso il veicolo davanti a te.', 'Tu guardi avanti, non dietro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22548, 'La distanza di sicurezza da mantenere da una macchina sgombraneve in azione è di 20 metri, non 10. È importante ricordare il valore corretto.', 'Il valore ''10 metri'' è sbagliato. La distanza corretta è 20 metri.', 'Sgombraneve = 20 metri, non 10.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22549, 'La distanza di sicurezza da mantenere da una macchina spanditrice di sale in azione è di 20 metri, non 15. Anche qui, il valore numerico è errato.', 'Il valore ''15 metri'' è sbagliato. La distanza corretta è 20 metri.', 'Spandisale = 20 metri, non 15.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22550, '10 metri sono una distanza assolutamente insufficiente per autotreni, specialmente se c''è un divieto di sorpasso. I veicoli pesanti richiedono distanze molto maggiori (ad esempio, 100 metri per i camion oltre 3,5t in certe condizioni).', 'Il valore ''almeno 10 metri'' è la trappola. È un valore troppo basso per la sicurezza di questi veicoli.', 'Autotreni = molta più distanza di 10 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22551, 'La distanza di sicurezza non è mai un valore fisso, ma cambia in base a tantissimi fattori come la velocità, le condizioni meteo, il tipo di veicolo, la prontezza dei riflessi, ecc. La parola ''sempre'' rende la frase falsa.', 'La parola ''sempre'' è una classica parola trappola nei quiz. La distanza di sicurezza è variabile.', 'Distanza non è mai ''sempre'' fissa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22552, 'La distanza di sicurezza deve essere maggiore della distanza di frenatura, perché deve includere anche lo spazio percorso durante il tuo tempo di reazione (il tempo che impieghi a decidere di frenare e a iniziare la frenata).', 'La frase ''almeno pari a quello della distanza di frenatura'' è insufficiente. Deve essere *maggiore* per essere sicura.', 'Distanza sicurezza = reazione + frenata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22553, 'La distanza di sicurezza è lo spazio che ti serve per fermarti senza urtare il veicolo davanti. La distanza di visibilità è quanto riesci a vedere avanti. Sono due concetti diversi e non devono essere confusi.', 'La ''distanza di visibilità'' è la parola trappola, perché non è direttamente collegata alla distanza di sicurezza in questo modo.', 'Visibilità non è sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22554, 'La distanza di sicurezza deve essere sempre rispettata, a qualsiasi velocità, anche a basse velocità. Anche a 30 km/h, se non mantieni la distanza, puoi causare un tamponamento.', 'Le parole ''non deve essere rispettata'' e ''inferiori ai 50 km/h'' sono la trappola. La distanza è sempre obbligatoria.', 'Distanza sempre, a ogni velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22555, 'La marcia che hai inserito (prima, seconda, ecc.) non influenza direttamente lo spazio di frenata o la tua reazione. Quello che conta è la velocità a cui stai andando, non la marcia.', 'La ''marcia innestata'' è un fattore irrilevante per la distanza di sicurezza.', 'Marcia non conta, velocità sì.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22556, 'VERO. Se sei stanco, distratto o non ti senti bene, il tuo tempo di reazione è più lento. Per questo, hai bisogno di più spazio per frenare in sicurezza. Le tue condizioni fisiche e mentali sono importanti per calcolare la distanza.', 'La parola ''anche'' significa che è uno dei tanti fattori. ''Condizioni psicofisiche'' si riferisce a come stai fisicamente e mentalmente.', 'Stanco = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22557, 'VERO. Lo scopo principale della distanza di sicurezza è proprio quello di evitare di urtare il veicolo che ti precede, se questo frena all''improvviso o rallenta.', '''Tamponare'' significa colpire la parte posteriore di un altro veicolo. È l''incidente che la distanza di sicurezza vuole evitare.', 'Distanza = no tamponamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22558, 'FALSO. La larghezza del veicolo davanti a te non cambia lo spazio che ti serve per frenare. Quello che conta è la sua velocità, la tua velocità, le condizioni della strada e il tuo tempo di reazione.', 'La parola ''larghezza'' è la trappola. Non ha importanza per la distanza di sicurezza.', 'Larghezza non conta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22559, 'FALSO. Il numero di corsie su una strada non influenza direttamente lo spazio che ti serve per fermarti in sicurezza dal veicolo che ti precede. La distanza di sicurezza riguarda la frenata, non il cambio di corsia.', '''Numero di corsie'' è un elemento di distrazione. Non è un fattore per la distanza di sicurezza.', 'Corsie non cambiano distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22560, 'FALSO. Il servosterzo ti aiuta a girare il volante più facilmente, ma non ha nessun effetto sulla distanza di frenata o sul tuo tempo di reazione. È una comodità, non un fattore di sicurezza per fermarsi.', '''Servosterzo'' è una caratteristica del veicolo che non influisce sulla distanza di sicurezza.', 'Servosterzo non frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22561, 'FALSO. La distanza di sicurezza è lo spazio che devi lasciare tra il tuo veicolo e quello che ti sta davanti. Il tipo di veicolo che ti segue (cioè quello dietro di te) non cambia lo spazio che tu devi lasciare davanti a te.', 'La trappola è ''veicolo che segue''. La distanza di sicurezza si calcola sempre rispetto al veicolo che ''precede''.', 'Guarda avanti, non dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22562, 'FALSO. L''adesivo con il limite di velocità sul retro di un veicolo (ad esempio, per i neopatentati o i mezzi pesanti) indica la sua velocità massima consentita, non un fattore per calcolare la tua distanza di sicurezza. Devi considerare la sua velocità reale e la tua.', 'La frase ''limite di velocità riportato sul retro'' è un dettaglio specifico che non determina la tua distanza di sicurezza.', 'Adesivo non è distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22563, 'FALSO. La distanza di sicurezza non è mai fissa. Cambia in base a molti fattori: la tua velocità, la velocità del veicolo davanti, le condizioni della strada (asciutta, bagnata), il meteo (pioggia, nebbia), il tuo tempo di reazione e le condizioni del tuo veicolo (freni, pneumatici).', 'La parola ''fissa'' è la chiave. La distanza di sicurezza è sempre variabile.', 'Distanza = variabile, mai fissa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22564, 'FALSO. Devi sempre rispettare la distanza di sicurezza, a qualsiasi velocità. Anche a basse velocità, hai bisogno di spazio per reagire e fermarti. È una regola fondamentale per tutte le situazioni.', 'La frase ''al di sopra di una certa velocità'' è la trappola. Implica che a basse velocità non serva, ma non è così.', 'Sempre distanza, a ogni velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22565, 'La distanza di sicurezza deve tenere conto di quanto bene gli pneumatici aderiscono alla strada. Se le gomme sono usurate o la strada è bagnata, l''aderenza è minore e il veicolo impiega più tempo a fermarsi. Per questo, la distanza di sicurezza deve essere maggiore.', 'La parola ''anche'' indica che l''aderenza degli pneumatici è uno dei tanti fattori che influenzano la distanza di sicurezza, non l''unico. ''Aderenza'' significa quanto bene la gomma ''si attacca'' alla strada.', 'Gomme lisce o strada bagnata = più distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22566, 'La distanza di sicurezza è composta da due parti: lo spazio che percorri mentre decidi di frenare (tempo di reazione) e lo spazio che percorri mentre il veicolo frena effettivamente. Quindi, lo spazio percorso nel tempo di reazione è una parte fondamentale della distanza di sicurezza.', 'La frase ''dipende dallo spazio percorso nel tempo di reazione'' è corretta perché il tempo di reazione è una componente essenziale del calcolo della distanza di sicurezza totale.', 'Distanza = spazio reazione + spazio frenata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22567, 'Non esiste una regola che imponga una distanza di sicurezza fissa di ''almeno 100 metri'' nelle forti discese. In discesa, la frenata è più difficile e quindi la distanza di sicurezza deve essere maggiore, ma non c''è un valore numerico preciso stabilito dalla legge.', 'La trappola è il valore numerico fisso ''almeno 100 metri''. La distanza di sicurezza è variabile e dipende da molti fattori, non da un numero fisso per una specifica situazione.', 'Nessun numero fisso per la distanza di sicurezza generica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22568, 'Anche in caso di nevicata, non c''è una distanza di sicurezza minima fissa di ''almeno 100 metri''. Con la neve, l''aderenza è molto bassa e la distanza di sicurezza deve essere aumentata notevolmente, ma non c''è un valore preciso imposto dalla legge.', 'Ancora una volta, il valore numerico fisso ''almeno 100 metri'' è la trappola. Le condizioni meteo avverse richiedono una distanza maggiore, ma non un valore predefinito.', 'Neve = distanza molto maggiore, ma senza un numero fisso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22569, 'Il freno di stazionamento (o freno a mano) serve per tenere fermo il veicolo quando è parcheggiato. Non viene usato per frenare durante la marcia e quindi non influenza la distanza di sicurezza necessaria per fermarsi in caso di emergenza.', 'La parola chiave è ''freno di stazionamento''. È importante capire la funzione specifica di questo freno per non confonderlo con il freno di servizio (pedale del freno).', 'Freno a mano = per parcheggio, non per frenare in corsa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22570, 'La corsia d''emergenza non deve essere percorsa, se non in casi eccezionali previsti dalla legge (ad esempio, per un guasto grave o per soccorso). Se si percorre la corsia d''emergenza, si sta commettendo un''infrazione. La distanza di sicurezza si applica alla normale circolazione, non a situazioni di guida scorretta.', 'La frase ''se si percorre la corsia d''emergenza'' è la trappola. Non si dovrebbe percorrere questa corsia, quindi la domanda è fuorviante.', 'Corsia d''emergenza = non si usa per guidare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22571, 'La distanza di sicurezza non è semplicemente lo spazio di frenatura più un valore fisso di 20 metri. La distanza di sicurezza è la somma di due elementi: lo spazio percorso nel tempo di reazione (che varia) e lo spazio di frenatura. Non è un calcolo fisso con un numero predefinito.', 'La trappola è il calcolo fisso ''uguale allo spazio di frenatura aumentato di 20 metri''. Questo ignora la componente fondamentale e variabile del tempo di reazione.', 'Distanza = spazio reazione + spazio frenata. Non è un numero fisso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22572, 'Questa affermazione è VERA. Lo spazio percorso nel tempo di reazione è proprio la distanza che il veicolo percorre dal momento in cui il conducente vede un pericolo (percezione) fino al momento in cui inizia a premere il pedale del freno (inizio della frenata).', 'Non ci sono parole trappola particolari in questa domanda, è una definizione precisa.', 'Vedo-Penso-Agisco = Spazio Reazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22573, 'Questa affermazione è VERA. Il motivo principale per cui manteniamo la distanza di sicurezza è proprio quello di avere abbastanza spazio per frenare ed evitare di colpire il veicolo che ci precede, cioè evitare il tamponamento.', 'Non ci sono parole trappola. La domanda descrive lo scopo fondamentale della distanza di sicurezza.', 'Distanza sicurezza = No Tamponamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22574, 'Questa affermazione è VERA. La distanza di sicurezza deve essere sufficiente a coprire sia lo spazio percorso nel tempo di reazione, sia lo spazio di frenata. Quindi, è logico che possa essere (e di solito è) maggiore del solo spazio percorso nel tempo di reazione.', 'La parola ''può'' indica una possibilità, che in questo caso è corretta. La distanza di sicurezza è la somma di spazio di reazione e spazio di frenata, quindi è sempre almeno uguale o maggiore dello spazio di reazione.', 'Distanza sicurezza > Spazio reazione (sempre).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22575, 'Questa affermazione è FALSA. La distanza di sicurezza serve per evitare di scontrarsi con il veicolo che ci precede (tamponamento). Lo scontro frontale avviene quando due veicoli si scontrano ''faccia a faccia'', spesso perché uno invade la corsia opposta, e non è legato alla distanza di sicurezza dal veicolo davanti.', 'La parola ''frontale'' è la chiave. La distanza di sicurezza non previene questo tipo di incidente.', 'Distanza sicurezza = dietro. Frontale = corsia sbagliata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22576, 'Questa affermazione è FALSA. Come per lo scontro frontale, la distanza di sicurezza non serve a prevenire gli scontri laterali. Gli scontri laterali avvengono di solito quando si cambia corsia senza attenzione o agli incroci, non per la distanza dal veicolo che ci precede.', 'La parola ''laterale'' è la chiave. La distanza di sicurezza non previene questo tipo di incidente.', 'Distanza sicurezza = dietro. Laterale = cambio corsia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22577, 'Questa affermazione è FALSA. La distanza di sicurezza deve essere sempre almeno uguale o maggiore della somma dello spazio percorso nel tempo di reazione e dello spazio di frenata. Non può mai essere inferiore al solo spazio percorso nel tempo di reazione, altrimenti non avremmo il tempo di frenare in sicurezza.', 'La parola ''inferiore'' è la trappola. La distanza di sicurezza deve essere sempre ''maggiore o uguale'' allo spazio di reazione più lo spazio di frenata.', 'Distanza sicurezza MAI < Spazio reazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22578, 'A 30 km/h, la distanza di sicurezza è di circa 9 metri. Questo valore è corretto perché ti permette di avere il tempo di reagire e frenare in caso di pericolo.', 'La parola "circa" significa "più o meno". Indica che il valore non deve essere esatto al millimetro, ma vicino. "Minima" significa che non puoi andare sotto questa distanza.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 30 km/h: (30/10) x 3 = 9 metri. VERO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22579, 'A 50 km/h, la distanza di sicurezza è di circa 15 metri. Il valore di 14 metri è molto vicino e quindi considerato corretto. È fondamentale mantenere questa distanza per la tua sicurezza.', 'Anche qui, "circa" ci dice che il valore è approssimativo e 14 metri è un''ottima stima.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 50 km/h: (50/10) x 3 = 15 metri. 14 è vicino. VERO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22580, 'A 100 km/h, la distanza di sicurezza è di circa 30 metri. Il valore di 28 metri è molto vicino e quindi corretto. Più vai veloce, più spazio ti serve per fermarti.', 'La parola "circa" è importante: 28 metri è un valore accettabile e vicino ai 30 metri.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 100 km/h: (100/10) x 3 = 30 metri. 28 è vicino. VERO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22581, 'A 150 km/h, la distanza di sicurezza è di circa 45 metri. Il valore di 42 metri è molto vicino e quindi corretto. A queste velocità, ogni metro è prezioso.', 'Il termine "circa" permette questa leggera differenza. L''importante è che il valore sia realistico e sufficiente.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 150 km/h: (150/10) x 3 = 45 metri. 42 è vicino. VERO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22582, 'A 130 km/h, la distanza di sicurezza è di circa 39 metri. Il valore di 36 metri è molto vicino e quindi corretto. Mantenere una buona distanza è fondamentale per la sicurezza.', 'Ancora una volta, "circa" ci aiuta a capire che non serve un numero preciso al millimetro, ma un''approssimazione corretta.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 130 km/h: (130/10) x 3 = 39 metri. 36 è vicino. VERO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22583, 'FALSO. A 30 km/h, la distanza di sicurezza è di circa 9 metri. 2 metri sono troppo pochi e molto pericolosi, non ti darebbero il tempo di reagire o frenare.', 'La parola "minima" è importante. Significa che non puoi andare sotto questa distanza. 2 metri è molto meno della distanza minima necessaria.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 30 km/h: 9 metri. 2 metri è troppo poco! FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22584, 'FALSO. A 50 km/h, la distanza di sicurezza è di circa 15 metri. 5 metri sono troppo pochi e non ti darebbero il tempo di frenare in caso di emergenza.', 'Il termine "minima" è la chiave. 5 metri è un valore troppo basso per essere considerato una distanza di sicurezza adeguata a 50 km/h.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 50 km/h: 15 metri. 5 metri è troppo poco! FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22585, 'FALSO. A 100 km/h, la distanza di sicurezza è di circa 30 metri. 15 metri sono la metà e sono insufficienti per fermarsi in sicurezza, specialmente a questa velocità.', 'La parola "minima" è fondamentale. 15 metri non è la distanza minima di sicurezza a 100 km/h, è un valore troppo basso.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 100 km/h: 30 metri. 15 metri è troppo poco! FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22586, 'FALSO. A 130 km/h, la distanza di sicurezza è di circa 39 metri. 20 metri sono troppo pochi per reagire e frenare in sicurezza, mettendo a rischio te e gli altri.', 'Il termine "minima" ci dice che il valore proposto (20 metri) è troppo basso per essere considerato sicuro a 130 km/h.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 130 km/h: 39 metri. 20 metri è troppo poco! FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22587, 'FALSO. A 150 km/h, la distanza di sicurezza è di circa 45 metri. 25 metri sono quasi la metà e non permettono di evitare un ostacolo o di frenare in tempo a questa alta velocità.', 'La parola "minima" è cruciale. 25 metri non è la distanza minima richiesta per la sicurezza a 150 km/h, è un valore pericolosamente basso.', 'Per la distanza di sicurezza, prova (velocità / 10) x 3. A 150 km/h: 45 metri. 25 metri è troppo poco! FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22588, 'È vero che la distrazione alla guida può causare incidenti. Se non guardi la strada o non sei concentrato, è facile fare errori e provocare un incidente.', 'La parola ''può'' indica una possibilità, ma nel contesto della guida, la distrazione è una causa molto comune di incidenti.', 'Distrazione = Rischio incidente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22589, 'È vero. Accendere il cellulare, guardarlo o usarlo mentre guidi ti distrae dalla strada. Anche solo un attimo per accenderlo è pericoloso.', 'Anche qui, ''può essere causata'' sottolinea la possibilità. L''azione di accendere il cellulare richiede di togliere gli occhi dalla strada e le mani dal volante.', 'Cellulare = Occhi via dalla strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22590, 'È vero. Accendere una sigaretta richiede di usare una mano e di distogliere lo sguardo per un momento, anche breve. Questo ti distrae dalla guida.', 'La frase ''può essere causata'' indica che non è sempre così, ma è una possibilità concreta. Qualsiasi azione che ti impegna le mani o gli occhi è una potenziale distrazione.', 'Sigaretta = Mani e occhi occupati.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22591, 'È vero. Cercare i comandi della radio, del navigatore o di altri apparecchi elettronici ti fa distogliere lo sguardo dalla strada e ti distrae dalla guida.', 'La ''ricerca dei comandi'' implica che non sai esattamente dove sono, quindi devi guardare per trovarli, togliendo l''attenzione dalla guida.', 'Comandi = Sguardo altrove.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22592, 'È falso. L''uso del cellulare è una delle cause principali di distrazione alla guida. Dire che ''non è determinata'' è sbagliato, perché il cellulare distrae moltissimo.', 'La parola ''non'' è la chiave. La frase nega una verità. L''uso del cellulare è una delle maggiori cause di distrazione.', 'Cellulare = SEMPRE distrazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22593, 'È falso. Anche pochi secondi di distrazione sono molto pericolosi. A 50 km/h, in soli 2 secondi, l''auto percorre circa 28 metri senza che tu guardi la strada. È un tempo sufficiente per causare un incidente grave.', 'Le parole ''non rappresenta un pericolo'' e ''pochi secondi'' sono la trappola. Ogni secondo conta quando si guida, e anche un attimo di distrazione può avere conseguenze gravi.', 'Ogni secondo conta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22594, 'VERO. Per sapere quanti metri si percorrono in un secondo, devi dividere la velocità in km/h per 3,6. Se dividi 50 per 3,6, ottieni circa 13,88 metri, che è molto vicino a 14 metri. Quindi, la frase è corretta.', 'La parola ''circa'' è importante. Significa ''più o meno'', ''approssimativamente''. Non devi calcolare il numero esatto al millimetro, ma capire se il valore è vicino a quello giusto.', '50 km/h? Pensa a 14 metri al secondo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22595, 'VERO. Applichiamo la stessa regola: dividiamo la velocità in km/h per 3,6. Se dividi 100 per 3,6, ottieni circa 27,77 metri. Questo valore è molto vicino a 28 metri. Quindi, la frase è corretta.', 'Anche qui, ''circa'' ti dice che il numero non è preciso al centesimo, ma è una buona stima. Se il numero fosse stato molto diverso (es. 10 metri), allora sarebbe stato FALSO.', '100 km/h? Sono quasi 28 metri al secondo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22596, 'VERO. Dividendo 130 km/h per 3,6, otteniamo circa 36,11 metri al secondo. Questo valore è molto vicino a 36 metri. Quindi, la frase è corretta.', 'Ricorda che ''circa'' ti dà un margine di tolleranza. Il valore indicato (36 metri) è una buona approssimazione del calcolo reale.', '130 km/h? Ricorda 36 metri al secondo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22597, 'VERO. Se dividiamo 150 km/h per 3,6, otteniamo circa 41,66 metri al secondo. Questo valore è molto vicino a 42 metri. Quindi, la frase è corretta.', 'La parola ''circa'' è fondamentale per queste domande. Ti permette di accettare un numero che non è esattamente il risultato del calcolo, ma è molto vicino.', '150 km/h? Quasi 42 metri al secondo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22598, 'FALSO. Abbiamo appena visto che a 150 km/h si percorrono circa 42 metri al secondo (150 / 3,6 = 41,66...). 20 metri è un valore molto più basso e non è ''circa'' 42 metri. Quindi, la frase è sbagliata.', 'Anche se c''è la parola ''circa'', il numero 20 è troppo lontano dal valore corretto (circa 42) per essere considerato un''approssimazione valida. ''Circa'' non significa ''un numero a caso''.', '150 km/h non sono 20 m/s, ma circa 42!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22599, 'FALSO. A 50 km/h si percorrono circa 14 metri al secondo (50 / 3,6 = 13,88...). 4 metri è un valore molto più basso e non è ''circa'' 14 metri. Quindi, la frase è sbagliata.', 'Il termine ''circa'' non giustifica una differenza così grande. 4 metri è un valore troppo piccolo rispetto ai 14 metri reali per essere considerato un''approssimazione.', '50 km/h non sono 4 m/s, ma circa 14!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22600, 'FALSO. A 100 km/h si percorrono circa 28 metri al secondo (100 / 3,6 = 27,77...). 10 metri è un valore molto più basso e non è ''circa'' 28 metri. Quindi, la frase è sbagliata.', 'Ancora una volta, ''circa'' non rende vera una frase con un numero così diverso. 10 metri è meno della metà del valore corretto, quindi non è un''approssimazione accettabile.', '100 km/h non sono 10 m/s, ma circa 28!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22601, 'FALSO. A 130 km/h si percorrono circa 36 metri al secondo (130 / 3,6 = 36,11...). 15 metri è un valore molto più basso e non è ''circa'' 36 metri. Quindi, la frase è sbagliata.', 'La parola ''circa'' non può essere usata per valori che sono così lontani dal risultato corretto. 15 metri è troppo poco rispetto ai 36 metri che si percorrono realmente.', '130 km/h non sono 15 m/s, ma circa 36!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22602, 'Questa affermazione è VERA. Lo spazio di frenatura è esattamente la distanza che il tuo veicolo percorre dal momento in cui inizi a premere il pedale del freno fino a quando l''auto si ferma completamente.', 'Non ci sono parole trappola particolari. La definizione è diretta e precisa.', 'Spazio frenatura = da inizio frenata a stop.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22603, 'Questa affermazione è VERA. È una regola fondamentale: lo spazio di frenatura non aumenta in modo semplice come la velocità, ma aumenta con il ''quadrato'' della velocità. Se raddoppi la velocità (x2), lo spazio di frenatura aumenta di 2x2, cioè 4 volte (si quadruplica).', 'La parola trappola potrebbe essere ''raddoppia'' (riferita alla velocità) che potrebbe farti pensare che anche lo spazio raddoppi. Invece, lo spazio ''quadruplica''.', 'Velocità x2 = Spazio x4 (al quadrato!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22604, 'Questa affermazione è VERA. Seguendo la stessa regola della domanda precedente, se la velocità si triplica (x3), lo spazio di frenatura aumenta di 3x3, cioè 9 volte.', 'Anche qui, ''triplica'' (riferita alla velocità) è la chiave. Ricorda che lo spazio aumenta al quadrato, quindi non 3 volte, ma 9 volte.', 'Velocità x3 = Spazio x9 (al quadrato!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22605, 'Questa affermazione è VERA. Ancora una volta, applicando la regola del quadrato, se la velocità si quadruplica (x4), lo spazio di frenatura aumenta di 4x4, cioè 16 volte.', 'La parola ''quadruplica'' (riferita alla velocità) è importante. Non confonderla con un aumento di 4 volte dello spazio, ma di 16 volte.', 'Velocità x4 = Spazio x16 (al quadrato!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22606, 'Questa affermazione è FALSA. Lo spazio di frenatura dipende moltissimo dalla velocità! Più vai veloce, più spazio ti serve per fermarti. Le domande precedenti lo dimostrano chiaramente.', 'La parola trappola è ''indipendente''. Significa ''che non dipende da''. Invece, lo spazio di frenatura dipende eccome dalla velocità!', 'Spazio frenata e velocità sono DIPENDENTI.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22607, 'Questa affermazione è FALSA. È una trappola comune! Come abbiamo imparato, se la velocità si raddoppia, lo spazio di frenatura non raddoppia, ma si quadruplica (aumenta di 4 volte).', 'La parte ''si raddoppia'' (riferita allo spazio di frenatura) è la parola trappola. È facile pensare che l''aumento sia proporzionale, ma non lo è.', 'Velocità x2 = Spazio x4, NON x2!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22608, 'Se l''aderenza tra le gomme e l''asfalto è bassa (cioè le gomme scivolano facilmente), l''auto impiega più strada per fermarsi. Quindi, lo spazio di frenatura aumenta.', 'La parola chiave è ''aderenza bassa'', che significa che le gomme non fanno bene presa sulla strada.', 'Poca aderenza = più strada per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22609, 'La neve rende la strada molto scivolosa, riducendo l''aderenza delle gomme. Quando la strada è scivolosa, l''auto ha bisogno di più spazio per fermarsi in sicurezza.', '''Innevata'' indica una condizione di scarsa aderenza, come il ghiaccio o il bagnato.', 'Neve = scivola = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22610, 'L''acqua sull''asfalto riduce l''attrito tra le gomme e la strada. Questo significa che le gomme fanno più fatica a ''aggrapparsi'' e l''auto ha bisogno di più spazio per fermarsi.', '''Bagnata'' è una condizione che diminuisce l''aderenza, proprio come la neve o il ghiaccio.', 'Bagnato = scivola = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22611, 'Quando la strada è in discesa, la forza di gravità ''spinge'' l''auto in avanti. Questo rende più difficile rallentare e fermarsi, quindi serve più spazio per frenare.', '''In discesa'' è la condizione che aumenta lo spazio di frenatura a causa della gravità.', 'Discesa = gravità spinge = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22612, 'Quando la strada è in salita, la forza di gravità ''tira'' l''auto indietro, aiutandola a rallentare. Per questo motivo, l''auto ha bisogno di meno spazio per fermarsi.', '''In salita'' è la condizione che diminuisce lo spazio di frenatura perché la gravità aiuta a rallentare.', 'Salita = gravità aiuta = meno spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22613, 'I riflessi pronti del conducente riducono il ''tempo di reazione'' (il tempo che passa da quando vedi un pericolo a quando inizi a frenare). Ma lo ''spazio di frenatura'' è solo la distanza che l''auto percorre DA QUANDO INIZI A FRENARE FINO A QUANDO SI FERMA. I riflessi non cambiano questa distanza.', 'Attenzione alla differenza tra ''spazio di frenatura'' e ''spazio di reazione''. I riflessi influiscono sullo spazio di reazione, non su quello di frenatura.', 'Riflessi = tempo di reazione, non spazio di frenatura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22614, 'Se le ruote si bloccano, smettono di girare e l''auto scivola sull''asfalto. Questo non aiuta a frenare, anzi! L''auto perde aderenza e controllo, e lo spazio per fermarsi aumenta. I sistemi come l''ABS servono proprio a evitare il bloccaggio delle ruote.', '''Si bloccano'' è una condizione negativa per la frenata efficace, non positiva.', 'Ruote bloccate = scivoli = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22615, 'Il tratto in discesa di un dosso è una discesa. Come abbiamo imparato, in discesa la forza di gravità spinge l''auto in avanti, rendendo più difficile fermarsi. Quindi, lo spazio di frenatura aumenta, non diminuisce.', 'La frase ''tratto in discesa'' è la chiave. Non importa che sia un dosso, è comunque una discesa.', 'Discesa (anche di un dosso) = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22616, 'Questa affermazione è falsa. In salita, la forza di gravità aiuta a rallentare l''auto, quindi lo spazio di frenatura DIMINUISCE, non aumenta.', 'La parola ''aumenta'' è la trappola. Ricorda che in salita la gravità ti aiuta a fermarti prima.', 'Salita = gravità aiuta = meno spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22617, 'Questa affermazione è falsa. In discesa, la forza di gravità spinge l''auto in avanti, rendendo più difficile fermarsi. Quindi, lo spazio di frenatura AUMENTA, non diminuisce.', 'La parola ''diminuisce'' è la trappola. Ricorda che in discesa la gravità ti spinge e ti serve più strada.', 'Discesa = gravità spinge = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22618, 'VERO. Lo spazio totale di arresto è la somma di due parti: lo spazio che percorri mentre decidi di frenare (tempo di reazione) e lo spazio che percorri mentre il veicolo frena davvero.', 'Nessuna parola trappola evidente. Questa è la definizione esatta.', 'Arresto = Reazione + Frenata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22619, 'VERO. Se vai più veloce, il veicolo percorre più strada sia nel tempo di reazione sia durante la frenata. Quindi, maggiore è la velocità, maggiore sarà lo spazio totale di arresto.', 'Nessuna parola trappola evidente.', 'Più veloce = più spazio per fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22620, 'VERO. I pneumatici usurati (consumati) hanno meno aderenza (grip) sull''asfalto. Con meno aderenza, il veicolo impiega più strada per fermarsi, aumentando lo spazio di frenata e quindi quello totale di arresto.', 'Nessuna parola trappola evidente.', 'Gomme lisce = più strada per fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22621, 'VERO. Se l''asfalto è bagnato, ghiacciato, sporco o rovinato, il veicolo ha meno aderenza. Questo allunga lo spazio di frenata e di conseguenza lo spazio totale di arresto.', 'Nessuna parola trappola evidente.', 'Asfalto brutto = più strada per fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22622, 'FALSO. Questa domanda dice che lo spazio di arresto ''è indipendente'' dall''usura dei pneumatici, ma non è vero. Come abbiamo visto, i pneumatici usurati riducono l''aderenza e aumentano lo spazio di frenata.', 'La parola ''indipendente'' è una trappola. Significa ''non dipende da''. In questo caso, è falso perché lo spazio di arresto dipende eccome dall''usura dei pneumatici.', 'Indipendente = Attenzione! Spesso FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22623, 'FALSO. Questa domanda dice che lo spazio di arresto ''è indipendente'' dalle condizioni dell''asfalto, ma non è vero. Le condizioni dell''asfalto (bagnato, ghiacciato, ecc.) influenzano molto l''aderenza e quindi lo spazio di frenata.', 'Anche qui, ''indipendente'' è la parola trappola. Lo spazio di arresto dipende molto dalle condizioni dell''asfalto.', 'Indipendente = Attenzione! Spesso FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22624, 'FALSO. Lo spazio totale di arresto non è ''solo'' lo spazio percorso nel tempo di reazione. È la somma dello spazio di reazione PIÙ lo spazio di frenata. Manca un pezzo!', 'La frase ''è pari a'' può essere una trappola, perché implica che sia solo quella parte. In questo caso, è incompleta.', 'Arresto = Reazione + Frenata. Non solo Reazione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22625, 'FALSO. Lo spazio totale di arresto non è ''solo'' lo spazio percorso durante la frenata. È la somma dello spazio di reazione PIÙ lo spazio di frenata. Manca un pezzo!', 'Anche qui, ''è pari a'' è la trappola. Implica che sia solo la frenata, ma manca lo spazio percorso nel tempo di reazione.', 'Arresto = Reazione + Frenata. Non solo Frenata!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22626, 'FALSO. Questa domanda dice che lo spazio di arresto ''non dipende'' dalla velocità, ma è sbagliato. La velocità è uno dei fattori più importanti: più vai veloce, più strada ti serve per fermarti.', 'La negazione ''non dipende'' è la trappola. La velocità è un fattore fondamentale per lo spazio di arresto.', 'Non dipende = Attenzione! Spesso FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22627, 'Se la velocità del veicolo aumenta, ci vuole più tempo e più strada per fermarsi completamente. Sia il tempo che impieghi a reagire che la distanza per frenare aumentano in modo significativo.', 'La parola chiave è ''aumenta''. Se una cosa aumenta (la velocità), anche l''altra (lo spazio di arresto) aumenta.', 'Più veloce = più strada per fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22628, 'La neve rende la strada molto scivolosa. Le gomme fanno più fatica ad ''aggrapparsi'' all''asfalto, quindi l''auto ha bisogno di più spazio per frenare e fermarsi.', 'La condizione ''innevata'' indica una superficie con poca aderenza.', 'Neve = scivoloso = più spazio per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22629, 'Il fango sulla strada riduce l''aderenza dei pneumatici, proprio come la neve o il ghiaccio. Le gomme scivolano di più e l''auto impiega più tempo e più spazio per fermarsi in sicurezza.', 'La frase ''coperta di fango'' descrive una condizione della strada che peggiora l''aderenza.', 'Fango = scivoloso = più spazio per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22630, 'I pneumatici usurati (consumati) hanno meno battistrada, cioè meno ''disegno'' sulla gomma. Questo riduce l''aderenza alla strada, facendo scivolare di più l''auto e aumentando lo spazio necessario per fermarsi.', 'La parola ''usurati'' è fondamentale: indica che i pneumatici non sono in buone condizioni.', 'Gomme usurate = meno grip = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22631, 'Se i pneumatici NON sono usurati, significa che sono in buone condizioni e hanno un buon battistrada. Pneumatici buoni offrono una buona aderenza alla strada, permettendo all''auto di frenare in uno spazio MINORE, non maggiore.', 'La negazione ''NON sono usurati'' è la chiave. Significa il contrario di usurati, quindi ''nuovi'' o ''in buono stato''.', 'Gomme buone = meno spazio per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22632, 'Se la velocità diminuisce, significa che stai andando più piano. Andando più piano, hai bisogno di meno strada per fermarti. Quindi lo spazio di arresto DIMINUISCE, non aumenta.', 'Attenzione alla contraddizione: ''aumenta se diminuisce''. Se la velocità diminuisce, lo spazio di arresto diminuisce.', 'Meno velocità = meno strada per fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22633, 'L''asfalto ruvido offre una maggiore aderenza (grip) ai pneumatici rispetto a un asfalto liscio. Una buona aderenza aiuta l''auto a frenare meglio e in uno spazio MINORE, non maggiore.', 'La parola ''ruvido'' è importante: indica una superficie che offre buona aderenza.', 'Asfalto ruvido = più grip = meno spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22634, 'Se il conducente non è concentrato (ad esempio, è stanco o distratto), reagirà più lentamente in caso di pericolo. Questo significa che avrà bisogno di più tempo e spazio per frenare, quindi la distanza di sicurezza deve essere maggiore.', 'La parola ''concentrazione'' è importante. Meno concentrazione significa più rischio e quindi più bisogno di spazio.', 'Meno attenzione = più distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22635, 'Più un veicolo va veloce, più strada percorre prima che il conducente possa reagire e il veicolo si fermi completamente. Per questo motivo, a velocità più alte è necessaria una distanza di sicurezza maggiore.', 'La ''velocità'' è il fattore più importante per la distanza di sicurezza. Ricorda che lo spazio di frenata aumenta molto con la velocità.', 'Velocità alta = distanza lunga.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22636, 'Un veicolo con un carico pesante ha più massa e quindi più inerzia. Questo significa che ha bisogno di più forza e più spazio per fermarsi completamente quando si frena. Perciò, con un carico maggiore, la distanza di sicurezza deve aumentare.', 'Il ''carico trasportato'' si riferisce al peso extra nel veicolo. Più peso, più difficile fermarsi.', 'Più peso = più distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22637, 'L''aderenza è la capacità delle gomme di ''aggrapparsi'' alla strada. Se la strada è bagnata, ghiacciata o le gomme sono usurate, l''aderenza diminuisce. Con meno aderenza, il veicolo scivola di più e ha bisogno di uno spazio di frenata molto più lungo, quindi la distanza di sicurezza deve essere maggiore.', 'Le parole ''aderenza'' e ''condizioni dei pneumatici'' sono fondamentali. Indicano quanto bene le gomme ''tengono'' la strada.', 'Gomme/strada brutte = più distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22639, 'Il numero di corsie di una strada (ad esempio, una strada con una corsia o con tre corsie) non cambia la distanza minima che ti serve per frenare in sicurezza. La distanza di sicurezza dipende da te, dal tuo veicolo e dalle condizioni della strada, non da quante corsie ci sono.', 'La frase ''numero di corsie'' è una distrazione. Non ha un impatto diretto sulla fisica della frenata o sul tempo di reazione.', 'Corsie non contano per la distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22640, 'La distanza di sicurezza che devi mantenere serve a garantire che tu abbia spazio sufficiente per fermarti senza colpire il veicolo che ti precede. Non importa se quel veicolo è una piccola auto o un grande camion; la tua capacità di frenare e il tuo spazio di arresto sono determinati dal tuo veicolo e dalle condizioni, non dalla dimensione di chi ti sta davanti.', 'La ''dimensione del veicolo che precede'' è irrilevante. Tu devi avere spazio per fermarti *prima* di lui, a prescindere dalla sua grandezza.', 'La dimensione dell''altro non cambia la tua distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22641, 'Il numero di marce del cambio serve per gestire la potenza del motore e la velocità del veicolo. Non ha alcun effetto diretto sulla distanza necessaria per frenare in caso di emergenza. La frenata dipende dai freni, dalle gomme e dalla velocità.', 'Il ''numero di marce'' è una caratteristica meccanica del motore, non del sistema frenante. È una parola trappola.', 'Marce non frenano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22642, 'Il numero di ruote del veicolo (ad esempio, due per una moto, quattro per un''auto) non è un fattore che influenza direttamente la distanza di sicurezza. Questa si calcola in base alla velocità, alle condizioni della strada, del veicolo e del conducente, non al numero di ruote.', 'Il ''numero di ruote'' è una caratteristica del veicolo, ma non determina lo spazio di frenata o la distanza di sicurezza.', 'Ruote non dettano la distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22643, 'Il servosterzo è un sistema che rende più facile girare il volante. Non ha nessuna funzione legata alla frenata o allo spazio che ti serve per fermarti in sicurezza. Quindi, il tipo di servosterzo non influisce sulla distanza di sicurezza.', 'Il ''tipo di servosterzo'' è una parola trappola. È un aiuto per sterzare, non per frenare.', 'Servosterzo non frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22644, 'La distanza di sicurezza è lo spazio che devi lasciare tra la tua auto e quella che ti precede. Questo spazio serve per frenare in tempo. Il tipo di carburante (benzina, gasolio, GPL) non cambia la capacità di frenata della tua auto o il tuo tempo di reazione. Quindi, non influenza la distanza di sicurezza.', 'La frase ''tipo di alimentazione del motore'' è la parte su cui fare attenzione. Non ha alcuna relazione con la distanza di sicurezza.', 'Carburante non frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22645, 'Se non stai bene, sei stanco o hai problemi di salute, il tuo tempo di reazione potrebbe essere più lento. Questo significa che ti ci vorrà più tempo per accorgerti di un pericolo e frenare. Per questo, devi aumentare la distanza di sicurezza per avere più spazio per reagire.', 'Le ''condizioni di salute'' del conducente sono importanti perché influenzano la tua prontezza alla guida.', 'Stanco? Più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22646, 'Se sei distratto o non concentrato, impiegherai più tempo a vedere un pericolo e a frenare. Un tempo di reazione più lungo richiede una distanza di sicurezza maggiore per evitare incidenti. Per questo, l''attenzione è fondamentale.', 'Le parole ''attenzione e concentrazione'' sono la chiave. Se mancano, aumenta il rischio.', 'Attento? Meno rischi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22647, 'Quando ci sono molte auto vicine, come in coda o nel traffico, è una buona idea lasciare più spazio tra un veicolo e l''altro. Se un''auto frena bruscamente, avere più distanza ti dà il tempo di frenare senza colpire l''auto davanti e senza che quella dietro ti tamponi, evitando così una serie di incidenti.', 'La frase ''tamponamenti a catena'' spiega il motivo per cui è importante aumentare la distanza in colonna.', 'Colonna? Larga distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22648, 'La distanza di sicurezza che devi mantenere dipende dalla tua velocità, dalle condizioni della strada, dalla tua auto e dal tuo tempo di reazione. Non dipende dalla potenza del motore dell''auto che ti sta davanti. La potenza di un altro veicolo non cambia il tuo spazio di frenata.', 'La ''potenza del veicolo che precede'' è un elemento irrilevante per la tua distanza di sicurezza.', 'Potenza altrui non ti frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22649, 'Il freno a mano (o freno di stazionamento) serve per tenere ferma l''auto quando è parcheggiata. Non è usato per frenare l''auto mentre si guida. La distanza di sicurezza dipende dall''efficienza dei freni principali (freni di servizio) e non dal freno a mano.', 'Il ''freno a mano'' è la parola trappola. Non è il freno che usi per la distanza di sicurezza.', 'Freno a mano = parcheggio, non sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22650, 'La distanza di sicurezza è lo spazio che devi mantenere tra la tua auto e il veicolo che ti sta davanti. Non ha nulla a che fare con i veicoli che ti seguono, cioè quelli che sono dietro di te. Tu devi preoccuparti di avere spazio sufficiente per frenare rispetto a chi ti precede.', 'La frase ''presenza di veicoli che seguono'' è la parte su cui fare attenzione. La distanza di sicurezza riguarda solo ciò che è davanti a te.', 'Sicurezza = davanti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22651, 'La distanza di sicurezza è una regola fondamentale che vale per tutti i veicoli, non solo per i quadricicli a motore. Auto, moto, camion, autobus e tutti gli altri veicoli devono mantenere una distanza di sicurezza adeguata per la sicurezza di tutti sulla strada.', 'La parola ''solo'' è la trappola principale. Le regole di sicurezza stradale sono quasi sempre per tutti.', 'Distanza = per tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22652, 'La distanza di sicurezza è fondamentale per la tua sicurezza e quella degli altri. Devi mantenerla sempre, anche quando stai per sorpassare un altro veicolo. Questo ti permette di avere il tempo di reagire se il veicolo davanti frena all''improvviso o succede qualcosa di inaspettato.', 'La parola ''sempre'' è importante. Significa che non ci sono eccezioni, nemmeno ''prima di iniziare un sorpasso''.', 'Distanza di sicurezza: mai attaccarsi, nemmeno per sorpassare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22653, 'Se non riesci a capire bene cosa farà il conducente davanti a te (magari guida in modo strano, o non vedi bene i suoi stop), è più sicuro aumentare la distanza di sicurezza. Così hai più tempo per reagire a qualsiasi sua mossa inaspettata.', 'La frase chiave è ''difficile valutare il comportamento''. Quando c''è incertezza, la distanza deve ''essere aumentata''.', 'Dubbi sul davanti? Aumenta la distanza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22654, 'Lo scopo principale della distanza di sicurezza è darti lo spazio e il tempo necessari per fermare il tuo veicolo in sicurezza. Se c''è un pericolo improvviso, come un ostacolo o una frenata brusca del veicolo che ti precede, devi riuscire a fermarti senza causare un incidente.', 'Le parole ''fermare in tempo'' e ''in caso di pericolo'' spiegano il motivo fondamentale della distanza di sicurezza.', 'Distanza = Tempo per fermarsi in sicurezza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22655, 'Il tempo di reazione è il tempo che impieghi per vedere un pericolo e decidere di frenare. Durante questo tempo, il tuo veicolo continua a muoversi. La distanza di sicurezza deve essere almeno uguale a quella che percorri in questo tempo, per darti una base minima di sicurezza prima ancora di iniziare a frenare.', 'La frase ''almeno uguale'' è cruciale. Significa che la distanza di sicurezza deve coprire come minimo lo spazio percorso durante il ''tempo di reazione'', ma in realtà deve essere anche di più (includendo lo spazio di frenatura).', 'Distanza minima = Spazio di reazione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22656, 'Questa affermazione è falsa. La distanza di sicurezza non è uguale solo allo spazio di frenatura. La distanza di sicurezza è la somma di due parti: lo spazio che percorri durante il tuo tempo di reazione (prima di iniziare a frenare) E lo spazio di frenatura (mentre stai frenando). Quindi, la distanza di sicurezza è sempre maggiore dello spazio di frenatura da solo.', 'La parola ''sempre uguale'' è la trappola. La distanza di sicurezza è composta da ''spazio di reazione'' + ''spazio di frenatura'', quindi non è ''sempre uguale'' solo allo spazio di frenatura.', 'Distanza sicurezza = Reazione + Frenata. Non solo frenata!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22657, 'Se il veicolo davanti a te ha un carico che sporge o non è stabile, c''è un rischio maggiore che qualcosa cada o che il carico si muova in modo inaspettato. Per questo motivo, devi aumentare la distanza di sicurezza per avere più tempo e spazio per reagire in caso di pericolo.', 'La frase ''deve essere aumentata'' indica una necessità di maggiore cautela. ''Carico sporgente, poco stabile'' sono le condizioni di rischio che giustificano l''aumento.', 'Carico instabile = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22658, 'La distanza di sicurezza non è mai un numero fisso (come ''almeno 100 metri''). Dipende da tanti fattori: la tua velocità, le condizioni della strada (asciutta, bagnata, ghiacciata), il tipo di veicolo, la tua prontezza. In caso di forte pioggia, devi certamente aumentare la distanza, ma non esiste una regola che imponga esattamente 100 metri.', 'La trappola è ''di almeno 100 metri''. Le distanze di sicurezza non sono quasi mai espresse con un numero fisso e preciso, perché variano sempre. ''Deve essere'' è un''affermazione forte che qui è falsa per il numero specifico.', 'Distanza non è fissa! Dipende da tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22659, 'Nelle gallerie, la visibilità può essere ridotta, e lo spazio per manovrare è limitato. Per questi motivi, è ancora più importante mantenere una distanza di sicurezza adeguata, o addirittura aumentarla, non diminuirla. Diminuire la distanza aumenterebbe il rischio di incidenti.', 'La parola chiave ''diminuita'' è la trappola. In situazioni potenzialmente più rischiose (come le gallerie), la distanza di sicurezza va mantenuta o aumentata, mai diminuita.', 'Galleria = meno visibilità, più attenzione, non meno distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22660, 'In autostrada si viaggia a velocità più elevate. Maggiore è la velocità, maggiore è lo spazio necessario per frenare in sicurezza. Anche se le frenate improvvise sono meno frequenti, possono comunque accadere, e le conseguenze sarebbero più gravi. Per questo motivo, in autostrada la distanza di sicurezza deve essere maggiore, non minore.', 'La frase ''è possibile diminuire la distanza di sicurezza'' è la trappola. L''argomento ''non ci si aspetta una frenata improvvisa'' è un''assunzione pericolosa e non giustifica la diminuzione della distanza.', 'Autostrada = alta velocità = più distanza, non meno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22661, 'È vero che gli autocarri (veicoli pesanti) hanno uno spazio di frenatura più lungo rispetto alle auto. Ma proprio per questo motivo, tu devi aumentare la distanza di sicurezza dal veicolo pesante che ti precede. Se frenasse all''improvviso, a lui servirebbe più spazio per fermarsi, e tu dovresti avere più spazio per reagire e frenare a tua volta senza tamponarlo. Diminuire la distanza sarebbe molto pericoloso.', 'La trappola è ''si deve diminuire la distanza di sicurezza''. La motivazione data (''i veicoli pesanti hanno uno spazio di frenatura molto più lungo'') è corretta, ma la conclusione che ne deriva (''diminuire la distanza'') è sbagliata e pericolosa.', 'Autocarro = frena più tardi = tu stai più lontano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22662, 'Quando un veicolo esce da un parcheggio in retromarcia per entrare nella strada, deve dare la precedenza a tutti i veicoli che stanno già circolando, sia quelli che arrivano da destra che quelli da sinistra. Questo perché chi si immette nel traffico è sempre tenuto a non creare pericolo o intralcio.', 'La frase ''deve dare la precedenza'' indica un obbligo. ''Sia da destra che da sinistra'' sottolinea che la precedenza è per tutti i veicoli in transito.', 'Chi esce dal parcheggio, dà la precedenza a tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22663, 'Sì, è obbligatorio segnalare le proprie intenzioni agli altri utenti della strada. Azionare l''indicatore di direzione (la freccia) serve a comunicare dove intendi andare una volta che sarai uscito dal parcheggio e ti sarai immesso nella circolazione.', '''Azionare gli indicatori di direzione'' è un''azione necessaria per ogni manovra che cambia la direzione o la posizione del veicolo.', 'Ogni manovra, freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22664, 'I pedoni sono utenti della strada più vulnerabili e hanno sempre la precedenza, specialmente quando un veicolo fa retromarcia. Devi guardare attentamente e assicurarti che non ci siano pedoni dietro di te prima di iniziare la manovra e, se ci sono, aspettare che passino.', '''Pedoni in transito'' e ''dar loro la precedenza'' sono concetti chiave: i pedoni hanno sempre la precedenza in queste situazioni.', 'Pedone = precedenza assoluta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22665, 'Esatto. Quando ti immetti nel traffico da una posizione di sosta (come un parcheggio), devi dare la precedenza a tutti i veicoli che sono già sulla strada, indipendentemente dalla loro direzione. Non puoi intralciare la circolazione già presente.', 'La frase ''a tutti i veicoli in transito'' è importante e sottolinea che la precedenza è universale in questo contesto.', 'Chi si immette, dà precedenza a tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22666, 'Fare retromarcia è una manovra che richiede molta attenzione. Devi essere sicuro che non ci siano ostacoli, altri veicoli o pedoni. La prudenza è fondamentale per evitare incidenti, dato che la visibilità in retromarcia è spesso limitata.', '''Assicurarsi che la strada sia libera'' e ''particolare prudenza'' sono concetti fondamentali per la sicurezza stradale.', 'Retromarcia = massima prudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22667, 'Falso. La segnalazione luminosa di pericolo (le ''quattro frecce'') si usa solo in caso di pericolo immediato, di fermata improvvisa o di veicolo fermo che crea intralcio. Per segnalare una normale manovra di immissione nel traffico si usano gli indicatori di direzione (le frecce singole).', 'La ''segnalazione luminosa di pericolo'' è la trappola. Non va usata per una manovra normale, ma solo per situazioni di emergenza.', 'Quattro frecce = pericolo, non manovra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22668, 'Falso. La luce posteriore per nebbia si usa solo in condizioni di scarsa visibilità dovute a nebbia fitta, forte pioggia o neve intensa. Non deve essere accesa per una normale manovra di retromarcia, perché la sua luce intensa può abbagliare chi segue senza motivo.', 'La ''luce posteriore per nebbia'' ha uno scopo specifico legato alle condizioni meteo. Usarla in altre situazioni è sbagliato.', 'Luce nebbia = solo con nebbia fitta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22669, 'Falso. Questa è una trappola! Come abbiamo visto, chi si immette nel traffico da un parcheggio deve dare la precedenza a tutti i veicoli che circolano sulla strada, non ''solo'' a quelli che vanno nella stessa direzione. La sicurezza richiede di guardare in tutte le direzioni.', 'La parola ''solo'' è spesso una trappola nei quiz. La precedenza è ''a tutti'', non limitata a un solo senso di marcia.', 'Precedenza a tutti, non ''solo'' ad alcuni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22670, 'Falso. Le manovre di retromarcia devono essere fatte con estrema lentezza e prudenza, non velocemente. La velocità aumenta il rischio di errori, di non vedere ostacoli o pedoni e di causare incidenti. La sicurezza viene prima della velocità.', '''Manovrare velocemente'' è la trappola. La velocità è pericolosa in retromarcia.', 'Retromarcia = lenta, non veloce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22671, 'Falso. Il clacson si usa solo in caso di pericolo immediato per avvertire gli altri utenti della strada. Suonare ripetutamente il clacson senza un motivo di pericolo è vietato, disturba la quiete pubblica e non è il modo corretto per segnalare una manovra.', '''Suonare ripetutamente il clacson'' è la trappola. L''uso del clacson è limitato a situazioni di pericolo.', 'Clacson = solo per pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22672, 'È VERO. Quando devi svoltare a destra, devi tenerti il più possibile vicino al margine destro della strada. Se ti tieni a sinistra, crei un pericolo per gli altri veicoli e intralci la circolazione.', 'La parola trappola è ''sinistro'' quando si parla di svoltare ''a destra''. Sono due direzioni opposte.', 'Svolta a destra? Stai a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22673, 'È VERO. Sostare (cioè fermarsi per un tempo più lungo della fermata) sui binari del tram è molto pericoloso perché blocca il tram e può causare incidenti. È sempre vietato.', 'La frase ''sostare sui binari tramviari'' indica un''azione chiaramente pericolosa e quindi vietata.', 'Binari = Via libera al tram, non a te.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22674, 'È VERO. Devi sempre segnalare con la freccia (indicatore di direzione) la tua intenzione di cambiare direzione (svoltare, cambiare corsia) con un buon anticipo. Non farlo è pericoloso perché gli altri non sanno cosa farai.', 'Le parole chiave sono ''senza segnalare'' e ''senza sufficiente anticipo''. Fare una manovra senza avvisare è sempre sbagliato.', 'Segnala sempre prima di muoverti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22675, 'È VERO. Gareggiare in velocità (fare corse) sulle strade pubbliche è estremamente pericoloso, illegale e può causare incidenti gravissimi. La strada non è una pista.', 'La frase ''gareggiare in velocità'' è un''azione che implica sempre pericolo e intralcio sulla strada pubblica.', 'Strada non è pista, gareggiare è vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22676, 'È VERO. Guidare troppo lentamente senza un buon motivo (ad esempio, se la strada è libera e le condizioni sono buone) può essere pericoloso. Può creare intralcio al traffico e costringere gli altri veicoli a frenare o a fare manovre improvvise.', 'Le parole ''troppo bassa'' e ''senza giustificato motivo'' sono importanti. Se c''è un motivo (nebbia, pioggia forte), allora è giusto andare piano.', 'Né troppo veloce, né troppo lento (senza motivo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22677, 'È FALSO. Non è vietato immettersi nel traffico da una strada laterale. È una manovra normale che si fa tutti i giorni. L''importante è farla con prudenza, dando la precedenza a chi è già sulla strada principale.', 'La parola ''vietato'' è la trappola. Immettersi nel traffico è una manovra consentita, non vietata, se fatta correttamente.', 'Entrare in strada è normale, ma con prudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22678, 'È FALSO. Non è vietato, ma è OBBLIGATORIO regolare la velocità in base alle condizioni della strada (pioggia, curve, traffico, ecc.). È una regola fondamentale per la sicurezza. Chi non lo fa, mette in pericolo sé stesso e gli altri.', 'La parola ''vietato'' è la trappola. ''Regolare la velocità'' è un dovere del conducente, non un divieto.', 'Adatta la velocità, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22679, 'È FALSO. Fermare momentaneamente (fare una ''fermata'') un veicolo lungo il margine destro di una strada a senso unico è generalmente permesso, a patto che non si crei pericolo o intralcio per la circolazione. La ''fermata'' è diversa dalla ''sosta'' (che è più lunga).', 'Le parole ''vietato'' e ''fermare momentaneamente'' sono importanti. La fermata è spesso permessa, la sosta ha più restrizioni.', 'Fermata a destra (senso unico) = OK se non intralci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22680, 'I limiti di velocità sono regole che valgono per tutti i veicoli, non importa quanto siano potenti o veloci. Anche se la tua auto è ''ad elevate prestazioni'', devi sempre rispettare i limiti di velocità stabiliti dalla legge per la sicurezza di tutti.', 'La frase ''anche se ad elevate prestazioni'' è una distrazione. La potenza del veicolo non cambia le regole della strada.', 'Limiti di velocità = per tutti, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22681, 'Nei crocevia (incroci) senza segnali specifici (come Stop o Dare Precedenza), la regola generale è dare la precedenza ai veicoli che arrivano dalla tua destra. Questa è la ''norma'' del Codice della Strada.', 'La parola ''di norma'' è importante. Significa ''come regola generale'', indicando che ci possono essere eccezioni (ad esempio, se ci sono segnali stradali diversi).', 'Incrocio senza segnali = precedenza a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22682, 'La sicurezza è la cosa più importante quando si guida. Ogni conducente, con qualsiasi tipo di veicolo, deve guidare in modo responsabile per non creare situazioni pericolose per sé e per gli altri utenti della strada (pedoni, ciclisti, altri automobilisti).', 'La frase ''evitare di costituire pericolo'' è un dovere fondamentale di ogni guidatore. Non è un''opzione, ma un obbligo.', 'Guida sicura = mai un pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22683, 'Prima di cambiare corsia o direzione, è fondamentale controllare gli specchietti retrovisori per assicurarsi che non ci siano altri veicoli. Solo dopo aver controllato e aver visto che la manovra è sicura, si può mettere la freccia per segnalare l''intenzione.', 'L''ordine ''prima di segnalare'' è cruciale. Prima guardi, poi segnali. Non il contrario.', 'Specchietto, poi freccia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22684, 'Quando devi svoltare a destra, devi posizionarti il più vicino possibile al bordo destro della strada. Questo serve per fare la svolta in modo sicuro, senza invadere la corsia di chi va dritto o di chi svolta a sinistra, e per essere ben visibile.', 'La frase ''il più vicino possibile al margine destro'' indica la posizione corretta e sicura per la svolta a destra.', 'Svolta a destra = stai a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22685, 'Questa affermazione è falsa. Non si deve guidare ''sempre al centro della strada''. In Italia, si deve tenere la destra della carreggiata, soprattutto quando la strada ha più corsie o quando si incrociano altri veicoli. Guidare al centro è pericoloso e sbagliato.', 'La parola ''sempre'' è una parola trappola. Non è mai vero che si deve guidare sempre al centro. La regola è tenere la destra.', 'Guida = tieni la destra, non il centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22686, 'Questa affermazione è falsa. Gli abbaglianti (luci di profondità) sono luci molto forti che servono per illuminare bene la strada di notte, fuori dai centri abitati e quando non ci sono altri veicoli. Di giorno e in città, si usano gli anabbaglianti o le luci diurne, perché gli abbaglianti darebbero fastidio agli altri e non sono necessari.', 'La combinazione ''abbaglianti di giorno anche in città'' è sbagliata. Gli abbaglianti abbagliano, quindi non si usano in queste condizioni.', 'Abbaglianti = solo di notte, fuori città, senza abbagliare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22687, 'Questa affermazione è falsa. Non si può sorpassare ''in ogni condizione di traffico''. Ci sono molte situazioni in cui il sorpasso è vietato, anche se non c''è un segnale specifico. Ad esempio, è vietato sorpassare in curva, in prossimità degli incroci, sui dossi o quando la visibilità è scarsa.', 'La frase ''in ogni condizione di traffico'' è la trappola. Il sorpasso ha molte regole e divieti, non solo il segnale.', 'Sorpasso = tante regole, non solo il divieto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22688, 'Questa affermazione è falsa. Nei centri abitati, il clacson (avvisatore acustico) si usa solo in caso di pericolo immediato per evitare un incidente. Non si deve usare per segnalare la propria presenza agli attraversamenti ciclabili o pedonali, altrimenti si disturba la quiete pubblica.', 'La frase ''ogni qualvolta ci si avvicina ad un attraversamento ciclabile'' è la trappola. L''uso del clacson è molto limitato in città.', 'Clacson in città = solo per pericolo grave.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22689, 'Questa affermazione è falsa. Le trombe bitonali, che producono un suono più forte e complesso, sono vietate sui veicoli normali. Sono riservate solo ai veicoli di emergenza (come ambulanze, polizia, vigili del fuoco) per segnalare la loro urgenza.', 'Le ''trombe bitonali'' sono la chiave. Sono un tipo di clacson speciale e non sono per le auto comuni.', 'Trombe bitonali = solo per emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22690, 'Sui motocicli è permesso portare animali, ma solo se sono dentro una gabbia speciale, ben fissata e che non ti impedisca di guidare in sicurezza.', 'La parte importante è ''se custoditi in apposita gabbia''. Non puoi portare un animale libero sul motociclo.', 'Animale in moto? Solo in gabbia sicura!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22691, 'Il carico sui motocicli non può sporgere troppo ai lati. Il limite massimo è di 50 centimetri per lato rispetto all''asse del veicolo.', 'Il numero ''50 cm'' è il dato chiave da ricordare per la sporgenza laterale sui motocicli.', 'Moto: carico non più di 50 cm per lato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22692, 'Il carico deve essere messo in modo che tu, come conducente, possa vedere bene la strada, gli specchietti e tutto ciò che ti circonda. La visibilità è fondamentale per la sicurezza.', '''non diminuire la visibilità'' è un principio di sicurezza generale. Se non vedi, non guidi bene.', 'Vedi bene? Carico ok!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22693, 'Il carico non deve bloccare i tuoi movimenti. Devi poter usare il volante, i pedali e il cambio senza problemi per guidare in modo sicuro e reattivo.', '''non impedire la libertà di movimenti'' significa che devi avere il controllo totale del veicolo.', 'Guida libero? Carico ok!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22694, 'Il carico deve essere sempre ben fissato e stabile. Se cade, può essere pericoloso per te e per gli altri utenti della strada.', '''evitarne la caduta'' è una regola di buon senso e sicurezza. Un carico instabile è un pericolo.', 'Carico fermo, mai a terra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22695, 'Il carico può sporgere dalla parte posteriore dell''autoveicolo, ma c''è un limite preciso: non più di tre decimi (cioè il 30%) della lunghezza totale del veicolo.', 'La frase chiave è ''non sporgere dalla parte posteriore per più dei tre decimi''. Ricorda ''tre decimi'' per la sporgenza posteriore.', 'Dietro: max 3/10 della lunghezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22696, 'Ogni veicolo ha un peso massimo che può trasportare, chiamato ''portata''. Questo limite è scritto sulla ''carta di circolazione'' (il libretto del veicolo) e non deve mai essere superato per la tua sicurezza e per non danneggiare il veicolo.', 'Le parole importanti sono ''non deve superare la portata'' e ''carta di circolazione''. Sono termini tecnici che indicano un limite legale.', 'Peso? Controlla la carta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22697, 'Questa affermazione è falsa. Il carico sugli autoveicoli non può sporgere lateralmente, se non in casi molto specifici e con veicoli speciali. La regola dei ''tre decimi'' vale solo per la sporgenza posteriore, non per quella laterale.', 'La trappola è ''sporgenza laterale'' abbinata a ''tre decimi della lunghezza''. I tre decimi sono solo per la sporgenza posteriore. Lateralmente, il carico non deve sporgere.', 'Laterale? Mai! (Tre decimi è solo dietro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22698, 'Questa affermazione è falsa. L''altezza massima di un veicolo con il suo carico non può mai superare i 4 metri. Non esiste una tolleranza del 10% sull''altezza massima indicata sulla carta di circolazione.', 'La trappola è ''non superare di oltre il 10% l''altezza massima''. Non c''è nessuna tolleranza del 10% sull''altezza. Il limite è fisso a 4 metri.', 'Altezza massima: 4 metri, senza eccezioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22699, 'Questa affermazione è falsa. Non è consentito superare la portata utile del veicolo, nemmeno del 10%. La portata è un limite massimo e deve essere rispettata esattamente per la sicurezza e la legalità.', 'La trappola è ''non superare di oltre il 10% la portata utile''. La portata non ha tolleranze. È un limite assoluto.', 'Portata? Zero tolleranza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22700, 'Questa affermazione è falsa. Il carico non può mai sporgere dalla parte anteriore del veicolo. La sporgenza è ammessa solo dietro (fino a 3/10 della lunghezza) e, in casi eccezionali, lateralmente per i motocicli.', 'La trappola è ''sporgere dalla parte anteriore''. La sporgenza anteriore è sempre vietata. Non c''è nessun limite di ''tre decimi'' per la parte davanti.', 'Davanti? Mai sporgere!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22701, 'Questa affermazione è falsa. Se il carico sporge dalla parte posteriore, di giorno deve essere segnalato con un pannello quadrato speciale, omologato, a strisce BIANCHE e rosse, non con un semplice panno rosso.', 'La trappola è ''panno rosso''. Non è un panno qualsiasi, ma un pannello specifico con colori precisi.', 'Sporgenza? Pannello bianco-rosso, non panno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22702, 'Questa affermazione è falsa. Il pannello per segnalare la sporgenza posteriore del carico deve avere strisce BIANCHE e rosse, non gialle e rosse. Il colore è importante per la riconoscibilità e la conformità alle norme.', 'La trappola è ''strisce gialle e rosse''. Il colore corretto è bianco e rosso.', 'Pannello sporgenza: bianco e rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22703, 'Questa affermazione è falsa. Sui motocicli è consentito trasportare un carico, purché sia sistemato correttamente, non sporga troppo (ricordi i 50 cm per lato?) e non superi i limiti di peso.', 'La trappola è ''in nessun caso''. Questa espressione rende quasi sempre falsa l''affermazione, perché di solito ci sono delle condizioni o eccezioni.', '''Nessun caso''? Quasi sempre falso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22704, 'Questa affermazione è falsa. Qualsiasi carico, anche i sacchetti della spesa, deve essere sempre ben fissato e ''saldamente assicurato'' per non cadere, non spostarsi e non creare pericoli durante la guida.', 'La trappola è ''anche se non saldamente assicurati''. Il carico deve essere SEMPRE ben fissato per la sicurezza.', 'Carico? Sempre fisso e sicuro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22705, 'Guidare a una velocità giusta per la situazione (strada, traffico, meteo) è fondamentale per la sicurezza. Non esiste una velocità unica, ma deve cambiare in base alle condizioni.', 'La parola chiave è ''adeguata''. Significa ''giusta'' o ''adatta'' alle circostanze, non una velocità fissa o massima.', 'Velocità = Sicurezza + Condizioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22706, 'Oltre alle regole scritte nel Codice della Strada, è importante usare il buon senso e la prudenza per evitare pericoli e guidare in modo sicuro per tutti.', 'La frase ''comune prudenza'' sottolinea che non bastano solo le regole, ma serve anche il buon senso e l''attenzione.', 'Regole + Prudenza = Guida Corretta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22707, 'Se il semaforo diventa giallo fisso e sei troppo vicino all''incrocio per fermarti in sicurezza (senza frenare bruscamente o creare pericolo), devi attraversare velocemente per non bloccare il traffico.', 'La condizione fondamentale è ''non si è in grado di arrestare il veicolo in sicurezza''. Se puoi fermarti in sicurezza, devi farlo.', 'Giallo + Troppo Vicino = Sgombra Veloce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22708, 'I pedoni che attraversano sulle strisce pedonali hanno sempre la precedenza. È una regola molto importante per la loro sicurezza.', 'Anche se non è esplicitato, il concetto di ''sempre'' è implicito quando si parla di precedenza ai pedoni sulle strisce.', 'Strisce Pedonali = Pedoni Prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22709, 'Di notte, quando guidi nei centri abitati, devi usare i fari anabbaglianti. Servono per vedere la strada ed essere visti dagli altri, senza abbagliare nessuno.', 'La parola ''anabbaglianti'' è importante. Non si usano gli abbaglianti in città di notte, perché darebbero fastidio agli altri.', 'Notte + Città = Anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22710, 'Prima di cambiare corsia, svoltare o fare qualsiasi manovra, devi sempre guardare negli specchietti retrovisori per controllare se ci sono altri veicoli e poi segnalare la tua intenzione con la freccia.', 'L''ordine è fondamentale: ''prima di azionare l''indicatore''. Prima guardi, poi segnali.', 'Specchi + Freccia = Manovra Sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22711, 'Non bisogna sempre andare il più velocemente possibile. La velocità deve essere ''adeguata'' alle condizioni della strada e del traffico, non per forza massima. Andare troppo veloce può essere pericoloso.', 'Le parole ''sempre'' e ''il più rapidamente possibile'' sono trappole. La velocità deve essere adeguata, non massima.', 'Non ''sempre veloce'', ma ''sempre adeguato''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22712, 'Ti fermi ai passaggi pedonali solo se ci sono pedoni che vogliono attraversare o stanno già attraversando. Se non c''è nessuno, non devi fermarti, ma rallentare e fare attenzione.', 'La parola ''sempre'' è la trappola. Non è vero che ci si ferma sempre, ma solo se ci sono pedoni.', 'Pedoni = Stop. No Pedoni = Via Libera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22713, 'I fari abbaglianti si usano solo fuori dai centri abitati e quando non ci sono altri veicoli (o pedoni) che potresti abbagliare. Non si usano ''in ogni caso''.', 'La frase ''in ogni caso'' è una trappola. Gli abbaglianti non si usano sempre, perché possono accecare gli altri.', 'Abbaglianti = Solo se nessuno è abbagliato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22714, 'Se il segnale è un ''Dare precedenza'' (il triangolo rovesciato), ti fermi solo se devi dare la precedenza ad altri veicoli. Se la strada è libera e non arriva nessuno, non ti fermi, ma rallenti e controlli.', 'La frase ''in ogni caso'' è la trappola. Non ci si ferma sempre, ma solo se necessario per dare la precedenza.', 'Dare Precedenza = Fermati solo se serve.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22715, 'Andare a velocità elevata è pericoloso e non è il modo corretto di guidare. La velocità deve essere ''adeguata'' alle condizioni, non alta. Creare intralcio significa andare troppo piano, ma anche andare troppo veloce è sbagliato.', 'La frase ''velocità elevata'' è la trappola. Non è mai la soluzione per non creare intralcio. La velocità deve essere adeguata, non alta.', 'Velocità ''elevata'' = Pericolo. Velocità ''adeguata'' = Sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22716, 'Se ti accorgi di aver scelto la corsia sbagliata prima di un incrocio, devi comunque seguire la direzione indicata dalle frecce sull''asfalto (segnaletica orizzontale) per quella corsia. Non puoi cambiare idea all''ultimo momento.', 'La frase chiave è ''dobbiamo seguire la direzione consentita''. Significa che sei obbligato a rispettare la segnaletica della corsia in cui ti trovi, anche se hai sbagliato.', 'Corsia sbagliata? Segui la freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22717, 'Quando sei già vicino all''incrocio e hai sbagliato corsia, non devi cambiare corsia all''ultimo momento. Questo è pericoloso e crea confusione per gli altri veicoli che ti seguono o che sono nelle corsie vicine.', 'Le parole importanti sono ''non dobbiamo effettuare cambiamenti di corsia''. Cambiare corsia all''ultimo è vietato e pericoloso.', 'Corsia sbagliata? Non cambiare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22718, 'Se hai sbagliato corsia, non devi frenare forte e all''improvviso. Frenare bruscamente è molto pericoloso e può causare un tamponamento con il veicolo che ti segue.', 'Attenzione a ''non ci dobbiamo arrestare bruscamente''. Frenare di colpo è sempre da evitare, specialmente in prossimità di un incrocio.', 'Mai frenare di colpo all''incrocio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22719, 'Non devi fermarti in mezzo all''incrocio per chiedere informazioni. Questo bloccherebbe il traffico e creerebbe un pericolo per tutti gli altri veicoli.', 'La parte importante è ''non ci dobbiamo fermare a chiedere informazioni''. L''incrocio non è un luogo dove fermarsi per chiedere indicazioni.', 'Incrocio non è un ufficio informazioni!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22720, 'Anche se hai sbagliato corsia, devi continuare a guidare nella direzione indicata dalla segnaletica per quella corsia. Ricorda sempre di dare la precedenza a chi ce l''ha, come faresti normalmente.', 'Le parole chiave sono ''procedere nel senso voluto dalla segnaletica'' e ''dando le dovute precedenze''. Devi rispettare sia la direzione della corsia che le regole di precedenza.', 'Segui la freccia e dai la precedenza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22721, 'Se arrivi a un incrocio e non sei sicuro di chi debba passare per primo (chi ha la precedenza), la cosa più sicura da fare è rallentare e procedere con molta attenzione. Meglio essere troppo prudenti che causare un incidente.', 'La frase ''bisogna procedere con prudenza e accortezza'' è fondamentale. In caso di dubbio, la prudenza è sempre la scelta giusta.', 'Dubbio sulla precedenza? Rallenta e osserva!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22722, 'Questa affermazione è falsa. Se non sei sicuro di chi ha la precedenza, devi sempre rallentare e fare attenzione, non importa se vuoi andare dritto, girare a destra o a sinistra. Proseguire senza rallentare è molto pericoloso.', 'La parte ''si può proseguire senza rallentare'' è la trappola. In caso di incertezza sulla precedenza, rallentare è obbligatorio per la sicurezza.', 'Precedenza incerta? Rallenta SEMPRE!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22723, 'Questa affermazione è falsa. Se hai sbagliato corsia, non puoi forzare la svolta che volevi fare. Devi seguire la direzione indicata per la corsia in cui ti trovi, anche se non è quella che avevi in mente.', 'La trappola è ''effettuare la manovra di svolta che intendevamo fare''. Non puoi cambiare la direzione della corsia solo perché hai sbagliato.', 'Non puoi forzare la svolta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22724, 'Questa affermazione è falsa. Non devi fermarti all''incrocio per chiedere consiglio agli agenti del traffico. Questo bloccherebbe la circolazione e creerebbe un pericolo. Devi procedere seguendo la segnaletica della tua corsia.', 'La parte ''dobbiamo chiedere consiglio agli agenti del traffico'' è sbagliata. Non è il momento né il luogo per farlo.', 'Agente non è un navigatore!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22725, 'Questa affermazione è falsa. Accendere tutte le frecce (luci di emergenza) non è la soluzione quando hai sbagliato corsia. Le luci di emergenza si usano per segnalare un vero pericolo (es. veicolo in panne), non un errore di percorso. Usarle in questo caso può confondere gli altri guidatori.', 'La trappola è ''azionare l''accensione simultanea di tutti gli indicatori di direzione, quale segnale di pericolo''. Un errore di corsia non è un pericolo che richiede le luci di emergenza.', 'Frecce d''emergenza non sono per errori di corsia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22726, 'Questa affermazione è falsa. Non devi accostarti e fermarti all''incrocio, nemmeno sulla destra. Fermarsi in un incrocio è pericoloso e blocca il traffico. Devi continuare a procedere seguendo la direzione della tua corsia.', 'Le parole ''accostarci sulla destra e fermarci'' sono la trappola. Fermarsi in un incrocio è sempre sbagliato e pericoloso.', 'Non fermarti all''incrocio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22727, 'Questa affermazione è falsa. Non devi mai fare retromarcia in un incrocio, nemmeno con prudenza. È una manovra estremamente pericolosa e vietata che può causare incidenti gravi.', 'La frase ''cerchiamo di retrocedere'' è la trappola. La retromarcia in incrocio è assolutamente proibita.', 'Mai fare retromarcia all''incrocio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22728, 'Questa affermazione è falsa. Non puoi aspettare al semaforo per cambiare corsia. Una volta che sei in una corsia di preselezione, devi seguire la direzione che quella corsia ti permette. Il semaforo regola il flusso del traffico, non ti permette di cambiare corsia all''interno dell''incrocio.', 'La trappola è ''attendere che la luce ci consenta di effettuare il cambio di corsia''. Il semaforo non dà il permesso di cambiare corsia in un incrocio.', 'Semaforo non cambia la tua corsia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22729, 'Anche se il pedone è fuori dalle strisce, tu come conducente hai sempre la responsabilità di evitare incidenti. È fondamentale ridurre la velocità e, se necessario, fermarsi per garantire la sua sicurezza e non investirlo.', 'La parola chiave è ''necessario''. Significa che è un obbligo, non una scelta. ''Non investirlo'' sottolinea la tua responsabilità principale.', 'Pedone = sempre massima attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22730, 'Rallentare è sempre una buona idea per la sicurezza. Usare il clacson è permesso solo per avvisare di un pericolo immediato, non per rimproverare il pedone. Un ''breve colpo'' è la chiave per un uso corretto.', 'Attenzione a ''breve colpo di clacson'' e ''in caso di pericolo immediato''. Il clacson non si usa per far spostare qualcuno, ma solo per evitare un incidente imminente.', 'Clacson: solo per pericolo, non per ''svegliare''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22731, 'Questa domanda ribadisce il concetto delle precedenti. La sicurezza è prioritaria. Devi essere pronto a fermarti subito (''tempestivamente'') se c''è il rischio di un incidente, anche se il pedone è in torto.', 'Anche qui ''necessario'' indica un obbligo. ''Tempestivamente'' significa ''subito, senza perdere tempo''.', 'Fermarsi è meglio che investire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22732, 'È FALSO. In un centro abitato, specialmente di notte, non si usano gli abbaglianti. Abbagliano gli altri conducenti e anche i pedoni, creando più pericolo invece di risolverlo. Devi usare gli anabbaglianti.', 'La trappola è ''abbaglianti accesi'' in ''centro abitato''. Gli abbaglianti sono per strade extraurbane senza illuminazione e senza altri veicoli di fronte.', 'Abbaglianti in città = MAI.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22733, 'È FALSO. Non puoi usare ''qualsiasi mezzo'' per richiamare l''attenzione del pedone. Alcuni mezzi (come gridare, fare gesti bruschi o usare il clacson in modo eccessivo) potrebbero spaventarlo o distrarlo, causando un pericolo maggiore. Il tuo obiettivo è la sicurezza, non forzare il pedone a darti la precedenza.', 'La frase ''con qualsiasi mezzo'' è la trappola. Non tutto è permesso. Anche ''perché ci dia la precedenza'' è sbagliato, non devi forzare la situazione.', 'Non forzare, previeni il pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22734, 'È FALSO. Questa è una risposta molto pericolosa! Anche se hai la precedenza, non puoi mai ''proseguire, senza curarci di lui''. La tua responsabilità come conducente è sempre quella di evitare incidenti. La precedenza non ti dà il diritto di mettere in pericolo nessuno.', 'Le parole ''senza curarci di lui'' e ''perché abbiamo la precedenza'' sono le trappole principali. Avere la precedenza non ti esonera dalla prudenza.', 'La precedenza non è un via libera per investire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22735, 'Quando incontri un corteo (come una sfilata o una processione) in città, devi fermarti sul lato destro della strada e aspettare che tutto il corteo sia passato e la strada sia di nuovo libera. È una questione di sicurezza e rispetto.', 'La parola ''deve'' indica un obbligo. Non è una scelta, ma una regola da seguire.', 'Corteo = Fermati e aspetta a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22736, 'È importante non suonare il clacson quando incontri un corteo. Farlo potrebbe disturbare le persone o creare confusione. Devi mantenere la calma e il silenzio.', 'Anche qui ''deve evitare'' sottolinea un obbligo. Non disturbare è la regola.', 'Corteo = No clacson.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22737, 'Se vedi un corteo e c''è una strada laterale che puoi prendere in modo sicuro e senza problemi, è una buona idea farlo per non intralciare e non aspettare troppo a lungo. Ma solo se la manovra è facile e sicura!', '''È opportuno'' significa ''è consigliabile'', non ''è obbligatorio''. Le condizioni ''se possibile'' e ''purché la manovra possa essere fatta in maniera corretta'' sono fondamentali: la sicurezza prima di tutto.', 'Corteo = Via laterale se sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22738, 'Prima di ripartire, devi essere sicuro che l''intero corteo sia passato. Non provare a passare in mezzo o subito dopo l''ultima persona, aspetta che la strada sia completamente libera.', '''Deve accertarsi'' e ''completamente'' sono parole chiave. Devi avere la certezza che non ci sia più nessuno del corteo sulla strada.', 'Corteo = Aspetta la fine completa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22739, 'Non è una buona idea fare retromarcia se questo blocca le altre auto o crea problemi al traffico. Cerca di gestire la situazione senza creare ulteriori ingorghi.', 'La condizione ''se ciò ostacola il flusso della circolazione'' è cruciale. Se la retromarcia crea problemi, non farla.', 'Corteo = No retro se blocchi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22740, 'Fare inversione di marcia (girare l''auto di 180 gradi) può essere pericoloso e bloccare il traffico. Se incontri un corteo, è meglio non farlo se questo crea intralcio.', 'Anche qui, ''qualora ciò costituisca intralcio alla circolazione'' è la condizione che rende la frase vera. L''obiettivo è non creare problemi al traffico.', 'Corteo = No inversione se intralci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22741, 'È FALSO. Non devi suonare il clacson per dire al corteo di sbrigarsi o di liberare la strada. Questo è maleducato e può causare confusione. Devi aspettare con pazienza.', 'La frase ''suonare discretamente onde avvertire il corteo di far cessare al più presto l''ingombro'' è la trappola. Non si deve mai ''avvertire'' un corteo in questo modo.', 'Corteo = Mai suonare per affrettare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22742, 'È FALSO. Non devi mai cercare di farti strada o interrompere un corteo, anche se lo fai con prudenza. È pericoloso e non permesso. Devi aspettare che passi.', 'La parte ''interrompendo il corteo'' è l''errore principale. ''Con estrema prudenza'' è un tentativo di rendere accettabile un''azione sbagliata.', 'Corteo = Mai interrompere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22743, 'È FALSO. Le luci di profondità (abbaglianti) sono molto forti e servono per vedere bene di notte su strade senza illuminazione, fuori città. Accenderle in un centro abitato, specialmente vicino a persone, è pericoloso perché acceca gli altri.', 'Le ''luci di profondità'' sono la parola chiave che rende la frase falsa. Non si usano in città.', 'Corteo = No abbaglianti in città.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22744, 'È FALSO. Avere fretta non ti dà il permesso di guidare in modo pericoloso o irrispettoso. Non puoi passare velocemente suonando il clacson in continuazione. Devi aspettare con calma.', 'Tutte le parti ''se proprio ha molta fretta'', ''passi rapidamente'' e ''usando il clacson in maniera continua'' sono sbagliate e indicano un comportamento scorretto.', 'Corteo = La fretta non è scusa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22745, 'È FALSO. Non puoi decidere di superare o interrompere un corteo in base a quanto è ''denso''. La regola è chiara: devi aspettare che passi completamente, senza cercare di farti strada.', 'Le azioni ''oltrepassandolo o interrompendolo'' sono sempre sbagliate quando si tratta di un corteo.', 'Corteo = Non si supera né interrompe.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22746, 'È FALSO. Non devi fare retromarcia rapidamente, e tantomeno fino al primo incrocio. Questo può essere molto pericoloso e creare un grande intralcio al traffico. La retromarcia va fatta solo se strettamente necessario e con la massima prudenza, senza creare pericoli.', 'Le parole ''rapidamente'' e ''fino al primo incrocio'' indicano una manovra eccessiva e potenzialmente pericolosa.', 'Corteo = No retromarcia rapida e lunga.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22747, 'Quando un veicolo davanti a te tarda a partire al semaforo verde, la cosa migliore da fare è aspettare con calma. Non sappiamo il motivo del ritardo, potrebbe essere una distrazione o un piccolo problema al veicolo. La pazienza aiuta a mantenere la calma nel traffico.', 'La parola chiave è ''pazientemente''. Indica un comportamento corretto e rispettoso degli altri utenti della strada.', 'Nel traffico, la pazienza è d''oro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22748, 'Suonare il clacson in modo insistente non serve a nulla, anzi, può solo innervosire gli altri automobilisti e creare una situazione spiacevole. Il clacson va usato solo in caso di pericolo immediato.', 'Le parole ''evitare di suonare il clacson con insistenza'' sono importanti. L''insistenza è il problema, non il clacson in sé (che ha altri usi).', 'Clacson: solo per pericolo, non per fretta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22749, 'Se vedi che l''automobilista davanti ha un problema (ad esempio, la macchina non parte) e puoi aiutarlo senza metterti in pericolo o bloccare ancora di più il traffico, è un gesto di civiltà e solidarietà. Ma sempre con prudenza!', 'La frase ''se c''è bisogno ed è possibile farlo senza pericolo'' è fondamentale. Non devi mai creare un nuovo pericolo per aiutare.', 'Aiuta se puoi, ma sempre in sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22750, 'Nei centri abitati, l''uso del clacson è vietato per sollecitare un veicolo a partire. Si può usare solo in caso di pericolo grave e immediato per evitare un incidente. Suonare per ''svegliare'' qualcuno non è permesso.', 'La parte ''vietato l''uso del segnalatore acustico per sollecitare'' è la chiave. Il motivo per cui si usa il clacson è importante.', 'Clacson in città: solo per emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22751, 'La sicurezza è sempre la cosa più importante. Superare un veicolo fermo in un incrocio, specialmente in città, con manovre azzardate è molto pericoloso e può causare incidenti gravi. Meglio aspettare.', 'La frase ''non si deve superarlo con manovre pericolose'' è chiara. ''Pericolose'' è la parola da ricordare.', 'Mai manovre pericolose, la sicurezza prima di tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22752, 'Questa affermazione è falsa. Come abbiamo già detto, suonare il clacson in modo insistente per sollecitare un veicolo a partire è sbagliato e vietato nei centri abitati. Crea solo rumore e nervosismo.', 'Le parole ''suonare insistentemente per sollecitare'' indicano un comportamento scorretto e vietato.', 'Clacson non è un campanello d''allarme per la partenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22753, 'Questa affermazione è falsa. Il problema è il veicolo davanti a te che non parte, non quelli che ti seguono. Suonare il clacson per richiamare l''attenzione di chi sta dietro non ha senso e crea solo confusione e rumore inutile.', 'La parte ''richiamare con il clacson l''attenzione degli automobilisti che seguono'' è il punto sbagliato. Il clacson non serve per comunicare con chi è dietro di te in questa situazione.', 'Clacson: per chi è davanti, non per chi è dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22754, 'Questa affermazione è falsa. Scendere dal veicolo in mezzo al traffico, specialmente a un incrocio, è estremamente pericoloso per te e per gli altri. Inoltre, bloccheresti ancora di più la circolazione. Non è un comportamento corretto o sicuro.', 'La frase ''tirare il freno a mano e scendere per cercare un agente'' descrive un''azione irresponsabile e molto pericolosa.', 'Resta in auto, non scendere nel traffico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22755, 'Questa affermazione è falsa. Invertire il senso di marcia (fare un''inversione a U) in un incrocio è una manovra estremamente pericolosa e vietata dal Codice della Strada. Può causare incidenti gravissimi. Non è mai una soluzione per sgombrare la carreggiata.', 'La parte ''anche invertendo il senso di marcia'' rende la risposta falsa. Questa manovra è proibita e pericolosissima in un incrocio.', 'Mai invertire il senso di marcia in incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22756, 'Quando un altro veicolo ti abbaglia con i fari di notte, devi guidare con attenzione (prudenza) e usare le tue luci anabbaglianti. Questo serve per non abbagliare a tua volta l''altro conducente e per mantenere una buona visibilità.', 'La frase ''procedere con prudenza'' è quasi sempre vera nei quiz, perché la prudenza è fondamentale alla guida. ''Usando le luci anabbaglianti'' è la corretta azione per non creare pericolo.', 'Abbagliato? Anabbaglianti e prudenza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22757, 'Se un veicolo ti abbaglia, non guardare direttamente i suoi fari. È meglio guardare un po'' a destra, verso il bordo della strada. Così eviti di essere accecato e puoi ancora vedere la strada con la visione laterale.', '''Distogliere lo sguardo'' significa non guardare direttamente. È un consiglio di sicurezza per evitare di perdere la vista per un momento.', 'Non guardare la luce, guarda il bordo strada!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22758, 'Quando sei abbagliato, vedi meno bene. Per questo, è importante rallentare per avere più tempo per reagire. Se la visibilità è davvero scarsa e non vedi nulla, fermarsi in sicurezza è la scelta migliore.', 'Le parole ''adeguatamente'' ed ''eventualmente'' sono importanti. Non devi fermarti per forza, ma solo se è necessario e in modo sicuro. Rallentare è sempre una buona idea.', 'Abbagliato? Rallenta, se serve fermati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22759, 'Essere abbagliati significa che la tua capacità di vedere è ridotta. Devi guidare tenendo conto di questo, quindi essere più attento e cauto in ogni tua azione al volante.', '''Tener conto della ridotta visibilità'' significa semplicemente che devi guidare con maggiore attenzione perché vedi meno bene del solito.', 'Meno vedi, più attento devi essere!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22760, 'Con la visibilità ridotta a causa dell''abbagliamento, fare manovre improvvise o cambiare corsia senza vedere bene può essere molto pericoloso. Potresti non vedere altri veicoli o ostacoli.', '''Evitare brusche manovre'' significa non fare movimenti improvvisi e pericolosi con il veicolo. La prudenza è la chiave.', 'Abbagliato? Niente mosse improvvise!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22761, 'Il retrovisore interno serve per vedere i veicoli che ti seguono. Se un veicolo ti abbaglia da davanti, il retrovisore interno non ti aiuta. La posizione antiabbagliante del retrovisore interno serve per i fari dei veicoli che sono dietro di te.', 'La trappola è ''retrovisore interno''. L''abbagliamento viene da ''davanti'', non da ''dietro''.', 'Abbagliato da davanti? Il retrovisore non ti aiuta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22762, 'Se un altro veicolo ti abbaglia, non devi fare lo stesso. Accendere i tuoi fari abbaglianti creerebbe una situazione ancora più pericolosa per entrambi i conducenti. Devi usare gli anabbaglianti.', '''A nostra volta con i fari abbaglianti'' è un comportamento sbagliato e pericoloso, che va contro le regole della buona condotta stradale.', 'Non abbagliare chi ti abbaglia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22763, 'Fermarsi ''immediatamente'' (di colpo) può essere molto pericoloso, specialmente su una strada extraurbana dove gli altri veicoli potrebbero non aspettarsi una frenata improvvisa. È meglio rallentare gradualmente e, se necessario, fermarsi in un luogo sicuro.', 'La parola ''immediatamente'' è la trappola. Non si deve mai fare una manovra improvvisa che possa creare pericolo.', 'Non fermarti di colpo, rallenta prima!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22764, 'Le trombe bitonali (il clacson) si usano solo per avvertire di un pericolo imminente. Non sono il modo corretto per segnalare a un altro conducente che ti sta abbagliando. Per questo si usano brevi lampeggi con i fari anabbaglianti.', '''Azionare le trombe bitonali'' è la parte sbagliata. Il clacson non è il segnale adatto per l''abbagliamento.', 'Non suonare il clacson, lampeggia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22765, 'Togliere le mani dal volante per coprirti gli occhi è molto pericoloso perché perdi il controllo del veicolo. È meglio distogliere lo sguardo o rallentare, ma le mani devono restare sul volante.', '''Ripararsi gli occhi con le mani'' è una manovra che ti fa perdere il controllo del veicolo, quindi è sbagliata.', 'Mani sul volante, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22766, 'Per guidare in sicurezza e non creare pericoli, devi sempre adattare il tuo modo di guidare. Questo significa considerare il tipo di veicolo che hai, le condizioni della strada (se è bagnata, stretta, ecc.) e quanto traffico c''è. È un principio fondamentale della guida sicura.', 'Non ci sono parole trappola evidenti. La frase ''guidare in modo adeguato'' è la chiave per capire che bisogna adattarsi.', 'Adatta la guida a tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22767, 'Per essere un buon guidatore e non causare problemi, non basta solo conoscere e seguire le regole della strada. È altrettanto importante usare il ''buonsenso'', cioè agire con intelligenza e prudenza in ogni situazione, anche quando non c''è una regola specifica.', 'La frase ''non solo... ma anche'' è importante. Significa che entrambe le cose (regole e buonsenso) sono necessarie, non solo una.', 'Regole + Buonsenso = Sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22768, 'Guidare bene significa seguire le regole, ma anche avere un ''senso civico''. Questo vuol dire essere rispettosi degli altri utenti della strada (pedoni, ciclisti, altri automobilisti), essere pazienti e non fare cose che possono dare fastidio o mettere in pericolo gli altri.', 'La parola ''unire'' indica che le due cose (regole e senso civico) devono andare insieme, non basta solo una.', 'Regole + Rispetto = Guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22769, 'Questa affermazione è falsa. Non basta solo rispettare i limiti massimi di velocità. A volte, anche se il limite massimo è alto, le condizioni della strada (pioggia, nebbia, traffico intenso) o del veicolo ti impongono di andare più piano per essere sicuro. ''Limitarsi'' significa fare solo quello, ed è sbagliato.', 'La parola ''limitarsi'' è la trappola. Suggerisce che basta fare solo una cosa, ma nella guida sicura bisogna considerare molti fattori.', 'Non solo il massimo! Adatta sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22770, 'Questa affermazione è falsa. Non puoi ''sempre'' andare a velocità costante. Devi cambiare la velocità in base a curve, incroci, pedoni, traffico, condizioni meteo. Mantenere una velocità costante in ogni situazione sarebbe pericoloso.', 'La parola ''sempre'' è la trappola. Le affermazioni assolute (sempre, mai, tutti) sono spesso false nei quiz di guida.', 'La velocità non è mai ''sempre'' costante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22771, 'Questa affermazione è falsa. Non devi ''comunque'' dare la precedenza a ''tutti'' i veicoli negli incroci. Esistono regole precise sulla precedenza (segnali, destra, ecc.). Se hai la precedenza, non devi darla a tutti, altrimenti creeresti confusione e pericolo.', 'Le parole ''comunque'' e ''a tutti i veicoli'' sono le trappole. Indicano un''azione indiscriminata e non basata sulle regole.', 'Segui le regole di precedenza, non dare a tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22772, 'Questa affermazione è falsa. Come per i limiti massimi, non basta ''limitarsi'' a osservare solo i limiti minimi di velocità. Devi considerare anche i limiti massimi e, soprattutto, le condizioni della strada, del traffico e del tuo veicolo per scegliere la velocità più sicura.', 'Anche qui, la parola ''limitarsi'' è la trappola. Non è sufficiente fare solo una cosa per guidare in sicurezza.', 'Non solo il minimo! Adatta sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22773, 'VERO. Quando c''è molto traffico, è importante guidare alla stessa velocità degli altri veicoli nella tua corsia. Questo aiuta il traffico a scorrere meglio e in modo più sicuro per tutti.', 'La frase ''il più possibile'' significa che devi cercare di farlo, ma non è una regola rigida al millimetro. L''importante è non creare rallentamenti o accelerazioni brusche rispetto agli altri.', 'Segui il flusso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22774, 'VERO. Anche se il traffico è lento o fermo, devi sempre mantenere una distanza di sicurezza dal veicolo davanti a te. Questo ti dà il tempo di frenare se l''altro veicolo si ferma improvvisamente o si muove all''indietro.', 'La parola ''sempre'' è fondamentale qui. La distanza di sicurezza è una regola che vale in ogni situazione, anche con traffico intenso.', 'Distanza = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22775, 'VERO. Il clacson serve per avvisare di un pericolo, non per ''spingere'' gli altri a muoversi più velocemente. Suonare il clacson nel traffico intenso crea solo rumore e stress, senza risolvere il problema.', 'La frase ''per invitare i veicoli che lo precedono ad accelerare'' indica un uso scorretto del clacson. Non è il suo scopo.', 'Clacson = pericolo, non fretta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22776, 'FALSO. Cambiare corsia continuamente nel traffico intenso è pericoloso e spesso inutile. Può causare incidenti, rallentare ancora di più il traffico e non ti fa arrivare prima. È meglio rimanere nella propria corsia.', 'Le parole ''ripetutamente'' e ''sempre quella più libera'' sono parole trappola. Indicano un comportamento aggressivo e non sicuro alla guida.', 'Cambi corsia = più rischio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22777, 'FALSO. Le corsie riservate ai veicoli di servizio pubblico (come autobus o taxi) sono vietate agli altri veicoli, anche se sono libere e c''è molto traffico. Non puoi usarle.', 'La frase ''se libere'' è la parola trappola. Anche se la corsia è libera, se è ''riservata'', non puoi usarla.', 'Riservata = vietata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22778, 'FALSO. Il lampeggio simultaneo di tutti gli indicatori di direzione (le ''quattro frecce'') si usa solo in caso di pericolo o di fermata temporanea per un''emergenza. Usarlo nel traffico normale può confondere gli altri conducenti, che potrebbero pensare a un problema o a una fermata improvvisa.', 'La frase ''fare uso del lampeggio simultaneo'' si riferisce a un segnale specifico che ha un significato preciso (pericolo/emergenza), non per segnalare il traffico intenso.', 'Quattro frecce = emergenza, non coda.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22779, 'Quando giri a destra, devi stare il più vicino possibile al bordo destro della strada. Questo ti aiuta a fare la curva in modo sicuro e a non intralciare gli altri veicoli che vanno dritto o che girano a sinistra.', 'La frase ''il più vicino possibile'' sottolinea che devi proprio accostarti al margine destro, non solo stare a destra in generale.', 'Svolta a destra? Stai a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22780, 'È fondamentale far sapere agli altri cosa intendi fare. Per questo, prima di girare a destra, devi accendere la freccia (l''indicatore di direzione) con un po'' di anticipo. Così, chi ti segue o chi viene di fronte sa che stai per svoltare.', 'Le parole ''in anticipo'' sono importanti: non accendere la freccia all''ultimo momento, ma prima di iniziare la manovra.', 'Prima la freccia, poi la svolta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22781, 'Se ci sono più corsie, devi scegliere quella giusta per girare a destra. Di solito è la corsia più a destra, o una corsia con un''indicazione specifica per la svolta a destra. Non puoi girare a destra da una corsia centrale o di sinistra.', 'La frase ''corsia che consente'' significa che devi usare la corsia apposita, non una qualsiasi.', 'Corsia giusta, svolta sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22782, 'Avvicinandoti al punto in cui devi girare, è importante rallentare. Questo ti permette di avere il controllo del veicolo, di vedere bene se ci sono pedoni o altri veicoli e di reagire in tempo a eventuali imprevisti.', 'La parola ''moderando'' significa rallentare, diminuire la velocità, non fermarsi di colpo.', 'Svolta lenta, svolta attenta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22783, 'Ogni manovra che fai alla guida deve essere fatta in modo sicuro, senza mettere in pericolo nessuno (pedoni, ciclisti, altri automobilisti) e senza bloccare il traffico inutilmente. Questa è una regola generale per tutte le manovre.', 'Le parole ''senza creare pericolo o intralcio'' sono una regola d''oro della guida: la sicurezza prima di tutto.', 'Guida sicuro, rispetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22784, 'Questa affermazione è falsa. Per girare a destra, devi stare il più vicino possibile al margine destro della strada, non a quello sinistro. Se ti tieni a sinistra per girare a destra, tagli la strada agli altri e crei una situazione molto pericolosa.', 'La parola ''sinistro'' è la parola trappola. Per la svolta a destra, devi stare a destra.', 'Destra = destra, non sinistra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22785, 'Questa affermazione è falsa. Per girare a destra, devi stare nella corsia più a destra o in quella indicata per la svolta a destra. Stare nella corsia di sinistra per girare a destra è sbagliato e pericoloso, perché incroceresti la traiettoria degli altri veicoli.', 'La frase ''corsia di sinistra'' è la trappola. Per girare a destra, devi usare la corsia di destra.', 'Destra non è sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22786, 'Questa affermazione è falsa. Anche se hai il semaforo verde per svoltare a destra, devi SEMPRE dare la precedenza ai pedoni che stanno attraversando la strada in cui stai per entrare. I pedoni hanno quasi sempre la precedenza, specialmente quando attraversano sulle strisce.', 'Le parole ''senza mai dare la precedenza'' e ''se il semaforo ha la luce verde accesa'' sono le trappole. Il ''mai'' rende l''affermazione falsa, perché i pedoni hanno la precedenza anche con il tuo verde.', 'Pedoni sempre prima, anche col verde.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22787, 'Questa affermazione è falsa. Girare attorno a una colonnina o un''isola al centro dell''incrocio è una manovra che si fa per svoltare a SINISTRA (o per fare un''inversione di marcia, in alcuni casi), non a destra. Per la svolta a destra, devi stare vicino al bordo destro.', 'La frase ''girando attorno alla colonnina luminosa'' descrive una manovra per la svolta a sinistra, non a destra.', 'Destra è stretta, non larga.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22788, 'Questa affermazione è falsa. Avvicinarsi al centro dell''incrocio è la manovra corretta per svoltare a SINISTRA. Per svoltare a destra, invece, devi tenerti il più vicino possibile al margine destro della carreggiata.', 'La frase ''vicinanza del centro dell''incrocio'' è la trappola. Questa posizione è per la svolta a sinistra.', 'Destra = bordo, Sinistra = centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22789, 'Su una strada con tre corsie e traffico in entrambi i sensi (doppio senso di marcia), la corsia centrale è speciale. Non si usa per guidare normalmente, ma solo per superare un altro veicolo. Dopo il sorpasso, devi tornare subito nella corsia di destra.', 'La parola ''solo'' è importante. Significa che non puoi usare la corsia centrale per altri scopi, come guidare a lungo.', 'Corsia centrale a doppio senso = solo per sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22790, 'Su una strada con due corsie e traffico in entrambi i sensi (doppio senso di marcia), la corsia di sinistra, rispetto alla tua direzione, serve solo per superare. Dopo aver superato, devi rientrare nella corsia di destra.', 'Anche qui, ''solo'' è la parola chiave. Indica che l''uso della corsia di sinistra è limitato al sorpasso.', 'Due corsie, doppio senso: sinistra = sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22791, 'Le strade extraurbane principali sono strade veloci e importanti. Per la tua sicurezza e quella degli altri, non puoi fermarti o parcheggiare dove vuoi. La sosta è permessa solo in aree speciali, come le piazzole di sosta o le aree di servizio, che sono fatte apposta per questo.', 'La frase ''solo nelle apposite aree'' è fondamentale. Significa che non è consentita la sosta in altri punti della strada o della banchina.', 'Extraurbana principale: sosta solo in aree dedicate.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22792, 'Una strada a due carreggiate separate significa che ci sono due strade distinte, una per andare in una direzione e l''altra per tornare. Su ogni singola carreggiata, tu devi usare la corsia più a destra per guidare normalmente e le corsie di sinistra per superare. Non si usa un''intera carreggiata solo per il sorpasso.', 'La trappola è ''quella di sinistra per il sorpasso''. Non si intende la corsia di sinistra della tua carreggiata, ma l''intera carreggiata di sinistra, il che è sbagliato.', 'Carreggiate separate: ogni carreggiata ha le sue corsie per marcia/sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22793, 'Guidare ''per file parallele'' significa andare affiancati, come in una gara. Questo è permesso solo in alcune situazioni, ad esempio in città con molte corsie nella stessa direzione o quando c''è molto traffico. Su una strada con solo due corsie e doppio senso di marcia, devi sempre tenere la destra e usare la corsia di sinistra solo per superare, non per guidare affiancato a un altro veicolo.', 'La frase ''si può marciare per file parallele'' è la parte da cui diffidare. Su questo tipo di strada non è consentito.', 'Due corsie, doppio senso = no file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22794, 'Una strada con quattro carreggiate separate è molto rara. Anche se esistesse, ogni carreggiata avrebbe le sue corsie: quelle di destra per la marcia normale e quelle di sinistra per il sorpasso. Non è corretto dire che intere carreggiate (quelle centrali) sono riservate solo al sorpasso. Il sorpasso si fa usando le corsie di sinistra all''interno della propria carreggiata.', 'La trappola è ''quelle centrali sono riservate al sorpasso''. Non si riservano intere carreggiate al sorpasso, ma solo le corsie più a sinistra all''interno di una carreggiata.', 'Carreggiate separate: ogni carreggiata ha le sue regole, non si riserva un''intera carreggiata al sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22795, 'Quando vuoi cambiare corsia, devi sempre guardare avanti e assicurarti che ci sia abbastanza spazio libero nella corsia dove vuoi andare. Questo serve per non dover frenare all''improvviso o creare pericolo per chi ti precede.', 'La frase chiave è ''davanti per un tratto sufficiente''. Significa che devi avere spazio libero non solo subito davanti, ma per un pezzo di strada, per poterti inserire in sicurezza.', 'Davanti libero, cambio sicuro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22796, 'Oltre a guardare avanti, è fondamentale controllare anche dietro di te. Devi essere sicuro che non stia arrivando nessun veicolo troppo velocemente o troppo vicino nella corsia che vuoi occupare, per evitare collisioni.', 'La frase chiave è ''dietro per un tratto sufficiente''. Ricorda che non basta guardare solo davanti, ma anche dietro per un pezzo di strada.', 'Dietro libero, cambio sicuro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22797, 'Se cambi corsia per sorpassare, devi controllare che il veicolo davanti a te non abbia già messo la freccia per fare la stessa manovra. Se lo facesse, potreste scontrarvi.', 'La parte importante è ''non abbia segnalato l''inizio della stessa manovra''. Questo ti avvisa di un possibile conflitto di intenzioni.', 'Sorpasso? Occhio a chi ti precede!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22798, 'È obbligatorio usare l''indicatore di direzione (la freccia) sempre prima di cambiare corsia. Questo avvisa gli altri conducenti delle tue intenzioni e li aiuta a capire cosa farai.', 'Le parole importanti sono ''in anticipo'' e ''tramite l''indicatore di direzione''. Non all''ultimo momento e non con altri mezzi.', 'Freccia sempre prima!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22799, 'Quando cambi corsia, la tua manovra non deve mai costringere gli altri veicoli a frenare bruscamente o a fare manovre pericolose. La sicurezza è la cosa più importante.', 'La frase chiave è ''non deve creare intralcio o pericolo''. Significa che non devi disturbare o mettere a rischio gli altri.', 'Mai ostacolare, mai mettere in pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22800, 'Questa affermazione è FALSA. Devi sempre usare l''indicatore di direzione quando cambi corsia, anche se la strada ti sembra completamente libera. È una regola per comunicare le tue intenzioni, sempre.', 'La parola ''non'' rende la frase una trappola. La frase ''se la strada è libera'' è un tentativo di farti pensare che non sia necessario, ma è sempre obbligatorio.', 'Strada libera o no, la freccia va!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22801, 'Questa affermazione è FALSA. Per segnalare il cambio di corsia si usa l''indicatore di direzione (la freccia), non il clacson. Il clacson si usa solo per avvisare di un pericolo immediato.', 'La trappola è ''avvisatore acustico (clacson o trombe)''. Questo è il metodo sbagliato per segnalare un cambio di corsia.', 'Cambio corsia? Freccia, non clacson!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22802, 'Questa affermazione è FALSA. Se le corsie sono separate da una striscia continua, non puoi cambiare corsia! Puoi farlo solo se la striscia è discontinua (tratteggiata).', 'La parola ''continua'' è la chiave. Una striscia continua significa divieto di superare o cambiare corsia.', 'Continua? Non si passa!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22803, 'Quando devi girare a sinistra in una strada dove le macchine vanno in due direzioni (doppio senso), è corretto spostarsi verso il centro della strada. Questo ti aiuta a fare la curva in modo sicuro senza intralciare chi viene di fronte o chi gira a destra.', 'La frase ''avvicinarsi al centro'' significa che devi posizionarti nella parte centrale della tua corsia, non troppo a destra e non troppo a sinistra.', 'Svolta a sinistra = centro strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22804, 'Per svoltare a sinistra in un incrocio a doppio senso, di solito devi posizionarti nella parte sinistra dell''incrocio (rispetto al tuo senso di marcia). Questo ti permette di fare una curva ampia e sicura. Se ci sono segnali diversi (come frecce a terra), devi seguire quelli.', 'La parola ''di norma'' significa ''solitamente'', ''normalmente'', ma ricorda che ci possono essere eccezioni. ''Salvo diversa segnalazione'' è importante: se ci sono cartelli o linee diverse, devi seguirli.', 'Svolta a sinistra = area sinistra incrocio (se non ci sono segnali diversi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22805, 'Se l''incrocio è una rotatoria (cioè c''è il segnale di rotatoria), per girare a sinistra devi fare il giro intorno al centro della rotatoria. Non devi tagliare la rotatoria, ma seguirne il percorso.', 'La condizione ''se c''è il segnale di rotatoria'' è fondamentale. Senza questo segnale, la manovra è diversa.', 'Rotatoria = giro intorno al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22806, 'Quando giri a sinistra, devi sempre dare la precedenza ai veicoli che arrivano dalla tua destra. Questa è una regola generale degli incroci. Ricorda che i segnali stradali (come Stop o Dare Precedenza) o i semafori possono cambiare questa regola.', 'La frase ''salvo diversa segnalazione'' è cruciale: significa che se ci sono segnali specifici, devi rispettare quelli, altrimenti vale la regola della precedenza a destra.', 'Svolta a sinistra = precedenza a destra (se non ci sono segnali).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22807, 'È FALSO. Non devi spostarti sul margine sinistro della carreggiata. Se lo facessi, invaderesti la corsia di chi viene in senso opposto, creando una situazione molto pericolosa. Devi avvicinarti al centro della carreggiata, non al margine sinistro.', 'La parola ''margine sinistro'' è la trappola. Il margine sinistro è la parte più a sinistra della strada, che è per il traffico che viene in senso opposto.', 'Svolta a sinistra = centro, non margine sinistro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22808, 'È FALSO. Non devi fare la manovra velocemente. Le manovre agli incroci devono essere fatte con molta prudenza e a velocità moderata. Questo ti dà il tempo di vedere gli altri veicoli e di reagire in caso di pericolo. La velocità aumenta solo il rischio.', 'La parola ''velocemente'' è la trappola. Le manovre pericolose o complesse non vanno mai fatte velocemente.', 'Incrocio = prudenza, non velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22809, 'È FALSO. Per svoltare a sinistra non devi occupare il lato destro dell''incrocio. Questo è sbagliato e molto pericoloso. Il lato destro è per chi gira a destra o va dritto. Tu devi posizionarti verso il centro della carreggiata e poi nell''area sinistra dell''incrocio per fare la curva.', 'La frase ''lato destro dell''incrocio'' è la trappola. Se giri a sinistra, non puoi stare a destra.', 'Svolta a sinistra = non a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22810, 'È FALSO. La regola generale è dare la precedenza a chi viene da destra, non da sinistra. Quando giri a sinistra, devi dare la precedenza anche a chi viene di fronte e va dritto o gira a destra, ma la precedenza ''di base'' è a destra.', 'La frase ''da sinistra'' è la trappola. La precedenza di norma è a destra.', 'Precedenza = a destra (non a sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22811, 'È FALSO. Suonare il clacson non aumenta la sicurezza in un incrocio. Il clacson si usa solo in caso di pericolo immediato o fuori dai centri abitati per avvisare di un sorpasso. Usarlo senza motivo è vietato e può confondere gli altri conducenti.', 'Le frasi ''suonare il clacson'' e ''maggior sicurezza'' sono la trappola. Il clacson non è uno strumento per aumentare la sicurezza nelle manovre normali.', 'Clacson = solo per pericolo, non per sicurezza normale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22812, 'La regola generale del Codice della Strada dice che i veicoli devono sempre circolare sulla parte destra della strada, il più vicino possibile al bordo destro. Questo serve per garantire la sicurezza e la fluidità del traffico.', 'La frase ''di norma'' significa ''normalmente'', ''solitamente''. Indica la regola generale, che vale quasi sempre, salvo eccezioni specifiche (come il sorpasso).', 'La destra è la regola base!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22813, 'Se la strada ha due carreggiate separate (cioè due strade distinte affiancate), ognuna è per un senso di marcia. Tu devi usare quella che si trova alla tua destra, cioè quella per la tua direzione.', 'Anche qui ''di norma'' indica la regola generale. ''Rispetto alla propria direzione di marcia'' è importante: significa che devi considerare la carreggiata che è alla tua destra mentre vai avanti.', 'La tua destra è la tua carreggiata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22814, 'In una strada con tre carreggiate separate, di solito due sono per un senso di marcia e una per l''altro, oppure la centrale è promiscua. Se la carreggiata centrale è destinata anche al tuo senso di marcia, puoi usarla, ma la regola generale è comunque tenere la destra. Quindi, puoi usare la più a destra o quella centrale se è per la tua direzione.', 'La parola ''di norma'' conferma che è la regola generale. ''Centrale o su quella di destra'' indica che entrambe possono essere usate per la tua direzione, ma sempre preferendo la destra.', 'Anche la centrale può essere tua (se per la tua direzione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22815, 'In una strada a doppio senso con due corsie (una per senso di marcia), devi stare nella corsia di destra, che è la tua. La corsia di sinistra è per chi viene dall''altra parte, ma puoi usarla per sorpassare, solo se è sicuro e la segnaletica lo permette.', 'La parte ''impegnando solo quella di sinistra per il sorpasso'' si riferisce alla corsia del senso opposto, che puoi usare temporaneamente per il sorpasso, ma con molta attenzione.', 'Stai a destra, sorpassa a sinistra (se puoi e è sicuro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22816, 'Anche se ci sono molte corsie per il tuo senso di marcia, la regola è sempre quella di usare la corsia più a destra. Le altre corsie (centrale e sinistra) sono per il sorpasso o per i veicoli che vanno più veloci, ma non per la marcia normale.', '''Di norma'' e ''più libera a destra'' rafforzano il concetto che devi tenere la destra e lasciare le altre corsie libere se non stai sorpassando.', 'La destra è la tua corsia base.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22817, 'Normalmente non si circola per file parallele. Ma in situazioni di traffico intenso, specialmente vicino a incroci dove ci sono semafori o vigili che regolano il traffico, è permesso formare più file di veicoli per far scorrere meglio la circolazione.', '''In vicinanza di incroci regolati da vigili o da semafori'' è la condizione specifica che permette di circolare per file parallele. Senza queste condizioni, non è permesso.', 'Incrocio regolato = file parallele ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22818, 'In una strada a doppio senso con tre corsie, la corsia centrale non è per la ''marcia normale''. È una corsia ''promiscua'', cioè può essere usata da entrambi i sensi di marcia, ma solo per sorpassare o per svoltare a sinistra, non per andare dritto normalmente.', 'La frase ''marcia normale'' è la parola chiave. La corsia centrale non è per questo scopo. È solo per manovre specifiche.', 'Centrale = solo sorpasso/svolta, non marcia normale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22819, 'Circolare per file parallele è permesso solo in casi speciali (come incroci regolati o traffico intenso su strade con più corsie per lo stesso senso di marcia). Una strada a doppio senso con tre corsie (una per senso + una centrale promiscua) non rientra in queste condizioni per la circolazione normale.', '''Circolare per file parallele'' non è la condizione normale per questo tipo di strada. Non ci sono abbastanza corsie per lo stesso senso di marcia per farlo in sicurezza.', 'File parallele solo in casi speciali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22820, 'Per svoltare a sinistra, devi avvicinarti al centro della strada (o al margine sinistro della tua metà carreggiata se a doppio senso). Tenerti sul margine destro è la manovra corretta per svoltare a destra, non a sinistra.', 'La parola ''margine destro'' è l''errore. Per svoltare a sinistra, devi spostarti verso il centro o la sinistra della tua corsia.', 'Svolta a sinistra = verso il centro/sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22821, 'Anche se la strada è completamente vuota, devi sempre rispettare la regola di tenere la destra. Circolare al centro della carreggiata è sbagliato e può essere pericoloso, perché non rispetti la posizione corretta sulla strada.', '''Al centro della carreggiata'' e ''quando la strada è libera'' non sono giustificazioni per non tenere la destra. La regola vale sempre.', 'Destra sempre, anche se vuota.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22822, 'Una strada a doppio senso con due corsie significa che c''è solo una corsia per ogni direzione di marcia. Non ci sono le condizioni per circolare per file parallele, che richiede almeno due corsie per lo stesso senso di marcia e condizioni specifiche (come incroci regolati o traffico intenso).', '''Circolare per file parallele'' non è applicabile a una strada con una sola corsia per senso di marcia.', 'Una corsia per senso = no file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22823, 'Le corsie riservate (ad esempio, agli autobus o ai taxi) sono dedicate solo a quei veicoli specifici. Non puoi usarle, anche se c''è molto traffico, a meno che non ci sia un segnale che ti autorizza in particolari condizioni (ma sono casi rari e specifici).', 'La frase ''utilizzando le corsie riservate'' è l''errore. Le corsie riservate sono vietate agli altri veicoli.', 'Corsie riservate = solo per chi è autorizzato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22824, 'È VERO. Tutti i veicoli, anche quelli senza motore come le biciclette, devono circolare il più possibile vicino al margine destro della carreggiata. Questo serve per garantire la sicurezza e non ostacolare gli altri veicoli.', 'La frase ''il più possibile vicino'' indica che è una regola generale da seguire con attenzione.', 'Destra è sempre la regola per tutti i veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22825, 'È VERO. Anche chi conduce animali (ad esempio, un gregge) deve tenerli il più possibile vicino al margine destro della carreggiata. Questo aiuta a mantenere la strada sicura per tutti e a non bloccare il traffico.', 'Anche qui, ''il più possibile vicino'' sottolinea l''importanza di aderire alla destra per la sicurezza.', 'Animali a destra, come i veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22826, 'È VERO. Quando incontri un altro veicolo che viene dalla direzione opposta su una strada a doppio senso, devi spostarti il più a destra possibile. Questo evita collisioni e lascia spazio sufficiente per il passaggio sicuro.', '''Incrociando altri veicoli'' significa che stai incontrando veicoli che vengono nella direzione opposta.', 'Incontro = destra stretta per sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22827, 'È VERO. Su strade a doppio senso con più corsie, la regola generale è di usare la corsia di destra per la marcia normale. La corsia di sinistra si usa solo per effettuare un sorpasso e poi si rientra a destra.', 'La parola ''solo'' è importante: la corsia di sinistra ha uno scopo specifico, il sorpasso.', 'Destra per marcia, sinistra per sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22828, 'È VERO. Quando si sale su un dosso, la visibilità è ridotta. Per questo, è fondamentale tenersi il più possibile vicino al margine destro della carreggiata per evitare di invadere la corsia opposta e prevenire incidenti.', '''Tratto in salita di un dosso'' indica una situazione di pericolo potenziale per la visibilità limitata.', 'Dosso = destra stretta, massima prudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22829, 'È FALSO. Anche su una strada a senso unico, la regola generale è di tenere la destra. Non ci si sposta al margine sinistro per percorrere una curva a sinistra, a meno che non si debba svoltare a sinistra in un incrocio.', 'La parola ''sinistro'' è la trappola. La regola generale di marcia è sempre a destra.', 'Curva = destra, sempre! (Tranne per svolta a sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22830, 'È FALSO. Indipendentemente dal fatto che la strada abbia due carreggiate separate o meno, la regola di base è sempre quella di tenere la destra. Circolare vicino al margine sinistro è sbagliato e pericoloso.', 'Anche qui, ''margine sinistro'' è la parola trappola. La regola è sempre la destra.', 'Dosso o no, sempre a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22831, 'È FALSO. Anche se la striscia è discontinua (e quindi permetterebbe il sorpasso), in curva è molto pericoloso e sconsigliato oltrepassarla per ''marciare'' nell''altra corsia, anche se sembra libera. La sicurezza in curva è prioritaria.', '''Oltrepassando la striscia discontinua'' in curva è la trappola. Anche se la striscia lo permette, in curva è pericoloso e non si deve fare senza motivo valido (es. sorpasso con ottima visibilità, ma comunque sconsigliato).', 'Curva = prudenza, non invadere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22832, 'È FALSO. Se devi svoltare a sinistra, devi spostarti verso il centro della carreggiata (o il margine sinistro se la strada è a senso unico) per prepararti alla svolta. Tenersi al margine destro ti impedirebbe di svoltare correttamente e sarebbe pericoloso.', '''Margine destro'' è la trappola. Per svoltare a sinistra, ci si sposta verso sinistra.', 'Svolta a sinistra = spostati a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22833, 'È FALSO. Tutti i veicoli, inclusi i filobus, devono circolare il più possibile vicino al margine destro della carreggiata. Non c''è nessuna eccezione che li autorizzi a circolare a sinistra di norma.', '''Margine sinistro'' è la parola trappola. ''Di norma'' rafforza la regola generale, che è la destra.', 'Filobus come tutti: a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22834, 'È FALSO. Anche in caso di traffico intenso, i ciclomotori (e tutti i veicoli) devono rispettare le regole di circolazione. La corsia di sinistra è per il sorpasso, non per la marcia normale, anche se c''è molto traffico.', '''Possono circolare sulla corsia di sinistra'' è la trappola. Il traffico intenso non cambia le regole di base.', 'Ciclomotori a destra, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22835, 'È FALSO. Questa domanda ripete il concetto precedente. I ciclomotori, come tutti i veicoli, devono tenere la destra. Il traffico intenso non è una giustificazione per usare la corsia di sinistra per la marcia normale.', '''Possono circolare sulla corsia di sinistra'' è la trappola. La regola non cambia con il traffico.', 'Ciclomotori a destra, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22836, 'È FALSO. Le piste ciclabili sono riservate esclusivamente alle biciclette e, in alcuni casi, ai pedoni. Ciclomotori e motocicli non possono mai circolare sulle piste ciclabili, indipendentemente dal traffico o dalla velocità. È vietato e molto pericoloso.', '''Possono circolare sulla pista ciclabile'' è la trappola principale. ''Se non superano la velocità di 20 km/h'' è un dettaglio fuorviante.', 'Pista ciclabile = solo bici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22837, 'È FALSO. Le corsie di emergenza sono destinate solo a situazioni di vera emergenza (come un guasto al veicolo, un malore o per i mezzi di soccorso). Non possono essere usate dai motocicli o da altri veicoli per evitare il traffico.', '''Possono circolare sulle corsie di emergenza'' è la trappola. Le corsie di emergenza non sono per evitare il traffico.', 'Corsia emergenza = solo emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22838, 'Quando cambi corsia, devi fare attenzione a non creare problemi o pericoli agli altri veicoli che sono già in quella corsia. La sicurezza è la cosa più importante.', 'La frase ''non si deve creare intralcio o pericolo'' è fondamentale. Significa che la tua manovra non deve disturbare o mettere a rischio nessuno.', 'Cambia corsia senza disturbare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22839, 'Prima di cambiare corsia, devi sempre usare l''indicatore di direzione (la freccia) per far sapere agli altri cosa intendi fare. Questo aiuta tutti a guidare in sicurezza.', 'La parola ''in anticipo'' è importante. Non devi segnalare all''ultimo momento, ma un po'' prima, per dare tempo agli altri di capire e reagire.', 'Segnala sempre prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22840, 'Prima di spostarti, devi guardare bene e assicurarti che la corsia in cui vuoi andare sia libera per un tratto abbastanza lungo. Non basta che sia libera solo per un attimo.', 'La frase ''libera davanti per un tratto sufficiente'' è la chiave. Non devi solo vedere uno spazio, ma uno spazio che ti permetta di entrare in sicurezza senza frenare bruscamente o tagliare la strada.', 'Spazio libero è sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22841, 'Puoi cambiare corsia solo se la linea che le divide è tratteggiata (discontinua). Se la linea è continua, non puoi superarla e quindi non puoi cambiare corsia.', 'La parola ''tratteggiata'' è la parola chiave. Ricorda che le linee continue non si possono mai superare.', 'Solo striscia tratteggiata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22842, 'Per segnalare che vuoi cambiare corsia, devi usare l''indicatore di direzione, cioè la freccia. È l''unico modo corretto per comunicare la tua intenzione agli altri.', 'L''espressione ''indicatore di direzione'' è il termine tecnico per la ''freccia''. È obbligatorio usarlo.', 'Freccia obbligatoria.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22843, 'È fondamentale controllare bene, anche usando gli specchietti e girando un po'' la testa (controllo dell''angolo cieco), che non ci siano altri veicoli che stanno arrivando nella corsia dove vuoi andare.', 'La frase ''non stiano arrivando altri veicoli'' sottolinea l''importanza di un controllo accurato, specialmente per i veicoli che potrebbero essere nel tuo angolo cieco.', 'Guarda bene, nessuno dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22844, 'Non è mai permesso guidare ''a cavallo'' delle strisce di corsia, né in città né fuori. È pericoloso e non ti permette di mantenere una posizione chiara sulla strada.', 'La frase ''a cavallo delle strisce di corsia'' è la trappola. Significa guidare con le ruote su due corsie diverse, cosa sempre vietata.', 'Mai sulle strisce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22845, 'L''uso dell''indicatore di direzione (la freccia) è sempre obbligatorio quando cambi corsia o direzione, anche se le strisce sono tratteggiate. Non è mai ''facoltativo''.', 'La parola ''facoltativo'' è la trappola. L''uso della freccia è sempre un obbligo per la sicurezza e la comunicazione con gli altri utenti della strada.', 'Freccia sempre, non facoltativa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22846, 'Ogni volta che cambi corsia, sia a destra che a sinistra, devi sempre fare molta attenzione. Potrebbero esserci veicoli, moto o biciclette che non vedi subito.', 'La frase ''non occorre alcuna particolare attenzione'' è la trappola. L''attenzione è sempre necessaria, indipendentemente dalla direzione del cambio di corsia.', 'Attenzione sempre, anche a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22847, 'Vicino agli incroci, spesso è vietato cambiare corsia, specialmente se ci sono strisce continue. La parola ''sempre'' rende questa affermazione falsa, perché ci sono molte situazioni in cui non si può fare.', 'La parola ''sempre'' è la trappola. Vicino agli incroci, il cambio di corsia è spesso vietato o comunque molto limitato per motivi di sicurezza.', 'Incrocio = no cambio corsia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22848, 'Quando sorpassi, di solito devi aumentare la velocità per completare la manovra il più rapidamente e in sicurezza possibile. Ridurre la velocità sarebbe pericoloso e allungherebbe il tempo del sorpasso.', 'La frase ''ridurre la velocità'' è la trappola. Per sorpassare, si aumenta la velocità per superare l''altro veicolo velocemente.', 'Sorpasso = velocità su.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22849, 'Quando vuoi cambiare direzione (svoltare a destra o a sinistra), devi sempre accendere la freccia (l''indicatore di direzione) un po'' prima di iniziare la manovra. Questo serve per far capire agli altri guidatori cosa hai intenzione di fare, così possono prepararsi e guidare in sicurezza.', 'La parola chiave è ''in anticipo''. Non devi accendere la freccia all''ultimo momento, ma prima di iniziare a svoltare.', 'Freccia = prima di svoltare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22850, 'Quando giri a sinistra in un incrocio, di solito devi passare ''dietro'' il centro dell''incrocio. Questo significa che il centro dell''incrocio deve rimanere alla tua destra mentre giri. In questo modo, tu e chi viene dalla direzione opposta e gira a sinistra non vi incrociate al centro, evitando collisioni.', 'La frase ''di norma'' significa ''normalmente'' o ''solitamente''. Ci sono poche eccezioni, ma questa è la regola generale. ''Come i veicoli in figura'' si riferisce all''immagine che mostra questa manovra corretta.', 'Svolta a sinistra = centro a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22851, 'Se sei su una strada a senso unico (dove tutte le auto vanno nella stessa direzione) e vuoi svoltare a sinistra, devi spostarti il più possibile sul lato sinistro della strada. Questo permette a chi va dritto o gira a destra di passare senza problemi.', 'La condizione importante è ''su strada a senso unico''. Se la strada fosse a doppio senso, la regola sarebbe diversa.', 'Senso unico + sinistra = margine sinistro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22852, 'Quando fai un''inversione di marcia (cioè un ''testa-coda'' per tornare indietro nella direzione da cui sei venuto), devi tenere l''indicatore di direzione (la freccia) acceso per tutto il tempo della manovra. Questo è importante per segnalare chiaramente agli altri guidatori la tua intenzione, dall''inizio alla fine.', 'La frase ''per l''intera durata della manovra'' è fondamentale. Non devi spegnere la freccia a metà manovra.', 'Manovra lunga = freccia sempre accesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22853, 'Questa domanda si riferisce a un''immagine che non vediamo, ma se la risposta è FALSO, significa che il veicolo non può svoltare a destra. Questo succede se c''è un segnale di ''Divieto di svolta a destra'' o se il veicolo si trova in una corsia che permette solo di andare dritto o svoltare a sinistra.', 'La parola ''può'' indica una possibilità o un permesso. Se la risposta è FALSO, significa che non c''è il permesso.', 'Segnali = comandi, non desideri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22854, 'Questa affermazione è sbagliata. Per svoltare a sinistra, non devi ''girare intorno'' al centro dell''incrocio. Come abbiamo visto nella domanda 22850, il centro dell''incrocio deve rimanere alla tua destra. ''Girare intorno'' significherebbe fare un giro troppo largo e pericoloso.', 'La frase ''girare intorno al centro dell''incrocio'' è la parte sbagliata. È l''opposto della regola corretta.', 'Sinistra = non girare intorno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22855, 'Quando vuoi cambiare direzione, è obbligatorio usare gli indicatori di direzione (le frecce), non il clacson. Il clacson (segnalazioni acustiche) si usa solo in caso di pericolo immediato per avvisare gli altri, non per indicare una svolta. Usare il clacson senza motivo è vietato.', 'Le parole ''obbligatorio'' e ''segnalazioni acustiche'' sono le trappole. Non è obbligatorio usare il clacson per svoltare, anzi, è sbagliato.', 'Cambiare direzione = freccia, non clacson.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22856, 'Se sei su una strada con tre corsie nella tua direzione, per svoltare a sinistra devi usare la corsia più a sinistra. La corsia centrale è di solito per andare dritto o per sorpassare, non per svoltare a sinistra. La corsia più a destra è per andare dritto o svoltare a destra.', 'La trappola è ''corsia centrale''. Per svoltare a sinistra, si usa la corsia più a sinistra.', 'Tre corsie + sinistra = corsia più a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22857, 'Quando giri a sinistra in una strada a doppio senso, devi entrare nella nuova strada rispettando il senso di marcia. Non puoi andare contro il traffico (contromano) perché sarebbe molto pericoloso e vietato.', 'La parola ''contromano'' significa andare nella direzione sbagliata, contro il flusso del traffico. È una manovra sempre vietata e pericolosa.', 'Svolta a sinistra: entra sempre nel tuo senso di marcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22858, 'Quando giri a sinistra in un incrocio a doppio senso, devi fare una curva ampia. Questo significa che il centro dell''incrocio (il punto centrale) deve rimanere alla tua destra mentre giri. In questo modo, non tagli la strada a chi viene di fronte e la manovra è più sicura.', '''Di norma'' significa ''solitamente'', ''normalmente''. Questa è la regola generale, a meno che non ci siano segnali specifici o isole di traffico che indicano un percorso diverso. ''Lasciare il centro dell''incrocio alla nostra destra'' significa fare una svolta ampia, non stretta.', 'Svolta a sinistra: centro incrocio sempre a destra (curva ampia).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22859, 'Se la strada ha più corsie, devi scegliere quella giusta per girare a sinistra. Non puoi girare a sinistra da una corsia che serve per andare dritto o a destra, perché creeresti confusione e pericolo per gli altri veicoli.', '''Inserirsi nelle corsie che consentono'' significa scegliere la corsia corretta, quella che ha la freccia per svoltare a sinistra (se presente) o che è la più a sinistra tra quelle disponibili per la svolta.', 'Svolta a sinistra: usa la corsia giusta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22860, 'La linea continua di mezzeria non si può mai superare. Per svoltare a sinistra, devi avvicinarti alla linea di mezzeria, ma rimanere sempre alla sua destra (nella tua corsia). Superarla significa invadere la corsia opposta, il che è vietato e molto pericoloso.', 'La frase ''spostarsi a sinistra della linea continua di mezzeria'' è la parte trappola. Una linea continua non può mai essere superata o calpestata.', 'Linea continua: mai superare, mai a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22861, 'Per svoltare a sinistra, devi avvicinarti il più possibile al centro della strada (alla linea di mezzeria, se c''è). Tenersi lungo il margine destro della carreggiata è la posizione corretta per svoltare a destra, non a sinistra.', 'La frase ''margine destro della carreggiata'' è la trappola. Questa posizione è per la svolta a destra. Per la svolta a sinistra, ci si sposta verso il centro della strada.', 'Svolta a sinistra: verso il centro. Svolta a destra: verso il margine destro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22862, 'Non è obbligatorio fermarsi se non ci sono veicoli che arrivano e puoi fare la manovra in sicurezza. Ti fermi solo se devi dare la precedenza, se c''è un semaforo rosso, un segnale di stop o se la situazione lo richiede per sicurezza.', 'La frase ''è necessario arrestarsi... anche se non sopraggiungono veicoli'' è la trappola. L''arresto è obbligatorio solo se ci sono ostacoli, veicoli con precedenza, o segnali che lo impongono. Se la strada è libera, puoi procedere.', 'Fermarsi solo se serve (precedenza, ostacoli). Se libero, vai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22863, 'Prima di girare a sinistra, devi sempre usare la freccia per far sapere agli altri cosa farai. Questo vale sempre, anche su strade a senso unico. È una regola di sicurezza fondamentale.', 'La frase ''in anticipo'' è importante: significa che devi segnalare la manovra prima di iniziarla, non all''ultimo momento.', 'Freccia sempre prima di girare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22864, 'Se stai andando in fila parallela e devi girare, puoi spostarti nella corsia giusta per la svolta. Devi farlo con attenzione e segnalando con la freccia, per non creare pericolo.', 'La frase ''è consentito'' significa che si può fare, non che è vietato. L''importante è farlo in sicurezza.', 'Cambi corsia per svoltare, ma con attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22865, 'Se ci sono i vigili urbani o la polizia stradale che dirigono il traffico, loro possono decidere di farvi andare in file parallele, anche se normalmente non sarebbe permesso. Le loro indicazioni hanno sempre la precedenza.', 'La parte ''autorizzata dagli agenti del traffico'' è la chiave. L''autorizzazione di un agente è una condizione che permette le file parallele.', 'Agente comanda, file parallele si fanno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22866, 'Agli incroci con il semaforo, se ci sono almeno due corsie per la tua direzione, puoi andare in file parallele. Questo aiuta a far scorrere meglio il traffico e a ridurre gli ingorghi.', 'La condizione ''regolato da semaforo'' è fondamentale. In un incrocio non regolato, non è permesso.', 'Semaforo + 2+ corsie = file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22867, 'Se la strada ha almeno due corsie per la tua direzione e c''è tanto traffico (intenso), puoi viaggiare in file parallele. Questo è un modo per gestire meglio il flusso di veicoli.', 'La condizione ''qualora il traffico sia intenso'' è cruciale. Senza traffico intenso, anche con più corsie, non si viaggia per file parallele.', 'Traffico intenso + 2+ corsie = file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22868, 'Se c''è un incrocio dove i vigili urbani o la polizia dirigono il traffico, puoi andare in file parallele. Questo è uno dei casi in cui la legge lo permette per migliorare la circolazione.', 'La frase ''Di norma'' significa ''solitamente'', ''normalmente''. ''Regolato da agenti del traffico'' è la condizione che lo permette.', 'Agente all''incrocio = file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22869, 'Se la strada è a senso unico, ha tre corsie e c''è molto traffico, puoi andare in file parallele. Questo serve a far scorrere meglio le auto e a evitare ingorghi.', 'Le condizioni ''traffico intenso'' e ''carreggiata a senso unico a tre corsie'' sono entrambe necessarie per permettere le file parallele.', 'Senso unico + 3 corsie + traffico = file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22870, 'Anche se vai in file parallele, per girare a sinistra devi sempre usare la corsia più a sinistra. Non puoi scegliere una corsia qualsiasi, altrimenti creeresti confusione e pericolo.', 'La parola ''qualsiasi'' è la trappola. Non puoi scegliere una corsia a caso, ma devi usare quella corretta per la svolta.', 'Svolta a sinistra = corsia più a sinistra, non ''qualsiasi''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22871, 'Le file parallele sono permesse solo se l''incrocio è regolato da un semaforo o da un agente del traffico, oppure se c''è traffico intenso su strade con più corsie. Se l''incrocio non è regolato, non puoi andare in file parallele per motivi di sicurezza.', 'La frase ''non regolato'' è la chiave che rende la risposta FALSO. Le file parallele richiedono una regolazione o condizioni specifiche.', 'Incrocio non regolato = no file parallele.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22872, 'Per viaggiare in file parallele, la strada deve avere almeno due corsie per OGNI senso di marcia, o essere a senso unico con più corsie. Una strada con due corsie totali (una per senso di marcia) non permette le file parallele perché non c''è spazio sufficiente.', 'La descrizione ''due corsie e doppio senso di marcia'' significa una corsia per senso di marcia. Questo non è sufficiente per le file parallele.', 'File parallele richiedono almeno due corsie *per il tuo senso di marcia*.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22873, 'Non è ''sempre'' consentito. Anche se ci sono due corsie per senso di marcia, le file parallele sono permesse solo in caso di traffico intenso o in prossimità di incroci regolati. Non è una regola valida in ogni momento.', 'La parola ''sempre'' è una tipica parola trappola nei quiz. Quasi mai una regola è valida ''sempre'' senza eccezioni o condizioni.', '''Sempre'' è quasi sempre FALSO. Le file parallele hanno condizioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22874, 'Anche nei centri urbani, le file parallele non sono permesse ''in qualunque condizione di traffico''. Sono permesse solo se il traffico è intenso o in prossimità di incroci regolati, e se la strada ha le corsie adatte.', 'La frase ''in qualunque condizione di traffico'' è la trappola. Ci sono sempre delle condizioni specifiche che devono essere rispettate.', '''Qualunque'' è quasi sempre FALSO. Le file parallele hanno condizioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22875, 'Non è ''obbligatorio'' viaggiare per file parallele. È consentito, cioè si può fare, ma solo in certe condizioni (traffico intenso, incroci regolati). Non è mai un obbligo imposto dalla legge.', 'La parola ''obbligatorio'' è la trappola. Le file parallele sono una possibilità per gestire il traffico, non un dovere.', 'File parallele non sono mai obbligatorie.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22876, 'L''indicatore di direzione (la freccia) si usa solo quando cambi corsia o giri. Se stai solo percorrendo una corsia, anche quella di sinistra, non devi tenere la freccia accesa, altrimenti confonderesti gli altri guidatori.', 'La frase ''mantenere in funzione'' significa tenerla sempre accesa. Questo è sbagliato e può creare malintesi nel traffico.', 'Freccia solo per cambiare o svoltare, non per ''mantenere''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22877, 'Questa frase è un po'' ingannevole. Le file parallele sono ammesse anche su strade a una sola carreggiata, purché abbiano almeno due corsie per senso di marcia (o siano a senso unico con più corsie) e ci siano le condizioni (traffico intenso, incroci regolati). Non è la presenza di una sola carreggiata a vietarle in assoluto.', 'La trappola è ''non è ammessa se la strada è a una sola carreggiata''. Non è la carreggiata singola il problema, ma il numero di corsie per senso di marcia.', 'Non è la carreggiata singola il limite, ma le corsie per senso di marcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22878, 'Assolutamente no! È molto pericoloso e vietato per i motocicli passare in mezzo ai veicoli che vanno in file parallele. Devono stare nella loro corsia come gli altri veicoli per la sicurezza di tutti.', 'La frase ''possono procedere passando tra i veicoli affiancati'' descrive una manovra estremamente pericolosa e vietata dal Codice della Strada.', 'Moto non passano tra le file. Pericolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22879, 'È vero. I veicoli che si muovono su rotaie, come i tram e i treni, hanno quasi sempre la precedenza agli incroci. Questo significa che devi fermarti e lasciarli passare, a meno che non ci sia un segnale (come un semaforo rosso o un segnale di Stop) che indichi il contrario.', 'La frase ''salvo diversa segnalazione'' è importante. Significa che la regola generale (dare precedenza ai veicoli su rotaie) vale, ma ci possono essere eccezioni se i segnali stradali dicono altro.', 'Rotaie = Precedenza (salvo eccezioni chiare).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22880, 'È vero. Quando sei fermo (ad esempio, parcheggiato a lato della strada o in un''area di sosta) e vuoi rientrare nel flusso del traffico, devi assicurarti che la strada sia libera. Questo significa guardare bene sia a destra che a sinistra e dare la precedenza a tutti i veicoli che stanno già circolando.', 'Le parole ''da fermi, ci si immette nella circolazione'' indicano una manovra di ingresso nel traffico. In questi casi, la prudenza è massima e si dà precedenza a tutti.', 'Entri nel traffico? Guarda ovunque!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22881, 'È vero. L''inversione del senso di marcia (fare un''inversione a U) è una manovra che richiede molto spazio e attenzione. Per farla in sicurezza, devi dare la precedenza a tutti gli altri veicoli che stanno già circolando sulla strada, per non creare pericolo o intralcio.', 'L''espressione ''inversione del senso di marcia'' si riferisce a una manovra speciale. Tutte le manovre speciali richiedono di dare la precedenza agli altri veicoli.', 'Inverti? Tutti prima di te!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22882, 'È vero. Quando fai retromarcia, la tua visibilità è limitata e il controllo del veicolo è più difficile. Per questo motivo, devi sempre dare la precedenza a tutti gli altri veicoli e pedoni che si trovano sulla strada o nelle vicinanze, per evitare incidenti.', 'La parola ''retromarcia'' indica una manovra con visibilità ridotta. In questi casi, la regola è sempre dare la precedenza.', 'Retromarcia? Precedenza sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22883, 'È vero. Un passo carrabile è un''uscita da una proprietà privata (come un garage o un cortile) sulla strada pubblica. Quando esci da un passo carrabile, stai entrando nel traffico e devi dare la precedenza a tutti i veicoli che circolano sulla strada, sia da destra che da sinistra.', 'L''espressione ''passo carrabile'' indica un''uscita da un''area privata. Ogni volta che si passa da un''area privata a una pubblica, si deve dare la precedenza.', 'Esci dal passo? Guarda bene!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22884, 'È vero. Se il segnale in figura è il segnale di ''Dare precedenza'' (un triangolo rovesciato con bordo rosso e sfondo bianco), significa che devi dare la precedenza a tutti i veicoli che arrivano sull''altra strada, sia da destra che da sinistra, prima di impegnare l''incrocio.', 'Il ''segnale in figura'' è fondamentale. Se si tratta del segnale ''Dare precedenza'', la risposta è VERO. Questo segnale ti obbliga a fermarti o rallentare e dare la precedenza a chi è sulla strada principale.', 'Segnale ''Dare precedenza''? Guarda ovunque!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22885, 'È falso. Se il segnale in figura è quello di ''Diritto di precedenza'' (un quadrato giallo con bordo bianco), significa che sei tu ad avere la precedenza. Quindi, non devi dare la precedenza né a destra né a sinistra, ma sono gli altri veicoli che devono darla a te.', 'Il ''segnale in figura'' è la chiave. Se è il segnale di ''Diritto di precedenza'', la frase è FALSO perché tu hai la precedenza, non devi darla.', 'Segnale ''Diritto di precedenza''? La precedenza è tua!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22886, 'È falso. In una rotatoria, la regola generale è dare la precedenza a chi è già all''interno della rotatoria (se non ci sono segnali diversi all''ingresso). Non si tratta di dare la precedenza ''a destra e a sinistra'' in modo generico come in un incrocio normale, ma di seguire il flusso della rotatoria.', 'La parola ''ROTATORIA'' indica un tipo specifico di incrocio con regole di precedenza particolari, diverse dalla semplice ''destra e sinistra''.', 'Rotatoria? Precedenza a chi è dentro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22887, 'È falso. Quando il semaforo è a luce gialla lampeggiante, significa che l''incrocio non è regolato dal semaforo in quel momento. Devi fare molta attenzione e applicare le normali regole della precedenza (ad esempio, dare la precedenza a destra, salvo diversa segnalazione). Non è obbligatorio dare la precedenza ''a tutti i veicoli'', ma seguire le regole generali del Codice della Strada.', 'La frase ''a tutti i veicoli'' è la trappola. La luce gialla lampeggiante significa ''attenzione'' e applicare le regole normali, non dare la precedenza indiscriminatamente a tutti.', 'Giallo lampeggiante? Attenzione e regole normali!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22888, 'È falso. Quando si svolta a sinistra, è vero che si deve dare la precedenza ai veicoli che provengono dal senso opposto e che proseguono dritto o svoltano a destra. Ma non è ''a tutti i veicoli circolanti''. Ad esempio, non devi dare la precedenza a chi ti segue. La regola è più specifica e riguarda solo alcuni veicoli.', 'La frase ''a tutti i veicoli circolanti'' è la trappola. La precedenza quando si svolta a sinistra è limitata ai veicoli che vengono dal senso opposto e che hanno diritto di precedenza.', 'Svolti a sinistra? Precedenza solo a chi viene di fronte!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22889, 'È falso. Se il segnale in figura è quello di ''Diritto di precedenza'' (un quadrato giallo con bordo bianco), significa che sei tu ad avere la precedenza. Quindi, non devi dare la precedenza a tutti i veicoli, ma sono gli altri a doverla dare a te.', 'La frase ''a tutti i veicoli'' è la trappola. Se il segnale ti dà il diritto di precedenza, non devi darla tu a tutti, ma sono gli altri che devono darla a te.', 'Segnale ''Diritto di precedenza''? La precedenza è tua!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22890, 'Quando ti avvicini a un incrocio, devi sempre essere pronto a dare o ricevere la precedenza, a seconda dei segnali stradali o delle regole generali. È fondamentale per la sicurezza di tutti.', 'La frase ''predisporsi ad osservare'' significa prepararsi a rispettare. Non è una trappola, ma sottolinea l''importanza di essere attenti in anticipo.', 'Incrocio = Occhi aperti sulla precedenza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22891, 'Se vuoi girare a destra o a sinistra, devi metterti nella corsia giusta (ad esempio, la corsia più a destra per girare a destra) con un po'' di anticipo. Questo evita di creare confusione o pericolo agli altri veicoli.', 'La locuzione ''per tempo'' è importante: significa in anticipo, non all''ultimo momento. Agire in anticipo è sempre più sicuro.', 'Corsia giusta = Manovra sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22892, 'Quando vuoi girare, devi usare la freccia (indicatore di direzione) con un po'' di anticipo. Questo avvisa gli altri conducenti delle tue intenzioni e aiuta a prevenire incidenti.', 'Anche qui, ''per tempo'' è la parola chiave. Segnalare all''ultimo secondo è inutile e pericoloso.', 'Freccia = Avviso per tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22893, 'Anche se sei in moto o in scooter, all''incrocio devi stare in fila come le auto, dietro gli altri veicoli. Non puoi superare la fila per metterti davanti.', 'La parola ''incolonnarsi'' significa mettersi in fila. È una regola di disciplina stradale che vale per tutti i veicoli.', 'Due ruote o quattro, la fila si rispetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22894, 'Non devi entrare nell''incrocio se vedi che non puoi attraversarlo completamente e rischi di bloccarlo. Questo è importante per non creare ingorghi, specialmente con il traffico intenso.', 'La condizione ''solo se si ha la possibilità di proseguire e liberarlo'' è fondamentale. Non bloccare l''incrocio è una regola di civiltà e sicurezza.', 'Incrocio libero = Traffico fluido.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22895, 'L''incrocio è un punto pericoloso dove le strade si incontrano. Devi essere molto attento, rallentare e guardare bene per evitare di fare o subire incidenti.', 'L''espressione ''massima prudenza'' è un principio generale di sicurezza stradale, sempre valido in situazioni potenzialmente pericolose come gli incroci.', 'Incrocio = Attenzione massima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22896, 'Questa affermazione è falsa! La regola generale è che devi dare la precedenza a chi viene da destra, a meno che non ci siano segnali diversi (stop, dare precedenza, semaforo).', 'La parola ''sempre'' è una trappola classica nei quiz. Le regole stradali raramente sono ''sempre'' o ''mai'' senza eccezioni. La precedenza a destra è la regola generale, ma ci sono molte eccezioni.', '''Sempre'' è quasi sempre FALSO (per la precedenza a destra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22897, 'Questa affermazione è falsa. Se vuoi girare a destra, devi stare sulla corsia più a destra e non devi sorpassare. Sorpassare a sinistra per poi girare a destra è una manovra molto pericolosa e vietata.', 'La frase ''sorpassare velocemente a sinistra se si vuole svoltare a destra'' descrive una manovra contraddittoria ed estremamente pericolosa. È un chiaro segnale di falso.', 'Svoltare a destra = Stai a destra, non sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22898, 'Questa affermazione è falsa. Nei centri abitati, il clacson si usa solo in caso di pericolo immediato per evitare un incidente. Non si usa per avvisare che si sta arrivando all''incrocio o per salutare.', 'La parola ''occorre'' implica che sia una necessità o un obbligo, ma nei centri abitati è l''opposto: l''uso del clacson è vietato se non per pericolo grave e imminente.', 'Clacson in città = Solo per pericolo grave.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22899, 'Procedere a zig zag, cioè cambiare corsia spesso e rapidamente, è molto pericoloso vicino o dentro un incrocio. Anche se le linee sono tratteggiate (discontinue) e permetterebbero il cambio di corsia, la sicurezza all''incrocio è la priorità. Per questo non è consentito.', 'La frase ''anche se le corsie direzionali sono segnate da strisce discontinue'' è una trappola. Nonostante le strisce, la manovra è pericolosa e vietata.', 'Incrocio = stabilità, no zig zag.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22900, 'Cambiare direzione all''improvviso, senza preavviso o senza segnalare, è molto pericoloso per te e per gli altri veicoli. Agli incroci è fondamentale essere prevedibili per evitare incidenti.', 'La parola ''improvvisamente'' è la chiave. Ogni manovra deve essere graduale e segnalata.', 'Incrocio = prevedibilità, no mosse a sorpresa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22901, 'Fare l''inversione di marcia (girarsi e tornare indietro) in un incrocio è una manovra molto complessa e pericolosa. Si incrociano troppe traiettorie di veicoli, aumentando il rischio di collisioni.', 'Non ci sono parole trappola particolari, ma l''azione ''inversione di marcia'' è il punto cruciale. È una manovra da evitare in luoghi trafficati e complessi come gli incroci.', 'Incrocio = no inversione di marcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22902, 'La sosta (fermare il veicolo per un tempo prolungato, anche con il conducente a bordo) è vietata in corrispondenza degli incroci, sia in città che fuori. Questo perché ostacola la visibilità e il flusso del traffico, rendendo l''incrocio più pericoloso.', 'La parola ''extraurbani'' potrebbe farti pensare che le regole siano meno severe, ma per la sosta agli incroci non cambia nulla: è sempre vietata.', 'Incrocio = no sosta, mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22903, 'Anche la fermata (fermare il veicolo per un breve tempo, per far salire o scendere passeggeri, o per un''esigenza momentanea) è vietata in corrispondenza degli incroci. Anche una breve fermata può creare intralcio e pericolo, specialmente fuori città dove le velocità sono maggiori.', 'Anche qui, ''extraurbani'' non cambia la regola. La fermata è vietata agli incroci per motivi di sicurezza e fluidità del traffico.', 'Incrocio = no fermata, neanche breve.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22904, 'Sorpassare una bicicletta è consentito solo se si ha spazio sufficiente e si può mantenere una distanza di sicurezza. Se per sorpassare devi invadere la corsia opposta, vicino o dentro un incrocio, è troppo rischioso a causa del traffico che potrebbe arrivare o svoltare.', 'La condizione ''se si deve occupare la corsia opposta di marcia'' è fondamentale. Senza questa condizione, il sorpasso di una bici potrebbe essere consentito se sicuro.', 'Incrocio + corsia opposta = no sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22905, 'I fari anabbaglianti sono le luci che usi normalmente di notte o in condizioni di scarsa visibilità. È obbligatorio usarli per vedere la strada ed essere visti dagli altri, anche e soprattutto in prossimità degli incroci. Quindi, è consentito usarli, anzi, è necessario.', 'La frase ''non è consentito'' è la trappola. È l''opposto della verità. I fari anabbaglianti sono fondamentali per la sicurezza.', 'Anabbaglianti = sempre utili, anche all''incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22906, 'Non esiste una regola generale che imponga un limite di 60 km/h agli incroci extraurbani. La velocità deve essere sempre adeguata alle condizioni della strada, del traffico e della visibilità, e rispettare i limiti specifici della strada. Potrebbe essere 90 km/h o meno, a seconda dei segnali.', 'Il numero ''60 km/h'' è la trappola. Non è un limite fisso per tutti gli incroci extraurbani. La velocità va sempre regolata con prudenza, ma non c''è un limite universale di 60 km/h.', 'Velocità = segnali e prudenza, non numero fisso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22907, 'È sempre obbligatorio usare l''indicatore di direzione (la freccia) quando si cambia direzione, anche per una semplice svolta a destra in un incrocio urbano. Questo serve a comunicare le tue intenzioni agli altri utenti della strada e prevenire incidenti.', 'La frase ''è consentito non azionare'' è la trappola. È il contrario di ciò che si deve fare. La freccia è sempre obbligatoria per ogni cambio di direzione.', 'Svolta = freccia sempre, senza eccezioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22908, 'Se un incrocio è regolato da un semaforo e hai il verde, e non ci sono altri divieti (come una linea continua o un segnale specifico), il sorpasso è consentito, a patto che sia sicuro e che tu rimanga nella tua corsia. Il semaforo verde ti dà il via libera, ma sempre con prudenza.', 'La frase ''non è consentito il sorpasso'' è la trappola. Se il semaforo è verde e le condizioni lo permettono, il sorpasso è consentito.', 'Semaforo verde = ok sorpasso (se sicuro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22909, 'Un semaforo a luce gialla lampeggiante significa ''procedere con cautela e dare la precedenza''. Questo implica che devi assolutamente rallentare, essere pronto a fermarti e assicurarti che non ci siano pericoli prima di attraversare l''incrocio.', 'La frase ''non si deve rallentare'' è la trappola. È l''esatto contrario di ciò che si deve fare. Il giallo lampeggiante richiede massima prudenza e rallentamento.', 'Giallo lampeggiante = rallenta e prudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22910, 'Fuori dai centri abitati (extraurbani), è consentito usare il clacson (segnalazione acustica) se necessario per motivi di sicurezza, ad esempio per avvisare della tua presenza in un incrocio con scarsa visibilità. In città, invece, è vietato se non per pericolo immediato.', 'La frase ''non è consentito'' è la trappola. Fuori città, il clacson è permesso per sicurezza. La distinzione ''extraurbani'' è cruciale qui.', 'Clacson extraurbano = ok per sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22911, 'La regola generale della precedenza agli incroci, quando non ci sono segnali specifici, è che si deve dare la precedenza a chi viene da destra. Di conseguenza, chi arriva da sinistra deve dare la precedenza.', 'La frase ''di norma'' significa ''normalmente'' o ''solitamente'', indicando che questa è la regola generale quando non ci sono cartelli o semafori che dicono il contrario.', 'Chi viene da sinistra, aspetta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22912, 'Sì, è vero. Anche se si ha la precedenza, è sempre obbligatorio guidare con prudenza e rallentare agli incroci. Questo serve a prevenire incidenti, anche se l''altro conducente dovesse sbagliare.', 'La parola ''entrambi'' è importante: significa che sia chi ha la precedenza sia chi non ce l''ha, devono moderare la velocità.', 'Incrocio = prudenza per tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22913, 'È vero. Anche se un altro veicolo sbaglia e non rispetta la precedenza, tu devi comunque essere prudente per evitare un incidente. La ''tolleranza'' significa non insistere sul tuo diritto a tutti i costi, per la sicurezza di tutti.', 'La frase ''pur non avendo la precedenza, passa ugualmente'' descrive una situazione di errore altrui. ''Prudenti e tolleranti'' sono le parole chiave che indicano il comportamento corretto.', 'Meglio un secondo in più che un incidente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22914, 'È vero. Quando esci da un passo carrabile, un garage o qualsiasi proprietà privata, ti stai immettendo in una strada pubblica. Devi fare molta attenzione perché potresti incontrare veicoli o pedoni che non si aspettano la tua uscita.', 'La ''proprietà privata'' è un luogo non pubblico. ''Procedere con prudenza'' è un obbligo generale in queste situazioni.', 'Da privato a pubblico, massima attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22915, 'È vero. I pedoni hanno sempre la precedenza quando un veicolo esce da una proprietà privata e si immette su un marciapiede o sulla strada. Devi fermarti e aspettare che passino.', 'La parola ''eventuali'' ricorda che devi sempre considerare la possibilità che ci siano pedoni, anche se non li vedi subito.', 'Pedone sempre re, da proprietà privata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22916, 'È vero. Uscire lentamente ti permette di vedere meglio e di avere il tempo di reagire se c''è un pericolo. Se sei in retromarcia, la visibilità è ridotta, quindi la lentezza è ancora più importante per la sicurezza.', 'La frase ''specie se in retromarcia'' sottolinea che la lentezza è ancora più cruciale in quella specifica manovra.', 'Lento e attento, soprattutto in retro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22917, 'È falso. La larghezza della strada non ha alcuna importanza per stabilire chi ha la precedenza. La precedenza è regolata dai segnali stradali (stop, dare precedenza) o, in assenza di questi, dalla regola della precedenza a destra.', 'La frase ''strada più stretta'' è la trappola: non è un criterio valido per decidere la precedenza.', 'Larghezza strada? Non conta per la precedenza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22918, 'È falso. Il clacson si usa solo in caso di pericolo immediato per avvisare gli altri. Non è un obbligo generale quando si esce da una proprietà privata. L''obbligo è la prudenza e dare la precedenza.', 'La parola ''obbligatorio'' è la trappola. Suonare il clacson non è un obbligo in questa situazione, ma un uso specifico in caso di pericolo.', 'Clacson solo per pericolo, non per abitudine.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22919, 'È falso. È il contrario! Quando esci da una proprietà privata, devi sempre dare la precedenza ai pedoni che si trovano sul marciapiede o sulla strada. I pedoni sono la parte più debole della strada.', 'La frase ''si ha la precedenza sui pedoni'' è la trappola, perché è esattamente il contrario di quello che dice la legge.', 'Pedone sempre re, da proprietà privata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22920, 'È VERO. Un autotreno è un veicolo molto lungo. Per svoltare a destra in una strada stretta, ha bisogno di rallentare molto per fare la curva in sicurezza. Gli altri veicoli devono aspettarsi questo rallentamento.', 'La parola ''potrebbe'' indica una possibilità, ma in questo caso è una possibilità molto alta e da considerare. ''Notevolmente'' sottolinea che il rallentamento sarà significativo.', 'Autotreno lungo = curva lenta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22921, 'È VERO. A causa della sua lunghezza, un autotreno che deve svoltare a destra in una strada stretta spesso deve prima spostarsi un po'' a sinistra (cioè ''allargarsi'') per avere lo spazio sufficiente per completare la curva senza che le ruote posteriori finiscano sul marciapiede o urtino ostacoli.', 'La frase chiave è ''si sposti a sinistra (si allarghi)''. Questo è il comportamento tipico dei veicoli lunghi in curva.', 'Autotreno a destra? Prima a sinistra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22922, 'È VERO. Se un autotreno non riesce a completare la svolta o incontra un ostacolo, potrebbe aver bisogno di fare una piccola retromarcia. Se sei troppo vicino, gli impedisci di fare questa manovra e diventi un intralcio.', 'Le parole ''non bisogna stargli troppo vicino'' e ''d''intralcio'' sono importanti. Indicano la necessità di mantenere una distanza di sicurezza.', 'Distanza = spazio per manovre (anche retromarcia).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22923, 'È VERO. Un autotreno è un veicolo molto grande. Se provi a sorpassarlo mentre sta svoltando a un incrocio, ti bloccherà completamente la vista di eventuali segnali stradali o di altri veicoli che arrivano dalle strade laterali, rendendo la manovra estremamente pericolosa.', 'Le parole ''rinunciare a sorpassarlo'' e ''impedire la vista'' sono fondamentali. Indicano un divieto e un pericolo grave.', 'Autotreno + incrocio = mai sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22924, 'È FALSO. Questa è una manovra molto pericolosa. Come abbiamo visto, l''autotreno potrebbe allargarsi a sinistra prima di svoltare a destra. Se lo sorpassi a sinistra, rischi di rimanere schiacciato o di causare un incidente grave. Inoltre, sorpassare in prossimità di un incrocio è generalmente vietato o molto rischioso.', 'La parola ''bisogna'' rende l''affermazione un obbligo, ma l''azione ''sorpassarlo subito a sinistra'' è sbagliata e pericolosa.', 'Autotreno che gira = non sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22925, 'È FALSO. Quando un autotreno aziona l''indicatore di direzione, significa che sta per iniziare la manovra di svolta. Questo è il momento in cui devi essere più prudente, rallentare e mantenere la distanza, non certo sorpassarlo. Sorpassare in questa situazione è estremamente pericoloso.', 'Le parole ''devono sorpassarlo'' e ''appena aziona l''indicatore di direzione'' sono le trappole. L''indicatore di direzione è un segnale di attenzione, non un invito al sorpasso.', 'Freccia = attenzione, non sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22926, 'È FALSO. La segnalazione luminosa di pericolo (le ''quattro frecce'') si usa per segnalare un pericolo che riguarda il tuo veicolo (ad esempio, un guasto, una sosta forzata, un rallentamento improvviso e inaspettato). Non si usa per segnalare la manovra di un altro veicolo, per quanto complessa possa essere. In questo caso, devi solo rallentare e mantenere la distanza di sicurezza.', 'La parola ''debbono'' indica un obbligo, ma l''azione ''azionare la segnalazione luminosa di pericolo'' è sbagliata per questa situazione.', 'Pericolo altrui = prudenza, non 4 frecce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22927, 'Quando fai l''inversione di marcia, cambi completamente direzione e attraversi la strada. Per questo motivo, devi sempre controllare bene e lasciare passare tutti i veicoli che stanno arrivando, sia da davanti che da dietro, per non causare incidenti. La sicurezza è la priorità.', 'La frase ''deve dare la precedenza'' indica un obbligo preciso. Non è un''opzione, ma una regola da seguire sempre.', 'Inversione = precedenza a tutti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22928, 'Se la strada è molto trafficata e le macchine passano continuamente, fare l''inversione di marcia è estremamente pericoloso. Potresti bloccare il traffico o causare un incidente. In queste situazioni, è obbligatorio non fare la manovra e cercare un posto più sicuro o un''altra strada.', 'Le parole ''deve rinunciare'' e ''traffico intenso e continuo'' sono chiare: se le condizioni sono queste, la manovra è vietata per sicurezza.', 'Troppo traffico? Non fare inversione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22929, 'La visibilità è fondamentale per guidare in sicurezza. Se non vedi bene (per nebbia, pioggia forte, buio, ecc.), non puoi fare l''inversione di marcia. Non vedresti le altre macchine e loro non vedrebbero te, creando un grande pericolo. È obbligatorio rinunciare alla manovra in queste condizioni.', 'Anche qui, ''deve rinunciare'' è un obbligo. ''Scarsa visibilità'' è la condizione che rende la manovra pericolosa e quindi vietata.', 'Non vedi? Non girare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22930, 'L''indicatore di direzione, cioè la ''freccia'', serve per comunicare agli altri conducenti cosa intendi fare. È obbligatorio usarlo ogni volta che cambi direzione o fai una manovra, inclusa l''inversione di marcia, per avvisare chi ti segue o chi ti incrocia.', 'La frase ''deve azionare l''indicatore di direzione'' sottolinea un obbligo. Non è una scelta, ma una regola per la sicurezza stradale.', 'Ogni manovra = freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22931, 'Questa è una regola generale per tutte le manovre alla guida. Devi sempre guidare in modo da non mettere in pericolo gli altri utenti della strada (pedoni, ciclisti, altri veicoli) e da non bloccare il traffico. L''inversione di marcia, essendo una manovra complessa, richiede particolare attenzione a questo principio.', 'La frase ''non deve creare pericolo o intralcio'' è un principio fondamentale del Codice della Strada. È un divieto chiaro a comportamenti rischiosi.', 'Sicurezza prima di tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22932, 'La segnalazione luminosa di pericolo (le ''quattro frecce'') si usa solo in situazioni di emergenza, quando il veicolo è fermo in una posizione pericolosa o in caso di guasto. Per l''inversione di marcia, che è una normale manovra, si usa solo l''indicatore di direzione (la freccia singola) per segnalare la propria intenzione.', 'La trappola è confondere ''segnalazione luminosa di pericolo'' (quattro frecce) con ''indicatore di direzione'' (freccia singola). Sono due cose diverse con scopi diversi.', 'Inversione = freccia singola, non quattro frecce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22933, 'Fare l''inversione di marcia in curva è sempre vietato e molto pericoloso. In curva la visibilità è ridotta, quindi non vedresti bene i veicoli che arrivano e loro non ti vedrebbero in tempo. Dare la precedenza non elimina il pericolo intrinseco della curva.', 'La parola ''anche in curva'' è la chiave. Le curve sono luoghi dove la visibilità è limitata e quindi le manovre complesse come l''inversione sono proibite, anche se si dà la precedenza.', 'Curva = mai inversione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22934, 'Se la linea di mezzeria è continua, non puoi superarla né attraversarla. Questo significa che non puoi fare l''inversione di marcia. Per poter fare l''inversione, la linea di mezzeria deve essere tratteggiata. Quindi, devi accertarti che NON sia continua, o che sia tratteggiata.', 'La trappola è ''deve accertarsi se la linea di mezzeria è continua''. Se è continua, l''inversione è vietata. La frase è Falsa perché l''accertamento dovrebbe essere per la linea tratteggiata, che permette la manovra, o per la non continuità della linea.', 'Linea continua = no inversione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22935, 'Anche se la linea di mezzeria è tratteggiata e ti permetterebbe di attraversarla, non puoi fare l''inversione di marcia se c''è scarsa visibilità. La sicurezza è sempre la cosa più importante. Se non vedi bene, la manovra è troppo rischiosa, indipendentemente dalla linea sull''asfalto.', 'La frase ''anche con scarsa visibilità'' è la trappola. La scarsa visibilità rende la manovra pericolosa e quindi vietata, anche se la linea tratteggiata permetterebbe teoricamente l''attraversamento.', 'Scarsa visibilità = mai inversione, anche con linea tratteggiata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22936, 'Non è vero che puoi fare l''inversione di marcia ''solo'' sulle strade molto larghe e con una sola manovra. Puoi farla anche su strade meno larghe, facendo più manovre (avanti e indietro), purché ci siano tutte le condizioni di sicurezza: buona visibilità, assenza di traffico, linea di mezzeria tratteggiata e spazio sufficiente per completare la manovra senza pericolo.', 'La parola ''solo'' è la trappola. Limita troppo le possibilità. Si può fare inversione anche con più manovre, se le condizioni di sicurezza lo permettono.', 'Non solo strade larghe; anche con più manovre, se sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22937, 'È VERO. Nelle curve la visibilità è limitata, non si vede bene chi arriva. Fare inversione di marcia in questi punti è molto pericoloso e può causare incidenti.', 'non è consentito', 'Curva = No inversione (non vedi chi arriva).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22938, 'È VERO. Gli incroci sono punti dove si incontrano molti veicoli. Fare inversione di marcia lì è pericoloso perché si intralcia il traffico e si rischia di causare collisioni.', 'non è consentita', 'Incrocio = No inversione (troppo traffico e pericolo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22939, 'È VERO. Se la visibilità è scarsa (per esempio per nebbia, pioggia forte o buio), non si vedono bene gli altri veicoli. Fare inversione in queste condizioni è estremamente pericoloso.', 'in tutti i casi di scarsa visibilità', 'Scarsa visibilità = No inversione (non vedi la strada).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22940, 'È VERO. Sui dossi o subito dopo, la visibilità è ridotta. Non si vede chi arriva dall''altra parte della strada. Fare inversione in questi punti è molto pericoloso.', 'non è consentito', 'Dosso = No inversione (non vedi oltre).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22941, 'È FALSO. La mancanza di segnaletica orizzontale (le linee sull''asfalto) non significa che non si possa fare inversione di marcia. Se le condizioni della strada e del traffico lo permettono in sicurezza, si può fare.', 'non è consentito', 'No linee = Puoi fare inversione (se è sicuro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22942, 'È FALSO. La linea di margine continua indica il bordo della carreggiata e non si può superare per uscire o entrare dalla strada. Ma l''inversione di marcia si fa sulla carreggiata, non superando la linea di margine. Quindi, questa linea non vieta l''inversione.', 'linea di margine', 'Linea di margine continua = Non vieta inversione (si fa sulla strada).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22943, 'È FALSO. Fuori dai centri abitati, se la strada è dritta, la visibilità è buona e non ci sono pericoli (come curve, dossi o incroci), è possibile fare inversione, prestando sempre la massima attenzione.', 'non è consentito', 'Fuori città = Puoi fare inversione (se sicuro e visibile).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22944, 'È FALSO. Sulle autostrade e sulle strade extraurbane principali è sempre vietato fare inversione di marcia, tornare indietro o fare retromarcia. Sono strade ad alta velocità e queste manovre sono estremamente pericolose.', 'è consentito', 'Autostrada = MAI inversione (troppo pericoloso).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22945, 'Nelle rotatorie moderne, dove c''è il segnale ''DARE PRECEDENZA'' all''ingresso, devi dare la precedenza ai veicoli che arrivano da sinistra, cioè quelli che sono già dentro la rotatoria. Se non ci fosse il segnale, varrebbe la regola generale della precedenza a destra.', 'La frase chiave è ''solo se vi è il segnale DARE PRECEDENZA''. Questo significa che la regola della precedenza a sinistra non è sempre valida, ma dipende dalla segnaletica.', 'Rotatoria con segnale = precedenza a sinistra (a chi è già dentro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22946, 'Se in una rotatoria non ci sono segnali specifici (come ''DARE PRECEDENZA'' o semafori), si applica la regola generale del Codice della Strada: devi dare la precedenza a chi viene dalla tua destra.', 'La parte importante è ''in assenza di specifico segnale''. Questo cambia la regola, perché se ci fosse un segnale, dovresti seguirlo.', 'Nessun segnale = precedenza a destra (regola generale).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22947, 'Sì, è vero. Le rotatorie sono spesso organizzate in modo che i veicoli che vogliono entrare (in entrata) debbano dare la precedenza a quelli che stanno già girando dentro (già circolanti nell''anello). Questo rende il traffico più fluido e sicuro.', 'La frase ''può essere disciplinata'' indica che è una possibilità e il modo più comune di regolare le rotatorie moderne, non un obbligo senza segnali.', 'Rotatoria moderna = chi entra dà precedenza a chi è già dentro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22948, 'Sì, è vero. L''obbligo di dare la precedenza è spesso imposto ai veicoli che stanno per entrare nella rotatoria, di solito tramite il segnale ''DARE PRECEDENZA''. Questo serve a garantire la sicurezza e la fluidità del traffico all''interno dell''anello.', 'Anche qui, ''può essere imposto'' sottolinea che questa regola è stabilita da una specifica segnaletica o regolamentazione.', 'Chi entra in rotatoria *può* dover dare precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22949, 'Sì, è vero. Quando ti avvicini a una rotatoria, è sempre una buona pratica ridurre la velocità e fare molta attenzione. Devi guardare bene cosa fanno gli altri veicoli e i pedoni per evitare incidenti.', 'La frase ''è opportuno'' significa che è consigliabile e una buona norma di comportamento, anche se non è sempre un obbligo legale stretto, è fondamentale per la sicurezza.', 'In incrocio/rotatoria = sempre prudenza e velocità moderata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22950, 'Sì, è vero. Su una strada in forte salita o discesa, se due veicoli non riescono a passare contemporaneamente, di solito chi scende deve fermarsi e, se necessario, fare retromarcia. Questo perché chi scende ha più controllo del veicolo e chi sale potrebbe avere difficoltà a ripartire.', 'La parola ''in genere'' indica che questa è la regola generale, ma potrebbero esserci eccezioni o situazioni particolari. Tuttavia, è la norma.', 'In pendenza stretta: chi scende dà precedenza a chi sale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22951, 'Sì, è vero. Il segnale ''DARE PRECEDENZA'' è sempre accompagnato da una linea bianca orizzontale fatta di triangoli. Se devi fermarti per dare precedenza, devi farlo prima di questa linea, in modo da non invadere l''incrocio.', 'La frase ''se occorre arrestarsi'' è importante: non devi fermarti sempre, ma solo se ci sono veicoli a cui dare precedenza. Ma se ti fermi, il punto è quello.', 'Dare precedenza = fermati alla linea di triangoli (se serve).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22952, 'FALSO. Non è *sempre* obbligatorio dare la precedenza ai veicoli provenienti da sinistra in una rotatoria. Questo obbligo esiste solo se ci sono i segnali che lo indicano (come il segnale ''DARE PRECEDENZA'' all''ingresso). Se non ci sono segnali, vale la regola generale della precedenza a destra.', 'La parola ''obbligatorio'' rende la frase falsa, perché non è una regola universale per *tutte* le rotatorie. Dipende dalla segnaletica.', 'Precedenza a sinistra in rotatoria = solo con segnale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22953, 'FALSO. Non bisogna ''sempre'' dare la precedenza ai veicoli già dentro la rotatoria. Questa regola vale nelle rotatorie moderne con il segnale ''DARE PRECEDENZA'' all''ingresso. Ma nelle rotatorie più vecchie o senza segnali specifici, vale la precedenza a destra, quindi chi è già dentro potrebbe dover dare precedenza a chi entra da destra.', 'La parola ''sempre'' è la trappola. Non è una regola universale per tutte le rotatorie. Devi guardare i segnali.', '''Sempre'' in rotatoria? Attenzione! Dipende dai segnali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22954, 'FALSO. È assolutamente vietato fare manovre di retromarcia all''interno di una rotatoria. La retromarcia è una manovra molto pericolosa in incroci e rotatorie, perché può causare incidenti gravi.', 'La frase ''possono effettuare manovre di retromarcia'' è falsa. La retromarcia è quasi sempre vietata in situazioni di traffico o incroci.', 'Rotatoria = mai retromarcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22956, 'FALSO. Nelle rotatorie, come nella maggior parte delle strade, il sorpasso è consentito solo a sinistra. Sorpassare a destra è generalmente vietato e molto pericoloso, a meno di casi specifici (ad esempio, se il veicolo davanti ha segnalato di voler svoltare a sinistra e si è spostato molto a sinistra).', 'La parte ''sia a destra che a sinistra'' rende la frase falsa. Il sorpasso a destra è quasi sempre vietato.', 'Sorpasso = di norma solo a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22957, 'Quando sei su una strada in forte salita o discesa e non c''è spazio per passare, di solito chi scende deve fermarsi e, se necessario, fare retromarcia. Questo perché chi sale ha più difficoltà a ripartire da fermo.', 'La frase ''in genere'' significa ''di solito'', non è una regola assoluta ma la prassi più sicura e logica.', 'In pendenza, chi scende si ferma e aspetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22958, 'Se c''è una piazzola di scambio (uno slargo dove un veicolo può accostare) e il passaggio è difficile, chi è vicino alla piazzola deve usarla per far passare l''altro veicolo. Questo aiuta a rendere il traffico più fluido e sicuro.', 'La parola ''Qualora'' significa ''se''. ''spetta a lui'' significa che è suo compito o responsabilità.', 'C''è una piazzola? Usala per facilitare il passaggio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22959, 'Il segnale DARE PRECEDENZA ti dice di dare la precedenza agli altri veicoli. Devi rallentare e fare attenzione, ma non devi fermarti per forza. Ti fermi solo se vedi che stanno arrivando altri veicoli o se non riesci a vedere bene la strada.', 'La parte ''solo in caso di necessità'' è fondamentale. Non è un obbligo di arresto come lo STOP.', 'Dare Precedenza: rallenta, fermati solo se serve.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22960, 'Il segnale di STOP significa che devi SEMPRE fermarti. Non importa se non c''è la linea bianca sull''asfalto o se non vedi arrivare nessuno. Devi fare un arresto completo e poi ripartire solo quando è sicuro.', 'La frase ''non occorre arrestarsi'' è la trappola. Il segnale di STOP impone sempre l''arresto.', 'STOP: sempre stop, anche senza linea o veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22961, 'Questa affermazione è falsa. In una strada in forte pendenza, è più difficile ripartire per chi sta salendo. Per questo motivo, è chi scende che deve fermarsi per facilitare il passaggio, non chi sale.', 'La parte ''in salita arrestarsi'' è l''errore. È il contrario della regola corretta.', 'Chi sale ha la precedenza, chi scende si ferma.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22962, 'Non è mai consentito fermarsi sulle strisce pedonali. Le strisce devono essere sempre libere per permettere ai pedoni di attraversare in sicurezza, anche se il semaforo per i pedoni è rosso.', 'La frase ''è consentito arrestarsi sulle strisce pedonali'' è la trappola. Le strisce pedonali sono un''area sacra per i pedoni.', 'Strisce pedonali? Mai fermarsi sopra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22963, 'È VERO. Quando vedi scritte luminose sui veicoli della polizia, come ''INCIDENTE'' o ''RALLENTARE'', devi sempre seguire le loro indicazioni. Sono lì per la tua sicurezza e per regolare il traffico.', 'La frase ''devono attenersi'' significa che è un obbligo, non una scelta. Devi seguire le istruzioni.', 'Polizia = Obbligo. Segui sempre le indicazioni luminose.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22964, 'È VERO. Se la polizia ti sorpassa con la sirena e ti mostra ''ACCOSTARE'', significa che devi fermarti subito sul lato della strada. È un ordine diretto a te.', '''Accostare'' significa ''mettersi a lato della strada e fermarsi''. Non significa solo rallentare o svoltare.', '''ACCOSTARE'' = Fermati subito a lato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22965, 'È VERO. Se la polizia ti segnala ''ALT POLIZIA'' con la sirena e il display, l''ordine è rivolto a te. Devi fermarti immediatamente. Non è un segnale per tutti i veicoli in generale, ma per quello a cui si stanno rivolgendo.', 'La parola ''solo'' qui è corretta perché l''ordine è specifico per il veicolo che la polizia sta fermando, non per tutti gli altri veicoli sulla strada.', '''ALT POLIZIA'' = Fermati TU.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22966, 'È VERO. Se vedi ''INCIDENTE'' sul display della polizia, significa che c''è un pericolo avanti. Devi rallentare per essere pronto a fermarti o a reagire in sicurezza.', 'La frase ''bisogna diminuire la velocità'' indica un''azione necessaria per la sicurezza.', '''INCIDENTE'' = Rallenta per sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22967, 'È FALSO. La scritta ''INCIDENTE'' sul veicolo della polizia significa che c''è un incidente in quel momento, non che la zona è ''ad alto rischio'' in generale. È una segnalazione di un evento attuale, non una previsione futura.', 'La frase ''ad alto rischio di incidenti'' è la parola trappola. ''INCIDENTE'' indica un fatto presente, non una caratteristica della zona.', '''INCIDENTE'' = C''è un problema ORA, non un rischio futuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22968, 'È FALSO. ''ACCOSTARE'' significa fermarsi sul lato della strada, non ''svoltare'' (girare). Se la polizia ti dice di accostare, devi fermarti, non cambiare direzione.', 'La parola ''svoltare'' è la trappola. ''Accostare'' e ''svoltare'' sono azioni diverse.', '''ACCOSTARE'' = Fermarsi, non girare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22969, 'È FALSO. Quando la polizia segnala ''RALLENTARE'', l''obbligo è per TUTTI i veicoli, non solo per quelli pesanti. Le indicazioni di sicurezza valgono per tutti i conducenti.', 'La frase ''ai soli veicoli pesanti'' è la trappola. Le indicazioni della polizia sono quasi sempre per tutti, a meno che non sia specificato diversamente (es. ''ALT CAMION'').', '''RALLENTARE'' = Per TUTTI, non solo camion.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22970, 'Quando ti immetti nel traffico (cioè entri nella strada da un parcheggio, un passo carrabile, ecc.), devi sempre fare attenzione a non creare problemi o pericoli per gli altri veicoli e persone che sono già sulla strada. La sicurezza è la cosa più importante.', 'La frase chiave è ''senza creare pericolo o intralcio''. Questo significa che la tua manovra non deve mettere a rischio nessuno né rallentare o bloccare il traffico.', 'Entri? Non disturbare e non mettere in pericolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22971, 'Prima di entrare nel flusso della circolazione, devi guardare bene dove si trovano gli altri veicoli, quanto sono lontani da te e in che direzione stanno andando. Questo ti aiuta a capire se hai abbastanza spazio e tempo per entrare in sicurezza.', 'Le parole ''posizione, distanza, direzione'' sono fondamentali. Devi valutare tutti questi aspetti degli altri utenti della strada per una manovra sicura.', 'Guarda tutto: dove sono, quanto distano, dove vanno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22972, 'È obbligatorio usare l''indicatore di direzione (la ''freccia'') per segnalare che vuoi entrare nel traffico. Devi farlo con un po'' di anticipo, così gli altri conducenti capiscono la tua intenzione e possono prepararsi.', 'Le parole ''deve azionare'' e ''con sufficiente anticipo'' sono importanti. ''Deve'' significa che è un obbligo, e ''sufficiente anticipo'' significa non all''ultimo momento.', 'Freccia sempre e per tempo, è un obbligo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22973, 'Quando ti immetti nel traffico, devi sempre dare la precedenza ai veicoli che sono già sulla strada. Loro hanno il diritto di passare per primi perché sono già nel flusso della circolazione.', 'La frase ''deve dare la precedenza'' è la regola principale. Chi entra, si adatta al traffico esistente.', 'Chi entra, aspetta chi è già dentro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22974, 'Questa affermazione è FALSA. Anche se non vedi altri veicoli, devi comunque azionare l''indicatore di direzione. È una regola di comportamento e ti aiuta a creare una buona abitudine, utile quando ci saranno altri veicoli.', 'La parola ''può evitare'' è la trappola. L''uso della freccia non è facoltativo, ma obbligatorio, indipendentemente dalla presenza di altri veicoli.', 'Freccia SEMPRE, anche se non c''è nessuno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22975, 'Questa affermazione è FALSA. Devi dare la precedenza ai veicoli in transito SEMPRE quando ti immetti nel flusso della circolazione, non solo se c''è un cartello. È una regola generale di comportamento.', 'La parola ''solo'' è la trappola. Non è vero che la precedenza si dà solo con il segnale; è una regola che vale sempre in questa situazione.', 'Precedenza SEMPRE, segnale o no.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22976, 'Questa affermazione è FALSA. Quando ti immetti nel traffico, devi dare la precedenza a TUTTI i veicoli in transito, incluse le biciclette. Le biciclette sono utenti della strada e hanno gli stessi diritti e la stessa precedenza in questo caso.', 'La frase ''ad eccezione delle biciclette'' è la trappola. Non ci sono eccezioni per le biciclette; sono veicoli come gli altri e vanno rispettate.', 'Precedenza a TUTTI, bici incluse!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22977, 'Quando guidi un motociclo, il casco è obbligatorio. Devi indossarlo e allacciarlo sempre, anche quando parti da fermo per immetterti nel traffico. È una regola fondamentale per la tua sicurezza.', 'La parola ''deve'' indica un obbligo, non una scelta. Non puoi partire senza casco.', 'Casco sempre, prima di partire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22978, 'La cintura di sicurezza è obbligatoria per il conducente e i passeggeri di un autoveicolo. Devi allacciarla prima di iniziare a muoverti. Ci sono delle eccezioni, ma sono rare e devono essere certificate (ad esempio, per motivi medici).', 'La frase ''salvo che non sia esentato'' è importante. Significa che l''obbligo vale per tutti, a meno che non ci sia un motivo speciale e riconosciuto per non usarla.', 'Cintura sempre, prima di partire (salvo esenzioni).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22979, 'I motocicli devono tenere sempre accesi i fari anabbaglianti, sia di giorno che di notte. Questo serve per essere più visibili agli altri veicoli e aumentare la sicurezza, anche quando parti dal margine della strada.', 'Anche qui, ''deve'' sottolinea un obbligo. Non è una scelta accendere o meno le luci.', 'Moto: luci anabbaglianti sempre accese.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22980, 'Prima di partire e immetterti nel traffico, è molto importante controllare bene che la strada sia libera. Devi guardare avanti, di lato e usare gli specchietti retrovisori per vedere se arrivano altri veicoli o pedoni. La sicurezza prima di tutto.', 'La frase ''deve accertarsi'' indica una tua responsabilità. ''anche negli specchietti'' significa che non basta guardare solo avanti, ma devi usare tutti gli strumenti a disposizione.', 'Partenza sicura: guarda ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22981, 'Questa affermazione è falsa. La cintura di sicurezza va allacciata PRIMA di iniziare qualsiasi manovra, anche una semplice partenza. Non puoi aspettare di essere già in movimento, perché in caso di incidente improvviso non saresti protetto.', 'La parola ''dopo'' è la trappola. La cintura va messa ''prima''. Anche ''può'' è fuorviante, perché non è una scelta ma un obbligo.', 'Cintura: prima di partire, non dopo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22982, 'Questa affermazione è falsa. Come per la cintura, il casco deve essere indossato e allacciato PRIMA di partire con il motociclo. È fondamentale per la tua protezione fin dal primo istante in cui ti muovi.', 'Anche qui, ''dopo'' è la parola trappola. Il casco va messo ''prima''. ''può'' suggerisce una scelta, ma è un obbligo di legge.', 'Casco: prima di partire, non dopo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22983, 'Quando esci da un parcheggio in retromarcia, devi sempre controllare bene che non ci siano altri veicoli o persone sulla strada. È fondamentale fare la manovra con molta attenzione per non causare pericoli o incidenti.', 'Le espressioni ''assicurarsi che la strada sia libera'' e ''eseguire la manovra con prudenza'' sono concetti base di sicurezza. Non sono parole trappola, ma principi fondamentali da ricordare sempre.', 'Retromarcia = Occhi aperti e piano!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22984, 'Quando un veicolo (come il veicolo E) si muove per uscire da un parcheggio e vuole entrare nel traffico, deve sempre usare gli indicatori di direzione (le frecce). Questo serve a far capire agli altri conducenti dove intendi andare.', 'L''espressione ''azionare gli indicatori di direzione'' indica un''azione obbligatoria per segnalare ogni cambio di direzione o manovra. Non è una parola trappola, ma un dovere del conducente.', 'Ogni manovra = Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22985, 'Quando esci da un parcheggio in retromarcia per entrare nella circolazione, sei tu che devi dare la precedenza a tutti i veicoli che stanno già circolando sulla strada. Questo vale sia per i veicoli che vengono da destra che per quelli che vengono da sinistra.', 'La frase ''dare la precedenza a tutti i veicoli'' è la chiave. Non ci sono eccezioni quando ci si immette da un''area privata o da un parcheggio sulla strada pubblica.', 'Esci dal parcheggio = Tutti hanno la precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22986, 'Quando fai retromarcia, specialmente per uscire da un parcheggio, devi fare molta attenzione ai pedoni. I pedoni potrebbero passare dietro il tuo veicolo e potresti non vederli subito, quindi la prudenza è massima.', 'L''espressione ''fare attenzione agli eventuali pedoni'' è un punto cruciale. I pedoni sono utenti deboli della strada e vanno sempre tutelati.', 'Retromarcia = Occhio ai pedoni!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22987, 'Le quattro frecce (la segnalazione luminosa di pericolo) si usano solo in situazioni di emergenza, quando il veicolo è fermo e crea un pericolo, o in caso di guasto. Per una normale manovra di immissione nel traffico, si usano solo gli indicatori di direzione (una freccia alla volta), non le quattro frecce.', 'La frase ''segnalazione luminosa di pericolo (quattro frecce lampeggianti simultaneamente)'' è la parola trappola. Questa manovra non è considerata un''emergenza che richiede le quattro frecce.', 'Quattro frecce = Solo emergenza, non manovra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22988, 'Il clacson si usa solo per avvertire di un pericolo immediato e solo per il tempo strettamente necessario. Non si deve suonare il clacson per tutta la durata di una manovra, perché è vietato e disturba gli altri.', 'La frase ''durante l''intera manovra'' è la parola trappola. Il clacson non si usa in modo continuativo.', 'Clacson = Solo per pericolo, non per manovra lunga.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22989, 'Quando ti immetti nel traffico da un parcheggio, devi dare la precedenza a TUTTI i veicoli che circolano sulla strada, senza fare eccezioni. Le biciclette sono veicoli e hanno diritto alla precedenza come tutti gli altri.', 'La frase ''ad eccezione delle biciclette'' è la parola trappola. Non ci sono eccezioni per le biciclette in questo contesto; anche loro hanno la precedenza.', 'Immissione = Precedenza a TUTTI, bici incluse.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22990, 'Quando ti fermi con la macchina, devi sempre fare attenzione a non creare problemi o pericoli per gli altri veicoli o persone sulla strada. La sicurezza è la cosa più importante.', 'Le parole chiave sono ''senza creare pericolo o intralcio''. Significano che non devi mettere in pericolo nessuno e non devi bloccare la strada agli altri.', 'Fermati sicuro, non disturbare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22991, 'Prima di fermarti, devi guardare bene dove sono gli altri veicoli, quanto sono lontani e in che direzione vanno. Questo ti aiuta a fare la manovra in modo sicuro per tutti.', 'La frase ''tenere conto della posizione, distanza, direzione'' significa che devi osservare attentamente tutto ciò che ti circonda.', 'Guarda, valuta, poi frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22992, 'I veicoli a due ruote (moto e biciclette) sono più piccoli e a volte più difficili da vedere. Per questo, devi essere ancora più attento a non metterli in pericolo quando ti fermi.', 'La parte importante è ''evitare di creare pericolo ai conducenti di veicoli a due ruote''. Ricorda che sono più vulnerabili.', 'Occhio ai più piccoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22993, 'Devi sempre usare la freccia (indicatore di direzione) con un buon anticipo, così gli altri guidatori capiscono cosa vuoi fare e hanno il tempo di reagire. Non aspettare l''ultimo momento!', 'La parola ''sufficiente anticipo'' è fondamentale. Non basta segnalare, devi farlo in tempo utile.', 'Segnala sempre in tempo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22994, 'Frenare all''improvviso (brusca frenata) è pericoloso perché il veicolo dietro di te potrebbe non avere il tempo di frenare e tamponarti. Rallenta sempre in modo graduale.', 'Le parole ''brusche frenate'' indicano un''azione pericolosa da evitare. ''Garantire la sicurezza'' è l''obiettivo.', 'Frena dolcemente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22995, 'Per segnalare che vuoi fermarti, devi usare la freccia destra e tenerla accesa. ''Lampeggiare ripetutamente'' non è il modo corretto e può confondere gli altri guidatori. Si usa la freccia fissa, non a intermittenza veloce.', 'La frase ''lampeggiando ripetutamente'' è la trappola. Non si ''lampeggia'' più volte, ma si accende la freccia e la si tiene accesa.', 'Una freccia, non un concerto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22996, 'Le ''quattro frecce'' (segnalazione luminosa di pericolo) si usano quando il veicolo è già fermo e crea un pericolo, o in caso di emergenza. Per segnalare che stai per fermarti, devi usare solo la freccia destra.', 'La trappola è ''azionando la segnalazione luminosa di pericolo (quattro frecce)''. Le quattro frecce indicano un pericolo già esistente o un''emergenza, non l''intenzione di fermarsi.', 'Quattro frecce = pericolo già presente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22997, 'Anche se ci sono poche macchine (traffico scarso), devi sempre segnalare le tue intenzioni. È una regola di sicurezza e di comunicazione sulla strada, valida in ogni situazione.', 'Le parole ''può evitare di segnalare'' e ''se il traffico è scarso'' sono la trappola. Le regole di sicurezza valgono sempre, senza eccezioni per il traffico.', 'Segnala sempre, anche da solo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22998, 'Quando ti immetti nel traffico (ad esempio, partendo da un parcheggio o da un passo carrabile), devi sempre rispettare le regole, come dare la precedenza e usare l''indicatore di direzione. Se non lo fai, commetti un''infrazione che può comportare la perdita di punti dalla patente, oltre ad altre sanzioni.', 'La frase ''tra l''altro'' significa ''anche''. Questo indica che la perdita di punti è una delle conseguenze possibili, non l''unica.', 'Immissione nel traffico: massima attenzione, altrimenti perdi punti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (22999, 'Questa affermazione è falsa perché, come abbiamo visto nella domanda precedente, il mancato rispetto delle norme per immettersi nel flusso della circolazione comporta proprio la perdita di punti dalla patente. Non è vero che c''è solo la multa.', 'La parte ''non comporta la sottrazione di punti'' è la trappola. In realtà, la sottrazione di punti è una conseguenza prevista per queste infrazioni.', 'Immissione sbagliata = punti persi (e multa!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23000, 'Fare una fermata senza segnalare con l''indicatore di direzione (la freccia) è un errore e comporta una sanzione pecuniaria (una multa). Tuttavia, questa specifica infrazione non è considerata così grave da comportare la sottrazione di 4 punti dalla patente. La perdita di punti è prevista per infrazioni più pericolose o che mettono a rischio la sicurezza in modo significativo.', 'Il numero ''4 punti'' è la parola trappola. Non tutte le infrazioni comportano la perdita di punti, e quelle che lo fanno hanno un numero specifico. Una semplice fermata senza freccia non rientra tra quelle che fanno perdere punti.', 'Fermata senza freccia: multa sì, punti no (o comunque non 4).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23001, 'Gli specchi retrovisori (quelli laterali e quello centrale) ti aiutano a vedere cosa succede dietro e ai lati della tua auto, ampliando la tua visuale e permettendoti di avere una visione più completa della strada. Per questo, contribuiscono alla visione panoramica.', 'La frase "contribuiscono alla visione panoramica" significa che gli specchi aiutano a vedere di più, non che vedono tutto da soli. È un aiuto importante.', 'Specchi = occhi extra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23002, 'È fondamentale regolare bene lo specchio centrale per vedere chiaramente cosa c''è dietro la tua auto, così puoi guidare in sicurezza e avere sempre sotto controllo la situazione posteriore.', 'L''obiettivo è garantire una "buona visione posteriore", cioè una visuale chiara e sufficiente di ciò che accade dietro il veicolo.', 'Specchio centrale = finestra sul dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23003, 'Prima di regolare gli specchi, devi sistemare il sedile di guida nella posizione corretta per te. Se cambi la posizione del sedile, cambia anche la tua visuale e quindi dovrai regolare di nuovo gli specchi. La sequenza è importante per una regolazione efficace.', 'La parola chiave è "dopo che è stata regolata la posizione del sedile". Questo indica l''ordine corretto delle operazioni.', 'Prima sedile, poi specchi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23004, 'Regola lo specchio centrale in modo da vedere tutto il lunotto (il vetro posteriore dell''auto). Così hai la massima visuale possibile di ciò che accade dietro di te, riducendo i punti ciechi.', 'La frase "l''intero lunotto posteriore" indica che lo specchio deve coprire tutta l''area del vetro posteriore per una visione completa.', 'Centrale = tutto il lunotto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23005, 'Lo specchio centrale deve essere facile da guardare senza dover girare troppo la testa. Deve essere nel tuo campo visivo naturale mentre guidi, in modo da poterlo usare rapidamente e senza distrazioni.', 'La frase "rientrare nel campo visivo del conducente" significa che lo specchio deve essere facilmente visibile con un piccolo movimento degli occhi, senza dover spostare la testa.', 'Specchio centrale = a portata di sguardo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23006, 'Lo specchio centrale è fatto per mostrarti la distanza reale delle auto dietro di te, senza farle sembrare più lontane o più vicine di quanto siano. Questo è importante per valutare correttamente le distanze e guidare in sicurezza.', 'La frase "ridurre al minimo la distorsione" significa che lo specchio è progettato per essere il più preciso possibile nel mostrare le distanze.', 'Centrale = distanza vera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23007, 'Prima di girare (svoltare), devi sempre controllare gli specchi per assicurarti che non ci siano altre auto o moto che arrivano da dietro e che potresti tagliare la strada. Questo è fondamentale per evitare incidenti.', 'La parte cruciale è "prima di svoltare". Questo è uno dei momenti in cui il controllo degli specchi è obbligatorio.', 'Svolta = controlla dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23008, 'Molti specchi centrali hanno una levetta o un pulsante per cambiare la posizione e ridurre l''abbagliamento dei fari delle auto che ti seguono di notte. Questa funzione è molto utile per la sicurezza e il comfort visivo.', 'Le parole chiave sono "posizione antiriflesso" e "ore notturne". Indicano la funzione e il momento in cui usarla.', 'Notte = antiriflesso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23009, 'La funzione antiriflesso serve proprio a non farti abbagliare dai fari delle auto dietro di te quando è buio, rendendo la guida più sicura e confortevole. Riduce il fastidio agli occhi e ti permette di vedere meglio la strada.', 'La frase "ridurre il fastidio agli occhi causato dai proiettori accesi" spiega chiaramente lo scopo di questa funzione.', 'Antiriflesso = meno abbaglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23010, 'Quando parcheggi all''indietro, è fondamentale guardare negli specchi per vedere ostacoli, pedoni o altre auto che non vedi direttamente. Gli specchi ti danno una visuale completa della zona di manovra.', 'La frase "prima di iniziare una manovra di parcheggio in retromarcia" indica il momento in cui il controllo degli specchi è indispensabile.', 'Parcheggio indietro = specchi sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23011, 'Prima di sorpassare, devi controllare gli specchi per assicurarti che non ci sia nessuno che ti sta già sorpassando o che stia arrivando velocemente da dietro. Questo è un controllo di sicurezza essenziale.', 'La frase "prima di iniziare una manovra di sorpasso" sottolinea l''importanza del controllo preventivo.', 'Sorpasso = controlla dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23012, 'Non solo prima di sorpassare, ma anche durante e dopo il sorpasso, devi usare gli specchi per controllare quando puoi rientrare in sicurezza nella tua corsia. Il controllo continuo è fondamentale per tutta la manovra.', 'La frase "completare in sicurezza la manovra di sorpasso" evidenzia che gli specchi sono utili per tutta la durata del sorpasso, non solo all''inizio.', 'Sorpasso sicuro = specchi sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23013, 'Questa affermazione è falsa. La posizione antiriflesso serve proprio per la notte, per non essere abbagliati dai fari delle auto che seguono. Usarla di notte rende la guida più sicura e confortevole.', 'La parola "non" rende l''affermazione falsa. È il contrario: *deve* essere usata di notte.', 'Antiriflesso = per la notte (non il contrario).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23014, 'È falso. Puoi e devi usare la posizione antiriflesso anche in autostrada di notte, se i fari delle auto dietro ti danno fastidio. Non c''è nessuna regola che lo vieti, anzi, è consigliato per la sicurezza.', 'La frase "non può essere utilizzata" è la parte falsa. Si può usare ovunque sia necessario, inclusa l''autostrada.', 'Antiriflesso = ovunque serva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23015, 'È falso. Se vai dritto a un incrocio, di solito non è necessario controllare gli specchi retrovisori, a meno che tu non debba fare una manovra particolare (come cambiare corsia). Il controllo è più importante quando cambi direzione o fai manovre.', 'La frase "ogni volta che a un incrocio si intende proseguire diritto" è un''esagerazione. Non è sempre necessario, solo in casi specifici.', 'Dritto = non sempre specchi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23016, 'È falso. L''illuminazione interna (se presente) dello specchio retrovisore non è collegata alle luci di posizione. Di solito si accende con l''apertura delle portiere, con l''accensione delle luci interne dell''abitacolo o con un interruttore specifico.', 'La frase "si accende con l''accensione delle luci di posizione" è la parte sbagliata. Non c''è questo collegamento diretto.', 'Specchio illuminato = non con luci di posizione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23017, 'È falso. Le dimensioni degli specchi retrovisori dipendono dal tipo di veicolo e dalla necessità di garantire una buona visuale, non dalla cilindrata (la potenza del motore). Ogni veicolo ha specchi adatti alla sua struttura e funzione.', 'La parola "proporzionali alla cilindrata" è la relazione errata. Le dimensioni sono legate alla visibilità richiesta, non al motore.', 'Specchi = visuale, non motore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23018, 'È falso. Lo specchio centrale è obbligatorio, a meno che la visuale posteriore sia impedita (ad esempio da un carico molto grande) e il veicolo sia dotato di *due* specchi laterali (destro e sinistro). Non basta avere solo quello sinistro per rimuovere il centrale.', 'La condizione "se il veicolo è dotato di specchio laterale sinistro" è insufficiente per la rimozione del centrale. Servono entrambi i laterali e una visuale impedita.', 'Specchio centrale = obbligatorio (quasi sempre).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23019, 'È falso. I sensori di parcheggio sono un aiuto, ma non sostituiscono la tua vista e il controllo diretto con gli specchi. Devi sempre guardare per sicurezza, perché i sensori potrebbero non rilevare tutti gli ostacoli (es. un paletto sottile o un bambino piccolo).', 'La frase "non è necessario utilizzare gli specchi" è l''errore. I sensori sono un *aiuto*, non un *sostituto* degli occhi e degli specchi.', 'Sensori = aiuto, non sostituto degli specchi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23020, 'È falso. Anche con tutti gli specchi ben regolati, ci sono sempre delle "zone d''ombra" o "angoli ciechi" che non puoi vedere. Per questo è importante girare la testa e fare un controllo diretto (il cosiddetto ''colpo d''occhio'') prima di cambiare corsia o svoltare.', 'La frase "l''intera area" è un''esagerazione che rende l''affermazione falsa. Gli specchi non possono coprire *tutto*.', 'Specchi = quasi tutto, non tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23021, 'È falso. Tutti i veicoli, inclusi gli autocaravan, devono avere gli specchi retrovisori obbligatori per legge, anche se sono grandi. La sicurezza viene prima dell''ingombro e gli specchi sono essenziali per vedere cosa succede intorno al veicolo.', 'La frase "possono non essere dotati" è la parte falsa. Sono obbligatori per legge.', 'Autocaravan = specchi obbligatori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23022, 'È falso. La regolazione degli specchi deve essere fatta a veicolo fermo, prima di partire, per la tua sicurezza e per non distrarti mentre guidi. Regolarli in movimento è pericoloso.', 'La frase "con il veicolo in marcia" è la condizione sbagliata. La regolazione va fatta da fermo.', 'Regola specchi = veicolo fermo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23023, 'È falso. Gli specchi devono essere omologati e conformi alle norme. Non puoi sostituirli con qualsiasi tipo, anche se più grandi, se non sono specifici per il tuo veicolo o non rispettano le regole di omologazione. Modifiche non autorizzate sono vietate.', 'La condizione "purché di superficie maggiore" non è sufficiente. Devono essere omologati e adatti al veicolo.', 'Specchi = omologati, non a caso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23024, 'È falso. Non puoi circolare se mancano gli specchi retrovisori obbligatori, è pericoloso e contro la legge. Non ci sono eccezioni di velocità o segnalazioni che lo permettano. Un veicolo senza specchi obbligatori non è idoneo alla circolazione.', 'La frase "Si può circolare" è la parte falsa. Non si può circolare senza gli specchi obbligatori.', 'Senza specchi = non si circola.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23025, 'Per vedere bene cosa succede dietro e a lato, lo specchio laterale sinistro deve essere regolato in modo da vedere un piccolo pezzo della tua auto (la coda) nella parte più interna dello specchio. Questo ti aiuta a capire la posizione degli altri veicoli rispetto al tuo.', 'La frase ''nel suo terzo di destra'' si riferisce alla parte dello specchio più vicina alla tua auto. È lì che dovresti vedere un pezzo della tua coda.', 'Coda nel terzo interno = regolazione corretta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23026, 'Lo scopo principale dello specchio laterale è farti vedere la strada che sta a fianco e dietro la tua auto, specialmente i veicoli che ti stanno superando o che sono nel tuo angolo cieco. Deve mostrare soprattutto la strada.', '''Prevalentemente'' significa ''soprattutto''. Lo specchio serve principalmente a questo, non a guardare altro.', 'Specchio laterale = strada a fianco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23027, 'Molti specchi laterali sono convessi (curvi) per darti un campo visivo più ampio. Questa curvatura, però, fa sembrare i veicoli più lontani e più lenti di quanto non siano in realtà. È importante saperlo per non fare errori di valutazione.', '''Falsa la percezione'' significa che ti dà un''idea sbagliata. Non fidarti ciecamente della distanza che vedi.', 'Specchio laterale curvo = distanza inganna.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23028, 'Prima di spostarti a sinistra, devi sempre controllare lo specchio sinistro per assicurarti che non ci siano altri veicoli che stanno arrivando o che sono già nella corsia dove vuoi andare. È un controllo fondamentale per la sicurezza.', '''Prima di iniziare'' è fondamentale. Il controllo va fatto sempre in anticipo, non mentre stai già cambiando corsia.', 'Cambio corsia sinistra = specchio sinistro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23029, 'Prima di sorpassare, devi controllare lo specchio sinistro per vedere se qualcuno ti sta già superando o se c''è spazio sufficiente per la tua manovra. È il primo passo per un sorpasso sicuro.', 'Anche qui, ''prima di iniziare'' è la chiave. Il controllo precede l''azione.', 'Sorpasso = specchio sinistro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23030, 'Prima di girare a sinistra, devi controllare lo specchio sinistro per assicurarti che non ci siano veicoli, moto o biciclette che ti stanno affiancando o superando a sinistra. Questo evita collisioni in curva.', '''Svolta a sinistra'' richiede attenzione al lato sinistro, dove potresti avere veicoli nell''angolo cieco.', 'Svolta sinistra = specchio sinistro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23031, 'L''angolo cieco è quella zona intorno al veicolo che non puoi vedere né con gli specchi né guardando dritto. Gli specchi laterali, anche se utili, non coprono tutto e lasciano una zona ''cieca'' dove un veicolo potrebbe nascondersi. Per questo è importante girare la testa.', '''Angolo cieco'' è la zona non visibile. ''Molto ampio'' sottolinea l''importanza di fare attenzione e non fidarsi solo dello specchio.', 'Specchio laterale = angolo cieco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23032, 'Proprio per l''esistenza dell''angolo cieco, non basta guardare solo lo specchio. Prima di iniziare un sorpasso, devi anche girare un attimo la testa per controllare direttamente la zona laterale sinistra e assicurarti che non ci sia nessuno.', '''Integrato con un rapido controllo visivo laterale diretto'' significa che devi usare sia lo specchio che girare la testa. Non basta uno solo.', 'Specchio + testa = sicurezza sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23033, 'Quando parti da fermo (ad esempio da un parcheggio) e vuoi entrare nel traffico, devi fare molta attenzione. Controlla lo specchio sinistro e poi gira la testa per guardare direttamente, per essere sicuro che non ci siano ostacoli o veicoli in arrivo.', '''Immettere il veicolo nel flusso della circolazione'' significa entrare nel traffico. ''Nonché'' significa ''e anche'', quindi entrambi i controlli sono necessari.', 'Entrata traffico = specchio + sguardo diretto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23034, 'Lo specchio laterale sinistro serve per guardare la strada dietro e a lato del veicolo. Per controllare i bambini seduti dietro si usa lo specchio retrovisore centrale (quello interno), non quello laterale.', 'La parola chiave è ''laterale sinistro''. La sua funzione è esterna, non interna all''abitacolo.', 'Specchio laterale = strada. Specchio centrale = passeggeri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23035, 'Gli specchi retrovisori sono obbligatori e fondamentali per la sicurezza. Non devono mai essere chiusi mentre si guida, nemmeno su strade strette, perché ti servono per vedere cosa succede dietro e a lato.', '''Deve essere chiuso'' è l''errore. Gli specchi devono essere sempre aperti e utilizzabili durante la guida.', 'Specchi sempre aperti in marcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23036, 'Gli specchi retrovisori sono sempre necessari, in qualsiasi tipo di strada (città, autostrada, montagna). Ti aiutano a vedere gli altri veicoli, i pedoni, i ciclisti e a fare manovre in sicurezza. Non usarli è pericoloso.', '''Non è necessario'' è la trappola. Sono sempre necessari per la sicurezza, ovunque tu sia.', 'Specchi = sempre necessari.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23037, 'Questo è falso e pericoloso! Come abbiamo visto, è fondamentale integrare il controllo dello specchio con uno sguardo diretto (girando la testa) per eliminare l''angolo cieco. Non è una distrazione, ma una misura di sicurezza indispensabile.', '''Non controllare anche con uno sguardo diretto'' è l''errore. È proprio il contrario! Lo sguardo diretto è un''aggiunta di sicurezza.', 'Specchio + sguardo diretto = sicurezza massima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23038, 'Anche gli specchi delle moto e degli scooter sono regolabili. Devono essere regolati dal conducente per avere la migliore visuale possibile. Le vibrazioni non impediscono la regolazione, altrimenti sarebbero inutili.', '''Fissi e senza possibilità di regolazione'' è l''errore. Tutti gli specchi devono essere regolabili per adattarsi al conducente.', 'Specchi moto = regolabili.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23039, 'La regolazione degli specchi va fatta ogni volta che una persona diversa guida l''auto, o se la posizione del sedile viene cambiata. Non c''è una distanza in chilometri, ma dipende dalla posizione di guida del conducente.', '''Ogni mille chilometri circa'' è la trappola. La regolazione è legata al conducente e alla sua posizione, non alla distanza percorsa.', 'Regola specchi = ogni cambio conducente/sedile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23040, 'Anche se i poggiatesta posteriori possono limitare un po'' la visuale, lo specchio retrovisore centrale è comunque presente e utile per vedere cosa succede dietro l''auto. Non è ''inutilizzabile'', ma la sua efficacia può essere ridotta.', '''Non sono muniti'' e ''inutilizzabile'' sono le parole trappola. Lo specchio c''è e serve, anche se con qualche limitazione.', 'Specchio centrale = sempre presente e utile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23041, 'Lo specchio retrovisore centrale ha una sola funzione: farti vedere la strada dietro il veicolo. Non deve essere usato per altre cose, come un navigatore, perché distrarrebbe dalla guida e impedirebbe la sua funzione principale di sicurezza.', '''Può essere utilizzato come schermo per il navigatore'' è l''errore. Lo specchio ha una funzione specifica e non deve essere alterato.', 'Specchio centrale = solo per vedere dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23042, 'Il tram, essendo un veicolo su rotaia, ha quasi sempre la precedenza rispetto a tutti gli altri veicoli, a meno che non ci siano segnali specifici che indicano il contrario. In questo incrocio, non ci sono segnali che tolgano la precedenza al tram.', 'La frase ''rispetto agli altri veicoli'' è importante perché conferma che il tram ha la precedenza su tutti, senza eccezioni in questo caso.', 'Tram = Precedenza quasi sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23043, 'Indipendentemente dalle regole di precedenza, è sempre obbligatorio usare prudenza e attenzione quando si attraversa un incrocio. Questo è fondamentale per la sicurezza di tutti gli utenti della strada.', 'Le parole ''tutti i veicoli'' e ''devono usare prudenza'' sono affermazioni generali di buon senso e sicurezza stradale che valgono sempre.', 'Incrocio = Massima prudenza, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23044, 'Il veicolo O deve attendere il tram perché il tram ha la precedenza assoluta. Riguardo al veicolo A, anche se O ha la precedenza su A (perché O svolta a destra e A è alla sua sinistra), in un incrocio complesso è buona norma attendere che il veicolo A, che deve svoltare a sinistra, si posizioni al centro. Questo aiuta a gestire il flusso del traffico e a evitare intralci, garantendo maggiore sicurezza.', 'La frase ''che il veicolo A si porti al centro'' non riguarda la precedenza in senso stretto, ma la gestione dello spazio e la sicurezza nell''incrocio, specialmente quando un veicolo deve occupare il centro per svoltare a sinistra.', 'Svolta a sinistra = Occupazione centro. Sicurezza > Precedenza rigida.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23045, 'Come stabilito dalla regola generale, il tram ha la precedenza su tutti gli altri veicoli in questo incrocio, quindi è il primo a passare.', 'La frase ''transita per primo'' indica chiaramente l''ordine di passaggio e rafforza la regola della precedenza del tram.', 'Tram = Primo a passare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23046, 'Dopo il tram, il veicolo O ha la precedenza su M. Questo perché M si trova alla sinistra di O (o, più precisamente, O ha M alla sua sinistra). Quindi, M deve dare la precedenza a O e attendere il suo transito.', 'La frase ''deve attendere'' indica l''obbligo di dare precedenza. Ricorda la regola della destra.', 'O ha M a sinistra = O passa prima di M.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23047, 'Il veicolo M non può attraversare l''incrocio insieme al tram. Il tram ha la precedenza assoluta e M deve attendere che il tram sia passato. Inoltre, M deve attendere anche il veicolo O.', 'La parola ''insieme'' è la trappola. Nessun veicolo può passare contemporaneamente al tram se il tram ha la precedenza.', 'Tram solo = Nessuno insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23048, 'Il veicolo A sta svoltando a sinistra. Anche se non ha un veicolo immediatamente alla sua destra all''inizio, deve comunque dare la precedenza al veicolo M che proviene dalla direzione opposta e va dritto. Durante la manovra di svolta, M si troverà alla sua destra, quindi la destra non è ''libera'' nel senso di non avere veicoli a cui dare precedenza.', 'La frase ''ha la destra libera'' è la trappola. La destra non è libera se ci sono veicoli a cui dare precedenza durante la manovra, anche se non sono immediatamente visibili all''inizio.', 'Svolta a sinistra = Dai precedenza a chi viene di fronte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23049, 'Il veicolo O deve attendere solo il tram, perché il tram ha la precedenza assoluta. Il veicolo M, invece, deve dare la precedenza a O (O ha M alla sua sinistra), quindi O non deve attendere M.', 'La congiunzione ''ed'' che lega ''il tram'' e ''il veicolo M'' è la trappola. O non aspetta M.', 'O > M.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23050, 'Il veicolo O deve attendere solo il tram. O ha la precedenza su M e A, quindi non deve attendere che transitino tutti gli altri veicoli.', 'La frase ''tutti gli altri veicoli'' è la trappola. O non è l''ultimo a passare.', 'O non è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23051, 'Il veicolo A deve dare la precedenza al tram (come tutti). Inoltre, A deve dare la precedenza anche al veicolo M, perché M proviene dalla direzione opposta e va dritto, mentre A svolta a sinistra.', 'La frase ''ma non al veicolo M'' è la trappola. A deve dare precedenza a M.', 'Svolta a sinistra = Dai precedenza a chi viene di fronte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23052, 'Il veicolo O deve dare la precedenza solo al tram. Non deve dare la precedenza al veicolo M, perché O ha la precedenza su M (M si trova alla sinistra di O).', 'La congiunzione ''ed'' che lega ''il tram'' e ''il veicolo M'' è la trappola. O non dà precedenza a M.', 'O > M.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23053, 'In questo incrocio, il veicolo B passa per primo. Questo significa che B non deve aspettare nessun altro veicolo per passare. Gli altri veicoli (C e H) devono aspettare che B sia passato.', 'La frase ''non deve dare la precedenza'' significa che il veicolo ha il diritto di passare per primo, senza aspettare.', 'B è il primo a passare, quindi non dà precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23054, 'L''ordine di passaggio è B, poi H, e infine C. Quindi, dopo che B è passato, tocca a H. Per questo H passa per secondo.', 'La parola ''secondo'' indica la posizione nell''ordine di passaggio.', 'B primo, H secondo, C ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23055, 'Il veicolo C sta svoltando a sinistra e ha il veicolo H alla sua destra. Inoltre, in questo tipo di incrocio con un ''anello di precedenza'', chi svolta a sinistra è spesso l''ultimo. L''ordine è B, poi H, e infine C. Quindi C passa per ultimo.', 'La frase ''disimpegnare l''incrocio per ultimo'' significa che deve attraversare l''incrocio dopo tutti gli altri.', 'C svolta a sinistra, quindi è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23056, 'Il veicolo B non ha nessuno alla sua destra che possa passare prima. Il veicolo C ha H alla sua destra, e H ha B alla sua destra. In questa situazione, B è il primo a passare, poi H, e infine C.', 'La frase ''passa per primo'' indica che ha la precedenza assoluta in quel momento.', 'B non ha nessuno alla sua destra che lo blocca, quindi passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23057, 'Il veicolo C sta svoltando a sinistra. Quando si svolta a sinistra, si deve dare la precedenza ai veicoli che vengono dalla direzione opposta o dalla propria destra e che vanno dritto o svoltano a destra. Il veicolo H è alla destra di C e va dritto, quindi C deve dargli la precedenza.', 'La frase ''deve dare la precedenza'' significa che deve aspettare l''altro veicolo.', 'C svolta a sinistra, H è alla sua destra: C aspetta H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23058, 'Come abbiamo visto, il veicolo B passa per primo. Il veicolo H passa per secondo. Quindi, l''affermazione che H passa per primo è falsa.', 'Attenzione a ''per primo'': solo un veicolo può essere il primo.', 'H non è il primo, B lo è.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23059, 'I veicoli B e C non possono passare contemporaneamente perché si trovano in un incrocio dove ci sono regole di precedenza. B ha C alla sua destra, e C ha H alla sua destra. C''è un ordine preciso da seguire (B, poi H, poi C), non possono passare insieme.', 'La parola ''contemporaneamente'' è una trappola: in un incrocio con precedenze, raramente due veicoli passano insieme se le loro traiettorie si incrociano.', 'Mai contemporaneamente se c''è un conflitto di precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23060, 'L''ordine di passaggio corretto è B, poi H, e infine C. Questo significa che H passa dopo B, ma prima di C. Quindi, l''affermazione che H deve aspettare sia B che C è falsa.', 'La frase ''dopo il passaggio dei veicoli B e C'' implica che H sia l''ultimo, ma H è il secondo.', 'H passa tra B e C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23061, 'Il tipo di veicolo (autobus, auto, moto) non dà automaticamente la precedenza in un incrocio normale senza segnaletica specifica. Le regole di precedenza si basano sulla posizione dei veicoli e sulla direzione che prendono, non sul loro essere autobus o auto.', 'La frase ''in quanto è un autobus'' è una trappola. Il tipo di veicolo non conta per la precedenza in questo caso.', 'Il tipo di veicolo non dà precedenza (a meno di segnali specifici).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23062, 'Il veicolo C è l''ultimo a passare in questo incrocio, perché sta svoltando a sinistra e ha il veicolo H alla sua destra. Quindi, l''affermazione che C passa per primo è falsa.', 'Attenzione a ''per primo'': C è l''ultimo, non il primo.', 'C è l''ultimo, non il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23063, 'In questo incrocio senza segnali, la regola generale sarebbe ''dare precedenza a destra''. Tuttavia, per questo specifico tipo di incrocio a ''T'' presente nei quiz, il veicolo R (rosso) è spesso considerato quello che passa per primo, come se fosse sulla strada principale. È un''interpretazione particolare del quiz.', 'La frase ''Secondo le norme di precedenza'' qui va interpretata nel contesto specifico di questo quiz, che non sempre segue alla lettera la regola generale per tutti i veicoli.', 'R è il ''capo'' in questo incrocio anomalo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23064, 'Il veicolo C (blu) deve dare la precedenza sia ad A che a R. Questo perché, in questo tipo di incrocio, la strada da cui arriva C è spesso considerata come un''immissione o una strada secondaria, anche se non ci sono segnali. Per questo motivo, C passa per ultimo.', '''deve passare per ultimo'' indica chiaramente la posizione finale di C nella sequenza di precedenza.', 'C è l''ultimo, viene da una ''strada minore''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23065, 'Il veicolo A (giallo) deve passare dopo R (rosso). Questo perché, come abbiamo visto, R è il primo a liberare l''incrocio. Dopo che R ha completato la sua manovra, tocca ad A.', '''dopo il veicolo R'' indica la sequenza temporale di passaggio tra i veicoli.', 'A segue R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23066, 'Il veicolo A (giallo) passa prima di C (blu). Questo perché C deve dare la precedenza ad A (e a R), essendo considerato su una strada secondaria o un''immissione, come spiegato in precedenza.', '''prima del veicolo C'' indica che A precede C nella sequenza di passaggio.', 'A precede C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23067, 'Il veicolo C (blu) deve passare dopo entrambi i veicoli R (rosso) e A (giallo). Questa affermazione conferma che C è l''ultimo a passare in questo incrocio, aspettando che gli altri due veicoli abbiano liberato la loro traiettoria.', '''dopo i veicoli R e A'' sottolinea la posizione finale di C nella sequenza di precedenza.', 'C aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23068, 'Se il veicolo A è della polizia e ha i dispositivi di allarme (sirena e luci blu) accesi, ha la precedenza assoluta su tutti gli altri veicoli, indipendentemente dalle normali regole dell''incrocio. I mezzi di soccorso in servizio urgente hanno sempre la precedenza.', '''se è della polizia con i dispositivi di allarme in funzione'' è la condizione speciale che annulla tutte le altre regole di precedenza.', 'Mezzi di soccorso con sirena = precedenza assoluta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23069, 'Il veicolo A (giallo) non passa per primo. Secondo l''interpretazione di questo quiz, il veicolo R (rosso) passa per primo, poi A, e infine C.', '''passa per primo'' è la parola chiave che rende l''affermazione falsa, perché il primo a passare è R, non A.', 'Non è A il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23070, 'Il veicolo A (giallo) non passa per ultimo. Il veicolo che passa per ultimo in questo incrocio è C (blu). A passa per secondo, dopo R.', '''deve passare per ultimo'' è la parola chiave che rende l''affermazione falsa, perché l''ultimo è C.', 'Non è A l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23071, 'Il veicolo R (rosso) non deve passare dopo il veicolo A (giallo). Al contrario, R passa prima di A, come stabilito dalla sequenza di precedenza per questo incrocio (R -> A -> C).', '''dopo il veicolo A'' è la parola chiave che rende l''affermazione falsa, perché R passa prima.', 'R non aspetta A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23072, 'Il veicolo R (rosso) non attraversa l''incrocio per secondo. Secondo l''interpretazione di questo quiz, R è il primo veicolo a passare nell''incrocio.', '''attraversare l''incrocio per secondo'' è la parola chiave che rende l''affermazione falsa, perché R è il primo.', 'R è il primo, non il secondo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23073, 'Il veicolo C (blu) non passa per secondo. C è il veicolo che passa per ultimo in questo incrocio, dopo R e A.', '''passa per secondo'' è la parola chiave che rende l''affermazione falsa, perché C è l''ultimo.', 'C è l''ultimo, non il secondo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23074, 'I veicoli C (blu) e R (rosso) non possono passare per primi e contemporaneamente. R passa per primo, ma C passa per ultimo. Inoltre, i loro percorsi si incrociano, quindi non possono attraversare l''incrocio nello stesso momento.', '''passano per primi e contemporaneamente'' rende l''affermazione falsa su due punti: non passano primi entrambi e non possono passare insieme se i percorsi si intersecano.', 'Mai due insieme se si incrociano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23075, 'Il veicolo L non ha nessun veicolo alla sua destra. Per la regola della precedenza a destra, chi non ha nessuno alla sua destra può attraversare l''incrocio per primo.', 'Nessuna parola trappola evidente. ''per primo'' indica semplicemente l''inizio della sequenza.', 'Destra libera = via libera!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23076, 'Il veicolo H ha il veicolo C alla sua destra, quindi deve aspettare C. A sua volta, C ha il veicolo L alla sua destra e deve aspettare L. Per questo motivo, H è l''ultimo ad attraversare l''incrocio.', '''per ultimo'' indica la fine della sequenza di attraversamento.', 'H ha C a destra, C ha L a destra. H aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23077, 'Questo è l''ordine corretto basato sulla regola della precedenza a destra. L non ha nessuno a destra, quindi va per primo. Poi C, che ha L alla sua destra, può andare quando L ha liberato l''incrocio. Infine H, che ha C alla sua destra, può andare quando C ha liberato l''incrocio.', '''consentito'' significa che è permesso, è l''ordine giusto.', 'L -> C -> H, la catena della precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23078, 'Il veicolo C ha il veicolo L alla sua destra, quindi deve aspettare che L passi. Il veicolo H ha il veicolo C alla sua destra, quindi H deve aspettare C. Per questo, C passa dopo L e prima di H.', '''dopo... ma prima'' specifica la posizione intermedia di C nella sequenza.', 'C è il ''mezzo'' della catena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23079, 'Il veicolo C ha il veicolo L alla sua destra. Per la regola della precedenza a destra, C deve dare la precedenza a L. Non possono attraversare contemporaneamente, uno deve aspettare l''altro.', 'La parola trappola è ''contemporaneamente'', che significa ''allo stesso tempo''. Non è possibile se c''è una precedenza.', 'Mai contemporaneamente se c''è precedenza a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23080, 'Questo ordine è sbagliato. H è l''ultimo ad attraversare, non il primo, perché ha C alla sua destra. L è il primo, non l''ultimo.', 'L''ordine proposto è completamente invertito rispetto alla regola della precedenza.', 'H ultimo, L primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23081, 'Anche questo ordine è sbagliato. H è l''ultimo ad attraversare, non il primo. L è il primo, non il secondo. L''ordine corretto è L, C, H.', 'L''ordine proposto è errato e non rispetta la precedenza.', 'H ultimo, L primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23082, 'L''ordine è sbagliato. Dopo L dovrebbe passare C, perché H ha C alla sua destra e C ha L alla sua destra. Quindi C passa prima di H.', 'L''ordine di C e H è invertito rispetto alla sequenza corretta.', 'L, poi C, poi H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23083, 'Questo ordine è sbagliato. L deve attraversare per primo perché non ha nessuno alla sua destra. C e H devono aspettare L.', 'L''ordine proposto è completamente errato, L è il primo a passare.', 'L è sempre il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23084, 'In questo incrocio senza segnali, si applica la regola della precedenza a destra. Il veicolo A non ha nessuno alla sua destra, quindi passa per primo. Tra E e B, il veicolo E ha il veicolo B alla sua destra, mentre il veicolo B ha il veicolo E alla sua destra. Questa è una situazione di ''blocco''. La regola per risolvere il blocco è che i veicoli che si trovano di fronte e devono svoltare a sinistra (come E e B) si incrociano senza darsi la precedenza a vicenda, ma devono comunque dare la precedenza a chi viene da destra. Tuttavia, in questi quiz, spesso si considera che il veicolo che ha la strada libera per primo (A) passa, e poi si risolve il blocco tra gli altri. Se E ha la precedenza su B (come indicato dalle risposte successive), allora l''ordine è A, poi E, e infine B. Quindi, E passa dopo A (vero) e B passa dopo E (vero).', 'La congiunzione ''e'' significa che entrambe le parti della frase devono essere vere affinché l''affermazione sia VERA. Attenzione alle situazioni di ''blocco'' negli incroci, dove la precedenza a destra può creare un circolo vizioso.', 'A è libero, passa. Tra E e B, E ha la precedenza su B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23085, 'Il veicolo A non ha nessun altro veicolo alla sua destra. Secondo la regola generale della precedenza a destra, chi non ha veicoli alla propria destra ha il diritto di precedenza e può passare per primo. Quindi, il veicolo A non deve dare la precedenza a nessun altro veicolo presente nell''incrocio.', 'La frase ''non deve dare la precedenza ad alcun veicolo'' significa che A ha la precedenza assoluta in questo contesto.', 'Destra libera = passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23086, 'Dopo che il veicolo A è passato, rimangono i veicoli E e B. Entrambi devono svoltare a sinistra. In una situazione di ''blocco'' come questa, dove E ha B alla sua destra e B ha E alla sua destra, la convenzione (spesso implicita nei quiz) è che il veicolo che si trova ''più avanti'' o che ha una traiettoria che ''taglia'' meno l''altro, o semplicemente per risolvere il blocco, uno dei due viene considerato prioritario. Le risposte successive confermano che E passa prima di B. Quindi, E ha diritto di precedenza su B.', 'Il ''diritto di precedenza'' indica chi può passare prima. In un incrocio a ''T'' o con svolte a sinistra che creano un blocco, la risoluzione non è sempre intuitiva solo con la ''destra''.', 'E su B: E passa prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23087, 'Basandoci sull''ordine di precedenza stabilito (A -> E -> B), il veicolo E passa prima del veicolo B (vero) e passa dopo il veicolo A (vero). Entrambe le condizioni sono soddisfatte, rendendo l''affermazione vera.', 'Anche qui la congiunzione ''ma'' richiede che entrambe le parti della frase siano vere. ''Prima di'' e ''dopo'' indicano l''ordine temporale di passaggio.', 'A -> E -> B: E è in mezzo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23088, 'Seguendo l''ordine di precedenza (A -> E -> B), il veicolo B è l''ultimo a passare. Prima passa A, poi E, e solo alla fine B può completare la sua manovra.', '''Per ultimo'' è un indicatore chiaro della posizione finale nell''ordine di passaggio.', 'B è l''ultimo, aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23089, 'Il veicolo B ha il veicolo E alla sua destra (prima che E passi) e deve dargli la precedenza (secondo l''ordine A -> E -> B). Quindi, l''affermazione che B non deve dare la precedenza ad alcun veicolo è falsa, perché deve darla ad E.', 'La negazione ''non deve'' è la parola trappola. B *deve* dare la precedenza a E.', 'B ha E a destra, quindi cede.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23090, 'Il veicolo A non ha nessuno alla sua destra, quindi ha la precedenza su tutti, inclusi B ed E. Pertanto, A non deve dare la precedenza al veicolo B, ma è il contrario: B deve aspettare A (e poi E).', 'La frase ''deve dare la precedenza'' è la chiave. A non deve darla a nessuno.', 'A è il primo, non cede.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23091, 'Secondo l''ordine di precedenza (A -> E -> B), il veicolo E passa prima del veicolo B. Questo significa che B deve dare la precedenza a E. Quindi, l''affermazione che B non deve dare la precedenza a E è falsa.', 'Ancora la negazione ''non deve''. B *deve* dare la precedenza a E.', 'B cede a E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23092, 'L''ordine di passaggio è A, poi E, e infine B. I veicoli A e B non passano contemporaneamente, né passano dopo il veicolo E. A passa prima di E, e B passa dopo E. Quindi l''affermazione è falsa.', '''Contemporaneamente'' e ''dopo il veicolo E'' sono le parole trappola. L''ordine è sequenziale e specifico.', 'Passano uno alla volta, non insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23093, 'L''ordine di passaggio è A, poi E, e infine B. I veicoli A e B non passano contemporaneamente. A passa prima di E, ma B passa dopo E. Quindi l''affermazione è falsa.', '''Contemporaneamente'' e ''prima del veicolo E'' sono le parole trappola. L''ordine è A, poi E, poi B.', 'Passano uno alla volta, non insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23094, 'Il veicolo R non ha nessun veicolo alla sua destra, quindi passa per primo. Tra i veicoli A e C, il veicolo A ha il veicolo C alla sua sinistra. Questo significa che A ha la precedenza su C. Quindi, l''ordine corretto di passaggio è R, poi A, e infine C. La frase dice che A passa dopo R (vero) e C passa dopo A (vero).', 'Le parole ''dopo il veicolo R'' e ''dopo il veicolo A'' sono importanti per capire la sequenza corretta dei veicoli.', 'L''ordine è R, A, C: chi non ha nessuno a destra va per primo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23095, 'Il veicolo R passa per primo perché non ha nessun veicolo alla sua destra. Poi, tra A e C, il veicolo A ha il veicolo C alla sua sinistra, quindi A ha la precedenza su C. Per questo, A passa prima di C ma dopo R, posizionandosi al secondo posto nell''ordine di passaggio.', 'Le espressioni ''prima del veicolo C'' e ''dopo il veicolo R'' indicano chiaramente la posizione intermedia del veicolo A nella sequenza.', 'A è in mezzo: dopo R, prima di C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23096, 'Il veicolo R è l''unico che non ha nessun altro veicolo alla sua destra. Secondo la regola generale della precedenza a destra, R può passare per primo senza dover dare la precedenza a nessun altro veicolo.', 'La frase ''non deve dare la precedenza ad alcun veicolo'' significa che il veicolo R è il primo a passare.', 'R è libero: nessuno a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23097, 'Il veicolo R passa per primo perché non ha nessun veicolo alla sua destra. Poi, il veicolo A ha il veicolo C alla sua sinistra, quindi A ha la precedenza su C. Questo significa che A passa prima di C. L''ordine corretto di passaggio è quindi R, A, C.', 'La sequenza ''nell''ordine: R, A, C'' è la chiave per capire la domanda e la risposta.', 'L''ordine è R, A, C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23098, 'Il veicolo C ha il veicolo A alla sua destra. Secondo la regola della precedenza a destra, C deve dare la precedenza ad A. Quindi, C non può passare per primo e deve aspettare che A passi.', 'La parte ''non deve dare la precedenza ad alcun veicolo'' è falsa, perché C deve darla al veicolo A.', 'C ha A a destra, deve aspettare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23099, 'Il veicolo R passa per primo, quindi A non può passare prima di R. Inoltre, A passa prima di C, non dopo C. La frase è sbagliata in entrambe le sue affermazioni.', 'Le espressioni ''prima del veicolo R'' e ''dopo il veicolo C'' sono entrambe errate rispetto all''ordine corretto di passaggio (R, A, C).', 'A non è né primo né ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23100, 'L''ordine corretto di passaggio è R, A, C. Il veicolo A ha la precedenza su C perché C si trova alla sinistra di A. Quindi A passa prima di C, non dopo. La sequenza proposta nella domanda è errata.', 'La sequenza ''nell''ordine: R, C, A'' è sbagliata perché inverte l''ordine di passaggio tra A e C.', 'Non R, C, A, ma R, A, C!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23101, 'Il veicolo R non ha nessun veicolo alla sua destra. Per questo motivo, è il primo a passare nell''incrocio, non l''ultimo.', 'L''affermazione ''passa per ultimo'' è la parte sbagliata della frase, in quanto R è il primo.', 'R è il primo, non l''ultimo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23102, 'Il veicolo R attraversa per primo perché non ha nessun veicolo alla sua destra. Successivamente, si crea un ''blocco'' tra i veicoli D, B e L. Il veicolo L, svoltando a sinistra, deve dare la precedenza sia a D che a B, quindi L aspetta. Tra D e B, il veicolo D ha la precedenza su B (perché B ha D alla sua destra). Quindi, l''ordine di attraversamento è R, poi D, poi B, e infine L. La domanda è VERA perché il veicolo D attraversa effettivamente dopo il veicolo R.', 'Nessuna parola trappola particolare in questa domanda, la sequenza è chiara.', 'R va, poi D.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23103, 'Il veicolo R attraversa per primo. Poi si crea un ''blocco'' tra D, B e L. Il veicolo L, svoltando a sinistra, deve dare la precedenza sia a D che a B, quindi L aspetta. Tra D e B, D ha la precedenza su B (perché B ha D alla sua destra). Quindi, l''ordine è R, poi D, poi B, e infine L. La domanda è VERA, ma la frase ''dopo l''attraversamento di tutti gli altri veicoli'' è una trappola linguistica. B attraversa dopo R e D, ma prima di L. La domanda è VERA perché L, dovendo svoltare a sinistra, aspetta tutti gli altri veicoli (R, D e B) prima di impegnare l''incrocio. Quindi B attraversa dopo R e D, e L aspetta B.', 'La frase ''tutti gli altri veicoli'' è la parola trappola. Non significa che B attraversa dopo L, ma dopo quelli che lo precedono (R e D), dato che L deve comunque aspettare B.', 'Chi svolta a sinistra aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23104, 'Il veicolo R è il primo ad attraversare l''incrocio. Questo perché, applicando la regola della precedenza a destra, il veicolo R non ha nessun altro veicolo alla sua destra. Quindi, può impegnare l''incrocio senza dare la precedenza a nessuno. La domanda è VERA.', 'Nessuna parola trappola particolare. La regola è diretta.', 'Nessuno a destra? Vai per primo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23105, 'Come spiegato in precedenza, l''ordine di attraversamento è R, poi D, poi B, e infine L. Il veicolo B attraversa dopo che R e D hanno già impegnato e liberato l''incrocio. La domanda è VERA.', 'Nessuna parola trappola particolare. La sequenza è chiara.', 'B segue R e D.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23106, 'Il veicolo R attraversa per primo. Il veicolo D attraversa per secondo. Il veicolo B attraversa per terzo. Quindi, B non può attraversare contemporaneamente a R (che va per primo) e non può attraversare prima di D (che va prima di B). La domanda è FALSA.', 'Le parole ''contemporaneamente'' e ''prima'' indicano una sequenza temporale specifica che non corrisponde alla realtà.', 'Uno alla volta, e D prima di B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23107, 'Il veicolo R è il primo ad attraversare l''incrocio. Il veicolo D è il secondo. Quindi, D non attraversa prima di tutti gli altri veicoli, perché R lo precede. La domanda è FALSA.', 'La parola ''prima'' è la trappola. D non è il primo.', 'R è il primo, non D.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23108, 'Il veicolo R è il primo ad attraversare l''incrocio, non deve dare la precedenza a nessuno. Quindi, non può attraversare ''dopo'' i veicoli B e D, che invece attraversano dopo di lui. La domanda è FALSA.', 'La parola ''dopo'' è la trappola. R va prima di tutti.', 'R è il primo, non l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23109, 'Il veicolo R è il primo ad attraversare l''incrocio, seguito da D, e poi da B. Quindi, B non attraversa ''prima'' degli altri veicoli, ma dopo R e D. La domanda è FALSA.', 'La parola ''prima'' è la trappola. B non è il primo.', 'B non è il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23110, 'VERO. In questo tipo di incrocio, dove tutti i veicoli svoltano a sinistra e si crea un ''carosello'' (ognuno ha un veicolo alla sua destra), l''ordine di passaggio è spesso risolto seguendo una sequenza che ''sblocca'' la situazione. L''ordine D, P, B, N è quello corretto, dove D inizia la sequenza.', 'Attenzione alla frase ''Secondo le norme di precedenza'': in questi casi di ''carosello'' la norma va interpretata in modo specifico per sbloccare la situazione circolare.', 'Carosello a sinistra? D, P, B, N! (Memorizza l''ordine).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23111, 'VERO. Seguendo l''ordine di passaggio corretto (D, P, B, N), il veicolo N è l''ultimo a passare l''incrocio.', 'La frase ''per ultimo'' indica la posizione finale nella sequenza di passaggio.', 'N è l''ultimo del carosello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23112, 'VERO. Nell''ordine di passaggio stabilito (D, P, B, N), il veicolo B passa dopo il veicolo P.', 'La parola ''dopo'' indica la successione temporale tra i veicoli.', 'P precede B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23113, 'VERO. Nell''ordine di passaggio corretto (D, P, B, N), il veicolo D è il primo a passare l''incrocio, sbloccando la situazione di ''carosello''.', 'La frase ''prima degli altri veicoli'' significa che D è il primo in assoluto a passare.', 'D apre il carosello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23114, 'VERO. Nell''ordine di passaggio corretto (D, P, B, N), il veicolo B passa prima del veicolo N.', 'La frase ''prima del'' indica che B ha la precedenza temporale su N.', 'B precede N.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23115, 'VERO. Nell''ordine di passaggio corretto (D, P, B, N), il veicolo N passa dopo il veicolo B.', 'La frase ''dopo il'' indica la successione temporale, confermando che N segue B.', 'N segue B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23116, 'VERO. Nell''ordine di passaggio corretto (D, P, B, N), il veicolo P passa prima del veicolo B.', 'La frase ''può passare prima'' indica che P ha la precedenza su B in questo specifico ordine.', 'P prima di B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23117, 'FALSO. L''ordine corretto di passaggio dei veicoli è D, P, B, N. L''ordine proposto (D, B, N, P) è diverso e quindi non corretto.', 'La frase ''seguente ordine'' richiede di controllare attentamente l''intera sequenza proposta.', 'L''ordine è D, P, B, N, non D, B, N, P.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23118, 'FALSO. L''ordine corretto di passaggio dei veicoli è D, P, B, N. L''ordine proposto (P, B, N, D) è diverso e non inizia con il veicolo corretto.', 'La frase ''seguente ordine'' richiede di controllare attentamente l''intera sequenza proposta, specialmente il primo veicolo.', 'L''ordine inizia con D, non con P.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23119, 'FALSO. I veicoli non passano contemporaneamente. Secondo l''ordine corretto (D, P, B, N), D passa per primo e N passa per ultimo, quindi in momenti diversi.', 'La parola ''contemporaneamente'' significa nello stesso momento. In questo incrocio, i veicoli passano uno alla volta in sequenza.', 'Mai contemporaneamente in un carosello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23120, 'FALSO. I veicoli non passano contemporaneamente. D passa per primo, mentre B passa solo dopo P, quindi in momenti diversi.', 'La parola ''contemporaneamente'' significa nello stesso momento. I veicoli passano in sequenza, non insieme.', 'Passano in sequenza, non insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23121, 'FALSO. Il veicolo P passa prima del veicolo B (questo è vero), ma non passa dopo il veicolo N. N è l''ultimo a passare, quindi P passa prima di N. La seconda parte dell''affermazione la rende falsa.', 'La congiunzione ''ma'' introduce una condizione che potrebbe rendere falsa l''intera affermazione. Controlla bene tutte le parti della frase.', 'P è prima di N.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23122, 'FALSO. Non passano indifferentemente. C''è un ordine preciso: D passa per primo, mentre B passa solo dopo P. Non possono passare per primi in modo casuale.', 'La parola ''indifferentemente'' significa che non c''è un ordine specifico tra loro, il che è falso in questo incrocio.', 'C''è un ordine preciso: D è il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23123, 'Il veicolo D passa per primo perché non ha nessun veicolo alla sua destra. Dopo D, la situazione si sblocca in modo che C passi, poi A, e infine H.', 'Attenzione alla frase ''nel seguente ordine'': indica una sequenza precisa che deve essere rispettata. Se anche un solo veicolo è fuori posto, l''affermazione è falsa.', 'D ha la destra libera, quindi parte. Poi C, A, H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23124, 'Guarda il veicolo A (giallo). Alla sua destra c''è il veicolo C (rosso). Quindi, la destra di A non è libera, è occupata da C.', 'La frase ''destra occupata'' significa che c''è un altro veicolo che arriva da quella direzione e che ha la precedenza su di te.', 'Se c''è un''auto a destra, la destra è occupata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23125, 'Il veicolo D passa per primo, mentre il veicolo C passa per secondo. Questo significa che D passa prima di C, quindi D ha la precedenza su C.', 'La frase ''ha la precedenza su'' significa che passa prima dell''altro veicolo.', 'D è il primo, C è il secondo. D precede C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23126, 'Il veicolo D non ha nessun altro veicolo alla sua destra. Per la regola della precedenza a destra, chi non ha nessuno a destra passa per primo.', 'La frase ''primo ad impegnare l''incrocio'' significa il primo a entrare nell''incrocio.', 'Destra libera = primo a passare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23127, 'Secondo l''ordine di passaggio corretto (D, C, A, H), il veicolo H è l''ultimo a passare.', 'La frase ''l''ultimo ad attraversare'' indica la posizione finale nella sequenza di passaggio.', 'H è l''ultimo della fila.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23128, 'Il veicolo D passa per primo perché ha la destra libera. Il veicolo C passa dopo D. Quindi, D non deve dare la precedenza a C, ma è il contrario: C deve aspettare D.', 'La frase ''deve dare la precedenza'' significa che deve aspettare l''altro veicolo.', 'Chi ha la destra libera non dà precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23129, 'Il veicolo D attraversa per primo, non C. C è il secondo a passare nell''ordine corretto.', 'La frase ''attraversa per primo'' indica il primo veicolo in assoluto a muoversi.', 'D è il primo, non C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23130, 'L''ordine di passaggio è D, C, A, H. Questo significa che C passa prima di A, quindi A non attraversa prima di C.', 'La frase ''prima del veicolo C'' indica che A dovrebbe precedere C, ma non è così.', 'C precede A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23131, 'L''ordine corretto è D, C, A, H. L''ordine proposto (C, A, H, D) è sbagliato perché D non è l''ultimo e C non è il primo.', 'La frase ''nel seguente ordine'' ti chiede di controllare attentamente ogni posizione nella sequenza.', 'D è il primo, H è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23132, 'L''ordine corretto è D, C, A, H. L''ordine proposto (H, A, C, D) è sbagliato perché H non è il primo e D non è l''ultimo.', 'La frase ''nel seguente ordine'' ti chiede di controllare attentamente ogni posizione nella sequenza.', 'D è il primo, H è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23133, 'Solo il veicolo D passa per primo. C passa per secondo e H passa per ultimo. Quindi, non sono C e H a passare per primi.', 'La frase ''passano per primi'' implica che più di un veicolo ha la precedenza assoluta, ma in questo caso è solo uno.', 'Solo D è il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23134, 'Il veicolo L passa per primo. Anche se sta svoltando a sinistra e ha il veicolo D alla sua destra, il veicolo D sta anch''esso svoltando a sinistra. In questo tipo di incrocio, L non ha veicoli alla sua destra che vanno dritto o svoltano a destra, quindi può iniziare la manovra per primo.', 'La frase ''passa per primo'' indica che L è il primo veicolo a muoversi nell''incrocio.', 'L gira a sinistra, D gira a sinistra. L non ha ''destra libera'' da chi va dritto o a destra, quindi passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23135, 'Il veicolo D è l''ultimo a passare. Deve dare la precedenza a L (che passa per primo) e poi ad A (che gli viene da destra e va dritto).', 'La frase ''l''ultimo a passare'' significa che D è il veicolo che si muove per ultimo nell''incrocio.', 'D aspetta tutti, è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23136, 'Dopo che il veicolo L ha liberato l''incrocio, i veicoli C e A possono passare contemporaneamente. Anche se C ha la precedenza su A (perché A ha C alla sua destra), in questo specifico contesto di quiz si considera che possano passare insieme se le loro traiettorie lo permettono dopo che L ha liberato l''incrocio.', 'La parola ''contemporaneamente'' significa nello stesso momento. ''Dopo il veicolo L'' indica la sequenza temporale.', 'Dopo L, C e A passano insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23137, 'Il veicolo A ha la precedenza sul veicolo D. Questo perché A va dritto, mentre D sta svoltando a sinistra. D ha il veicolo A alla sua destra, quindi D deve dare la precedenza ad A.', 'La frase ''ha la precedenza su'' significa che A passa prima di D.', 'A va dritto, D gira: A passa prima di D.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23138, 'Non è vero che passa per primo il veicolo più veloce. La precedenza negli incroci è stabilita dalle regole del Codice della Strada, non dalla velocità dei veicoli.', 'La parola ''più veloce'' è una trappola. La velocità non è un criterio per la precedenza.', 'La velocità non dà precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23139, 'Il veicolo A non passa per ultimo. A passa dopo L e contemporaneamente a C, ma prima di D. Quindi non è l''ultimo veicolo a muoversi.', 'La frase ''passa per ultimo'' è la parte falsa dell''affermazione.', 'A non è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23140, 'L''ordine di passaggio indicato (C, A, D, L) è sbagliato. Il veicolo L passa per primo, non C. L''ordine corretto è L, poi C e A insieme, e infine D.', 'La frase ''nel seguente ordine'' richiede di verificare l''intera sequenza. Se anche solo un veicolo è fuori posto, l''affermazione è falsa.', 'L è il primo, non C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23141, 'L''ordine di passaggio indicato (C, L, A, D) è sbagliato. Il veicolo L passa per primo, non C. Inoltre, C e A passano insieme, non separatamente in questa sequenza.', 'Anche qui, ''nel seguente ordine'' è la parte da controllare attentamente. L''ordine è completamente diverso da quello corretto.', 'L è il primo, non C. C e A vanno insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23142, 'Questa affermazione è falsa. I veicoli D e L non passano contemporaneamente (L passa per primo, D per ultimo). Inoltre, L passa prima di A, ma D passa dopo A, quindi non passano entrambi ''prima del veicolo A''.', 'Le parole ''contemporaneamente'' e ''prima del veicolo A'' sono entrambe trappole, perché non corrispondono alla realtà dei fatti per entrambi i veicoli.', 'D e L non insieme. D non passa prima di A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23143, 'Questo incrocio è un caso particolare, spesso chiamato ''incrocio ad anello'' o ''a catena'', dove tutti i veicoli hanno un altro veicolo alla loro destra. La sequenza di passaggio corretta da memorizzare per questo specifico diagramma è H, D, B, L. Quindi, l''affermazione è VERA.', 'L''ordine ''H, D, B, L'' è la chiave di questo quiz. Non cercare di applicare la regola della precedenza a destra in modo iterativo, perché in questo caso specifico porta a un blocco.', 'H-D-B-L: la sequenza da ricordare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23144, 'Secondo la sequenza di passaggio stabilita per questo incrocio (H, D, B, L), il veicolo H è il primo a transitare. Quindi, l''affermazione è VERA.', '''per primo'' indica chiaramente la posizione di H nella sequenza di passaggio.', 'H apre la strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23145, 'Nell''ordine di passaggio H, D, B, L, il veicolo B transita prima del veicolo L. Quindi, l''affermazione è VERA.', '''prima del veicolo L'' conferma la posizione di B nella sequenza.', 'B precede L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23146, 'Poiché il veicolo H passa per primo e il veicolo D passa dopo H, significa che D deve attendere il transito di H. Quindi, D deve dare la precedenza a H. L''affermazione è VERA.', '''deve dare la precedenza'' significa che D aspetta H, confermando l''ordine H, D.', 'D aspetta H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23147, 'Nell''ordine di passaggio H, D, B, L, il veicolo B transita prima del veicolo L. Questo significa che L deve attendere che B sia passato. Quindi, L deve dare la precedenza a B. L''affermazione è VERA.', '''deve dare la precedenza'' significa che L aspetta B, confermando l''ordine B, L.', 'L aspetta B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23148, 'Secondo la sequenza di passaggio H, D, B, L, il veicolo L è l''ultimo a transitare all''incrocio. Quindi, l''affermazione è VERA.', '''per ultimo'' indica la posizione finale di L nella sequenza.', 'L chiude la fila.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23149, 'Nell''ordine di passaggio H, D, B, L, il veicolo D transita prima del veicolo B. Quindi, l''affermazione è VERA.', '''prima del veicolo B'' conferma la posizione di D nella sequenza.', 'D precede B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23150, 'Il veicolo B passa per terzo nell''ordine H, D, B, L. Questo significa che deve attendere solo H e D, ma non L, perché L passa dopo di lui. Quindi, non deve attendere ''gli altri tre veicoli''. L''affermazione è FALSA.', 'La parola ''tutti'' o ''gli altri tre'' è la trappola. B passa prima di L, quindi non aspetta L.', 'B non è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23151, 'Il veicolo H passa per primo nell''ordine H, D, B, L. Questo significa che non deve attendere nessun altro veicolo. Quindi, l''affermazione è FALSA.', '''deve attendere'' è la parola trappola, perché H non attende nessuno.', 'H non aspetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23152, 'Nell''ordine di passaggio H, D, B, L, il veicolo D passa per secondo e il veicolo L passa per ultimo. Non transitano contemporaneamente. Quindi, l''affermazione è FALSA.', '''contemporaneamente'' è la parola trappola. C''è un ordine preciso, non un passaggio simultaneo.', 'Non contemporaneamente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23153, 'L''ordine corretto di passaggio per questo incrocio è H, D, B, L. La sequenza proposta (H, D, L, B) è diversa, inverte B e L. Quindi, l''affermazione è FALSA.', 'La trappola è l''inversione di ''L'' e ''B''. Ricorda l''ordine esatto: H, D, B, L.', 'Ricorda: B prima di L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23154, 'Il veicolo B, come si vede dalla freccia, prosegue diritto, non svolta a sinistra. Inoltre, ha precedenza sul veicolo L. Quindi, l''affermazione è FALSA per due motivi.', 'Doppia trappola: ''svolta a sinistra'' (B va dritto) e ''non ha diritto di precedenza su alcun veicolo'' (B precede L).', 'B va dritto e precede L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23155, 'La precedenza agli incroci non segnalati si basa sulla regola della ''precedenza a destra''. Anche se i veicoli L e D vanno diritto, L ha H alla sua destra e D ha B alla sua destra, quindi devono dare la precedenza. L''affermazione è FALSA.', 'La trappola è ''hanno la precedenza perché non effettuano svolte''. La direzione non è l''unico fattore; la regola della destra è fondamentale.', 'La destra comanda, non la direzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23156, 'In questo incrocio, il veicolo B entra e aspetta al centro. Questo permette al veicolo R di passare per primo. Dopo R, passano N e D. Quindi, N passa dopo R.', 'La parola ''dopo'' indica l''ordine in cui i veicoli attraversano l''incrocio.', 'R è il primo, N è dopo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23157, 'Il veicolo B, dopo aver aspettato al centro, completa la sua svolta per ultimo. Quindi, N passa prima di B.', 'La parola ''dopo'' è cruciale per capire la sequenza. B completa la manovra dopo N.', 'B aspetta, N passa prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23158, 'Il veicolo R passa per primo. Dopo R, passano N e D. Quindi, D passa dopo R.', 'La parola ''dopo'' indica l''ordine in cui i veicoli attraversano l''incrocio.', 'R è il primo, D è dopo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23159, 'Il veicolo B, che deve svoltare a sinistra, entra nell''incrocio e si ferma al centro per non bloccare il veicolo R. In questo modo, R può passare per primo.', 'La frase ''dopo che... si è spostato al centro'' spiega che B non passa subito, ma attende, permettendo a R di muoversi.', 'B aspetta al centro, R passa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23160, 'Dopo che il veicolo R è passato, i veicoli N e D possono attraversare l''incrocio insieme. Anche se N va dritto e D svolta a sinistra, in questo specifico caso del quiz passano contemporaneamente.', 'La parola ''contemporaneamente'' è la chiave: significa ''nello stesso momento''.', 'R primo, poi N e D insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23161, 'Il veicolo B deve svoltare a sinistra. Per non bloccare il traffico e permettere a R di passare, B entra nell''incrocio e aspetta al centro.', 'La frase ''deve fermarsi al centro'' indica un''azione obbligatoria per B.', 'B svolta a sinistra, aspetta al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23162, 'Il veicolo R va dritto. Non ha motivo di fermarsi al centro dell''incrocio, ma lo attraversa direttamente.', 'La frase ''si ferma al centro'' è la parola trappola: R non si ferma, ma prosegue dritto.', 'R va dritto, non si ferma.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23163, 'Il veicolo R passa per primo, non il veicolo N.', 'La frase ''per primo'' indica l''ordine di passaggio. N non è il primo.', 'R è il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23164, 'Il veicolo R passa per primo, non il veicolo D.', 'La frase ''per primo'' indica l''ordine di passaggio. D non è il primo.', 'R è il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23165, 'Il veicolo B, aspettando al centro, passa per ultimo. Quindi, D non deve dargli la precedenza per passare, perché D passa prima di B.', 'La frase ''deve dare la precedenza'' è la trappola. D passa prima di B.', 'B ultimo, D prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23166, 'Il veicolo B non deve dare la precedenza al veicolo D. B è a destra di D, ma in questo scenario B aspetta al centro e passa per ultimo. D non ha la precedenza su B.', 'La frase ''deve dare la precedenza'' è la trappola. B non dà precedenza a D.', 'B non dà precedenza a D.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23167, 'Il veicolo R passa per primo, non per ultimo.', 'La frase ''per ultimo'' è la trappola. R è il primo.', 'R è il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23168, 'Questo è un incrocio particolare dove, applicando la regola della precedenza a destra, si crea un "circolo vizioso" (ogni veicolo ha un altro alla sua destra, bloccandosi a vicenda). In questi casi, per convenzione nei quiz, il veicolo che svolta a sinistra (C) passa per primo per "sbloccare" l''incrocio. Poi, tra A e P, A passa prima di P. Quindi l''ordine corretto è C, A, P.', 'Attenzione all''espressione "nel seguente ordine": è fondamentale ricordare la sequenza esatta per questo tipo di incrocio.', 'C-A-P: Circolo Anomalo Precedenza. Ricorda l''ordine per questo incrocio ''bloccato''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23169, 'Sì, è vero. Secondo l''ordine di passaggio stabilito per questo incrocio ''bloccato'' (C, A, P), il veicolo C passa per primo, e solo dopo passa il veicolo A.', 'La parola chiave è "dopo": indica una sequenza temporale chiara.', 'C precede A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23170, 'Sì, è vero. Nell''ordine di passaggio C, A, P, il veicolo P è l''ultimo a passare l''incrocio.', 'L''espressione "per ultimo" significa che P è l''ultimo veicolo a transitare.', 'P chiude la fila.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23171, 'No, è falso. L''ordine corretto di passaggio per questo incrocio, secondo la convenzione dei quiz per i ''circoli viziosi'', è C, A, P. L''ordine P, C, A è sbagliato.', 'Controlla bene l''ordine proposto: "P, C, A" è l''opposto di quello corretto.', 'Non P-C-A, ma C-A-P.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23172, 'No, è falso. Il veicolo C passa per primo, mentre il veicolo P passa per ultimo. Quindi P non passa prima di C.', 'La frase "prima del veicolo C" è la parte da cui dipende la veridicità della domanda. In questo caso, è errata.', 'C precede P.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23173, 'No, è falso. Il veicolo P non passa per primo, ma per ultimo, secondo l''ordine C, A, P. Inoltre, in questo incrocio si crea un "circolo vizioso" (deadlock) dove la regola della "destra libera" non può essere applicata in modo semplice per determinare il primo veicolo a passare.', 'Le espressioni "per primo" e "perché ha la destra libera" sono entrambe errate per questo incrocio specifico.', 'P è l''ultimo, non il primo. La destra non è ''libera'' in un blocco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23174, 'In questo incrocio senza segnali, il veicolo C deve dare la precedenza al veicolo S perché S si trova alla sua destra. Quindi C aspetta S. Tra S e N, anche se S svolta a sinistra e N va dritto, in questa specifica configurazione di ''blocco'' (dove tutti aspettano qualcuno), il veicolo S procede per primo per ''sbloccare'' l''incrocio. Dopo S, il veicolo N può passare perché non ha più ostacoli alla sua destra. Infine, il veicolo C, che aspettava S, può passare per ultimo. L''ordine è quindi S, N, C.', '''nel seguente ordine'' - indica una sequenza precisa che deve essere rispettata. È importante memorizzare l''ordine esatto per questo tipo di incrocio.', 'Sblocca l''incrocio: S, N, C!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23175, 'Il veicolo C deve dare la precedenza al veicolo S perché S si trova alla sua destra. Questo significa che C non può passare per primo. Dopo che S e N sono passati, C può finalmente attraversare l''incrocio, quindi transita per ultimo.', '''per ultimo'' - significa che è l''ultimo veicolo ad attraversare l''incrocio. È la posizione corretta di C.', 'C ha S a destra, quindi C aspetta sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23176, 'Secondo l''ordine di passaggio corretto per questo incrocio (S, N, C), il veicolo N transita dopo il veicolo S (che è il primo) e prima del veicolo C (che è l''ultimo).', '''dopo... e prima'' - indica la posizione intermedia di N nella sequenza. Controlla bene l''ordine S, N, C.', 'N è in mezzo: dopo S, prima di C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23177, 'Questa affermazione è falsa perché il veicolo C non può passare per primo. C deve dare la precedenza al veicolo S che si trova alla sua destra. L''ordine corretto di passaggio è S, N, C.', '''C, N, S'' - l''ordine proposto è sbagliato, specialmente perché C è indicato come primo. Ricorda che C è l''ultimo.', 'C non è mai primo, ha S a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23178, 'Questa affermazione è falsa. Il veicolo N transita dopo S, ma prima di C. Non transita dopo C. L''ordine corretto è S, N, C.', '''dopo il veicolo C'' - questa parte rende l''affermazione falsa, perché N passa prima di C, non dopo.', 'N non aspetta C, N passa prima!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23179, 'Questa affermazione è falsa. Il veicolo C non può transitare per primo perché deve dare la precedenza al veicolo S, che si trova alla sua destra. C transita per ultimo.', '''per primo'' - questa espressione è la parola trappola, perché C è l''ultimo veicolo a passare.', 'C ha S a destra, mai per primo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23180, 'Il veicolo T è un tram. I tram hanno quasi sempre la precedenza su tutti gli altri veicoli (auto, moto, ecc.), a meno che non ci siano segnali specifici che indicano il contrario. In questa immagine non ci sono segnali che tolgono la precedenza al tram, quindi il tram T transita per primo.', 'La frase ''transita per primo'' significa che il veicolo T è il primo a passare attraverso l''incrocio, prima di tutti gli altri.', 'Tram = Precedenza quasi assoluta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23181, 'Analizziamo l''ordine di passaggio:1. Il veicolo T (il tram) passa per primo, come spiegato prima, perché ha la precedenza su tutti.2. Dopo il tram, il veicolo L (blu) va dritto. I veicoli A e C devono svoltare a sinistra e incrociano la sua traiettoria. Il veicolo L non ha nessun veicolo alla sua destra che deve dargli la precedenza. Quindi, L passa dopo il tram.3. Ora restano i veicoli A (giallo) e C (rosso), entrambi svoltano a sinistra. Normalmente, il veicolo C, essendo alla destra di A, avrebbe la precedenza su A. Tuttavia, in questo specifico contesto di quiz, l''ordine indicato (A prima di C) è considerato corretto. Questo può accadere in situazioni dove il veicolo più a sinistra (A) ha una traiettoria di svolta più ''interna'' o diretta, permettendogli di completare la manovra prima di C, che deve attendere per evitare incroci.', 'La frase ''nel seguente ordine: T, L ed A, infine C'' indica una sequenza precisa: prima T, poi L, poi A, e solo alla fine C. La parte ''ed A'' non significa che A passa insieme a L, ma che A è il prossimo dopo L. La ''parola trappola'' qui è l''ordine tra A e C, che in questo quiz va contro la regola generale della precedenza a destra.', 'Tram > Dritto. Tra chi svolta a sinistra affiancato, in questo quiz: A (sinistra) prima di C (destra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23182, 'Questo incrocio presenta una situazione di ''precedenza a destra'' circolare, dove tutti i veicoli hanno un altro veicolo alla loro destra, creando uno stallo. Per risolvere questo stallo, si segue un ordine convenzionale specifico: C, A, L, R, E. Quindi, l''affermazione è VERA.', 'La frase ''seguente ordine'' indica una sequenza precisa che deve essere memorizzata per questo tipo di incrocio.', 'C-A-L-R-E: la sequenza ''speciale'' per questo incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23183, 'Secondo l''ordine di transito stabilito per questo incrocio (C, A, L, R, E), il veicolo C è il primo a impegnare e liberare l''incrocio. Questo ''rompe'' lo stallo iniziale.', 'La parola ''per primo'' sottolinea che C è il veicolo che inizia la sequenza di passaggio.', 'C apre la strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23184, 'Una volta che il veicolo C ha attraversato l''incrocio, il veicolo A non ha più nessuno alla sua destra (C è passato) e può quindi procedere. Questo lo rende il secondo veicolo a transitare, subito dopo C.', 'L''espressione ''subito dopo'' indica una successione immediata nella sequenza di transito.', 'C libera A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23185, 'Nell''ordine di transito C, A, L, R, E, il veicolo E è l''ultimo a passare. Questo significa che deve attendere che tutti gli altri veicoli (C, A, L, R) abbiano liberato l''incrocio, inclusi R e L. Quindi, E deve dare la precedenza a R e L.', 'La frase ''deve dare la precedenza'' significa che il veicolo deve aspettare il passaggio degli altri.', 'E è l''ultimo, aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23186, 'Analizzando l''ordine di transito C, A, L, R, E, si vede chiaramente che il veicolo A transita come secondo, mentre il veicolo L transita come terzo. Quindi, A passa prima di L.', 'L''espressione ''prima del'' indica la posizione relativa di un veicolo rispetto a un altro nella sequenza.', 'A precede L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23187, 'Secondo l''ordine di transito C, A, L, R, E, il veicolo L transita come terzo, mentre il veicolo R transita come quarto. Di conseguenza, L passa prima di R.', 'Anche qui, ''prima del'' è la parola chiave per capire la relazione temporale tra i passaggi.', 'L precede R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23188, 'Nell''ordine di transito C, A, L, R, E, il veicolo A transita come secondo e il veicolo L transita come terzo. Questo significa che L passa dopo A.', 'L''espressione ''dopo il'' indica che un veicolo segue l''altro nella sequenza di transito.', 'L segue A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23189, 'Il veicolo A sta svoltando a sinistra, mentre il veicolo E procede dritto. Secondo la regola generale della precedenza, un veicolo che svolta a sinistra deve dare la precedenza ai veicoli provenienti dalla direzione opposta che vanno dritto o svoltano a destra. Quindi, è il veicolo A che deve dare la precedenza a E, non il contrario. Per questo motivo, l''affermazione che E deve dare la precedenza ad A è FALSA.', 'La frase ''deve dare la precedenza'' qui si riferisce alla regola generale di precedenza per le svolte a sinistra, che prevale sull''ordine di passaggio stabilito per risolvere lo stallo.', 'Svolta a sinistra (A) cede a dritto (E).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23190, 'L''ordine corretto di transito per risolvere lo stallo in questo incrocio è C, A, L, R, E. L''ordine proposto (E, C, A, L, R) è diverso e quindi sbagliato.', 'La frase ''seguente ordine'' richiede di conoscere la sequenza esatta. Qualsiasi variazione rende l''affermazione FALSA.', 'Ricorda C-A-L-R-E, non E-C-A-L-R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23191, 'Secondo l''ordine di transito C, A, L, R, E, il veicolo A transita come secondo, mentre il veicolo E transita per ultimo. Questo significa che A passa molto prima di E e non deve attendere il suo passaggio.', 'L''espressione ''deve attendere'' implica un''attesa che non è necessaria in questo caso, dato l''ordine di transito.', 'A precede E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23192, 'È vietato impegnare un incrocio se non si ha la certezza di poterlo sgomberare completamente. Fermarsi al centro dell''incrocio blocca il traffico e crea pericolo. Bisogna sempre attendere di avere spazio sufficiente per attraversare.', 'Le parole ''qualunque veicolo'' e ''fermarmi al centro'' indicano un comportamento pericoloso e non consentito in un incrocio.', 'Non bloccare l''incrocio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23193, 'L''ordine di transito è C, A, L, R, E. Questo significa che C transita per primo, A transita per secondo e R transita per quarto. Non solo C e R non transitano contemporaneamente, ma C transita prima di A, e R transita dopo A. Quindi l''affermazione è FALSA.', 'Le parole ''contemporaneamente'' e ''dopo il passaggio del veicolo A'' sono i dettagli da verificare attentamente rispetto alla sequenza corretta.', 'C, A, L, R, E è una sequenza, non contemporaneità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23194, 'Il veicolo A non ha nessun altro veicolo alla sua destra, quindi passa per primo. Dopo che A ha liberato l''incrocio, gli altri veicoli (E, V, H, C) seguono un ordine specifico: prima E, poi V, poi H, e infine C. Questo significa che E ha la precedenza su V, V su H e H su C.', '"disimpegnano l''incrocio" significa che i veicoli lo attraversano e lo lasciano libero.', 'A è libero, poi E, V, H, C in sequenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23195, 'Secondo l''ordine di passaggio corretto per questo incrocio (A, E, V, H, C), il veicolo V passa prima del veicolo H. Quindi, V ha la precedenza su H.', '"ha la precedenza su" significa che passa prima di un altro veicolo.', 'V prima di H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23196, 'Secondo l''ordine di passaggio corretto (A, E, V, H, C), il veicolo H passa prima del veicolo C. Per questo motivo, C deve aspettare che H sia passato, cioè deve dargli la precedenza.', '"deve dare la precedenza" significa che deve fermarsi o rallentare per far passare l''altro veicolo.', 'C aspetta H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23197, 'Analizzando l''ordine corretto (A, E, V, H, C), vediamo che E passa prima di V, e V passa prima di H. Di conseguenza, il veicolo E passa prima del veicolo H.', '"passa prima" indica che ha il diritto di attraversare l''incrocio per primo rispetto all''altro.', 'E -> V -> H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23198, 'L''ordine di passaggio stabilito è A, E, V, H, C. Questo significa che il veicolo H passa solo dopo che A, E e V hanno già attraversato l''incrocio.', '"passa dopo" significa che deve aspettare che gli altri veicoli siano transitati.', 'H è l''ultimo tra A, E, V, H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23199, 'Il veicolo A non ha nessun altro veicolo alla sua destra che debba dargli la precedenza. Per la regola generale della precedenza a destra, A è il primo a poter attraversare l''incrocio.', '"passa per primo" significa che è il veicolo che ha la precedenza assoluta in quel momento.', 'A è libero, va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23200, 'L''ordine corretto di passaggio per questo incrocio è A, E, V, H, C. L''ordine proposto (A, H, C, E, V) è diverso, in particolare la sequenza di H, C, E, V è sbagliata rispetto all''ordine corretto.', '"nel seguente ordine" richiede una sequenza precisa e non modificabile.', 'L''ordine è A, E, V, H, C, non A, H, C, E, V.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23201, 'L''ordine corretto di passaggio è A, E, V, H, C. L''ordine proposto (A, E, C, V, H) è sbagliato perché il veicolo C non passa prima di V e H, ma dopo di loro.', '"nel seguente ordine" indica una sequenza specifica che deve essere rispettata.', 'L''ordine è A, E, V, H, C, non A, E, C, V, H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23202, 'Secondo l''ordine corretto (A, E, V, H, C), il veicolo V passa dopo A ed E, ma *prima* di H. Quindi, V non deve attendere H, ma è H che deve attendere V.', '"deve attendere" significa che deve dare la precedenza. Qui è il contrario.', 'V passa prima di H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23203, 'In un incrocio con regole di precedenza, i veicoli non possono passare contemporaneamente se le loro traiettorie si incrociano. Devono rispettare un ordine preciso per evitare incidenti.', '"contemporaneamente" significa nello stesso momento. Questo è quasi sempre falso negli incroci.', 'Mai contemporaneamente se c''è conflitto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23204, 'L''ordine corretto di passaggio è A, E, V, H, C. Questo significa che il veicolo V passa prima di H e C, non dopo di loro.', '"passa dopo" significa che deve aspettare. In questo caso, V non aspetta C e H.', 'V passa prima di H e C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23205, 'I veicoli L e H non hanno il segnale di "Dare precedenza", quindi passano prima di B e O. Le loro traiettorie non si incrociano, quindi possono passare nello stesso momento senza ostacolarsi.', '"contemporaneamente" significa "nello stesso momento". È importante capire che non si ostacolano a vicenda.', 'L e H: strade libere, passano insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23206, 'L e H passano per primi perché non hanno segnali di "Dare precedenza" e le loro strade non si incrociano. Poi passa B, che deve dare precedenza a L e H, ma non ha nessuno alla sua destra tra i veicoli rimasti (O). Infine passa O, che deve dare precedenza a L, H e anche a B.', '"nel seguente ordine" indica una sequenza precisa di passaggio.', 'L&H (insieme), poi B, poi O. O è sempre l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23207, 'Il veicolo B ha il segnale di "Dare precedenza", quindi deve aspettare che passino i veicoli L e H, che non hanno questo segnale e quindi hanno la precedenza.', '"dopo" indica una successione temporale. B passa dopo L e H.', '"Dare precedenza" = aspetti chi non ce l''ha.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23208, 'Il veicolo O ha il segnale di "Dare precedenza" e deve cedere il passo a tutti gli altri veicoli (L, H e B). Per questo motivo, transita per ultimo.', '"per ultimo" significa che è l''ultimo in ordine di passaggio.', 'O ha "Dare precedenza" e L alla destra: ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23209, 'Il veicolo B ha il segnale di "Dare precedenza", quindi passa dopo L e H. Tra B e O, B passa prima perché, una volta che L e H sono passati, B non ha più ostacoli alla sua destra, mentre O deve ancora aspettare B.', '"prima del" e "dopo i" indicano l''ordine di passaggio. Attenzione a non confonderli.', 'B: dopo L&H, prima di O.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23210, 'Il veicolo O ha il segnale di "Dare precedenza", il che significa che deve cedere il passo a tutti gli altri veicoli che si trovano nell''incrocio, cioè L, H e B.', '"a tutti gli altri veicoli" è una generalizzazione corretta in questo caso, perché O è l''ultimo a passare.', 'O con "Dare precedenza" = cede a tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23211, 'Il veicolo O ha il segnale di "Dare precedenza" e passa per ultimo. Il veicolo H, invece, passa tra i primi (con L). Quindi O non può transitare prima di H.', '"prima del" è la parola chiave. O non passa prima di H.', 'O è ultimo, H è primo: O non può essere "prima di H".')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23212, 'Il veicolo O ha il segnale di "Dare precedenza" e passa per ultimo. Il veicolo H, invece, passa tra i primi. Quindi O non può transitare prima di H.', '"prima del" è la parola chiave. O non passa prima di H.', 'O è ultimo, H è primo: O non può essere "prima di H".')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23213, 'Il veicolo B ha il segnale di "Dare precedenza", quindi deve aspettare che passino L e H. Per questo motivo, B non può transitare per primo.', '"per primo" è la parola trappola. B non è il primo a passare.', 'B ha "Dare precedenza" = non è mai primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23214, 'Il veicolo H passa tra i primi (con L), mentre il veicolo O passa per ultimo. Quindi H transita molto prima di O, non dopo.', '"dopo il" è la parola trappola. H non passa dopo O.', 'H è primo, O è ultimo: H non è "dopo O".')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23215, 'L''ordine corretto di passaggio è L e H (insieme), poi B, e infine O. L''ordine proposto (B, L, O, H) è completamente sbagliato, perché B e O hanno il segnale di "Dare precedenza" e quindi non possono passare per primi, e H non è l''ultimo.', '"nel seguente ordine" richiede di verificare l''intera sequenza. Se anche solo un veicolo è fuori posto, la risposta è FALSO.', 'L&H (insieme), B, O. Qualsiasi altro ordine è FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23216, 'Il veicolo O ha il segnale di "Dare precedenza" e transita per ultimo, non per primo. Inoltre, non deve fermarsi al centro dell''incrocio, ma attendere fuori dall''incrocio finché non può attraversare in sicurezza.', '"per primo" e "si ferma al centro di esso" sono entrambe affermazioni false. O è l''ultimo e non si ferma al centro.', 'O è ultimo, non primo; non si ferma al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23217, 'Il veicolo S non ha il segnale di "Dare precedenza", mentre il veicolo R sì. Questo significa che S ha la precedenza su R. Inoltre, S è il primo veicolo a transitare in assoluto nell''incrocio.', '"prima del veicolo R" - indica un ordine specifico di transito.', 'S senza triangolo, R con triangolo: S passa prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23218, 'Il veicolo S non ha il segnale di "Dare precedenza" e non ha nessun veicolo alla sua destra che abbia la precedenza. Per questo motivo, S è il primo a poter attraversare l''incrocio, prima di tutti gli altri.', '"prima di tutti gli altri veicoli" - sottolinea l''assoluta priorità di S.', 'S è libero a destra e senza segnale: passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23219, 'L''ordine corretto è: S (non ha segnale e non ha nessuno a destra), poi A (dopo S non ha più nessuno a destra e ha precedenza su E e R), poi E (ha il segnale ma R, che è alla sua destra, deve svoltare a sinistra e quindi gli dà la precedenza), e infine R (ha il segnale e deve dare precedenza a E).', '"nell''ordine: S, A, E, R" - indica una sequenza precisa e corretta.', 'Senza triangolo e libero a destra (S), poi A, poi E (diritto), infine R (svolta sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23220, 'Il veicolo S si trova alla destra del veicolo A e non ha il segnale di "Dare precedenza". Per la regola generale della precedenza a destra, A deve dare la precedenza a S.', '"deve dare la precedenza" - indica un obbligo per il veicolo A.', 'S è a destra di A: A dà precedenza a S.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23221, 'Il veicolo R ha il segnale di "Dare precedenza" e, tra i veicoli che devono dare precedenza (E e R), R deve anche dare precedenza a E perché E va diritto mentre R svolta a sinistra. Per questo R è l''ultimo a passare.', '"per ultimo" - indica la posizione finale nella sequenza di transito.', 'R ha il triangolo e svolta a sinistra: passa per ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23222, 'Il veicolo E va diritto, mentre il veicolo R svolta a sinistra. Anche se entrambi hanno il segnale di "Dare precedenza", chi svolta a sinistra (R) deve dare precedenza a chi va diritto (E) provenendo dalla direzione opposta. Quindi E passa prima di R.', '"deve attendere" - è la parola trappola, perché E non deve attendere R.', 'E va diritto, R svolta a sinistra: E non aspetta R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23223, 'Il veicolo R ha il segnale di "Dare precedenza" e transita per ultimo. Non può quindi impegnare l''incrocio per primo. Inoltre, fermarsi al centro dell''incrocio senza motivo è pericoloso e non è una norma di precedenza.', '"per primo", "si ferma al centro di esso" - affermazioni completamente errate e pericolose.', 'R è l''ultimo, non il primo; non si ferma al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23224, 'Il veicolo A non ha il segnale di "Dare precedenza", mentre il veicolo E sì. Questo significa che A ha la precedenza su E. Quindi A transita prima di E, non dopo.', '"dopo il veicolo E" - indica un ordine sbagliato di transito.', 'A senza triangolo, E con triangolo: A passa prima di E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23225, 'Il veicolo A transita dopo S, ma prima di E e R. Non è quindi l''ultimo a transitare. L''ultimo è il veicolo R.', '"per ultimo" - affermazione errata sulla posizione di transito di A.', 'A è il secondo, non l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23226, 'L''ordine corretto di transito è S, A, E, R. L''ordine proposto (E, R, S, A) è completamente sbagliato, in quanto mette per primi veicoli che hanno il segnale di "Dare precedenza".', '"nell''ordine: E, R, S, A" - questa sequenza è totalmente errata.', 'L''ordine è S, A, E, R. Ricorda i triangoli!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23227, 'Il veicolo A deve attendere solo il veicolo S, perché S ha la precedenza su A. Il veicolo E, invece, deve dare la precedenza ad A, quindi A non deve aspettare E.', '"attendere che siano transitati i veicoli S ed E" - la parte "ed E" è l''errore, A non aspetta E.', 'A aspetta S, ma non E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23228, 'Il veicolo A ha il segnale ''Dare precedenza'', quindi deve aspettare tutti i veicoli che non hanno questo segnale. C ed R non hanno il segnale ''Dare precedenza'', quindi A deve aspettare che passino loro.', '''deve attendere'' significa che è obbligato ad aspettare.', '''Dare precedenza'' = Aspetta tutti gli altri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23229, 'L''ordine corretto di transito è C per primo, poi R, poi A e infine H. C e R passano prima perché non hanno il segnale ''Dare precedenza''. Tra C e R, in questo tipo di incrocio, C passa prima di R. Poi, tra A e H (che hanno entrambi il ''Dare precedenza''), A passa prima di H perché H ha A alla sua destra.', '''nell''ordine'' indica la sequenza esatta.', 'C, R, A, H: Ricorda l''ordine specifico per questo incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23230, 'Il veicolo H ha il segnale ''Dare precedenza'', quindi deve aspettare tutti gli altri veicoli che non hanno questo segnale (C e R) e anche il veicolo A, che pur avendo il ''Dare precedenza'' passa prima di H perché H lo ha alla sua destra.', '''deve attendere'' significa che è obbligato ad aspettare.', 'H ha ''Dare precedenza'' e A alla destra = H è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23231, 'Il veicolo H ha il segnale ''Dare precedenza'' e, tra i veicoli che devono dare precedenza, è quello che ha un altro veicolo (A) alla sua destra. Per questo motivo, H transita per ultimo.', '''per ultimo'' significa che è l''ultimo in ordine di passaggio.', 'H con ''Dare precedenza'' e A a destra = Ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23232, 'In questo specifico incrocio, secondo la logica dei quiz, il veicolo C (che svolta a sinistra e non ha segnali di precedenza) transita prima del veicolo R (che va dritto e non ha segnali di precedenza). Quindi R deve aspettare C.', '''deve attendere'' significa che è obbligato ad aspettare.', 'C prima di R (eccezione quiz).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23233, 'Il veicolo C non ha segnali di ''Dare precedenza'' e, in questo tipo di incrocio, è considerato il primo a poter impegnare l''intersezione, anche se svolta a sinistra.', '''per primo'' significa che è il primo in ordine di passaggio.', 'C senza segnali = Primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23234, 'L''ordine corretto è C, R, A, H. Questa affermazione è falsa perché inverte l''ordine tra H e A. Il veicolo A passa prima di H perché H ha A alla sua destra (e entrambi hanno il ''Dare precedenza'').', '''nell''ordine'' indica la sequenza esatta. L''errore è nell''inversione di A e H.', 'A prima di H (H ha A a destra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23235, 'Il veicolo C non ha il segnale ''Dare precedenza'', mentre il veicolo H sì. Per questo, C ha la precedenza su H e non deve aspettarlo.', '''deve attendere'' è la parola chiave. C non deve aspettare H.', 'C senza segnale > H con segnale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23236, 'Entrambi i veicoli A e H hanno il segnale ''Dare precedenza''. Tuttavia, H ha il veicolo A alla sua destra, quindi H deve dare la precedenza ad A. Questo significa che A non deve aspettare H, ma è H che aspetta A.', '''deve attendere'' è la parola chiave. A non deve aspettare H.', 'A prima di H (H ha A a destra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23237, 'Il veicolo R non ha il segnale ''Dare precedenza'', mentre H ed A sì. Quindi R ha la precedenza su H ed A e non deve aspettarli.', '''deve attendere'' è la parola chiave. R non deve aspettare H e A.', 'R senza segnale > H e A con segnale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23238, 'Il veicolo C transita per primo. Non deve aspettare nessuno di questi veicoli. In particolare, non aspetta R (come visto prima), e non aspetta A e H perché questi hanno il segnale ''Dare precedenza''.', '''deve attendere'' è la parola chiave. C non deve aspettare nessuno.', 'C è il primo, non aspetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23239, 'Il veicolo R non ha il segnale ''Dare precedenza'', mentre il veicolo H sì. Quindi R ha la precedenza su H e non deve aspettarlo.', '''deve attendere'' è la parola chiave. R non deve aspettare H.', 'R senza segnale > H con segnale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23240, 'Il tram (veicolo T) ha sempre la precedenza su tutti gli altri veicoli, a meno che non ci siano segnali specifici (come un semaforo rosso o un segnale di stop) che indichino il contrario. In questo incrocio non ci sono, quindi il tram passa per primo.', 'La regola del tram è quasi assoluta, non ci sono eccezioni implicite nell''immagine.', 'Tram = Re della strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23241, 'Dopo il tram, tra i veicoli O e A, il veicolo O ha la precedenza su A. Questo perché il veicolo A sta svoltando a sinistra e deve dare la precedenza ai veicoli che provengono dalla sua destra o che vanno dritto o svoltano a destra dalla direzione opposta. Quindi, A deve aspettare O.', 'Il verbo ''attendere'' significa ''aspettare'' o ''dare la precedenza''.', 'Svolta a sinistra = aspetta chi va dritto o a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23242, 'Il veicolo T è un tram e, come abbiamo detto, ha la precedenza su tutti gli altri veicoli. Quindi, il veicolo O deve aspettare che il tram T sia passato prima di poter transitare.', '''Deve attendere'' indica un obbligo di dare la precedenza.', 'Tram prima di tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23243, 'L''ordine corretto è: prima il tram (T) perché ha sempre la precedenza. Poi il veicolo O, perché ha la precedenza sul veicolo A (che svolta a sinistra). Infine, il veicolo A.', '''Nell''ordine'' significa che la sequenza è fondamentale e non può essere cambiata.', 'T-O-A: Tram, poi chi ha la destra libera/svolta a destra, poi chi svolta a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23244, 'Dopo il tram, tra O e A, il veicolo O transita per primo. Questo perché A sta svoltando a sinistra e deve dare la precedenza a O, che viene dalla sua destra e svolta a destra.', '''Prima del'' indica una precedenza temporale chiara.', 'Svolta a sinistra aspetta chi va dritto/destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23245, 'Falso. Il tram (veicolo T) ha la precedenza su tutti gli altri veicoli, incluso il veicolo O. Quindi, è il veicolo O che deve aspettare T, non il contrario.', 'Attenzione a chi ''deve attendere'': il tram non aspetta quasi mai.', 'Tram non aspetta nessuno (salvo semaforo/stop).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23246, 'Falso. Dopo il tram, il veicolo O transita prima del veicolo A. Il veicolo A, svoltando a sinistra, deve dare la precedenza a O. Quindi, O non deve aspettare A.', 'La frase ''deve attendere'' è la trappola: O non deve attendere A, ma A deve attendere O.', 'Chi svolta a sinistra (A) aspetta chi va dritto/destra (O).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23247, 'Falso. Il tram (veicolo T) ha la precedenza assoluta su tutti gli altri veicoli, compreso il veicolo A. Non deve aspettare nessuno dei due.', 'Ancora una volta, ''deve attendere'' è la parola trappola quando riferita al tram.', 'Tram = sempre primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23248, 'Falso. L''ordine corretto è T, O, A. Il veicolo O transita prima di A perché A sta svoltando a sinistra e deve dare la precedenza a O. L''ordine proposto è sbagliato.', 'La parola ''nell''ordine'' è cruciale: se l''ordine è sbagliato, la risposta è falsa.', 'Ricorda l''ordine esatto: T-O-A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23249, 'Falso. Il tram (T) transita per primo. Il veicolo A transita per ultimo, dopo O. Non possono transitare contemporaneamente perché il tram ha la precedenza su A e O.', 'La parola ''contemporaneamente'' è la trappola: i veicoli transitano uno alla volta, in base alla precedenza.', 'Uno alla volta, in ordine di precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23250, 'Il veicolo B ha il segnale di "Dare precedenza" (il triangolo rovesciato) e sta svoltando a sinistra. Questo significa che deve aspettare che tutti gli altri veicoli (T, G, P) passino prima di lui. Quindi, l''affermazione è VERA.', 'La frase "a tutti gli altri veicoli" è importante perché conferma che B deve aspettare tutti e tre gli altri veicoli.', 'B ha il triangolo rovesciato e gira a sinistra: aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23251, 'Il veicolo T è un tram. I tram hanno quasi sempre la precedenza, a meno che non ci siano segnali specifici (come un semaforo rosso o un segnale di stop) che dicano il contrario. In questo incrocio, il tram T non ha il segnale di "Dare precedenza", quindi passa per primo. L''affermazione è VERA.', 'Nessuna parola trappola evidente. "passa per primo" è chiaro e corretto.', 'Tram senza segnale: passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23252, 'Il veicolo B ha il segnale di "Dare precedenza" e, tra i veicoli che devono cedere, è anche quello che svolta a sinistra. Questo lo rende l''ultimo a passare, dopo il tram T, il veicolo G e il veicolo P. L''affermazione è VERA.', '"transita per ultimo" indica la posizione finale nell''ordine di passaggio, ed è corretta per B.', 'B con triangolo e svolta a sinistra: ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23253, 'Il veicolo P ha il segnale di "Dare precedenza". Questo significa che deve aspettare che passino i veicoli che non hanno questo segnale o che hanno la precedenza per altre regole. In questo caso, T (il tram) e G (che non ha segnali di precedenza e va dritto) passano prima di P. L''affermazione è VERA.', 'Nessuna parola trappola evidente. "deve dare la precedenza" è il concetto chiave e qui è applicato correttamente.', 'P ha il triangolo: cede a T e G.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23254, 'L''ordine corretto di transito è: 1. Il tram T (ha la precedenza generale). 2. Il veicolo G (non ha segnali di precedenza e non deve cedere a nessuno). 3. Il veicolo P (ha il "Dare precedenza" ma ha la destra libera rispetto a B). 4. Il veicolo B (ha il "Dare precedenza" e svolta a sinistra). L''ordine T, G, P, B è quindi VERO.', '"nell''ordine" richiede la sequenza esatta, che qui è corretta.', 'Ordine: Tram, poi chi non cede, poi chi cede ma ha la destra libera, infine chi cede e gira a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23255, 'Il veicolo T è un tram e ha la precedenza su tutti gli altri veicoli, incluso il veicolo G. Anche se G non ha il segnale di "Dare precedenza", deve comunque aspettare che il tram T passi. L''affermazione è VERA.', '"deve attendere" indica l''obbligo di aspettare, che per G nei confronti di T è corretto.', 'G aspetta il tram T.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23256, 'Il veicolo T è un tram e ha la precedenza su tutti gli altri veicoli, incluso il veicolo G. Quindi, è G che deve aspettare T, non il contrario. Il tram T passa prima di G. L''affermazione è FALSA.', 'La frase "deve attendere" rende l''affermazione falsa, perché il tram non attende G.', 'Tram non aspetta auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23257, 'Il veicolo T (il tram) transita per primo, non il veicolo G. I tram hanno la precedenza generale. L''affermazione è FALSA.', '"transita per primo" è la parte sbagliata dell''affermazione, perché il primo è il tram.', 'Primo è il tram, non G.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23258, 'Il veicolo B ha il segnale di "Dare precedenza" e transita per ultimo, non per primo. Inoltre, non deve fermarsi al centro dell''incrocio, ma deve dare la precedenza prima di entrarci, se necessario. L''affermazione è FALSA.', 'Entrambe le parti dell''affermazione sono false: "impegna per primo" (B è l''ultimo) e "deve fermarsi al centro di esso" (non è una regola di precedenza).', 'B è l''ultimo, non il primo e non si ferma al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23259, 'Il veicolo T (il tram) impegna l''incrocio per primo, questo è vero. Ma non deve fermarsi al centro dell''incrocio. Avendo la precedenza, il tram prosegue senza fermarsi, a meno di ostacoli o segnali specifici. L''affermazione è FALSA a causa della seconda parte.', 'La congiunzione "ma" unisce una parte vera ("impegna per primo") con una falsa ("deve fermarsi al centro di esso"). Attenzione a queste costruzioni.', 'Tram passa per primo, non si ferma al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23260, 'L''ordine corretto di transito è T, G, P, B. L''affermazione propone l''ordine T, P, G, B, scambiando la posizione di P e G. Il veicolo G passa prima di P perché G non ha il segnale di "Dare precedenza", mentre P sì. L''affermazione è FALSA.', '"nell''ordine" è la parola chiave che indica che la sequenza proposta è sbagliata.', 'G prima di P.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23261, 'Dopo il veicolo T (il tram), transita il veicolo G. Solo dopo G, transita il veicolo P. Quindi P non passa "subito dopo" T, perché c''è G in mezzo. L''affermazione è FALSA.', 'L''espressione "subito dopo" rende l''affermazione falsa, perché c''è un altro veicolo (G) che passa tra T e P.', 'Dopo T c''è G, non P.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23262, 'Il veicolo N (autocarro) ha il veicolo E (auto bianca) alla sua destra. Secondo la regola generale della precedenza a destra, N deve dare la precedenza a E e quindi attendere il suo transito. Questo è VERO.', 'La frase ''deve attendere il transito'' significa che il veicolo indicato non può passare prima dell''altro.', 'Chi ha un veicolo a destra, aspetta. N ha E a destra, quindi N aspetta E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23263, 'Il veicolo E (auto bianca) ha il veicolo L (auto gialla) alla sua destra. Secondo la regola generale della precedenza a destra, E deve dare la precedenza a L e quindi attendere il suo transito. Questo è VERO.', 'Anche qui, ''deve attendere il transito'' indica che E non può passare prima di L.', 'Chi ha un veicolo a destra, aspetta. E ha L a destra, quindi E aspetta L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23264, 'Il veicolo R (filobus) ha il veicolo N (autocarro) alla sua destra, quindi R deve attendere N. Poiché N a sua volta deve attendere E (come visto nella domanda 23262), R indirettamente attende anche E. Questo è VERO.', 'La frase ''deve attendere il transito dei veicoli E ed N'' indica che R deve aspettare entrambi i veicoli.', 'R aspetta N (che è a destra). Se N aspetta E, allora R aspetta anche E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23265, 'Questo incrocio è un caso particolare di ''blocco'' dove tutti i veicoli hanno un altro veicolo alla propria destra. Per risolvere il blocco, si stabilisce un ordine. In questo specifico schema, l''ordine corretto è L, poi E, poi N, e infine R. Il veicolo L, girando a destra, ''sblocca'' l''incrocio, permettendo agli altri di seguire in sequenza. Questo è VERO.', 'La frase ''transitano nell''ordine'' chiede la sequenza esatta. La ''trappola'' è il blocco dell''incrocio, che richiede di conoscere l''ordine convenzionale per risolverlo.', 'L-E-N-R: L sblocca l''incrocio, gli altri seguono la catena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23266, 'Il veicolo R (filobus) è l''ultimo a passare nell''ordine stabilito (L, E, N, R). Non ha la precedenza sugli altri veicoli, anzi, deve attendere tutti gli altri. Questo è FALSO.', 'La frase ''ha la precedenza sugli altri veicoli'' è la chiave. I filobus non hanno precedenza speciale se non sono su rotaie o se non indicato da segnaletica specifica.', 'Filobus non è tram! Niente precedenza speciale qui. R è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23267, 'Nell''ordine di transito stabilito per questo incrocio (L, E, N, R), il veicolo E passa prima del veicolo R. Quindi E non deve attendere R. Questo è FALSO.', 'La frase ''deve attendere il transito'' è la chiave. Se E passa prima, non deve attendere.', 'E passa prima di R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23268, 'Il veicolo L è il primo a passare nell''ordine stabilito (L, E, N, R). Questo significa che L non attende R, ma è R che attende L (indirettamente, seguendo la catena di precedenze). Questo è FALSO.', 'La frase ''deve attendere il transito'' è la chiave. La ''trappola'' è che R è alla destra di L, ma in questo specifico blocco L passa per primo per sbloccare l''incrocio.', 'L sblocca l''incrocio, quindi non aspetta R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23269, 'Nell''ordine di transito stabilito (L, E, N, R), il veicolo E passa prima di N e R. Quindi E non deve attendere né N né R. Questo è FALSO.', 'La frase ''deve attendere il transito dei veicoli N e R'' indica una precedenza multipla. Se E passa prima, non attende nessuno dei due.', 'E passa prima di N e R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23270, 'Nell''ordine di transito stabilito (L, E, N, R), il veicolo E passa prima del veicolo N. Quindi E non deve attendere N. Questo è FALSO.', 'La frase ''deve attendere il transito'' è la chiave. Se E passa prima, non attende N.', 'E passa prima di N.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23271, 'L''ordine corretto di transito per questo incrocio, come stabilito per risolvere il blocco, è L, E, N, R. L''ordine proposto (R, L, E, N) è sbagliato. Questo è FALSO.', 'La frase ''transitano nell''ordine'' chiede la sequenza esatta. È importante ricordare l''ordine specifico per questo tipo di incrocio.', 'L''ordine è L-E-N-R, non R-L-E-N.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23272, 'VERO. In questo incrocio senza segnali, si crea un "blocco" perché ogni veicolo ha un altro veicolo alla sua destra. La sequenza corretta di transito è H, A, F, L. Poiché F transita dopo A, deve attendere il suo passaggio.', 'La frase "deve attendere il transito" significa che il veicolo indicato deve aspettare che l''altro veicolo passi prima.', 'L''ordine è H, A, F, L. F viene dopo A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23273, 'VERO. La sequenza di transito corretta per questo incrocio è H, A, F, L. Il veicolo L è l''ultimo a transitare, quindi deve attendere il passaggio di tutti gli altri veicoli, inclusi A ed F.', 'La parola "attendere" significa aspettare. "Transito" si riferisce al passaggio del veicolo.', 'L è l''ultimo, aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23274, 'VERO. La sequenza di transito corretta per questo incrocio è H, A, F, L. Il veicolo H transita per primo, e solo dopo può passare il veicolo A. Quindi, A deve attendere H.', 'La frase "deve attendere il transito" indica una precedenza: chi deve attendere passa dopo.', 'H va per primo, A lo segue.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23275, 'VERO. La sequenza di transito corretta per questo incrocio è H, A, F, L. Il veicolo L è l''ultimo della fila a passare, quindi transita per ultimo.', 'La parola "ultimo" è chiara: significa che passa dopo tutti gli altri.', 'L è l''ultimo della fila.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23276, 'VERO. In questo incrocio, dove tutti i veicoli hanno un altro veicolo alla loro destra (creando un "blocco"), il veicolo H è quello che, per convenzione didattica in questi quiz, transita per primo per "sbloccare" la situazione, anche se ha A alla sua destra.', 'La frase "transita per primo" significa che è il primo veicolo ad attraversare l''incrocio.', 'H sblocca il cerchio, va per primo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23277, 'VERO. La sequenza corretta di transito per questo incrocio, che presenta un "blocco" di precedenze, è H, A, F, L. H sblocca l''incrocio, poi A, poi F e infine L.', 'La frase "debbono transitare nell''ordine" indica la sequenza esatta in cui i veicoli devono passare.', 'L''ordine da ricordare è H, A, F, L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23278, 'FALSO. L''ordine corretto di transito per questo incrocio è H, A, F, L. L''ordine proposto (A, F, L, H) è sbagliato perché H transita per primo e L per ultimo.', 'Attenzione all''ordine dei veicoli. Anche un solo veicolo fuori posto rende la risposta Falsa.', 'Ricorda: H, A, F, L è l''unico ordine corretto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23279, 'FALSO. Il veicolo H transita per primo in questo incrocio. Il veicolo F transita per terzo, dopo H e A.', 'La parola "primo" è la chiave. F non è il primo.', 'F non è il primo, H lo è.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23280, 'FALSO. Il veicolo H transita per primo, mentre il veicolo L transita per ultimo. Quindi, H non deve attendere L, ma è L che attende H.', 'La frase "deve attendere" indica chi aspetta chi. Qui è il contrario.', 'H va prima di L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23281, 'FALSO. Il veicolo H transita per primo, mentre il veicolo F transita per terzo. Quindi, H non deve attendere F, ma è F che attende H (e A).', 'Anche qui, "deve attendere" è la parola trappola. La relazione di attesa è inversa.', 'H va prima di F.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23282, 'FALSO. La sequenza di transito è H, A, F, L. Il veicolo A transita prima del veicolo F, quindi A non deve attendere F, ma è F che attende A.', 'La frase "deve attendere il transito" è cruciale. Se A passa prima di F, non lo aspetta.', 'A va prima di F.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23283, 'Il veicolo N deve dare la precedenza sia al veicolo A (che viene dalla sua destra) sia al veicolo R (che viene di fronte e va dritto). Per questo motivo, N passa per ultimo e conclude l''attraversamento per ultimo.', 'La frase "conclude per ultimo" significa che finisce di attraversare l''incrocio dopo tutti gli altri veicoli.', 'N gira a sinistra, aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23284, 'Il veicolo A si trova alla destra del veicolo N. Secondo la regola generale della precedenza, chi viene da destra ha la precedenza. Quindi, N deve dare la precedenza ad A.', 'La frase "deve dare la precedenza" significa che deve aspettare che l''altro veicolo passi prima.', 'Destra libera, N aspetta A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23285, 'In questo incrocio, il veicolo N ha la precedenza rispetto al veicolo R. Questo significa che R deve attendere il passaggio di N.', 'La frase "ha la precedenza rispetto a" indica chi deve passare prima.', 'N passa prima di R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23286, 'Il veicolo N deve aspettare sia il veicolo A (che viene dalla sua destra) sia il veicolo R (che viene di fronte e va dritto). Per questo motivo, N può completare la sua svolta solo dopo che A e R sono passati.', 'La frase "concludere la manovra" significa finire la svolta. "Dopo il transito" significa dopo che sono passati.', 'N aspetta A e R, poi gira.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23287, 'Il veicolo N, per svoltare a sinistra, deve prima entrare nell''incrocio e poi fermarsi al centro, se necessario. Da lì, deve dare la precedenza sia al veicolo A (che viene dalla sua destra) sia al veicolo R (che viene di fronte e va dritto). Quindi, deve attendere che entrambi siano passati.', 'La frase "dopo essersi portato al centro dell''incrocio" indica la posizione corretta per chi svolta a sinistra, prima di completare la manovra. "Deve attendere" significa che deve aspettare.', 'N al centro, aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23288, 'Il veicolo N deve dare la precedenza sia al veicolo A (che viene dalla sua destra) sia al veicolo R (che viene di fronte e va dritto). Per questo motivo, N non può attraversare per primo, ma passa per ultimo.', 'La frase "attraversa per primo" significa che passa prima di tutti gli altri veicoli.', 'N ultimo, non primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23289, 'Il veicolo N non deve dare la precedenza al veicolo R. Questo perché, in questo contesto, N ha la precedenza su R e quindi può passare prima senza aspettare.', 'La frase "deve dare la precedenza" significa che deve aspettare. Se la risposta è FALSO, significa che non deve aspettare.', 'N non aspetta R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23290, 'Il veicolo A si trova alla destra del veicolo N. Secondo la regola generale della precedenza, chi viene da destra ha la precedenza. Quindi, N non ha la precedenza rispetto ad A, ma deve aspettare che A passi.', 'La frase "ha la precedenza rispetto a" indica chi deve passare prima.', 'Destra libera, N aspetta A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23291, 'Questa affermazione è falsa perché il veicolo N deve dare la precedenza al veicolo A (che viene da destra), quindi N passa dopo A. Inoltre, secondo la logica di questo quiz, N ha la precedenza rispetto a R, quindi N passa prima di R. L''affermazione dice che N passa ''dopo R'' (che è falso) e ''prima di A'' (che è falso). Per questi motivi, l''intera affermazione è falsa.', 'Le espressioni "dopo il transito di" e "prima che transiti" indicano l''ordine di passaggio tra i veicoli.', 'N passa tra A e R (A -> N -> R).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23292, 'Secondo l''ordine di passaggio stabilito dalle risposte precedenti (A passa per primo, poi N, poi R), il veicolo N impegna l''incrocio dopo A ma prima di R. Quindi, non lo impegna per ultimo.', 'La frase "impegna l''incrocio per ultimo" significa che entra nell''incrocio dopo tutti gli altri veicoli.', 'N non è l''ultimo a entrare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23293, 'In questo incrocio senza segnali, il tram (T) ha sempre la precedenza. Dopo il tram, il veicolo B ha la precedenza perché non ha nessuno alla sua destra. Il veicolo A ha il veicolo B alla sua destra, quindi deve dargli la precedenza. Per questo, il veicolo A deve dare la precedenza sia al tram che al veicolo B.', 'La frase ''deve dare la precedenza'' indica un obbligo. Non ci sono eccezioni in questo caso.', 'Tram sempre prima, poi chi non ha nessuno a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23294, 'Dopo che il tram (T) e il veicolo B sono passati, rimangono i veicoli A e C. Il veicolo C ha il veicolo A alla sua destra, quindi C deve dare la precedenza ad A. Questo significa che il veicolo A ha la precedenza rispetto al veicolo C.', 'La parola ''rispetto'' indica un confronto diretto tra due veicoli per stabilire chi passa prima.', 'Chi ha la destra libera passa prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23295, 'L''ordine corretto di transito è: prima il tram (T) perché ha sempre la precedenza. Poi il veicolo B, perché non ha nessuno alla sua destra. Poi il veicolo A, perché dopo B non ha più nessuno alla sua destra e C deve dargli la precedenza. Infine, il veicolo C. La domanda raggruppa T e B come primi a transitare (non necessariamente contemporaneamente, ma prima di A e C), il che è corretto nell''ordine generale.', 'La congiunzione ''e'' tra ''T e B'' in questo contesto significa che questi due veicoli sono i primi a passare, uno dopo l''altro, non per forza nello stesso istante. È una ''trappola'' comune che fa pensare alla simultaneità.', 'T, B, A, C: Tram, poi chi non ha destra, poi il resto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23296, 'Anche se il tram (T) ha la precedenza assoluta e il veicolo B deve dargli la precedenza, in alcuni casi, se le loro traiettorie non si incrociano in modo pericoloso o se il veicolo B può iniziare la manovra senza intralciare il tram, possono transitare ''contemporaneamente'' nel senso che entrambi sono in movimento nell''incrocio, ma il tram mantiene la sua priorità. Tuttavia, la regola generale è che se le traiettorie si incrociano, non possono essere simultanei. Questa è una domanda ''tranello'' che accetta una interpretazione più elastica di ''contemporaneamente'' in contesti di quiz, dove si intende che non si ostacolano a vicenda se uno rispetta la precedenza dell''altro.', 'La parola ''contemporaneamente'' è la parola trappola. In senso stretto, se le traiettorie si incrociano, non possono essere simultanei. Ma nei quiz, a volte si intende che possono essere entrambi in movimento senza collisione se le precedenze sono rispettate.', 'Attenzione a ''contemporaneamente'': spesso è FALSO se le traiettorie si incrociano, ma a volte VERO se uno aspetta l''altro senza fermarsi del tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23297, 'Seguendo l''ordine di precedenza (T, B, A, C), il veicolo C è l''ultimo a transitare perché deve dare la precedenza a tutti gli altri veicoli (T, B, A).', 'La frase ''transita per ultimo'' è chiara e indica la posizione finale nell''ordine di passaggio.', 'L''ultimo è chi ha tutti a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23298, 'Il tram (T) ha la precedenza assoluta. Il veicolo C deve dare la precedenza al tram (T) e anche al veicolo A. Le loro traiettorie si incrociano, quindi non possono transitare contemporaneamente. Il tram passa per primo, C per ultimo.', 'Anche qui, ''contemporaneamente'' è la parola chiave. Le loro traiettorie si incrociano, quindi non possono passare nello stesso momento.', 'Se le traiettorie si incrociano, non si passa insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23299, 'L''ordine corretto di transito è T, B, A, C. La sequenza proposta (T, B, C, A) è sbagliata perché il veicolo A transita prima del veicolo C (A ha la precedenza su C).', 'L''ordine dei veicoli è fondamentale. Basta un''inversione per rendere la risposta FALSO.', 'Ricorda l''ordine esatto: T, B, A, C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23300, 'Il veicolo A transita dopo il tram (T) e il veicolo B, ma prima del veicolo C. Quindi non è l''ultimo a transitare; l''ultimo è il veicolo C.', 'La parola ''ultimo'' è la chiave. Bisogna identificare chi chiude la sequenza.', 'L''ultimo è chi ha tutti a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23301, 'I veicoli T, B e C non possono transitare contemporaneamente perché le loro traiettorie si incrociano e hanno precedenze diverse. Il tram (T) passa per primo, poi B, poi A, e infine C.', 'La parola ''contemporaneamente'' è la trappola. Se le traiettorie si incrociano e non c''è un ordine chiaro di non-interferenza, non possono passare insieme.', 'Troppi veicoli insieme = pericolo, quindi FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23302, 'Il veicolo B non deve dare la precedenza al veicolo A. Al contrario, il veicolo A deve dare la precedenza al veicolo B, perché B si trova alla destra di A (e B non ha nessuno alla sua destra).', 'Attenzione all''inversione dei ruoli: ''B deve dare la precedenza ad A'' è il contrario di ''A deve dare la precedenza a B''.', 'Chi ha la destra libera passa, chi ha qualcuno a destra aspetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23303, 'Il veicolo D non ha nessun altro veicolo alla sua destra. Secondo la regola generale della precedenza, chi non ha nessuno a destra passa per primo. Quindi, il veicolo D passa per primo.', 'La domanda è diretta e non contiene parole trappola particolari, chiede semplicemente la posizione di D nell''ordine di precedenza.', 'Destra libera? Via libera!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23304, 'Dato che il veicolo D non ha nessun veicolo alla sua destra, non deve dare la precedenza a nessuno. È il primo a passare e non ha obblighi di precedenza.', 'La parola ''alcun'' significa ''nessun''. È fondamentale capire che D non deve dare la precedenza a *nessuno* dei veicoli presenti.', 'Nessuno a destra = nessuna precedenza da dare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23305, 'Il veicolo D passa per primo perché non ha nessuno alla sua destra. Di conseguenza, non deve dare la precedenza al veicolo A, che si trova alla sua sinistra.', 'La frase ''non ha l''obbligo'' è importante: conferma che D non deve fermarsi per A.', 'D è il primo, A aspetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23306, 'Il veicolo D non ha nessun veicolo alla sua destra. Per la regola della precedenza, D è il primo a passare, non il terzo. Quindi l''affermazione è falsa.', 'La parola ''terzo'' è la trappola. Cambia completamente il significato della frase, indicando un ordine di passaggio errato.', 'D è il primo, non il terzo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23307, 'Il veicolo D non ha nessun veicolo alla sua destra. Questo significa che è il primo a passare e non deve dare la precedenza a nessuno, tantomeno a ''tutti'' i veicoli.', 'La frase ''a tutti i veicoli'' è una trappola molto forte. D non deve dare la precedenza a nessuno, quindi non a tutti.', 'D ha la destra libera, non dà precedenza a nessuno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23308, 'Il veicolo D passa per primo perché non ha nessuno alla sua destra, quindi non deve dare la precedenza al veicolo E. Inoltre, il veicolo E vuole girare a sinistra, non proseguire diritto.', 'Ci sono due trappole: ''ha l''obbligo di dare la precedenza'' (FALSO, D non deve) e ''che prosegue diritto'' (FALSO, E gira a sinistra).', 'D è il primo. E gira, non va dritto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23309, 'In questo incrocio, c''è una situazione di "precedenza a destra" circolare (A deve dare precedenza a R, R a N, N ad A). Per sbloccare l''incrocio, il veicolo N (che svolta a sinistra) si impegna per primo nell''incrocio, ma si ferma al centro per dare la precedenza a R che va dritto. Quindi, R "dà la precedenza" a N nel senso che N si muove per primo nell''incrocio, anche se poi R passa prima che N completi la svolta.', 'La parola "precedenza" qui è una trappola. Non significa che N passa completamente prima di R, ma che N ha il diritto di impegnare l''incrocio per primo per avviare lo sblocco.', 'N si muove per primo, ma si ferma al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23310, 'Il veicolo R si trova alla destra del veicolo A. Secondo la regola generale della precedenza, chi viene da destra ha la precedenza. Quindi R passa prima di A.', '"rispetto al veicolo A" chiarisce il confronto diretto tra i due veicoli.', 'Destra ha sempre precedenza (R è a destra di A).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23311, 'Il veicolo N, che svolta a sinistra, si impegna nell''incrocio per primo (come visto nella domanda 23309), ma deve fermarsi al centro per permettere al veicolo R di passare, perché R va dritto e attraversa la traiettoria di N. Dopo che R è passato, N può completare la sua svolta.', '"dopo che il veicolo N si è fermato al centro" descrive esattamente la manovra di svolta a sinistra in presenza di traffico che incrocia la traiettoria.', 'N si ferma al centro, poi R passa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23312, 'Come spiegato per la domanda 23310, il veicolo R si trova alla destra del veicolo A. Per la regola della precedenza a destra, R passa prima di A.', '"passa prima" indica l''ordine di attraversamento.', 'R è a destra di A, quindi R passa prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23313, 'Basandoci sull''ordine stabilito (N si impegna, si ferma, R passa, N finisce, A passa), il veicolo R è il primo a completare il suo percorso attraverso l''incrocio.', '"conclude per primo l''attraversamento" significa che è il primo a uscire dall''incrocio.', 'R è il più veloce a liberare l''incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23314, 'Il veicolo R si trova alla destra del veicolo A. Secondo la regola generale, R ha la precedenza su A, non il contrario. Quindi R non deve dare la precedenza ad A.', '"deve dare la precedenza" è l''elemento chiave. Qui è FALSO perché R ha la precedenza.', 'R è a destra di A, quindi R NON dà precedenza ad A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23315, 'Come stabilito, il veicolo R è il primo a completare l''attraversamento dell''incrocio, dopo che N si è fermato al centro. Quindi non passa per ultimo.', '"passa per ultimo" è l''affermazione da valutare.', 'R è il primo a liberare l''incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23316, 'Il veicolo R ha la precedenza rispetto al veicolo A (R è alla sua destra). Quindi R passa prima di A, non dopo.', '"dopo il transito" indica un ordine temporale.', 'R è a destra di A, quindi R passa PRIMA.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23317, 'Il veicolo R va dritto e ha la precedenza sul veicolo A e passa dopo che N si è fermato al centro. Non ha motivo di fermarsi al centro dell''incrocio. È il veicolo N (che svolta a sinistra) che si ferma al centro.', '"si ferma al centro" è l''azione chiave. R non si ferma al centro.', 'R va dritto, non si ferma al centro. N si ferma.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23318, 'La regola generale in un incrocio senza segnali è dare la precedenza a chi viene da destra. Il veicolo T ha il veicolo A alla sua destra. A sua volta, il veicolo A ha il veicolo R alla sua destra. Questo significa che T deve aspettare sia A che R. Per questo motivo, T passa per ultimo.', 'La frase ''passa per ultimo'' indica che il veicolo T è l''ultimo a muoversi nell''incrocio, dopo tutti gli altri.', 'T ha A a destra, A ha R a destra. T aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23319, 'In un incrocio senza segnali, la regola è dare la precedenza a chi viene da destra. Il veicolo R non ha nessun altro veicolo alla sua destra. Non avendo nessuno a cui dare la precedenza, R può passare per primo.', 'La frase ''passa per primo'' significa che il veicolo R è il primo a muoversi nell''incrocio, prima di tutti gli altri.', 'R non ha nessuno a destra = passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23320, 'Il veicolo A deve dare la precedenza a chi viene dalla sua destra. Guardando l''immagine, il veicolo R si trova alla destra del veicolo A. Quindi, A è obbligato ad aspettare che il veicolo R sia passato prima di poter proseguire.', 'La frase ''deve attendere il transito'' significa che il veicolo A è obbligato ad aspettare che R passi.', 'A ha R a destra, quindi A aspetta R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23321, 'Il veicolo T ha il veicolo A alla sua destra. Il veicolo A, a sua volta, ha il veicolo R alla sua destra. Questo significa che T deve aspettare prima A e poi R. In pratica, T deve aspettare che passino entrambi i veicoli R e A.', 'La frase ''deve attendere il transito dei veicoli R ed A'' significa che T deve aspettare che entrambi i veicoli menzionati siano passati.', 'T ha A a destra, A ha R a destra. T aspetta entrambi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23322, 'Seguendo la regola della precedenza a destra: 1. R non ha nessuno a destra, quindi passa per primo. 2. Dopo R, tra A e T, il veicolo A ha T alla sua sinistra (T sta svoltando a sinistra e deve dare precedenza ad A). Quindi A passa dopo R. 3. Infine, T passa per ultimo perché ha A alla sua destra. L''ordine corretto è R, poi A, poi T.', 'La parola ''nell''ordine'' è fondamentale e indica la sequenza esatta di passaggio dei veicoli.', 'Ordine: R (nessuno a destra) -> A (T a sinistra) -> T (A a destra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23323, 'Abbiamo stabilito che il veicolo R passa per primo perché non ha nessuno alla sua destra. Il veicolo T, invece, passa per ultimo perché deve dare la precedenza sia ad A che a R. Quindi, T non può passare prima di R, ma passa dopo.', 'La frase ''transita prima'' è la parola chiave. Qui è falso perché T transita DOPO R, non prima.', 'R è primo, T è ultimo. T non può essere prima di R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23324, 'L''ordine corretto di passaggio, basato sulla regola della precedenza a destra, è R, A, T. Questa affermazione propone l''ordine R, T, A. Questo è sbagliato perché il veicolo A passa prima del veicolo T, non dopo. T deve aspettare A.', 'La parola ''nell''ordine'' è la chiave. La sequenza proposta (R, T, A) è errata rispetto alla regola.', 'Ricorda: l''ordine corretto è R, A, T. Non R, T, A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23325, 'L''ordine corretto di passaggio è R, A, T. Questa affermazione propone l''ordine T, A, R. Questo è completamente sbagliato perché il veicolo T è l''ultimo a passare, mentre R è il primo. L''ordine proposto è l''opposto di quello corretto per R e T.', 'La parola ''nell''ordine'' è la chiave. La sequenza proposta (T, A, R) è completamente sbagliata.', 'R è primo, T è ultimo. L''ordine T, A, R è sbagliato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23326, 'Il veicolo T ha il veicolo A alla sua destra, e A ha R alla sua destra. Questo significa che T deve aspettare sia A che R. Quindi, T è l''ultimo a passare nell''incrocio, non il primo. L''affermazione è falsa.', 'La frase ''transita prima degli altri veicoli'' è la parola chiave. Qui è falso perché T transita DOPO gli altri, essendo l''ultimo.', 'T è l''ultimo, non il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23327, 'In questo incrocio, la regola generale è dare la precedenza a chi viene da destra. Il veicolo S non ha nessuno alla sua destra, quindi passa per primo. Poi E, che non ha più S alla sua destra. Poi D, che non ha più E alla sua destra. Infine, A, che non ha più D alla sua destra. Quindi, A passa per ultimo.', 'La frase "per ultimo" significa che tutti gli altri veicoli passano prima di A.', 'A ha D alla sua destra, D ha E, E ha S. La catena di precedenza rende A l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23328, 'Il veicolo A deve dare la precedenza a D. Il veicolo D deve dare la precedenza a E. Il veicolo E deve dare la precedenza a S. Questo significa che A deve aspettare che passino tutti e tre i veicoli (D, E e S), quindi deve dare la precedenza anche a E e S.', 'La frase "deve dare la precedenza" significa che A deve aspettare che questi veicoli passino.', 'Se aspetti chi è alla tua destra, aspetti anche chi è alla destra del tuo ''destra''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23329, 'Il veicolo A deve dare la precedenza a D. D deve dare la precedenza a E. E deve dare la precedenza a S. Questo significa che A deve aspettare che passino tutti e tre i veicoli: S, poi E, poi D. La frase ''nell''ordine, dei veicoli D, E e S'' in questo contesto indica l''elenco dei veicoli che A deve attendere, non necessariamente l''ordine esatto in cui passano, ma che A deve aspettare che tutti e tre abbiano transitato.', 'La parola trappola è "nell''ordine". Non significa che D passa per primo, poi E, poi S. Significa che A deve aspettare tutti e tre i veicoli menzionati, e l''ordine di passaggio effettivo è S, E, D.', 'A aspetta D, E, S. ''Nell''ordine'' qui è una lista, non una sequenza di passaggio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23330, 'Il veicolo A ha il veicolo D alla sua destra. Secondo la regola della precedenza a destra, A deve dare la precedenza a D. Quindi, la sua destra non è libera.', 'La frase "destra libera" significa che non c''è nessun veicolo che arriva dalla tua destra e a cui devi dare la precedenza.', 'Guarda sempre a destra: se c''è qualcuno, non è libera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23331, 'Il veicolo A deve dare la precedenza al veicolo D perché D si trova alla sua destra. Questo significa che D passa prima di A. Non possono passare nello stesso momento.', 'La parola "contemporaneamente" significa nello stesso momento. In questo caso, è falso perché c''è una precedenza.', 'Chi ha la precedenza passa prima, non insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23332, 'L''ordine di passaggio è S, poi E, poi D, e infine A. Quindi, A passa dopo S, dopo E e anche dopo D. La frase dice ''ma prima del veicolo D'', che è sbagliata perché A passa dopo D.', 'La parte "ma prima del veicolo D" rende l''intera affermazione falsa.', 'Ricorda l''ordine: S, E, D, A. A è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23333, 'La regola della precedenza a destra vale sempre, indipendentemente dalla direzione che prendono i veicoli (dritto, svolta a destra o svolta a sinistra), a meno che non ci siano segnali specifici. Quindi, A deve dare la precedenza a D anche se D sta svoltando.', 'La parola "solo" è spesso una trappola. La precedenza non dipende dalla direzione del veicolo.', 'Precedenza a destra vale per tutti, non solo per chi va dritto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23334, 'Il veicolo A deve dare la precedenza al veicolo C (che è alla sua destra). Il veicolo C, a sua volta, deve dare la precedenza al veicolo L (che è alla sua destra). Questo significa che A deve aspettare C, e C deve aspettare L. Di conseguenza, A deve dare la precedenza anche a L, che passerà prima di A.', 'Nessuna parola trappola evidente. La frase è diretta e chiara.', 'A aspetta C, C aspetta L. Quindi A aspetta L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23335, 'L''ordine di passaggio è L, poi C, poi A, e infine D. Dopo che il veicolo L è passato, il veicolo C può attraversare l''incrocio. Subito dopo C, anche il veicolo A può passare. La parola ''insieme'' qui non significa ''contemporaneamente'', perché A deve comunque aspettare che C liberi la sua destra. Significa piuttosto ''nella stessa fase di sgombero dell''incrocio'', uno dopo l''altro.', 'La parola ''insieme'' è la trappola. Non significa ''allo stesso momento'' se c''è una precedenza da rispettare, ma ''nella stessa fase di passaggio'' o ''uno dopo l''altro immediatamente''.', '''Insieme'' non sempre significa ''allo stesso momento'' se c''è precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23336, 'Il veicolo D sta svoltando a sinistra. La regola dice che chi svolta a sinistra deve dare la precedenza sia ai veicoli che provengono dalla sua destra (come A) sia a quelli che provengono di fronte e vanno diritto (come L). Poiché D deve dare la precedenza ad A, significa che A ha la precedenza su D.', 'Nessuna parola trappola evidente. La frase è diretta e chiara.', 'Chi svolta a sinistra (D) aspetta chi va diritto (A) e chi viene di fronte (L).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23337, 'Il veicolo A deve dare la precedenza a L e a C, perché sono alla sua destra o hanno precedenza su di lui nella sequenza di passaggio. Tuttavia, come abbiamo visto, A ha la precedenza sul veicolo D. Quindi, A non deve dare la precedenza a *tutti* i veicoli.', 'La parola ''tutti'' è la trappola. Spesso, termini assoluti come ''sempre'', ''mai'', ''tutti'', ''nessuno'' indicano una risposta FALSO, a meno di casi molto specifici.', '''Tutti'' è spesso FALSO. Controlla le eccezioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23338, 'L''ordine corretto di passaggio è: prima L, poi C, poi A, e infine D. Questo significa che il veicolo D passa per ultimo, non il veicolo A.', 'La parola ''ultimo'' è la trappola. Bisogna conoscere l''ordine esatto di passaggio.', 'Ricorda l''ordine: L, C, A, D. D è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23339, 'Il veicolo B vuole svoltare a sinistra. Il veicolo N viene dalla direzione opposta e svolta a destra. La regola dice che chi svolta a sinistra deve dare la precedenza ai veicoli che vengono di fronte e vanno diritto o svoltano a destra. Quindi B deve aspettare N.', '"deve dare la precedenza" significa che B deve aspettare N prima di completare la sua manovra.', 'Svolta a sinistra? Aspetta chi viene di fronte e va dritto o a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23340, 'Questo è un incrocio ''bloccato'' dove tutti i veicoli hanno qualcuno alla propria destra. In questi casi, il veicolo B (che svolta a sinistra) può avanzare fino al centro dell''incrocio per prepararsi alla svolta, perché il veicolo R (alla sua destra) è a sua volta bloccato dal veicolo D. Quindi B si porta al centro, e R aspetta D.', '"impegna l''incrocio" significa che B entra nell''incrocio, anche solo per posizionarsi al centro, non che completa la manovra.', 'Blocco? Chi svolta a sinistra può andare al centro se chi ha la precedenza è bloccato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23341, 'Come abbiamo detto, B deve dare la precedenza a N. Questo significa che B aspetterà che N passi prima di finire la sua svolta a sinistra.', '"dopo il transito" indica la sequenza temporale: prima N, poi B finisce.', 'B aspetta N per finire la svolta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23342, 'Questa domanda conferma la spiegazione precedente. B si porta al centro (come visto nella domanda 23340), ma poi deve aspettare N perché N ha la precedenza su B (come visto nella domanda 23339).', '"dopo essersi portato al centro" chiarisce la fase della manovra: prima si posiziona, poi aspetta.', 'Al centro? Aspetta chi ha la precedenza (N).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23343, 'Il veicolo R si trova alla destra del veicolo B. Anche se R è bloccato, la sua presenza significa che la destra di B non è ''libera''.', '"destra libera" significa che non ci sono veicoli alla tua destra. Qui c''è R, quindi non è libera.', 'R è a destra di B, quindi la destra non è libera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23344, 'Anche se B svolta a sinistra e deve dare molte precedenze, non è detto che sia l''ultimo ad ''impegnare'' l''incrocio. Come abbiamo visto nella domanda 23340, B può portarsi al centro prima di R. Quindi non è l''ultimo ad entrare.', '"per ultimo" è la parola trappola. B non è l''ultimo ad entrare, anche se è l''ultimo a completare la svolta rispetto a D e N.', 'Non sempre l''ultimo ad entrare, anche se svolti a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23345, 'Questa è la domanda più delicata. Normalmente, B dovrebbe dare la precedenza a R perché R è alla sua destra. Ma in questo incrocio ''bloccato'', R è a sua volta bloccato da D. Poiché R non può muoversi, B non deve ''dare la precedenza'' a R nel senso di aspettare che R passi, ma può avanzare al centro dell''incrocio.', '"deve dare la precedenza" qui è una trappola. Se R è bloccato, non può esercitare la sua precedenza, quindi B non deve ''aspettarlo'' attivamente per muoversi al centro.', 'Se chi ha la precedenza è bloccato, non devi aspettarlo per avanzare al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23346, 'Il veicolo P ha il segnale di ''Dare precedenza''. Questo significa che deve fermarsi o rallentare e far passare gli altri veicoli che non hanno questo segnale o che sono tram. Il tram (T) ha sempre la precedenza. Il veicolo G non ha il segnale di ''Dare precedenza'', quindi ha la precedenza su P. Per questo, P deve dare la precedenza sia al tram T che al veicolo G.', 'Il segnale di ''Dare precedenza'' è la chiave: ti obbliga a far passare chi non ce l''ha o chi è un tram.', 'Segnale ''Dare precedenza'' = cedi a tram e a chi non ha il segnale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23347, 'Sia il veicolo P che il veicolo B hanno il segnale di ''Dare precedenza''. Dopo che sono passati il tram (T) e il veicolo G (che hanno la precedenza su entrambi), dobbiamo decidere chi passa tra P e B. In questo caso, P va dritto e B gira a sinistra. La regola dice che, a parità di condizioni (entrambi con ''Dare precedenza''), chi va dritto ha la precedenza su chi gira. Inoltre, P si trova alla destra di B rispetto alla loro traiettoria finale nell''incrocio. Quindi, P ha la precedenza su B.', 'Quando due veicoli hanno lo stesso segnale di ''Dare precedenza'', si applicano le regole generali: chi va dritto ha la precedenza su chi gira, e chi viene da destra ha la precedenza.', 'Tra due ''Dare precedenza'', chi va dritto e da destra passa prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23348, 'Analizziamo l''ordine di passaggio: 1. Il tram (T) ha sempre la precedenza. 2. Il veicolo G non ha il segnale di ''Dare precedenza'', mentre P e B sì, quindi G passa dopo T. 3. Tra P e B, entrambi con ''Dare precedenza'', P va dritto e B gira a sinistra, quindi P passa prima di B. L''ordine finale è T, poi G, poi P, e infine B. La frase dice che P passa dopo T e G, ma prima di B, ed è corretto.', 'La frase descrive l''ordine di passaggio. ''Dopo'' e ''prima'' sono le parole chiave per capire la sequenza.', 'Ordine: Tram > G (senza segnale) > P (dritto) > B (gira).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23349, 'La frase dice che P transita ''contemporaneamente'' al veicolo B. Questo è falso. Come spiegato prima, P ha la precedenza su B (perché P va dritto e B gira a sinistra, e P è alla destra di B dopo aver ceduto a T e G). Quindi, P passa prima di B, non contemporaneamente. La parte ''dopo il tram'' è corretta, ma ''contemporaneamente al veicolo B'' rende l''intera affermazione falsa.', 'La parola ''contemporaneamente'' è la trappola. Significa ''nello stesso momento'', ma P e B non passano insieme.', 'Non ''contemporaneamente'': P passa prima di B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23350, 'Il veicolo P ha il segnale di ''Dare precedenza''. Questo significa che deve cedere il passo ad altri veicoli, come il tram (T) e il veicolo G (che non ha il segnale di ''Dare precedenza''). Quindi, P non ha la precedenza su tutti i veicoli, ma solo su B. Per questo motivo, l''affermazione è falsa.', 'La parola ''tutti'' è una trappola comune. Raramente un veicolo ha la precedenza su ''tutti'' gli altri in un incrocio complesso.', '''Tutti'' è quasi sempre falso, controlla sempre i segnali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23351, 'Il veicolo P ha il segnale di ''Dare precedenza''. Questo significa che deve cedere il passo a tutti i veicoli che non hanno questo segnale e ai tram. P deve dare la precedenza al tram (T) e al veicolo G (che viene dalla sua sinistra, ma non ha il segnale di ''Dare precedenza''). Quindi, P non deve dare la precedenza ''solo'' al veicolo proveniente dalla sua destra, ma anche a T e G. L''affermazione è falsa.', 'La parola ''solo'' è una trappola. Indica un''esclusività che spesso non è vera. P deve cedere a più veicoli, non solo a uno specifico.', '''Solo'' è spesso falso: P cede a T e G, non solo a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23352, 'VERO. Il veicolo L si trova alla destra del veicolo E. In assenza di segnali stradali specifici, la regola generale della precedenza impone di dare la precedenza a chi proviene dalla propria destra. Quindi, E deve aspettare L.', 'La frase ''deve dare la precedenza'' indica un obbligo chiaro e non negoziabile.', 'Destra libera, via libera! L è a destra di E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23353, 'VERO. Il veicolo L proviene dalla destra del veicolo E. Come spiegato prima, la regola fondamentale negli incroci senza segnaletica è dare la precedenza a chi viene da destra.', 'La locuzione ''proveniente dalla sua destra'' si riferisce specificamente al veicolo L.', 'Chi viene da destra ha la precedenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23354, 'VERO. Dopo che il veicolo L è passato, il veicolo E può proseguire. Il filobus R si trova in una posizione tale che E passa prima di lui. L''ordine di passaggio è L, poi E, poi N, e infine R.', 'La negazione ''non ha l''obbligo'' è cruciale: significa che E passa prima di R.', 'E non aspetta R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23355, 'VERO. Il veicolo E deve dare la precedenza a L (che è alla sua destra), quindi passa dopo L. Successivamente, E passa prima dell''autocarro N. La sequenza corretta è L, poi E, poi N, e infine R.', 'La frase ''prima dell''autocarro N, dopo il transito del veicolo L'' specifica l''esatto posizionamento di E nella sequenza di passaggio.', 'L-E-N: L primo, E secondo, N terzo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23356, 'FALSO. Questa affermazione è falsa perché il veicolo E passa prima del filobus R, non dopo. La sequenza corretta di passaggio è L, E, N, R.', 'La parola ''dopo'' riferita al filobus rende l''affermazione falsa. E passa ''prima'' del filobus.', 'E non aspetta R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23357, 'FALSO. Il veicolo E passa prima dell''autocarro N. Inoltre, l''autocarro N non prosegue diritto, ma svolta a sinistra, come indicato dalla freccia. Quindi ci sono due errori nell''affermazione.', 'La congiunzione ''perché'' introduce una motivazione errata (''prosegue diritto'') e la premessa (''deve dare la precedenza all''autocarro'') è anch''essa falsa.', 'N svolta, non va dritto. E passa prima di N.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23358, 'FALSO. Il veicolo E deve dare la precedenza al veicolo L, che proviene dalla sua destra. Quindi non ha la precedenza su tutti i veicoli, in particolare non su quelli alla sua destra.', 'La generalizzazione ''su tutti i veicoli provenienti da destra e da sinistra'' è una tipica parola trappola. E deve dare precedenza a destra.', 'E dà precedenza a destra (a L).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23359, 'FALSO. Il veicolo L passa per primo, poiché il veicolo E deve dargli la precedenza. E non è il primo a passare.', 'La frase ''passa per primo'' è un''affermazione assoluta che qui è falsa.', 'L è il primo a passare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23360, 'In questo incrocio, tutti i veicoli si trovano in una situazione di "blocco" perché ognuno ha un altro veicolo alla sua destra. Per risolvere questo blocco, si segue un ordine specifico. Il veicolo S passa per primo. Di conseguenza, il veicolo B deve aspettare e dare la precedenza a S.', '"deve dare la precedenza" significa che B non può passare prima di S, ma deve aspettare.', 'S passa per primo, quindi B aspetta S.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23361, 'Questo è l''ordine corretto per attraversare l''incrocio in questa specifica situazione di blocco. Nonostante la regola generale della precedenza a destra, in questi casi particolari si adotta questa sequenza per sbloccare il traffico. S passa per primo, poi B, poi L, e infine D.', '"ordine di transito" indica la sequenza in cui i veicoli attraversano l''incrocio.', 'Memorizza la sequenza S, B, L, D per questo incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23362, 'L''ordine corretto è S, B, L, D. I veicoli D e L non possono passare contemporaneamente perché i loro percorsi si incrociano e creerebbero un pericolo. Devono passare uno dopo l''altro.', '"contemporaneamente" significa nello stesso momento. Non è possibile per D e L passare insieme.', 'D e L non passano mai insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23363, 'L''ordine corretto è S, B, L, D. I veicoli S e D non possono passare contemporaneamente. S ha D alla sua destra e i loro percorsi si incrociano. Non è sicuro né permesso che passino insieme.', '"contemporaneamente" significa nello stesso momento. Non è possibile per S e D passare insieme.', 'S e D non passano mai insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23364, 'In questa intersezione, il veicolo D (l''autocarro) transita prima del veicolo F (il filobus). Questo perché, dopo che il veicolo R è passato, il veicolo D non ha più veicoli alla sua destra. Il veicolo F, invece, ha il veicolo D alla sua destra e deve aspettare che D passi.', 'La frase ''transita prima'' significa semplicemente che passa per primo o in anticipo rispetto all''altro veicolo. Non indica una precedenza speciale, ma l''ordine di passaggio.', 'D ha F alla sua sinistra, quindi D passa prima di F.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23365, 'L''ordine corretto di transito è R, D, F. Il veicolo R (l''auto gialla) passa per primo perché non ha nessun veicolo alla sua destra. Poi passa il veicolo D (l''autocarro) perché R è già passato e F è alla sua sinistra. Infine, passa il veicolo F (il filobus) perché non ha più veicoli alla sua destra.', 'La frase ''ordine di transito'' si riferisce alla sequenza in cui i veicoli attraversano l''incrocio. È importante capire chi passa prima, chi dopo e chi per ultimo.', 'R libera la destra di D, poi D libera la destra di F. Ordine: R, D, F.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23366, 'Questa affermazione è falsa. Il filobus non passa per primo. La regola generale della precedenza a destra si applica anche ai filobus, a meno che non ci siano segnali stradali specifici che indicano diversamente. Il fatto che sia ''vincolato alla linea elettrica aerea'' non gli dà automaticamente la precedenza in un incrocio senza segnaletica.', 'La parte ''perché vincolato alla linea elettrica aerea'' è la parola trappola. Molti pensano che i veicoli su rotaia o con vincoli di percorso abbiano sempre la precedenza, ma non è così in tutti i casi, specialmente in assenza di segnaletica specifica.', 'Filobus = veicolo normale. Non ha precedenza ''speciale'' solo per la linea.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23367, 'Questa affermazione è falsa. L''ordine di transito corretto, come abbiamo visto, è R, D, F. Il veicolo F (il filobus) non può passare per primo perché ha sia il veicolo R che il veicolo D alla sua destra, e deve dare loro la precedenza.', 'Anche qui, ''ordine di transito'' è la chiave. È fondamentale identificare correttamente la sequenza di passaggio per non cadere in errore.', 'F è l''ultimo! Ha R e D alla sua destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23368, 'Il veicolo T non ha nessun altro veicolo alla sua destra. Secondo la regola generale della precedenza a destra, chi non ha nessuno a destra passa per primo. Quindi, il veicolo T transita per primo, non per ultimo. L''affermazione che T passa per ultimo è FALSA.', 'La parola "ultimo" è la chiave. Se T passa per primo, non può passare per ultimo.', 'Destra libera, via libera! T ha la destra libera, quindi passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23369, 'L''ordine corretto di precedenza si stabilisce applicando la regola della precedenza a destra. Il veicolo T non ha nessuno a destra e passa per primo. Poi D, che non ha più T alla sua destra. Poi B, che non ha più D alla sua destra. Infine R, che non ha più B alla sua destra. L''ordine corretto è T, D, B, R. L''affermazione che l''ordine è R, B, D, T è FALSA.', '"Ordine di precedenza" indica la sequenza di transito. La sequenza proposta (R, B, D, T) è l''opposto di quella corretta.', 'Ricorda: T, D, B, R. Chi ha la destra libera va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23370, 'Applicando la regola della precedenza a destra, l''ordine di transito è T, poi D, poi B, e infine R. Questo significa che il veicolo D transita effettivamente prima del veicolo B. L''affermazione che D transita prima di B è VERA.', 'Le parole "prima" e "dopo" sono fondamentali per capire la sequenza.', 'D precede B. L''ordine è T, D, B, R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23371, 'Il veicolo N non ha il segnale di ''Dare Precedenza'', quindi ha la precedenza su A e R che invece ce l''hanno. Dopo che N è passato, tra A e R, il veicolo A si trova alla destra di R. Per la regola generale della precedenza a destra, A transita prima di R. Quindi l''ordine è N, A, R.', 'L''espressione ''ordine di transito'' indica la sequenza esatta in cui i veicoli devono attraversare l''incrocio.', 'N senza segnale va per primo, poi A (a destra di R).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23372, 'I veicoli A e R hanno il segnale di ''Dare Precedenza''. Questo segnale significa che devono dare la precedenza agli altri veicoli e, se non c''è spazio o se arriva un veicolo con precedenza (come N), devono fermarsi per permettere il transito.', 'La frase ''se necessario'' è una parola trappola. Non significa che devono fermarsi sempre, ma solo se le condizioni del traffico o la presenza di veicoli con precedenza lo richiedono.', 'Dare Precedenza = Fermati solo se serve.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23373, 'Questa domanda conferma l''ordine di transito corretto. N ha la precedenza su tutti. Dopo N, tra A e R, A ha la precedenza perché viene da destra rispetto a R, anche se entrambi hanno il segnale di ''Dare Precedenza'' (una volta che la strada principale è libera).', 'La costruzione ''può transitare prima... ma dopo...'' serve a specificare la posizione intermedia del veicolo A nell''ordine di passaggio.', 'N prima, poi A (destra di R), poi R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23374, 'Questa affermazione è falsa perché il veicolo N non ha il segnale di ''Dare Precedenza'' e quindi ha la precedenza su A e R. N deve transitare per primo, non A.', 'L''espressione ''ordine di transito'' indica la sequenza esatta in cui i veicoli devono attraversare l''incrocio. È importante non confonderla.', 'N senza segnale = N va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23375, 'Questa affermazione è falsa. L''ordine corretto è N, A, R. Il veicolo A ha la precedenza su R perché si trova alla sua destra, dopo che N ha liberato l''incrocio.', 'L''espressione ''ordine di precedenza'' è un sinonimo di ''ordine di transito'' e si riferisce a chi ha il diritto di passare per primo.', 'A è a destra di R, quindi A precede R.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23376, 'Il tram (veicolo T) ha sempre la precedenza sugli altri veicoli, a meno che non ci siano semafori o segnali specifici che dicano il contrario. Nell''immagine non ci sono segnali, quindi il tram passa per primo.', 'La frase ''transita per primo'' significa che il veicolo passa prima di tutti gli altri. È importante capire che il tram ha una precedenza speciale.', 'Tram = Precedenza quasi sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23377, 'Il tram (T) passa per primo. Dopo il tram, dobbiamo guardare P e M. Il veicolo P viene da destra rispetto al veicolo M. Per la regola della precedenza a destra, P passa prima di M. Quindi l''ordine è T, P, M.', 'La frase ''nel seguente ordine'' chiede la sequenza esatta di passaggio dei veicoli. Bisogna applicare tutte le regole di precedenza.', 'Tram, poi chi viene da destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23378, 'Abbiamo stabilito che l''ordine di passaggio è T, P, M. Questo significa che il veicolo M è l''ultimo a transitare, perché deve dare la precedenza sia al tram (T) che al veicolo P (che viene dalla sua destra).', 'La frase ''transita per ultimo'' significa che il veicolo passa dopo tutti gli altri. È il contrario di ''transita per primo''.', 'M è l''ultimo perché P è alla sua destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23379, 'Anche se il veicolo M è un autobus (un servizio pubblico), questo non gli dà automaticamente la precedenza in un incrocio senza altri segnali specifici. Deve comunque rispettare le normali regole di precedenza, come dare la precedenza al tram e a chi viene da destra.', 'La parola trappola è ''perché è in servizio pubblico''. Essere un servizio pubblico non significa avere precedenza automatica in un incrocio, a meno di situazioni particolari (es. veicoli di emergenza con sirena e lampeggiante, o in partenza da fermata con freccia, ma non in questo caso).', 'Servizio pubblico non è precedenza automatica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23380, 'L''ordine corretto di passaggio è T, P, M. Questa domanda propone l''ordine T, M, P. Questo è sbagliato perché il veicolo P ha la precedenza sul veicolo M (P viene da destra rispetto a M).', 'La frase ''nel seguente ordine: T, M, P'' presenta un ordine errato. È fondamentale capire la differenza tra P che precede M e M che precede P.', 'P è a destra di M, quindi P prima di M.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23381, 'Il tram (T) ha la precedenza sempre, a meno di segnali specifici che lo vietino. La sua precedenza non dipende dal fatto che il veicolo M sia o meno un servizio pubblico di linea. Il tram passa per primo in ogni caso.', 'La condizione ''purché il veicolo M non stia svolgendo un servizio pubblico di linea'' è la trappola. La precedenza del tram è una regola generale e non è legata allo status degli altri veicoli.', 'Tram ha precedenza, punto. Non dipende da altri veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23382, 'In questo incrocio, la presenza del veicolo eccezionale D rende la situazione particolare. Anche se R svolta a sinistra e di solito dovrebbe dare precedenza, in questo specifico quiz, R è il primo a passare per liberare l''incrocio. Quindi l''affermazione è VERA.', 'La frase "passa per primo" è la chiave. Nonostante le regole generali, in questo caso specifico è VERO.', 'R come ''Rapido'' a liberare l''incrocio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23383, 'L''ordine corretto di transito in questo incrocio è R, poi D, e infine A. R passa per primo, come spiegato. Poi il veicolo eccezionale D, per la sua mole e la necessità di manovre ampie, transita prima di A. Infine, A attende che gli altri due veicoli abbiano liberato l''incrocio. Quindi l''affermazione è VERA.', 'La frase "seguente ordine" richiede di conoscere la sequenza esatta. La presenza del "veicolo eccezionale" è una trappola che spesso fa pensare che sia l''ultimo, ma qui è secondo.', 'R-D-A: Ricorda Difficile Andare (contro l''ordine del quiz!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23384, 'Questa affermazione è FALSO perché, come abbiamo visto, il veicolo R passa per primo. Il veicolo D transita dopo R, quindi R passa prima di D, non il contrario.', 'La frase "prima del veicolo R" è la parte da analizzare. Se R passa per primo, D non può passare prima di R.', 'R è il ''Re'' della precedenza qui.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23385, 'Questa affermazione è FALSO. L''ordine corretto di transito è R, D, A. Quindi, l''ordine D, A, R è sbagliato perché D non passa per primo e A non passa per secondo.', 'La frase "seguente ordine" e la sequenza proposta. È importante non confondere l''ordine corretto con quello sbagliato.', 'L''ordine D, A, R è ''Disordinato, Assolutamente sbagliato, Ricorda l''ordine giusto!''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23386, 'Questa affermazione è FALSO. I veicoli non possono passare contemporaneamente perché le loro traiettorie si incrociano e hanno precedenze diverse. R passa per primo, mentre A passa per ultimo, quindi non possono transitare nello stesso momento.', 'La parola "contemporaneamente" è la trappola. In un incrocio con precedenze, è raro che veicoli con traiettorie che si intersecano passino nello stesso momento.', 'Contemporaneamente? No, c''è un ordine preciso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23387, 'Il veicolo T è un tram. I tram hanno quasi sempre la precedenza sugli altri veicoli, a meno che non ci siano semafori o segnali specifici che dicano il contrario. In questo incrocio non ci sono segnali, quindi il tram passa per primo.', '"per primo" - significa che è il primo in assoluto a passare.', 'Tram = Precedenza quasi sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23388, 'Dopo che il tram (T) è passato, dobbiamo decidere tra A e S. Il veicolo A non ha nessun altro veicolo alla sua destra che deve dargli la precedenza. Il veicolo S, invece, ha il veicolo A alla sua destra. Per la regola della precedenza a destra, A passa prima di S. Quindi A passa subito dopo T.', '"subito dopo" - indica l''ordine immediato.', 'Dopo il tram, chi ha la destra libera passa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23389, 'Il veicolo S deve dare la precedenza sia al tram (T) perché i tram hanno precedenza, sia al veicolo A perché A si trova alla destra di S (e non ha nessuno alla sua destra). Quindi S deve aspettare che sia T che A siano passati.', '"deve attendere" - indica un obbligo di aspettare.', 'S ha T e A alla sua destra, quindi aspetta entrambi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23390, 'Riassumendo le regole: il tram (T) ha la precedenza su tutti. Dopo il tram, tra A e S, il veicolo A non ha nessuno alla sua destra, mentre S ha A alla sua destra. Quindi A passa prima di S. L''ordine corretto è T, poi A, poi S.', '"nel seguente ordine" - specifica la sequenza esatta.', 'Tram, poi chi ha la destra libera, poi l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23391, 'Il veicolo A non transita per primo. Il tram (T) ha la precedenza su tutti gli altri veicoli, quindi è il tram a passare per primo, non il veicolo A.', '"per primo" - è la parola chiave che rende l''affermazione falsa, perché il tram passa prima.', 'Il tram è sempre il primo (salvo eccezioni).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23392, 'L''ordine indicato è sbagliato. Il veicolo A non può passare per primo perché il tram (T) ha la precedenza. L''ordine corretto è T, A, S.', '"nel seguente ordine: A, T, S" - l''intera sequenza è errata.', 'Il tram non è mai secondo o terzo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23393, 'Questa affermazione è falsa. Il veicolo S transita dopo il veicolo T, ma non prima del veicolo A. S deve dare la precedenza ad A perché A si trova alla sua destra. Quindi S transita per ultimo, dopo T e dopo A.', '"ma prima del veicolo A" - questa parte rende l''affermazione falsa.', 'S ha A a destra, quindi A passa prima di S.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23394, 'I veicoli A e S non possono transitare contemporaneamente. Dopo il passaggio del tram (T), il veicolo A ha la precedenza su S (perché S ha A alla sua destra). Quindi prima passa A, poi passa S. Non passano insieme.', '"contemporaneamente" - questa parola rende l''affermazione falsa.', 'Mai contemporaneamente se c''è una precedenza da rispettare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23395, 'In questo incrocio, la sequenza di transito corretta è P, poi B, e infine C. Questo significa che il veicolo B deve aspettare che il veicolo P sia passato prima di poter procedere.', 'La frase ''deve attendere'' indica un obbligo di dare la precedenza.', 'P è il primo, B lo segue.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23396, 'Secondo le regole di questo specifico incrocio, il veicolo P è il primo a impegnare e attraversare l''incrocio, dando il via alla sequenza di transito.', 'La parola chiave ''per primo'' significa che nessun altro veicolo lo precede.', 'P è il ''pioniere''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23397, 'La sequenza corretta per il transito dei veicoli in questo incrocio è P per primo, seguito da B, e infine C. Questa è la soluzione specifica per questo tipo di diagramma.', 'La frase ''nell''ordine'' specifica la successione esatta dei veicoli.', 'Ricorda la sequenza: P-B-C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23398, 'Il veicolo C ha il veicolo B alla sua destra. Secondo la regola generale della precedenza a destra, se un veicolo ha un altro veicolo alla sua destra, la sua ''destra è occupata'' e deve dare la precedenza.', 'L''espressione ''destra occupata'' significa che c''è un veicolo alla propria destra a cui dare la precedenza.', 'C vede B alla sua destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23399, 'Nella sequenza di transito P, B, C, il veicolo B transita per secondo, non per ultimo. L''ultimo veicolo a transitare è C.', 'La parola ''per ultimo'' è la trappola; B non è l''ultimo.', 'C è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23400, 'La sequenza corretta di transito per questo incrocio è P, B, C. La domanda propone l''ordine P, C, B, che è sbagliato perché B transita prima di C.', 'Attenzione all''ordine ''P, C, B'' che inverte gli ultimi due veicoli rispetto alla sequenza corretta.', 'Non P-C-B, ma P-B-C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23401, 'I veicoli P e C non transitano nello stesso momento. P transita per primo e C transita per ultimo, quindi c''è un intervallo di tempo tra il loro passaggio.', 'La parola ''contemporaneamente'' è la trappola, perché i veicoli transitano uno dopo l''altro.', 'Uno alla volta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23402, 'Il veicolo P impegna l''incrocio per primo e prosegue il suo percorso senza doversi fermare al centro. La fermata al centro è prevista solo in casi specifici, ad esempio per dare precedenza a veicoli provenienti da senso opposto quando si svolta a sinistra, ma non è il caso qui per il primo veicolo.', 'La frase ''si deve fermare al centro di esso'' è la parte sbagliata dell''affermazione.', 'P va senza fermarsi al centro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23403, 'In questo incrocio, il veicolo B transita per primo. Questa è una situazione particolare dove, nonostante B giri a sinistra, ha la precedenza sugli altri veicoli.', 'La frase ''transita per primo'' indica che B non deve dare la precedenza a nessuno. È una situazione specifica che va memorizzata.', 'In questo incrocio, B va per primo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23404, 'L''ordine corretto di transito per i veicoli in questo incrocio è B, poi T, e infine S. B passa per primo, poi T, e S è l''ultimo.', 'La frase ''seguente ordine'' richiede di conoscere la sequenza esatta. Non confondere con la regola generale della precedenza a destra, qui c''è un''eccezione.', 'L''ordine è B, T, S.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23405, 'Il veicolo S transita per ultimo. Deve aspettare che sia B che T abbiano liberato l''incrocio prima di poter passare.', 'La frase ''transita per ultimo'' significa che S deve dare la precedenza a tutti gli altri veicoli.', 'S è l''ultimo ad andare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23406, 'Questa affermazione è falsa perché l''ordine corretto di transito è B, T, S, e non S, B, T. S non transita per primo.', 'Attenzione all''ordine proposto: ''S, B, T'' è l''opposto dell''ordine corretto per questo incrocio.', 'Non è S, B, T.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23407, 'Questa affermazione è falsa. Il veicolo B transita per primo, quindi non deve dare la precedenza al veicolo T.', 'La frase ''deve dare la precedenza'' indica un obbligo. In questo caso, B non ha questo obbligo verso T.', 'B non dà precedenza a T.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23408, 'Questa affermazione è falsa. In ogni incrocio, anche se si ha la precedenza, è sempre obbligatorio moderare la velocità per garantire la sicurezza e prevenire incidenti.', 'La parola ''nessuno'' è una parola trappola. È quasi sempre falso che ''nessuno'' debba fare qualcosa di prudente alla guida.', 'Agli incroci, sempre moderare la velocità!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23409, 'Questa affermazione è falsa. I veicoli B e S hanno percorsi che si incrociano all''interno dell''incrocio, quindi non possono transitare contemporaneamente senza rischio di collisione.', 'La parola ''contemporaneamente'' è una trappola. Se i percorsi si incrociano, non si può passare nello stesso momento.', 'Percorsi che si incrociano = non contemporaneamente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23410, 'Il veicolo R (giallo) non ha nessun veicolo alla sua destra, quindi transita per primo. Il veicolo A (blu) transita dopo R, come secondo veicolo. Per questo motivo, l''affermazione è VERA.', 'La frase "dopo il veicolo R" indica una sequenza temporale. Se R passa per primo, A deve passare dopo.', 'R è il primo, A è il secondo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23411, 'Il veicolo R (giallo) non ha nessun veicolo che proviene dalla sua destra. Secondo la regola generale della precedenza a destra, R può transitare per primo senza dover dare la precedenza a nessun altro veicolo. Per questo motivo, l''affermazione è VERA.', 'La parte "non deve dare la precedenza ad alcun veicolo" significa che R ha la precedenza assoluta in questo incrocio.', 'R è libero, va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23412, 'Dopo che il veicolo R è passato, rimangono i veicoli A (blu) e C (rosso). In questo specifico incrocio, il veicolo C deve dare la precedenza al veicolo A. Questo significa che A transita prima di C. Per questo motivo, l''affermazione è VERA.', 'Attenzione! Questa è una situazione particolare e spesso causa confusione. Normalmente, il veicolo C (che ha A alla sua sinistra) avrebbe la precedenza. Tuttavia, per questo specifico diagramma, la risposta corretta indica che C deve dare la precedenza ad A.', 'Per questo incrocio, A prima di C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23413, 'Analizzando le precedenze: R (giallo) non ha nessuno alla sua destra e passa per primo. Poi, tra A (blu) e C (rosso), il veicolo A transita prima di C (come spiegato nella domanda 23412). Quindi l''ordine corretto è R, A, C. Per questo motivo, l''affermazione è VERA.', 'La frase "nel seguente ordine: R, A, C" riassume l''intera sequenza di transito. È fondamentale memorizzare l''ordine corretto per questo incrocio.', 'L''ordine è R-A-C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23414, 'Il veicolo C (rosso) deve dare la precedenza sia al veicolo R (giallo), che passa per primo, sia al veicolo A (blu), che passa prima di C. Quindi, l''affermazione che C non deve dare la precedenza a nessuno è FALSO.', 'La parola "alcun" rende l''affermazione assoluta. Se un veicolo deve dare la precedenza anche solo a uno, l''affermazione con "alcun" è falsa.', 'C non è l''ultimo, deve aspettare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23415, 'Il veicolo R (giallo) transita per primo, mentre il veicolo C (rosso) transita per ultimo. Non possono transitare nello stesso momento perché R ha la precedenza su C. Per questo motivo, l''affermazione è FALSO.', 'La parola "contemporaneamente" significa nello stesso momento. Negli incroci con precedenze, è raro che più veicoli transitino contemporaneamente.', 'Mai ''contemporaneamente'' se c''è un ordine.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23416, 'L''ordine corretto di transito, come stabilito dalle regole di precedenza per questo incrocio, è R, A, C. L''affermazione propone un ordine diverso (R, C, A), invertendo A e C. Per questo motivo, l''affermazione è FALSO.', 'Controlla sempre l''ordine esatto. La differenza tra A e C è cruciale per la correttezza dell''affermazione.', 'L''ordine è R-A-C, non R-C-A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23417, 'Il veicolo R (giallo) non ha nessun veicolo alla sua destra, quindi ha la precedenza su tutti gli altri veicoli (A e C). Per questo motivo, R transita per primo e non deve attendere nessuno. Per questo motivo, l''affermazione è FALSO.', 'La frase "deve attendere" è una trappola quando il veicolo in questione ha la precedenza assoluta.', 'R non aspetta nessuno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23418, 'In questo incrocio, l''ordine corretto di passaggio è H, D, B. Il veicolo H (rosso) passa per primo perché non ha nessun veicolo alla sua destra e il veicolo D (giallo), a cui dovrebbe dare la precedenza, è a sua volta bloccato dal veicolo B (blu). Quindi H può passare. Dopo H, passa il veicolo D. Infine, il veicolo B passa per ultimo.', 'La difficoltà sta nell''interpretare la precedenza quando più veicoli sono coinvolti e si bloccano a vicenda. La regola generale ''chi svolta a sinistra dà precedenza'' qui è ''superata'' dal fatto che il veicolo a cui dare precedenza (D) è bloccato.', 'H è ''libero'' e D è ''bloccato da B'', quindi H va. Poi D va prima di B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23419, 'Sì, il veicolo B (blu) deve passare per ultimo. Questo perché il veicolo D (giallo) passa prima di B in questo specifico incrocio, e il veicolo H (rosso) passa prima di tutti.', 'La frase ''per ultimo'' è chiara. La trappola è capire perché B non ha la precedenza su D, dato che D ha B alla sua destra (una regola che qui non si applica come ci si aspetterebbe).', 'B è l''ultimo della fila.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23420, 'Il veicolo H (rosso) non deve dare la precedenza a nessun veicolo in questo caso. Anche se svolta a sinistra e dovrebbe dare precedenza a D (giallo), D è bloccato dal veicolo B (blu). Inoltre, H non ha veicoli alla sua destra.', 'La frase ''non deve dare la precedenza ad alcun veicolo'' è la chiave. Normalmente, chi svolta a sinistra dà precedenza, ma qui è un''eccezione.', 'H ha la strada ''libera'' per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23421, 'Sì, il veicolo D (giallo) deve dare la precedenza al veicolo H (rosso). Questo è coerente con il fatto che H passa per primo nell''incrocio.', 'La frase ''deve dare la precedenza'' è la chiave. Normalmente H darebbe precedenza a D (svolta a sinistra), ma in questo caso è il contrario.', 'D aspetta H.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23422, 'No, è falso. Il veicolo D (giallo) non deve attendere che il veicolo B (blu) sia transitato. In questo specifico incrocio, D passa prima di B.', 'La frase ''deve attendere'' è la trappola. La regola della precedenza a destra (D dovrebbe aspettare B) qui non si applica.', 'D non aspetta B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23423, 'No, è falso. L''ordine corretto di passaggio è H, D, B. Il veicolo D (giallo) passa prima del veicolo B (blu), quindi l''ordine H, B, D è sbagliato.', 'L''ordine dei veicoli è la chiave. ''H, B, D'' è sbagliato perché D passa prima di B.', 'D prima di B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23424, 'No, è falso. Il veicolo B (blu) non ha la precedenza sul veicolo D (giallo). In questo incrocio, D passa prima di B.', 'La frase ''ha la precedenza'' è la trappola. Normalmente B avrebbe precedenza su D (B è alla destra di D), ma qui è il contrario.', 'B non ha precedenza su D.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23425, 'No, è falso. I veicoli H (rosso) e B (blu) non possono passare contemporaneamente. H passa per primo, mentre B passa per ultimo, quindi non c''è possibilità di passaggio simultaneo.', 'La parola ''contemporaneamente'' è la chiave. Anche se non si incrociano direttamente, l''ordine di precedenza li separa.', 'Non contemporaneamente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23426, 'In questo incrocio si crea una situazione di ''blocco'' perché ogni veicolo ha un altro veicolo alla sua destra. Per risolvere il blocco e permettere a tutti di passare, il veicolo P è quello che può iniziare la manovra per primo.', 'La difficoltà non è nelle parole, ma nell''interpretazione di questo specifico incrocio a ''blocco'' che ha una soluzione particolare.', 'P sblocca il blocco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23427, 'Questa affermazione è vera. Anche se normalmente D non dovrebbe dare precedenza a P (perché P è alla sua sinistra), in questo specifico incrocio a ''blocco'', D cede il passo a P per permettere a P di passare per primo e sbloccare la situazione.', 'La frase ''D deve dare la precedenza al veicolo P'' è una ''parola trappola'' perché va contro la regola generale della precedenza a destra. Ricorda che è un''eccezione per questo tipo di incrocio.', 'D cede a P per sbloccare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23428, 'Il veicolo B deve aspettare sia P che D. B ha P alla sua destra, quindi deve dargli la precedenza. Inoltre, B sta svoltando a sinistra e deve dare precedenza ai veicoli che gli vengono incontro e vanno dritto, come D. Quindi B aspetta P e D.', 'Non ci sono parole trappola, ma è importante capire le due ragioni per cui B deve aspettare (P a destra, D di fronte e dritto).', 'B aspetta P (destra) e D (di fronte).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23429, 'Il veicolo L ha il veicolo B alla sua destra. Secondo la regola generale della precedenza a destra, L deve dare la precedenza a B.', 'Nessuna parola trappola. È una diretta applicazione della regola di precedenza a destra.', 'L ha B a destra, quindi L aspetta B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23430, 'Questo è l''ordine corretto di passaggio per risolvere il ''blocco'' di precedenze in questo incrocio. Prima passa P, poi D, poi B, e infine L.', 'L''ordine specifico ''P, D, B, L'' è la chiave. Ricordalo per questo incrocio.', 'L''ordine è P, D, B, L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23431, 'Questa affermazione è falsa. Il veicolo B non deve dare la precedenza a L. Anzi, è il contrario: L deve dare la precedenza a B perché B è alla destra di L. B ha P alla sua destra e deve dare precedenza a D (che gli viene incontro e va dritto).', 'La parte ''deve dare la precedenza al veicolo L'' è falsa. B non cede a L.', 'B non cede a L (L è a sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23432, 'Questa affermazione è falsa. Come abbiamo visto, il veicolo P è il primo a passare per sbloccare l''incrocio. Non deve aspettare gli altri tre veicoli, ma è lui che passa per primo.', 'La frase ''deve attendere che siano transitati gli altri tre veicoli'' è la parte falsa.', 'P è il primo, non l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23433, 'Questa affermazione è falsa. L''ordine corretto di passaggio è P, D, B, L. L''affermazione inverte l''ordine di B e L. L deve dare la precedenza a B (perché B è alla sua destra), quindi B passa prima di L.', 'L''ordine ''L, B'' è la parte falsa. Ricorda che B passa prima di L.', 'B prima di L (L aspetta B).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23434, 'Questa affermazione è falsa. Il primo veicolo a passare è P. D e L non possono passare contemporaneamente per primi, perché D deve aspettare L (se P fosse già passato) e L deve aspettare B.', 'La frase ''passano contemporaneamente per primi'' è la parte falsa. Solo un veicolo può passare per primo.', 'Solo P passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23435, 'In questo incrocio, i veicoli si trovano in una situazione di ''precedenza a catena'' o ''circolare'': E dovrebbe dare precedenza a C, C a M, e M a E. Per risolvere questa situazione di stallo, la regola generale è che il veicolo che svolta a destra (il veicolo E) transita per primo, perché ha il percorso più semplice e ''rompe'' la catena di precedenze.', 'La frase ''transita per primo'' indica che il veicolo E passa prima di tutti gli altri. È importante capire il motivo di questa precedenza speciale.', 'In caso di ''catena'' di precedenze, chi svolta a destra (E) va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23436, 'Dopo che il veicolo E ha attraversato l''incrocio (avendo la precedenza per rompere la catena), rimangono i veicoli C e M. Il veicolo C va dritto e ha il veicolo M alla sua sinistra. Secondo la regola della precedenza a destra, C ha la precedenza su M. Quindi, C transita dopo E.', 'La frase ''transita dopo il veicolo E'' significa che C passa in un momento successivo a E. Non significa che C è l''ultimo.', 'Dopo E, C ha la precedenza su M (C va dritto, M svolta a sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23437, 'L''ordine corretto di transito è E, C, M. E transita per primo per risolvere la situazione di precedenza circolare (svolta a destra). Poi, tra C e M, C va dritto e ha M alla sua sinistra, quindi C ha la precedenza su M. M, che svolta a sinistra, è l''ultimo a passare perché deve dare precedenza a entrambi.', 'La frase ''nel seguente ordine'' richiede la sequenza esatta di passaggio. È fondamentale conoscere l''ordine preciso.', 'L''ordine è E (svolta a destra), C (va dritto), M (svolta a sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23438, 'Il veicolo M svolta a sinistra. In un incrocio senza segnali, chi svolta a sinistra deve dare precedenza sia a chi viene da destra (E) sia a chi va dritto o svolta a destra (C). Per questo motivo, M è l''ultimo a passare, non il primo.', 'La parola ''primo'' è la trappola. Chi svolta a sinistra è quasi sempre l''ultimo a passare, non il primo.', 'Chi svolta a sinistra (M) è quasi sempre l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23439, 'L''ordine corretto di transito è E, C, M. L''affermazione propone un ordine diverso (C, M ed E), che è sbagliato. In particolare, C non è il primo (E lo è), e M non è il secondo (è l''ultimo).', 'L''intera sequenza ''C, M ed E'' è errata. Bisogna memorizzare l''ordine corretto per non cadere in queste trappole.', 'Ricorda l''ordine E, C, M. Qualsiasi altro ordine è sbagliato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23440, 'I veicoli M ed E non possono transitare contemporaneamente. Il veicolo E ha la precedenza su M (E è alla destra di M e M svolta a sinistra). Inoltre, le loro traiettorie si incrociano, quindi non possono passare nello stesso momento senza rischio di collisione.', 'La parola ''contemporaneamente'' è la trappola. Se c''è una regola di precedenza o le traiettorie si incrociano, i veicoli non possono passare nello stesso momento.', 'Se c''è precedenza o incrocio di traiettorie, non si passa mai contemporaneamente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23441, 'In questo incrocio, tutti i veicoli devono svoltare a sinistra e si crea una situazione particolare dove ognuno ha un veicolo alla sua destra. Per sbloccare l''incrocio, si considera che il veicolo A passi per primo. Una volta che A ha svoltato, libera la strada per gli altri.', 'La frase ''passa per primo'' significa che il veicolo A è il primo a muoversi nell''incrocio.', 'In questo incrocio ''a catena'' con tutti a sinistra, A sblocca la situazione e va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23442, 'Il veicolo C ha il veicolo A alla sua destra. Secondo la regola generale della precedenza a destra, C deve aspettare che A passi prima di muoversi.', 'L''espressione ''deve dare la precedenza'' significa che il veicolo C deve aspettare che l''altro veicolo (A) transiti.', 'C ha A a destra, quindi C aspetta A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23443, 'Dopo che A è passato, C può passare perché A non è più alla sua destra. Solo dopo che C è passato, L può passare perché C non è più alla sua destra. Per questo motivo, L è l''ultimo a muoversi nell''incrocio.', 'La frase ''passa per ultimo'' significa che il veicolo L è l''ultimo a muoversi nell''incrocio.', 'L aspetta C, C aspetta A. L è l''ultimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23444, 'La sequenza corretta per il passaggio dei veicoli in questo incrocio è: prima A, poi C, e infine L. Questo ordine permette di risolvere la situazione di ''blocco'' e di rispettare le precedenze.', 'La frase ''nel seguente ordine'' indica la sequenza esatta in cui i veicoli devono passare.', 'L''ordine corretto è A, C, L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23445, 'Questa affermazione è falsa perché il veicolo A è il primo a passare in questo incrocio. Non deve aspettare né L né C.', 'L''espressione ''deve attendere'' significa che dovrebbe aspettare, ma in questo caso è il contrario.', 'A non aspetta, A va per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23446, 'Questa affermazione è falsa. Il veicolo L è l''ultimo a passare nell''incrocio, non il primo.', 'La frase ''passa per primo'' è la parola trappola, perché L è l''ultimo.', 'L è l''ultimo, non il primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23447, 'Questa affermazione è falsa. L''ordine corretto di passaggio dei veicoli è A, C, L. L''ordine proposto (L, C, A) è sbagliato.', 'La frase ''nel seguente ordine'' introduce una sequenza che in questo caso è errata.', 'L''ordine corretto è A, C, L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23448, 'Questa affermazione è falsa. Il veicolo C deve dare la precedenza al veicolo A (che è alla sua destra). Il veicolo L è alla sinistra di C, quindi C non deve aspettare L. Anzi, è L che deve aspettare C.', 'La frase ''deve attendere il transito del veicolo L'' è la trappola, perché la precedenza si dà a destra, non a sinistra.', 'C aspetta A, non L. L aspetta C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23449, 'Il veicolo E non ha nessun veicolo alla sua destra che deve attraversare la sua traiettoria. Per questo motivo, il veicolo E può passare per primo senza dare la precedenza a nessuno.', '"non deve dare la precedenza ad alcun veicolo" - significa che E passa per primo.', 'E è "libero a destra", quindi passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23450, 'Il veicolo E passa per primo. Il veicolo C, per poter passare, deve aspettare che il veicolo E abbia completato la sua manovra. Quindi C deve dare la precedenza a E.', '"deve dare la precedenza" - significa che C deve aspettare.', 'E passa prima di C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23451, 'Il veicolo L deve aspettare prima il veicolo E, perché E passa per primo. Poi, tra L e C, il veicolo C va dritto mentre L gira a sinistra. Chi gira a sinistra deve dare la precedenza a chi va dritto. Quindi L deve aspettare anche C.', '"attendere il transito dei veicoli E e C" - significa che L passa per ultimo.', 'L gira a sinistra, aspetta tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23452, 'Abbiamo stabilito che il veicolo E passa per primo perché non ha nessuno alla sua destra. Poi, tra C e L, il veicolo C va dritto e L gira a sinistra, quindi L deve dare la precedenza a C. L''ordine corretto è E, poi C, e infine L.', '"disimpegnano l''incrocio nel seguente ordine" - indica la sequenza di passaggio.', 'E (libero), C (dritto), L (sinistra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23453, 'Questa affermazione è falsa. Dopo che E è passato, rimangono C e L. Il veicolo C va dritto, mentre il veicolo L gira a sinistra. La regola dice che chi gira a sinistra deve dare la precedenza a chi va dritto. Quindi è L che deve aspettare C, non il contrario.', '"deve attendere" - attenzione a chi aspetta chi.', 'C va dritto, L gira: C passa prima di L.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23454, 'Questa affermazione è falsa. Il veicolo E non ha nessun veicolo alla sua destra che deve attraversare la sua traiettoria, quindi è il primo a passare, non l''ultimo.', '"passare per ultimo" - è l''opposto di passare per primo.', 'E è libero a destra, passa per primo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23455, 'Questa affermazione è falsa. L''ordine corretto di passaggio è E, C, L. Il veicolo L deve dare la precedenza al veicolo C perché C va dritto e L gira a sinistra. Quindi L non può passare prima di C.', '"nel seguente ordine: E, L, C" - confrontare con l''ordine corretto E, C, L.', 'L gira a sinistra, C va dritto: L aspetta C.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23456, 'Questa affermazione è falsa. Il veicolo E passa per primo perché non ha nessuno alla sua destra. Il veicolo C deve dare la precedenza a E. Quindi non possono passare nello stesso momento.', '"passano contemporaneamente" - significa nello stesso momento.', 'E ha precedenza su C, quindi non passano insieme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23457, 'È fondamentale che tu possa vedere bene la strada davanti a te e intorno a te prima di iniziare un sorpasso. Se la visibilità è scarsa (per esempio per nebbia, pioggia forte o una curva cieca), non puoi sorpassare in sicurezza.', 'La parola ''accertarsi'' significa controllare con attenzione, assicurarsi che sia vero.', 'Se non vedi, non sorpassi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23458, 'Il sorpasso deve essere una manovra fluida e sicura, che non costringa gli altri veicoli a frenare bruscamente o a cambiare direzione per evitarti. Non devi creare problemi agli altri utenti della strada.', 'L''espressione ''senza costituire intralcio'' significa senza creare ostacolo, fastidio o pericolo per gli altri.', 'Sorpassa senza disturbare nessuno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23459, 'Prima di sorpassare, devi guardare se il veicolo davanti a te ha già messo la freccia per sorpassare a sua volta. Se sì, devi aspettare che finisca la sua manovra. Non si sorpassa chi sta già sorpassando.', 'L''espressione ''analoga manovra'' significa la stessa manovra, cioè il sorpasso.', 'Chi prima segnala, prima sorpassa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23460, 'Non devi controllare solo davanti, ma anche dietro di te. Se un veicolo che ti segue ha già iniziato a sorpassarti, non puoi iniziare tu la manovra. Devi dargli la precedenza.', 'La frase ''sulla stessa carreggiata'' si riferisce alla parte di strada dove si guida, che può avere più corsie.', 'Guarda avanti e dietro prima di agire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23461, 'Devi avere abbastanza spazio libero sulla strada per poter completare il sorpasso e rientrare nella tua corsia in sicurezza, senza tagliare la strada al veicolo sorpassato o a quelli che arrivano.', 'L''espressione ''completa esecuzione'' significa fare tutto il sorpasso, dall''inizio alla fine, incluso il rientro in corsia.', 'Spazio libero per rientrare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23462, 'Lo spazio necessario per sorpassare dipende da quanto più veloce vai tu rispetto al veicolo che vuoi sorpassare. Se la differenza di velocità è piccola, ti servirà più strada. Se è grande, meno.', 'La ''differenza di velocità'' è quanto la tua velocità è maggiore rispetto a quella del veicolo da sorpassare.', 'Poca differenza, lungo sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23463, 'Se la strada è a doppio senso di marcia, devi assicurarti che non stia arrivando nessun veicolo dalla direzione opposta mentre sei nella corsia di sorpasso. Se arriva qualcuno, devi avere il tempo di rientrare in sicurezza.', '''Eventuali veicoli'' significa ''se ci sono veicoli''. ''Direzione opposta'' è l''altra corsia di marcia.', 'Occhio al traffico che viene incontro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23464, 'Un veicolo più lungo (come un camion o un autobus) ha bisogno di più spazio e tempo per sorpassare rispetto a un''auto piccola. Devi considerare la dimensione di entrambi i veicoli.', 'L''espressione ''in relazione alla lunghezza'' significa ''in base a quanto sono lunghi''.', 'Veicoli lunghi, sorpassi lunghi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23465, 'La strada deve essere abbastanza larga da permetterti di sorpassare senza rischiare di finire fuori strada, di toccare il veicolo sorpassato o di invadere la corsia opposta in modo pericoloso.', 'La ''larghezza della carreggiata'' è quanto è larga la strada. ''In condizioni di sicurezza'' significa senza pericoli.', 'Strada stretta, sorpasso vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23466, 'Ci sono cartelli stradali specifici che vietano il sorpasso (ad esempio, il segnale rotondo bianco e nero con due auto). Devi sempre controllare che non ci siano questi segnali prima di sorpassare.', 'Un ''segnale verticale'' è un cartello stradale posizionato a lato della strada.', 'Rispetta i cartelli, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23467, 'Questa affermazione è FALSA. Non basta solo guardare se arrivano veicoli dalla direzione opposta. Ci sono molti altri fattori da considerare per un sorpasso sicuro: la visibilità, lo spazio, i veicoli che ti seguono, quelli che ti precedono, i segnali stradali, ecc.', 'La parola ''semplicemente'' è una parola trappola. Suggerisce che sia l''unica cosa da fare, ma il sorpasso richiede molte più attenzioni.', 'Mai ''semplicemente'', il sorpasso è complesso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23468, 'Questa affermazione è FALSA. Azionare l''indicatore di direzione (le frecce) è obbligatorio per segnalare la tua intenzione, ma non è l''unico obbligo. Devi anche controllare tutti gli altri aspetti di sicurezza visti nelle domande precedenti.', 'L''espressione ''unico obbligo'' è una parola trappola. Indica che non ci sono altri doveri, il che è sbagliato per il sorpasso.', 'Non solo freccia, ma anche testa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23469, 'Questa affermazione è FALSA. Controllare i segnali di divieto di sorpasso è molto importante, ma non è l''unica cosa da fare. Devi anche valutare la situazione del traffico, la visibilità, lo spazio disponibile e tutti gli altri fattori di sicurezza.', 'La parola ''unicamente'' è una parola trappola. Significa ''solo questo'', ma per il sorpasso ci sono molte più cose da considerare.', 'Non ''unicamente'', ma ''tutto'' per sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23470, 'Prima di iniziare qualsiasi manovra, come il sorpasso, è fondamentale segnalare la tua intenzione agli altri utenti della strada. Usare l''indicatore di direzione (la freccia) è obbligatorio per far capire cosa farai.', 'La parola ''occorre'' significa ''è necessario'' o ''si deve''. Indica un obbligo.', 'Freccia sempre prima di muoverti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23471, 'In Italia e nella maggior parte dei paesi con guida a destra, la regola generale è che il sorpasso si effettua sulla sinistra del veicolo che si vuole superare. Ci sono pochissime eccezioni, ma la norma è questa.', 'L''espressione ''di norma'' significa ''solitamente'', ''come regola generale''. Non significa ''sempre'', ma indica la prassi comune e corretta.', 'Sorpasso? A sinistra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23472, 'Quando sorpassi un altro veicolo, devi lasciare uno spazio sufficiente tra la tua auto e quella che stai superando. Questo spazio laterale è essenziale per la sicurezza di entrambi e per evitare collisioni.', 'L''espressione ''adeguata distanza laterale'' significa uno spazio giusto, né troppo poco né troppo, che garantisca la sicurezza.', 'Spazio laterale = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23473, 'Dopo aver completato il sorpasso, devi tornare nella corsia di destra. È importante farlo ''appena possibile'', ma soprattutto ''senza creare pericolo o intralcio'', cioè senza tagliare la strada o frenare bruscamente davanti al veicolo sorpassato.', 'Le condizioni ''appena possibile'' e ''senza creare pericolo o intralcio'' sono cruciali. Non basta tornare a destra, bisogna farlo in sicurezza.', 'Torna a destra, ma con calma e sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23474, 'Se un altro veicolo ti sta sorpassando, tu devi aiutarlo a completare la manovra in sicurezza. Questo significa che non devi accelerare e, se possibile, devi spostarti leggermente a destra per dargli più spazio.', 'La parola ''agevolare'' significa ''facilitare'', ''aiutare''. ''Non accelerare'' è un divieto fondamentale per la sicurezza.', 'Chi è sorpassato non accelera, anzi aiuta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23475, 'Su strade con una sola corsia per senso di marcia, se qualcuno ti sta sorpassando, devi spostarti il più possibile verso il margine destro della strada. Questo crea più spazio per il veicolo che ti sta superando e rende la manovra più sicura.', 'L''espressione ''il più vicino possibile al margine destro'' indica l''azione corretta da compiere per facilitare il sorpasso.', 'A destra per chi sorpassa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23476, 'Non devi mai sorpassare se non vedi bene la strada davanti a te (ad esempio, in curva, in salita, o se c''è nebbia) e non sei sicuro di poter finire il sorpasso in modo sicuro. La visibilità è fondamentale per la sicurezza.', 'Le parole ''non va effettuata'' e ''insufficiente per completarla in sicurezza'' sono chiare: se non ci sono le condizioni di sicurezza, il sorpasso è vietato.', 'Se non vedi bene, non sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23477, 'Se la strada è troppo stretta, non c''è abbastanza spazio per sorpassare in sicurezza. Potresti urtare il veicolo che sorpassi o finire fuori strada. La larghezza della carreggiata è un fattore di sicurezza importante.', 'Le parole ''non va effettuata'' e ''non è sufficientemente larga'' indicano un divieto basato sulla mancanza di spazio adeguato.', 'Strada stretta? No sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23478, 'Non è obbligatorio usare il clacson (segnale acustico) per sorpassare. Anzi, il clacson si usa solo in caso di pericolo immediato o, fuori dai centri abitati, per avvertire. Per il sorpasso si usa l''indicatore di direzione (la freccia).', 'La parola ''obbligo'' è la chiave. Non c''è l''obbligo di usare il segnale acustico per il sorpasso.', 'Clacson solo per pericolo, non per sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23479, 'Questa affermazione è falsa perché è sempre obbligatorio usare la freccia (indicatore di direzione) prima di iniziare un sorpasso. Serve a segnalare la tua intenzione agli altri conducenti e garantire la sicurezza.', 'L''espressione ''non ha l''obbligo'' è l''errore. L''obbligo di usare la freccia c''è sempre prima di sorpassare.', 'Freccia SEMPRE prima di sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23480, 'Dopo il sorpasso, devi tornare a destra, ma solo quando puoi farlo in sicurezza, senza ''tagliare la strada'' al veicolo che hai appena superato. Tornare ''immediatamente'' e ''tagliando la strada'' è pericoloso e vietato.', 'Le parole ''immediatamente'' e ''se taglia la strada'' rendono la frase falsa. Il rientro deve essere graduale e sicuro.', 'Torna a destra con spazio, mai tagliare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23481, 'Non devi mai fare una ''gara'' di velocità con chi ti sta sorpassando. È estremamente pericoloso e contro la legge. Il conducente sorpassato deve agevolare la manovra e non accelerare.', 'L''espressione ''gareggiare in velocità'' indica un comportamento vietato e molto rischioso.', 'No gare in strada, mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23482, 'Non devi mai sorpassare se non vedi bene la strada o se non sei sicuro di poter finire il sorpasso in sicurezza. Se lo spazio visibile è insufficiente, il sorpasso è vietato perché troppo rischioso.', 'L''espressione ''anche se lo spazio visibile risulta insufficiente'' è la condizione che rende la frase falsa. In queste condizioni, il sorpasso è proibito.', 'Se non vedi, non sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23483, 'In strade con almeno due corsie per senso di marcia (come le autostrade), se hai già sorpassato un veicolo e puoi sorpassarne un altro subito dopo senza creare pericolo o rallentare gli altri, puoi farlo senza tornare nella corsia più a destra. L''importante è non intralciare il traffico.', 'La frase chiave è ''senza rientrare a destra''. Non è sempre obbligatorio rientrare se le condizioni lo permettono e ''se non si crea intralcio'' è la condizione fondamentale.', 'Più corsie, più sorpassi a fila se non intralci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23484, 'Se un veicolo davanti a te mette la freccia a sinistra per svoltare, si sposterà verso il centro della strada. In questo caso, tu puoi sorpassarlo sulla sua destra, perché lui sta liberando la corsia di destra.', 'La frase ''deve essere eseguita a destra'' indica un caso specifico in cui il sorpasso a destra è permesso e obbligatorio. La condizione è ''ha segnalato l''intenzione di voler svoltare a sinistra''.', 'Lui a sinistra per svoltare? Tu lo passi a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23485, 'Anche in questo caso, se un veicolo su una strada a senso unico si sposta a sinistra per accostare (cioè fermarsi), libera la parte destra della strada. Quindi, tu puoi sorpassarlo a destra.', 'Le condizioni sono ''su strada a senso unico'' e ''accostare a sinistra''. ''deve essere eseguita a destra'' indica l''obbligo in questa situazione specifica.', 'Accosta a sinistra? Passa a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23486, 'Se sei su una strada dove tutte le macchine vanno nella stessa direzione (senso unico) e c''è abbastanza spazio, puoi sorpassare il tram sia a destra che a sinistra.', 'La parte importante è ''su ambo i lati''. Le condizioni sono ''strada è a senso unico'' e ''la larghezza della carreggiata lo consente''.', 'Senso unico, spazio c''è? Tram lo passi dove vuoi!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23487, 'Il salvagente è una specie di isola pedonale dove i passeggeri aspettano o scendono dal tram. Se c''è il salvagente, significa che i passeggeri sono protetti e tu puoi sorpassare il tram a destra, facendo attenzione.', 'La condizione fondamentale è ''se esiste il salvagente''. ''può effettuarsi a destra'' è la conseguenza.', 'Salvagente c''è? Passa a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23488, 'Se il tram è fermo e non c''è il salvagente, i passeggeri scendono direttamente sulla strada. In questo caso, è pericoloso sorpassare a destra perché potresti investire qualcuno. Devi aspettare che il tram riparta.', 'La negazione è ''non può effettuarsi a destra''. La condizione è ''se manca il salvagente''.', 'Salvagente non c''è? Non passare a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23489, 'Questa affermazione è falsa per via della parola ''sempre''. Come abbiamo visto, puoi sorpassare a destra solo se c''è il salvagente. Se non c''è, non puoi. Quindi non è ''sempre'' possibile.', 'La parola trappola è ''sempre''. Attenzione agli avverbi di tempo assoluti che spesso rendono le affermazioni false.', '''Sempre'' è quasi sempre FALSO! Controlla il salvagente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23490, 'Questa affermazione è falsa. Abbiamo appena visto diversi casi in cui il sorpasso a destra è permesso, ad esempio quando il veicolo davanti svolta a sinistra, o quando c''è il salvagente per il tram. Non è ''sempre'' vietato.', 'La parola trappola è ''sempre''. Non è mai ''sempre'' vietato, ci sono eccezioni.', '''Sempre vietato'' è quasi sempre FALSO! Ci sono eccezioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23491, 'Sulle autostrade, il sorpasso si fa sempre a sinistra. L''unica eccezione è se la colonna di veicoli nella corsia di destra va più veloce di quella di sinistra, ma non è un vero e proprio sorpasso, è un ''superamento''. Il sorpasso vero e proprio è a sinistra.', 'Le parole chiave sono ''di norma'' e ''a destra sulle autostrade''. Il sorpasso ''di norma'' è a sinistra.', 'Autostrada, sorpasso a sinistra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23492, 'Questa affermazione è falsa. Il sorpasso si fa ''di norma'' a sinistra, non solo in quel caso specifico. Se un veicolo sta svoltando a destra, tu lo sorpassi a sinistra, ma puoi sorpassare a sinistra anche in molte altre situazioni (ad esempio, un veicolo che va dritto).', 'La parola trappola è ''soltanto''. Limita troppo le possibilità, rendendo l''affermazione falsa.', '''Soltanto'' è quasi sempre FALSO! Il sorpasso a sinistra è la regola generale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23493, 'Questa affermazione è falsa. Come abbiamo visto nella domanda 23483, in strade con almeno due corsie per senso di marcia (come le autostrade), se non crei intralcio, puoi fare più sorpassi di seguito senza rientrare nella corsia più a destra.', 'Le parole chiave sono ''vietato'' e ''senza prima essersi riportati a destra''. Non è sempre vietato.', 'Più corsie, più sorpassi a fila se non intralci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23494, 'Su strade con due corsie e doppio senso di marcia, le curve riducono la visibilità. Non puoi vedere chi arriva dall''altra parte, quindi sorpassare è molto pericoloso e per questo è vietato.', 'La frase chiave è ''a due corsie a doppio senso di marcia''. Questa condizione rende il sorpasso pericoloso in curva.', 'Curva + Doppio Senso = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23495, 'Come per le curve, anche i dossi (le salite e discese ripide) su strade a doppio senso di marcia limitano la visibilità. Non puoi vedere cosa c''è dopo il dosso, quindi sorpassare è vietato per evitare incidenti.', 'Anche qui, ''a due corsie a doppio senso di marcia'' è la condizione che rende il dosso pericoloso per il sorpasso.', 'Dosso + Doppio Senso = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23496, 'Se la visibilità è scarsa (per nebbia, pioggia forte, buio), non puoi valutare bene la distanza e la velocità degli altri veicoli. Sorpassare in queste condizioni è estremamente pericoloso e quindi vietato.', '''Scarsa visibilità'' è la condizione che rende il sorpasso sempre vietato.', 'Non vedi bene? Non sorpassare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23497, 'Se la strada ha due carreggiate separate, significa che non c''è traffico che viene in senso opposto sulla tua carreggiata. Se poi ci sono almeno due corsie per il tuo senso di marcia, puoi sorpassare in curva usando la corsia di sinistra in sicurezza.', 'Le condizioni ''due carreggiate separate'' e ''almeno due corsie per ogni senso di marcia'' sono fondamentali. Senza traffico opposto e con più corsie, il sorpasso è sicuro.', 'Carreggiate separate + più corsie = Curva OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23498, 'La stessa logica delle curve vale per i dossi. Se la strada ha carreggiate separate e più corsie per il tuo senso di marcia, non c''è rischio di scontrarsi con veicoli che vengono dall''altra parte, quindi puoi sorpassare in sicurezza.', 'Anche qui, ''due carreggiate separate'' e ''due corsie per senso di marcia'' sono le condizioni che permettono il sorpasso sul dosso.', 'Carreggiate separate + più corsie = Dosso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23499, 'Se un veicolo sta già sorpassando e tu vuoi sorpassare anche lui, ma per farlo devi andare nella corsia opposta (dove arrivano le macchine), è vietato. È troppo pericoloso perché rimarresti troppo a lungo nella corsia sbagliata.', 'La parte cruciale è ''se ciò impone di spostarsi sul lato riservato all''altro senso di marcia''. Se non devi invadere la corsia opposta (es. in autostrada), la situazione cambia.', 'Doppio sorpasso + corsia opposta = NO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23500, 'Ai passaggi a livello c''è il rischio che arrivi un treno. Se ci sono veicoli fermi e tu devi andare nella corsia opposta per sorpassarli, è vietato perché è estremamente pericoloso.', 'La condizione ''se bisogna impegnare la semicarreggiata opposta'' è quella che rende il sorpasso vietato in questo contesto.', 'Passaggio a livello + corsia opposta = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23501, 'Anche se i veicoli si muovono lentamente, il rischio al passaggio a livello rimane alto. Se per sorpassarli devi invadere la corsia opposta, è vietato per la tua sicurezza e quella degli altri.', 'La combinazione di ''lento movimento ai passaggi a livello'' e ''necessario spostarsi sul lato riservato all''altro senso di marcia'' rende il sorpasso vietato.', 'Passaggio a livello + corsia opposta = NO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23502, 'I veicoli fermi al semaforo aspettano il loro turno. Se per sorpassarli devi andare nella corsia opposta, è vietato. Potresti scontrarti con chi arriva da altre direzioni o con chi riparte al verde.', 'La condizione ''necessario spostarsi sul lato riservato all''altro senso di marcia'' è il motivo del divieto.', 'Semaforo + corsia opposta = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23503, 'Nel traffico intenso, i veicoli si muovono in modo imprevedibile. Se per sorpassare devi invadere la corsia opposta, è molto pericoloso e vietato, perché potresti causare un incidente o bloccare il traffico.', 'La ''congestione della circolazione'' unita alla necessità di ''spostarsi sul lato riservato all''altro senso di marcia'' rende il sorpasso vietato.', 'Traffico + corsia opposta = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23504, 'Normalmente agli incroci non si sorpassa. Ma se l''incrocio è regolato da semafori, il traffico è controllato e i movimenti sono previsti. In questo caso, il sorpasso è consentito se le condizioni lo permettono.', 'La condizione ''se regolate dai semafori'' è l''eccezione che permette il sorpasso all''incrocio.', 'Incrocio + Semaforo = Sorpasso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23505, 'Questa è una delle poche situazioni in cui è consentito sorpassare a destra. Se un veicolo davanti a te sta per girare a sinistra e ha già iniziato la manovra, si sposta a sinistra, lasciando spazio a destra per il sorpasso.', 'Le condizioni ''a destra'', ''veicolo da sorpassare ha indicato di voler svoltare a sinistra'' e ''ha iniziato la manovra'' sono tutte necessarie.', 'Svolta a sinistra + Sorpasso a destra = OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23506, 'Se l''incrocio è su una strada a precedenza (hai la precedenza), ha due carreggiate separate (niente traffico opposto) e le corsie sono ben delimitate, allora è sicuro sorpassare.', 'Ci sono molte condizioni qui: ''strada è a precedenza'', ''due carreggiate separate'' e ''corsie siano delimitate''. Tutte insieme rendono il sorpasso consentito.', 'Incrocio + Precedenza + Carreggiate separate + Corsie = Sorpasso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23507, 'Le biciclette (veicoli a due ruote non a motore) sono più piccole e lente. Se puoi sorpassarle all''incrocio senza invadere la corsia opposta, il rischio è minimo e quindi è consentito.', 'Le condizioni ''veicolo a due ruote non a motore'' e ''non si invade il lato riservato al senso opposto'' sono cruciali.', 'Incrocio + Bici + NO corsia opposta = OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23508, 'Se un agente del traffico (vigile) regola l''incrocio, è lui che decide chi passa e quando. Le sue indicazioni rendono il traffico sicuro, quindi il sorpasso è consentito se lui lo permette.', '''Regolate da agenti del traffico'' è la condizione che permette il sorpasso.', 'Incrocio + Vigile = Sorpasso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23509, 'I passaggi a livello senza barriere sono molto pericolosi. Ma se ci sono semafori che regolano il traffico, questi indicano quando è sicuro passare. Quindi, in questo caso, il sorpasso è consentito.', 'La condizione ''se la circolazione è regolata da semafori'' è l''eccezione che permette il sorpasso.', 'Passaggio a livello senza barriere + Semaforo = Sorpasso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23510, 'Se un veicolo si ferma per far passare i pedoni, significa che ci sono persone sulla strada o che stanno per attraversare. Sorpassare quel veicolo metterebbe i pedoni in grave pericolo, quindi è assolutamente vietato.', 'La ragione ''per consentire l''attraversamento di pedoni'' è la chiave del divieto.', 'Pedoni + Veicolo fermo = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23511, 'Vale lo stesso principio della domanda precedente. Se un veicolo rallenta per i pedoni, sta agendo per la loro sicurezza. Sorpassarlo sarebbe pericoloso per i pedoni, quindi è vietato.', 'La condizione ''rallentato in corrispondenza di un passaggio pedonale per consentire l''attraversamento dei pedoni'' è il motivo del divieto.', 'Pedoni + Veicolo rallentato = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23512, 'Le corsie di accelerazione servono per entrare in una strada principale, quelle di decelerazione per uscire. Sono luoghi dove le velocità cambiano rapidamente e in modo imprevedibile. Sorpassare lì è pericoloso e vietato.', '''Corsie di accelerazione o di decelerazione'' sono corsie speciali con divieto di sorpasso.', 'Corsie speciali (accel/decel) = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23513, 'Le strisce continue (bianche, singole o doppie) sulla strada indicano che non puoi superarle. Sono lì per segnalare punti pericolosi dove non si deve invadere la corsia opposta, quindi il sorpasso è vietato.', '''Striscia longitudinale bianca continua semplice o doppia'' è un segnale chiaro di divieto.', 'Linea continua = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23514, 'Se il veicolo che stai cercando di sorpassare accelera, la differenza di velocità tra voi diminuisce. Questo significa che impiegherai più tempo e quindi più spazio per completare il sorpasso.', '''Aumenta'' e ''veicolo da sorpassare accelera'' sono le parole chiave. L''accelerazione dell''altro rende il sorpasso più lungo.', 'L''altro accelera? Più spazio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23515, 'Un veicolo più lungo richiede più tempo per essere superato completamente. Devi stare affianco a lui per una distanza maggiore, quindi ti serve più spazio sulla strada.', '''Maggiore lunghezza del veicolo da sorpassare'' è la causa dell''aumento dello spazio.', 'Veicolo lungo da superare? Più spazio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23516, 'Se il tuo veicolo è più lungo, hai bisogno di più spazio per uscire dalla corsia, superare e poi rientrare in sicurezza senza tagliare la strada al veicolo sorpassato.', '''Maggiore lunghezza del veicolo che sorpassa'' è la causa dell''aumento dello spazio.', 'Il tuo veicolo è lungo? Più spazio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23517, 'Se la tua velocità è solo leggermente superiore a quella del veicolo che vuoi sorpassare, ci vorrà molto più tempo per completare la manovra. Questo significa che avrai bisogno di una distanza maggiore.', '''Poca differenza di velocità'' è la condizione che richiede ''maggiore'' spazio.', 'Poca differenza di velocità? Più spazio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23518, 'La distanza di sicurezza è fondamentale per la tua sicurezza e quella degli altri. Devi mantenerla sempre, anche quando ti prepari a sorpassare, per poter frenare in tempo se il veicolo davanti frena improvvisamente.', '''Anche quando si inizia la manovra di sorpasso'' sottolinea che la distanza di sicurezza è sempre obbligatoria.', 'Distanza di sicurezza = Sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23519, 'Sul tratto in discesa di un dosso, la visibilità migliora molto rispetto alla cima o alla salita. Se vedi bene e la strada è libera, puoi sorpassare. Il divieto vale per la salita e la cima del dosso.', '''Tratto discendente'' è la parola chiave che rende il sorpasso consentito.', 'Dosso in discesa = OK (se vedi bene).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23520, 'Prima di sorpassare, devi sempre controllare che non ci siano cartelli stradali o segnaletica orizzontale (come le linee continue) che vietano la manovra. È una tua responsabilità.', '''Obbligatorio accertarsi'' evidenzia la responsabilità del conducente.', 'Prima di sorpassare, controlla i divieti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23521, 'Il sorpasso è pericoloso perché potresti non essere l''unico a voler sorpassare. Altri veicoli, davanti o dietro di te, potrebbero iniziare la stessa manovra contemporaneamente, causando un incidente.', 'La frase ''possibilità di urtare altri veicoli che... intendano compiere la stessa manovra'' descrive il rischio principale.', 'Sorpasso = Attenzione agli altri che sorpassano!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23522, 'Se un veicolo si ferma per far passare i pedoni, anche se non c''è un attraversamento pedonale segnalato, devi fermarti anche tu. Sorpassarlo metterebbe in pericolo i pedoni, quindi è vietato.', 'La parte ''anche fuori dagli attraversamenti pedonali'' è importante: la sicurezza dei pedoni viene prima di tutto.', 'Pedoni = Stop, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23523, 'Quando rientri nella tua corsia dopo un sorpasso, devi farlo in modo sicuro. Se rientri troppo presto o troppo bruscamente, costringi il veicolo che hai appena superato a frenare, creando una situazione pericolosa.', '''Costringe i veicoli sorpassati a frenare bruscamente'' è la conseguenza pericolosa da evitare.', 'Rientro = Non far frenare nessuno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23524, 'Per rientrare in sicurezza, devi essere sicuro di avere abbastanza spazio. Controlla negli specchietti retrovisori che il veicolo che hai sorpassato sia completamente visibile prima di spostarti a destra.', '''Controllare la posizione del veicolo sorpassato attraverso gli specchietti retrovisori'' è l''azione di sicurezza fondamentale.', 'Rientro = Specchietti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23525, 'Falso. Il sorpasso è sempre vietato in caso di scarsa visibilità. Lampeggiare con i fari non rende una situazione pericolosa sicura. La visibilità è la condizione fondamentale per un sorpasso sicuro.', 'La parola ''consentito'' in caso di ''scarsa visibilità'' è la trappola. La scarsa visibilità è un divieto assoluto.', 'Scarsa visibilità = NO Sorpasso, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23526, 'Falso. Se la strada ha due carreggiate separate, non c''è traffico in senso opposto sulla tua carreggiata. Questo elimina il pericolo principale delle curve, quindi il sorpasso è consentito (se ci sono abbastanza corsie).', 'La frase ''anche se la strada è a due carreggiate separate'' è la chiave. Questa condizione permette il sorpasso, rendendo la frase ''vietato'' falsa.', 'Carreggiate separate = Curva OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23527, 'Falso. Se la strada ha almeno due corsie per il tuo senso di marcia, puoi sorpassare in curva usando la corsia di sinistra senza invadere la corsia opposta. Quindi non è vietato.', 'La frase ''anche se la strada è ad almeno due corsie per senso di marcia'' è la chiave. Questa condizione permette il sorpasso, rendendo la frase ''vietato'' falsa.', 'Più corsie per senso = Curva OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23528, 'Falso. I passaggi a livello senza barriere sono molto pericolosi. Anche se il treno sembra lontano, non puoi mai essere sicuro. Il sorpasso è vietato in queste situazioni, a meno che non ci siano semafori che regolano il traffico.', 'La frase ''se il treno è distante'' è una condizione soggettiva e pericolosa. Il sorpasso è vietato per principio di sicurezza.', 'Passaggio a livello = Massima prudenza, NO sorpasso (salvo semaforo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23529, 'Falso. Vale lo stesso principio della domanda precedente. La vicinanza di un passaggio a livello senza barriere rende il sorpasso estremamente rischioso, anche se i veicoli si muovono lentamente e il treno sembra lontano.', 'Anche qui, ''se il treno è distante'' è una condizione insufficiente per permettere il sorpasso in un luogo così pericoloso.', 'Passaggio a livello = Massima prudenza, NO sorpasso (salvo semaforo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23530, 'Falso. Il sorpasso agli incroci è generalmente vietato per la scarsa visibilità e i possibili conflitti di traffico. La condizione ''purché non provenga nessuno dalla destra'' non è sufficiente a renderlo sicuro o legale. Ci sono eccezioni specifiche, ma questa non è una di quelle.', 'La condizione ''purché non provenga nessuno dalla destra'' è una trappola, non è una condizione legale per il sorpasso all''incrocio.', 'Incrocio = NO Sorpasso (salvo eccezioni specifiche).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23531, 'Falso. Le corsie di accelerazione sono fatte per aumentare la velocità e immettersi nel flusso del traffico, non per sorpassare. È vietato sorpassare lì, anche se lo fai con attenzione.', 'La parola ''consentito'' è falsa. ''Purché la manovra venga effettuata con attenzione'' è un tentativo di ingannare, ma il divieto rimane.', 'Corsie di accelerazione = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23532, 'Falso. Anche se sorpassare un veicolo a due ruote può sembrare più facile, tutte le regole generali sul sorpasso (visibilità, segnaletica, incroci, ecc.) si applicano anche a loro. Non è ''sempre'' consentito.', 'La parola ''sempre'' è una trappola. Le regole hanno quasi sempre delle eccezioni o delle condizioni.', '''Sempre'' = Attenzione, spesso è FALSO!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23533, 'Falso. Nelle strade a senso unico non c''è traffico in senso opposto, il che rende il sorpasso generalmente più sicuro e quindi consentito, a meno di altri divieti specifici (es. linea continua).', 'La parola ''vietato'' è falsa. Le strade a senso unico facilitano il sorpasso.', 'Senso unico = Sorpasso più facile (non vietato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23534, 'Falso. Puoi sorpassare i veicoli della polizia come qualsiasi altro veicolo, a meno che non siano in servizio di emergenza (con sirene e luci blu accese).', 'La parola ''vietato'' è falsa. Non c''è un divieto specifico per i veicoli della polizia in condizioni normali.', 'Polizia = Si sorpassa (se non in emergenza).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23535, 'Falso. In autostrada si sorpassa normalmente a sinistra. Il sorpasso a destra è consentito solo in casi molto specifici, ad esempio se il veicolo davanti sta svoltando a sinistra o in caso di traffico intenso con corsie parallele. Non è una scelta ''indifferente''.', 'La parola ''indifferentemente'' è la trappola. Il sorpasso a destra è un''eccezione, non la norma.', 'Autostrada = Sorpasso a sinistra (di norma).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23536, 'Falso. La regola generale del sorpasso a sinistra vale per tutti i veicoli, inclusi i motocicli. Il sorpasso a destra è permesso solo in situazioni molto specifiche, non come opzione generale.', 'La frase ''sia a destra che a sinistra'' è la trappola. Non è una libertà generale.', 'Sorpasso = A sinistra (salvo eccezioni).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23537, 'Falso. Se il veicolo che stai sorpassando rallenta, la differenza di velocità tra voi aumenta. Questo ti permette di completare la manovra più velocemente e quindi hai bisogno di *meno* spazio, non di più.', 'La parola ''aumenta'' è falsa. Se l''altro rallenta, lo spazio necessario diminuisce.', 'L''altro rallenta? Meno spazio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23538, 'Falso. Lo spazio necessario per il sorpasso dipende molto dalla lunghezza sia del veicolo che sorpassa sia di quello sorpassato. Veicoli più lunghi richiedono più spazio.', 'La parola ''indipendente'' è falsa. La lunghezza dei veicoli è un fattore importante.', 'Lunghezza veicoli = Più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23539, 'Falso. Non è vietato sorpassare un autobus fermo per i passeggeri, ma devi farlo con estrema cautela. Devi rallentare e prepararti a fermarti se i passeggeri attraversano la strada. Il divieto assoluto non esiste.', 'La parola ''vietato'' è falsa. È consentito con cautela, non vietato.', 'Autobus fermo = Cautela, non vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23540, 'Falso. Nelle strade a senso unico non c''è traffico in senso opposto. Questo elimina il pericolo principale delle curve e dei dossi, quindi il sorpasso è consentito (se ci sono abbastanza corsie e visibilità).', 'La frase ''strade a senso unico'' è la chiave. In questo caso, il sorpasso su curve e dossi non è vietato.', 'Senso unico = Curva/Dosso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23541, 'Falso. La linea longitudinale tratteggiata (discontinua) indica proprio che è consentito superarla per effettuare un sorpasso, a condizione che sia sicuro. È la linea continua che vieta il sorpasso.', 'La parola ''vietato'' è falsa. La ''linea tratteggiata'' permette il sorpasso.', 'Linea tratteggiata = Sorpasso OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23542, 'Falso. Il sorpasso a destra è generalmente vietato, indipendentemente dal tipo di veicolo o dallo spazio disponibile. È consentito solo in casi molto specifici (es. veicolo che svolta a sinistra, tram). ''Spazio sufficiente'' non è una condizione valida per sorpassare a destra.', 'La frase ''a destra'' e la condizione ''se vi è spazio sufficiente'' sono la trappola. Lo spazio non rende legale un sorpasso a destra non previsto dalla legge.', 'Sorpasso a destra = Solo in casi specifici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23543, 'Falso. Le corsie riservate sono dedicate a categorie specifiche di veicoli (es. autobus, taxi) o a scopi particolari. Nessun veicolo, inclusi i motociclisti, può usarle per sorpassare nel traffico intenso, a meno che non siano autorizzati a circolare in quella corsia.', 'La parola ''consentito'' è falsa. Le ''corsie riservate'' sono off-limits per il sorpasso generico.', 'Corsie riservate = NO Sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23544, 'Sì, è permesso usare i proiettori abbaglianti per un breve lampeggio per avvisare chi ti precede che stai per iniziare la manovra di sorpasso. È un modo per attirare l''attenzione e segnalare la tua intenzione.', 'La parola ''consentito'' significa che è permesso. ''Segnalare la manovra'' si riferisce all''atto di avvisare gli altri conducenti.', 'Lampeggio abbaglianti = Segnale di sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23545, 'Quando sorpassi, devi scegliere una velocità che ti permetta di superare il veicolo in modo rapido e sicuro, ma anche di non essere troppo lento rispetto a chi sorpassi. Devi adattare la tua velocità per completare la manovra senza pericoli.', 'L''espressione ''regolare la velocità in relazione a'' significa che devi adattare la tua velocità a quella del veicolo che stai per superare.', 'Velocità sorpasso = Adatta e sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23546, 'Assolutamente no! I limiti di velocità devono essere sempre rispettati, anche quando si sorpassa, specialmente nei centri urbani dove ci sono più pericoli (pedoni, incroci, ecc.). Superare i limiti è sempre vietato e pericoloso.', 'La frase ''si possono momentaneamente superare i limiti di velocità'' è la trappola. I limiti di velocità non si possono mai superare, nemmeno per un momento.', 'Limiti velocità = Sempre validi, mai superare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23547, 'Quando sorpassi, devi spostarti a sinistra per superare il veicolo che ti precede. Mantenere strettamente la destra è la regola quando non stai sorpassando o quando devi facilitare il sorpasso agli altri.', 'L''espressione ''mantenere strettamente la destra'' è l''opposto di ciò che si fa durante un sorpasso, che richiede di spostarsi a sinistra.', 'Sorpasso = Spostati a sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23548, 'Per sorpassare in sicurezza e il più velocemente possibile, devi accelerare per superare il veicolo e rientrare nella tua corsia. Non accelerare renderebbe la manovra troppo lunga e quindi più pericolosa.', 'La negazione ''non bisogna accelerare'' rende la frase falsa. È fondamentale accelerare durante il sorpasso.', 'Sorpasso = Accelerare per sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23549, 'Dopo il sorpasso devi rientrare a destra, ma non ''immediatamente'' e soprattutto non ''rallentando''. Devi rientrare solo quando hai superato completamente il veicolo e lo vedi nello specchietto retrovisore, mantenendo una velocità adeguata. Rallentare sarebbe molto pericoloso per chi ti segue.', 'Le parole ''immediatamente'' e ''rallentando'' sono le trappole. Il rientro deve essere graduale e sicuro, senza rallentare.', 'Rientro = Sicuro, non subito, non rallentando.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23550, 'Non è vietato sorpassare gli autobus di linea in generale. Il sorpasso è vietato solo se l''autobus è fermo per far salire o scendere passeggeri e ci sono pedoni che attraversano o potrebbero attraversare. Se l''autobus è in movimento o fermo senza passeggeri, puoi sorpassarlo se le condizioni lo permettono.', 'La generalizzazione ''È vietato il sorpasso'' è la trappola. Non è sempre vietato, dipende dalla situazione specifica dell''autobus.', 'Autobus = Sorpassabile (se non fermo passeggeri).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23551, 'Se il veicolo davanti mette la freccia destra, probabilmente sta per svoltare a destra o accostare. Questo di solito non vieta il sorpasso, anzi, in alcuni casi potrebbe facilitarlo se il veicolo si sposta a destra. Devi comunque fare attenzione.', 'La frase ''È vietato il sorpasso'' è la trappola. La freccia destra non è un segnale di divieto di sorpasso.', 'Freccia destra = Non vieta sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23552, 'Non è vietato sorpassare solo perché nevica. Il sorpasso è vietato in condizioni di scarsa visibilità o aderenza (strada scivolosa), che possono essere causate dalla neve, ma la neve da sola non è un divieto assoluto. Devi valutare attentamente le condizioni della strada e la visibilità.', 'La generalizzazione ''È vietato il sorpasso se nevica'' è la trappola. La neve richiede prudenza, ma non è un divieto automatico.', 'Neve = Prudenza, non divieto assoluto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23553, 'I passi carrabili sono gli accessi a proprietà private (come garage o cortili). Non esiste un divieto specifico di sorpasso in corrispondenza dei passi carrabili. Devi solo fare attenzione a chi entra o esce, ma puoi sorpassare se le condizioni lo permettono.', 'La frase ''È vietato il sorpasso'' è la trappola. Non c''è una regola che vieti il sorpasso ai passi carrabili.', 'Passi carrabili = Attenzione, non divieto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23554, 'Non esiste un divieto di sorpasso specifico in prossimità degli ospedali. Devi guidare con prudenza, rispettare i limiti di velocità e fare attenzione alle ambulanze o ai pedoni, ma non è vietato sorpassare se le condizioni lo permettono e la manovra è sicura.', 'La frase ''È vietato il sorpasso'' è la trappola. La vicinanza a un ospedale richiede prudenza, non un divieto di sorpasso.', 'Ospedale = Prudenza, non divieto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23555, 'Non è vietato sorpassare in prossimità delle stazioni di servizio. Devi fare attenzione ai veicoli che entrano ed escono dalla stazione, ma non c''è un divieto assoluto di sorpasso in queste aree. La prudenza è sempre d''obbligo.', 'La frase ''È vietato il sorpasso'' è la trappola. Le stazioni di servizio non sono zone di divieto di sorpasso.', 'Stazione servizio = Attenzione, non divieto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23556, 'Su una strada a senso unico, tutti i veicoli vanno nella stessa direzione. Questo significa che non c''è traffico che viene in senso contrario. Quindi, anche se c''è un dosso (una salita che limita la visibilità), puoi sorpassare perché non rischi di scontrarti con veicoli che arrivano dall''altra parte.', 'La frase chiave è ''strade a senso unico''. Se la strada è a senso unico, non c''è pericolo di traffico in arrivo, quindi il sorpasso è permesso anche in prossimità di un dosso.', 'Senso unico = via libera al dosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23557, 'Simile alla precedente. Una carreggiata a senso unico significa che tutti i veicoli su quella parte di strada vanno nella stessa direzione. Non c''è traffico che viene contro di te, quindi il sorpasso è sicuro anche vicino a un dosso.', 'La frase chiave è ''carreggiate a senso unico''. La parola ''carreggiata'' si riferisce alla parte della strada destinata ai veicoli. Il concetto è lo stesso di ''strada a senso unico''.', 'Carreggiata a senso unico = sorpasso ok al dosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23558, 'Se una strada ha due corsie per ogni senso di marcia, significa che ci sono almeno quattro corsie in totale (due per andare e due per tornare). In questo caso, puoi sorpassare usando la corsia di sinistra del tuo senso di marcia, senza invadere la parte di strada dove arrivano i veicoli dall''altra direzione. Quindi, anche con un dosso, il sorpasso è sicuro.', 'La frase chiave è ''due corsie per senso di marcia''. Questo indica una strada ampia e divisa, dove non si invade la corsia opposta.', 'Due corsie per senso = sorpasso sicuro al dosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23559, 'Le strade a due carreggiate separate sono come le autostrade o le superstrade, dove c''è una barriera (come uno spartitraffico) che divide il traffico che va in una direzione da quello che va nell''altra. Non c''è rischio di scontrarsi con veicoli che arrivano in senso opposto, quindi puoi sorpassare anche vicino a un dosso.', 'La parola chiave è ''separate''. Significa che i due sensi di marcia sono fisicamente divisi, eliminando il rischio di collisioni frontali.', 'Carreggiate separate = dosso non blocca il sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23560, 'Le ambulanze in emergenza vanno molto veloci e hanno la precedenza. Se ti ''accodi'' (cioè le segui da vicino) per approfittare del loro passaggio e superare il traffico, è molto pericoloso e vietato. Potresti ostacolare l''ambulanza o causare un incidente.', 'Le parole chiave sono ''accodandosi'' e ''in servizio di emergenza''. Non devi mai usare un veicolo di emergenza come ''apripista'' per i tuoi sorpassi.', 'Ambulanza in emergenza = non seguirla per sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23562, 'Su una strada a doppio senso con un dosso, la visibilità è limitata. Non puoi vedere chi arriva dall''altra parte. Anche se un veicolo a trazione animale è lento, il sorpasso richiede di invadere la corsia opposta, il che è pericoloso in prossimità di un dosso. La regola generale è che il sorpasso è vietato in prossimità dei dossi se si deve invadere la corsia opposta.', 'Le parole chiave sono ''doppio senso'' e ''in prossimità di un dosso''. Queste due condizioni insieme rendono il sorpasso pericoloso e vietato se si invade la corsia opposta. Il tipo di veicolo (a trazione animale) non cambia la regola di sicurezza.', 'Dosso + doppio senso = no sorpasso (anche se lento).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23563, '''Sorpassare nella scia'' significa seguire molto da vicino il veicolo che ti precede e superarlo appena lui si sposta. Questo è pericoloso in generale, ma ancora di più in prossimità di un dosso su una strada a doppio senso. Non hai visibilità e non puoi reagire in tempo se c''è un pericolo. Il sorpasso è vietato in queste condizioni.', 'La frase chiave è ''nella scia del veicolo che precede''. Questa è una manovra pericolosa e non è mai una buona idea, specialmente dove la visibilità è ridotta e il traffico è a doppio senso.', 'Dosso + doppio senso = no sorpasso, nemmeno ''a scia''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23564, 'In prossimità di un dosso, la visibilità è ridotta. Invadere la semicarreggiata opposta è pericolosissimo perché non puoi vedere se sta arrivando un altro veicolo. Non importa se stai sorpassando un autobus fermo; la regola di sicurezza sul dosso prevale.', 'Le frasi chiave sono ''invadere l''opposta semicarreggiata'' e ''in prossimità di un dosso''. Queste due condizioni rendono il sorpasso vietato.', 'Dosso + corsia opposta = mai sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23565, 'Questa domanda dice ''Non si può sorpassare'', ma la risposta corretta è FALSO, quindi *si può* sorpassare. Se la carreggiata è a senso unico e ha due corsie, significa che tutti i veicoli vanno nella stessa direzione. Puoi usare la corsia di sinistra per sorpassare senza invadere la corsia opposta. Quindi, il sorpasso è consentito anche in prossimità di un dosso.', 'Attenzione alla negazione ''Non si può''. La chiave è ''senso unico a due corsie'', che permette il sorpasso anche al dosso.', 'Senso unico a due corsie = sorpasso ok al dosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23566, 'Questa domanda dice ''Non si può sorpassare'', ma la risposta corretta è FALSO, quindi *si può* sorpassare. Se un veicolo segnala che vuole accostarsi a destra, significa che sta per rallentare o fermarsi e liberare la corsia. In questo caso, puoi sorpassarlo a sinistra, se le condizioni lo permettono e la manovra è sicura.', 'Attenzione alla negazione ''Non si può''. Se un veicolo ''segnala l''intenzione di accostarsi al margine destro'', sta liberando la strada a sinistra, rendendo il sorpasso possibile.', 'Veicolo a destra = sorpasso a sinistra possibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23567, 'Questa domanda dice ''Non si può sorpassare'', ma la risposta corretta è FALSO, quindi *si può* sorpassare. Non c''è una regola specifica che vieti il sorpasso all''uscita di un parcheggio pubblico. Devi sempre valutare la sicurezza della manovra, ma non è un divieto assoluto come, ad esempio, in prossimità di un incrocio o di un dosso su strada a doppio senso.', 'Attenzione alla negazione ''Non si può''. ''Uscita di un pubblico parcheggio'' non è un luogo di divieto assoluto per il sorpasso.', 'Uscita parcheggio = sorpasso possibile con cautela.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23568, 'Questa domanda dice ''E'' vietato'', ma la risposta corretta è FALSO, quindi *non è vietato*. Se alla sinistra del tuo veicolo c''è una linea discontinua affiancata da una continua, significa che tu (che sei dalla parte della discontinua) puoi sorpassare, mentre chi viene dal senso opposto (dalla parte della continua) non può. Quindi, il sorpasso è consentito per te.', 'Attenzione alla negazione implicita ''E'' vietato''. La chiave è ''linea bianca discontinua affiancata da una continua''. Se la discontinua è dalla tua parte, puoi sorpassare.', 'Discontinua dalla tua parte = puoi sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23569, 'Questa domanda dice ''Non si può sorpassare'', ma la risposta corretta è FALSO, quindi *si può* sorpassare. Se il tram marcia al centro della carreggiata e non c''è spazio a sinistra, o se la strada è a senso unico, è consentito sorpassare il tram sulla destra, purché ci sia spazio sufficiente e sia sicuro.', 'Attenzione alla negazione ''Non si può''. Se il ''tram marcia al centro della carreggiata'', in alcuni casi (ad esempio, se non c''è spazio a sinistra o su strada a senso unico), il sorpasso a destra è permesso.', 'Tram al centro = sorpasso a destra possibile (se sicuro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23570, 'Quando sorpassi un altro veicolo, devi fare attenzione a non andare troppo vicino al veicolo che hai appena superato, né a rientrare troppo presto nella tua corsia. È importante lasciare sempre uno spazio di sicurezza per evitare incidenti.', 'Le parole ''stringere'' o ''tagliare la strada'' indicano azioni pericolose e scorrette che devi assolutamente evitare durante il sorpasso.', 'Sorpassa con spazio, rientra con calma.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23571, 'Il sorpasso è pericoloso perché potresti scontrarti con un altro veicolo che, nello stesso momento, vuole fare la tua stessa manovra. Per questo è fondamentale controllare bene gli specchietti prima di iniziare.', 'La frase ''manifestano l''intenzione di compiere la stessa manovra'' si riferisce a veicoli che potrebbero voler sorpassare contemporaneamente a te, creando un rischio.', 'Prima di sorpassare, guarda sempre gli specchietti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23572, 'Il sorpasso diventa pericoloso se, mentre ti avvicini al veicolo che vuoi superare, non mantieni la giusta distanza o velocità e rischi di colpirlo prima ancora di affiancarlo.', 'La parte ''in fase di avvicinamento'' sottolinea che il pericolo non è solo durante il sorpasso, ma anche prima di iniziarlo, quando ti avvicini al veicolo.', 'Distanza di sicurezza, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23573, 'Dopo aver superato un veicolo, se rientri troppo presto nella tua corsia, potresti colpire il veicolo che hai appena sorpassato. Devi rientrare solo quando lo vedi bene nello specchietto retrovisore interno.', 'La frase ''in fase di rientro in corsia'' indica un momento molto delicato della manovra, dove è facile commettere errori se non si è prudenti.', 'Rientra solo quando vedi il veicolo nello specchietto interno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23574, 'Se sorpassi su una strada a doppio senso di marcia, devi fare molta attenzione ai veicoli che arrivano dalla direzione opposta. Se non c''è abbastanza spazio o tempo, potresti scontrarti frontalmente, il che è estremamente pericoloso.', 'Le parole ''urto frontale'' e ''veicolo che provenga dal senso contrario'' evidenziano il rischio più grave e diretto nelle strade a doppio senso.', 'Su strada a doppio senso, occhio al traffico opposto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23575, 'Se la strada è stretta, c''è meno spazio per sorpassare in sicurezza. Questo aumenta il rischio di toccare il veicolo sorpassato o di finire fuori strada.', 'La ''ridotta larghezza della carreggiata'' è un fattore che limita lo spazio disponibile e rende il sorpasso più difficile e rischioso.', 'Strada stretta, sorpasso vietato o molto difficile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23576, 'Dopo aver sorpassato, devi rientrare nella tua corsia il prima possibile, ma sempre in sicurezza. Non devi rimanere nella corsia di sorpasso più del necessario, per non bloccare gli altri veicoli che potrebbero voler sorpassare.', 'La frase ''il più a lungo possibile'' è la parola trappola. Devi fare l''esatto contrario: rientrare appena possibile, non rimanere a lungo.', 'Sorpassa e rientra subito (in sicurezza).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23577, 'Non devi usare il clacson (avvisatore acustico) continuamente mentre sorpassi. Il clacson si usa solo in caso di pericolo immediato o, fuori dai centri abitati, per avvisare. Per segnalare il sorpasso si usano le frecce.', 'La parola ''continuamente'' è la trappola. Il clacson non serve per segnalare la manovra in modo prolungato.', 'Frecce per sorpassare, clacson solo per pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23578, 'Devi sorpassare velocemente per ridurre il tempo della manovra, ma non c''è una regola che dice che la tua velocità deve essere ''almeno doppia'' rispetto a quella del veicolo sorpassato. Devi superare in sicurezza e in un tempo breve, ma senza esagerare.', 'La frase ''almeno doppia'' è la trappola. Non esiste un rapporto fisso di velocità da mantenere durante il sorpasso.', 'Sorpassa rapidamente ma senza eccessi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23579, 'I delineatori di margine sono quei paletti bianchi e neri o gialli che si trovano ai bordi della strada e servono a indicare dove finisce la carreggiata. Non rendono il sorpasso pericoloso, anzi, aiutano a orientarsi.', 'I ''delineatori normali di margine'' non sono un fattore di pericolo per il sorpasso. La domanda cerca di confondere associando un elemento utile a un rischio.', 'Delineatori = bordo strada, non pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23580, 'Il sorpasso non è vietato solo perché è notte o l''illuminazione è scarsa. È vietato se le condizioni di visibilità non permettono di farlo in sicurezza. Ma non c''è un divieto generale per la notte o l''illuminazione insufficiente di per sé.', 'La frase ''vietato di notte, nei centri urbani con pubblica illuminazione insufficiente'' è una trappola. Non è un divieto automatico, ma una condizione che richiede maggiore prudenza.', 'Sorpasso: sempre con buona visibilità, non solo di giorno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23581, 'La linea tratteggiata di mezzeria significa proprio che il sorpasso è consentito, se le condizioni lo permettono e la manovra è sicura. Se il sorpasso fosse vietato, ci sarebbe una linea continua.', 'La ''linea tratteggiata di mezzeria'' è il segnale che permette il sorpasso. La trappola è confonderla con la linea continua, che invece lo vieta.', 'Linea tratteggiata = via libera (se sicuro).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23582, 'Non c''è un divieto specifico di sorpassare un autobus di linea sulle strade di montagna. Puoi sorpassarlo se ci sono le condizioni di sicurezza (spazio, visibilità, assenza di divieti specifici come curve o dossi).', 'La frase ''vietato quando sulle strade di montagna si è preceduti da un autobus di linea'' è una trappola. Non è un divieto automatico, ma una situazione che richiede maggiore attenzione.', 'Autobus in montagna: sorpassa solo se sicuro, non è vietato a priori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23583, 'Non c''è una distanza fissa di 100 metri per il rientro dal sorpasso. Devi rientrare in sicurezza, assicurandoti di non tagliare la strada al veicolo sorpassato e di vederlo bene nello specchietto retrovisore interno. La distanza di sicurezza è variabile e dipende dalla velocità.', 'La distanza ''almeno 100 m'' è una distanza specifica e non corretta. Non esiste un valore fisso per il rientro.', 'Rientra sicuro, non c''è distanza fissa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23584, 'Non devi usare il clacson (segnalare acusticamente) quando rientri dal sorpasso. Devi usare le frecce per indicare il rientro e assicurarti di farlo in sicurezza. Il clacson è per segnalare un pericolo, non una manovra di routine.', 'La frase ''segnalare acusticamente'' è la trappola. Il clacson non serve per il rientro, si usano le frecce.', 'Frecce per rientrare, non clacson.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23585, 'Il sorpasso a destra è consentito solo in casi specifici. Quando un filobus è fermo per far salire o scendere i passeggeri, puoi sorpassarlo a destra solo se c''è un ''salvagente'' (un''isola pedonale) o uno spazio apposito che ti separa dai passeggeri. Se non c''è, non puoi.', 'La frase ''anche se non esiste salvagente'' è la trappola. La presenza del salvagente è fondamentale per poter sorpassare a destra in questa situazione.', 'Filobus fermo, passeggeri: sorpasso a destra solo con salvagente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23586, 'Anche su una strada extraurbana a senso unico, la regola generale è sorpassare a sinistra. Il sorpasso a destra è permesso solo in situazioni molto particolari, ad esempio se il veicolo davanti ha segnalato l''intenzione di svoltare a sinistra. Non è consentito solo perché la strada è a senso unico.', 'La frase ''consentito quando si percorre una strada extraurbana a senso unico'' è una trappola. Non è una condizione sufficiente per sorpassare a destra.', 'Sorpasso a destra: solo in casi eccezionali, non per strada a senso unico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23587, 'Non devi preoccuparti di confrontare la potenza del tuo motore con quella del veicolo che stai per sorpassare. Devi assicurarti che il tuo veicolo abbia una potenza sufficiente per completare il sorpasso in sicurezza e rapidamente, ma non è necessario che sia ''maggiore'' di quella dell''altro veicolo.', 'La frase ''sia maggiore di quella del veicolo da sorpassare'' è la trappola. Non è un requisito. Devi avere potenza sufficiente per la manovra, non per un confronto.', 'Potenza sufficiente per te, non per confronto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23588, 'Quando un altro veicolo ti sta sorpassando, non devi aumentare la velocità per impedirgli di passare. È pericoloso e contro la legge, perché potrebbe causare un incidente.', 'La frase ''gareggiare in velocità'' significa competere, fare una gara. Non si deve mai fare una gara con chi ti sta sorpassando.', 'Non fare a gara, facilita il sorpasso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23589, 'Se qualcuno ti sta sorpassando, devi mantenere la tua velocità o, se necessario, rallentare un po'', ma mai accelerare. Accelerare rende il sorpasso più difficile e pericoloso per chi ti sta superando.', '''Non accelerare la propria andatura'' significa non aumentare la velocità. È un obbligo per la sicurezza di tutti.', 'Non accelerare, facilita il sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23590, 'Se guidi un veicolo molto lento e crei un intralcio al traffico (cioè rallenti molto gli altri), devi fermarti in un posto sicuro (come una piazzola di sosta) appena possibile per permettere agli altri veicoli di passare. Questo aiuta a mantenere il flusso del traffico e la sicurezza.', '''Veicolo molto lento'' e ''far defluire il traffico'' indicano una situazione eccezionale in cui si crea un rallentamento significativo e si deve agire per non bloccare la circolazione.', 'Se sei lento e intralci, accosta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23591, 'Per facilitare il sorpasso e lasciare spazio a chi ti supera, devi spostarti il più possibile verso il lato destro della strada, specialmente se c''è una sola corsia per il tuo senso di marcia. Questo permette al veicolo sorpassante di avere più spazio e di superarti in sicurezza.', '''Il più possibile vicino al margine destro'' significa spostarsi a destra per lasciare spazio. È un comportamento corretto e obbligatorio.', 'Stai a destra, lascia spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23592, 'È il contrario! Devi spostarti a destra per facilitare il sorpasso, non al centro. Andare al centro della carreggiata bloccherebbe il sorpasso e sarebbe molto pericoloso, impedendo agli altri di superarti.', 'La frase ''portarsi al centro della carreggiata'' è la trappola. Non si fa mai per facilitare un sorpasso; al contrario, lo si impedisce.', 'Mai al centro per il sorpasso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23593, 'Le luci di emergenza (le quattro frecce che lampeggiano insieme) si usano solo in caso di pericolo, di guasto al veicolo o di fermata di emergenza. Non si usano per segnalare che la strada è libera per un sorpasso. Questo potrebbe confondere gli altri conducenti e creare situazioni pericolose.', 'La trappola è ''per segnalare che la strada è sgombra''. Le luci di pericolo hanno un significato ben preciso e non vanno usate per dare il ''via libera'' a un sorpasso.', 'Quattro frecce = pericolo, non via libera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23594, 'Non devi *sempre* ridurre la velocità. Devi mantenere la tua andatura o, se necessario, rallentare un po'' per facilitare il sorpasso, ma non c''è un obbligo di ridurre la velocità in ogni situazione. L''importante è non accelerare e non ostacolare il sorpasso.', 'La parola ''sempre'' è la trappola. Non è un obbligo assoluto ridurre la velocità in ogni circostanza, ma piuttosto non aumentarla e facilitare il sorpasso.', 'Non ''sempre'' ridurre, ma non accelerare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23595, 'Inserire marce più basse farebbe aumentare i giri del motore e la velocità del veicolo, il che è contrario a quanto richiesto quando si viene sorpassati. Devi mantenere la tua andatura, non accelerare, per facilitare il sorpasso in sicurezza.', '''Inserire le marce più basse'' è la trappola. Questa azione serve per aumentare la potenza o rallentare con il freno motore, non per aiutare chi ti sta superando.', 'Marce basse non servono per farsi sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23596, 'Non c''è una regola che vieta *sempre* il sorpasso di un veicolo che traina un caravan in discesa. Il sorpasso è vietato in discesa solo se la visibilità è limitata (ad esempio per una curva) o se la strada è a doppio senso con una sola corsia per senso di marcia e non c''è spazio sufficiente. La presenza del caravan non lo rende ''mai'' vietato di per sé.', 'La parola ''mai'' è la trappola. Molto spesso, nei quiz, se una cosa è indicata come ''mai'' o ''sempre'', è probabile che sia falsa, perché ci sono quasi sempre delle eccezioni.', '''Mai'' è quasi sempre falso nei quiz.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23597, 'Se un''auto della Polizia non sta svolgendo un servizio di emergenza (cioè non ha sirene o luci blu accese), è considerata come qualsiasi altro veicolo. Quindi, puoi sorpassarla se le condizioni della strada lo permettono e non ci sono altri divieti.', 'La frase chiave è ''se non è in servizio di emergenza''. Questo cambia completamente la regola.', 'Polizia ''normale'' = auto ''normale''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23598, 'Quando un altro veicolo ti sta sorpassando e vedi un''auto arrivare dal senso opposto, è una buona idea ridurre un po'' la tua velocità. Questo aiuta chi ti sta sorpassando a completare la manovra più velocemente e in sicurezza, evitando un possibile scontro con il veicolo che arriva.', 'La parola ''consigliabile'' indica che non è un obbligo, ma una pratica sicura e responsabile.', 'Aiuta chi sorpassa, rallenta un po''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23599, 'Quando vieni sorpassato, specialmente se c''è un veicolo che arriva dalla direzione opposta, devi spostarti il più possibile verso il margine destro della strada. Questo crea più spazio per il veicolo che ti sta sorpassando e rende la manovra più sicura per tutti.', 'La frase ''il più vicino possibile'' sottolinea l''importanza di massimizzare lo spazio a disposizione.', 'Fai spazio a destra, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23600, 'Sì, è vero. La legge ti chiede di facilitare la manovra di sorpasso. Se non lo fai (ad esempio, acceleri o non ti sposti a destra) e succede un incidente, potresti essere considerato in parte responsabile perché non hai fatto il possibile per aiutare chi ti stava sorpassando.', 'La parte ''se non si è fatto il possibile per facilitare'' è fondamentale. Indica una responsabilità attiva.', 'Facilitare è un dovere, non un favore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23601, 'Questa affermazione è falsa. Come abbiamo visto, se un''auto della Polizia non è in servizio di emergenza (cioè non ha sirene o luci blu accese), è come un veicolo normale. Non è vietato sorpassarla e non la ostacoli se lo fai in modo corretto e sicuro.', 'Le parole ''vietato'' e ''non in servizio di emergenza'' sono in contrasto. Se non è in emergenza, non è vietato.', 'Polizia ''normale'' = sorpasso ''normale''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23602, 'Questa affermazione è falsa. Non è mai consentito sorpassare un veicolo di emergenza (come un''auto della Polizia, un''ambulanza o i Vigili del Fuoco) quando è in servizio di emergenza, cioè con sirene e luci accese. Devi sempre dargli la precedenza e facilitare il suo passaggio, non sorpassarlo, anche se ci sono molte corsie.', 'La frase ''anche se in servizio di emergenza'' è la trappola. Proprio in quel caso non si può sorpassare.', 'Emergenza = non sorpassare MAI.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23603, 'Questa affermazione è falsa. Tenere accesi i proiettori abbaglianti (luci alte) quando c''è un veicolo che arriva dal senso opposto è molto pericoloso, perché acceca il conducente dell''altro veicolo. Non è un segnale di pericolo, ma crea pericolo. Devi usare i proiettori anabbaglianti (luci basse).', 'Le parole ''proiettori abbaglianti'' e ''come segnale di pericolo'' sono la chiave. Gli abbaglianti non sono un segnale di pericolo in questo contesto, ma un rischio.', 'Abbaglianti = pericolo per gli altri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23604, 'Questa affermazione è falsa. Non hai l''obbligo di mantenere la stessa velocità. Anzi, come abbiamo visto, è consigliabile ridurre leggermente la velocità per facilitare la manovra di sorpasso e renderla più sicura, soprattutto se c''è un veicolo che arriva dal senso opposto.', 'La frase ''obbligo di mantenere la stessa velocità'' è sbagliata. Non solo non è un obbligo, ma è spesso sconsigliato.', 'Non mantenere, facilita!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23605, 'Questa affermazione è falsa. L''indicatore di direzione destro (la freccia destra) serve per segnalare che vuoi svoltare a destra o spostarti a destra. Non è un segnale generico di pericolo. Usarlo in questa situazione creerebbe confusione e non sarebbe corretto.', 'La frase ''indicatore di direzione destro, come segnale di pericolo'' è errata. La freccia ha un significato specifico.', 'Freccia destra = svolta a destra, non pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23606, 'Quando sorpassi, devi sempre guardare anche dietro, nello specchietto. Se non fai attenzione a chi ti segue, potresti non vedere un veicolo che sta già sorpassando o che arriva molto veloce, causando un pericolo. Per questo, la scarsa attenzione è una causa di incidente.', 'La frase ''scarsa attenzione'' significa poca attenzione o attenzione insufficiente. È una parola chiave che indica un comportamento sbagliato.', 'Sorpasso = Occhi ovunque (anche dietro)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23607, 'La distanza di sicurezza è fondamentale. Se non mantieni una distanza sufficiente dal veicolo che stai sorpassando o da quello che ti precede dopo il sorpasso, non avrai tempo di frenare in caso di imprevisto e potresti fare un incidente.', 'La parola ''insufficiente'' significa ''non abbastanza''. Quindi, ''insufficiente distanza di sicurezza'' vuol dire che la distanza non è adeguata per la sicurezza.', 'Distanza = Tempo per reagire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23608, 'Immagina di voler sorpassare e un''altra auto davanti a te, che non hai visto o che non ti ha visto, si sposta improvvisamente nella stessa corsia di sorpasso. Questo crea una situazione molto pericolosa e può causare un incidente.', 'La parola ''improvviso'' indica qualcosa che succede all''improvviso, senza preavviso. Un ''improvviso spostamento'' è un movimento inaspettato e pericoloso.', 'Sorpasso = Attenzione a chi ti precede!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23609, 'La corsia di sorpasso serve per sorpassare e poi tornare a destra. Se rimani ''troppo a lungo'' sulla corsia di sorpasso, impedisci agli altri veicoli più veloci di sorpassare, creando un ''intralcio'' (un ostacolo) al traffico. Questo è un comportamento scorretto e pericoloso.', 'La frase ''troppo a lungo'' indica un tempo eccessivo. La parola ''intralcio'' significa ostacolo o impedimento al normale flusso del traffico.', 'Corsia di sorpasso = Solo per sorpassare, poi a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23610, 'Accodarsi significa mettersi subito dietro un altro veicolo che sta già sorpassando. Questo è pericoloso perché riduce la tua visibilità e la distanza di sicurezza. Se il veicolo davanti frena o ha un problema, tu non hai spazio per reagire e potresti causare un incidente.', 'Il verbo ''accodarsi'' significa mettersi in coda, subito dietro un altro veicolo. È un comportamento da evitare durante il sorpasso.', 'Sorpasso = Non in fila indiana!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23611, 'Un forte vento laterale (che arriva di lato) può spingere l''auto e farla sbandare, specialmente quando si cambia corsia o si è vicini a veicoli grandi. Questo rende il sorpasso molto più rischioso e può causare la perdita di controllo del veicolo e quindi un incidente.', 'La frase ''compromette la stabilità'' significa che rende l''auto meno stabile, più difficile da controllare. Il ''vento laterale'' è un fattore esterno che può creare pericolo.', 'Vento forte = Sorpasso con cautela (o evita)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23612, 'Le piazzole di sosta sono aree dove ci si può fermare, ma non sono un punto dove il sorpasso è più pericoloso di altri. Non c''è una regola specifica che vieta o rende il sorpasso più rischioso vicino a una piazzola di sosta, a meno che non ci siano altre condizioni (come un veicolo che entra o esce). La sola vicinanza non è di per sé causa di incidente.', 'La frase ''in vicinanza di una piazzola di sosta'' non indica di per sé una condizione di pericolo per il sorpasso. Non è un punto dove il sorpasso è vietato o intrinsecamente più rischioso.', 'Piazzola = Non è un divieto di sorpasso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23613, 'Le luci anabbaglianti devono essere sempre accese in autostrada, anche di giorno. Accenderle non è una causa di incidente, anzi, aumenta la tua visibilità e quindi la sicurezza. Viaggiare con le luci anabbaglianti accese è un comportamento corretto e sicuro, non pericoloso.', 'La frase ''sempre accese'' è la condizione corretta per le luci anabbaglianti in autostrada. Non è una causa di incidente, ma una misura di sicurezza obbligatoria.', 'Anabbaglianti = Sempre accesi, sempre più sicuri!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23614, 'Se parcheggi in un''area dove c''è il parchimetro, devi pagare e poi mettere il biglietto (il tagliando) sul cruscotto, in modo che sia facile vederlo. Così dimostri di aver pagato.', 'La frase ''occorre esporre l''apposito tagliando, in modo che sia ben visibile'' è chiara e non contiene trappole. Significa semplicemente che devi mostrare il biglietto del parchimetro.', 'Parchimetro? Biglietto in vista!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23615, 'Quando parcheggi in una zona con il disco orario, devi mettere il disco sul cruscotto e indicare l''ora esatta in cui sei arrivato. Questo serve per controllare quanto tempo rimani parcheggiato.', 'Le parole ''ben visibile'' e ''orario di arrivo'' sono importanti. Devi mostrare chiaramente l''ora in cui hai iniziato la sosta.', 'Disco orario? Segna l''arrivo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23616, 'Se ti fermi solo per un attimo, giusto il tempo di far scendere o salire qualcuno dall''auto (questa si chiama ''fermata''), non devi pagare il parchimetro. Il parchimetro serve per la ''sosta'', cioè quando lasci il veicolo fermo per più tempo.', 'La trappola qui è la differenza tra ''sosta'' e ''fermata''. ''Soltanto per far salire o scendere un passeggero'' indica una fermata, che non richiede il parchimetro.', 'Fermata breve? Niente parchimetro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23617, 'Le persone con disabilità, che hanno l''apposito contrassegno, hanno un permesso speciale. Nelle aree dove il parcheggio è a tempo limitato, non devono rispettare quel limite di tempo e possono parcheggiare più a lungo.', 'La frase ''non sono obbligati a rispettare il limite di tempo'' è la chiave. È un''eccezione importante per i veicoli al servizio di persone con disabilità.', 'Disabili? Più tempo per parcheggiare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23618, 'Questa affermazione è FALSA. Con il disco orario devi sempre indicare l''ora in cui sei ARRIVATO, non l''ora in cui pensi di andare via. E devi usare il disco apposito, non un foglio di carta.', 'Le parole trappola sono ''orario di fine della sosta'' (è l''orario di inizio!) e ''oppure trascriverlo su un foglio di carta'' (devi usare il disco!).', 'Disco orario? Solo l''inizio, solo il disco!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23619, 'Questa affermazione è FALSA. Non puoi semplicemente cambiare l''orario sul disco per prolungare la sosta senza spostare l''auto. Se vuoi stare di più, devi muovere il veicolo e poi riparcheggiare, mettendo un nuovo orario.', 'La frase ''aggiornare l''orario, senza che il veicolo venga spostato'' è la trappola. Non è permesso prolungare la sosta in questo modo.', 'Disco orario? Non barare, sposta l''auto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23620, 'Questa affermazione è FALSA. Se si tratta di una ''sosta'', anche se breve, devi sempre pagare il parchimetro. La regola del non pagare vale solo per la ''fermata'', cioè quando ti fermi solo per far salire o scendere qualcuno.', 'La trappola è ''breve sosta''. Anche una sosta breve richiede il parchimetro, a meno che non sia una vera e propria ''fermata''.', 'Sosta? Paga sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23621, 'Questa affermazione è FALSA. Devi usare l''apposito disco orario, non un foglio di carta. E devi indicare l''ora e i minuti precisi di arrivo, non solo l''ora.', 'Le trappole sono ''trascrivere su un foglio di carta'' (si usa il disco!) e ''senza indicare i minuti'' (i minuti sono fondamentali!).', 'Disco orario? Usa il disco, metti ora e minuti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23622, 'Quando apri la portiera di un veicolo fermo, devi sempre guardare se arrivano altri veicoli. Questo serve per evitare incidenti e garantire la sicurezza di tutti.', 'La frase ''particolare attenzione'' non è una trappola, ma rafforza l''importanza di essere molto cauti.', 'Portiera aperta = occhi aperti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23623, 'Su una strada stretta c''è meno spazio. Per questo, prima di scendere dall''auto, è ancora più importante controllare bene che non stiano arrivando altri veicoli, per non causare pericoli.', 'La condizione ''strada stretta'' non è una trappola, ma sottolinea la necessità di maggiore prudenza.', 'Strada stretta, doppia attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23624, 'Anche se la strada è a senso unico e sei sul lato sinistro, i veicoli possono comunque arrivare da dietro. È buona norma che il conducente ricordi al passeggero di fare attenzione, perché la sicurezza è responsabilità di tutti.', 'Le parole ''lato sinistro'' e ''senso unico'' potrebbero far pensare a meno pericoli, ma non è così. ''È opportuno'' significa ''è consigliabile'', quindi è una buona pratica.', 'Passeggero? Ricorda tu la sicurezza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23625, 'Quando un passeggero apre la portiera sul lato destro, specialmente in città, deve fare attenzione ai pedoni che camminano sul marciapiede. Il conducente deve ricordarglielo per evitare di colpire qualcuno.', 'La frase ''pedoni in transito'' specifica a chi fare attenzione, non è una limitazione. ''È opportuno'' significa ''è consigliabile'', quindi è una buona pratica.', 'Portiera destra? Occhio al pedone!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23626, 'Lasciare il motore acceso quando si è fermi, anche per poco tempo, è sbagliato. Inquina l''aria, fa rumore e consuma carburante inutilmente. Il motore va spento.', 'La frase ''per poco tempo'' è la parola trappola. Non importa quanto tempo, il motore va spento se si sosta.', 'Sosta = motore spento, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23627, 'Quando scendi dall''auto, devi sempre controllare in entrambe le direzioni: sia i veicoli che arrivano da dietro, sia quelli che arrivano di fronte. Non puoi ignorare una direzione, specialmente su una strada stretta.', 'La frase ''ma non di quelli di fronte'' è la trappola. Devi guardare sempre in tutte le direzioni.', 'Scendi? Guarda avanti e indietro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23628, 'È molto importante regolare il sedile e il poggiatesta prima di partire. Questo ti permette di guidare in modo comodo e sicuro, avendo il controllo del veicolo e proteggendo il collo in caso di incidente.', 'La parola ''opportuno'' significa che è una cosa buona e consigliabile da fare, non un obbligo assoluto, ma è fondamentale per la tua sicurezza.', 'Sedile e poggiatesta: comfort e sicurezza prima di partire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23629, 'Regolare bene gli specchietti (quello interno e quelli esterni) è essenziale. Ti permette di vedere cosa succede dietro e ai lati del tuo veicolo, evitando pericoli e manovrando in sicurezza.', 'Anche qui ''opportuno'' indica una buona pratica, una cosa da fare per la tua sicurezza e quella degli altri.', 'Specchietti: vedi tutto, guidi sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23630, 'Anche quando guidi un motociclo, gli specchietti sono fondamentali. Regolarli bene ti aiuta a controllare il traffico dietro di te e a fare manovre in sicurezza.', 'Il concetto di ''opportuno'' si applica anche qui: è una buona abitudine che aumenta la tua sicurezza.', 'Moto o auto, specchietti sempre a posto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23631, 'È un obbligo di legge avere sempre con te tutti i documenti del veicolo e la tua patente, e devono essere validi (non scaduti). Se ti fermano per un controllo, devi mostrarli.', 'La parola ''bisogna'' indica un obbligo, una cosa che devi fare per legge. ''In corso di validità'' significa che non devono essere scaduti.', 'Documenti validi: sempre con te, sempre in regola.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23632, 'Non puoi guidare qualsiasi veicolo. Devi essere sicuro che la patente che possiedi ti permetta di guidare quel tipo specifico di veicolo (ad esempio, con la patente B non puoi guidare un camion).', 'La frase ''bisogna essere certi'' significa che devi verificare con attenzione. È un obbligo legale e di sicurezza.', 'Patente giusta = veicolo giusto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23633, 'Prima di partire, devi assicurarti che il veicolo funzioni bene. Questo include freni, luci, pneumatici, ecc. Un veicolo non efficiente è pericoloso per te e per gli altri.', 'La frase ''perfetto stato di efficienza'' può sembrare forte, ma significa che il veicolo deve essere sicuro e funzionante, senza difetti che possano causare problemi durante la guida.', 'Veicolo efficiente = guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23634, 'Se trasporti oggetti (ad esempio nel bagagliaio o sul sedile posteriore), devi sistemarli bene. Se cadono o si muovono, possono distrarti, bloccare i pedali o causare incidenti.', '''Accertarsi'' significa verificare con attenzione. È importante per la sicurezza di tutti.', 'Carico sicuro = nessun pericolo in viaggio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23635, 'È fondamentale che tu possa vedere bene dietro e ai lati del veicolo. Se i passeggeri o il carico bloccano la vista, non puoi guidare in sicurezza e rischi incidenti.', '''Compromessa la visibilità'' significa che non riesci a vedere bene. Questo è molto pericoloso.', 'Vedere bene = sempre, senza ostacoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23636, 'Se guidi un veicolo che non conosci, devi prima capire dove sono i comandi (come le frecce, i fari, il clacson) e come funzionano. Questo ti permette di reagire velocemente e in sicurezza.', '''Individuare'' e ''comprenderne bene il funzionamento'' sono azioni importanti per la tua sicurezza e per evitare errori alla guida.', 'Conosci i comandi = guida sicura e senza sorprese.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23637, 'Prima di partire, devi controllare che tutti i passeggeri (anche quelli dietro) abbiano allacciato correttamente le cinture di sicurezza. Le cinture salvano la vita in caso di incidente.', '''Regolarmente allacciato'' significa che la cintura deve essere messa bene, non solo appoggiata.', 'Cinture = tutti allacciati, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23638, 'Il contachilometri parziale serve solo per misurare i chilometri di un singolo viaggio, se vuoi. Non è una regolazione obbligatoria o necessaria per iniziare a guidare in sicurezza.', 'La parola ''bisogna'' qui è una trappola. Non è un obbligo, ma una scelta personale.', 'Contachilometri parziale: non è obbligatorio regolarlo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23639, 'L''airbag del conducente è un sistema di sicurezza molto importante che si attiva in caso di incidente. Non deve mai essere disattivato, perché ti protegge.', '''Disinserire'' significa spegnere o disattivare. L''airbag del conducente non si disattiva, a meno di casi molto specifici e rari che non riguardano la guida normale.', 'Airbag conducente: mai disattivare, è sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23640, 'Il pretensionatore è un sistema che stringe le cinture in caso di urto, ma non tutte le cinture lo hanno. L''importante è che le cinture ci siano e funzionino bene, non è obbligatorio verificare la presenza del pretensionatore prima di ogni viaggio.', 'La frase ''verificare che siano dotate di pretensionatore'' è troppo specifica e non è un controllo obbligatorio prima di partire. L''importante è la funzionalità generale delle cinture.', 'Cinture funzionanti: sì; pretensionatore: non è un controllo obbligatorio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23641, 'Devi controllare che il veicolo sia efficiente (freni, luci, pneumatici) sempre, prima di ogni viaggio, anche se è breve. La sicurezza non dipende dalla lunghezza del percorso.', 'La parola ''solo se'' è una trappola. La sicurezza è importante sempre, non solo per i lunghi viaggi.', 'Efficienza veicolo: sempre, non ''solo se''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23642, 'VERO. L''arresto è quando ti fermi per un motivo legato alla circolazione stradale, come un semaforo rosso, un segnale di stop o il traffico. Non è una tua scelta, ma un obbligo.', 'La parola chiave è ''esigenze della circolazione''. Significa che la causa della fermata è il traffico o le regole della strada, non una tua necessità personale.', 'Arresto = Obbligo della strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23643, 'VERO. La fermata è una sosta molto breve che fai per far salire o scendere qualcuno dal veicolo. Il conducente deve rimanere vicino al veicolo e pronto a ripartire subito.', 'Le parole importanti sono ''temporanea sospensione'' e ''salita o discesa delle persone''. Indicano che è una pausa breve e per uno scopo specifico legato ai passeggeri.', 'Fermata = Persone salgono/scendono.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23644, 'VERO. La fermata può essere anche una brevissima pausa per altre necessità, come chiedere informazioni, ma sempre per un tempo molto limitato e senza creare intralcio al traffico.', 'Attenzione a ''esigenze di brevissima durata''. Questo sottolinea che la fermata è sempre per poco tempo e per motivi rapidi, non per lunghe attese.', 'Fermata = Breve e veloce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23645, 'VERO. Questa è la definizione generale di fermata: una pausa molto corta della marcia del veicolo per una necessità immediata. L''importante è che sia ''temporanea'' e di ''brevissima durata''.', 'Le parole ''temporanea sospensione'' e ''brevissima durata'' sono fondamentali per capire il concetto di fermata. Se fosse più lunga, sarebbe una sosta.', 'Fermata = Pausa lampo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23646, 'FALSO. Questa descrizione non è dell''arresto, ma della fermata (o della sosta se la durata è maggiore). L''arresto è sempre legato a un obbligo della circolazione, non a esigenze personali del conducente o dei passeggeri.', 'La frase ''esigenze del conducente o dei passeggeri'' è la trappola. Questo è il motivo di una fermata, non di un arresto. L''arresto non è una scelta personale.', 'Arresto = Obbligo, non scelta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23647, 'FALSO. Questa è la definizione di ''arresto'', non di ''fermata''. La fermata è per esigenze personali e brevi, mentre l''arresto è imposto dalle regole o dalle condizioni del traffico.', 'La frase ''esigenze della circolazione'' è la chiave. Se leggi questa frase, pensa subito all''arresto, non alla fermata.', 'Fermata = Personale; Arresto = Circolazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23648, 'FALSO. La legge non stabilisce una durata massima in minuti per la fermata. Deve essere di ''brevissima durata'' e il conducente deve essere sempre pronto a ripartire. Dieci minuti sono considerati troppo lunghi per una fermata e rientrerebbero nella definizione di ''sosta''.', 'Il numero ''dieci minuti'' è la parola trappola. Non esiste un limite di tempo specifico per la fermata, solo l''indicazione ''brevissima durata''.', 'Fermata = Brevissima, non 10 minuti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23649, 'FALSO. Il numero di passeggeri che salgono o scendono non rende la fermata vietata. L''importante è che la fermata sia fatta in sicurezza, per un tempo brevissimo e senza creare pericolo o intralcio alla circolazione.', 'La frase ''più di uno'' è un dettaglio irrilevante e serve a confondere. Il numero di passeggeri non influenza la legalità della fermata.', 'Numero passeggeri non vieta la fermata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23650, 'Quando ti fermi con la macchina, non devi bloccare la strada o rendere difficile il passaggio per gli altri veicoli. Devi sempre permettere al traffico di muoversi liberamente.', 'La frase ''arrecare intralcio'' significa ''causare un ostacolo'' o ''dare fastidio''.', 'Fermata = mai bloccare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23651, 'È simile alla domanda precedente. Quando ti fermi, la tua auto non deve fermare o rallentare il traffico normale. Devi scegliere un posto dove non dai fastidio.', 'La frase ''normale flusso del traffico'' significa che le altre auto devono poter passare senza problemi.', 'Flusso libero, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23652, 'Quando ti fermi, devi stare attento a non creare situazioni pericolose per pedoni, ciclisti o altre auto. Per esempio, non devi aprire la portiera senza guardare.', 'La frase ''costituire pericolo'' significa ''essere un pericolo''. Gli ''utenti della strada'' sono tutte le persone che usano la strada (pedoni, ciclisti, altri automobilisti).', 'Sicurezza prima di tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23653, 'La fermata è una sosta molto breve. Questo significa che devi rimanere al volante o molto vicino all''auto, pronto a ripartire subito se serve. Non puoi allontanarti.', 'La chiave è ''sempre presente e pronto a riprendere la marcia''. La ''fermata'' è diversa dalla ''sosta'' proprio per questo.', 'Fermata = al volante!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23654, 'Devi sempre prendere tutte le precauzioni necessarie per non causare incidenti. Ad esempio, guardare nello specchietto prima di accostare, segnalare con la freccia.', 'Le ''opportune cautele'' significano ''le giuste attenzioni/precauzioni''. ''Atte ad evitare'' significa ''fatte per evitare''.', 'Attenzione massima!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23655, 'Anche se vuoi chiedere informazioni a un poliziotto, non puoi fermarti se questo blocca il traffico o lo rallenta. Devi trovare un posto dove fermarti senza dare fastidio.', 'La frase ''Non è consentito'' significa ''non si può fare''. La condizione ''quando ciò possa causare intralcio o rallentamento'' è fondamentale.', 'Informazioni sì, intralcio no!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23656, 'Questa è una domanda ''trappola'' sulla definizione di fermata. La fermata è una sosta brevissima dove il conducente NON si allontana dal veicolo e rimane pronto a ripartire. Se ti allontani, anche per poco, non è più una fermata ma una sosta.', 'La parola ''allontanarsi'' rende la frase falsa per la definizione di fermata. Durante la fermata, il conducente non si allontana.', 'Fermata = mai via!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23657, 'Non è *sempre* consentita. Come abbiamo visto nella domanda 23655, se la fermata per chiedere informazioni causa intralcio o rallentamento, allora non è permessa. La parola ''sempre'' è la chiave.', 'La parola ''sempre'' è quasi sempre una trappola nei quiz di guida, perché ci sono quasi sempre delle eccezioni.', '''Sempre'' è spesso FALSO!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23658, 'Ci sono due errori qui. Primo, durante la fermata il conducente NON si allontana. Secondo, anche se fosse una sosta (dove ci si può allontanare), non si deve mai lasciare il motore acceso quando si lascia il veicolo, sia per sicurezza che per inquinamento.', 'La frase ''se si allontana'' è già sbagliata per la fermata. Inoltre, ''deve lasciare il veicolo con il motore acceso'' è sbagliato in generale.', 'Motore spento, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23659, 'Quando ti fermi e non c''è un marciapiede rialzato, devi lasciare almeno un metro di spazio tra il tuo veicolo e il bordo della strada. Questo spazio serve per far camminare i pedoni in sicurezza.', 'La frase ''non inferiore ad un metro'' significa che devi lasciare ''almeno un metro'' di spazio. È una misura minima di sicurezza per i pedoni.', 'No marciapiede = 1 metro per i pedoni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23660, 'Fuori dalle città, quando ti fermi, la regola generale è mettere il tuo veicolo fuori dalla strada (carreggiata), se c''è lo spazio. Questo aiuta a mantenere la strada libera e sicura per gli altri veicoli.', 'La parola chiave è ''se possibile''. Significa che devi farlo solo se ci sono le condizioni (ad esempio, una piazzola o una banchina). Non è un obbligo assoluto se non c''è spazio adeguato.', 'Fuori città, fermata = fuori carreggiata (se puoi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23661, 'Anche fuori dalle città, devi mettere il veicolo fuori dalla carreggiata quando ti fermi. Ma ricorda, non puoi mai fermarti o parcheggiare sulle piste ciclabili, perché sono riservate solo alle biciclette.', 'La parte ''ma non sulle piste ciclabili'' è fondamentale. Le piste ciclabili sono sempre vietate ai veicoli a motore per la fermata e la sosta.', 'Fuori carreggiata sì, pista ciclabile no!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23662, 'Se fuori città non puoi proprio mettere il veicolo fuori dalla strada (magari non c''è spazio o una banchina), allora devi fermarti sul bordo destro della strada, il più vicino possibile. Così non ostacoli il traffico.', 'La frase ''se non è possibile collocare il veicolo fuori della carreggiata'' indica una situazione eccezionale. In questo caso, ''il più vicino possibile al margine destro'' è la soluzione corretta.', 'Fuori carreggiata no? Allora margine destro, attaccato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23663, 'Questa domanda è FALSA. Nelle strade urbane (in città) senza marciapiede rialzato, non devi stare ''il più vicino possibile'' al margine. Devi lasciare almeno un metro di spazio per i pedoni, come abbiamo visto nella domanda 23659.', 'La frase ''il più vicino possibile'' è la trappola. In città, senza marciapiede, la priorità è lasciare spazio (1 metro) per i pedoni, non attaccarsi al bordo.', 'Città, no marciapiede = 1 metro per pedoni, non attaccato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23664, 'Questa domanda è FALSA. È vero che fuori città, se possibile, devi mettere il veicolo fuori dalla carreggiata. Ma la parte ''eventualmente su una pista ciclabile'' è assolutamente sbagliata! Non si può mai fermarsi o parcheggiare su una pista ciclabile.', 'La parte ''eventualmente su una pista ciclabile'' rende l''intera affermazione FALSA. Le piste ciclabili sono sempre vietate per la fermata e la sosta dei veicoli a motore.', 'Pista ciclabile = mai! (nemmeno per fermata).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23665, 'È vero. Fermarsi vicino ai passaggi a livello è molto pericoloso perché potresti non vedere il treno o bloccare il suo passaggio. La sicurezza è la cosa più importante.', 'La frase ''in corrispondenza o in prossimità'' significa ''proprio sopra o molto vicino''. Entrambe le situazioni sono vietate per la fermata.', 'Passaggio a livello = pericolo, non fermarti mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23666, 'È vero. Non puoi fermarti sui binari del treno o del tram, né così vicino da bloccare il passaggio di questi veicoli. È estremamente pericoloso e può causare incidenti gravi.', 'La frase ''intralciare la marcia'' significa ''bloccare il passaggio''. È vietato fare qualsiasi cosa che impedisca il movimento dei veicoli su rotaia.', 'Binari = via libera per treni/tram, non per te.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23667, 'È vero. Nelle gallerie la visibilità è ridotta e lo spazio è limitato. Fermarsi è pericoloso perché potresti causare un incidente. Puoi fermarti solo se c''è un cartello specifico che lo permette.', 'La parte ''salvo diversa segnalazione'' è importante. Significa che il divieto vale sempre, a meno che un segnale stradale non indichi esplicitamente il contrario.', 'Galleria = buio, non fermarti (a meno di cartello).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23668, 'È vero. Questi luoghi (sottopassaggi, sotto i ponti, sotto archi o portici) sono spesso stretti o con visibilità limitata. Fermarsi lì può essere pericoloso e creare intralcio. Anche qui, puoi fermarti solo se c''è un segnale che lo permette.', 'Le parole ''sottovia, sovrapassaggi, fornici e portici'' indicano tutti luoghi dove la visibilità o lo spazio possono essere ridotti. ''Salvo diversa segnalazione'' ha lo stesso significato della domanda precedente.', 'Sotto strutture = spazio limitato, non fermarti (a meno di cartello).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23669, 'È vero. Sui dossi (le gobbe della strada) la visibilità è molto ridotta. Se ti fermi lì, chi arriva dall''altra parte non ti vede in tempo e c''è un alto rischio di incidente.', 'La parola ''dossi'' si riferisce alle salite o discese ripide che limitano la visuale. Il divieto è assoluto.', 'Dosso = non si vede, non fermarti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23670, 'È vero. Fuori città e sulle strade veloci, le auto vanno più forte. Se ti fermi vicino a un dosso, anche se non proprio sopra, chi arriva non ha il tempo di vederti e frenare. Per questo, il divieto si estende anche alla ''prossimità''.', 'La frase ''in prossimità'' significa ''vicino''. Non è solo vietato sul dosso, ma anche nelle sue vicinanze in certi tipi di strade. ''Fuori dai centri abitati e sulle strade urbane di scorrimento'' sono i luoghi dove la velocità è maggiore.', 'Dosso + alta velocità = anche vicino è pericoloso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23671, 'È vero. Nelle curve la visibilità è limitata. Se ti fermi, chi arriva non ti vede. Fuori città o sulle strade veloci, dove si va più forte, è vietato fermarsi anche vicino alla curva, proprio per la sicurezza.', 'Il divieto vale ''nelle curve'' e, in certi contesti (''fuori dei centri abitati e sulle strade urbane di scorrimento''), anche ''in loro prossimità'' (vicino alle curve).', 'Curva = non si vede, non fermarti (e fuori città, neanche vicino).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23672, 'È falso. La fermata è normalmente consentita sul margine destro della carreggiata, purché non ci siano divieti specifici (come strisce gialle, segnali di divieto, ecc.) e non si crei intralcio. Anzi, è il posto più comune e sicuro per fermarsi.', 'La parola ''vietata'' è la trappola. La fermata sul margine destro è la regola generale, non un divieto.', 'Margine destro = di solito si può fermare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23673, 'È falso. In una strada a senso unico, se non ci sono divieti specifici (come strisce gialle o segnali), puoi fermarti anche sul margine sinistro, purché non intralci il traffico e lasci spazio per il passaggio.', 'Anche qui, ''vietata'' è la parola chiave. In una strada a senso unico, il margine sinistro è spesso permesso per la fermata, a differenza delle strade a doppio senso.', 'Senso unico = anche a sinistra si può (se non vietato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23674, 'È falso. La fermata è sempre vietata in curva, anche se dura poco. La visibilità è troppo ridotta e c''è sempre il rischio di un incidente, non importa quanto sia breve la fermata.', 'Le parole ''anche in curva'' e ''di breve durata'' sono le trappole. Non importa quanto duri la fermata, in curva è sempre proibito.', 'Curva = mai fermarsi, neanche un secondo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23675, 'È falso. La fermata è consentita allo sbocco dei passi carrabili, purché non si intralci l''accesso o l''uscita dei veicoli. È la sosta (lasciare il veicolo e allontanarsi) che è vietata, non la fermata (breve e con il conducente presente).', 'La parola ''vietata'' è la trappola. È fondamentale distinguere tra ''fermata'' e ''sosta''. La sosta è vietata, la fermata no, se non si crea intralcio.', 'Passo carrabile: fermata OK, sosta NO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23676, 'È falso. La fermata è consentita in queste aree, ma solo per il tempo strettamente necessario e senza intralciare le operazioni di mercato o di carico/scarico. È la sosta (lasciare il veicolo per un tempo non breve) che è vietata, non la fermata.', 'Ancora una volta, ''vietata'' è la parola chiave. Come per i passi carrabili, è la ''sosta'' che è vietata in queste aree, non la ''fermata'' breve e funzionale.', 'Aree speciali: fermata OK, sosta NO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23677, 'È vietato fermarsi vicino a un segnale stradale verticale se il tuo veicolo lo copre, perché gli altri automobilisti non lo vedrebbero. La sicurezza stradale dipende dalla chiara visibilità dei segnali.', 'La parte importante è ''in modo da occultarne la vista''. Non è vietato fermarsi *sempre* vicino a un segnale, ma solo se lo nascondi.', 'Non coprire i segnali!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23678, 'Come per i segnali verticali, non puoi fermarti dove il tuo veicolo nasconde un semaforo. È fondamentale che tutti vedano le luci del semaforo per capire quando fermarsi o partire, evitando incidenti.', 'Anche qui, ''in modo da occultarne la vista'' è la condizione chiave. Se non lo copri, la fermata potrebbe essere permessa (se non ci sono altri divieti).', 'Non coprire i semafori!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23679, 'I segnali di preselezione (le frecce disegnate sull''asfalto che indicano la direzione) e le corsie di canalizzazione (quelle che ti guidano in una direzione specifica) servono a organizzare il traffico. Fermarsi lì blocca il flusso e crea confusione e pericolo.', '''Segnali orizzontali di preselezione'' e ''corsie di canalizzazione'' sono luoghi specifici dove il traffico deve scorrere liberamente e senza interruzioni.', 'Non bloccare le frecce a terra e le corsie speciali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23680, 'Fuori dalle città, gli incroci sono spesso più pericolosi perché le velocità sono più alte. Fermarsi vicino a un incrocio è molto pericoloso perché riduce la visibilità per tutti e può causare incidenti gravi.', '''Fuori dei centri abitati'' specifica il contesto. La regola è più severa dove le velocità sono maggiori e la visibilità può essere ridotta.', 'Lontano dagli incroci fuori città.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23681, 'Nelle città, vicino agli incroci, non puoi fermarti o parcheggiare a meno di 5 metri dall''incrocio. Questo serve a garantire la visibilità e la sicurezza per tutti. Se c''è un segnale diverso (ad esempio, un parcheggio consentito), allora puoi.', '''A meno di 5 metri'' è la distanza minima di sicurezza. ''Salvo diversa segnalazione'' significa che un segnale specifico può cambiare questa regola generale.', 'In città, 5 metri dagli incroci, a meno che non sia permesso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23682, 'La fermata è vietata *sempre* in corrispondenza dei distributori di carburante, non solo quando sono aperti. Questo perché le aree dei distributori devono essere libere per il rifornimento e per la sicurezza, in qualsiasi momento.', '''Limitatamente alle ore di esercizio'' è la parola trappola. Il divieto è valido 24 ore su 24, 7 giorni su 7.', 'Distributore = sempre libero.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23683, 'Il segnale ''DIVIETO DI SOSTA'' vieta solo la sosta (cioè il parcheggio prolungato), ma non la fermata (una breve interruzione per far salire/scendere qualcuno o per un''esigenza momentanea, con il conducente vicino al veicolo).', 'È fondamentale distinguere tra ''sosta'' e ''fermata''. Il segnale vieta solo la sosta.', 'Divieto di Sosta = puoi fermarti, non parcheggiare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23684, 'La fermata è vietata vicino ai segnali stradali *solo se* il tuo veicolo li copre e impedisce agli altri di vederli. Se non li copri e non crei pericolo, puoi fermarti.', '''Anche se il veicolo non ne occulta la vista'' è la parte che rende la frase falsa. Il divieto scatta *solo se* il segnale viene coperto.', 'Se non copri, puoi fermarti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23685, 'Sulle autostrade la fermata è vietata, ma ci sono eccezioni per le emergenze (ad esempio, un guasto al veicolo o un malore). In questi casi, devi fermarti sulla corsia di emergenza o in una piazzola di sosta, se presenti.', '''Anche in caso di emergenza'' è la parola trappola. In caso di emergenza, la fermata è consentita, ma in luoghi specifici e sicuri.', 'Emergenza in autostrada = corsia d''emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23686, 'Nelle città, la fermata è vietata *a meno di 5 metri* dagli incroci. Se sei a *più di 5 metri*, la fermata è generalmente consentita (a meno di altri divieti specifici, come un divieto di fermata o sosta).', '''A più di 5 metri'' è la trappola. Il divieto è per ''meno di 5 metri''.', 'In città, oltre i 5 metri dall''incrocio puoi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23687, 'Le corsie di accelerazione servono per entrare in autostrada o su strade a scorrimento veloce, prendendo la giusta velocità. Fermarsi lì è estremamente pericoloso perché blocca il traffico e impedisce agli altri veicoli di accelerare in sicurezza. Non è mai consentita, nemmeno per pochissimo tempo.', '''Purché brevissima'' è la trappola. Non importa quanto sia breve, è sempre vietata per la sicurezza di tutti.', 'Corsia di accelerazione = mai fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23688, 'Gli attraversamenti pedonali sono spazi dedicati ai pedoni per attraversare la strada in sicurezza. Se un veicolo si ferma o sosta lì, blocca il passaggio e può essere molto pericoloso per chi cammina. Per questo motivo, è sempre vietato fermarsi o sostare.', 'La parola ''sempre'' in questo caso è corretta. Non ci sono eccezioni per gli attraversamenti pedonali.', 'Attraversamento pedonale: MAI fermarsi o sostare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23689, 'Le piste ciclabili sono riservate alle biciclette. Se un veicolo si ferma o sosta su di esse, impedisce ai ciclisti di passare e li mette in pericolo. Anche agli ''sbocchi'' (cioè dove la pista inizia o finisce) è vietato per non bloccare l''accesso o l''uscita dei ciclisti.', 'La frase ''in ogni caso'' significa che non ci sono eccezioni. Per le piste ciclabili e i loro sbocchi, è vero.', 'Pista ciclabile e sbocchi: zona sacra per le bici, tutto vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23690, 'I marciapiedi sono fatti per i pedoni. Di solito, non si può fermare o sostare su di essi. Tuttavia, a volte ci sono dei cartelli o delle strisce che indicano che è permesso, ad esempio per scaricare merci in certi orari. Quindi, il divieto vale ''salvo diversa segnalazione''.', 'La parte ''salvo diversa segnalazione'' è fondamentale. Significa ''a meno che non ci sia un cartello che dice il contrario''. Senza questa precisazione, la frase sarebbe FALSO.', 'Marciapiede = pedoni. Solo se c''è un cartello puoi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23691, 'Il passo carrabile è l''ingresso di un garage o di un cortile. La sosta è vietata perché bloccherebbe l''accesso. Ma la fermata, che è per un tempo molto breve e con il conducente vicino e pronto a ripartire, è consentita, perché non impedisce il passaggio.', 'Attenzione alla differenza tra ''sosta'' (più lunga, veicolo fermo senza conducente o con conducente che si allontana) e ''fermata'' (brevissima, conducente presente e pronto a ripartire). La sosta è vietata, la fermata è permessa.', 'Passo carrabile: sosta NO, fermata SÌ (se non blocchi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23692, 'I cassonetti servono per buttare la spazzatura. La sosta è vietata per non impedire lo svuotamento da parte degli operatori. Ma la fermata, per un tempo molto breve (ad esempio per buttare la spazzatura o far scendere un passeggero), è consentita, purché non si blocchi il servizio di raccolta.', 'Anche qui, la ''sosta'' è vietata, ma la ''fermata'' è permessa. È importante distinguere i due concetti.', 'Cassonetto: sosta NO, fermata SÌ (se non blocchi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23693, 'Come abbiamo visto, gli attraversamenti pedonali devono essere sempre liberi per i pedoni. Non si può né sostare né fermarsi, nemmeno per un attimo, nemmeno per far scendere un passeggero. È troppo pericoloso e impedisce il passaggio sicuro dei pedoni.', 'La frase ''consentita sugli attraversamenti pedonali'' è la parte sbagliata. Gli attraversamenti pedonali sono sempre vietati per qualsiasi tipo di fermata o sosta.', 'Attraversamento pedonale = MAI fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23694, 'Abbiamo imparato che sia la sosta che la fermata sono vietate sia sulle piste ciclabili che ai loro sbocchi. La frase dice ''ma non agli sbocchi di esse'', il che è sbagliato. È vietata anche agli sbocchi per garantire la sicurezza dei ciclisti.', 'La parte ''ma non agli sbocchi di esse'' è la parola trappola che rende la frase FALSO. Il divieto vale per entrambi i casi.', 'Pista ciclabile e sbocchi: tutto vietato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23695, 'Questa domanda è l''opposto della 23691. Abbiamo detto che la fermata è consentita allo sbocco dei passi carrabili (mentre la sosta è vietata). Quindi, dire che la fermata è vietata è sbagliato.', 'La frase ''La fermata è vietata'' è la parte sbagliata. La fermata è consentita, la sosta è vietata.', 'Passo carrabile: sosta NO, fermata SÌ.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23696, 'Di solito, la fermata in seconda fila è vietata perché blocca il traffico e può essere pericolosa. Tuttavia, ci sono delle rare eccezioni, ad esempio se non c''è spazio per fermarsi al bordo della strada e non si crea nessun intralcio al traffico. La parola ''sempre'' rende la frase FALSO, perché non è un divieto assoluto.', 'La parola ''sempre'' è la trappola. Non è *sempre* vietata, ci sono delle eccezioni molto specifiche.', 'Seconda fila: di solito NO, ma ''sempre'' è troppo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23697, 'Non esiste nessuna regola nel Codice della Strada che vieta la fermata solo perché è notte. Si può fermare anche di notte, purché si rispettino tutte le altre regole (non bloccare il traffico, non essere in divieto di sosta, ecc.).', 'La frase ''in ogni caso nelle ore notturne'' è la parte trappola. Non c''è un divieto specifico per la fermata durante la notte.', 'La notte non cambia le regole di fermata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23698, 'La sosta è quando fermi il veicolo per un tempo prolungato e puoi allontanarti. È la differenza principale con la ''fermata'', dove devi rimanere vicino al veicolo.', 'Le parole chiave sono ''protratta nel tempo'' e ''possibilità del conducente di allontanarsi''. Queste definiscono la sosta.', 'Sosta = tempo + via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23699, 'Sì, questa è proprio la caratteristica che distingue la sosta dalla fermata. Se fai una sosta, puoi lasciare il veicolo e andare via per un po''.', 'La frase ''può allontanarsi'' è il punto cruciale. Se fosse ''non può allontanarsi'', sarebbe una fermata.', 'Sosta = scendi e vai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23700, 'Anche se ti allontani dal veicolo, devi sempre assicurarti che sia parcheggiato in sicurezza. Ad esempio, devi mettere il freno a mano, spegnere il motore e, se in pendenza, girare le ruote verso il marciapiede.', 'La frase ''deve adottare le opportune cautele'' significa che devi prendere tutte le precauzioni necessarie per evitare pericoli.', 'Sosta = sicurezza prima di tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23701, 'Quando lasci il veicolo, devi fare in modo che nessuno possa usarlo senza il tuo permesso. Questo significa togliere le chiavi, chiudere le portiere e, se possibile, attivare l''antifurto.', 'La frase ''impedire l''uso del veicolo senza il suo consenso'' si riferisce alla prevenzione di furti o usi non autorizzati.', 'Sosta = chiavi via, auto chiusa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23702, 'Non ''in ogni caso''. Se il veicolo è parcheggiato in una strada ben illuminata, non è obbligatorio lasciare le luci di posizione accese. Le luci servono per rendere visibile il veicolo, ma se la strada è già chiara, non servono.', 'La parola trappola è ''in ogni caso''. Nei quiz, le affermazioni assolute (come ''sempre'', ''mai'', ''in ogni caso'') sono spesso false.', '''In ogni caso'' = attenzione, spesso è FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23703, 'Non c''è un limite di tempo massimo per la sosta, a meno che non ci siano segnali specifici (come un disco orario o un parcheggio a pagamento con limite). La sosta può durare anche giorni, se consentito.', 'La frase ''non può allontanarsi... per più di tre ore'' introduce un limite di tempo che non esiste nella definizione generale di sosta.', 'Sosta = nessun limite di tempo (se non indicato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23704, 'Quando ti fermi per una sosta, è sempre una buona pratica usare il freno a mano (freno di stazionamento) per bloccare l''auto. Inoltre, mettere la prima marcia (il rapporto più basso) aiuta a tenere ferma l''auto, specialmente se la strada è un po'' in pendenza, aggiungendo un blocco meccanico al motore.', 'La parola ''opportuno'' significa ''è consigliabile'' o ''è una buona idea''. Non è un obbligo assoluto, ma è la pratica più sicura e corretta.', 'Sosta = Freno a mano + 1ª marcia (o retromarcia in discesa).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23705, 'Quando parcheggi, devi sempre assicurarti che la tua auto non si muova da sola. Questo vale sempre, sia che la strada sia piatta, in salita o in discesa. Devi usare tutti i mezzi necessari (freno a mano, marcia inserita) per bloccarla in modo sicuro.', 'La frase ''indipendentemente dal grado di pendenza della strada'' è fondamentale. Significa che non importa se la strada è in salita, in discesa o piatta, la sicurezza è sempre la priorità.', 'Sosta = Auto ferma SEMPRE, ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23706, 'Se la strada è molto in pendenza, devi fare più cose per garantire la sicurezza. Oltre al freno a mano e alla prima marcia (o retromarcia in discesa), devi girare le ruote verso il marciapiede. Così, se l''auto si muovesse, si bloccherebbe contro il marciapiede e non andrebbe in mezzo alla strada, causando pericoli.', 'La condizione ''nelle strade a forte pendenza'' indica una situazione che richiede misure di sicurezza extra. ''Verso il marciapiede'' è l''accorgimento aggiuntivo specifico.', 'Forte pendenza = Freno a mano + Marcia + Ruote al marciapiede.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23707, 'Quando fai una sosta, devi sempre spegnere il motore. Lasciare il motore acceso non è permesso, inquina l''ambiente e consuma carburante inutilmente. È una questione di rispetto delle norme e dell''ambiente.', 'Il verbo ''deve'' indica un obbligo, non una semplice raccomandazione. È una regola da seguire sempre.', 'Sosta = Motore SPENTO, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23708, 'Se la strada è in salita, devi inserire la PRIMA marcia, non la quarta. La prima marcia è quella che blocca meglio il motore e impedisce all''auto di scendere. La quarta marcia, essendo un rapporto più ''lungo'', non ha lo stesso effetto frenante e non garantisce l''immobilità del veicolo.', 'La parola ''quarta marcia'' è la trappola. La marcia giusta per bloccare il veicolo in salita è la prima (o la retromarcia in discesa).', 'Salita = 1ª marcia (MAI la 4ª!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23709, 'Mettere il cambio in folle significa che nessuna marcia è inserita. In questo modo, il motore non aiuta a tenere ferma l''auto e il veicolo potrebbe muoversi più facilmente. Devi sempre inserire una marcia (la prima in salita, la retromarcia in discesa) oltre al freno a mano per maggiore sicurezza.', 'La frase ''in folle'' è la parola trappola. La folle non blocca il veicolo e lo rende più vulnerabile a movimenti involontari.', 'Sosta = MAI in folle. Sempre una marcia inserita.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23710, 'Nei centri abitati, se c''è un marciapiede rialzato, devi parcheggiare la tua auto il più vicino possibile al bordo destro della strada, nella stessa direzione del traffico. Questo aiuta a mantenere la strada libera e sicura per tutti.', 'La frase ''purché esista il marciapiede rialzato'' è importante. Significa che questa regola vale solo se c''è un marciapiede rialzato. Se non c''è, la regola cambia.', 'Centro abitato + Marciapiede = Vicino a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23711, 'Se parcheggi in un luogo dove non c''è un marciapiede rialzato, devi lasciare almeno un metro di spazio tra la tua auto e il bordo della strada. Questo spazio è fondamentale per permettere ai pedoni di camminare in sicurezza.', 'La parte ''non inferiore ad un metro'' è la chiave. Indica la distanza minima obbligatoria da lasciare per i pedoni.', 'No marciapiede = 1 metro per pedoni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23712, 'Quando sei fuori dai centri abitati e devi parcheggiare, hai l''obbligo di mettere il veicolo fuori dalla strada principale (la carreggiata), se c''è spazio. Questo rende la strada più sicura per chi guida.', 'La parola ''ove possibile'' è importante. Significa che devi farlo se c''è la possibilità, altrimenti si applicano altre regole.', 'Fuori città = Parcheggia fuori strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23713, 'Fuori dai centri abitati, devi parcheggiare l''auto fuori dalla strada, ma non puoi mai parcheggiare sulle piste ciclabili. Le piste ciclabili sono riservate solo alle biciclette.', 'La frase ''ma non sulle piste ciclabili'' è fondamentale. Indica un divieto assoluto, anche se sei fuori dalla carreggiata.', 'Fuori strada sì, pista ciclabile no!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23714, 'Fuori dai centri abitati, devi parcheggiare il veicolo fuori dalla strada. Di solito non puoi parcheggiare sulle banchine (la parte laterale della strada, spesso non asfaltata o meno resistente), a meno che un cartello stradale non ti indichi diversamente.', 'La parte ''ma non sulle banchine, salvo diversa segnalazione'' è cruciale. La regola generale è no, ma un segnale specifico può cambiare questa indicazione.', 'Fuori strada sì, banchina no (salvo cartello).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23715, 'Se ti trovi fuori dai centri abitati e non puoi proprio parcheggiare l''auto fuori dalla strada, allora devi metterla il più vicino possibile al bordo destro della strada. È una soluzione alternativa quando non c''è altro spazio.', 'La frase ''in caso di impossibilità'' è la chiave. Indica che questa è una regola per situazioni eccezionali, quando non puoi fare come previsto dalla regola generale.', 'Fuori strada impossibile = Vicino a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23716, 'Questa affermazione è falsa. Nei centri abitati, se non c''è il marciapiede rialzato, non basta solo parcheggiare vicino al bordo destro. Devi anche lasciare almeno un metro di spazio per il passaggio dei pedoni. La domanda non menziona questo spazio, rendendola incompleta e quindi sbagliata.', 'La trappola è ''anche dove non esiste il marciapiede rialzato''. Se il marciapiede non c''è, la regola non è solo ''vicino al margine'', ma ''vicino al margine e lasciare 1 metro per i pedoni''.', 'No marciapiede = 1 metro per pedoni (non solo vicino).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23717, 'Questa affermazione è falsa. Non si può mai parcheggiare sulle piste ciclabili, né dentro né fuori i centri abitati. Le piste ciclabili sono spazi riservati esclusivamente alle biciclette per la loro sicurezza.', 'La parola ''eventualmente'' e la frase ''anche sulle piste ciclabili'' sono la trappola. Non c''è nessuna ''eventualità'': è sempre vietato parcheggiare sulle piste ciclabili.', 'Pista ciclabile = MAI parcheggiare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23718, 'Questa affermazione è falsa. Se fuori città non puoi parcheggiare l''auto fuori dalla strada, non significa che non puoi proprio sostare. In questo caso, devi parcheggiare il più vicino possibile al bordo destro della strada. C''è un''alternativa, non un divieto assoluto.', 'La frase ''non deve effettuare la sosta'' è la trappola. Non è un divieto di sosta, ma una modifica della modalità di sosta in caso di impossibilità.', 'Impossibile fuori strada = Parcheggia vicino a destra (non vietato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23719, 'In una strada dove si va solo in una direzione (senso unico), puoi parcheggiare anche sul lato sinistro della strada. L''importante è lasciare abbastanza spazio perché le altre auto possano passare senza problemi.', 'La parola ''purché'' indica una condizione. Non è sempre consentita, ma solo se c''è spazio sufficiente.', 'Senso unico + spazio = sosta a sinistra OK.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23720, 'Questa domanda specifica la quantità di spazio da lasciare. Nelle strade a senso unico, se parcheggi a sinistra, devi lasciare almeno 3 metri liberi per il passaggio degli altri veicoli. Questo garantisce la sicurezza e la fluidità del traffico.', 'La frase ''non inferiore a tre metri'' è il requisito specifico di spazio che devi ricordare.', 'Senso unico, sosta a sinistra, minimo 3 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23721, 'Quando trovi un''area dedicata al parcheggio, devi sempre seguire le indicazioni che ti danno i cartelli stradali o le linee disegnate sull''asfalto. Non puoi parcheggiare come vuoi, ma devi rispettare le regole indicate.', 'La frase ''deve collocare... nel modo prescritto'' indica un obbligo, non una scelta. Devi fare come ti dice la segnaletica.', 'Parcheggio = Segui la segnaletica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23722, 'Se ci sono le linee bianche o blu che disegnano i posti auto (chiamati ''stalli''), devi parcheggiare la tua auto esattamente dentro queste linee. Non devi andare negli spazi degli altri veicoli, per non occupare più posti del dovuto.', 'Le parole ''deve sempre sistemare... entro... senza invadere'' sottolineano l''obbligo di essere precisi e rispettare gli spazi delimitati.', 'Stalli = Stai dentro le linee.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23723, 'Questa affermazione è falsa. Anche se è una strada a senso unico, non puoi parcheggiare a sinistra ''sempre''. Devi sempre lasciare spazio per il passaggio degli altri veicoli (ricordi, almeno 3 metri). Se non c''è spazio sufficiente, non puoi parcheggiare lì.', 'La parola ''sempre'' è una parola trappola. Le regole di solito hanno delle condizioni e non sono ''sempre'' valide in ogni situazione.', '''Sempre'' è quasi sempre FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23724, 'Questa affermazione è falsa. Non è vero che è vietato parcheggiare nei centri abitati se non ci sono le strisce. Puoi parcheggiare anche senza strisce, purché non ci siano cartelli di divieto specifici e tu rispetti le regole generali (ad esempio, non bloccare il traffico, non parcheggiare su marciapiedi, ecc.). Le strisce indicano solo i posti ''ufficiali'' e organizzati.', 'La frase ''vietato... quando non esistano le apposite strisce'' è la trappola. L''assenza di strisce non significa un divieto automatico di sosta.', 'No strisce = Non per forza vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23725, 'Questa affermazione è falsa. Se ci sono gli stalli (le linee per parcheggiare), devi parcheggiare la tua auto dentro lo stallo. Non puoi parcheggiare fuori, nemmeno se ti fermi per pochissimo tempo. La durata della sosta non ti permette di non rispettare gli spazi delimitati.', 'La frase ''anche fuori dall''apposito spazio... a condizione che la sosta sia di brevissima durata'' è la trappola. La durata della sosta non è una scusa per non rispettare gli stalli.', 'Stalli = Stai dentro, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23726, 'Questa affermazione è falsa. Se in una zona c''è un parchimetro, significa che devi pagare per parcheggiare, non importa quanto tempo ti fermi. Anche per pochi minuti, devi pagare o mettere il disco orario se previsto, a meno che non sia specificato diversamente (es. primi 15 minuti gratuiti, ma comunque con obbligo di ticket).', 'La frase ''non occorre utilizzarlo se la sosta è di breve durata'' è la trappola. La durata non ti esenta dal pagamento o dall''uso del parchimetro.', 'Parchimetro = Paga sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23727, 'È vietato fermarsi con l''auto vicino ai binari del treno (passaggi a livello) per non creare pericoli o bloccare il traffico. Questa regola vale sia proprio sul passaggio a livello (in corrispondenza) sia molto vicino ad esso (in prossimità).', 'Le parole ''in corrispondenza o in prossimità'' sono importanti. Significano ''proprio lì o molto vicino''. Non solo ''lì'', ma anche ''vicino''.', 'Passaggio a livello = pericolo, non sostare mai vicino.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23728, 'Non si può parcheggiare l''auto sui binari del treno o del tram, né così vicino da impedire il passaggio dei treni o dei tram. I binari devono essere sempre liberi per i veicoli su rotaia.', 'La frase ''o così vicino ad essi da intralciare la marcia'' chiarisce che il divieto si estende anche a una distanza tale da creare un ostacolo.', 'Binari = via libera per treni/tram, non per auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23729, 'Non si può parcheggiare dentro le gallerie perché è pericoloso, riduce la visibilità e può bloccare il traffico in caso di emergenza. Questo divieto vale a meno che non ci sia un cartello specifico che indichi il contrario, ma è molto raro.', 'La clausola ''salvo diversa segnalazione'' è una ''parola trappola'' comune. Indica che la regola generale può cambiare solo se c''è un cartello che lo permette.', 'Galleria = buio e stretto, non sostare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23730, 'Non si può parcheggiare sotto ponti (sovrapassaggi), sottopassaggi (sottovia), archi (fornici) o portici. Anche qui, è pericoloso e può creare problemi di visibilità o spazio, a meno che non ci sia un cartello che lo permetta.', 'Anche qui, ''salvo diversa segnalazione'' è la clausola che può modificare la regola generale, ma il divieto è la norma.', 'Sotto strutture = no sosta, per sicurezza e spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23731, 'Non si può parcheggiare proprio sopra un dosso (una salita o discesa ripida) perché chi arriva non vede bene l''auto e potrebbe non avere il tempo di reagire. Questo crea un pericolo.', 'La parola ''sui dossi'' indica proprio la parte più alta o più bassa del dosso, dove la visibilità è ridotta.', 'Dosso = poca visibilità, no sosta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23732, 'Fuori dalle città e sulle strade veloci (strade urbane di scorrimento), non si può parcheggiare nemmeno vicino ai dossi. Questo perché le auto vanno più veloci e c''è bisogno di più spazio per vedere ed evitare ostacoli in sicurezza.', 'La frase ''in prossimità dei dossi'' è importante: non solo sopra, ma anche vicino. Il contesto ''Fuori dai centri abitati e sulle strade urbane di scorrimento'' indica dove la regola è più severa.', 'Fuori città + dosso = vietato anche vicino.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23733, 'Questa affermazione è falsa. La sosta è vietata sia proprio sui passaggi a livello (in corrispondenza) sia molto vicino ad essi (in prossimità). È pericoloso in entrambi i casi e la legge lo vieta per la sicurezza di tutti.', 'La parte ''ma non in loro prossimità'' è la ''parola trappola'' che rende la frase falsa. Il divieto include anche la prossimità.', 'Passaggio a livello = mai vicino, mai sopra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23734, 'Questa affermazione è falsa. La sosta è vietata sia sui binari dei treni (ferroviarie) sia sui binari dei tram (tranviarie). Tutti i binari devono essere liberi per il passaggio dei veicoli su rotaia.', 'La parte ''ma non di quelle tranviarie'' è la ''parola trappola'' che rende la frase falsa. Il divieto vale per entrambi i tipi di binari.', 'Binari (tutti) = no sosta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23735, 'Questa affermazione è falsa. Anche se una galleria è illuminata, la sosta è comunque vietata per motivi di sicurezza, per non creare intralcio e per facilitare il flusso del traffico, a meno che non ci sia un cartello specifico che lo permetta (cosa rara).', 'La parola ''consentita'' è la ''parola trappola'' che rende la frase falsa. La sosta è vietata. Il fatto che siano ''illuminate'' non cambia la regola generale.', 'Galleria = vietato, luce non cambia la regola.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23736, 'Questa affermazione è falsa. In questi luoghi (sottopassaggi, sotto i ponti, ecc.), è vietata sia la sosta (parcheggio lungo) sia la fermata (breve stop con il conducente a bordo). Sono luoghi pericolosi per qualsiasi tipo di arresto del veicolo.', 'La parte ''ma non la fermata'' è la ''parola trappola'' che rende la frase falsa. Anche la fermata è vietata in questi punti.', 'Sotto strutture = no sosta, no fermata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23737, 'Questa affermazione è falsa. Come abbiamo visto, fuori dai centri abitati e sulle strade urbane di scorrimento, la sosta è vietata anche in prossimità dei dossi. Questo per garantire la massima sicurezza, data la velocità dei veicoli.', 'La frase ''è consentita la sosta'' è la ''parola trappola'' che rende l''affermazione falsa. La sosta è vietata in queste condizioni.', 'Fuori città + dosso = vietato anche vicino.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23738, 'È vietato fermarsi o parcheggiare nelle curve perché riducono la visibilità e sono pericolose. Fuori dai centri abitati e sulle strade urbane di scorrimento (strade veloci), il divieto si estende anche vicino alle curve per la stessa ragione di sicurezza.', 'La parte ''anche in loro prossimità'' è fondamentale. Significa che il divieto non è solo sulla curva, ma anche nello spazio immediatamente precedente o seguente, specialmente dove le velocità sono più alte.', 'Curve = pericolo. Non fermarti né parcheggiare, neanche vicino (fuori città)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23739, 'Non si può fermare o parcheggiare dove si copre un segnale stradale verticale. Se lo fai, gli altri guidatori non vedono il segnale e potrebbero non capire le regole, creando situazioni pericolose.', 'La frase chiave è ''in modo da occultarne la vista''. Il divieto scatta se la tua auto nasconde il segnale. Se non lo nascondi, in teoria potresti, ma è sempre meglio evitare di essere troppo vicini.', 'Segnale coperto = pericolo. Non nascondere i segnali!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23740, 'Come per i segnali verticali, non si può fermare o parcheggiare dove si copre un semaforo. Se un guidatore non vede il semaforo, può non rispettare la luce e causare un incidente grave.', 'Anche qui, ''in modo da occultarne la vista'' è la condizione principale. L''obiettivo è garantire che tutti vedano il semaforo chiaramente.', 'Semaforo coperto = incidente. Non nascondere i semafori!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23741, 'I segnali di preselezione (le frecce disegnate sull''asfalto che indicano la direzione) e le corsie di canalizzazione (quelle che ti guidano a destra, sinistra o dritto) servono a organizzare il traffico. Se ti fermi lì, impedisci agli altri di mettersi nella corsia giusta e crei confusione o pericolo.', 'La congiunzione ''e'' è importante: il divieto vale per entrambi i casi, sia per i segnali orizzontali che per le corsie stesse.', 'Segnali a terra e corsie speciali = non bloccare il flusso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23742, 'Le intersezioni (gli incroci) sono punti dove il rischio di incidenti è più alto. Fuori dai centri abitati, dove le velocità sono maggiori, è ancora più importante non fermarsi o parcheggiare vicino agli incroci per non ostacolare la visibilità e il passaggio degli altri veicoli.', 'La frase ''in corrispondenza e in prossimità'' significa che il divieto vale sia proprio sull''incrocio che nello spazio immediatamente vicino ad esso. ''Fuori dei centri abitati'' specifica l''ambiente, ma il principio di sicurezza è generale.', 'Incroci = pericolo. Lontano dagli incroci, soprattutto fuori città!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23743, 'Questa affermazione è falsa. La sosta è sempre vietata nelle curve. Inoltre, fuori dai centri abitati e sulle strade di scorrimento, è vietata anche *in prossimità* delle curve, non solo *nelle* curve. Questo per garantire la massima sicurezza e visibilità.', 'La parte ''non è vietata in loro prossimità'' rende l''affermazione falsa. Il divieto include proprio la prossimità in quelle condizioni.', 'Curve = pericolo. Sempre vietato, anche vicino (fuori città)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23744, 'Questa affermazione è falsa. Se un veicolo copre un semaforo, sia la sosta (parcheggio prolungato) che la fermata (sosta breve) sono vietate. Entrambe le azioni impedirebbero agli altri di vedere il semaforo, creando pericolo.', 'La congiunzione ''ma non la fermata'' è la parola trappola. Il divieto vale per *entrambe* le situazioni: sosta E fermata.', 'Semaforo coperto = divieto per sosta E fermata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23745, 'Questa affermazione è falsa. La sosta è vietata sia in corrispondenza dei segnali orizzontali di preselezione (le frecce sull''asfalto) sia lungo le corsie di canalizzazione. Entrambi servono a guidare il traffico e non devono essere ostruiti.', 'La parte ''ma non lungo le corsie di canalizzazione'' è la trappola. Il divieto si applica a *entrambi* gli elementi.', 'Segnali a terra E corsie speciali = divieto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23746, 'Questa affermazione è falsa. Fuori dai centri abitati, la sosta è vietata sia *in corrispondenza* delle aree di intersezione (cioè proprio sull''incrocio) sia *in loro prossimità* (cioè vicino all''incrocio). Questo per garantire la sicurezza e la visibilità in punti critici.', 'La frase ''ma non in loro prossimità'' è la parte che rende l''affermazione falsa. Il divieto include proprio la prossimità.', 'Incroci = pericolo. Vietato sia sull''incrocio che vicino (fuori città)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23747, 'La sosta è sempre vietata allo sbocco dei passi carrabili. Questo significa che non puoi parcheggiare davanti a un cancello o un ingresso dove le auto entrano ed escono, perché bloccheresti il passaggio.', 'La parola ''vietata'' è chiara. Non ci sono particolari parole trappola in questa domanda, la regola è assoluta.', 'Passo carrabile: mai bloccare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23748, 'Questa affermazione è falsa. Sia la sosta (parcheggio lungo) che la fermata (sosta breve per far scendere qualcuno) sono vietate sugli attraversamenti pedonali. Le strisce pedonali devono essere sempre libere per i pedoni.', 'La frase ''ma non la fermata'' è la parola trappola. Ti fa pensare che la fermata sia permessa, ma non è così.', 'Strisce pedonali: né sosta né fermata!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23749, 'Questa affermazione è falsa. La sosta è vietata sia sulle piste ciclabili che ai loro sbocchi (cioè dove finiscono o iniziano e si collegano alla strada). Non importa se la sosta è di breve durata, non si deve mai bloccare il passaggio delle biciclette.', 'Le frasi ''ma non agli sbocchi di esse'' e ''nel caso sia di breve durata'' sono le parole trappola. Fanno pensare a un''eccezione che non esiste.', 'Pista ciclabile: sempre libera!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23750, 'Questa affermazione è falsa. La sosta sui marciapiedi è generalmente vietata perché i marciapiedi sono spazi dedicati ai pedoni. Non è consentita nemmeno per breve durata, a meno che non ci siano appositi segnali che lo permettono in casi specifici.', 'La parola ''consentita'' e la frase ''solo se di breve durata'' sono le parole trappola. Ti inducono a pensare che una sosta veloce sia permessa, ma non è la regola generale.', 'Marciapiede: solo per i pedoni!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23751, 'Se parcheggi la tua auto in modo da bloccare un altro veicolo che è già parcheggiato correttamente, la tua sosta è vietata. Non puoi impedire a un altro veicolo di uscire o entrare nel suo parcheggio.', 'La frase ''impedisce l''accesso'' è importante: significa che blocchi l''entrata o l''uscita di un altro veicolo.', 'Non bloccare chi è già parcheggiato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23752, 'Non puoi parcheggiare in un modo che impedisca a un altro veicolo, già parcheggiato, di muoversi o uscire. Questo vale in qualsiasi luogo.', 'La parola ''dovunque'' significa ''in qualsiasi posto''. ''Impedito lo spostamento'' significa che non può muoversi.', 'Mai bloccare il movimento di altri veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23753, 'Parcheggiare in seconda fila (cioè accanto a un altro veicolo già parcheggiato, occupando la corsia) è sempre vietato per le auto. L''unica eccezione sono i veicoli a due ruote (moto, scooter) che possono parcheggiare in seconda fila se non creano intralcio alla circolazione.', 'La parte ''salvo che si tratti di veicoli a due ruote'' è la chiave: indica l''unica eccezione al divieto.', 'Auto: mai in doppia fila. Moto: sì, se non intralcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23754, 'Gli spazi dove si fermano autobus, filobus o tram sono riservati solo a loro. Non puoi parcheggiare lì perché impediresti il servizio pubblico e la fermata dei mezzi.', 'La parola ''riservati'' è fondamentale: significa che quegli spazi sono destinati solo a un certo tipo di veicolo.', 'Spazi bus/tram = solo per bus/tram.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23755, 'Se non ci sono linee o segni a terra che indicano chiaramente l''area di fermata dell''autobus, devi lasciare almeno 15 metri liberi prima e dopo il segnale di fermata. Questo serve per permettere all''autobus di accostare e ripartire in sicurezza.', 'La distanza ''a meno di 15 metri'' è un numero preciso da ricordare. ''Qualora gli spazi... non siano delimitati'' significa ''se non ci sono le linee sull''asfalto''.', 'Segnale bus senza linee? 15 metri di rispetto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23756, 'La sosta in doppia fila è sempre vietata per gli autoveicoli, non importa per quanto tempo o se accendi le luci di emergenza. Le luci di emergenza non rendono legale una sosta vietata.', 'Le espressioni ''consentita per pochi minuti'' e ''azionando le luci di emergenza'' sono le trappole. Queste condizioni non rendono legale una sosta che è vietata per legge.', 'Doppia fila = sempre NO per auto, anche per un minuto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23757, 'Anche se lasci molto spazio per il passaggio di altri veicoli, la sosta in doppia fila per gli autoveicoli è comunque vietata. Non è una questione di spazio disponibile, ma di una regola generale di divieto.', 'La frase ''consentita purché rimanga spazio sufficiente'' è la trappola. Lo spazio non rende legale la doppia fila per le auto.', 'Doppia fila = sempre NO per auto, anche con spazio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23758, 'Gli spazi riservati agli autobus e ai tram sono solo per loro. Non puoi sostare lì, nemmeno per poco tempo. La durata della sosta non cambia il divieto in un''area riservata.', 'La frase ''consentita purché sia di breve durata'' è la trappola. La durata non rende legale la sosta in un''area che è riservata ad altri veicoli.', 'Aree riservate = mai sosta, nemmeno breve!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23759, 'Gli spazi riservati allo stazionamento dei veicoli in servizio di piazza (come i taxi) sono solo per loro. Se sosti lì, impedisci a questi veicoli di lavorare e di essere disponibili per i clienti.', 'La parola chiave è ''riservati''. Significa che quello spazio è solo per un tipo specifico di veicolo, non per tutti.', 'Spazi riservati = non puoi sostare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23760, 'Se un''area è usata per il mercato o per caricare e scaricare merci in orari specifici, non puoi sostare lì. La tua auto intralcerebbe le attività e il passaggio degli altri veicoli.', 'Attenzione a ''nelle ore stabilite''. Questo significa che il divieto vale solo in certi orari. Fuori da quegli orari, potrebbe essere permesso.', 'Mercato/Carico-scarico in orario = vietato sostare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23761, 'Le banchine sono le parti laterali della strada. Di solito, non sono fatte per la sosta e quindi è vietato fermarsi lì. Puoi sostare solo se c''è un segnale specifico che lo permette.', 'La frase ''salvo diversa segnalazione'' è importante. Significa che la regola generale (vietato) cambia solo se c''è un cartello che dice il contrario.', 'Banchina = no sosta, a meno che non ci sia un cartello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23762, 'Questi spazi sono creati apposta per le persone con disabilità. Sostare lì è un comportamento scorretto e impedisce a chi ne ha davvero bisogno di usare il proprio posto.', 'Anche qui, ''riservati'' è la parola chiave. Indica un uso esclusivo per una categoria specifica di persone.', 'Posto disabili = mai sostare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23763, 'Gli scivoli e i raccordi servono alle persone con disabilità per salire e scendere dai marciapiedi. Sostare lì blocca il loro passaggio e rende difficile o impossibile muoversi.', 'La frase ''in corrispondenza'' significa proprio lì, vicino o sopra. Non devi bloccare questi punti di accesso.', 'Scivoli disabili = mai bloccare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23764, 'Gli spazi per i taxi sono ''riservati'' solo ai taxi. Non puoi sostare lì, nemmeno per un minuto. La durata della sosta non cambia il divieto.', 'Le parole ''consentita'' e ''solo se non si protrae per lungo tempo'' sono le trappole. La sosta è sempre vietata, non importa quanto sia breve.', 'Spazi taxi = solo taxi, mai tu.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23765, 'Se un''area è destinata al carico e scarico merci in orari specifici, è solo per quello scopo. Non puoi sostare lì, nemmeno per poco tempo, perché intralceresti le operazioni.', 'Le parole ''consentita'' e ''soltanto se di breve durata'' sono le trappole. La sosta è vietata in quegli orari, indipendentemente dalla durata.', 'Carico/scarico in orario = solo per quello, mai tu.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23766, 'Gli spazi per le persone invalide sono ''riservati'' e non puoi mai sostare lì. Non importa se la sosta è di breve durata, il divieto è assoluto per chi non ha il permesso.', 'Le parole ''consentita'' e ''purché di breve durata'' sono le trappole. La sosta è sempre vietata in questi spazi per chi non è autorizzato.', 'Posto disabili = mai, nemmeno un minuto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23767, 'È vero. Le corsie o carreggiate riservate ai mezzi pubblici (come autobus o tram) devono essere sempre libere. Sostare lì impedirebbe il passaggio e il regolare funzionamento del trasporto pubblico.', 'La parola ''riservate'' è importante: significa che sono dedicate solo a quei mezzi, non ad altri.', 'Corsia bus = sempre libera.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23768, 'È vero. Le aree pedonali urbane sono spazi dedicati esclusivamente ai pedoni. Sostare con un veicolo in queste zone è vietato per garantire la sicurezza e la libertà di movimento delle persone a piedi.', 'Il termine ''aree pedonali'' indica chiaramente che sono zone per i pedoni, non per i veicoli.', 'Area pedonale = solo piedi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23769, 'È vero. Le Zone a Traffico Limitato (ZTL) sono aree dove l''accesso e la sosta sono permessi solo a veicoli autorizzati (ad esempio, residenti o mezzi di servizio). Se non hai un permesso specifico, non puoi sostare.', 'La frase chiave è ''per i veicoli non autorizzati''. Se fossi autorizzato, potresti.', 'ZTL senza permesso = no sosta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23770, 'È vero. Questi spazi sono vitali per i mezzi di soccorso (ambulanze, polizia, vigili del fuoco) o per i mezzi che si occupano della pulizia della città. Devono essere sempre liberi per permettere loro di intervenire rapidamente. La segnaletica specifica conferma questo divieto.', 'Le parole ''servizi di emergenza o di igiene pubblica'' e ''apposita segnaletica'' rafforzano il divieto assoluto.', 'Emergenza/Igiene = spazio libero.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23771, 'È vero. Sostare davanti ai cassonetti dei rifiuti impedisce ai mezzi della nettezza urbana di svuotarli. Questo può causare problemi di igiene e disagi per la comunità.', 'La frase ''davanti ai cassonetti'' è il punto cruciale: blocca il servizio di raccolta.', 'Cassonetto = no sosta (non bloccare).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23772, 'È falso. Nelle aree pedonali urbane non è consentita né la sosta né la fermata, nemmeno per un breve periodo. Sono zone esclusive per i pedoni e devono essere sempre sgombre da veicoli.', 'La parola ''consentite'' è la trappola. Nelle aree pedonali non si può proprio fermarsi o sostare con un veicolo.', 'Area pedonale = mai sosta/fermata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23773, 'È falso. Negli spazi destinati a servizi di emergenza o igiene pubblica è vietata la sosta (lasciare il veicolo per un certo tempo), ma la fermata (una sosta brevissima, con il conducente a bordo e pronto a ripartire) è generalmente consentita, a meno che non ci sia un segnale specifico che vieti anche la fermata. La domanda dice che ''anche la fermata'' è vietata, il che non è sempre vero.', 'La frase ''ed anche la fermata'' è la trappola. La sosta è vietata, ma la fermata no, se non c''è un divieto specifico.', 'Emergenza/Igiene: sosta NO, fermata SÌ (se non c''è divieto specifico).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23774, 'È falso. Davanti ai cassonetti dei rifiuti urbani è vietata la sosta, perché impedisce la raccolta. Tuttavia, la fermata (una sosta brevissima, con il conducente a bordo e pronto a ripartire) è consentita, a patto che non ostacoli il servizio di raccolta. Se ti fermi un attimo e riparti subito, non crei un problema.', 'La frase ''così come la fermata'' è la trappola. Solo la sosta è vietata, non la fermata.', 'Cassonetto: sosta NO, fermata SÌ (se non ostacola).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23776, 'Nei centri abitati, non puoi lasciare un rimorchio da solo, staccato dalla macchina che lo traina. Questo serve per non creare pericoli o intralci alla circolazione. Puoi farlo solo se c''è un cartello specifico che lo permette.', 'La frase ''salvo diversa segnalazione'' è importante. Significa che la regola generale è ''no'', ma se c''è un cartello che dice ''sì'', allora puoi.', 'Rimorchio staccato in città? No, a meno che non ci sia un cartello che lo permette.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23777, 'Se il Codice della Strada (la legge) dice chiaramente che non puoi parcheggiare in un certo posto (ad esempio, in curva o in galleria), allora quel divieto vale sempre. Non è necessario che ci sia anche un cartello che lo ripeta, perché la legge è già chiara.', 'Le parole ''espressamente vietata da una norma del codice stradale'' e ''non è condizionata'' sono fondamentali. Indicano che la legge è la fonte principale del divieto, non il cartello.', 'La legge è la legge! Se il Codice vieta, non serve il cartello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23778, 'È vero che non si può sostare vicino ai distributori di carburante per non intralciare, ma la regola dei ''5 metri prima e dopo'' non è corretta per i distributori. Inoltre, il divieto è principalmente per quando sono aperti e in funzione. Se sono chiusi, spesso la sosta non è vietata, a meno che non ci siano altri divieti specifici.', 'Le parole ''sino a 5 metri prima e dopo'' e ''anche quando i distributori sono chiusi'' sono le ''parole trappola''. La distanza di 5 metri è usata per altri divieti (es. incroci), non per i distributori, e il divieto non vale sempre quando sono chiusi.', 'Distributore: non 5 metri, e se è chiuso, spesso si può.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23779, 'Questa domanda è l''opposto della 23777. Se il Codice della Strada (la legge) dice chiaramente che non puoi parcheggiare in un certo posto, devi rispettare quel divieto. Non è vero che il divieto vale solo se c''è anche un cartello. La legge è sempre valida, con o senza cartello.', 'La frase ''è comunque condizionata dalla presenza di cartelli segnaletici'' è la ''parola trappola''. Implica che il cartello sia necessario, ma se il divieto è già nel Codice, non lo è.', 'La legge è la legge! Se il Codice vieta, non serve il cartello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23780, 'Sostare negli spazi riservati ai mezzi pubblici (autobus, filobus, tram) è molto pericoloso e impedisce il loro regolare servizio. Per questo, è una violazione grave che comporta la sottrazione di punti dalla patente.', 'La frase ''tra l''altro'' significa che la sottrazione di punti è una delle conseguenze, ma ce ne possono essere anche altre (come una multa).', 'Spazi mezzi pubblici = intoccabili, punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23781, 'Anche se non ci sono linee a terra, la legge stabilisce una distanza minima di 15 metri dal segnale di fermata dell''autobus dove non si può sostare. Questo serve a garantire che l''autobus possa fermarsi e ripartire senza ostacoli. Violando questa regola, si perdono punti.', '''A meno di 15 metri'' indica una distanza critica. ''Qualora gli spazi di fermata non siano delimitati'' significa che la regola vale anche senza strisce sull''asfalto.', '15 metri bus = zona vietata, punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23782, 'Occupare un parcheggio riservato alle persone invalide è una violazione molto grave perché impedisce a chi ha difficoltà di movimento di accedere a servizi essenziali. Per questo, oltre alla multa, si perdono anche punti dalla patente.', 'Anche qui, ''tra l''altro'' indica che la sottrazione di punti è una delle conseguenze, non l''unica.', 'Posti invalidi = mai, punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23783, 'Gli scivoli e i raccordi tra marciapiede e strada sono fondamentali per le persone invalide, ad esempio per chi usa la sedia a rotelle. Bloccarli con la sosta è un impedimento grave e comporta la sottrazione di punti dalla patente.', '''In corrispondenza'' significa proprio nel punto esatto dello scivolo. ''Utilizzati dai veicoli per persone invalide'' specifica l''importanza di questi spazi.', 'Scivoli invalidi = via libera, punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23784, 'Le corsie riservate sono create per permettere ai mezzi pubblici di viaggiare più velocemente e senza ostacoli. Sostare in queste corsie blocca il traffico pubblico e crea pericolo, per questo è una violazione grave con sottrazione di punti.', '''Riservate'' è la parola chiave: significa che sono solo per quei veicoli specifici.', 'Corsie bus = solo bus, punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23785, 'Gli spazi riservati ai mezzi pubblici sono sempre vietati alla sosta per i veicoli privati. Il disco orario serve solo dove la sosta è permessa ma limitata nel tempo, non rende legale una sosta vietata.', 'La trappola è ''è consentita se si utilizza il disco orario''. Il disco orario non annulla i divieti assoluti.', 'Spazi mezzi pubblici = mai, disco orario inutile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23786, 'Le quattro frecce (segnalazione luminosa di pericolo) si usano per segnalare un''emergenza o un pericolo, non per rendere legale una sosta vietata. Sostare vicino alla fermata del bus è sempre vietato, a prescindere dalle frecce.', 'La trappola è ''è consentita azionando la segnalazione luminosa di pericolo''. Le quattro frecce non danno il permesso di sostare dove è vietato.', 'Quattro frecce = emergenza, non permesso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23787, 'Sostare negli spazi riservati alle persone invalide è una violazione molto grave. Comporta sia una multa (sanzione pecuniaria) sia la sottrazione di punti dalla patente. La frase è FALSO perché dice ''ma non la sottrazione di punti''.', 'La trappola è ''ma non la sottrazione di punti''. Invece, i punti vengono tolti eccome!', 'Posti invalidi = multa E punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23788, 'Sostare sugli scivoli per disabili è una violazione grave che comporta la sottrazione di punti e una multa, ma non la sospensione della patente. La sospensione è una sanzione per violazioni ancora più gravi.', 'La trappola è ''comporta la sospensione della patente''. È grave, ma non così grave da sospendere la patente.', 'Scivoli invalidi = punti, non sospensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23789, 'Le corsie riservate ai mezzi pubblici sono tali 24 ore su 24, a meno che non ci sia un segnale specifico che indichi orari diversi. Non è un divieto che vale solo di giorno o in certi orari.', 'La trappola è ''è consentita, nei centri abitati, dalle ore 22.00 alle ore 8.00''. Il divieto è continuo, salvo indicazioni diverse.', 'Corsie bus = sempre vietato, non a orari.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23790, 'La sosta di emergenza avviene quando il tuo veicolo non può più muoversi a causa di un guasto improvviso (avaria). Non puoi continuare a guidare, quindi devi fermarti per forza.', 'La parola chiave è ''avaria''. Significa che il veicolo si è rotto e non funziona più. Questo è un motivo di emergenza.', 'Avaria = Sosta di emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23791, 'Se tu che guidi o un passeggero vi sentite male improvvisamente e non potete continuare il viaggio in sicurezza, dovete fermarvi. Questa è una situazione di emergenza che richiede una sosta.', 'La frase ''malessere fisico'' indica un problema di salute improvviso che rende pericoloso continuare a guidare. È un''emergenza.', 'Malessere = Sosta di emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23792, 'Le ''esigenze della circolazione'' sono le normali situazioni del traffico, come fermarsi al semaforo rosso, in coda o per dare la precedenza. Queste non sono emergenze, ma normali interruzioni della marcia (fermate o arresti).', 'La frase ''esigenze della circolazione'' è una trappola. Non indica un''emergenza, ma le normali condizioni del traffico.', 'Traffico non è emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23793, 'Far scendere una persona, anche se invalida, è una ''fermata''. La fermata è una breve sospensione della marcia per far salire o scendere persone o caricare/scaricare cose. Non è una situazione di emergenza improvvisa.', 'La frase ''temporanea sospensione della marcia per consentire la discesa'' descrive una ''fermata'', non una ''sosta di emergenza''.', 'Scendere/Salire = Fermata, non Emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23794, 'Anche far salire una persona invalida sul veicolo è una ''fermata''. Non è un evento improvviso e inaspettato che ti costringe a fermarti per un pericolo, quindi non è una sosta di emergenza.', 'Come nella domanda precedente, ''temporanea sospensione della marcia per consentire ad una persona invalida di salire'' è la definizione di ''fermata''.', 'Scendere/Salire = Fermata, non Emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23795, 'Quando apri le porte del tuo veicolo, devi sempre fare attenzione a non creare problemi o pericoli per chi sta passando, come altre auto, moto o pedoni. La sicurezza è la cosa più importante.', 'Le parole chiave sono ''pericolo o intralcio''. Significano che non devi bloccare o mettere in pericolo nessuno.', 'Apri la porta? Guarda sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23796, 'Se devi aprire la portiera dal lato della strada (quello dove passano le macchine), è fondamentale guardare bene nello specchietto e girarti per assicurarti che non stia arrivando nessun altro veicolo. È molto pericoloso aprire la porta all''improvviso.', 'Fai attenzione a ''centro della strada'' e ''non sopraggiungano altri veicoli''. Indica il lato più pericoloso e cosa devi controllare.', 'Lato strada: occhio al traffico!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23797, 'Anche se apri la portiera dal lato del marciapiede, devi fare attenzione. Potrebbero esserci pedoni, ciclisti o bambini che passano proprio in quel momento. Non dare per scontato che sia sempre libero.', 'Le parole importanti sono ''lato rivolto verso il marciapiede'' e ''non sopraggiungano pedoni''. Ricorda che anche lì ci sono persone.', 'Lato marciapiede: occhio ai pedoni!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23798, 'Quando scendi dalla macchina, devi fare attenzione a non creare problemi o pericoli per gli altri. Questo include sia l''apertura della porta sia il modo in cui ti muovi subito dopo essere sceso.', 'Anche qui, ''pericolo o intralcio'' sono le parole chiave. Il concetto è lo stesso dell''apertura delle porte: non disturbare o mettere in pericolo nessuno.', 'Scendi? Guarda chi c''è!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23799, 'Prima di scendere dalla macchina, il conducente deve sempre controllare che non stiano arrivando altri veicoli. È utile usare lo specchietto retrovisore per vedere bene cosa succede dietro e di lato alla macchina.', 'La frase ''anche mediante lo specchietto retrovisore'' è importante. Ti ricorda di usare tutti gli strumenti a disposizione per la sicurezza.', 'Scendi? Specchietto prima!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23800, 'Quando parcheggi e scendi dalla macchina, devi sempre spegnere il motore. Lasciare il motore acceso non è permesso, inquina e non è sicuro.', 'La parola ''spento il motore'' è fondamentale. È una regola di base per la sicurezza e l''ambiente.', 'Spegni il motore, poi scendi!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23801, 'Aprire la portiera non è come girare o fermarsi. Non devi mettere la freccia (indicatore di direzione) quando apri la porta, perché potrebbe confondere gli altri utenti della strada. La freccia serve per segnalare un cambio di direzione o una manovra.', 'La parola ''obbligo'' è la trappola. Non c''è nessun obbligo di mettere la freccia per aprire la porta.', 'Porta aperta non è freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23802, 'Non è vero che è sempre vietato aprire la portiera dal lato della strada. A volte è necessario, ad esempio se sei il conducente e sei parcheggiato sul lato destro. L''importante è farlo con estrema attenzione e solo se non c''è nessun pericolo.', 'La parola ''vietato'' è la trappola. Non è un divieto assoluto, ma un obbligo di massima prudenza.', 'Vietato? No, ma con cautela!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23803, 'Non puoi lasciare il motore acceso quando sei in sosta, nemmeno per tenere l''aria condizionata. È una regola per ridurre l''inquinamento e il rumore. Il motore va spento.', 'La frase ''per consentire il funzionamento dell''aria condizionata'' è la giustificazione che rende la domanda falsa. Non è una ragione valida per lasciare il motore acceso.', 'Motore acceso in sosta? No!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23804, 'Il freno a mano deve essere sempre azionato quando parcheggi, sia in salita che in discesa, e anche in piano. Serve a bloccare il veicolo e impedire che si muova da solo. Non è solo per le discese.', 'La parte ''ma non in quelle in salita'' è la trappola. Il freno a mano va messo sempre, in ogni situazione di sosta.', 'Freno a mano? Sempre, ovunque!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23805, 'Se qualcosa cade dal tuo veicolo e blocca la strada, devi cercare di toglierlo, ma solo se puoi farlo in sicurezza e senza rischi. L''obiettivo è liberare la strada per gli altri.', 'La frase chiave è ''se possibile''. Significa che devi agire, ma sempre con prudenza e solo se non ti metti in pericolo.', 'Carico caduto? Rimuovi se puoi, in sicurezza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23806, 'Sulle strade fuori città (extraurbane), se un carico cade e blocca la strada, è obbligatorio usare il triangolo di pericolo per avvisare gli altri automobilisti. Questo è fondamentale per la sicurezza, perché le auto vanno più veloci.', 'Attenzione a ''Su strada extraurbana''. Il triangolo è obbligatorio solo fuori dai centri abitati. In città, bastano le luci di emergenza. ''Segnale di veicolo fermo (triangolo)'' specifica il dispositivo corretto.', 'Extraurbana + ostacolo = Triangolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23807, 'Se un carico cade e blocca la strada, devi fare il possibile per liberare il passaggio il più velocemente possibile. Non devi aspettare, ma agire subito per permettere agli altri veicoli di passare.', 'Le parole ''sollecitamente'' (velocemente) e ''per quanto possibile'' (il più possibile) indicano l''urgenza e la necessità di agire in modo pratico.', 'Carico caduto? Libera subito la strada!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23808, 'Se un carico cade e blocca la strada, non devi usare il segnale di STOP. Il segnale di STOP serve per gli incroci dove devi fermarti. Per segnalare un ostacolo, si usano le luci di emergenza o il triangolo di pericolo (se fuori città).', 'La parola ''STOP'' è la trappola. Non è il segnale giusto per avvisare di un ostacolo sulla carreggiata.', 'Ostacolo = Triangolo/Luci, non STOP!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23809, 'Se un carico cade e blocca la strada, non devi rimanere seduto in macchina ad aspettare i soccorsi. Hai il dovere di agire: provare a rimuovere l''ostacolo (se sicuro), segnalarlo agli altri e rendere la strada il più sicura possibile.', 'La frase ''restare a bordo del veicolo in attesa dei soccorsi'' è la trappola. Implica passività, mentre la legge richiede un''azione immediata.', 'Carico caduto? Agisci, non aspettare in auto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23810, 'Se il tuo veicolo si ferma sulla strada e blocca il passaggio, devi fare subito il possibile per liberare la strada, in modo che le altre auto possano passare. È importante per la sicurezza di tutti.', 'La parola ''sollecitamente'' significa ''subito, velocemente''. Non puoi aspettare, devi agire senza ritardo.', 'Ingombro = Libera subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23811, 'Se la tua auto si rompe e blocca la strada, la prima cosa da fare è cercare di spostarla completamente fuori dalla strada. Se non ci riesci, mettila il più possibile a destra, sul bordo della strada, per lasciare spazio al traffico.', 'La frase ''o, se ciò non è possibile'' indica una priorità: prima cerchi di toglierla del tutto, poi, se non puoi, la metti sul margine destro.', 'Auto rotta? Fuori o a destra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23812, 'Se qualcosa cade dal tuo veicolo e blocca la strada, o se c''è un altro ostacolo che hai causato, devi toglierlo dalla strada se puoi. Questo serve a non creare pericoli per gli altri utenti della strada.', 'La frase ''per quanto possibile'' significa che devi fare il massimo che puoi, ma senza metterti in pericolo. La sicurezza è sempre la priorità.', 'Ostacolo = Rimuovi se puoi!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23813, 'Anche se ci sono poche auto in giro, se il tuo veicolo blocca la strada perché si è rotto, devi comunque cercare di spostarlo. La sicurezza è sempre importante, non solo quando c''è tanto traffico. Non puoi lasciare un veicolo in panne sulla carreggiata.', 'Le parole ''non è tenuto a spostarlo'' e ''se il traffico è scarso'' sono le trappole. La regola è sempre di spostare l''ingombro, indipendentemente dal traffico.', 'Traffico scarso? Sposta lo stesso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23814, 'Se qualcosa cade dal tuo veicolo e blocca la strada, devi toglierlo subito. Non devi lasciarlo lì per far capire cosa è successo, perché creerebbe un pericolo per gli altri. La sicurezza e la fluidità del traffico vengono prima di tutto.', 'La frase ''evitare di spostarlo per consentire la ricostruzione'' è la trappola. La priorità assoluta è sempre la sicurezza e la rimozione dell''ostacolo.', 'Carico caduto? Rimuovi, non aspettare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23816, 'Se c''è un incidente su una strada fuori città e i veicoli danneggiati bloccano la strada senza poter essere spostati, è obbligatorio per il conducente o i passeggeri mettere il segnale triangolare mobile di pericolo per avvisare gli altri. Questo è fondamentale per la sicurezza.', 'La parola chiave è ''devono presegnalare'', che indica un obbligo preciso. Non è una scelta, ma una necessità.', 'Incidente + veicolo fermo = Triangolo OBBLIGATORIO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23817, 'Se il tuo veicolo si rompe e blocca la strada, non è vero che devi solo informare la polizia ''senza dover opportunamente presegnalare la zona''. In realtà, devi SEMPRE presegnalare la zona con il triangolo di pericolo per avvisare gli altri veicoli, oltre a chiamare la polizia se la situazione è grave o il veicolo non può essere spostato.', 'La frase ''senza dover opportunamente presegnalare la zona'' è la parte falsa. L''obbligo di presegnalare c''è sempre quando il veicolo è fermo in modo pericoloso.', 'Avaria + strada bloccata = Triangolo SEMPRE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23818, 'Se il carico cade dal veicolo e non si può rimuovere, bloccando la strada, non basta fare ''efficaci segnali manuali'' per evitare di chiamare la polizia. In questi casi, devi sempre usare il triangolo di pericolo e, se la situazione è pericolosa o il carico non si può togliere, devi anche informare la polizia per gestire il traffico e la rimozione. I segnali manuali non sono sufficienti.', 'La parte ''può evitare di informare un organo di polizia se presegnala la zona con efficaci segnali manuali'' è la trappola. I segnali manuali non sostituiscono l''obbligo di avvisare le autorità in caso di pericolo o ingombro non rimovibile.', 'Carico caduto + non rimovibile = Triangolo + Polizia (se grave). Mai solo segnali manuali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23819, 'Se cadono materie pericolose sulla strada, è tuo dovere segnalare il pericolo. Il segnale mobile di pericolo (il triangolo) serve proprio a questo e va messo dove serve, anche al centro della strada se il pericolo è lì, per avvisare gli altri conducenti.', 'La frase ''anche in mezzo alla carreggiata'' non significa che devi metterlo *solo* lì, ma che è una possibilità se il pericolo si trova in quella posizione e richiede una segnalazione chiara.', 'Pericolo in strada? Triangolo subito, dove serve!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23820, 'Questa domanda è molto simile alla precedente. Su una strada extraurbana, dove le auto vanno più veloci, è ancora più importante segnalare bene un pericolo con il triangolo, anche al centro della strada se necessario, per dare tempo agli altri di reagire.', 'La specificazione ''Su strada extraurbana'' rafforza l''importanza della segnalazione, non la limita. ''anche in mezzo alla carreggiata'' indica una delle possibili posizioni per la massima visibilità del pericolo.', 'Pericolo extraurbano? Segnala bene, anche al centro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23821, 'Se c''è un pericolo e hai messo il triangolo solo da una parte, devi comunque avvisare gli altri veicoli che arrivano dall''altra direzione, magari con gesti delle mani, per la loro sicurezza. Non tutti potrebbero vedere il triangolo subito.', 'La frase ''eseguire segnali manuali'' indica un''azione attiva e necessaria per la sicurezza. ''dalla parte dove non è stato posto il segnale mobile'' chiarisce che i segnali manuali servono a coprire le zone non segnalate dal triangolo.', 'Triangolo da un lato? Segnala a mano dall''altro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23822, 'Non basta solo segnalare il pericolo! Se puoi farlo in sicurezza, devi anche cercare di eliminare il pericolo o renderlo meno grave. Per esempio, se c''è olio, puoi coprirlo con sabbia o segatura per non far scivolare le auto.', 'La condizione ''se possibile'' è fondamentale. Non devi metterti in pericolo, ma se puoi agire per ridurre il rischio, devi farlo. ''rimuoverle o spargere... materiale idoneo'' indica azioni concrete per migliorare la situazione.', 'Segnala e, se puoi, pulisci o copri!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23823, 'Questa affermazione è FALSO. I segnali manuali servono proprio per avvisare dove il triangolo *non c''è* o non è ben visibile, o per rafforzare la segnalazione da ogni lato necessario. Non ha senso farli ''solo dalla parte dove è stato posto il segnale''.', 'La parola trappola è ''solo dalla parte''. Questa parola limita l''azione, mentre la sicurezza richiede di segnalare il pericolo da ogni lato necessario, non solo da uno.', '''Solo'' è quasi sempre FALSO per la sicurezza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23824, 'Questa affermazione è FALSO. Non puoi sostituire il triangolo di pericolo con i segnali sonori (il clacson). Il triangolo è obbligatorio per legge per segnalare un pericolo fermo sulla strada, specialmente di notte o in condizioni di scarsa visibilità. I segnali sonori sono solo un aiuto temporaneo, non un sostituto.', 'Le parole trappola sono ''può evitare di presegnalare... se esegue segnali sonori''. Non si può evitare un obbligo legale (il triangolo) con un''azione alternativa non prevista dal Codice della Strada.', 'Triangolo obbligatorio, il clacson non lo sostituisce!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23825, 'Questa affermazione è FALSO. Non è compito del conducente deviare il traffico. Questo è un compito della polizia o degli addetti alla strada. Tu devi segnalare il pericolo e, se possibile, ridurlo, ma non puoi gestire il traffico.', 'La frase ''deve deviare il traffico'' è la trappola. Deviare il traffico è una responsabilità delle autorità competenti, non del singolo cittadino o conducente.', 'Non sei un vigile! Segnala, non deviare il traffico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23826, 'È VERO. Fuori dai centri abitati, di notte, se le luci posteriori del veicolo non funzionano bene o non ci sono, è obbligatorio usare il triangolo per avvisare gli altri veicoli che c''è un pericolo.', 'La parola ''obbligatorio'' è fondamentale. Significa che non è una scelta, ma un dovere.', 'Notte + Fuori città + Luci rotte = Triangolo OBBLIGATORIO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23827, 'È VERO. Se un carico cade dal veicolo sulla strada, diventa un ostacolo pericoloso. Fuori dai centri abitati e di notte, devi sempre segnalarlo con il triangolo.', 'Anche qui, ''obbligatorio'' è la parola chiave. ''Ogni carico caduto'' significa che qualsiasi cosa cada è un pericolo da segnalare.', 'Carico caduto = Ostacolo. Notte + Fuori città = Triangolo OBBLIGATORIO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23828, 'È VERO. Anche di giorno, se ti trovi fuori dai centri abitati e il tuo veicolo fermo non si vede bene da almeno 100 metri di distanza, devi usare il triangolo per segnalarlo. La visibilità è la chiave.', 'La frase ''quando non può essere visto nettamente a 100 metri di distanza'' è la condizione che rende l''uso del triangolo ''obbligatorio'' anche di giorno.', 'Giorno + Fuori città + Non visibile a 100m = Triangolo OBBLIGATORIO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23829, 'È VERO. Stessa regola del veicolo fermo, ma per un carico caduto. Se fuori dai centri abitati, di giorno, un carico caduto non è visibile da 100 metri, devi usare il triangolo.', 'Ancora una volta, ''obbligatorio'' e la condizione ''quando l''ingombro non può essere visto nettamente a 100 metri di distanza'' sono le parole da non sottovalutare.', 'Carico caduto + Giorno + Fuori città + Non visibile a 100m = Triangolo OBBLIGATORIO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23830, 'È VERO. Il triangolo mobile di pericolo è un oggetto che devi sempre avere in macchina, fa parte dell''equipaggiamento obbligatorio di tutti gli autoveicoli.', 'La parola ''obbligatorio'' indica che è un oggetto che devi per forza avere a bordo del tuo veicolo.', 'Triangolo = Equipaggiamento OBBLIGATORIO in auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23831, 'È VERO. Quando usi il triangolo, devi metterlo sulla strada, dietro al veicolo o all''ostacolo che vuoi segnalare, a una distanza di almeno 50 metri.', 'Le parole ''dietro'' e ''almeno 50 metri'' sono cruciali per capire il posizionamento corretto.', 'Triangolo = 50 metri DIETRO l''ostacolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23832, 'È VERO. Se dietro al tuo veicolo c''è un incrocio a meno di 50 metri, non puoi mettere il triangolo a 50 metri. In questo caso speciale, lo metti dove si vede meglio, per garantire la massima visibilità.', 'La condizione ''Nel caso di intersezione a distanza inferiore a 50 metri'' è l''eccezione alla regola dei 50 metri. ''Posizione più idonea ad essere avvistato'' significa dove è più visibile.', 'Intersezione vicina (<50m) = Triangolo dove si vede MEGLIO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23833, 'È VERO. Il triangolo non solo deve essere a 50 metri dall''ostacolo, ma deve anche essere posizionato in modo che chi arriva con un altro veicolo lo possa vedere da almeno 100 metri di distanza.', 'La frase ''visibile ad una distanza di almeno 100 metri'' si riferisce alla visibilità del triangolo stesso, non alla sua distanza dall''ostacolo.', 'Triangolo = Visibile a 100 metri (per chi arriva).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23834, 'È FALSO. In quella situazione (fuori dai centri abitati, di notte, luci insufficienti), l''uso del triangolo non è solo ''consigliabile'', ma ''obbligatorio'' per legge. Non è una scelta.', 'La parola ''consigliabile'' è la trappola. La legge dice che è ''obbligatorio''.', 'Triangolo = OBBLIGATORIO, non solo ''consigliabile''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23835, 'È FALSO. La distanza di visibilità per cui è obbligatorio usare il triangolo (quando non è già obbligatorio per altre ragioni) è di 100 metri, non 150 metri. I 150 metri sono una distanza sbagliata.', 'Il numero ''150 metri'' è la trappola. La distanza corretta è 100 metri.', 'Visibilità per l''uso = 100 metri, non 150.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23836, 'È FALSO. Se un carico cade fuori dai centri abitati e non si vede bene da 100 metri, non è ''facoltativo'' (cioè a tua scelta) segnalarlo. È ''obbligatorio'' per la sicurezza.', 'La parola ''facoltativo'' è la trappola. La legge impone che sia ''obbligatorio''.', 'Non visibile a 100m = OBBLIGATORIO, non ''facoltativo''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23837, 'È FALSO. La regola del triangolo per luci insufficienti si applica ''fuori'' dai centri abitati. Nei centri abitati, di solito, c''è l''illuminazione pubblica che rende il triangolo non necessario.', 'La frase ''anche nei centri abitati'' è la trappola. Il triangolo non si usa dentro la città, dove ci sono i lampioni.', 'Triangolo = FUORI città. Dentro città = NO (di solito).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23838, 'È FALSO. Come per la domanda precedente, il triangolo non è obbligatorio nei centri abitati. Inoltre, per veicoli piccoli come biciclette, ciclomotori e motocicli, spesso si possono spostare o segnalare in altri modi, e il triangolo non è richiesto.', 'La frase ''anche nei centri abitati'' è la trappola principale. Inoltre, ''velocipedi, ciclomotori e motocicli'' sono veicoli che spesso non richiedono il triangolo.', 'Triangolo = FUORI città. Per mezzi piccoli = Spesso non serve o si sposta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23839, 'È FALSO. Il triangolo deve essere messo sulla carreggiata, ''dietro'' al carico caduto, per avvisare chi arriva. Non si mette ''sul'' carico, altrimenti non sarebbe visibile in tempo.', 'La parola ''sul carico'' è la trappola. Deve essere ''dietro'' al carico, sulla strada.', 'Triangolo = DIETRO l''ostacolo, non SOPRA.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23840, 'È FALSO. Il triangolo deve essere posizionato a ''almeno 50 metri'' dall''ostacolo, ma deve essere ''visibile'' da almeno ''100 metri'' per chi arriva. La domanda confonde le due distanze.', 'La frase ''visibile ad una distanza di almeno 50 metri'' è la trappola. La visibilità richiesta è di 100 metri.', 'Triangolo = Visibile a 100 metri (non 50). Posizionato a 50 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23841, 'Il segnale mobile triangolare di pericolo serve per avvisare gli altri guidatori che c''è un pericolo. Per questo, deve essere messo proprio dove si trova il problema, cioè sulla stessa corsia dove il veicolo è fermo o dove è caduto qualcosa. Così, chi arriva vede subito il pericolo.', 'La frase chiave è ''sulla corsia occupata''. Significa esattamente dove c''è il problema, non altrove.', 'Triangolo = dove c''è il pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23842, 'È importante che il triangolo sia ben visibile e non troppo vicino al bordo della strada, dove potrebbe essere difficile da vedere o finire fuori. Per questo, la legge dice che deve stare ad almeno un metro dal bordo esterno della carreggiata. Così è più sicuro e visibile per tutti.', 'La parte importante è ''ad almeno un metro dal bordo esterno''. Questo è un dettaglio specifico da ricordare.', '1 metro dal bordo per sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23843, 'Se ci sono più corsie, il triangolo deve essere messo sulla corsia dove si trova il veicolo fermo o il carico caduto. Metterlo sulla corsia a sinistra non servirebbe a molto per chi arriva sulla corsia del pericolo e potrebbe confondere gli altri guidatori.', 'La parola ''immediatamente a sinistra'' è la trappola. Il triangolo va sulla corsia del pericolo, non su quella accanto.', 'Triangolo = sulla corsia del problema, non a lato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23844, 'La regola di ''almeno un metro'' si riferisce al bordo esterno della strada, non alla linea che separa i due sensi di marcia (la striscia centrale). Il triangolo deve avvisare chi arriva nella stessa direzione del pericolo, quindi la distanza dal bordo esterno è quella che conta per la visibilità.', 'La frase ''dalla striscia di separazione dei sensi di marcia'' è la trappola. La distanza di un metro si misura dal ''bordo esterno'' della carreggiata.', '1 metro dal bordo, non dalla linea centrale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23845, 'Quando devi mettere il triangolo di pericolo (segnale mobile) perché la tua auto è ferma, devi essere ben visibile per la tua sicurezza e quella degli altri. Il giubbotto o le bretelle retroriflettenti ti rendono visibile, specialmente al buio o in condizioni di scarsa visibilità.', 'La frase ''deve rendersi visibile'' indica un obbligo chiaro per la sicurezza del conducente e degli altri utenti della strada.', 'Triangolo = Giubbotto obbligatorio per la tua sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23846, 'Non basta un giubbotto qualsiasi. Per garantire la massima sicurezza e visibilità, il giubbotto o le bretelle devono essere di un tipo speciale, che rispetta precise norme di sicurezza e riflette bene la luce. Questo tipo è chiamato ''approvato''.', 'La parola ''approvato'' è importante: significa che il giubbotto deve avere una certificazione specifica per essere efficace e legale.', 'Giubbotto = Approvato per massima sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23847, 'Anche se ti trovi in un''area che sembra più sicura, come la corsia di emergenza o una piazzola di sosta, c''è sempre il rischio di essere investiti da altri veicoli. Per questo motivo, il giubbotto è sempre obbligatorio in queste situazioni quando scendi dal veicolo.', 'La frase ''anche se si trova'' sottolinea che l''obbligo vale sempre, non ci sono eccezioni in queste situazioni che potrebbero sembrare meno pericolose.', 'Emergenza/Sosta = Giubbotto SEMPRE obbligatorio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23848, 'È proprio vietato scendere dall''auto e camminare sulla strada per mettere il triangolo senza indossare il giubbotto. È una regola di sicurezza fondamentale per evitare incidenti, perché senza il giubbotto saresti poco visibile e in grave pericolo.', 'La costruzione ''è vietato... senza indossare'' rafforza l''obbligo: non puoi fare quella cosa se non indossi il giubbotto.', 'Scendi dall''auto = Metti il giubbotto, è un divieto non farlo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23849, 'L''uso del giubbotto non è una scelta personale, ma un obbligo di legge per la tua sicurezza e quella degli altri. ''Facoltativo'' significa che puoi scegliere, ma in questo caso non è così: devi indossarlo per forza.', 'La parola ''facoltativo'' è la trappola. Ricorda che l''uso del giubbotto è obbligatorio, non a scelta.', 'Giubbotto = MAI facoltativo, è un obbligo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23850, 'Questa domanda è l''opposto della 23847. Come abbiamo già detto, anche in corsia di emergenza o in una piazzola di sosta, il giubbotto è obbligatorio per la tua sicurezza quando scendi dal veicolo. Non ci sono eccezioni in queste aree.', 'La negazione ''non deve indossare'' rende la frase falsa. L''obbligo c''è sempre, anche in queste aree.', 'Emergenza/Sosta = Giubbotto SEMPRE (ricorda la domanda 23847).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23851, 'L''obbligo di indossare il giubbotto ad alta visibilità vale solo fuori dai centri abitati (sulle strade extraurbane e in autostrada). Nei centri abitati, anche di notte e in caso di guasto, non è obbligatorio indossarlo se scendi dal veicolo.', 'La frase ''anche nei centri abitati'' è la parte trappola. L''obbligo del giubbotto non si estende ai centri abitati.', 'Giubbotto in città = NO obbligo. Solo fuori città e autostrade.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23852, 'Sulle autostrade e sulle strade extraurbane principali, che sono fatte per veicoli veloci e sicuri, è vietato far circolare biciclette (velocipedi), ciclomotori e motocicli con una cilindrata inferiore a 150 cm³. Questi veicoli sono considerati troppo lenti o meno stabili per la velocità e il traffico di queste strade.', 'Le parole chiave sono ''velocipedi, ciclomotori, motocicli di cilindrata inferiore a 150 cm3''. Indicano tutti veicoli che, per le loro caratteristiche, non sono adatti a circolare su autostrade e strade extraurbane principali.', 'Autostrada = solo veicoli veloci e potenti. Bici, ciclomotori e moto piccole = no.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23853, 'Per poter circolare in autostrada o su strade extraurbane principali, un''autovettura deve essere in grado di raggiungere una velocità di almeno 80 km/h. Se un''auto è costruita per essere più lenta di così, non può entrare in queste strade.', 'La frase ''per costruzione'' significa che è una caratteristica originale del veicolo, non un problema temporaneo. ''almeno 80 km/h'' è la velocità minima richiesta.', 'Auto in autostrada: minimo 80 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23854, 'Le macchine agricole, come i trattori, sono veicoli lenti e spesso ingombranti. Per questo motivo, non possono circolare sulle autostrade e sulle strade extraurbane principali, dove il traffico è veloce e intenso.', 'La parola ''macchine agricole'' identifica una categoria di veicoli che è sempre esclusa da queste strade.', 'Trattori e simili = vietati in autostrada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23855, 'È molto pericoloso circolare con un carico che non è ben sistemato, non è fissato saldamente o sporge troppo. Questo perché il carico potrebbe cadere, spostarsi e causare incidenti. Per la sicurezza di tutti, è vietato.', 'Le espressioni ''disordinato e non solidamente assicurato'' e ''sporgente oltre i limiti consentiti'' descrivono un carico che rappresenta un pericolo.', 'Carico instabile o sporgente = pericolo = vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23856, 'Se un veicolo non è ''a tenuta stagna'' (cioè perde liquidi) o ha un carico scoperto che può disperdersi (come sabbia, ghiaia, ecc.), è vietato circolare in autostrada. Questo perché i materiali dispersi possono sporcare la strada, renderla scivolosa e causare incidenti.', 'Le parole ''a tenuta non stagna'', ''carico scoperto'' e ''materiali che possono disperdersi'' indicano tutte situazioni di rischio per la sicurezza stradale.', 'Niente perdite o dispersioni in autostrada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23857, 'Un veicolo deve essere in perfette condizioni per circolare in autostrada. Se le sue condizioni generali, l''equipaggiamento (ad esempio, luci non funzionanti) o le gomme sono usurati e possono creare un pericolo, la circolazione è vietata.', 'La frase ''possono costituire pericolo per la circolazione'' è la chiave. Qualsiasi difetto che rende il veicolo insicuro lo esclude dall''autostrada.', 'Veicolo insicuro = vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23858, 'Gli autobus, inclusi quelli usati per il trasporto di studenti, possono circolare sulle autostrade e sulle strade extraurbane principali. Non c''è un divieto specifico per loro, purché rispettino le norme di sicurezza e velocità.', 'La frase ''autobus per trasporto di studenti'' non identifica una categoria di veicoli vietata. Gli autobus sono generalmente ammessi.', 'Autobus (anche scolastici) = ammessi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23859, 'Non è solo ''consigliabile evitare'' di circolare con veicoli che perdono materiali o con carico scoperto che può disperdersi; è proprio ''vietato'' dalla legge. Queste situazioni sono considerate molto pericolose e non una semplice scelta.', 'La parola ''consigliabile'' è la trappola. In questi casi, la legge non dà un consiglio, ma impone un divieto.', 'Pericolo = divieto, non consiglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23860, 'I veicoli che trasportano animali vivi possono circolare sulle autostrade e sulle strade extraurbane principali. Devono ovviamente rispettare le norme specifiche per il benessere degli animali e la sicurezza del trasporto, ma non c''è un divieto generale.', 'La frase ''veicoli che trasportano animali vivi'' non indica una categoria di veicoli esclusa dall''autostrada.', 'Trasporto animali = ammesso (con regole).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23861, 'I ciclomotori sono sempre vietati in autostrada e sulle strade extraurbane principali, indipendentemente dalla loro velocità massima. Anche se un ciclomotore potesse raggiungere i 50 km/h, non sarebbe comunque ammesso.', 'La parola ''ciclomotori'' è la chiave: sono sempre esclusi. La velocità di ''almeno 50 km/h'' è un tentativo di confondere, perché la velocità minima per le auto è 80 km/h, ma per i ciclomotori il divieto è assoluto.', 'Ciclomotori = mai in autostrada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23862, 'Le macchine agricole sono sempre vietate in autostrada e sulle strade extraurbane principali. Non importa se trainano un rimorchio o meno; sono considerate troppo lente e ingombranti per queste strade.', 'La frase ''macchine agricole'' indica una categoria di veicoli sempre esclusa. La condizione ''non trainanti un rimorchio'' è un dettaglio che non cambia il divieto generale.', 'Macchine agricole = mai in autostrada (con o senza rimorchio).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23863, 'Tutti i veicoli che circolano su strada devono essere muniti di pneumatici in buone condizioni. Un veicolo senza pneumatici (ad esempio, con cingoli o ruote metalliche) non può circolare in autostrada, anche se ha l''assicurazione. L''assicurazione è obbligatoria, ma non rende un veicolo idoneo alla circolazione se non ha le caratteristiche tecniche necessarie.', 'La frase ''non muniti di pneumatici'' è la condizione che rende il veicolo non idoneo. ''se assicurati'' è una condizione necessaria per circolare in generale, ma non sufficiente a rendere un veicolo senza pneumatici adatto all''autostrada.', 'Senza pneumatici = vietato. Assicurazione = obbligatoria, ma non basta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23864, 'Sulle autostrade e sulle strade extraurbane principali, i pedoni e gli animali non possono camminare. L''unica eccezione a questa regola sono le aree di servizio e le aree di sosta, dove è permesso.', 'La frase ''ad eccezione delle'' è importante. Significa che c''è una regola generale (vietato) ma anche un''eccezione (permesso in queste aree).', 'Autostrada: no pedoni/animali, tranne aree di servizio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23865, 'Nelle aree di servizio e di sosta, gli animali possono circolare, ma devono essere tenuti al guinzaglio o in un trasportino. Non possono essere lasciati liberi.', 'La condizione ''solo se debitamente custoditi'' è fondamentale. Non è un permesso totale, ma con una precisa condizione.', 'Aree di servizio: animali sì, ma al guinzaglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23866, 'La corsia di emergenza è per le vere emergenze. Un pedone può usarla solo se ha bisogno di aiuto e deve raggiungere una colonnina SOS per chiedere soccorso. Non può usarla per passeggiare o per altri motivi.', 'La parola ''solo'' limita molto l''uso. Indica che non ci sono altre ragioni per cui un pedone può stare lì.', 'Corsia emergenza: pedone solo per SOS.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23867, 'Se un veicolo si rompe in autostrada, non puoi trainarlo tu con la tua auto. Solo i mezzi speciali di soccorso, come i carri attrezzi, possono farlo. Questo è per la sicurezza di tutti.', 'La frase ''solo ai veicoli di soccorso autorizzati'' è una restrizione importante. Non è permesso il traino ''fai da te''.', 'Traino in autostrada: solo carro attrezzi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23868, 'Questa domanda è falsa perché contraddice la regola. Pedoni e animali sono vietati in autostrada, ma c''è un''eccezione: nelle aree di servizio e di sosta sono permessi. Dire ''anche nelle aree di servizio'' significa che sono vietati anche lì, il che è sbagliato.', 'La parola ''anche'' è la trappola. Se fosse vero, significherebbe che non possono circolare nemmeno nelle aree di servizio, ma sappiamo che lì è permesso (con regole per gli animali).', 'Aree di servizio: pedoni/animali SÌ (con regole).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23869, 'Questa domanda è falsa. Nelle aree di servizio e di sosta, gli animali possono circolare, ma devono essere tenuti al guinzaglio o in un trasportino. Dire che ''non possono circolare neppure se custoditi'' è sbagliato.', 'La frase ''non possono circolare neppure se debitamente custoditi'' è la trappola. La parola ''neppure'' nega completamente la possibilità, rendendo la frase falsa.', 'Aree di servizio: animali custoditi SÌ.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23870, 'In autostrada, per la sicurezza di tutti, non si possono chiedere o dare passaggi. Questo vale ovunque: sulla strada, sulle rampe, negli svincoli e anche nelle aree di servizio o parcheggio. È una regola molto importante per evitare pericoli.', 'La parola chiave è ''vietato'', che significa ''non si può fare'', ''è proibito''. Non ci sono eccezioni.', 'Autostrada = No passaggi, mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23871, 'Nelle aree di servizio o parcheggio in autostrada, puoi vendere cose o fare altre attività commerciali solo se hai un permesso speciale da chi gestisce l''autostrada. Non puoi farlo liberamente, serve sempre un''autorizzazione.', 'La frase ''solo se autorizzate'' è fondamentale. Indica una condizione necessaria: senza autorizzazione, l''attività è vietata.', 'Attività commerciali in autostrada? Solo con permesso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23872, 'In autostrada, di solito non si può campeggiare. Ma se ci sono delle aree speciali, fatte apposta per il campeggio, e solo per il tempo permesso da chi gestisce l''autostrada, allora è possibile. È una situazione molto specifica e controllata.', 'Le parole ''solo nelle aree a ciò destinate e per il periodo stabilito'' sono cruciali. Senza queste condizioni specifiche, il campeggio sarebbe vietato.', 'Campeggio in autostrada? Solo in aree dedicate e con limiti di tempo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23873, 'Nelle aree di servizio in autostrada, non puoi lasciare la tua auto parcheggiata per più di un giorno (24 ore). Dopo 24 ore, devi spostarla per permettere ad altri di usare lo spazio.', 'La frase ''non deve lasciare... per più di 24 ore'' indica il limite massimo di tempo consentito per la sosta.', 'Sosta in autostrada: max 24 ore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23874, 'In autostrada, non si possono dare passaggi a nessuno, nemmeno a persone invalide. La regola è chiara e vale per tutti, senza eccezioni, per garantire la sicurezza.', 'La trappola è ''persone invalide''. Non c''è nessuna eccezione per loro. Il divieto di concedere passaggi in autostrada è generale.', 'Autostrada = No passaggi, per nessuno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23875, 'Anche nelle aree di servizio o di parcheggio in autostrada, non è permesso chiedere o dare passaggi. Il divieto vale per tutta l''autostrada e le sue pertinenze, incluse queste aree.', 'La parola ''consentito'' è la trappola. In realtà, chiedere e concedere passaggi è vietato in tutte le pertinenze autostradali.', 'Aree di servizio = No passaggi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23876, 'Di solito, non si può campeggiare nelle aree di servizio o parcheggio delle autostrade e delle strade extraurbane principali. Il campeggio libero è vietato per motivi di sicurezza e regolamento, a meno di aree specifiche e autorizzate (ma la domanda non lo specifica).', 'La frase ''è consentito campeggiare'' è la trappola. Di norma non è consentito, a meno di condizioni molto specifiche (aree dedicate e autorizzate) che non sono menzionate in questa affermazione generale.', 'Campeggio in autostrada/extraurbana principale? No, salvo aree dedicate.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23877, 'La durata massima per la sosta nelle aree di servizio e parcheggio delle autostrade non è di tre ore, ma di 24 ore. Ricorda bene questo limite di tempo.', 'Il numero ''tre ore'' è la trappola. Il limite corretto per la sosta è di 24 ore.', 'Sosta in autostrada: 24 ore, non 3.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23878, 'Sulle autostrade e sulle strade extraurbane principali, è sempre necessario accendere i fari anabbaglianti, anche quando c''è il sole e si vede bene. Questo serve per essere più visibili agli altri veicoli e aumentare la sicurezza.', 'La parola chiave è ''obbligatorio''. Significa che non è una scelta, ma una regola da seguire sempre. ''Anche di giorno'' sottolinea che la regola vale sempre, non solo di notte o con brutto tempo.', 'Autostrada/Extraurbana principale = Anabbaglianti SEMPRE, giorno e notte!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23879, 'Questa affermazione è falsa. Come abbiamo visto, sulle autostrade e sulle strade extraurbane principali l''uso degli anabbaglianti è sempre obbligatorio, non è mai una scelta. Non importa se la visibilità è perfetta, i fari devono essere accesi.', 'La parola ''facoltativo'' è la trappola. Significa ''a scelta'', ma in questo caso non è così. ''In condizioni di perfetta visibilità'' è un tentativo di farti credere che non servano, ma la regola non cambia.', 'Su autostrada/extraurbana principale, gli anabbaglianti NON sono MAI facoltativi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23880, 'In autostrada e sulle strade extraurbane principali, è estremamente pericoloso e quindi vietato cambiare direzione (invertire il senso di marcia) o attraversare la barriera centrale (spartitraffico). Questo divieto vale sempre, anche dove ci sono delle aperture (varchi), perché queste sono riservate solo ai mezzi di soccorso o di servizio, non agli automobilisti comuni.', 'La frase ''anche all''altezza dei varchi'' è una trappola. Può far pensare che in quei punti sia permesso, ma non è così per il traffico normale.', 'Autostrada = mai inversione o spartitraffico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23881, 'Andare contromano (nel senso di marcia opposto) in autostrada o su strade extraurbane principali è una delle azioni più pericolose che si possano fare. È severamente vietato perché causa incidenti frontali gravissimi.', 'Il concetto di ''senso di marcia opposto'' è chiaro, ma è fondamentale capire la gravità del divieto.', 'Autostrada = mai contromano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23882, 'Fare retromarcia in autostrada o su strade extraurbane principali è vietato. Le auto viaggiano a velocità elevate e una retromarcia improvvisa può causare incidenti molto gravi.', 'Non ci sono parole trappola evidenti; il divieto è diretto e assoluto.', 'Autostrada = mai retromarcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23883, 'La corsia di emergenza è fatta apposta per le situazioni di urgenza. Se il tuo veicolo ha un guasto (avaria) e non puoi più guidare, puoi usarla per fermarti in sicurezza e chiedere aiuto.', 'La parola ''circolare'' può ingannare. Non significa guidare normalmente, ma usarla per raggiungere un punto di sosta in caso di vera emergenza, come specificato da ''per arrestarsi per avaria del veicolo''.', 'Corsia emergenza = solo per vera emergenza (es. avaria).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23884, 'Anche se ti trovi sulla corsia di emergenza, non puoi fare retromarcia. È comunque una parte della strada dove le auto viaggiano ad alta velocità e fare retromarcia è sempre pericoloso.', 'Non ci sono parole trappola particolari; è una specificazione del divieto generale di retromarcia.', 'Anche in emergenza, mai retromarcia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23885, 'È FALSO. Non importa quanto tu sia attento o quanti ''accorgimenti'' tu prenda, invertire il senso di marcia in autostrada è sempre vietato e pericolosissimo. Non ci sono eccezioni per i normali automobilisti.', 'La frase ''adottando tutti gli accorgimenti necessari'' è una trappola. Vuole farti credere che con cautela sia permesso, ma non lo è mai.', 'Autostrada = mai inversione, punto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23886, 'È FALSO. Anche in una situazione di ''particolare emergenza'', non puoi invertire il senso di marcia in autostrada. È troppo pericoloso. Devi cercare un''area di sosta o aspettare i soccorsi, ma mai invertire la marcia.', 'La frase ''in casi di particolare emergenza'' è la trappola. Fa pensare che ci sia un''eccezione, ma per l''inversione di marcia in autostrada non è così.', 'Autostrada = mai inversione, nemmeno per emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23887, 'È FALSO. Andare contromano, anche per un ''breve tratto'', è estremamente pericoloso e severamente vietato in autostrada. Non si può fare in nessun caso, nemmeno per pochi metri.', 'La frase ''per brevi tratti'' è la trappola. Suggerisce che per poco tempo sia accettabile, ma non lo è mai.', 'Autostrada = mai contromano, nemmeno per poco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23888, 'È FALSO. La corsia di emergenza non serve per superare il traffico o per andare più veloci quando c''è coda. Serve solo per vere emergenze, come un guasto al veicolo, un malore o per soccorrere qualcuno. Usarla per il traffico intenso è vietato e pericoloso.', 'La frase ''se il traffico è intenso'' è la trappola. Molti pensano di poterla usare per evitare la coda, ma è severamente vietato e sanzionato.', 'Corsia emergenza = solo per vera emergenza, non per traffico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23889, 'Quando entri in autostrada o su una strada extraurbana principale usando la corsia di accelerazione, devi sempre dare la precedenza ai veicoli che sono già sulla strada principale. Questo è fondamentale per la sicurezza e per non creare pericoli.', 'La frase chiave è ''deve dare la precedenza''. ''Deve'' indica un obbligo, non una scelta.', 'Accelerazione = Precedenza sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23890, 'Per uscire correttamente dall''autostrada o da una strada extraurbana principale, devi spostarti per tempo nella corsia di destra e poi entrare nella corsia di decelerazione fin dal suo inizio. Questo ti permette di rallentare in sicurezza senza intralciare il traffico sulla carreggiata principale.', 'Le parole ''per tempo'' e ''dal suo inizio'' sono importanti. Indicano che l''azione deve essere fatta con anticipo e correttamente.', 'Uscita = Decelerazione dal suo inizio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23891, 'Sulle autostrade e sulle strade extraurbane principali, è obbligatorio segnalare ogni cambio di corsia usando gli indicatori di direzione (le frecce). Questo serve a informare gli altri conducenti delle tue intenzioni e a prevenire incidenti.', 'La parola ''tempestivamente'' significa ''in tempo utile'', cioè abbastanza presto da dare agli altri il tempo di reagire. ''Deve segnalare'' indica un obbligo.', 'Cambio corsia = Freccia sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23892, 'In caso di ingorgo, se la corsia di emergenza non c''è o non basta, bisogna creare un ''corridoio di emergenza'' per i veicoli di soccorso. La regola generale è che i veicoli nella corsia più a destra si spostano il più possibile a destra, mentre quelli nelle altre corsie si spostano il più possibile a sinistra. La domanda, sebbene formulata in modo un po'' complesso (''striscia di sinistra''), intende che il veicolo nella corsia più a destra deve posizionarsi in modo da lasciare il massimo spazio possibile sulla destra per il passaggio dei mezzi di soccorso, anche spostandosi leggermente a sinistra all''interno della propria corsia per massimizzare lo spazio a destra.', 'La frase ''striscia di sinistra'' è la parte più ''trappola''. Non significa andare a sinistra della strada, ma posizionarsi verso il bordo sinistro della propria corsia per creare spazio sul lato destro della stessa, in modo che il corridoio si formi tra le corsie.', 'Ingorgo = Corridoio salva-vita. Spostati per far passare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23893, 'Normalmente non si può usare la corsia di emergenza. Tuttavia, in caso di ingorgo, puoi usarla per uscire dall''autostrada, ma solo a partire dal cartello che preavvisa l''uscita, che si trova a 500 metri dallo svincolo. Questo evita di bloccare le corsie di marcia mentre aspetti di uscire.', 'Le parole ''solo per uscire'' e ''a partire dal cartello di preavviso di uscita posto a 500 metri'' sono cruciali. Indicano una limitazione molto precisa.', 'Emergenza = Solo per Uscita (da 500m).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23894, 'Per uscire in sicurezza dall''autostrada o da una strada extraurbana principale, devi entrare nella corsia di decelerazione fin dal suo inizio. Entrare più avanti, nel ''tratto successivo'', è pericoloso perché ti costringe a rallentare bruscamente sulla carreggiata principale, creando un rischio per gli altri veicoli.', 'La frase ''anche nel tratto successivo al suo inizio'' è la trappola. È FALSO perché devi entrare SEMPRE dal suo inizio.', 'Decelerazione = Dal suo Inizio (sempre!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23895, 'È sempre obbligatorio usare gli indicatori di direzione (le frecce) quando cambi corsia, sia che il traffico sia intenso o meno. È una regola di base per la sicurezza, per comunicare le tue intenzioni agli altri conducenti.', 'Le frasi ''se il traffico non è intenso'' e ''non ha l''obbligo'' sono le trappole. L''obbligo c''è sempre, indipendentemente dal traffico.', 'Freccia = Sempre Obbligatoria.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23896, 'La marcia per file parallele (guidare affiancati su più corsie) è consentita solo in caso di traffico intenso o in situazioni specifiche (come agli incroci). Sulle autostrade e sulle strade extraurbane principali, in assenza di traffico, devi tenere la corsia più a destra e usare le altre solo per sorpassare.', 'La frase ''anche in assenza di traffico'' è la trappola. È FALSO, perché è consentita solo in presenza di traffico intenso.', 'File parallele = Solo con traffico intenso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23897, 'Sulle autostrade, puoi fermarti (sostare) solo se c''è un''emergenza vera e propria. Questo include se tu o un passeggero vi sentite male, oppure se la macchina ha un problema e non funziona bene. Non puoi fermarti per altri motivi.', 'La parola chiave è ''solo''. Significa che non ci sono altre eccezioni, solo queste situazioni di emergenza.', 'Autostrada: sosta SOLO per emergenza (malore o guasto).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23898, 'Se un passeggero si sente male mentre siete in autostrada, è permesso fermarsi. Devi usare la corsia speciale che si chiama ''corsia per la sosta di emergenza''.', 'Attenzione a ''corsia per la sosta di emergenza'': non puoi fermarti in mezzo alla carreggiata, ma solo lì.', 'Malessere passeggero = Sosta in corsia emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23899, 'Questa domanda è molto simile alla precedente. Se un passeggero non sta bene mentre guidi in autostrada, puoi fermarti sulla corsia di emergenza. È una situazione di emergenza valida.', 'Anche qui, ''corsia per la sosta di emergenza'' è importante. Non è un posto qualsiasi.', 'Malessere = Sosta in corsia emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23900, 'Quando ti fermi per emergenza in autostrada, non puoi stare lì per troppo tempo. Devi stare solo il tempo necessario per risolvere il problema e, in ogni caso, non puoi stare più di tre ore.', 'Le parole ''non deve superare il tempo strettamente necessario'' e ''non deve protrarsi comunque oltre tre ore'' sono fondamentali. Indicano un limite massimo.', 'Sosta emergenza = Max 3 ore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23901, 'Questa affermazione è falsa perché, come abbiamo visto, se un passeggero si sente male, è permesso fermarsi sulla corsia di emergenza. Non è vietato.', 'La parola ''vietato'' rende l''affermazione falsa. In caso di malessere, è consentito fermarsi.', 'Malessere = NON vietato fermarsi (in emergenza).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23903, 'Questa affermazione è falsa. La sosta di emergenza non può durare fino a 24 ore. Il limite massimo è di tre ore, come abbiamo imparato prima.', 'La frase ''può protrarsi fino a 24 ore'' è la parte sbagliata. Ricorda il limite di tempo corretto.', 'Sosta emergenza = NON 24 ore (ma 3).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23904, 'In autostrada, la corsia di emergenza serve solo per vere emergenze e per il tempo strettamente necessario. Fermarsi per dare un passaggio è vietato perché è molto pericoloso e non è una situazione di emergenza che giustifichi la sosta.', 'La parola ''vietato'' è importante. Significa che non si può fare, è contro la legge.', 'Autostrada: corsia d''emergenza = solo per vera emergenza, mai per passaggi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23905, 'Non è un tuo obbligo accompagnare un automobilista in avaria. In autostrada, la cosa giusta da fare è segnalare l''emergenza (ad esempio, chiamando il soccorso stradale o il 112), non fermarsi o accompagnare qualcuno, perché è molto pericoloso.', 'La frase ''lo deve accompagnare'' è la trappola. ''Deve'' indica un obbligo, ma in questo caso non c''è nessun obbligo di accompagnare.', 'Autostrada: non sei un taxi, segnala l''emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23906, 'In autostrada è molto pericoloso fermarsi per prestare soccorso. La velocità dei veicoli è alta e fermarsi può causare incidenti. La regola è non fermarsi, ma segnalare l''emergenza alle autorità competenti (polizia, soccorso stradale).', 'La frase ''si deve fermare a prestare soccorso'' è la trappola. ''Deve'' è la parola chiave: non è un obbligo fermarsi in autostrada, anzi è vietato e pericoloso.', 'Autostrada: non fermarti, segnala e continua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23907, 'In autostrada è assolutamente vietato fare retromarcia o tornare indietro, anche se con prudenza. È una manovra estremamente pericolosa che può causare incidenti gravissimi.', 'La frase ''può retrocedere con prudenza'' è la trappola. ''Retrocedere'' (fare retromarcia) è sempre vietato in autostrada, la prudenza non cambia la regola.', 'Autostrada: mai retromarcia, mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23908, 'In autostrada è vietato trainare un altro veicolo con la tua auto. Solo i mezzi di soccorso stradale autorizzati possono farlo. Trainare un veicolo in autostrada è molto pericoloso e non è permesso.', 'La frase ''può trainare prudentemente'' è la trappola. ''Può trainare'' è il punto: non è permesso trainare veicoli in autostrada con la propria auto, anche se con prudenza.', 'Autostrada: no traino fai-da-te, solo soccorso autorizzato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23909, 'È VERO. Per la sicurezza di tutti, i passeggeri devono sedersi in modo da non disturbare il conducente e da non coprire la sua visuale della strada. Immagina se un passeggero ti coprisse lo specchietto retrovisore!', 'La frase chiave è ''non limitare la libertà del conducente e da non impedirgli la visibilità''. Questo è un principio fondamentale di sicurezza.', 'Passeggero = mai d''intralcio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23910, 'È VERO. Ogni veicolo ha un documento chiamato ''carta di circolazione'' (o libretto) dove sono scritte tutte le informazioni importanti, incluso il numero massimo di persone che possono viaggiare legalmente in quell''auto.', 'Non ci sono vere e proprie parole trappola qui, ma è importante sapere che la ''carta di circolazione'' è il documento ufficiale dove trovare queste informazioni.', 'Posti = libretto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23911, 'È VERO. Puoi portare il tuo animale domestico in auto, ma deve essere sistemato in modo sicuro. Non deve poterti distrarre o creare pericoli durante la guida, ad esempio saltando sul cruscotto o tra i sedili.', 'La parte importante è ''comunque in condizione da non costituire impedimento o pericolo per la guida''. Questa è la condizione essenziale.', 'Animale OK, se sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23912, 'È VERO. Se hai più di un animale domestico, puoi trasportarli, ma devono essere ben protetti. Questo significa metterli in una gabbia apposita o nel bagagliaio, separato dall''abitacolo con una rete speciale. Questo evita che si muovano liberamente e ti distraggano.', 'Le parole chiave sono ''anche in numero superiore ad uno'' e le condizioni ''custoditi in gabbia o nel vano posteriore, appositamente diviso da rete''. Queste sono le uniche modalità sicure per più animali.', 'Più animali = gabbia o rete.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23913, 'È FALSO. Il numero di persone indicato sulla carta di circolazione include SEMPRE il conducente. Se sul libretto c''è scritto ''5 posti'', significa che possono viaggiare 4 passeggeri + il conducente.', 'La parola trappola è ''non comprende il conducente''. Ricorda che il conducente è sempre contato nel numero totale di posti.', 'Posti = conducente INCLUSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23914, 'È FALSO. Le autovetture (le normali auto che guidiamo) possono trasportare al massimo 9 persone (8 passeggeri + il conducente). Dieci persone sono troppe per un''autovettura standard.', 'La parola trappola è ''dieci''. Il numero massimo per le autovetture è 9.', 'Auto = max 9 persone.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23915, 'È FALSO. Trasportare più cani solo con il guinzaglio non è sufficiente per garantire la sicurezza. I cani, anche se al guinzaglio, potrebbero comunque muoversi, abbaiare, o saltare, distraendo il conducente. Devono essere in gabbia o separati da una rete, come visto nella domanda 23912.', 'La frase trappola è ''adeguatamente trattenuti al guinzaglio''. Per più cani, il guinzaglio da solo non è considerato ''adeguato'' per la sicurezza in auto.', 'Guinzaglio NON basta per più cani.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23917, 'La legge italiana stabilisce che non si possono trasportare bambini sui motocicli se hanno meno di 5 anni. Questa regola serve per la loro sicurezza, perché prima di quell''età non sono abbastanza grandi per viaggiare in moto in modo sicuro.', 'La parola ''vietato'' significa che è proibito, non si può fare. È una regola chiara e senza eccezioni per i minori di 5 anni.', 'Bambini < 5 anni = NO moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23918, 'Un motociclo non può né tirare un altro veicolo (trainare) né farsi tirare da un altro veicolo (farsi trainare). È una manovra molto pericolosa per la stabilità del motociclo e per la sicurezza stradale in generale.', 'Le parole ''trainare e farsi trainare'' indicano due azioni diverse ma entrambe proibite. Non si può fare nessuna delle due.', 'Moto = MAI traino (attivo o passivo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23919, 'Quando trasporti oggetti sul motociclo, devono essere legati molto bene, in modo ''solido''. Se non sono ben assicurati, possono cadere, spostarsi e causare pericoli per te e per gli altri utenti della strada.', 'La frase ''che non siano solidamente assicurati'' significa ''se non sono legati bene''. La doppia negazione può confondere, ma il senso è che devono essere ben fissati.', 'Oggetti in moto = SEMPRE legati bene.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23920, 'È vietato trasportare oggetti che ti impediscono di vedere bene la strada, gli specchietti o i segnali. La tua visibilità è fondamentale per guidare in sicurezza e reagire in tempo a eventuali pericoli.', 'Le parole ''impediscano o limitino la visibilità'' sono chiare: qualsiasi cosa che ti ostacoli la vista è proibita.', 'Visibilità = MAI ostacolata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23921, 'Non è vero che il passeggero deve essere maggiorenne. L''unica condizione di età è che il passeggero abbia almeno 5 anni (come visto nella domanda 23917). Non c''è un limite di età massima o l''obbligo di essere maggiorenne.', 'La parola ''solo'' è una trappola. Suggerisce che l''età adulta sia l''unica condizione, ma non è così. C''è solo un limite minimo di età (5 anni).', 'Passeggero moto = NO limite età massima, SÌ limite minimo (5 anni).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23922, 'Come già detto nella domanda 23918, è sempre vietato farsi trainare con un motociclo, da qualsiasi tipo di veicolo, non solo dalle autovetture. È una manovra pericolosa e non consentita dal Codice della Strada.', 'La parola ''consentito'' è l''opposto di ''vietato'' e cerca di ingannarti. La specificazione ''ma solo da autovetture'' è un ulteriore tentativo di confondere, perché il divieto è generale.', 'Moto = MAI trainata, da NESSUNO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23923, 'Questa affermazione è falsa perché non è vietato in assoluto che gli oggetti sporgano longitudinalmente (cioè in avanti o indietro). Ci sono dei limiti precisi: possono sporgere fino a 50 cm dietro la sagoma del veicolo, ma non possono sporgere in avanti.', 'La parola ''vietato'' in questo contesto è una trappola perché generalizza. Non è vietato del tutto, ma solo oltre certi limiti. Bisogna conoscere i limiti specifici di sporgenza.', 'Oggetti moto = SÌ sporgenza longitudinale (con limiti).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23924, 'È fondamentale che il carico sia ben fissato per evitare che cada o si sparga sulla strada. Questo è importante per la sicurezza di tutti, perché un oggetto caduto può causare incidenti.', 'Non ci sono parole trappola particolari. ''Evitarne'' significa ''evitare che cada o si disperda''.', 'Carico sicuro = strada pulita.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23925, 'Il conducente deve sempre avere una buona visuale della strada e poter muovere liberamente le braccia e le gambe per guidare in sicurezza. Il carico non deve mai ostacolare queste azioni.', '''Né impedirgli'' significa ''e non impedirgli''.', 'Guida libera, vista chiara.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23926, 'Un carico posizionato male o troppo pesante da un lato può rendere il veicolo instabile, facendolo sbandare o addirittura ribaltare. È essenziale che il veicolo mantenga la sua stabilità.', '''Compromettere'' significa ''mettere a rischio, rovinare''.', 'Stabilità è sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23927, 'Le luci, le frecce, la targa e i segnali fatti con il braccio sono essenziali per comunicare con gli altri utenti della strada. Il carico non deve mai coprirli, né di giorno né di notte.', '''Mascherare'' significa ''coprire''. ''Né'' significa ''e neanche''.', 'Tutto visibile, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23928, 'Questa affermazione è FALSA. Il carico deve essere sempre sistemato in modo sicuro per evitare cadute o dispersioni, non solo sulle strade extraurbane. La sicurezza vale su ogni tipo di strada: in città, fuori città, in autostrada.', 'La parola trappola è ''solo se''. Questa espressione limita l''obbligo a una sola situazione, rendendo l''affermazione falsa. L''obbligo è generale.', 'Carico sicuro SEMPRE, non ''solo se''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23929, 'Questa affermazione è FALSA. Le luci e i segnali devono essere sempre visibili, sia di giorno che di notte. È importante che gli altri vedano le tue intenzioni in ogni momento, non ''soltanto'' quando è buio.', 'La parola trappola è ''soltanto''. Questa espressione limita l''obbligo a una sola condizione (la notte), ma l''obbligo è valido 24 ore su 24.', 'Luci visibili SEMPRE, non ''soltanto'' di notte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23930, 'Ogni veicolo ha una dimensione massima (chiamata ''sagoma''). Il carico che trasporti non può essere più grande di questa dimensione, a meno di eccezioni molto specifiche e ben segnalate. Quindi, in generale, il carico deve stare dentro i limiti del veicolo.', 'La frase ''non deve superare'' indica un limite chiaro e obbligatorio. ''Limite di sagoma'' è la dimensione massima consentita per il veicolo.', 'Sagoma = Limite massimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23931, 'Il carico non può mai uscire dalla parte anteriore (davanti) del veicolo. Questo è molto importante per la sicurezza, per non ostacolare la vista del conducente e per non creare pericoli in caso di frenata o incidente.', '''non può sporgere longitudinalmente dalla parte anteriore'' significa che non può uscire in avanti. Il ''non può'' rende la regola assoluta.', 'Davanti = Mai sporgere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23932, 'Se il carico è una cosa che non si può dividere (ad esempio, un palo molto lungo), può sporgere dalla parte posteriore (dietro) del veicolo. Però c''è un limite: non più di 3 decimi (3/10) della lunghezza totale del veicolo. E, attenzione, deve essere sempre segnalato con l''apposito pannello!', 'Le parole chiave sono ''se costituito da cose indivisibili'' (è una condizione necessaria) e ''fino ai 3/10 della lunghezza'' (è il limite massimo).', 'Dietro = 3/10 (se indivisibile e segnalato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23933, 'Il carico può sporgere un po'' di lato, ma non più di 30 centimetri dalle luci di posizione che si trovano ai lati del veicolo. L''importante è che la larghezza totale del veicolo con il carico non superi comunque i limiti massimi di larghezza stabiliti dalla legge per quel tipo di veicolo.', '''non più di 30 centimetri dalle luci di posizione'' è il limite specifico. ''comunque entro i limiti massimi di sagoma'' ricorda che c''è un limite generale di larghezza da rispettare.', 'Lato = 30 cm dalle luci (ma rispetta la larghezza massima).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23934, 'È assolutamente vietato trasportare o trascinare cose che toccano e strisciano sul terreno. Questo vale anche se queste cose hanno delle ruote che le aiutano un po''. Strisciare sul terreno può rovinare la strada e creare pericoli.', '''vietato'' è la parola chiave che indica un divieto assoluto. ''anche se in parte sostenute da ruote'' chiarisce che non ci sono eccezioni per questo tipo di trasporto.', 'Strisciare = Sempre vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23935, 'Se il carico sporge dal veicolo (nei limiti consentiti dalla legge), tu che guidi devi fare molta attenzione. Devi prendere tutte le precauzioni necessarie per non mettere in pericolo gli altri utenti della strada, ad esempio segnalando bene la sporgenza.', '''deve adottare tutte le cautele idonee'' significa che il conducente ha la responsabilità di prevenire ogni pericolo.', 'Sporgenza = Massima attenzione e cautela.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23936, 'Questa affermazione è FALSO perché la sporgenza posteriore del carico deve essere segnalata con un pannello specifico, che è quadrato, a strisce bianche e rosse. La frase ''in figura'' è la trappola: se la figura non mostra il pannello corretto (o se non c''è una figura), l''affermazione è sbagliata. Non si usa ''un'' generico pannello retroriflettente, ma ''il'' pannello specifico.', 'La trappola è ''con il pannello retroriflettente in figura''. Se la figura non è quella del pannello a strisce bianche e rosse, la frase è FALSO. Il pannello deve essere quello regolamentare.', 'Pannello = Quello specifico (bianco/rosso), non ''uno qualsiasi in figura''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23937, 'Questa affermazione è FALSO. La sporgenza laterale del carico è permessa solo entro i 30 cm dalle luci di posizione e comunque entro i limiti massimi di larghezza del veicolo. La regola dei ''3/10'' si applica solo alla sporgenza posteriore (della lunghezza del veicolo), non a quella laterale (della larghezza).', 'La trappola è ''fino ai 3/10 della larghezza del veicolo''. Questo limite è sbagliato per la sporgenza laterale. I 3/10 sono per la sporgenza posteriore (della lunghezza).', '3/10 = Solo dietro (lunghezza), non di lato (larghezza).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23938, 'Questa affermazione è FALSO. È l''opposto di quanto abbiamo visto prima. Non è mai consentito trasportare o trainare cose che strisciano sul terreno, nemmeno se hanno delle ruote che le sostengono in parte. È un divieto assoluto per la sicurezza e per non danneggiare la strada.', '''E'' consentito'' è la parola trappola, perché in realtà è vietato. ''se in parte sostenute da ruote'' cerca di farti pensare che ci sia un''eccezione, ma non è così.', 'Strisciare = Sempre vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23939, 'Se il carico sporge dietro il veicolo, anche se non molto (fino a 3/10 della lunghezza totale del veicolo), è obbligatorio segnalarlo con questo pannello. Si usa uno o due pannelli a seconda di come sporge il carico.', 'La frase ''fino ai 3/10 della lunghezza del veicolo'' indica il limite massimo di sporgenza consentita per legge.', 'Carico sporgente dietro? Pannello sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23940, 'Non importa quanto poco il carico sporga dietro, deve sempre essere segnalato con il pannello. È una questione di sicurezza per gli altri utenti della strada, per rendere il carico ben visibile.', 'Le espressioni ''in ogni caso'' e ''anche se di poco'' sottolineano che la segnalazione è sempre obbligatoria, senza eccezioni per la quantità di sporgenza.', 'Sporge? Segnala! (Sempre)')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23941, 'Questo pannello serve proprio a segnalare i carichi che non possono essere divisi (indivisibili) e che escono dalla parte posteriore del veicolo, rendendoli più visibili e sicuri per tutti.', 'La parola ''indivisibili'' specifica il tipo di carico per cui si usa questo pannello, cioè carichi che non possono essere ridotti per rientrare nei limiti del veicolo.', 'Carico indivisibile dietro? Pannello visibile!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23942, 'Se il carico che sporge dietro è molto largo, cioè occupa tutta la larghezza del veicolo, per essere ben visibile da tutti i lati, si usano due pannelli. Vanno messi ai lati esterni del carico, uno per ogni estremità.', 'Le frasi ''intera larghezza della parte posteriore del veicolo'' e ''due, posti trasversalmente alle due estremità del carico'' sono dettagli importanti che specificano quando e come usare due pannelli.', 'Carico largo dietro? Due pannelli ai lati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23943, 'Anche se il pannello nell''immagine è quadrangolare, la legge specifica che i pannelli per segnalare i carichi sporgenti devono essere ''quadrangolari''. Se la domanda non include questa parola, potrebbe essere considerata incompleta o non abbastanza precisa rispetto alla norma.', 'L''assenza della parola ''quadrangolari'' rende la frase meno precisa rispetto a quanto richiesto dalla legge. La legge è molto specifica nei termini che usa.', 'La legge vuole precisione: ''pannelli quadrangolari''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23944, 'Questo pannello segnala carichi che sporgono dalla parte posteriore in generale, non solo dalla parte destra. Serve per rendere visibile il carico che esce dal veicolo, indipendentemente dal lato (destro, sinistro o centrale).', 'La specificazione ''solo dalla parte posteriore destra'' è la trappola. Il pannello è per la sporgenza posteriore in generale, non per un lato specifico.', 'Sporgenza dietro? Non importa il lato, il pannello c''è!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23945, 'È vero che se il carico è molto largo e sporge, si usano due pannelli, e questi pannelli sono retroriflettenti. Però, la domanda non dice dove devono essere messi i due pannelli. Devono essere posizionati ''alle due estremità del carico'' per segnalare bene la larghezza. Senza questa informazione, la frase è incompleta e quindi Falsa.', 'L''omissione della frase ''posti trasversalmente alle due estremità del carico'' è la trappola. La posizione dei pannelli è fondamentale per la sicurezza e la visibilità.', 'Due pannelli? Sì, ma la posizione conta! (Alle estremità)')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23946, 'VERO. Il pannello arancione con i numeri, come quello in figura, è un segnale internazionale che indica che il veicolo sta trasportando merci considerate pericolose (ad esempio benzina, gas infiammabili, ecc.). È retroriflettente per essere ben visibile anche di notte.', 'L''espressione ''segnala veicoli che stanno trasportando merci pericolose'' descrive esattamente la funzione principale di questo pannello.', 'Pannello arancione con numeri = Merci Pericolose.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23947, 'VERO. Questo pannello, essendo di colore arancione vivo e retroriflettente, aiuta a rendere il veicolo più visibile, specialmente in condizioni di scarsa luce o di notte. Questo è particolarmente utile per veicoli grandi come gli autocarri che trasportano merci pericolose.', 'L''espressione ''facilita l''individuazione'' è corretta, perché la sua natura retroriflettente e il colore lo rendono più visibile, anche se la sua funzione primaria è segnalare il tipo di carico.', 'Arancione e retroriflettente = Più visibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23948, 'VERO. Attenzione, la domanda è un po'' ingannevole per il colore! Il pannello *in figura* è arancione e indica merci pericolose. Tuttavia, esistono altri pannelli, di colore giallo (spesso con bordi o strisce rosse), che vengono applicati posteriormente ai rimorchi per segnalare la presenza di un autotreno o un autoarticolato, rendendoli più visibili. La domanda fa riferimento a questa funzione dei pannelli gialli, anche se il pannello mostrato non è giallo.', 'La parola trappola è ''giallo in figura''. Il pannello mostrato è arancione. I pannelli che individuano autotreni/autoarticolati sono gialli e rossi, ma non sono quello in figura.', 'Pannello arancione = Merci pericolose. Pannello giallo/rosso = Autotreno/Autoarticolato. Non confondere i colori!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23949, 'FALSO. Il pannello arancione con i numeri serve per segnalare il trasporto di *merci pericolose* (come benzina o gas). Per segnalare i *carichi sporgenti* (cioè che escono dal veicolo), si usa un pannello quadrato a strisce bianche e rosse.', 'La frase ''carichi sporgenti pericolosi'' è la trappola. Il pannello è per le *merci* pericolose, non per i *carichi sporgenti* in generale.', 'Arancione = Merci pericolose. Bianco/Rosso = Carico sporgente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23950, 'FALSO. I pannelli come quello in figura sono applicati sui veicoli che trasportano merci pericolose. Non vengono mai posizionati sulla strada (carreggiata) per segnalare ostacoli. Per gli ostacoli sulla strada si usano altri segnali, come il triangolo di pericolo o i coni.', 'La frase ''posti sulla carreggiata'' è la trappola. Questi pannelli sono sempre sui veicoli, non a terra sulla strada.', 'Pannello ADR = Sul veicolo. Ostacolo = Sulla strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23951, 'FALSO. Il pannello arancione con i numeri è obbligatorio solo per i veicoli che trasportano *merci pericolose*. Gli autobus, anche se di grandi dimensioni, non trasportano merci pericolose in questo senso, quindi non devono avere questo tipo di pannello.', 'La frase ''autobus di massa totale superiore a 3,5 tonnellate'' è la trappola. Il criterio per questo pannello non è il tipo o la massa del veicolo, ma il tipo di carico (merci pericolose).', 'Pannello ADR = Solo per merci pericolose.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23952, 'La regola generale è che un veicolo può trainare o essere trainato da un solo altro veicolo alla volta. Non si possono formare ''trenini'' di veicoli, a meno che non si tratti di trasporti eccezionali che hanno permessi speciali.', 'La frase ''Nessun veicolo può trainare o essere trainato da più di un veicolo'' stabilisce la regola. La parte tra parentesi ''(salvo il caso di trasporti eccezionali)'' indica un''eccezione, ma la regola generale rimane valida.', 'Un veicolo alla volta, come un ''treno'' normale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23953, 'Se un veicolo si rompe (avaria) o gli mancano parti essenziali per poter circolare, un altro autoveicolo può trainarlo per spostarlo dalla strada. Questo è un traino di emergenza.', 'La frase ''che non sia un rimorchio'' specifica che si parla di un altro tipo di veicolo (es. un''auto). ''per avaria o per mancanza di organi essenziali'' sono le condizioni che permettono il traino di emergenza.', 'Traino d''emergenza solo per veicoli rotti o incompleti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23954, 'Quando si traina un veicolo in emergenza, il collegamento tra i due veicoli deve essere forte e sicuro (solido), come una fune o una barra. È anche obbligatorio che questo collegamento sia ben visibile agli altri utenti della strada, per esempio con un panno rosso.', '''solido collegamento'' è fondamentale per la sicurezza. ''purché idoneamente segnalati'' significa che deve essere ben visibile.', 'Collegamento forte e ben visibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23955, 'Questa domanda ribadisce che il traino di emergenza di un veicolo in panne deve essere fatto con un collegamento robusto e che sia i veicoli che il collegamento devono essere segnalati bene, in modo che tutti li possano vedere chiaramente.', '''incombente situazione di emergenza'' sottolinea l''urgenza. ''chiaramente avvistabili'' rafforza l''importanza della visibilità.', 'Traino d''emergenza: forte e visibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23956, 'Se non si usa un collegamento forte e sicuro per trainare un veicolo in emergenza, si commette un''infrazione. La conseguenza è una multa e la perdita di 2 punti dalla patente, perché è una situazione pericolosa.', '''senza rispettare le prescrizioni relative alla solidità del collegamento'' indica la violazione. ''sottrazione di 2 punti'' è la sanzione specifica.', 'Collegamento non solido = -2 punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23957, 'In autostrada, il traino di veicoli in avaria non è permesso, se non per spostarli immediatamente sulla corsia di emergenza o in un''area di sosta vicina. Non si può trainare un veicolo per un lungo tratto in autostrada; per questo ci sono i carri attrezzi.', '''In autostrada'' è la parola chiave. Le regole sono molto più severe in autostrada. ''per qualsiasi grave motivo'' è troppo generico e non giustifica il traino in autostrada.', 'In autostrada, no traino (solo carro attrezzi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23958, 'È fondamentale che il collegamento per il traino sia solido E che sia anche segnalato. Non si può trainare un veicolo se il collegamento non è visibile, perché sarebbe troppo pericoloso per gli altri utenti della strada.', '''anche se non è possibile segnalarlo'' è la parte che rende la frase falsa. La segnalazione è sempre obbligatoria.', 'Solido E segnalato, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23959, 'Il veicolo trainato, se in avaria, potrebbe non avere le luci funzionanti. La segnalazione principale per il veicolo trainato è il pannello quadrato con strisce rosse e bianche (o il triangolo mobile di pericolo). Le luci posteriori, se funzionanti, vanno accese, ma non sono l''unica o la principale segnalazione in caso di avaria.', '''deve mantenere accese le luci posteriori in mancanza di altra idonea segnalazione'' è il punto critico. Le luci potrebbero non funzionare e la segnalazione principale è il pannello o il triangolo.', 'Trainato: pannello/triangolo, non solo luci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23960, 'Questa domanda è una ''trappola'' sul numero di punti. La sanzione per non aver rispettato la solidità del collegamento durante un traino di emergenza è la sottrazione di 2 punti dalla patente, non 4.', '''4 punti dalla patente'' è il numero sbagliato. La sanzione corretta è 2 punti.', 'Traino non solido = -2 punti (non 4!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23961, 'È VERO. Le biciclette (velocipedi) sono veicoli leggeri e lenti. Possono anche oscillare, cioè muoversi un po'' a destra e sinistra. Per questo, chi guida un''auto deve stare attento e considerare questi rischi, perché i ciclisti sono più vulnerabili.', 'Non ci sono parole trappola evidenti. La descrizione delle caratteristiche dei velocipedi è corretta e porta a una maggiore prudenza.', 'Bici = leggera, lenta, instabile. Attenzione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23962, 'È VERO. Tutti i conducenti, sia di auto che di moto, devono guidare in modo più attento quando ci sono biciclette nel traffico. Questo perché i ciclisti sono più esposti e meno protetti.', 'Non ci sono parole trappola. ''Adattare la propria guida'' significa proprio essere più prudenti e flessibili.', 'Bici in strada? Guida con più attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23963, 'È VERO. I ciclisti molto giovani o inesperti, così come gli anziani, possono avere reazioni più lente o fare errori. Per questo, chi guida un''auto deve essere ancora più prudente e prevedere possibili comportamenti inattesi.', '''Particolare attenzione'' è la chiave. Indica la necessità di una prudenza extra per queste categorie di ciclisti.', 'Giovani/Anziani in bici = massima attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23964, 'È VERO. Per un ciclista, specialmente quando deve fare una manovra (come girare), è difficile capire quanto velocemente si sta avvicinando un''auto. Questo perché la percezione della velocità è diversa e il ciclista è più lento.', '''Molto difficile valutare'' è il punto cruciale. Sottolinea una reale difficoltà per il ciclista.', 'Ciclista fatica a stimare velocità auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23965, 'È VERO. Se un ciclista sta per girare a sinistra, deve attraversare la corsia. Chi guida l''auto deve immaginare che il ciclista potrebbe non aver calcolato bene la velocità dell''auto. Quindi, è necessario rallentare e dare spazio.', '''Prevedere la difficoltà di valutazione'' significa che il conducente deve anticipare il possibile errore del ciclista.', 'Ciclista gira a sinistra? Rallenta, potrebbe sbagliare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23966, 'È VERO. Un ciclista anziano potrebbe avere difficoltà a girare il busto per guardare dietro di sé. Questo significa che potrebbe non vedere un veicolo che si avvicina. Il conducente deve essere molto prudente e considerare questa limitazione.', '''Particolare prudenza'' e ''difficoltà e lentezza'' sono le parole chiave che indicano la necessità di maggiore cautela.', 'Anziano in bici non vede bene dietro? Massima prudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23967, 'È FALSO. La presenza di bambini in bicicletta, anche se lenti, rappresenta sempre un rischio, soprattutto fuori città dove le auto vanno più veloci. I bambini sono imprevedibili e possono cambiare direzione o cadere all''improvviso. La loro bassa velocità non elimina il pericolo.', '''Non rappresenta un rischio'' è la frase trappola. I bambini sono sempre un rischio. Anche ''data la loro modesta velocità'' è fuorviante, perché la bassa velocità non elimina l''imprevedibilità.', 'Bambini in bici = sempre rischio, velocità non conta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23968, 'È FALSO. I ciclisti non possono viaggiare ''in tutta sicurezza'' nel traffico extraurbano. Nessun conducente può ''sempre'' prevedere ogni caduta o sbandamento di un ciclista, specialmente a causa di buche o irregolarità della strada. I ciclisti sono molto vulnerabili.', '''In tutta sicurezza'' e ''sono sempre capaci di prevedere'' sono le parole trappola. ''Sempre'' è quasi sempre un indicatore di affermazione falsa nei quiz di guida, perché è impossibile prevedere tutto.', '''Sempre'' è quasi sempre FALSO. Non si può prevedere tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23969, 'È FALSO. Questa affermazione contraddice quanto detto in altre domande vere. È difficile per un ciclista valutare la velocità di un''auto, specialmente fuori città dove le velocità sono maggiori. Un ciclista lento ha ancora più difficoltà a reagire o a giudicare correttamente.', '''Facilmente valutabile'' è la frase trappola. È l''opposto della realtà per un ciclista.', 'Ciclista lento + auto veloce = difficile valutare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23970, 'È vero. I ciclomotoristi, specialmente i più giovani, possono avere meno esperienza alla guida. Per questo, un conducente di autovettura deve essere sempre molto attento e considerare che potrebbero fare errori o manovre inaspettate.', 'La frase ''costantemente ricordare'' sottolinea l''importanza di mantenere sempre alta l''attenzione. ''Limitata esperienza di guida a causa della giovane età'' è un fattore di rischio reale da non sottovalutare.', 'Giovani in motorino = meno esperienza, più attenzione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23971, 'È vero. Svoltare a sinistra è una manovra rischiosa per tutti, ma ancora di più per un ciclomotore. Deve attraversare la strada dove arrivano veicoli più grandi e veloci, ed è meno visibile, aumentando il pericolo di incidenti.', '''Particolarmente pericolosa'' evidenzia il rischio elevato. ''Interferire con la traiettoria'' significa che il ciclomotore incrocia il percorso di altri veicoli, creando un punto di conflitto.', 'Svolta a sinistra in motorino? Attenzione doppia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23972, 'È vero. Se un ciclomotorista sta per svoltare, potrebbe rallentare o cambiare direzione. Tu, alla guida di un''auto, devi calcolare bene la distanza per non essere troppo vicino e avere il tempo di reagire in sicurezza, in base alla tua velocità.', '''Valutare con prudenza'' significa non sottovalutare la situazione e fare attenzione. ''In relazione alla propria velocità'' ricorda che la distanza di sicurezza dipende anche da quanto vai veloce.', 'Motorino svolta? Calcola bene la distanza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23973, 'È vero. Un buon conducente deve sempre prevedere che gli altri utenti della strada, specialmente i ciclomotoristi che sono meno stabili, possano fare manovre improvvise o inaspettate, come procedere a zig-zag. Essere pronti a reagire è fondamentale per la sicurezza.', '''Prevedere manovre improvvise altrui'' è un principio chiave della guida preventiva. ''A zig-zag'' è un esempio di comportamento imprevedibile che può mettere in pericolo.', 'Prevedi l''imprevisto, anche il motorino a zig-zag!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23974, 'È vero. Quando superi un ciclista o un ciclomotorista, devi lasciare una distanza di sicurezza non solo davanti, ma anche lateralmente. L''aria spostata dal tuo veicolo o la semplice vicinanza possono fargli perdere l''equilibrio e cadere.', '''Distanza di sicurezza laterale'' è la chiave: non basta la distanza frontale. ''Metterne a repentaglio l''equilibrio'' significa metterli in pericolo di cadere.', 'Distanza laterale: salva l''equilibrio di bici e motorini!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23975, 'È vero. Anche un piccolo spostamento laterale del tuo veicolo (una ''deviazione trasversale'') può essere molto pericoloso per ciclisti e ciclomotoristi. Sono meno stabili e un movimento improvviso della tua auto può farli cadere a terra.', '''Deviazioni trasversali, anche modeste'' sottolinea che anche piccoli movimenti possono essere pericolosi. ''Evitarne la possibile caduta a terra'' è l''obiettivo principale.', 'Non sbandare, anche poco: bici e motorini cadono!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23976, 'È falso. Un buon conducente non deve solo rispettare le regole, ma anche prevedere le possibili imprudenze o errori degli altri, specialmente di chi è più vulnerabile come i ciclomotoristi. La guida sicura significa essere sempre pronti a reagire a situazioni inaspettate.', 'La frase ''ma non è tenuto a prevedere'' è la parte che rende la risposta falsa. Un conducente responsabile DEVE prevedere le possibili imprudenze altrui.', 'Prevedi sempre l''imprudenza altrui, è guida sicura!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23977, 'È falso. Se un ciclomotorista rallenta all''improvviso e la strada non è ben segnalata, è molto difficile per te, alla guida di un''auto, capire subito cosa farà e calcolare la distanza necessaria. È una situazione complessa e potenzialmente pericolosa, non facile da gestire.', 'La parola ''facile'' è la trappola. In situazioni con rallentamenti bruschi e segnaletica scarsa, valutare la distanza non è mai facile, ma richiede molta attenzione e prudenza.', 'Rallentamento brusco + strada non segnalata = MAI facile!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23978, 'È falso. Anche se rispetti i limiti di velocità, non puoi superare un ciclomotorista se non c''è abbastanza spazio laterale. La distanza di sicurezza laterale è fondamentale per la sua incolumità e per evitare di metterlo in pericolo, indipendentemente dalla tua velocità.', 'La frase ''nonostante la scarsa distanza di sicurezza laterale'' rende la risposta falsa. La distanza laterale deve essere sempre adeguata, non scarsa. ''Velocità sostenuta'' anche se nei limiti, non giustifica la mancanza di distanza laterale.', 'Superi un motorino? Distanza laterale SEMPRE ampia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23979, 'È vero. Quando guidi un''auto, devi sempre fare attenzione ai veicoli che vanno molto più lentamente di te, specialmente fuori città. Questi veicoli, come i ciclomotori a tre ruote, possono creare situazioni inaspettate e devi essere pronto a reagire.', 'La frase ''deve conoscere i rischi'' significa che è un tuo dovere sapere che ci sono pericoli. ''Soprattutto su strade extraurbane'' evidenzia che il rischio è maggiore dove le velocità sono più alte.', 'Veicoli lenti = Attenzione doppia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23980, 'È vero. Se la tua auto va veloce e incontri un ciclomotore a tre ruote che va molto più piano, c''è un grande rischio. Se il ciclomotore fa una mossa improvvisa, tu hai poco tempo per reagire e questo può causare un incidente.', '''Velocità sostenuta'' indica che la tua auto va abbastanza veloce. ''Potenziale pericolo'' significa che c''è la possibilità di un pericolo. ''Manovre improvvise'' sono azioni fatte senza preavviso, molto pericolose.', 'Grande differenza di velocità + mosse improvvise = Pericolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23981, 'È vero. Quando guidi la tua auto a velocità normale su una strada fuori città, è difficile capire bene quanto velocemente si muove un veicolo molto lento, come un trattore. Questo può farti sbagliare a calcolare la distanza o il tempo per superarlo.', '''Difficoltosa la valutazione'' significa che è difficile giudicare o calcolare. ''In genere, procede lentamente'' conferma che questi veicoli sono sempre lenti, rendendo il giudizio più complicato.', 'Lento vs. Veloce = Difficile da valutare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23982, 'È falso. Avere veicoli con velocità molto diverse sulla stessa strada, specialmente fuori città, non è un fattore di sicurezza, ma un fattore di rischio! Aumenta la possibilità di incidenti perché ci sono più situazioni pericolose (sorpassi, frenate improvvise, ecc.).', 'La parola ''sicurezza'' è la trappola. La presenza di veicoli con velocità molto diverse tra loro crea insicurezza, non sicurezza.', 'Velocità diverse = Meno sicurezza, più rischio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23983, 'È falso. Non è facile, ma difficile! Se la tua auto va veloce e ti avvicini a un veicolo molto lento, è complicato calcolare bene quanto tempo ci metterai ad raggiungerlo. La grande differenza di velocità inganna l''occhio e rende il calcolo difficile.', 'La frase ''Risulta facile la valutazione'' è la trappola. In realtà, è proprio il contrario: è difficile valutare i tempi di avvicinamento in queste condizioni.', 'Veicolo lento + tua velocità alta = Difficile calcolare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23984, 'Quando due veicoli con pesi (masse) molto diversi si scontrano, il veicolo più leggero subisce danni maggiori e il rischio di lesioni è più alto. Per questo, la collisione è più pericolosa.', 'La frase chiave è ''masse molto diverse''. Indica una grande differenza di peso, che aumenta il pericolo.', 'Grande vs. Piccolo = Pericolo maggiore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23985, 'Se guidi un''auto piccola, devi essere consapevole che in caso di incidente con un''auto più grande e pesante, i rischi per te e per la tua auto sono maggiori. Per questo è importante guidare con più attenzione.', 'Le parole ''maggiori rischi'' e ''massa superiore'' sono importanti. Significano che c''è più pericolo se l''altro veicolo è più pesante.', 'Piccolo + Grande = Attenzione doppia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23986, 'Un''auto pesante è più sicura per chi la guida in caso di incidente, ma non rende più sicuri gli altri veicoli più piccoli. Anzi, in uno scontro, un''auto pesante può causare danni maggiori a un veicolo leggero.', 'La parola ''garanzia'' è la trappola. Un''auto pesante non ''garantisce'' la sicurezza degli altri veicoli, anzi, può aumentare il loro rischio.', 'La tua sicurezza non è la sicurezza degli altri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23987, 'Questa affermazione è falsa perché è il contrario. I veicoli sono più sicuri quando le loro masse (pesi) sono simili. Se le masse sono molto diverse, come un camion e una piccola auto, l''incidente è molto più pericoloso.', 'La frase ''tanto più sicuri... quanto più le loro masse sono differenziate'' è la trappola. ''Differenziate'' qui significa molto diverse, e questo rende gli incidenti più pericolosi, non più sicuri.', 'Masse diverse = Meno sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23988, 'Grandi differenze tra le auto (come una molto veloce e una molto lenta, o una molto pesante e una molto leggera) rendono la strada meno sicura, non più sicura. Queste differenze possono creare situazioni pericolose nel traffico e in caso di incidente.', 'La parola ''facilitano'' è la trappola. Grandi differenze non ''facilitano'' la sicurezza, ma la rendono più difficile.', 'Differenze estreme = Meno sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23989, 'È vero che il conducente di un SUV deve guidare con molta attenzione. I SUV sono veicoli grandi e pesanti, e questo li rende potenzialmente più pericolosi per pedoni, ciclisti e auto più piccole in caso di incidente. Quindi, è importante essere consapevoli di questa caratteristica e guidare con prudenza.', 'La frase chiave è ''potenziale pericolo''. Significa che c''è la possibilità che il veicolo sia pericoloso, non che lo sia sempre, ma che richiede maggiore attenzione.', 'SUV grande e pesante = più attenzione per gli altri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23990, 'È vero che i conducenti di SUV devono pensare ai danni che i loro paraurti possono causare. Molti SUV hanno paraurti robusti e che sporgono, che sono fatti per proteggere il SUV, ma possono fare molti più danni a veicoli più piccoli in caso di scontro.', 'Le parole ''gravi danni'' e ''paraurti sporgenti e rafforzati'' sono importanti. Indicano che queste parti del veicolo possono aumentare la gravità di un impatto.', 'Paraurti SUV robusti = più danni agli altri veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23991, 'È vero che guidare un SUV in città è più difficile e richiede molta attenzione, specialmente nelle situazioni di emergenza. I SUV sono grandi, meno agili e hanno un baricentro più alto rispetto alle auto normali, il che li rende più difficili da controllare in manovre improvvise come una frenata o una sterzata d''emergenza.', 'Le espressioni ''particolarmente impegnativa in città'' e ''richiede particolari cautele soprattutto nelle manovre di emergenza'' sottolineano la difficoltà e la necessità di prudenza extra.', 'SUV in città = più difficile, più attenzione nelle emergenze.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23992, 'È falso che un SUV garantisca la ''massima sicurezza'' per tutti. Anche se può dare una sensazione di sicurezza agli occupanti per la sua dimensione, la sua massa e altezza elevate non garantiscono la massima sicurezza per gli altri utenti della strada (pedoni, ciclisti, auto più piccole), anzi, possono aumentare il pericolo per loro in caso di incidente.', 'La parola ''massima'' è una parola trappola molto comune. Raramente qualcosa garantisce la ''massima'' sicurezza in assoluto, specialmente quando si parla anche degli ''altri utenti della strada''.', '''Massima sicurezza'' per tutti = quasi sempre FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23993, 'È falso. I paraurti sporgenti e rafforzati (come i ''bull bars'') non rendono i fuoristrada ''meno pericolosi'' per gli altri veicoli. Al contrario, sono progettati per proteggere il SUV, ma in caso di collisione aumentano il rischio di danni gravi per gli altri veicoli e per i pedoni, perché sono più rigidi e meno deformabili.', 'La frase ''meno pericolosi'' è la trappola. Questi paraurti rendono il SUV più sicuro per sé stesso, ma più pericoloso per gli altri.', 'Bull bars = più pericolosi per gli altri, non meno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23994, 'È falso. La guida di un SUV non è ''particolarmente indicata'' per i centri abitati. I SUV sono grandi, consumano di più e sono più difficili da parcheggiare e manovrare in spazi stretti tipici della città. Sono più adatti per strade extraurbane o per l''uso fuori strada.', 'L''espressione ''particolarmente indicata'' è la trappola. Significa ''molto adatta'', ma i SUV non sono affatto molto adatti per la città.', 'SUV in città = scomodo, non indicato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23995, 'È vero che alla guida di un''autovettura dobbiamo fare molta attenzione ai veicoli grandi come camion e autobus. Questi veicoli sono molto più pesanti e, in caso di incidente, possono causare danni maggiori. Per questo, è importante valutarne la presenza e guidare con prudenza quando ci sono.', 'La frase ''opportuno valutare costantemente'' significa che è sempre una buona idea pensarci e stare attenti, non che è un obbligo assoluto, ma una pratica di guida sicura. ''Potenziale pericolosità'' indica che possono essere pericolosi, non che lo sono sempre.', 'Veicolo grande = attenzione maggiore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23996, 'È vero. Se un veicolo pesante come un autocarro o un autoarticolato non rispetta i limiti di velocità, diventa molto più pericoloso. La sua grande massa, unita all''alta velocità, rende più difficile fermarsi e aumenta enormemente la gravità di un possibile incidente. Chi guida un veicolo più piccolo deve essere consapevole di questo rischio elevato.', 'Le parole ''alti rischi'' sottolineano la serietà del pericolo. La condizione ''che non rispettano i limiti di velocità'' è fondamentale: è proprio questa infrazione che rende il rischio così elevato.', 'Camion veloci = pericolo doppio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23997, 'Questa affermazione è falsa. Proprio a causa della loro ''massa notevole'', autocarri, autotreni e autoarticolati costituiscono un rischio potenziale molto maggiore per un''autovettura o un motociclo rispetto a un veicolo più piccolo. In caso di scontro, la differenza di peso e dimensioni rende l''impatto molto più grave per il veicolo più leggero.', 'La parte cruciale è ''non costituiscono... rischi potenziali maggiori''. La negazione ''non'' rende l''affermazione sbagliata. In realtà, i rischi sono decisamente maggiori.', 'Massa grande = rischio grande.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23998, 'Anche se la tua auto è costruita per darti una buona visibilità, tu devi sempre guardare con molta attenzione la strada davanti e ai lati. Non basta che la macchina sia fatta bene, devi essere tu a fare attenzione.', 'La parola ''Nonostante'' (anche se) è una trappola: non importa quanto sia buona la macchina, la tua attenzione deve essere sempre ''attentamente'' (con cura) alta.', 'Buona macchina non significa occhi chiusi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (23999, 'Sì, è vero. Anche parti della tua stessa auto, come i poggiatesta o i montanti della carrozzeria (i bordi del finestrino), possono coprire la vista e farti non vedere pedoni o altri veicoli, specialmente quelli più piccoli.', 'La parola ''accidentalmente'' (per caso) sottolinea che questi punti ciechi possono sorprenderti.', 'Anche la tua auto ha angoli ciechi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24000, 'È vietato mettere pellicole adesive sul parabrezza (il vetro davanti) e sui vetri laterali anteriori (quelli del guidatore e del passeggero). Questo perché le pellicole riducono la visibilità e possono essere pericolose.', 'La parola chiave è ''vietato'' (non permesso). Non ci sono eccezioni per questi vetri.', 'Davanti e ai lati, vetri puliti e chiari.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24001, 'I veicoli fuoristrada (come i SUV) sono grandi e alti. Per questo, è più difficile per il conducente vedere i pedoni, specialmente i bambini, che sono piccoli e vicini al veicolo, proprio davanti o ai lati bassi.', 'La frase ''a causa delle dimensioni del mezzo'' (per via della grandezza del veicolo) spiega il motivo del rischio.', 'SUV grande, attenzione ai piccoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24002, 'No, è falso. Non puoi mai fare un controllo veloce o ''affrettato''. Anche se la tua auto ha una buona visibilità, devi sempre guardare con molta attenzione e in modo completo l''area intorno al veicolo, specialmente quella più vicina.', 'Le parole ''può limitarsi'' (può fare solo) e ''affrettato'' (veloce e superficiale) sono le trappole. Alla guida, non ci si ''limita'' mai e non si è mai ''affrettati''.', 'Mai fretta, sempre attenzione massima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24003, 'No, è falso. Non è permesso mettere pellicole adesive sui vetri laterali anteriori e sul parabrezza, nemmeno se queste pellicole si possono togliere facilmente. La legge vuole che questi vetri siano sempre completamente trasparenti per la sicurezza.', 'La parola ''consentito'' (permesso) è la trappola, insieme a ''a condizione che siano di materiale rimovibile'' (se si possono togliere). La rimovibilità non cambia la regola.', 'Rimovibile o no, davanti e ai lati no.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24004, 'No, è falso. I veicoli fuoristrada (SUV) sono alti, e proprio per questo è più difficile per il conducente vedere gli ostacoli piccoli o i bambini che si trovano molto vicini al suolo, proprio davanti al veicolo. L''altezza del mezzo crea un ''angolo cieco'' in basso.', 'La frase ''adeguata visibilità di tutti i possibili ostacoli in basso'' (buona visibilità di tutti gli ostacoli bassi) è la trappola, perché è il contrario di ciò che accade con i SUV.', 'SUV alto, ostacoli bassi nascosti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24005, 'Gli autocarri sono veicoli grandi e alti. Questo significa che il conducente ha una visuale limitata, specialmente nella zona subito davanti al veicolo. Per questo motivo, è fondamentale fare molta attenzione a pedoni o ciclisti che potrebbero trovarsi lì prima di ripartire, perché sono difficili da vedere.', 'La frase ''particolare attenzione'' sottolinea l''importanza di questa azione. Non è una semplice attenzione, ma una molto elevata, proprio per i rischi legati ai punti ciechi degli autocarri.', 'Autocarro alto = punto cieco davanti. Attenzione massima prima di ripartire!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24006, 'Quando un autocarro è fermo, la sua grande dimensione (la ''sagoma'') può nascondere pedoni e ciclisti che si trovano molto vicini, soprattutto davanti o ai lati. Il conducente deve sempre ''prevedere'', cioè immaginare, che ci possano essere persone in queste zone non visibili, anche se non le vede direttamente.', 'Le parole ''prevedere'' e ''precluso dalla sagoma'' sono importanti. ''Prevedere'' significa anticipare un possibile pericolo, mentre ''precluso'' significa impedito o bloccato. La sagoma del veicolo blocca la vista.', 'Autocarro grande = vista bloccata. Prevedi sempre pedoni e ciclisti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24007, 'Il parabrezza degli autocarri è posizionato in alto, il che crea una ''zona d''ombra'' subito davanti al veicolo. Questa ''limitata visuale'' rende molto pericoloso fermarsi in coda se ci sono pedoni o ciclisti in quella zona, perché il conducente non li vedrebbe facilmente al momento di ripartire.', 'Le espressioni ''limitata visuale'' e ''rende pericolosa'' sono chiavi. Indicano che c''è un problema di visibilità che aumenta il rischio di incidenti, specialmente in situazioni come la fermata in colonna.', 'Visuale limitata davanti = fermata in colonna con autocarro = pericolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24008, 'Questa affermazione è FALSO. Gli autocarri, a causa delle loro dimensioni e della posizione di guida elevata, hanno ampi ''punti ciechi'' (zone non visibili) sia nella parte immediatamente antistante (davanti) che in quelle laterali. Non è possibile avere un ''controllo sicuro di tutta la zona''.', 'Le parole ''tutta la zona'' e ''controllo sicuro'' sono le trappole. In contesti di sicurezza stradale, affermazioni assolute come ''tutta'' o ''sempre'' sono spesso false, specialmente quando si parla di visibilità di veicoli grandi.', 'Autocarro = molti punti ciechi. Mai ''tutta la zona sicura''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24009, 'Questa affermazione è FALSO. Un pedone non può attraversare ''in tutta sicurezza'' davanti a un autocarro fermo che sta per ripartire. Come abbiamo visto, il conducente ha un punto cieco molto grande proprio lì e potrebbe non vedere il pedone. Affermare che è ''sicuramente avvistabile'' è un errore grave.', 'Le espressioni ''in tutta sicurezza'' e ''sicuramente avvistabile'' sono le parole trappola. Indicano una certezza che non esiste in questa situazione. Anzi, è proprio il contrario: è una zona di grande pericolo e scarsa visibilità.', 'Davanti all''autocarro = mai sicuro. ''Sicuramente'' è falso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24010, 'Questa affermazione è FALSO. I conducenti di autocarri NON possono ''facilmente avvistare'' pedoni o ciclisti che si trovano molto vicini alla parte anteriore del veicolo. Questa è proprio la zona del ''punto cieco'' dove la visibilità è minima o assente. È molto difficile vederli, non facile.', 'La parola ''facilmente'' è la trappola. La realtà è che è molto difficile, se non impossibile, avvistare persone o oggetti che si trovano a ridosso della parte anteriore di un autocarro.', 'Autocarro + vicino davanti = difficile vedere. Mai ''facilmente''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24011, 'Il giubbotto o le bretelle retroriflettenti servono a rendere visibile la persona, mentre il triangolo mobile di pericolo serve a segnalare il veicolo fermo. Hanno scopi diversi e non possono sostituirsi a vicenda. In caso di emergenza, spesso si usano entrambi.', 'La frase ''in ogni caso'' è una parola trappola. Significa ''sempre'', ma non è così. Giubbotto e triangolo hanno funzioni diverse e complementari.', 'Giubbotto per te, triangolo per l''auto. Non si sostituiscono!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24012, 'I giubbotti e le bretelle ad alta visibilità non sono solo di colore giallo. Possono essere anche arancione o rosso fluorescente. L''importante è che siano colori molto visibili per la sicurezza.', 'La parola ''solo'' è la trappola. Non è vero che esiste un unico colore permesso.', 'Non solo giallo: anche arancione o rosso vanno bene.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24013, 'Il giubbotto ad alta visibilità ha un solo scopo: renderti più visibile agli altri, specialmente di notte o con poca luce. Non è fatto per proteggerti da pericoli come sostanze chimiche, calore, fuoco o scosse elettriche.', 'La frase ''anche da rischi chimici, calore, fuoco ed elettricità'' è la trappola. Il giubbotto non ha queste funzioni protettive.', 'Giubbotto = visibilità, non protezione da pericoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24014, 'La legge richiede di avere almeno un giubbotto o un paio di bretelle retroriflettenti nel veicolo. Non è necessario averne uno per ogni posto disponibile, ma solo per la persona che scende dal veicolo in caso di emergenza.', 'La frase ''in numero pari a quello dei posti disponibili'' è la trappola. Basta averne uno.', 'Basta uno per l''emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24015, 'L''obbligo di indossare il giubbotto o le bretelle è lo stesso sia dentro che fuori dai centri abitati, quando si scende dal veicolo fermo sulla carreggiata o sulla corsia di emergenza, in situazioni di pericolo o scarsa visibilità. Non c''è una distinzione tra giubbotto e bretelle in base all''area.', 'La distinzione tra ''fuori dai centri abitati'' per il giubbotto e ''nelle aree urbane'' per le bretelle è la trappola. La regola è unica per entrambi e per tutte le aree.', 'Giubbotto/bretelle = visibilità, ovunque serva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24016, 'Il giubbotto retroriflettente serve a renderti visibile agli altri automobilisti, così che ti vedano e possano evitare incidenti. Non è un modo per chiedere aiuto, ma per aumentare la tua sicurezza passiva.', 'La frase ''per chiedere aiuto'' è la trappola. Il suo scopo è la sicurezza, non la richiesta di soccorso.', 'Giubbotto = farsi vedere, non chiedere aiuto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24017, 'Il giubbotto è utile in tutte le situazioni in cui devi scendere dal veicolo fermo sulla carreggiata, fuori dai centri abitati, o in situazioni di scarsa visibilità. Non solo per cambiare una ruota, ma anche in caso di guasto, incidente o qualsiasi altra emergenza che ti costringa a scendere dall''auto.', 'La parola ''solo'' è la trappola. Il giubbotto è utile in molte altre situazioni di emergenza.', 'Giubbotto = visibilità in ogni emergenza fuori dall''auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24018, 'Se un veicolo davanti a te ha un carico che potrebbe cadere, è fondamentale aumentare la distanza di sicurezza. Questo ti dà più tempo per reagire se qualcosa cade. In salita, il rischio può aumentare a causa delle forze in gioco, quindi è ancora più importante mantenere una distanza maggiore.', 'La frase ''specie se si è in salita'' non è una condizione che rende la risposta falsa, ma rafforza l''importanza di aumentare la distanza in quella situazione specifica.', 'Carico instabile = più spazio, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24019, 'Quando un veicolo ha un carico instabile, devi aumentare la distanza di sicurezza per proteggerti. Se le condizioni lo permettono e puoi farlo in sicurezza, è meglio sorpassarlo per allontanarti dal pericolo.', 'La parola ''appena possibile'' è la chiave. Significa che devi sorpassare solo quando è sicuro e consentito, non in modo avventato.', 'Carico instabile = distanza + sorpasso sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24020, 'È una buona pratica civica e di sicurezza avvertire un altro conducente se noti un pericolo, come un carico che sta per cadere. Puoi farlo con segnali luminosi o acustici, se possibile e sicuro.', 'Il termine ''opportuno'' significa che è consigliabile, una buona cosa da fare, non un obbligo assoluto, ma una misura di sicurezza utile.', 'Pericolo = avvisa il conducente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24021, 'Mantenere una distanza maggiore da un veicolo con un carico poco sicuro ti permette di avere il tempo necessario per frenare o fare una manovra evasiva se il carico dovesse cadere improvvisamente sulla strada.', 'La frase ''non stargli troppo vicino'' è un modo per dire ''aumenta la distanza di sicurezza''. Il motivo è chiarito: ''riuscire a fermarsi in tempo''.', 'Distanza = tempo di reazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24022, 'Le manovre come frenare o svoltare possono causare spostamenti improvvisi del carico. Se il carico è instabile, queste azioni aumentano il rischio che cada. Per questo, devi essere ancora più attento in questi momenti.', 'La parola ''soprattutto'' evidenzia che frenate e svolte sono i momenti più critici per la stabilità del carico.', 'Frenata/Svolta + carico instabile = massima attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24023, 'Un carico che sporge o penzola può coprire le luci posteriori del veicolo, inclusi gli indicatori di direzione. Questo rende difficile per te capire le intenzioni del conducente, aumentando il rischio di incidenti.', 'La frase ''può risultare difficile'' indica una possibilità concreta, non una certezza, ma un rischio da considerare.', 'Carico sporgente = segnali nascosti = attenzione extra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24024, 'Stringersi al margine sinistro della carreggiata non ti protegge da un carico che cade e potrebbe metterti in pericolo con il traffico in arrivo o con altri veicoli che sorpassano. La cosa giusta da fare è aumentare la distanza di sicurezza e, se possibile, sorpassare in sicurezza.', 'La frase ''stringersi il più vicino possibile al margine sinistro'' è una manovra pericolosa e sbagliata in questa situazione.', 'Carico che cade = non avvicinarti al centro/sinistra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24025, 'Spostarsi lungo il margine sinistro della carreggiata non è una soluzione sicura per un carico instabile. Devi mantenere la tua corsia, aumentare la distanza di sicurezza e, se le condizioni lo permettono, sorpassare in sicurezza.', 'Anche qui, ''spostarsi lungo il margine sinistro'' è una manovra errata e potenzialmente pericolosa.', 'Carico pericoloso = non cambiare corsia senza motivo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24026, 'Sorpassare ''subito, anche se in curva'' è estremamente pericoloso e vietato. Il sorpasso deve essere sempre effettuato solo quando è sicuro, c''è buona visibilità e le condizioni della strada lo permettono, mai in curva.', 'Le parole ''subito'' e ''anche se in curva'' sono indicatori di una risposta falsa, perché suggeriscono un''azione avventata e pericolosa.', 'Sorpasso = solo se sicuro, mai in curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24027, 'Arrestarsi ''bruscamente'' è molto pericoloso perché potresti causare un tamponamento con i veicoli che ti seguono. In caso di pericolo, devi reagire in modo graduale e sicuro, aumentando la distanza o, se necessario, deviando con cautela.', 'La parola ''bruscamente'' è quasi sempre un segnale di pericolo e di azione sbagliata nei quiz di guida.', 'Mai frenare bruscamente senza motivo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24028, 'Diminuire la distanza di sicurezza è l''esatto contrario di ciò che dovresti fare. Aumentare la distanza è fondamentale per la tua sicurezza. La ragione data, cioè impedire agli altri di sorpassare, non è un motivo valido per mettere a rischio la propria sicurezza.', 'La frase ''diminuire la distanza di sicurezza'' è la trappola principale. Ricorda che la distanza di sicurezza va sempre aumentata in condizioni di pericolo.', 'Carico instabile = sempre più distanza, mai meno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24029, 'Trainare un rimorchio, specialmente in salita, richiede un maggiore sforzo al motore. Questo sforzo extra produce più calore, facendo aumentare la temperatura del liquido di raffreddamento.', 'La frase ''forti salite'' indica una condizione di maggiore stress per il motore, che porta all''aumento della temperatura.', 'Più sforzo = più calore al motore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24030, 'Il rimorchio aggiunge peso al veicolo. Un peso maggiore significa che il sistema frenante deve lavorare di più per fermare il veicolo, e quindi ci vuole più spazio per frenare completamente.', 'La parola chiave è ''aumenta''. Il peso extra del rimorchio ha sempre un impatto negativo sulla frenata.', 'Più peso = più strada per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24031, 'Anche un rimorchio leggero presenta una superficie laterale che può essere colpita dal vento. Questa forza del vento può sbilanciare il veicolo e il rimorchio, aumentando il rischio di ribaltamento, soprattutto in presenza di vento forte o raffiche laterali.', 'La frase ''maggiore la forza ribaltante'' è cruciale. Il vento laterale è un pericolo sottovalutato per i veicoli con rimorchio.', 'Vento + rimorchio = rischio ribaltamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24032, 'Sistemare gli oggetti pesanti vicino all''asse del rimorchio (cioè al centro) aiuta a mantenere il rimorchio più stabile e bilanciato. Questo riduce le oscillazioni e rende la guida più sicura.', 'La chiave è ''il più vicino possibile al suo asse''. Questo garantisce una distribuzione del peso ottimale per la stabilità.', 'Peso al centro = più stabilità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24033, 'Quando si curva con un rimorchio, il rimorchio segue una traiettoria più interna rispetto al veicolo che lo traina (si dice che ''taglia'' la curva). Per questo, bisogna allargare di più la curva per evitare che le ruote del rimorchio salgano sul marciapiede.', 'La frase ''fare particolare attenzione a non salire con la ruota posteriore sul marciapiede'' evidenzia il problema della traiettoria del rimorchio.', 'Rimorchio ''taglia'' la curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24034, 'Il servosterzo è un sistema che rende lo sterzo più leggero e facile da girare. Funziona solo quando il motore è acceso. Se il veicolo è guasto e il motore è spento, il servosterzo non funziona, e quindi lo sterzo diventa molto più duro da manovrare.', 'Le parole ''servosterzo'' e ''veicolo guasto'' sono importanti. Senza motore, il servosterzo è inattivo.', 'Motore spento = servosterzo spento = sterzo duro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24035, 'È fondamentale che tutte le luci (fari, stop, indicatori di direzione) e i dispositivi di segnalazione del rimorchio funzionino correttamente. Questo garantisce la sicurezza sulla strada, rendendo il rimorchio visibile agli altri e segnalando le proprie intenzioni.', 'La frase ''funzionino regolarmente'' sottolinea l''importanza del controllo pre-partenza per la sicurezza.', 'Luci e frecce = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24036, 'Il rimorchio può limitare la visibilità posteriore attraverso gli specchietti retrovisori. È essenziale controllare che la visibilità sia sufficiente per guidare in sicurezza, magari regolando gli specchi o usando specchi aggiuntivi se necessario.', 'La parola ''adeguata'' è la chiave. La visibilità è fondamentale per la sicurezza stradale.', 'Controlla gli specchi, vedi bene.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24037, 'Un rimorchio, anche quando è fermo e staccato dal veicolo, può causare danni (ad esempio, se si muove accidentalmente). Per questo, deve avere una sua assicurazione specifica che copra il ''rischio statico'', cioè i danni che può causare da fermo.', 'La frase ''rischio statico (da fermo)'' è la parte più importante. L''assicurazione copre anche quando il rimorchio non è in movimento.', 'Rimorchio fermo = assicurazione sua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24038, 'Il freno ad inerzia è un sistema dove il rimorchio frena automaticamente quando il veicolo che lo traina rallenta o frena. È il tipo di freno più comune e pratico per i rimorchi di piccole e medie dimensioni trainati da autovetture.', 'La frase ''freno ad inerzia'' identifica il sistema di frenata tipico per questi rimorchi.', 'Rimorchio auto = freno a inerzia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24039, 'In Italia, i rimorchi (esclusi i carrelli appendice) sono considerati veicoli a sé stanti e devono avere una propria targa di immatricolazione, diversa da quella del veicolo che li traina. Questo serve per la loro identificazione.', 'La frase ''targa propria'' è chiara e indica un requisito legale fondamentale.', 'Rimorchio = sua targa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24040, 'FALSO. Concentrare il carico massimo in un punto estremo come il gancio di traino può rendere il rimorchio molto instabile e pericoloso. Il carico deve essere distribuito in modo equilibrato, con gli oggetti più pesanti posizionati vicino all''asse del rimorchio per garantire stabilità.', 'La parola ''concentrare'' è la trappola. Il carico va distribuito, non concentrato in un punto che può sbilanciare il rimorchio.', 'Carico distribuito, non sul gancio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24041, 'FALSO. Il collegamento elettrico tra motrice e rimorchio è sempre obbligatorio. Serve per far funzionare le luci posteriori, gli indicatori di direzione, le luci di stop e, in alcuni casi, i freni del rimorchio, garantendo la sicurezza e la visibilità.', 'La frase ''non occorre effettuare il collegamento elettrico'' è l''errore. È sempre necessario per la sicurezza.', 'Collegamento elettrico = obbligatorio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24042, 'FALSO. La patente di categoria E è necessaria per trainare rimorchi pesanti (non leggeri). Trainare un veicolo guasto non rientra in questa categoria e non richiede la patente E, ma solo la patente adeguata per il veicolo che traina (ad esempio, la patente B per un''autovettura).', 'La trappola è ''patente di guida della categoria E''. Trainare un veicolo guasto non è come trainare un rimorchio pesante.', 'Veicolo guasto non è rimorchio E.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24043, 'FALSO. La persona che si trova al volante del veicolo guasto trainato deve essere in grado di controllare lo sterzo e i freni. Per fare ciò, deve essere in possesso di una patente di guida valida per quel tipo di veicolo.', 'La frase ''privo di patente di guida'' è l''errore. Chiunque sia al volante deve avere la patente.', 'Al volante = patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24044, 'FALSO. Quando un veicolo guasto viene trainato con le quattro ruote a terra, il cambio di velocità deve essere in posizione di folle (punto morto). Inserire una marcia potrebbe causare gravi danni alla trasmissione del veicolo trainato.', 'La frase ''inserire la quarta marcia'' è l''errore. Il cambio deve essere in folle per evitare danni.', 'Traino a terra = folle.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24045, 'FALSO. Gli organi di traino, come il gancio e le sue parti mobili, sono componenti meccanici soggetti a usura. Devono essere periodicamente lubrificati per garantire il loro corretto funzionamento, la sicurezza e per prevenire la corrosione.', 'La negazione ''non devono essere periodicamente lubrificati'' è l''errore. La manutenzione è essenziale.', 'Gancio = lubrificare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24046, 'FALSO. Tutti gli organi di traino, indipendentemente dalla massa del rimorchio che devono trainare, devono essere omologati e installati secondo le normative vigenti. L''omologazione garantisce che siano sicuri e conformi agli standard.', 'La frase ''possono non essere omologati'' è l''errore. L''omologazione è sempre un requisito di sicurezza.', 'Omologazione = sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24047, 'FALSO. Se il servosterzo non funziona (perché il motore è spento), lo sterzo diventa molto più duro e faticoso da girare, ma non è bloccato. È comunque possibile manovrarlo, anche se con maggiore sforzo.', 'La parola ''sempre bloccato'' è la trappola. Diventa duro, non bloccato.', 'Servosterzo spento = duro, non bloccato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24048, 'FALSO. Nelle forti discese, il peso del rimorchio esercita una spinta aggiuntiva sul veicolo che lo traina. Questa forza aumenta la velocità e rende più difficile controllare il veicolo e frenare. È fondamentale tenerne conto e guidare con estrema prudenza.', 'La negazione ''non occorre tener conto'' è l''errore. È un fattore cruciale per la sicurezza in discesa.', 'Discesa + rimorchio = spinta extra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24049, 'FALSO. Anche i rimorchi leggeri devono avere luci posteriori, indicatori di direzione e luci di stop funzionanti per essere visibili e segnalare le proprie intenzioni agli altri utenti della strada. Per questo, il collegamento elettrico è sempre obbligatorio, indipendentemente dal peso del rimorchio.', 'La frase ''non occorre effettuare il collegamento elettrico'' è l''errore. Tutte le luci sono obbligatorie.', 'Tutte le luci = collegamento elettrico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24050, 'FALSO. Quando si traina un veicolo guasto, la distanza massima consentita tra i due veicoli è di 2,5 metri, non 3 metri. Se si utilizza una fune, questa deve essere ben visibile (ad esempio, con un panno rosso).', 'Il numero ''3 metri'' è la trappola. La distanza massima è 2,5 metri.', 'Traino guasto = max 2,5 metri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24051, 'FALSO. Nelle curve strette, il rimorchio segue una traiettoria più interna rispetto alla motrice (taglia la curva). Questo significa che lo spazio totale occupato dal veicolo più il rimorchio, cioè la ''fascia di ingombro'', è maggiore, non minore. Bisogna quindi allargare la curva per evitare ostacoli.', 'La frase ''fascia di ingombro è minore'' è l''errore. Il rimorchio ''taglia'' e quindi occupa più spazio lateralmente.', 'Rimorchio in curva = più spazio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24052, 'La carta di circolazione (oggi chiamata Documento Unico di Circolazione) è il documento ufficiale del veicolo. Su di essa sono scritte tutte le informazioni importanti, incluso il numero massimo di persone che possono essere trasportate. Quindi, questa affermazione è VERA.', 'La frase chiave è ''è indicato sulla carta di circolazione''. Ricorda che questo documento è la fonte principale per le informazioni sul tuo veicolo.', 'Quanti posti? Guarda la carta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24053, 'Esattamente come per la domanda precedente, il numero di posti a sedere disponibili in un veicolo è una delle informazioni fondamentali che trovi sulla carta di circolazione. È un dato obbligatorio. Quindi, questa affermazione è VERA.', 'Ancora una volta, ''è indicato sulla carta di circolazione'' è il punto cruciale. È il documento che fa fede.', 'Posti totali = sulla carta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24055, 'Le autovetture sono veicoli destinati al trasporto di persone. La legge stabilisce che il numero massimo di persone che un''autovettura può trasportare è nove, e in questo conteggio è sempre incluso anche il conducente. Se fossero di più, il veicolo non sarebbe più un''autovettura. Quindi, questa affermazione è VERA.', 'Le parole importanti sono ''massimo di nove'' e ''compreso quello del conducente''. ''Massimo'' significa che può essere anche meno (es. 5 o 7 posti), ma non di più.', 'Auto = max 9 (con conducente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24056, 'Questa domanda ripete il concetto della precedente. Le autovetture possono trasportare un massimo di nove persone, e questo numero include sempre il guidatore. È il limite legale per questa categoria di veicoli. Quindi, questa affermazione è VERA.', 'Fai attenzione a ''al massimo di nove, compreso il conducente''. ''Al massimo'' indica il limite superiore, non un numero fisso per tutte le auto.', 'Autovettura = 9 persone (max, con conducente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24057, 'Questa affermazione è FALSA. Non tutti i motocicli possono trasportare due persone oltre il conducente (cioè tre persone in totale). Molti motocicli sono omologati per una sola persona (il conducente) o per due persone in totale (conducente + un passeggero). Il numero esatto è sempre indicato sulla carta di circolazione del motociclo.', 'La parola ''sempre'' è una trappola! Non è mai ''sempre'' così. Anche ''oltre il conducente'' è un dettaglio importante, perché significa 3 persone in totale, il che è raro per un motociclo.', 'Motociclo: non ''sempre'' 3 persone! Controlla la carta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24058, 'Questa affermazione è FALSA. Come abbiamo visto nelle domande precedenti, il numero massimo di persone trasportabili sulle autovetture è nove, compreso il conducente. Ci sono molte autovetture che possono trasportare 5, 7 o anche 9 persone, non solo quattro.', 'La frase ''al massimo di quattro'' è la parte sbagliata. Ricorda che il limite per le autovetture è più alto.', 'Auto = max 9, non 4!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24059, 'Questa affermazione è FALSA. Gli autocarri sono veicoli destinati principalmente al trasporto di merci. Il numero di persone che possono trasportare varia molto a seconda del modello e dell''omologazione del veicolo, e non è ''sempre'' cinque. Alcuni autocarri possono trasportare solo due o tre persone. Il numero esatto è sulla carta di circolazione.', 'La parola ''sempre'' è la trappola principale. Non esiste un numero fisso per tutti gli autocarri. Anche ''compreso il conducente'' è corretto nel conteggio, ma il numero ''cinque'' non è universale.', 'Autocarro: non ''sempre'' 5! Dipende dal modello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24060, 'Questa affermazione è FALSA. Il numero di persone trasportabili indicato sulla carta di circolazione di qualsiasi veicolo include sempre il conducente. Quando si parla di ''posti'' o ''persone trasportabili'', si intende il numero totale di occupanti, compreso chi guida il veicolo.', 'La parte ''non comprende il conducente'' è l''errore. Il conducente è sempre contato nel numero totale di posti.', 'Posti totali = conducente + passeggeri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24061, 'Questo pannello serve proprio a segnalare che c''è un carico che esce dalla parte posteriore del veicolo. Va messo alla fine del carico, nel punto più lontano, per avvisare chi segue.', 'La frase ''all''estremità del carico'' è fondamentale: significa proprio alla fine, nel punto più sporgente.', 'Estremità = fine del carico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24062, 'Esatto! La funzione principale di questo pannello è proprio quella di indicare agli altri utenti della strada che il veicolo ha un carico che sporge dalla parte posteriore, rendendolo più lungo del normale.', 'Non ci sono parole trappola particolari. La domanda descrive correttamente l''uso del pannello.', 'Strisce rosse e bianche = attenzione carico dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24063, 'Sì, è vero. Il pannello deve essere retroriflettente, cioè deve riflettere la luce dei fari degli altri veicoli. Questo è molto importante per essere visibile di notte o quando c''è poca luce, garantendo la sicurezza.', 'La parola ''retroriflettente'' è la chiave. Significa che riflette la luce all''indietro, verso la fonte.', 'Riflettente = visibile anche al buio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24064, 'Vero. Non importa quanto il carico sporga. Anche se è solo di pochi centimetri, la legge dice che devi usare il pannello per segnalarlo. Non c''è una misura minima.', 'La frase ''anche se di poco'' è importante. Sottolinea che non c''è una misura minima per l''obbligo.', 'Sporge? Metti il pannello, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24065, 'Sì, è un uso secondario ma consentito. Se un veicolo è in panne e viene trainato, e le sue luci di emergenza non funzionano, questo pannello può essere usato come segnale di pericolo aggiuntivo per avvisare gli altri.', 'La parola ''può'' indica che è un''opzione, non un obbligo primario, ma è un uso valido.', 'Guasto senza luci? Usa il pannello come avviso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24066, 'Vero. Il pannello deve essere posizionato in modo che sia sempre ben visibile a chi arriva da dietro. Non deve essere coperto da altri oggetti o sporco, altrimenti non serve a nulla.', 'La frase ''sempre ben visibile'' è cruciale. La visibilità è fondamentale per la sicurezza.', 'Visibile = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24067, 'Vero. Il pannello è un segnale di pericolo. Vedendolo, gli altri conducenti capiscono che c''è un potenziale rischio (un carico sporgente) e sono invitati a guidare con maggiore attenzione e a mantenere una distanza di sicurezza.', 'La frase ''particolare prudenza'' riassume lo scopo di un segnale di pericolo.', 'Pannello = attenzione, rallenta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24068, 'Falso. Questa è una trappola! Il pannello va usato per QUALSIASI sporgenza posteriore, anche piccola. La regola dei ''tre decimi'' si riferisce alla LUNGHEZZA MASSIMA che un carico può sporgere, non a quando devi usare il pannello.', 'Le parole ''solo se'' sono una trappola comune. Inoltre, ''oltre tre decimi'' è un riferimento a un''altra regola (limite massimo di sporgenza), non all''obbligo di usare il pannello.', 'Non c''è un ''solo se'' per la sporgenza minima, basta che sporga!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24069, 'Falso. Questo pannello è specifico per i carichi che sporgono dalla PARTE POSTERIORE del veicolo. Se il carico sporge di lato, servono altri tipi di segnalazioni (ad esempio, luci o bandiere diverse), ma non questo pannello.', 'La frase ''anche di lato'' è l''errore. Il pannello a strisce rosse e bianche è solo per la parte posteriore.', 'Pannello a strisce = solo dietro, mai di lato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24070, 'Falso. Questo pannello non serve a identificare il tipo di veicolo o il tipo di merce che trasporta. Serve solo a segnalare un carico che sporge, indipendentemente dal fatto che sia un autocarro o meno, o che tipo di materiali trasporti.', 'La frase ''identifica gli autocarri specializzati'' è completamente sbagliata. Il pannello non ha questa funzione.', 'Non è un''etichetta per il tipo di camion, è per il carico che sporge!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24071, 'Falso. I veicoli che trasportano la spazzatura (i camion della nettezza urbana) hanno le loro segnalazioni specifiche (luci arancioni, ecc.), ma questo pannello non è per loro, a meno che non abbiano un carico che sporge in modo anomalo.', 'La frase ''veicoli che trasportano la spazzatura'' è un tentativo di confondere. Il pannello non è legato a questo tipo di veicoli.', 'Non è per la spazzatura, è per il carico che esce!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24072, 'Falso. Come abbiamo detto prima, non c''è una misura minima. Il pannello va messo anche se il carico sporge di pochi centimetri, non solo se supera i 50 centimetri.', 'Le parole ''solo se'' e ''almeno 50 centimetri'' sono la trappola. Non esiste un limite minimo di sporgenza per l''obbligo del pannello.', 'Non c''è un minimo di centimetri, basta che sporga!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24073, 'Falso. Il pannello va messo dietro agli autocarri (o a qualsiasi altro veicolo) SOLO SE hanno un carico che sporge dalla parte posteriore. Non tutti gli autocarri trasportano carichi sporgenti, quindi non tutti devono avere questo pannello.', 'La parola ''tutti'' rende la frase falsa. È una generalizzazione errata.', 'Non tutti i camion, solo quelli con carico sporgente!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24074, 'Falso. La legge è chiara: deve essere usato questo specifico pannello retroriflettente. Una semplice bandiera rossa non è sufficiente, soprattutto di notte, perché non rifletterebbe la luce e non sarebbe visibile come il pannello.', 'La frase ''può essere sostituito'' è la trappola. La legge richiede un dispositivo specifico, non un''alternativa generica.', 'Solo il pannello a strisce, non una bandiera!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24075, 'È VERO. Per evitare che il caravan si ribalti in curva, devi mettere gli oggetti più pesanti il più in basso possibile. Questo rende il veicolo più stabile.', 'Non ci sono parole trappola particolari. Il concetto di ''baricentro il più basso possibile'' è fondamentale per la stabilità.', 'Pesante in basso, stabile in curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24076, 'È VERO. Per ridurre il rischio di ribaltamento, il peso deve essere distribuito in modo uguale tra il lato destro e sinistro del caravan. Così non pende da una parte.', 'La parola chiave è ''equilibrato''. Significa che il peso deve essere bilanciato, non tutto da una parte.', 'Peso uguale, curva sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24077, 'È FALSO. Il caravan è sempre considerato un rimorchio, anche se lo usi per dormire. La sua funzione di ''alloggio'' non cambia la sua classificazione legale come veicolo trainato.', 'La trappola è ''non è considerato un rimorchio''. Ricorda che la funzione di alloggio non cambia la sua natura di rimorchio.', 'Caravan = Rimorchio, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24078, 'È FALSO. Non è mai permesso stare dentro il caravan mentre è in movimento, anche se ci fossero le cinture di sicurezza (che non ci sono per i passeggeri). Il caravan non è fatto per trasportare persone durante la circolazione.', 'La trappola è ''purché tutti i passeggeri allaccino le cinture di sicurezza''. Questa frase ti fa pensare che sia possibile, ma è assolutamente vietato stare dentro un caravan in movimento.', 'Caravan in movimento? Nessuno dentro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24079, 'È VERO. I rimorchi hanno un cavo di sicurezza. Se il rimorchio si stacca per sbaglio dalla macchina, questo cavo tira una leva che attiva i freni del rimorchio. Così il rimorchio si ferma da solo e non va in giro.', 'La frase ''sganciamento accidentale'' significa che il rimorchio si stacca per errore, non di proposito. ''Aziona automaticamente'' vuol dire che il freno si attiva da solo.', 'Rimorchio staccato = freno attivato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24080, 'È VERO. Se un rimorchio sta fermo per tanto tempo, specialmente all''aperto, l''acqua e l''umidità possono far arrugginire le parti metalliche dei freni. La ruggine rende i freni meno efficaci, cioè frenano meno bene.', 'La frase ''prolungato periodo di inattività'' significa che è stato fermo per molto tempo. ''Perso efficienza'' vuol dire che non funzionano più bene come prima.', 'Fermo a lungo = ruggine ai freni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24081, 'È VERO. Quando parcheggi un rimorchio, devi sempre mettere il freno a mano (freno di stazionamento) per sicurezza. Se la strada è in salita o in discesa, è ancora più importante usare anche dei cunei (pezzi di legno o plastica) sotto le ruote. Questo impedisce al rimorchio di muoversi da solo.', '''Occorre azionare'' significa che è necessario farlo. ''È opportuno applicare'' significa che è una buona idea, consigliato, specialmente per maggiore sicurezza.', 'Sosta rimorchio = freno + cunei in pendenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24082, 'È VERO. Il freno a inerzia funziona così: quando la macchina (motrice) frena, il rimorchio continua ad andare avanti per un attimo e spinge la macchina. Questa spinta attiva il freno del rimorchio. Quindi, il rimorchio frena un attimo dopo la macchina, non nello stesso preciso istante.', '''Non avviene simultaneamente'' significa che non succede nello stesso momento. ''Solo dopo che il rimorchio ha esercitato una spinta'' spiega il meccanismo del freno a inerzia.', 'Freno a inerzia = rimorchio spinge, poi frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24083, 'È VERO. Quando la macchina frena, il rimorchio, per inerzia, tende a continuare la sua corsa e si ''avvicina'' alla motrice (cioè spinge contro di essa). Questa spinta è quella che attiva il meccanismo del freno a inerzia.', '''Si avvicina alla motrice'' descrive l''azione fisica che attiva il freno a inerzia.', 'Freno a inerzia = avvicinamento attiva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24084, 'È FALSO. Quando freni, tutto ciò che è dentro il rimorchio (il carico) tende a muoversi in avanti, verso la direzione di marcia, per via dell''inerzia. Pensa a quando freni in macchina: tu stesso vieni spinto in avanti.', 'La parola trappola è ''all''indietro''. Il carico si sposta in avanti, non all''indietro.', 'Frenata = carico avanti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24085, 'È FALSO. Quando acceleri velocemente, il carico dentro il rimorchio tende a spostarsi all''indietro, cioè verso la parte posteriore del rimorchio. Pensa a quando acceleri in macchina: tu stesso vieni spinto all''indietro contro il sedile.', 'La parola trappola è ''in avanti''. Il carico si sposta all''indietro, non in avanti.', 'Accelerazione = carico indietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24086, 'È FALSO. Il sistema ABS della macchina serve per la frenata della macchina stessa. Non c''entra con il tipo di freni che deve avere il rimorchio. Puoi agganciare un rimorchio senza freni (se il suo peso lo permette) anche se la tua auto ha l''ABS.', 'La frase ''non è possibile'' è la parola trappola. È possibile, l''ABS della motrice non impedisce di trainare un rimorchio senza freni (se rispetta i limiti di peso).', 'ABS auto ≠ freni rimorchio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24087, 'È FALSO. Come spiegato prima, il freno a inerzia non è istantaneo. Il rimorchio deve prima spingere la motrice per attivare il suo freno. Quindi, non frena nello stesso momento della motrice, ma un attimo dopo.', 'La parola trappola è ''simultaneamente''. Non avviene nello stesso momento.', 'Freno a inerzia = non simultaneo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24088, 'È FALSO. Questa è l''opposto della realtà. Il rimorchio con freno a inerzia frena DOPO la motrice, non prima. Il meccanismo si attiva solo quando il rimorchio spinge la motrice.', 'La frase ''prima della motrice'' è la parola trappola. Frena dopo, non prima.', 'Freno a inerzia = rimorchio frena DOPO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24089, 'Nei centri abitati, non puoi lasciare un rimorchio da solo, staccato dalla macchina, a meno che non ci sia un cartello che lo permette. Questo serve per evitare ingombri e pericoli sulla strada.', 'La frase ''salvo diversa segnalazione'' è importante: significa che la regola vale a meno che un segnale stradale non indichi il contrario, permettendo l''eccezione.', 'In città, rimorchio staccato = NO, se non c''è un cartello che dice SÌ.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24090, 'Quando il rimorchio è attaccato alla macchina e sta circolando, è coperto dalla stessa assicurazione della macchina. Non serve una polizza separata per il rimorchio in quel momento.', 'La condizione chiave è ''Durante la circolazione''. Se il rimorchio è staccato e fermo (rischio statico), allora serve una sua assicurazione specifica.', 'Rimorchio attaccato = stessa assicurazione della motrice.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24091, 'Gli specchietti aggiuntivi che metti sulla macchina per vedere bene il rimorchio non possono sporgere troppo. Il limite massimo è di 20 centimetri dalla parte più larga del veicolo (che sia la macchina o il rimorchio).', 'Il limite preciso è ''non devono sporgere oltre 20 centimetri''. ''Punto di maggiore larghezza'' significa che la misura si prende dalla parte più larga del complesso veicolare.', 'Specchietti = max 20 cm di sporgenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24092, 'Il rapporto di traino è il rapporto tra la massa del rimorchio e la massa della motrice. Se il rimorchio ha i freni e pesa fino a 3,5 tonnellate, questo rapporto non può essere più grande di 1. In pratica, il rimorchio non può pesare più della motrice.', 'La frase ''non deve superare il valore di 1'' indica il limite massimo. ''Muniti di freno di servizio'' è una condizione fondamentale per questa regola.', 'Rimorchio con freni (fino 3.5t) = non più pesante della motrice (rapporto <= 1).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24093, 'Se un rimorchio non ha nessun tipo di freno, allora deve essere molto più leggero della macchina che lo traina. Il suo peso non può superare la metà del peso della motrice (il rapporto massimo è 0,5).', 'La condizione cruciale è ''sprovvisto di qualsiasi dispositivo di frenatura''. Il valore ''0,5'' è il limite esatto da ricordare.', 'Rimorchio senza freni = max metà peso della motrice (rapporto 0.5).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24094, 'Se non stai usando il gancio di traino, la parte che sporge dalla macchina deve essere tolta, smontata o ripiegata. Questo serve per sicurezza, per non creare pericoli o ferire qualcuno.', 'La condizione è ''quando il gancio di traino non viene utilizzato''. Le azioni obbligatorie sono ''sfilata, smontata o ripiegata''.', 'Gancio non usato = via! (sfilato/smontato/ripiegato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24095, 'I rimorchi T.A.T.S. (Trasporto Attrezzature Turistiche e Sportive) sono fatti per portare cose come barche, moto d''acqua, attrezzature sportive, ecc., ma solo per il tuo tempo libero, non per venderle o usarle per lavoro.', 'Le parole chiave sono ''non devono costituire oggetto di commercio'' e ''essere impiegate solo per il tempo libero''. Queste definiscono la natura dei T.A.T.S.', 'T.A.T.S. = tempo libero, non commercio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24096, 'Se guidi un veicolo con rimorchio e il peso totale (macchina + rimorchio) supera le 3,5 tonnellate, la legge è molto severa sull''alcol. Non puoi avere alcol nel sangue, nemmeno un po'' (tasso alcolemico superiore a zero).', 'La condizione di peso è ''superiore a 3,5 tonnellate''. La tolleranza è ''superiore a zero grammi per litro'', che significa alcol zero.', 'Complesso > 3.5t = alcol zero.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24097, 'Se guidi un veicolo con rimorchio che è molto lungo (più di 7 metri) su un''autostrada con tante corsie (tre o più), puoi usare solo le due corsie più a destra. Non puoi andare nella corsia più a sinistra.', 'Le condizioni sono ''lunghezza totale superiore a 7 metri'' e ''carreggiate a tre o più corsie''. Il limite è ''due più vicine al bordo destro''.', 'Complesso > 7m (autostrada 3+ corsie) = solo le due corsie di destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24098, 'Non è vero che tutti i rimorchi fino a 3,5 tonnellate devono avere le strisce riflettenti. Questo obbligo riguarda solo i veicoli più pesanti (con massa superiore a 3,5 tonnellate) o di dimensioni particolari. I rimorchi leggeri non hanno questo obbligo.', 'La trappola è ''fino a 3,5 tonnellate''. L''obbligo delle strisce retroriflettenti è per veicoli con massa superiore a 3,5 tonnellate o di particolari categorie, non per tutti i rimorchi leggeri.', 'Strisce riflettenti = per veicoli pesanti (>3.5t), non per tutti i rimorchi leggeri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24099, 'Tutti i rimorchi, anche quelli molto leggeri (sotto i 750 kg), devono essere immatricolati e avere la loro targa. Non puoi trainare un rimorchio non immatricolato.', 'La parola trappola è ''non immatricolati''. Tutti i rimorchi devono essere immatricolati, indipendentemente dal peso.', 'Ogni rimorchio = immatricolato, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24100, 'Il rimorchio è sempre un veicolo a sé stante, anche se leggero. Non è mai considerato ''parte integrante'' della motrice. Ha la sua targa e la sua assicurazione (quando staccato).', 'La frase ''parte integrante del veicolo'' è la trappola. Il rimorchio è un veicolo separato e indipendente.', 'Rimorchio = veicolo a sé, mai parte integrante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24101, 'Non è vero. La larghezza del rimorchio può essere maggiore di quella della motrice, ma ci sono dei limiti massimi di larghezza stabiliti dalla legge per i veicoli in generale (ad esempio 2,55 metri). L''importante è che non superi questi limiti e che la motrice sia adatta a trainarlo.', 'La trappola è ''non deve superare quella del veicolo trainante''. Ci sono limiti massimi assoluti di larghezza, non solo rispetto alla motrice.', 'Larghezza rimorchio > motrice = possibile, ma entro limiti legali massimi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24102, 'Questa affermazione è falsa per due motivi. Primo, il rimorchio non è parte integrante della motrice. Secondo, un rimorchio può essere agganciato a diverse motrici, purché queste siano omologate per trainarlo e abbiano il gancio di traino adatto.', 'Le trappole sono ''parte integrante del veicolo'' e ''non può essere agganciato a un altro veicolo''. Entrambe le affermazioni sono errate.', 'Rimorchio = indipendente, agganciabile a diverse motrici compatibili.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24103, 'Quando traini un rimorchio, specialmente se è largo o lungo, è quasi sempre obbligatorio avere gli specchietti retrovisori esterni che ti permettano di vedere bene dietro e ai lati del rimorchio. Questo include spesso lo specchietto destro, soprattutto se il rimorchio è più largo della motrice.', 'La trappola è ''non è obbligatorio''. In molti casi, per garantire una visibilità adeguata del rimorchio, gli specchietti aggiuntivi (anche il destro) sono necessari e quindi obbligatori.', 'Rimorchio = specchietti extra spesso obbligatori per buona visibilità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24104, 'Abbiamo visto prima che gli specchietti possono sporgere al massimo 20 centimetri dalla sagoma del veicolo più largo. 50 centimetri è troppo e non è corretto, indipendentemente dall''altezza da terra.', 'Il valore ''fino a 50 centimetri'' è la trappola. Il limite corretto di sporgenza per gli specchietti è 20 cm.', 'Specchietti = max 20 cm di sporgenza, non 50 cm.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24105, 'Il carico non può sporgere lateralmente oltre la sagoma del veicolo. Le imbarcazioni trasportate su rimorchi T.A.T.S. devono rientrare nella larghezza massima consentita per il veicolo e non possono sporgere lateralmente.', 'La trappola è ''possono sporgere fino a 50 centimetri per ogni lato''. Il carico non può mai sporgere lateralmente oltre la sagoma del veicolo.', 'Carico = non sporge lateralmente, mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24106, 'La patente BE serve per complessi di veicoli leggeri. La patente C serve per autocarri pesanti. Per guidare un autocarro pesante con rimorchio (categoria CE), devi prendere la patente CE specifica, non basta avere la C e la BE. Le categorie sono diverse.', 'La trappola è ''può guidare anche veicoli della categoria CE''. Avere BE e C non ti abilita automaticamente alla CE. Serve un esame specifico per la CE.', 'BE+C non è CE. Per CE serve esame CE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24107, 'Anche i complessi di veicoli con rimorchio, anche se il rimorchio è leggero (fino a 3,5 tonnellate), hanno limiti di velocità specifici (ad esempio 80 km/h in autostrada, 70 km/h sulle strade extraurbane principali) e devono esporre i contrassegni che indicano questi limiti sulla parte posteriore del rimorchio.', 'La trappola è ''non vige l''obbligo''. L''obbligo di apporre i contrassegni di velocità c''è per tutti i complessi con rimorchio, indipendentemente dalla massa del rimorchio (se rientra nella categoria dei complessi).', 'Complesso con rimorchio = sempre adesivi velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24108, 'Le luci di emergenza (segnalazione luminosa di pericolo) si usano solo in caso di pericolo reale, guasto o rallentamento improvviso. Non si usano per segnalare un trasporto speciale o per chiedere agli altri di aumentare la distanza di sicurezza.', 'La trappola è ''occorre tenere in funzione la segnalazione luminosa di pericolo''. Le luci di emergenza hanno uno scopo ben preciso e non vanno usate in questo contesto.', 'Luci emergenza = solo per vero pericolo, non per trasporto animali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24109, 'Questa è una vecchia regola che non vale più. Oggi, i rimorchi hanno una loro targa specifica (targa propria del rimorchio) e non si deve staccare la targa della motrice per applicarla al rimorchio.', 'La trappola è ''staccare la targa della motrice e applicarla nella parte posteriore del rimorchio''. Questa pratica è obsoleta e non più consentita.', 'Rimorchio = targa propria, non si toglie quella della motrice.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24110, 'Se nella carta di circolazione non c''è scritto quanto può trainare il veicolo, significa che quel veicolo NON è omologato per trainare rimorchi. Non significa che può trainare qualsiasi cosa.', 'La trappola è ''atto al traino di rimorchi di qualsiasi massa''. Se il valore manca, il veicolo non è abilitato al traino.', 'Massa rimorchiabile mancante = NO traino.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24111, 'I rimorchi devono fare la revisione periodica, ma la fanno per conto loro, non insieme alla motrice. Hanno le loro scadenze e la loro procedura di revisione separata.', 'La trappola è ''insieme al veicolo trainante''. La revisione del rimorchio è un processo indipendente da quello della motrice.', 'Revisione rimorchio = separata dalla motrice.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24112, 'Il carico non può mai sporgere dalla parte anteriore del veicolo (o del complesso veicolare). Può sporgere solo posteriormente, entro certi limiti e con le dovute segnalazioni.', 'La trappola è ''può sporgere dalla parte anteriore''. Il carico non può sporgere anteriormente per motivi di sicurezza e visibilità.', 'Carico = mai sporgere davanti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24113, 'Se il carico sporge posteriormente, anche sui rimorchi leggeri, deve sempre essere segnalato con l''apposito pannello quadrato a strisce bianche e rosse. Non ci sono eccezioni per i rimorchi leggeri.', 'La trappola è ''senza obbligo di specifiche segnalazioni''. La segnalazione con il pannello è sempre obbligatoria se il carico sporge posteriormente.', 'Carico sporgente dietro = sempre pannello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24114, 'I rimorchi per il trasporto di cavalli (van) possono circolare in autostrada, purché rispettino tutte le norme del Codice della Strada, come limiti di velocità, dimensioni, peso e siano trainati da un veicolo idoneo.', 'La trappola è ''non possono circolare in autostrada''. I van per cavalli sono veicoli a tutti gli effetti e possono circolare in autostrada, rispettando le regole.', 'Van cavalli = sì autostrada, con regole.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24115, 'Quando giri a destra con un veicolo che ha un rimorchio, il rimorchio ''taglia'' la curva, cioè si avvicina di più al marciapiede rispetto alla macchina. Per questo, devi fare molta attenzione a non colpire pedoni o ostacoli con la ruota posteriore destra del rimorchio o della motrice.', 'La frase ''particolare attenzione'' ti avvisa di un pericolo specifico. ''Eventuali pedoni'' indica che il rischio è presente se ci sono persone.', 'Rimorchio stringe in curva: occhio al marciapiede!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24116, 'Il ''fascia di ingombro'' è lo spazio totale che il tuo veicolo e il rimorchio occupano sulla strada. Poiché il rimorchio non segue esattamente la stessa traiettoria della macchina (tende a ''stringere'' la curva), l''ingombro totale è maggiore, specialmente quando giri.', 'La parola ''maggiore'' è la chiave: significa che hai bisogno di più spazio del solito.', 'Rimorchio = più spazio in curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24117, 'In una discesa ripida, il peso del rimorchio spinge in avanti la macchina (motrice). Questa ''forza di spinta'' rende più difficile frenare e può farti perdere il controllo del veicolo. Devi guidare con molta prudenza.', 'Le parole ''forza di spinta'' indicano un effetto fisico importante da considerare.', 'Discesa + rimorchio = spinta extra, frena con cautela.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24118, 'Quando traini un rimorchio, aggiungi peso al tuo veicolo. Più peso significa che il motore deve fare più fatica per accelerare. Per questo, la tua macchina sarà più lenta a prendere velocità, soprattutto se il rimorchio è pieno.', 'La frase ''sensibile riduzione'' significa che noterai un grande cambiamento nella capacità di accelerazione.', 'Rimorchio = meno sprint, più peso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24119, 'Con un rimorchio, il tuo veicolo è più lungo e più difficile da manovrare. È facile non vedere persone o oggetti che si trovano vicino al rimorchio. Per la tua sicurezza e quella degli altri, controlla sempre bene l''area intorno prima di muoverti.', '''Qualsiasi manovra'' significa che devi fare attenzione sempre, non solo in situazioni difficili. ''Bene accertarsi'' sottolinea l''importanza del controllo.', 'Rimorchio = occhi a 360 gradi prima di muovere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24120, 'Questo è un concetto fondamentale: quando la macchina gira, il rimorchio segue una traiettoria più stretta, come se ''tagliasse'' l''angolo. Questo significa che il raggio della curva del rimorchio è più piccolo di quello della macchina.', 'Le parole ''stringere'' e ''raggio inferiore'' sono termini tecnici che descrivono esattamente il comportamento del rimorchio in curva.', 'Il rimorchio stringe la curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24121, 'Se un rimorchio trasporta liquidi (come un''autocisterna), il movimento del liquido all''interno del serbatoio (chiamato ''effetto slosh'') può creare forze che rendono il veicolo molto instabile, specialmente quando giri, freni o acceleri. Questo è un grande pericolo.', 'La frase ''maggiori cause di instabilità'' evidenzia quanto sia pericoloso il movimento dei liquidi.', 'Liquido nel rimorchio = instabilità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24122, 'Il peso del rimorchio che si appoggia sul gancio di traino della macchina è molto importante. Se il carico è troppo o troppo poco, può cambiare l''equilibrio della macchina (l''assetto) e far puntare i fari troppo in alto o troppo in basso, accecando gli altri o non illuminando bene la strada.', '''Non alteri'' significa che il carico deve essere giusto per non cambiare l''equilibrio e la direzione dei fari.', 'Carico gancio = assetto e fari ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24123, 'FALSO. Il rimorchio non segue mai esattamente lo stesso percorso della motrice in curva. Tende sempre a ''stringere'', cioè a percorrere una traiettoria più interna, anche a bassa velocità. Questo è un principio fondamentale della guida con rimorchio.', 'La parola ''sempre'' è una parola ''trappola''. Spesso, affermazioni assolute come ''sempre'' o ''mai'' sono false nei quiz di guida.', 'Rimorchio MAI stesso percorso della motrice.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24124, 'FALSO. Il ruotino pivottante (o ruotino di manovra) serve per spostare il rimorchio a mano quando è staccato dalla macchina o per parcheggiarlo. Quando guidi, deve essere sollevato e bloccato per evitare che tocchi terra, si danneggi o causi problemi durante la marcia.', 'La parola ''deve'' indica un obbligo. In questo caso, l''obbligo è di tenerlo sollevato, non abbassato.', 'Ruotino in alto quando si guida.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24125, 'FALSO. Molti veicoli moderni con sensori di parcheggio sono progettati per trainare rimorchi. Spesso, i sensori posteriori si disattivano automaticamente o si regolano quando agganci un rimorchio, oppure puoi disattivarli manualmente. Non c''è nessun impedimento.', 'La frase ''non è possibile'' è una negazione assoluta che spesso è falsa nei quiz. Non è vero che non si può fare.', 'Sensori e rimorchio: sì, si può!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24126, 'FALSO. Trainare un rimorchio aggiunge peso e resistenza all''aria al tuo veicolo. Anche se guidi a velocità moderata, il motore deve lavorare di più per muovere il peso extra, e questo comporta sempre un aumento del consumo di carburante.', 'La frase ''non comporta un aumento'' è la parte falsa. Il consumo aumenta sempre. ''Se si marcia a velocità moderata'' è un tentativo di renderti la frase credibile, ma non cambia la realtà fisica.', 'Rimorchio = più benzina, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24127, 'Le parti meccaniche in movimento, come quelle del gancio di traino, devono essere sempre pulite e ben lubrificate. Questo serve a farle funzionare bene, a non farle rovinare troppo in fretta e a garantire la sicurezza.', 'La frase ''devono essere mantenute pulite e adeguatamente lubrificate'' indica un''azione obbligatoria e necessaria per la buona manutenzione.', 'Pulito e lubrificato, il gancio è assicurato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24128, 'Il gancio di traino e le sue parti non devono avere ''giochi'' (cioè movimenti eccessivi tra le parti), deformazioni (cambiamenti di forma) o incrinature (piccole rotture). Questi sono tutti segni di usura o danno che rendono il gancio insicuro e potrebbero causarne la rottura.', 'La negazione ''non devono presentare'' è importante: significa che è obbligatorio che queste condizioni negative siano assenti.', 'Niente giochi, niente crepe: la sicurezza non si rompe!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24129, 'Il gancio di traino deve permettere al rimorchio di muoversi un po'' su e giù rispetto alla macchina (oscillazioni verticali). Questo è fondamentale quando la strada non è piatta (ad esempio, in salita, in discesa o su dossi) per evitare che il gancio si blocchi o si danneggi, garantendo una guida più stabile e sicura.', 'La frase ''devono consentire sufficienti oscillazioni in senso verticale'' descrive una caratteristica tecnica necessaria per la funzionalità e la sicurezza del sistema di traino.', 'Oscillazione verticale, sicurezza stradale!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24130, 'Ogni gancio di traino ha un limite massimo di peso che può sopportare in verticale (il carico verticale). È molto importante non superare questo limite, perché un peso eccessivo può compromettere la stabilità del veicolo e danneggiare il gancio, rendendo la guida pericolosa.', 'La parte ''non ecceda il limite indicato dal costruttore'' è cruciale: il limite è sempre specificato e va rispettato rigorosamente.', 'Carico verticale: rispetta il limite, è vitale!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24131, 'L''informazione sul carico verticale massimo che il gancio può sopportare si trova sempre su una piccola targhetta. Questa targhetta è applicata direttamente sul gancio di traino o nelle sue immediate vicinanze, così è facile da consultare.', 'La frase ''indicato in un''apposita targhetta applicata sul gancio di traino'' specifica il luogo esatto dove trovare questa informazione importante.', 'Targhetta sul gancio: il peso massimo è lì, non c''è inganno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24132, 'FALSO. Questa affermazione è l''opposto di quanto abbiamo imparato! Le parti in movimento del gancio di traino *necessitano* di lubrificazione per funzionare bene e non usurarsi. Sgrassare senza lubrificare le renderebbe secche e soggette a usura rapida. Inoltre, la benzina non è un prodotto adatto per la manutenzione meccanica del gancio.', 'Le parole ''non necessitano di lubrificazione'' sono la trappola principale, perché è esattamente il contrario. Anche ''sgrassati con... benzina'' è fuorviante e sbagliato per la manutenzione.', 'Senza lubrificazione, il gancio va in pensione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24133, 'FALSO. Tutti gli organi di traino, senza eccezioni, devono essere di tipo omologato. L''omologazione è una certificazione che garantisce che il gancio è stato testato e rispetta tutte le norme di sicurezza, indipendentemente dal tipo o dal peso del rimorchio che deve trainare.', 'La frase ''possono non essere di tipo omologato, se destinati solo al traino di rimorchi leggeri'' è la trappola. L''omologazione è sempre obbligatoria per la sicurezza.', 'Omologazione sempre, per ogni rimorchio, non si scappa!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24134, 'FALSO. Anche i rimorchi leggeri devono avere le luci funzionanti (frecce, stop, luci di posizione) per essere visibili e segnalare le manovre agli altri utenti della strada. Per questo, il collegamento elettrico tra la motrice e il rimorchio è sempre obbligatorio e fondamentale per la sicurezza.', 'La negazione ''non occorre effettuare il collegamento elettrico'' è la trappola. Il collegamento è sempre necessario per le luci di sicurezza.', 'Luci sempre accese, anche per il leggero, per non avere sorprese!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24135, 'FALSO. Gli organi di traino sono componenti di sicurezza molto importanti. Se si rompono o si danneggiano gravemente, non possono essere riparati con una semplice saldatura. La saldatura potrebbe alterare la resistenza del materiale e rendere il gancio ancora più debole e pericoloso. In questi casi, il gancio deve essere sostituito con uno nuovo e omologato.', 'La frase ''possono essere riparati tramite saldatura'' è la trappola. La saldatura è quasi sempre vietata per componenti strutturali di sicurezza come il gancio di traino.', 'Gancio rotto? Non saldare, ma cambiare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24136, 'FALSO. Concentrare tutto il carico massimo del rimorchio in corrispondenza del gancio di traino è molto pericoloso. Il carico deve essere distribuito in modo equilibrato su tutto il rimorchio. Un carico eccessivo o mal distribuito può rendere il veicolo instabile, specialmente in curva o in frenata, aumentando il rischio di incidenti.', 'La frase ''concentrare il carico massimo in corrispondenza del gancio di traino'' è la trappola. Il carico deve essere distribuito, non concentrato in un unico punto.', 'Carico sul gancio? Non troppo, o il viaggio è un intoppo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24137, 'È vero. Quando trasporti merci con un rimorchio, devi assicurarti che siano ben ferme e stabili. Questo serve a evitare che si muovano, cadano o si rovinino durante il viaggio, garantendo la sicurezza di tutti.', 'La frase ''deve sistemare'' indica un obbligo preciso per il conducente. Non è una scelta, ma una regola di sicurezza.', 'Carico sicuro = viaggio sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24138, 'È vero. Se il rimorchio sta fermo per molto tempo e non puoi sollevare le ruote da terra, è una buona idea aumentare un po'' la pressione degli pneumatici e spostare il rimorchio ogni tanto. Così eviti che le gomme si schiaccino e si deformino (diventino ''ovalizzate'') sempre nello stesso punto.', 'La parola ''ovalizzazione'' si riferisce alla deformazione della gomma che perde la sua forma rotonda. ''Se non è possibile sollevarlo da terra'' indica una soluzione alternativa quando non si può fare la cosa migliore.', 'Rimorchio fermo? Gomme gonfie e ruotate!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24139, 'È vero. Se il rimorchio non viene usato per un lungo periodo, la cosa migliore da fare è sollevare gli pneumatici da terra. Puoi usare dei supporti speciali sotto il telaio. In questo modo, le gomme non subiscono il peso del rimorchio e non si deformano.', 'La frase ''se possibile'' indica che questa è la soluzione ideale e preferibile per la conservazione degli pneumatici.', 'Rimorchio fermo? Gomme su!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24140, 'È falso. La pressione degli pneumatici non è uguale per tutti i veicoli e i rimorchi. Dipende dal modello del veicolo, dal tipo di rimorchio e dal peso che trasporti. Devi sempre controllare il manuale del tuo veicolo e del rimorchio per sapere qual è la pressione giusta.', 'La frase ''deve essere la stessa'' è la parola trappola. Raramente le pressioni sono identiche; ogni veicolo ha le sue specifiche.', 'Pressione gomme: controlla il manuale, non è uguale per tutti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24141, 'Sulle autostrade e sulle strade extraurbane principali, è fondamentale essere ben visibili. Per questo, anche di giorno, devi accendere i fari anabbaglianti o, se la tua auto li ha, le luci di marcia diurna. Questo aumenta la sicurezza per tutti.', 'Le parole ''obbligatorio'' e ''anche di giorno'' sono importanti. Indicano che questa regola vale sempre, non solo di notte. ''O, in alternativa'' ti dà due opzioni per rispettare l''obbligo.', 'Autostrada/Extraurbana = Luci sempre accese (anabbaglianti o diurne).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24142, 'Se i fari della tua auto non sono regolati correttamente, possono causare due problemi: o tu vedi meno bene la strada (se puntano troppo in basso) o dai fastidio agli altri guidatori (se puntano troppo in alto, abbagliandoli).', 'Le espressioni ''errata impostazione'', ''ridurre la visibilità'' e ''abbagliare gli altri'' spiegano le conseguenze negative di un errore nella regolazione dei fari.', 'Fari storti = Tu non vedi o gli altri non vedono.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24143, 'Anche i fari anabbaglianti, che di solito non abbagliano, se non sono regolati bene e puntano troppo in alto, possono dare fastidio agli occhi di chi viene in senso opposto o di chi ti precede.', 'La frase ''male orientati'' è la chiave. Sottolinea che anche un tipo di faro ''sicuro'' come l''anabbagliante può diventare un problema se non è regolato correttamente.', 'Anabbaglianti alti = Abbagli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24144, 'Non basta accendere i fari anabbaglianti. Se le lampadine che usi non sono quelle giuste (non omologate) o sono state montate male, la luce può comunque essere troppo forte o puntare nella direzione sbagliata, abbagliando gli altri.', 'Le parole ''Pur avendo acceso'' indicano che l''azione di accendere non è sufficiente. ''Montate in maniera errata'' o ''non sono omologate'' sono le cause del problema.', 'Lampade non a norma = Problemi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24145, 'Per la tua sicurezza e quella di tutti gli altri sulla strada, tutte le parti del veicolo, incluse le lampade, devono essere approvate e certificate (omologate) secondo le norme. Usare lampade non omologate è vietato dalla legge.', 'Le parole ''non è consentito'' e ''non omologate'' sono chiare: c''è un divieto preciso sull''uso di parti non conformi alle norme.', 'Solo lampade omologate.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24146, 'No, è falso. Come abbiamo imparato, sulle strade extraurbane, anche se c''è il sole, devi accendere gli anabbaglianti o le luci diurne. Le luci di posizione servono solo per essere visti quando sei fermo o per accompagnare altri fari, non per la marcia diurna in extraurbana.', 'La parola ''sufficiente'' è la trappola. Le luci di posizione non sono sufficienti per la marcia diurna su una strada extraurbana.', 'Extraurbana di giorno = Anabbaglianti (o diurne), non solo posizione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24147, 'No, è falso. I fari abbaglianti sono molto potenti e si usano solo di notte, fuori dai centri abitati e solo quando non ci sono altri veicoli che potresti abbagliare. Di giorno sono assolutamente vietati perché abbaglierebbero tutti e causerebbero pericolo.', 'Le parole ''obbligatorio'', ''abbaglianti'' e ''ore diurne'' insieme creano la contraddizione. È proprio l''opposto di ciò che è permesso.', 'Abbaglianti = Solo di notte, senza abbagliare. Mai di giorno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24148, 'No, è falso. Se sei fermo di notte fuori dalla strada (cioè fuori dalla carreggiata, ad esempio in un parcheggio o in una piazzola di sosta), non è obbligatorio tenere accese le luci di posizione. Le accendi se sei fermo sulla carreggiata o sulla banchina, per segnalare la tua presenza e non creare pericolo.', 'La frase ''fuori della carreggiata'' è la chiave. Se sei completamente fuori dalla strada, non è obbligatorio accenderle.', 'Sosta fuori carreggiata = Luci di posizione non obbligatorie.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24149, 'No, è falso. Le luci di posizione, come tutte le luci del veicolo, devono avere colori specifici stabiliti dalla legge per essere riconoscibili. Davanti sono bianche, dietro sono rosse. Non puoi usare lampade di qualsiasi colore, altrimenti il veicolo non sarebbe a norma.', 'La frase ''qualsiasi colore'' è la parola trappola. Le luci hanno colori ben definiti per legge.', 'Luci = Colori specifici per legge.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24150, 'Questa affermazione è VERA. Nei centri abitati, quando è buio (dalla mezz''ora dopo il tramonto a mezz''ora prima dell''alba), è obbligatorio usare le luci anabbaglianti per vedere bene la strada ed essere visti dagli altri, senza però abbagliare nessuno.', 'La frase ''da mezz''ora dopo il tramonto del sole a mezz''ora prima del suo sorgere'' indica il periodo esatto in cui vige l''obbligo. ''Obbligatorio'' significa che devi farlo per forza.', 'Notte in città = Anabbaglianti sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24151, 'Questa affermazione è VERA. Se c''è poca visibilità a causa di pioggia forte, nebbia o neve, devi accendere sia le luci di posizione (per essere visto) sia le luci anabbaglianti (per vedere la strada). Questo ti rende più sicuro.', 'Le parole ''scarsa visibilità'' sono la chiave. ''Obbligatorio'' significa che non puoi scegliere, devi farlo.', 'Brutto tempo = Posizione + Anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24152, 'Questa affermazione è VERA. La luce posteriore per nebbia è molto forte e serve a farti vedere quando la nebbia è così fitta che non si vede quasi nulla (meno di 50 metri). Usala solo se la nebbia è davvero tanta e se la tua auto ha questa luce.', 'La condizione ''visibilità inferiore a 50 metri'' è molto importante. ''Se il veicolo ne è dotato'' significa che non tutte le auto ce l''hanno.', 'Nebbia fitta (<50m) = Fendinebbia posteriore (se c''è).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24153, 'Questa affermazione è VERA. Se di notte parcheggi la tua auto sul bordo della strada in città, puoi usare le luci di sosta. Servono a segnalare la presenza del veicolo senza consumare molta batteria, rendendolo visibile agli altri.', 'La parola ''può'' indica che è una possibilità, non un obbligo. ''Luci di sosta'' sono specifiche per segnalare un veicolo fermo.', 'Sosta notturna in città = Luci di sosta (opzionale).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24154, 'Questa affermazione è FALSA. Le luci abbaglianti sono molto potenti e abbagliano gli altri conducenti. Non è mai obbligatorio tenerle accese per tutto il tempo di notte. Si usano solo fuori dai centri abitati, quando non ci sono altri veicoli e la strada è buia.', 'La parola ''obbligatorio'' è la trappola qui, specialmente se abbinata a ''per tutto il tempo''. Le abbaglianti non sono mai obbligatorie in modo continuativo.', 'Abbaglianti = MAI obbligatori sempre! (Solo fuori città e senza nessuno).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24155, 'Questa affermazione è FALSA. Se di notte parcheggi il veicolo fuori dalla carreggiata (ad esempio, in un''area di sosta o un parcheggio vero e proprio, non sulla strada), non è obbligatorio tenere accese le luci anabbaglianti. Anzi, di solito le luci si spengono.', 'La frase ''fuori dalla carreggiata'' è fondamentale. Le luci anabbaglianti servono per la marcia, non per la sosta fuori strada. ''Obbligatorio'' è la parola trappola.', 'Sosta fuori strada = Luci spente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24156, 'Questa affermazione è FALSA. Se parcheggi la tua auto in un parcheggio autorizzato, non è obbligatorio tenere accese le luci di sosta. Le luci di sosta servono a segnalare il veicolo quando è fermo in condizioni di scarsa visibilità, non in un parcheggio normale.', 'Le parole ''parcheggio autorizzato'' e ''obbligatorio tenere accese per tutto il tempo'' sono le trappole. In un parcheggio sicuro, non c''è bisogno di luci.', 'Parcheggio autorizzato = Luci spente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24157, 'È vero. Quando entri in una galleria, devi sempre accendere i fari anabbaglianti, sia di giorno che di notte. Questo serve per vedere meglio e per essere visto dagli altri veicoli, aumentando la sicurezza.', 'La frase ''anche di giorno'' non è una trappola, ma rafforza la regola: l''obbligo vale sempre, non solo quando è buio.', 'Galleria = Anabbaglianti sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24158, 'È vero. Se la visibilità è scarsa a causa di nebbia, neve o pioggia forte, devi accendere le luci del veicolo. Questo ti aiuta a vedere la strada e, soprattutto, permette agli altri conducenti di vedere la tua auto.', 'La condizione chiave è ''scarsa visibilità''. Le condizioni meteo (nebbia, neve, pioggia) sono esempi di ciò che causa scarsa visibilità.', 'Brutto tempo, poca visibilità = Luci accese!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24159, 'È falso. L''obbligo di accendere i fari anabbaglianti in galleria vale sempre, non solo se la galleria è poco illuminata. Anche se la galleria sembra chiara, devi accendere le luci per essere sempre visibile.', 'La parola trappola è ''solo se''. Questa espressione limita l''obbligo a una condizione specifica, ma in realtà l''obbligo è generale per tutte le gallerie.', '''Solo se'' in galleria? FALSO! Le luci sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24160, 'Quando piove molto forte, la visibilità è bassa. Le luci anabbaglianti ti aiutano a vedere la strada, ma la luce posteriore per nebbia è molto più intensa e serve a far sì che gli altri veicoli ti vedano bene da dietro, aumentando la sicurezza. Quindi, se il tuo veicolo ha questa luce, devi accenderla.', 'La frase ''se il veicolo ne è dotato'' è importante. Significa che l''obbligo vale solo se la tua auto ha questa luce specifica, che non è presente su tutti i modelli.', 'Pioggia forte = Anabbaglianti + Fendinebbia posteriore (se c''è).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24161, 'Con una nevicata molto forte, la visibilità è ridotta, proprio come con la pioggia intensa o la nebbia. Le luci anabbaglianti ti permettono di vedere, e la luce posteriore per nebbia serve a far sì che gli altri automobilisti ti vedano chiaramente da dietro, prevenendo incidenti.', 'Anche qui, ''se il veicolo ne è dotato'' è la chiave. Se la tua auto ha la luce posteriore per nebbia, usala in caso di fitta nevicata. ''Fitta nevicata'' indica una condizione di scarsa visibilità.', 'Neve forte = Anabbaglianti + Fendinebbia posteriore (se c''è).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24162, 'Fuori dai centri abitati, le strade sono spesso più veloci e meno illuminate. Per questo, è obbligatorio tenere accese le luci anabbaglianti sia di giorno che di notte. Questo ti rende più visibile agli altri veicoli, anche quando c''è il sole.', 'La condizione ''fuori dai centri abitati'' è fondamentale. Dentro le città, di giorno, non è sempre obbligatorio. ''Obbligatorio'' significa che non è una scelta, ma una regola da seguire.', 'Fuori città = Anabbaglianti sempre (giorno e notte).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24163, 'I fari anabbaglianti sono progettati per illuminare la strada senza disturbare gli altri. Se però non sono regolati correttamente e puntano troppo in alto, la loro luce può finire negli occhi di chi guida in senso opposto o di chi ti precede, causando un abbagliamento e rendendo difficile la visione.', '''Male orientati'' significa che i fari non sono regolati nella posizione giusta. ''Abbagliare'' è l''effetto di una luce troppo forte che impedisce di vedere bene.', 'Fari storti = Abbaglio per gli altri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24164, 'Di notte, anche se la strada è ben illuminata dai lampioni (illuminazione pubblica), è sempre obbligatorio usare le luci anabbaglianti. Servono sia per vedere meglio la strada, sia per essere visti dagli altri veicoli e dai pedoni.', 'La frase ''anche se l''illuminazione pubblica è sufficiente'' è la parte cruciale. Non importa quanto sia luminosa la strada, di notte gli anabbaglianti sono sempre obbligatori.', 'Notte = Anabbaglianti sempre, anche con lampioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24165, 'Nelle gallerie, anche se sono illuminate, è sempre obbligatorio accendere le luci anabbaglianti. Questo aiuta a mantenere una buona visibilità quando si entra e si esce dalla galleria (per via del cambio di luce) e rende il tuo veicolo più visibile agli altri.', 'La parola ''non è consentito'' è la trappola. È il contrario: è obbligatorio! ''Gallerie illuminate'' non cambia l''obbligo di accendere i fari.', 'Gallerie = Anabbaglianti sempre (anche illuminate).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24166, 'Le luci di posizione sono molto deboli e servono principalmente per segnalare la presenza del veicolo quando è fermo o in condizioni di ottima visibilità (ad esempio, di giorno in città). Non sono abbastanza forti per illuminare la strada o per essere visti adeguatamente quando il veicolo è in movimento, quindi non possono sostituire le luci anabbaglianti.', 'La frase ''sempre consentito in alternativa'' è la trappola. Le luci di posizione non sono quasi mai un''alternativa agli anabbaglianti quando si guida. Sono per la sosta o per essere visti in condizioni di luce molto buona.', 'Posizione = Solo per sosta o visibilità perfetta. Non sostituiscono anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24167, 'L''obbligo di usare le luci anabbaglianti dipende dalle condizioni di luce (giorno/notte), dal luogo (dentro/fuori città) o dalla visibilità (pioggia, nebbia). Non c''è nessuna regola che ti obblighi ad accendere o spegnere le luci in base al tipo di veicolo che stai sorpassando, nemmeno se è un''auto della polizia.', 'La frase ''quando si sorpassa un''auto della polizia'' è la condizione trappola. Non esiste una regola specifica sull''uso delle luci legata al veicolo che si sorpassa.', 'Luci = Condizioni meteo/luce, non chi sorpassi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24168, 'VERO. I catadiottri non producono luce propria, ma la riflettono. Sono come degli ''occhi di gatto'' che diventano visibili quando vengono illuminati, ad esempio dai fari di un''altra auto. Servono a rendere il veicolo visibile anche se non ha le luci accese o se le luci si rompono.', 'La parola chiave è ''riflettono''. Non ''producono'' o ''emettono'' luce.', 'Catadiottri = riflettono, non illuminano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24169, 'VERO. Per legge, i dispositivi di segnalazione luminosa e i catadiottri nella parte posteriore dei veicoli devono essere di colore rosso. Questo colore indica che il veicolo si sta allontanando o è fermo.', 'L''abbinamento ''parte posteriore'' e ''rosso'' è fisso e importante da ricordare.', 'Dietro rosso, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24170, 'VERO. Per i rimorchi e i carrelli-appendice, i catadiottri posteriori hanno una caratteristica speciale: oltre ad essere rossi, devono avere una forma triangolare. Questo li distingue dagli altri veicoli e indica che sono veicoli trainati.', 'Ricorda l''eccezione: ''rimorchi e carrelli-appendice'' hanno catadiottri ''triangolari'' dietro.', 'Rimorchio dietro = triangolo rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24171, 'VERO. Anche i rimorchi e i carrelli-appendice devono essere ben visibili sulla strada, specialmente di notte o in condizioni di scarsa visibilità. Per questo motivo, sono dotati di catadiottri, proprio come i veicoli a motore.', 'La frase ''anche sui rimorchi e sui carrelli-appendice'' sottolinea che non sono esclusi.', 'Tutti i veicoli (anche trainati) hanno catadiottri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24172, 'VERO. Nella parte anteriore dei veicoli (e quindi anche di rimorchi e carrelli-appendice), i catadiottri e le luci devono essere di colore bianco. Questo colore indica che il veicolo sta arrivando.', 'L''abbinamento ''parte davanti'' e ''bianco'' è fisso e importante da ricordare.', 'Davanti bianco, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24173, 'FALSO. I catadiottri non sono luci che si ''accendono''. Sono dispositivi passivi che riflettono la luce esterna. Non hanno un interruttore e non c''è un orario specifico per ''accenderli'' perché sono sempre attivi quando c''è luce da riflettere.', 'La parola trappola è ''vanno accesi''. I catadiottri non si accendono.', 'Catadiottri non si accendono, riflettono!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24174, 'FALSO. Come detto, i catadiottri non si accendono. Le luci di posizione, invece, sono luci vere e proprie che producono luce e si accendono tramite un comando. I catadiottri sono sempre ''attivi'' nel loro compito di riflettere la luce.', 'Ancora una volta, la trappola è ''vanno accesi''. I catadiottri non sono luci attive.', 'Catadiottri non si accendono, non sono luci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24175, 'FALSO. I catadiottri non possono sostituire le luci di posizione. Le luci di posizione sono obbligatorie per rendere il veicolo visibile di notte o in condizioni di scarsa visibilità, perché producono luce propria. I catadiottri sono un aiuto in più per la sicurezza, ma non possono sostituire le luci attive.', 'La parola chiave da non confondere è ''sostituiscono''. I catadiottri non possono sostituire le luci attive.', 'Catadiottri non sostituiscono le luci. Sono un extra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24176, 'I catadiottri sono come dei piccoli specchietti che non fanno luce da soli, ma riflettono la luce dei fari di altri veicoli. Questo aiuta a vedere dove si trova un veicolo e quanto è grande, specialmente quando è buio o c''è poca visibilità.', 'La frase ''presenza e l''ingombro'' significa che i catadiottri mostrano dove si trova il veicolo e quanto spazio occupa sulla strada.', 'Catadiottro = ''Occhio di gatto'' che riflette la luce per farti vedere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24177, 'Sui rimorchi e semirimorchi, i catadiottri di colore bianco sono messi nella parte anteriore. Servono per indicare chiaramente dove inizia il veicolo, rendendolo più visibile a chi arriva frontalmente.', 'La parola ''evidenziare'' significa rendere ben visibile. I catadiottri bianchi sono specifici per la parte davanti dei rimorchi.', 'Bianco = Davanti (come i fari anteriori).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24178, 'Se un veicolo è fermo sulla strada, magari di notte e senza luci accese (o con luci guaste), i catadiottri sono molto importanti. Quando un altro veicolo illumina quello fermo, i catadiottri riflettono la luce e lo rendono visibile, aiutando a prevenire incidenti.', 'La condizione ''se illuminati'' è fondamentale: i catadiottri non producono luce propria. ''In sosta'' significa fermi.', 'Catadiottro = ''Salva-sosta notturna''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24179, 'Se la tua auto si guasta e le luci posteriori non funzionano, i catadiottri sono un aiuto importante. Riflettono la luce delle auto che arrivano da dietro, rendendo il tuo veicolo visibile anche senza le luci accese, specialmente di notte.', 'La frase ''nel caso in cui non funzionino'' evidenzia l''utilità dei catadiottri in situazioni di emergenza o guasto.', 'Catadiottro = ''Luce di emergenza passiva''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24180, 'I catadiottri riflettono la luce, ma non lampeggiano e non possono segnalare una svolta. Gli indicatori di direzione (le frecce) sono luci che lampeggiano per avvisare gli altri che stai per svoltare. Sono due cose diverse con funzioni diverse.', 'La trappola è associare la funzione di ''segnalare la svolta'' ai catadiottri. I catadiottri non hanno questa capacità.', 'Catadiottro = Riflette. Frecce = Lampeggiano per svoltare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24181, 'I catadiottri di colore bianco sono usati per la parte anteriore dei rimorchi e semirimorchi, non sono specifici per veicoli che trasportano materiale infiammabile. Questi veicoli hanno altri segnali speciali (come i pannelli arancioni) per indicare il tipo di carico.', 'La menzione di ''autoveicoli che trasportano materiale infiammabile'' è una distrazione. I catadiottri bianchi hanno una funzione generale di segnalazione anteriore per rimorchi.', 'Bianco = Davanti rimorchi. Non per ''infiammabile''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24182, 'Assolutamente no! I catadiottri riflettono la luce, non producono luce e non lampeggiano. Gli indicatori di direzione sono luci attive che lampeggiano per segnalare una manovra (come una svolta o un cambio di corsia). Non possono essere sostituiti da un catadiottro.', 'La frase ''possono sostituire'' è la parola trappola principale. Implica che una cosa possa fare il lavoro dell''altra, il che è falso per i catadiottri e gli indicatori di direzione.', 'Catadiottro = Riflette. Frecce = Sostituibili? MAI!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24183, 'È VERO. La luce sulla targa posteriore serve proprio a questo: a far sì che tutti possano leggere bene i numeri e le lettere della targa, specialmente quando è buio o c''è poca luce.', 'La frase chiave è ''facile lettura''. Questo indica lo scopo principale dell''illuminazione.', 'Targa illuminata = targa leggibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24184, 'È VERO. La legge è chiara su questo punto: la luce che illumina la targa posteriore deve essere di colore bianco. Non può essere di altri colori.', 'La parola importante è ''bianca''. Ricorda che il colore è specificato e non è a scelta.', 'Targa = luce bianca.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24185, 'È FALSO. La luce della targa si accende insieme alle luci di posizione. Questo significa che non si accende ''solo'' di notte, ma anche di giorno se ci sono condizioni di scarsa visibilità (ad esempio, in galleria, con nebbia fitta o pioggia forte).', 'La parola ''solo'' è una parola trappola molto comune. Spesso, quando vedi ''solo'', la risposta è FALSO perché ci sono altre situazioni possibili.', 'Non ''solo'' di notte, ma con luci di posizione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24186, 'È FALSO. Se sosti ''fuori dalla strada'' (ad esempio, in un parcheggio privato, in un cortile o in un garage), non è necessario che la luce della targa rimanga accesa. Le luci servono per essere visti quando si è sulla strada o in luoghi dove la visibilità è importante per la sicurezza stradale.', 'La frase ''fuori dalla strada'' è fondamentale. Indica che non sei più in un contesto di circolazione stradale dove le regole di visibilità sono obbligatorie.', 'Fuori strada = luci spente (se non serve).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24187, 'La spia delle luci di emergenza (le ''quattro frecce'') è rossa perché indica una situazione di pericolo o di emergenza, come un guasto o un arresto improvviso. Il colore rosso serve per attirare subito la tua attenzione.', 'La parola ''pericolo'' è la chiave. Tutto ciò che è pericoloso o urgente è rosso.', 'Pericolo = Rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24188, 'Se la temperatura dell''acqua di raffreddamento del motore è troppo alta, significa che il motore si sta surriscaldando. Questo può causare gravi danni al motore. Per questo motivo, la spia è rossa, per avvisarti di un problema serio.', 'La ''temperatura dell''acqua di raffreddamento'' alta è un segnale di allarme per il motore.', 'Motore caldo = Rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24189, 'La spia della pressione dell''olio è rossa perché una bassa pressione dell''olio significa che il motore non è lubrificato correttamente. Questo può portare a un guasto grave del motore. È un problema urgente che richiede la tua attenzione immediata.', 'La ''pressione dell''olio'' bassa è un segnale di grave malfunzionamento.', 'Olio basso = Rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24190, 'La spia della cintura di sicurezza è rossa per ricordarti che non l''hai allacciata. Non allacciare la cintura è un rischio per la tua sicurezza in caso di incidente. Il rosso indica un pericolo per te.', 'La ''cintura di sicurezza'' non allacciata è un pericolo per l''occupante.', 'Cintura non messa = Rosso (pericolo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24191, 'La spia del freno a mano è rossa perché se provi a guidare con il freno a mano inserito, puoi danneggiare i freni e la macchina non frena bene. È una situazione di potenziale pericolo o di danno al veicolo.', 'Il ''freno a mano'' inserito mentre si guida è un errore che causa problemi.', 'Freno a mano inserito = Rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24192, 'La spia degli indicatori di direzione (le frecce) non è rossa. È verde. Il colore verde indica che una funzione è attiva e non c''è nessun pericolo, ma solo un''informazione che stai per svoltare.', 'Gli ''indicatori di direzione'' sono per informare, non per segnalare un pericolo.', 'Frecce = Verde (informazione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24193, 'La spia delle luci anabbaglianti non è rossa. È verde. Le luci anabbaglianti sono le luci normali che usi per guidare di notte o con poca visibilità. Il verde indica che sono accese e funzionano correttamente.', 'Le ''luci anabbaglianti'' sono di uso comune, non indicano un problema.', 'Anabbaglianti = Verde (uso normale).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24194, 'La spia delle luci abbaglianti non è rossa. È blu. Le luci abbaglianti sono molto forti e si usano solo in particolari condizioni. Il colore blu è specifico per questa funzione e non indica un pericolo.', 'Le ''luci abbaglianti'' hanno un colore unico per distinguerle.', 'Abbaglianti = Blu (luce forte).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24195, 'La spia delle luci fendinebbia non è rossa. Le luci fendinebbia anteriori hanno una spia verde, mentre quelle posteriori hanno una spia gialla/ambra. Servono per migliorare la visibilità, non segnalano un guasto o un pericolo.', 'Le ''luci fendinebbia'' sono per la visibilità, non per un allarme.', 'Fendinebbia = Verde/Giallo (visibilità).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24196, 'La spia del dispositivo per sbrinare o disappannare il parabrezza non è rossa. È di colore giallo/ambra. Questo dispositivo serve per pulire il vetro dalla condensa o dal ghiaccio, è una funzione normale della macchina e non indica un pericolo.', 'Lo ''sbrinatore'' è una funzione di comfort/visibilità, non un allarme.', 'Sbrinatore = Giallo (funzione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24197, 'Questo simbolo indica i proiettori di profondità, chiamati anche ''abbaglianti''. Quindi, è corretto che si trovi sul comando per accenderli.', 'Nessuna parola trappola. ''Comando di accensione'' è chiaro.', 'Linee dritte = profondità (abbaglianti).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24198, 'La spia che si accende quando usi i proiettori di profondità (abbaglianti) è sempre di colore blu. Questo colore serve a farti capire subito che sono accesi e che devi fare attenzione a non abbagliare gli altri.', 'Nessuna parola trappola. ''Spia a luce blu'' è specifico.', 'Abbaglianti = Spia blu.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24199, 'Falso! La spia dei proiettori di profondità è blu, non verde. Le spie verdi sono usate per altre luci, come gli anabbaglianti o le frecce.', 'La parola trappola è ''luce verde''. Ricorda che per gli abbaglianti è blu.', 'Non verde, ma blu!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24200, 'Falso! Questo simbolo è per i proiettori di profondità (abbaglianti). I proiettori anabbaglianti hanno un simbolo simile, ma le linee sono inclinate verso il basso.', 'La parola trappola è ''anabbaglianti''. Il simbolo è per i ''profondità'' (abbaglianti).', 'Linee dritte = profondità, non anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24201, 'Falso! Questo simbolo indica i fari anteriori di profondità. La luce posteriore per nebbia ha un simbolo diverso: un faro rivolto a destra con linee orizzontali e una linea ondulata che le attraversa.', 'La frase ''luce posteriore per nebbia'' è la trappola. Questo simbolo è per i fari anteriori normali.', 'Non nebbia, non posteriore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24202, 'Falso! Questo simbolo ti dice che i proiettori di profondità sono accesi. Non ti ricorda di spegnere le luci di posizione, che hanno un simbolo diverso e una funzione diversa.', 'La frase ''deve spegnere le luci di posizione'' è la trappola. Il simbolo indica l''accensione di un altro tipo di luce.', 'Accende i fari, non spegne le posizioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24203, 'Questo simbolo rappresenta i proiettori anabbaglianti, cioè le luci che usi normalmente per vedere la strada senza abbagliare chi viene in senso opposto. Quindi, lo trovi sul bottone o sulla leva che li accende.', 'Nessuna parola trappola evidente. Il testo è diretto e descrive correttamente la funzione del simbolo.', 'Simbolo a ''D'' con linee in basso = Anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24204, 'Quando accendi gli anabbaglianti, sul cruscotto si illumina una spia con questo simbolo. Il colore verde indica che le luci sono accese e funzionano correttamente, senza problemi.', 'Nessuna parola trappola evidente. ''Luce verde'' è il colore standard per le luci di marcia normali.', 'Anabbaglianti accesi = Spia verde.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24205, 'Falso! La spia a luce blu è usata per i proiettori abbaglianti, quelli molto forti che si usano solo fuori città e quando non c''è nessuno. Gli anabbaglianti, invece, hanno la spia verde.', 'La parola ''blu'' è la trappola. Ricorda che il blu è per le luci più ''aggressive'' (gli abbaglianti).', 'Blu = Abbaglianti (luce forte).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24206, 'Falso! Questo simbolo è per gli anabbaglianti anteriori. La luce posteriore per nebbia ha un simbolo diverso: è sempre una ''D'' con le linee, ma le linee sono attraversate da un''onda e puntano verso destra (perché è dietro).', 'Le parole ''posteriore per nebbia'' sono la trappola. Indicano una funzione e un simbolo completamente diversi.', 'Nebbia posteriore = Onda e a destra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24207, 'Falso! Questo simbolo è per gli anabbaglianti. Gli abbaglianti hanno un simbolo simile, ma le linee sono dritte (non inclinate verso il basso) e la spia è di colore blu.', 'La parola ''abbaglianti'' è la trappola. È il contrario di anabbaglianti.', 'Abbaglianti = Linee dritte e spia blu.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24208, 'Falso! Questo simbolo è per gli anabbaglianti. Le luci di posizione hanno un simbolo diverso, di solito due piccole luci che si fronteggiano o due semicerchi.', 'Le parole ''luci di posizione'' sono la trappola. Indicano una funzione e un simbolo diversi.', 'Posizione = Due piccole luci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24209, 'Falso! Questo simbolo è per gli anabbaglianti. L''indicatore di direzione (la freccia) è rappresentato da una freccia che punta a sinistra o a destra, a seconda della direzione.', 'Le parole ''indicatore di direzione destro'' sono la trappola. Indicano una funzione e un simbolo completamente diversi.', 'Frecce = Frecce!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24210, 'Questo simbolo, con le due frecce che puntano in direzioni opposte, indica proprio il comando per attivare gli indicatori di direzione, che noi chiamiamo comunemente ''frecce''. Servono per segnalare agli altri utenti della strada la nostra intenzione di svoltare a destra o a sinistra.', 'La frase ''indicatori di direzione'' è il termine tecnico per le ''frecce''.', 'Due frecce opposte = frecce di svolta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24211, 'Sì, è vero. Quando attivi gli indicatori di direzione, sul cruscotto della tua auto si accende una spia con questo simbolo. Questa spia è di colore verde, perché indica un normale funzionamento e non un problema.', 'Le ''spie a luce verde'' indicano sempre che una funzione è attiva e funziona correttamente.', 'Frecce attive = spia verde.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24212, 'Esatto, è vero. Quando metti la freccia per svoltare, la spia sul cruscotto con questo simbolo non solo si accende di verde, ma ''lampeggia'', cioè si accende e si spegne a intermittenza. Questo ti conferma che l''indicatore di direzione è ''azionato'', cioè attivato, e sta funzionando.', 'La parola ''lampeggiante'' è importante: la spia delle frecce deve lampeggiare. ''Azionato'' significa ''attivato''.', 'Frecce = spia verde che lampeggia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24213, 'No, è falso. Le spie di colore rosso sul cruscotto indicano sempre un pericolo, un malfunzionamento grave o qualcosa che richiede attenzione immediata (come la pressione dell''olio bassa o la batteria scarica). La spia degli indicatori di direzione è verde, perché indica un''azione normale e non un problema.', 'Ricorda che le ''spie di colore rosso'' sono sempre un segnale di allarme o pericolo.', 'Rosso = pericolo; Verde = ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24214, 'Falso. Questo simbolo è per gli indicatori di direzione (le frecce). Le ''luci di posizione'' hanno un simbolo diverso, che di solito assomiglia a due semicerchi con dei raggi che escono. Non confondere le due funzioni.', 'Non confondere le ''luci di posizione'' con gli indicatori di direzione. Sono due cose diverse.', 'Frecce non sono luci di posizione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24215, 'Falso. Come abbiamo detto, questo simbolo indica il comando per gli indicatori di direzione, cioè le frecce. Il ''comando per accendere le luci di posizione'' ha un simbolo specifico e diverso da questo.', 'Il ''comando per accendere le luci di posizione'' è una funzione diversa e ha un simbolo proprio.', 'Frecce = direzione, non posizione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24216, 'Il simbolo raffigurato, un doppio triangolo, è il comando per accendere le luci di emergenza della macchina, che servono proprio a segnalare un pericolo agli altri veicoli.', 'La frase ''segnalazione luminosa di pericolo'' descrive esattamente la funzione delle luci di emergenza.', 'Doppio triangolo = luci di pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24217, 'Quando premi il pulsante con questo simbolo, tutte le frecce della tua auto (gli indicatori di direzione) si accendono e spengono insieme, contemporaneamente, per avvisare gli altri di una situazione di pericolo.', 'Le parole ''contemporanea'' e ''tutti gli indicatori di direzione'' sono precise per descrivere l''effetto delle luci di emergenza.', 'Tutti i triangoli = tutte le frecce accese.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24218, 'La spia che si accende quando attivi le luci di emergenza, o il pulsante stesso, è quasi sempre di colore rosso. Il rosso è un colore che attira l''attenzione e indica un avvertimento o un pericolo.', 'Il colore ''rosso'' è tipico per le spie di avvertimento importanti nel cruscotto.', 'Pericolo = Rosso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24219, 'Le luci di emergenza si usano quando c''è un problema o una situazione inaspettata sulla strada, come un guasto all''auto, un incidente o un rallentamento improvviso. Sono un dispositivo di sicurezza per le ''emergenze''.', 'La parola ''emergenza'' è la chiave. Questo dispositivo è fatto per situazioni urgenti.', 'Triangolo = Emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24220, 'FALSO. Il ''segnale mobile di pericolo'' è il triangolo rosso che devi mettere sulla strada dietro la tua auto in caso di guasto. Questo simbolo, invece, indica il comando per le luci di emergenza elettriche della macchina, non il triangolo fisico.', 'Attenzione alla parola ''mobile''. Il ''segnale mobile di pericolo'' è un oggetto fisico, non un comando elettrico dell''auto.', 'Mobile = triangolo da mettere a terra, non un pulsante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24221, 'FALSO. La spia del freno a mano ha un simbolo diverso, di solito un cerchio con una ''P'' o un punto esclamativo all''interno. Questo simbolo (il doppio triangolo) è solo per le luci di emergenza.', 'La frase ''freno a mano inserito'' si riferisce a una spia completamente diversa.', 'Triangolo = pericolo, non freno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24222, 'FALSO. Questo simbolo indica un comando che il conducente deve azionare manualmente. Non tutte le auto accendono automaticamente le luci di emergenza dopo un incidente, e anche se alcune lo fanno, il simbolo rappresenta il pulsante per attivarle, non un sistema automatico.', 'Le parole ''automaticamente'' e ''ad ogni incidente'' sono le trappole. Il simbolo indica un comando manuale, non un sensore automatico universale.', 'Questo è un *comando*, non un sensore automatico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24223, 'È VERO. Ogni volta che cambi corsia, devi sempre usare gli indicatori di direzione (le frecce) per avvisare gli altri conducenti della tua intenzione. Questo aiuta a prevenire incidenti e a mantenere il traffico fluido.', 'La frase chiave è ''ogni cambio di corsia''. Non ci sono eccezioni, ogni volta che ti sposti lateralmente, devi segnalare.', 'Cambio corsia? Freccia sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24224, 'È VERO. Anche se la strada è a senso unico, se ti sposti da una corsia all''altra (ad esempio, dalla destra alla sinistra), devi usare la freccia. Questo serve a comunicare la tua manovra agli altri veicoli che ti seguono o che sono accanto a te.', 'La parte importante è ''anche su strada a senso unico''. Non pensare che il senso unico ti esenti dall''usare la freccia per i cambi di corsia.', 'Spostamento laterale = freccia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24225, 'È VERO. Ogni volta che devi girare (svoltare) a destra o a sinistra, è obbligatorio usare gli indicatori di direzione. Questo avvisa chi ti segue e chi viene dal senso opposto della tua intenzione di cambiare direzione.', 'La parola ''ogni volta'' è fondamentale. Non ci sono eccezioni per le manovre di svolta.', 'Svolta? Freccia sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24226, 'È VERO. Se devi uscire dalla strada principale (carreggiata) per fermarti, devi usare la freccia per segnalare questa manovra. In questo modo, chi ti segue sa che stai per rallentare e spostarti.', 'La frase ''uscire dalla carreggiata'' indica una manovra che richiede sempre segnalazione.', 'Esci dalla strada? Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24227, 'È VERO. Quando riparti da fermo, ad esempio da un parcheggio a lato della strada, e vuoi entrare nel flusso del traffico, devi usare la freccia. Questo avvisa gli altri veicoli che stai per muoverti e occupare la strada.', 'La frase ''immettere nella circolazione'' è la chiave. Ogni volta che entri nel traffico, devi segnalarlo.', 'Rientri nel traffico? Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24228, 'È VERO. Quando sei in autostrada e vuoi uscire, devi spostarti nella corsia di decelerazione (quella per rallentare). Questa manovra deve essere segnalata con la freccia per avvisare gli altri veicoli che stai per lasciare l''autostrada.', 'La ''corsia di decelerazione'' è il punto in cui si inizia la manovra di uscita, e va segnalata.', 'Esci dall''autostrada? Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24229, 'È VERO. Quando entri in autostrada dalla corsia di accelerazione, devi usare la freccia per segnalare la tua intenzione di immetterti nel traffico autostradale. Questo permette ai veicoli già in autostrada di capire la tua manovra e, se possibile, facilitarti l''ingresso.', 'La ''corsia di accelerazione'' è il punto in cui si inizia la manovra di ingresso, e va segnalata.', 'Entri in autostrada? Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24230, 'È FALSO. Anche se la strada è a senso unico, se cambi corsia, devi sempre usare gli indicatori di direzione. Non usare la freccia in questo caso è pericoloso perché gli altri conducenti non sanno cosa intendi fare.', 'La parola ''Non'' all''inizio rende la frase falsa. L''obbligo di usare la freccia per cambiare corsia vale sempre, anche su strada a senso unico.', 'Cambio corsia = freccia, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24231, 'È FALSO. Anche se le carreggiate sono separate da uno spartitraffico, devi comunque usare gli indicatori di direzione ogni volta che fai una manovra, come cambiare corsia, svoltare a un incrocio o uscire dalla strada. La separazione delle carreggiate non elimina l''obbligo di segnalare le tue intenzioni.', 'La frase ''Non è mai necessario'' è una trappola. La parola ''mai'' rende quasi sempre falsa un''affermazione di questo tipo nel codice della strada.', 'Manovra = freccia, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24232, 'È FALSO. Qualsiasi spostamento laterale per fermarsi, sia a destra che a sinistra (se consentito), deve essere segnalato con la freccia. Non segnalare la manovra può creare pericolo per gli altri veicoli.', 'La negazione ''Non si devono usare'' rende la frase falsa. La direzione (sinistra o destra) non cambia l''obbligo di segnalare una manovra di fermata.', 'Spostamento per fermata = freccia, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24233, 'È FALSO. Gli indicatori di direzione (le frecce) servono per segnalare un cambio di direzione o di corsia. Per segnalare una frenata brusca si usano le luci di stop (che si accendono automaticamente) o, in caso di emergenza, le luci di emergenza (le ''quattro frecce''). Usare la freccia destra per frenare è sbagliato e può confondere gli altri.', 'La frase ''indicatori di direzione destri per segnalare che si sta per frenare bruscamente'' è l''errore. Le frecce non hanno questa funzione.', 'Freccia = cambio direzione. Frenata = stop/quattro frecce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24234, 'È FALSO. Entrare in un passo carrabile è una manovra di svolta e di uscita dalla carreggiata. Devi sempre usare la freccia (in questo caso quella destra) per avvisare gli altri conducenti della tua intenzione di lasciare la strada.', 'La negazione ''Non si devono usare'' rende la frase falsa. Ogni volta che si esce dalla carreggiata o si svolta, anche per un passo carrabile, la freccia è obbligatoria.', 'Entri in passo carrabile? Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24235, 'È FALSO. Devi usare gli indicatori di direzione sia quando svolti a sinistra sia quando svolti a destra. Ogni manovra di svolta deve essere segnalata per la sicurezza di tutti.', 'La parte ''ma non quando si svolta a destra'' è l''errore che rende la frase falsa. L''obbligo vale per entrambe le direzioni.', 'Svolta (destra o sinistra) = freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24236, 'È FALSO. Un tornante è una curva molto stretta della strada, ma non è una manovra di cambio di direzione o di corsia rispetto al flusso del traffico. Le frecce si usano per segnalare un''intenzione di cambiare la propria posizione o direzione sulla strada, non per seguire il percorso naturale della strada stessa.', 'La parola ''tornante'' è la chiave. Non è una svolta in un incrocio o un cambio di corsia, ma una curva della strada. Non si usano le frecce per le curve.', 'Freccia = cambio direzione/corsia, non per seguire la curva della strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24237, 'Quando vuoi cambiare corsia, devi sempre usare gli indicatori di direzione (le frecce). Questo serve per far capire agli altri automobilisti la tua intenzione e guidare in sicurezza.', 'La parola ''necessario'' significa che è obbligatorio, non una scelta. Devi sempre farlo.', 'Cambio corsia? Freccia sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24238, 'Prima di iniziare un sorpasso, devi accendere la freccia sinistra. Questo avvisa chi ti segue e chi stai per superare che stai per spostarti per la manovra.', 'La parola ''intenzione'' è importante: devi segnalare prima di agire, non mentre lo stai già facendo.', 'Sorpasso inizia? Freccia sinistra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24239, 'Anche quando parcheggi, devi segnalare la tua manovra. Se parcheggi sul lato sinistro della strada (cosa possibile solo in una strada a senso unico), devi usare la freccia sinistra per avvisare gli altri.', 'Non importa il lato (''margine sinistro''), l''importante è segnalare lo spostamento laterale per parcheggiare.', 'Parcheggi? Freccia del lato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24240, 'Ogni volta che giri (a destra o a sinistra) a un incrocio o per entrare in una via, devi usare gli indicatori di direzione. È fondamentale per la sicurezza di tutti.', 'La frase ''ogni qualvolta'' significa ''sempre''. Non ci sono eccezioni per le svolte.', 'Svolta? Freccia sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24241, 'Quando fai retromarcia, specialmente se devi spostarti un po'' di lato (ad esempio per parcheggiare o uscire da un parcheggio), è utile e necessario usare la freccia per indicare la direzione in cui ti muoverai lateralmente.', 'Le ''manovre di retromarcia'' includono anche gli spostamenti laterali, non solo andare dritto all''indietro.', 'Retromarcia con spostamento? Freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24242, 'La marcia per file parallele significa che ci sono più veicoli che vanno nella stessa direzione, uno accanto all''altro. Se non cambi corsia e rimani nella tua, non devi usare la freccia. La freccia serve solo per segnalare uno spostamento laterale.', 'La parte ''anche se non si effettuano cambiamenti di corsia'' è la chiave. Se non cambi, non serve la freccia.', 'Stessa corsia? Niente freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24243, 'Devi usare la freccia per segnalare l''inizio del sorpasso e poi per segnalare il rientro nella tua corsia. Non devi tenerla accesa per una lunga distanza (500 metri) dopo aver finito la manovra. Si spegne appena hai completato il rientro.', 'La distanza ''per almeno 500 metri dopo'' è la trappola. La freccia si usa solo per la durata della manovra.', 'Freccia: inizio e fine manovra, non per km!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24244, 'È obbligatorio usare la freccia sia quando inizi il sorpasso (freccia sinistra) sia quando lo termini rientrando nella tua corsia (freccia destra). Devi segnalare entrambe le fasi della manovra per la sicurezza.', 'La frase ''ma non quando la si termina'' è sbagliata. Devi segnalare anche la fine del sorpasso.', 'Sorpasso: freccia per uscire E per rientrare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24245, 'Non importa se parcheggi a destra o a sinistra, devi sempre usare la freccia per segnalare la tua intenzione di fermarti e spostarti per parcheggiare. Questo avvisa gli altri automobilisti.', 'La frase ''non è necessario'' è la trappola. È sempre necessario segnalare il parcheggio.', 'Parcheggi? Freccia sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24246, 'Quando ti fermi a un semaforo rosso, non stai facendo una manovra che cambia la tua direzione o la tua posizione laterale. Ti stai semplicemente fermando in attesa. Quindi, non devi usare la freccia.', 'La frase ''si arresta ad un semaforo rosso'' descrive una fermata normale, non una manovra che richiede la freccia.', 'Semaforo rosso? Niente freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24247, 'Se ti fermi perché il traffico è bloccato o c''è un''interruzione della circolazione, non devi usare la freccia destra. La freccia serve per segnalare un cambio di direzione o di corsia, non una semplice fermata nel traffico.', 'La combinazione di ''indicatori di direzione destri'' e ''interruzione della circolazione'' è la trappola. La freccia destra si usa per svoltare o spostarsi a destra, non per una fermata generica nel traffico.', 'Traffico fermo? Niente freccia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24248, 'L''uso dei proiettori a luce abbagliante è vietato, di norma, quando si guida nei centri abitati. Questo perché in città c''è già molta luce (dai lampioni, dai negozi) e gli abbaglianti potrebbero dare fastidio agli altri guidatori e ai pedoni, accecandoli.', 'La frase ''di norma'' significa ''normalmente'' o ''solitamente''. Implica che ci sono delle regole generali, ma potrebbero esserci rare eccezioni. In questo caso, la regola generale è che gli abbaglianti sono vietati in città.', 'In città: Anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24249, 'Fuori dai centri abitati, se l''illuminazione pubblica (i lampioni) non è sufficiente e non ci sono altri veicoli che vengono verso di te o che stai seguendo, è necessario usare i proiettori a luce abbagliante per vedere bene la strada.', 'Le parole chiave sono ''insufficiente'' (non abbastanza luce) e ''non si incrociano altri veicoli''. Se ci fossero altri veicoli, dovresti abbassare gli abbaglianti per non accecarli.', 'Fuori città + buio + solo = Abbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24250, 'Simile alla domanda precedente, se fuori dai centri abitati non c''è proprio illuminazione pubblica (è buio totale) e non ci sono altri veicoli, è fondamentale usare gli abbaglianti per garantire la tua sicurezza e quella degli altri, vedendo bene la strada.', 'La parola ''manca'' significa che l''illuminazione è completamente assente. Anche qui, è cruciale la condizione ''non si incrociano altri veicoli''.', 'Buio totale + solo = Abbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24251, 'Quando stai usando i proiettori a luce abbagliante e vedi che sta arrivando un altro veicolo (o ne stai seguendo uno da vicino), devi subito passare ai proiettori a luce anabbagliante. Questo serve per non accecare l''altro guidatore, che potrebbe perdere il controllo del veicolo.', 'La frase ''va sostituito'' indica un obbligo, non una scelta. È una regola di sicurezza fondamentale.', 'Altri veicoli = Anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24252, 'Questa affermazione è falsa. L''uso dei proiettori a luce abbagliante in caso di nebbia fitta è sconsigliato, sia in città che fuori. La luce abbagliante, infatti, si riflette sulle goccioline d''acqua della nebbia e crea un ''muro'' di luce che peggiora la visibilità, invece di migliorarla. In caso di nebbia, si usano gli anabbaglianti e i fendinebbia (se presenti).', 'La trappola è ''di norma consentito''. In realtà, è il contrario: è sconsigliato. ''Nebbia fitta'' è la condizione che rende gli abbaglianti inutili e pericolosi.', 'Nebbia = Anabbaglianti (o fendinebbia), mai abbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24253, 'Questa affermazione è falsa. Nelle gallerie urbane (cioè in città), anche se a senso unico, l''illuminazione è di solito sufficiente. Usare gli abbaglianti non è necessario e potrebbe comunque dare fastidio ad altri veicoli, anche se vanno nella stessa direzione (ad esempio, attraverso gli specchietti retrovisori).', 'La parola ''necessario'' è la trappola. Non è affatto necessario. ''Urbane'' indica che siamo in un contesto cittadino, dove l''illuminazione è generalmente buona.', 'Gallerie urbane = Anabbaglianti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24254, 'Questa affermazione è falsa. Anche se si trasportano feriti o ammalati gravi e si ha fretta, le regole di sicurezza stradale non cambiano. Non è ''sempre ammesso'' usare gli abbaglianti, perché si rischierebbe di accecare gli altri guidatori e causare incidenti. Si possono usare i segnali di emergenza (sirena, lampeggianti), ma non gli abbaglianti se mettono in pericolo gli altri.', 'La parola ''sempre'' è una grande trappola nei quiz. Molto raramente una cosa è ''sempre'' o ''mai'' ammessa senza condizioni. In questo caso, la sicurezza degli altri utenti della strada prevale.', 'Emergenza non significa accecare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24255, 'Questa affermazione è falsa. I proiettori a luce abbagliante servono per vedere al buio o in condizioni di scarsa visibilità (come di notte o in una galleria non illuminata). Di giorno, anche se si guida contro il sole, gli abbaglianti non aiutano a migliorare la visibilità e potrebbero comunque infastidire gli altri guidatori. Per il sole si usano le alette parasole o gli occhiali da sole.', 'Le parole ''di giorno'' e ''necessario'' sono le trappole. Gli abbaglianti non sono fatti per il giorno o per il sole.', 'Abbaglianti = buio, non sole.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24256, 'Sì, puoi usare i fari abbaglianti a intermittenza (lampeggiando) sia di giorno che di notte per avvisare gli altri utenti della strada di un pericolo e prevenire incidenti. È un segnale utile per richiamare l''attenzione.', 'La frase ''uso intermittente'' significa ''lampeggiare''. ''Avvertimenti utili al fine di evitare incidenti'' indica lo scopo di sicurezza.', 'Lampeggio = avviso di pericolo (sempre consentito).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24257, 'Sì, anche dentro le città (centri abitati) puoi usare gli abbaglianti a intermittenza per avvisare di un pericolo e prevenire incidenti. L''importante è che sia un uso breve e necessario per la sicurezza.', 'La parte importante è ''anche all''interno dei centri abitati''. Molti pensano che in città non si possano usare gli abbaglianti, ma l''uso intermittente per avviso è permesso.', 'Lampeggio pericolo = permesso anche in città.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24258, 'Sì, puoi usare gli abbaglianti a intermittenza per far capire al veicolo che ti precede che hai intenzione di sorpassarlo, sia di giorno che di notte. Questo aiuta a comunicare le tue intenzioni in sicurezza.', '''Segnalare... l''intenzione di sorpassare'' è lo scopo specifico. ''Sia di giorno che di notte'' conferma che il momento non è un limite.', 'Lampeggio = voglio sorpassare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24259, 'Sì, anche all''interno dei centri abitati, se vuoi sorpassare, puoi usare gli abbaglianti a intermittenza per avvisare chi ti precede. Ricorda che il sorpasso in città ha regole più severe, ma il segnale è permesso.', 'Anche qui, ''anche all''interno dei centri abitati'' è la chiave. L''uso intermittente è permesso anche in città per segnalare il sorpasso.', 'Lampeggio sorpasso = permesso anche in città.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24260, 'No, non è vero che puoi usare gli abbaglianti a intermittenza *soltanto* fuori città. Come abbiamo visto, è permesso anche nei centri abitati per avvisare di pericoli o per segnalare un sorpasso.', 'La parola trappola è ''soltanto''. Questa parola rende l''affermazione troppo limitata e quindi falsa.', '''Soltanto'' spesso rende FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24261, 'No, non è vero che puoi usare gli abbaglianti a intermittenza in città *solo di giorno*. È permesso sia di giorno che di notte, come abbiamo visto nelle domande precedenti, per avvisi e sorpassi.', 'Le parole trappola sono ''ma unicamente di giorno''. Questo limita l''uso in modo sbagliato.', '''Unicamente'' spesso rende FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24262, 'No, non è vero che puoi usare gli abbaglianti a intermittenza *solo* quando trasporti feriti o ammalati gravi. Puoi usarli anche per avvisare di pericoli o per segnalare un sorpasso, in situazioni normali.', 'La parola trappola è ''solo''. Questo restringe troppo le possibilità d''uso.', '''Solo quando'' spesso rende FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24263, 'No, non è vero che puoi usare gli abbaglianti a intermittenza *solo* se non c''è luce o se è poca. Puoi usarli anche di giorno, con buona luce, per avvisare o segnalare un sorpasso.', '''Purché l''illuminazione esterna manchi o sia insufficiente'' è una condizione limitante che non si applica all''uso intermittente per segnalazione.', 'L''uso intermittente non dipende dalla luce esterna.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24264, 'No, non è vero che puoi usare gli abbaglianti a intermittenza *esclusivamente* per pericoli immediati. Puoi usarli anche per segnalare l''intenzione di sorpassare, che non è sempre un pericolo immediato.', 'La parola trappola è ''esclusivamente''. Questa parola limita troppo l''uso.', '''Esclusivamente'' spesso rende FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24265, 'I proiettori di profondità (fari abbaglianti) sono molto potenti e servono per vedere bene la strada quando non c''è illuminazione. Ma se c''è il rischio di abbagliare (cioè di accecare temporaneamente) altri utenti della strada, come altri automobilisti, ciclisti o pedoni, devi spegnerli e usare i proiettori anabbaglianti (fari normali). La sicurezza è la cosa più importante.', 'La frase chiave è ''pericolo di abbagliare gli altri utenti della strada''. Questo è il motivo principale per cui devi cambiare i fari.', 'Se abbagli, spegni gli abbaglianti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24266, 'Esatto, la regola è la stessa! I pedoni sono utenti della strada e i fari abbaglianti possono accecarli, rendendo pericoloso per loro attraversare o camminare. Quindi, se vedi dei pedoni e c''è il rischio di abbagliarli, devi passare agli anabbaglianti.', 'Anche qui, ''pericolo di abbagliare i pedoni'' è la condizione fondamentale. I pedoni rientrano nella categoria più ampia di ''altri utenti della strada''.', 'Pedone in vista? Anabbagliante subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24267, 'Sì, è vero. Anche se i veicoli sono su un''altra strada (magari una strada parallela o una che si incrocia più avanti), se i tuoi fari abbaglianti possono raggiungerli e abbagliare i conducenti, devi spegnerli. Il pericolo di abbagliamento non dipende solo dalla tua corsia.', 'La parte ''su altre strade'' potrebbe farti pensare che non sia un problema, ma il punto è sempre il ''pericolo di abbagliare''. L''importante è non creare pericolo.', 'Abbagliare è sempre vietato, anche da lontano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24268, 'Quando stai per incontrare un altro veicolo che viene nella direzione opposta, i tuoi fari abbaglianti e i suoi fari potrebbero creare un effetto di accecamento molto forte. Per questo, devi spegnere i fari di profondità e usare gli anabbaglianti per non disturbare l''altro conducente.', 'La frase ''stanno per incrociare altri veicoli'' indica una situazione molto comune in cui è obbligatorio cambiare i fari.', 'Incrocio? Anabbagliante!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24269, 'Se segui un altro veicolo troppo da vicino con i fari abbaglianti accesi, la luce forte si rifletterà nello specchietto retrovisore del veicolo davanti a te, abbagliando il conducente. Questo è molto pericoloso. Quindi, devi passare agli anabbaglianti.', 'La condizione ''seguono un veicolo a breve distanza'' è cruciale. La distanza è importante per la sicurezza.', 'Segui da vicino? Anabbagliante!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24270, 'Falso! La ragione per cui si spengono i fari di profondità e si usano gli anabbaglianti non è per risparmiare la batteria. Le batterie delle auto moderne sono fatte per sopportare l''uso dei fari. La vera ragione è sempre la sicurezza, per non abbagliare gli altri utenti della strada.', 'La parte ''per evitare di scaricare la batteria'' è la ''parola trappola''. È una motivazione sbagliata per cambiare i fari.', 'Luci non scaricano batteria, ma abbagliano!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24271, 'Falso! Non è vero che devi spegnere i fari abbaglianti solo se il veicolo che ti precede è un''autovettura. Devi farlo per qualsiasi tipo di veicolo (camion, moto, autobus, ecc.) che segui a breve distanza, perché il pericolo di abbagliare il conducente è lo stesso, indipendentemente dal tipo di mezzo.', 'La parola ''solo'' è una ''parola trappola'' molto comune. Spesso, quando una regola viene limitata da ''solo'', la risposta è FALSO. La regola vale per tutti i veicoli.', '''Solo''? Attenzione! La regola vale per tutti i veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24273, 'Questo simbolo, quando indica un problema grave come il surriscaldamento, è sempre associato a una spia di colore rosso. Il rosso nel cruscotto segnala un pericolo che richiede attenzione immediata.', 'Non ci sono parole trappola evidenti in questa domanda, è un''affermazione diretta sulla colorazione standard delle spie di pericolo.', 'Spia rossa = Pericolo immediato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24274, 'Il simbolo mostra un termometro immerso in un liquido. Se la spia è rossa e accesa, significa che la temperatura del liquido di raffreddamento del motore è troppo alta, causando un eccessivo riscaldamento del motore.', 'La parola ''eccessivo'' è importante: non è un normale riscaldamento, ma uno che supera i limiti di sicurezza.', 'Termometro caldo = Motore surriscaldato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24275, 'Questo simbolo è specificamente progettato per avvisare il conducente quando il liquido che raffredda il motore (il liquido di raffreddamento) raggiunge una temperatura troppo elevata, che può danneggiare il motore.', 'Anche qui, ''eccessiva'' sottolinea che si tratta di una condizione anomala e pericolosa, non della normale temperatura di funzionamento.', 'Termometro + onde = Temperatura liquido raffreddamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24276, 'Quando una spia di pericolo si accende, significa che un valore (in questo caso la temperatura del liquido di raffreddamento) ha superato i limiti di sicurezza stabiliti da chi ha costruito l''auto. È un segnale che qualcosa non va come dovrebbe.', 'La frase ''supera i limiti stabiliti dal costruttore'' è una formulazione tipica per indicare un''anomalia che richiede intervento.', 'Spia accesa = Fuori dai limiti di sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24277, 'Molte auto hanno un indicatore (una lancetta) che mostra la temperatura del liquido di raffreddamento. Questa spia ''integra'' quell''indicatore, accendendosi per dare un allarme visivo quando la temperatura indicata supera un certo livello di guardia.', 'La parola ''integra'' può confondere, ma significa che la spia completa la funzione dell''indicatore, trasformando un''informazione (la temperatura) in un avviso di pericolo.', 'Spia = Allarme dell''indicatore di temperatura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24278, 'Il simbolo raffigurato rappresenta un termometro e un liquido, non ha nulla a che fare con il liquido per i tergicristalli. Il simbolo del tergicristallo di solito mostra un parabrezza con uno spruzzo d''acqua.', 'La frase ''bocchettone del serbatoio del liquido tergicristalli'' è la trappola principale, in quanto devia completamente l''attenzione dal significato reale del simbolo.', 'Termometro non è tergicristallo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24279, 'Questo simbolo indica la *temperatura* del liquido di raffreddamento, non il suo *livello*. Per il livello basso del liquido di raffreddamento, di solito c''è un simbolo diverso, spesso un contenitore con un''onda e un segno di minimo.', 'La parola ''livello'' è la trappola. Il simbolo è chiaramente un termometro, quindi si riferisce alla temperatura.', 'Termometro = Temperatura, non livello.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24280, 'Il simbolo raffigurato si riferisce alla temperatura del *liquido di raffreddamento*, non all''olio motore. La spia dell''olio motore (pressione o temperatura) ha solitamente il simbolo di una lattina d''olio.', 'La frase ''temperatura dell''olio di lubrificazione del motore'' è la trappola. Le onde sotto il termometro indicano un liquido a base d''acqua, non olio.', 'Onde = Acqua (liquido raffreddamento), non olio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24281, 'Come spiegato prima, questo simbolo è per la temperatura del liquido di raffreddamento del motore, non per la temperatura dell''olio. Sono due liquidi diversi con funzioni diverse e spie diverse.', 'Ancora una volta, ''temperatura dell''olio'' è la parola chiave che rende l''affermazione falsa. Ricorda la differenza tra liquido di raffreddamento e olio.', 'Onde = Acqua, non olio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24282, 'Questo simbolo è per la temperatura del liquido di raffreddamento del motore. Non ha alcuna relazione con l''olio del cambio di velocità. Il cambio ha i suoi specifici indicatori o spie, se presenti.', 'La trappola qui è doppia: ''olio di lubrificazione'' e ''cambio di velocità''. Il simbolo non si riferisce né all''olio né al cambio, ma al liquido di raffreddamento del motore.', 'Termometro + onde = Motore, non cambio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24283, 'VERO. Il ''generatore di corrente'' è un altro nome per l''alternatore. Se la spia rossa della batteria si accende mentre guidi, significa che l''alternatore non sta producendo elettricità per ricaricare la batteria. Questo è un problema serio perché la batteria si scaricherà e l''auto potrebbe fermarsi.', 'La frase ''generatore di corrente'' è un sinonimo di ''alternatore''. Non è una trappola, ma è utile conoscerlo per capire meglio.', 'Spia rossa batteria = alternatore non carica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24284, 'VERO. Se la spia rossa della batteria si accende, significa proprio che c''è un problema nel sistema di ricarica e la batteria non sta ricevendo l''energia necessaria per mantenersi carica. Questo può portare la batteria a scaricarsi completamente.', 'La frase ''non si sta ricaricando come previsto'' indica che c''è un malfunzionamento nel processo normale di ricarica.', 'Spia rossa batteria = batteria non si ricarica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24285, 'VERO. L''alternatore è il componente dell''auto che produce elettricità per far funzionare i sistemi elettrici e per ricaricare la batteria. Se la spia rossa della batteria si accende, la causa più comune è proprio un malfunzionamento dell''alternatore, che non riesce più a ricaricare la batteria.', 'Nessuna parola trappola evidente. ''Alternatore'' è il termine tecnico corretto per il componente che ricarica la batteria.', 'Spia rossa batteria = alternatore guasto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24286, 'VERO. La funzione principale di questa spia rossa è proprio quella di avvisare il conducente se c''è un problema nel sistema di ricarica della batteria, cioè se l''alternatore non sta facendo il suo lavoro correttamente.', 'La frase ''permette di capire'' descrive la funzione informativa della spia, che serve a segnalare un problema.', 'Spia rossa batteria = controlla la ricarica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24287, 'FALSO. La spia indica un problema al *sistema di ricarica*, non che la batteria è *già* completamente scarica. Se la batteria fosse completamente scarica, l''auto non si accenderebbe o si fermerebbe subito. La spia ti avvisa che la batteria *si scaricherà* se non risolvi il problema.', 'La parola ''completamente scarica'' è la trappola. La spia segnala un problema *durante la marcia*, non lo stato finale della batteria.', 'Spia rossa batteria = problema ricarica, non batteria già morta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24288, 'FALSO. L''accensione della spia indica un problema al *sistema di ricarica*, che potrebbe essere l''alternatore, la cinghia dell''alternatore, un cavo o un fusibile. Non significa automaticamente che la batteria sia da sostituire. Potrebbe essere la batteria in buone condizioni ma non ricaricata.', 'La frase ''sostituire subito la batteria'' è la trappola. La spia indica un problema più ampio al sistema elettrico, non solo alla batteria.', 'Spia rossa batteria = problema ricarica, non per forza batteria da cambiare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24289, 'FALSO. Invertire i cavi della batteria è un errore molto grave che può causare danni seri all''impianto elettrico dell''auto e non è mai la soluzione a un problema di ricarica. I cavi devono essere sempre collegati correttamente (positivo con positivo, negativo con negativo).', 'La frase ''invertire l''allacciamento dei cavi'' è una trappola pericolosa. Non si deve mai fare!', 'Spia rossa batteria = non toccare i cavi, mai invertirli!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24290, 'FALSO. La spia rossa della batteria indica un *mancato* caricamento o un caricamento insufficiente della batteria. Un ''sovraccarico'' significa che la batteria riceve troppa energia, il che è un problema diverso e meno comune, e non è segnalato da questa spia.', 'La parola ''sovraccarica'' è la trappola. La spia indica il problema opposto: la batteria non si carica o si carica male.', 'Spia rossa batteria = non carica, non sovraccarica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24291, 'Il simbolo raffigurato è proprio quello che indica la pressione dell''olio (il lubrificante) nel motore. Se la pressione è troppo bassa, il motore non è lubrificato bene.', 'La parola ''lubrificante'' è un altro modo per dire ''olio motore''.', 'Olio che gocciola = pressione olio motore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24292, 'Sì, questa spia è una delle più importanti e pericolose, per questo è sempre di colore rosso. Le spie rosse indicano un pericolo grave che richiede attenzione immediata.', 'Nessuna parola trappola evidente. ''Può essere posto'' indica una possibilità, che in questo caso è vera.', 'Spia olio = sempre rossa, pericolo grave.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24293, 'Quando una spia rossa di pericolo è spenta, significa che non c''è nessun problema. Quindi, se la spia dell''olio è spenta, la pressione dell''olio è normale e tutto funziona correttamente.', 'La condizione ''se spenta durante la marcia'' è la chiave per capire che non c''è un problema.', 'Spia rossa spenta = tutto ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24294, 'Se la spia dell''olio si accende mentre guidi, significa che la pressione dell''olio è troppo bassa. Questo è un problema serio perché il motore non viene lubrificato correttamente.', '''Insufficiente pressione'' è il problema specifico indicato da questa spia.', 'Spia olio accesa = pressione bassa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24295, 'La pressione bassa dell''olio è molto pericolosa per il motore. Se non c''è abbastanza pressione, le parti del motore non vengono lubrificate e possono rompersi. Per questo, devi fermare subito il motore per evitare danni gravi.', '''Arrestare subito il motore'' e ''gravi danni'' sottolineano l''urgenza e la serietà del problema.', 'Spia olio accesa = ferma subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24296, 'Questa spia è sempre di colore rosso perché indica un pericolo grave e immediato per il motore. Le spie gialle/ambra indicano un''anomalia che richiede attenzione ma non un pericolo immediato.', '''Giallo ambra'' è la parola trappola. Ricorda che le spie rosse sono per pericoli gravi.', 'Olio = rosso, mai giallo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24297, 'Questa spia indica la *pressione* dell''olio, non la sua *temperatura*. Per la temperatura dell''olio c''è un''altra spia (di solito con un simbolo di termometro).', '''Temperatura troppo bassa'' è la trappola. La spia è per la *pressione*.', 'Olio gocciola = pressione, non temperatura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24298, 'Questa spia indica un problema di *pressione* dell''olio, non quanto olio il motore sta consumando. Il consumo di olio si controlla con l''astina di livello, non con questa spia.', '''Consuma troppo olio'' è la trappola. La spia non misura il consumo.', 'Pressione, non consumo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24299, 'Questa spia si riferisce all''olio del *motore*, non all''olio del *cambio di velocità*. Sono due circuiti diversi e hanno spie diverse.', '''Cambio di velocità'' è la trappola. La spia è per il *motore*. Anche ''troppo denso'' è un dettaglio irrilevante per questa spia.', 'Olio motore, non cambio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24300, 'La spia indica un problema di *pressione* dell''olio, non che è ora di cambiarlo. Per sapere quando cambiare l''olio, si guarda il libretto di manutenzione dell''auto o il contachilometri.', '''Bisogna cambiare l''olio'' è la trappola. La spia non è un promemoria per la manutenzione.', 'Pressione, non cambio olio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24301, 'Il simbolo raffigurato è la spia dei freni. Le spie di colore rosso indicano sempre un pericolo grave o un problema che richiede attenzione immediata per la sicurezza del veicolo e dei passeggeri. I freni sono un sistema fondamentale per la sicurezza, quindi la loro spia è rossa.', 'La frase chiave è ''colore rosso''. Ricorda che il rosso indica sempre un''urgenza o un pericolo grave.', 'Spia rossa = Pericolo! Freni = Urgente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24302, 'Questo simbolo (un cerchio con un punto esclamativo e due parentesi curve ai lati) è universalmente riconosciuto come la spia dell''impianto frenante. Indica che c''è un problema o un malfunzionamento in una parte di questo sistema vitale.', '''funzionamento difettoso'' significa che qualcosa non sta lavorando come dovrebbe. Non è un semplice avviso, ma un problema.', 'Simbolo freni = Problema ai freni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24303, 'Le guarnizioni dei freni (chiamate anche pastiglie) si consumano con l''uso. Quando sono troppo usurate, il sistema frenante non funziona più in modo efficace e la spia si accende per avvisarti che è ora di sostituirle, prima che diventino pericolose.', '''eccessiva usura'' significa che le parti sono troppo consumate e non svolgono più bene il loro lavoro.', 'Spia freni accesa = Controlla le pastiglie!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24304, 'Il liquido idraulico dei freni è essenziale per trasmettere la forza dal pedale alle ruote e far frenare l''auto. Se il livello di questo liquido è troppo basso, i freni potrebbero non funzionare correttamente o smettere di funzionare del tutto. La spia ti avvisa di questo pericolo.', '''scarso livello del liquido idraulico'' indica una quantità insufficiente di un fluido vitale per il sistema.', 'Spia freni accesa = Controlla il liquido!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24305, 'Poiché la spia dei freni è rossa e indica un problema grave, è fondamentale agire subito. Ignorare questa spia può portare a incidenti molto pericolosi. Devi portare l''auto da un meccanico il prima possibile per un controllo e una riparazione.', '''rapidamente'' sottolinea l''urgenza dell''intervento. Non è qualcosa che puoi rimandare.', 'Spia freni accesa = Subito dal meccanico!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24306, 'Questa spia è specifica per l''impianto frenante. Se ci fosse un problema alla centralina elettronica generale del veicolo, si accenderebbe un''altra spia, spesso quella del motore (a forma di motore) o una spia generica di avaria, non questa.', '''centralina elettronica è fuori uso'' è un problema troppo generico e non è segnalato da questa spia specifica dei freni.', 'Spia freni = Solo freni, non centralina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24307, 'Il tagliando è una manutenzione programmata che si fa a intervalli regolari (ad esempio ogni anno o ogni tot chilometri). Non è un''emergenza. Questa spia, essendo rossa, indica un problema immediato e grave ai freni, non un promemoria per il tagliando.', '''tagliando periodico'' e ''entro 500 chilometri'' sono termini che si riferiscono a manutenzione programmata, non a un guasto improvviso.', 'Spia freni = Emergenza, non tagliando.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24308, 'La revisione periodica è un controllo obbligatorio dello stato generale del veicolo, con scadenze stabilite dalla legge (ad esempio ogni 2 anni). Questa spia segnala un problema ai freni che richiede attenzione immediata, non la scadenza della revisione.', '''revisione periodica di legge'' e ''entro un mese'' si riferiscono a scadenze legali, non a un guasto improvviso e pericoloso.', 'Spia freni = Guasto, non revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24309, 'L''estintore di bordo, se presente, ha un simbolo specifico che lo rappresenta (spesso una fiamma barrata o un estintore stilizzato). Questo simbolo è chiaramente legato all''impianto frenante, non a un estintore.', '''estintore di bordo'' è un oggetto completamente diverso e ha un simbolo differente.', 'Simbolo freni = Non estintore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24310, 'L''alta tensione ha simboli specifici, come un fulmine o un triangolo con un fulmine, per avvisare del pericolo elettrico. Questo simbolo è invece dedicato all''impianto frenante del veicolo.', '''alta tensione'' si riferisce a un pericolo elettrico, non a un problema meccanico dei freni.', 'Simbolo freni = Non alta tensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24311, 'Le portiere aperte o chiuse male hanno una spia dedicata, che di solito mostra l''immagine stilizzata di un''auto con una portiera aperta. Questa spia è specifica per i freni e non ha nulla a che fare con le portiere.', '''portiere aperte o chiuse non correttamente'' è un problema diverso, con una spia diversa e meno grave di un problema ai freni.', 'Spia freni = Non portiere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24312, 'Questa spia indica un problema di sicurezza importante: la cintura di sicurezza non è allacciata. Per questo motivo, è di colore rosso, che segnala un pericolo o un''azione immediata da compiere.', 'Non ci sono parole trappola evidenti in questa domanda. Il punto chiave è associare il colore rosso a un''allerta di sicurezza.', 'Rosso = Pericolo! Metti la cintura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24313, 'Esatto! La spia rossa con questo simbolo si accende proprio per avvisarti che tu (il conducente) o un passeggero non avete allacciato la cintura di sicurezza, specialmente quando l''auto è in movimento.', 'La frase ''durante la marcia'' è importante. La spia potrebbe accendersi brevemente all''avvio, ma la sua funzione di avviso è cruciale quando si guida.', 'Spia rossa + cintura = Allarme! Allaccia subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24314, 'Molte auto moderne, oltre alla luce rossa, emettono anche un suono (un ''bip'' o un campanello) per essere sicure che il conducente noti l''avviso e allacci la cintura. Questo rende l''allarme più efficace.', 'La locuzione ''in genere'' significa ''di solito'' o ''nella maggior parte dei casi''. Non tutte le auto potrebbero avere il segnale acustico, ma è una caratteristica molto comune per aumentare la sicurezza.', 'Rosso + Bip = Non puoi ignorarlo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24315, 'Falso! Questa è una spia di sicurezza fondamentale. Non esiste un pulsante per ''spegnerla'' e continuare a guidare senza cintura. Il suo scopo è obbligarti ad allacciarla per la tua sicurezza e quella degli altri.', 'Le parole ''disattivata con apposito comando'' sono la trappola. Implicano che tu possa scegliere di ignorare la sicurezza, cosa che non è permessa per le cinture.', 'La sicurezza non si ''spegne'' con un pulsante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24316, 'No, è falso. Come abbiamo detto, le spie di pericolo grave o di azione immediata sono sempre rosse. Le spie gialle o arancioni indicano un avviso meno urgente o un malfunzionamento che non richiede un''azione immediata (ad esempio, livello basso del carburante).', 'La parola ''giallo'' è la trappola. Ricorda che il colore della spia è fondamentale per capire la gravità dell''avviso.', 'Cintura = Rosso (pericolo), non Giallo (avviso).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24317, 'Falso. Il pretensionatore è un sistema di sicurezza che, in caso di incidente, stringe automaticamente la cintura per tenerti più fermo. Non è qualcosa che il conducente può ''regolare'' con un pulsante. Il simbolo indica solo l''obbligo di allacciare la cintura.', 'La frase ''regolare le modalità di azione del pretensionatore'' è la trappola. I sistemi di sicurezza come il pretensionatore funzionano in automatico e non sono regolabili dal conducente.', 'Cintura = Metti e basta. Non si ''regola'' il pretensionatore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24318, 'Anche se indossi la cintura di sicurezza, non devi modificarla o fare in modo che non funzioni bene. La cintura deve essere sempre in perfette condizioni per proteggerti. Se la alteri, rischi una multa.', 'La frase chiave è ''alteri o ostacoli il normale funzionamento''. Significa che non devi cambiare la cintura o impedirle di lavorare come dovrebbe, anche se la indossi.', 'Cintura modificata = multa assicurata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24319, 'Questa affermazione è vera. La cintura di sicurezza serve proprio a questo: in caso di frenata improvvisa o incidente, ti tiene fermo sul sedile e ti impedisce di sbattere contro il parabrezza o altre parti dell''auto.', 'Non ci sono parole trappola particolari. Il concetto è una conseguenza diretta e logica della funzione della cintura di sicurezza.', 'Senza cintura, volo assicurato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24320, 'Questa affermazione è falsa. Gli airbag sono un sistema di sicurezza aggiuntivo, ma non sostituiscono la cintura. Anzi, gli airbag funzionano al meglio solo se la cintura è allacciata. Senza cintura, l''airbag potrebbe anche essere pericoloso.', 'La parola trappola è ''si può fare a meno''. Questo suggerisce che la cintura non sia necessaria, ma è sbagliato. Airbag e cintura lavorano insieme.', 'Airbag + Cintura = Doppia sicurezza. Mai senza cintura!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24321, 'Questa affermazione è falsa. Le cinture di sicurezza vanno allacciate sempre, a qualsiasi velocità e anche per brevi tragitti. Gli incidenti possono avvenire anche a basse velocità e la cintura è fondamentale per la tua sicurezza in ogni situazione.', 'La parola trappola è ''solo''. Questo limite di velocità è sbagliato. La cintura è obbligatoria sempre, non solo sopra i 30 km/h.', 'Cintura sempre, velocità mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24322, 'Se metti un seggiolino per bambini sul sedile davanti, con il bambino che guarda indietro (cioè lo schienale è verso il parabrezza), e l''airbag si apre in caso di incidente, può essere molto pericoloso per il bambino. Per questo, se il veicolo ha il comando per spegnere l''airbag, devi farlo.', 'La frase ''schienale rivolto verso il parabrezza'' indica che il bambino è girato all''indietro. Questa è la posizione più pericolosa per l''airbag, che deve essere disattivato.', 'Seggiolino all''indietro davanti? Airbag spento!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24323, 'Se la tua auto non ha un modo per spegnere l''airbag del passeggero, non puoi mettere un seggiolino per bambini sul sedile davanti, anche se il bambino è girato in avanti (schienale rivolto verso la strada). L''airbag potrebbe comunque causare danni gravi. La regola generale è: se non puoi spegnere l''airbag, il seggiolino va dietro.', 'La frase ''non deve essere sistemato'' indica un divieto. Anche se il bambino è ''schienale rivolto verso la strada'' (cioè guarda avanti), senza la possibilità di disattivare l''airbag, il sedile anteriore non è sicuro.', 'Niente disattivazione airbag? Seggiolino sempre dietro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24325, 'L''airbag e le cinture di sicurezza lavorano insieme per proteggerti. L''airbag è un sistema di protezione aggiuntivo, ma non sostituisce le cinture. Le cinture ti tengono fermo e ti impediscono di sbattere contro l''airbag quando si apre, evitando lesioni gravi. È sempre obbligatorio indossare le cinture.', 'La frase ''non vi è l''obbligo'' è la parola trappola. Implica che non è necessario, ma è FALSO. L''obbligo di indossare le cinture c''è sempre, anche con l''airbag.', 'Airbag + Cinture = Sicurezza massima. Cinture SEMPRE!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24326, 'Il poggiatesta è un elemento di sicurezza fondamentale. La sua funzione principale è proprio quella di proteggere il collo e la testa in caso di incidente, specialmente in un tamponamento (quando un''auto ti colpisce da dietro). Fermando il movimento improvviso della testa all''indietro, previene il ''colpo di frusta'', una lesione molto dolorosa al collo.', 'La frase ''prevenire il colpo di frusta'' indica chiaramente la funzione protettiva del poggiatesta. Non ci sono parole trappola particolari qui, il significato è diretto.', 'Poggiatesta = Protezione collo in caso di urto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24327, 'Perché il poggiatesta sia efficace e ti protegga davvero, deve essere regolato bene. Questo significa che la parte superiore del poggiatesta deve essere all''altezza della parte superiore della tua testa e deve essere il più vicino possibile alla nuca. Se è troppo basso o troppo lontano, non può fermare la testa correttamente e la protezione diminuisce.', 'La parola chiave è ''correttamente''. Un poggiatesta non regolato bene perde la sua efficacia. Ricorda che ''sia in altezza che in inclinazione'' sono entrambi aspetti importanti della regolazione.', 'Regolazione giusta = Sicurezza garantita.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24328, 'Questa affermazione è falsa. Il poggiatesta non serve per rilassare i muscoli mentre guidi. La sua funzione è di sicurezza attiva, cioè proteggere in caso di incidente. Se lo usi per appoggiare la testa e rilassarti durante la guida, potresti anche non avere la postura corretta per reagire prontamente o per essere protetto in caso di emergenza.', 'La frase ''rilassare la muscolatura'' è la trappola. Il poggiatesta non è un cuscino per il comfort, ma un dispositivo di sicurezza. Non confondere comfort con sicurezza.', 'Poggiatesta = Sicurezza, non relax.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24329, 'Questa affermazione è completamente falsa. Il poggiatesta ha una funzione di sicurezza molto importante, come abbiamo già detto, per proteggere il collo e la testa in caso di incidente. Non è un elemento decorativo o ''estetico''. La sua presenza e la sua forma sono dettate da studi sulla sicurezza e sulla protezione dei passeggeri.', 'La frase ''non di sicurezza, ma estetica'' è la trappola principale, perché ribalta completamente la verità. Il poggiatesta è l''esatto contrario: è un elemento di sicurezza, non di estetica.', 'Poggiatesta = Sicurezza, mai estetica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24330, 'Questa affermazione è VERA. Le donne in gravidanza sono obbligate a usare la cintura di sicurezza, ma se hanno un certificato medico che attesta un rischio specifico per la loro salute o quella del bambino, allora possono essere esentate dall''obbligo.', 'La parola chiave è ''certificate''. Senza un certificato medico che attesti un rischio, l''obbligo rimane.', 'Gravidanza + Certificato = Esenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24331, 'Questa affermazione è VERA. Se una persona ha una malattia particolare e un medico certifica che indossare la cintura di sicurezza potrebbe essere pericoloso o dannoso per la sua salute, allora quella persona è esentata dall''obbligo.', 'Anche qui, la parola ''certificate'' è fondamentale. Non basta avere una malattia, serve un documento ufficiale del medico.', 'Malattia + Certificato = Esenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24332, 'Questa affermazione è VERA. Gli istruttori di guida, quando stanno svolgendo il loro lavoro (cioè insegnando a guidare), non sono obbligati a usare la cintura. Questo perché potrebbero aver bisogno di muoversi rapidamente per intervenire sul volante o sui pedali in caso di emergenza.', 'La frase ''nello svolgimento della loro professione'' è importante. Se l''istruttore guida per conto suo, deve mettere la cintura.', 'Istruttore in servizio = No cintura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24333, 'Questa affermazione è FALSA. Anche il postino, come la maggior parte dei conducenti, ha l''obbligo di agganciare la cintura di sicurezza durante l''attività lavorativa. Non ci sono esenzioni generali per questa categoria, a meno di specifiche e rare eccezioni legate a particolari tipi di veicoli o servizi di raccolta e distribuzione a domicilio con fermate molto frequenti, ma non è la regola generale.', 'La frase ''non ha l''obbligo'' è la trappola. In generale, l''obbligo c''è.', 'Postino = Cintura (salvo eccezioni molto specifiche).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24334, 'Questa affermazione è FALSA. L''età non è un motivo per non indossare la cintura di sicurezza. Tutti i conducenti e i passeggeri, indipendentemente dall''età (a parte i bambini che usano seggiolini specifici), devono sempre usare la cintura.', 'La parte ''oltre 65 anni di età'' è una distrazione. L''età non dà esenzioni.', 'Età non conta, la cintura si porta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24335, 'Questa affermazione è FALSA. Chi guida con il ''foglio rosa'' (l''autorizzazione ad esercitarsi) è assolutamente obbligato a usare la cintura di sicurezza. Anzi, deve essere ancora più attento alle regole.', 'La frase ''non è obbligato'' è l''errore. L''obbligo c''è eccome!', 'Foglio rosa = Cintura SEMPRE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24336, 'Il casco è un dispositivo di sicurezza molto importante. È sempre obbligatorio per chi guida un ciclomotore a due ruote, per proteggere la testa in caso di caduta o incidente.', 'La parola ''obbligatorio'' significa che è una regola che devi seguire per legge. Non ci sono eccezioni per i ciclomotori a due ruote.', 'Ciclomotore a due ruote = casco sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24337, 'I motocicli (le moto) non hanno una ''gabbia'' di protezione (cellula di sicurezza) o cinture di sicurezza come le auto. Per questo motivo, il casco è l''unica protezione per la testa ed è sempre obbligatorio per il conducente.', 'La frase ''non dotati di cellula di sicurezza e di dispositivi di ritenuta'' è la chiave. Se un veicolo a due ruote non ha queste protezioni, il casco è obbligatorio.', 'Moto senza ''gabbia'' = casco obbligatorio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24338, 'Anche il passeggero, cioè la persona che sta dietro al conducente, deve indossare il casco. Se il motociclo non ha una struttura che lo protegge (come un''auto), il casco è obbligatorio anche per chi è trasportato, per la sua sicurezza.', 'La parola ''passeggero'' indica che l''obbligo non è solo per chi guida, ma anche per chi viene trasportato. La condizione ''privo di cellula di sicurezza e sistemi di ritenuta'' è la stessa del conducente.', 'Su moto senza ''gabbia'', casco per tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24339, 'Non importa l''età del passeggero, che sia minorenne o maggiorenne. Su un ciclomotore a due ruote, il casco è sempre obbligatorio per tutti, per garantire la massima sicurezza a chiunque sia a bordo.', 'La frase ''anche se maggiorenne'' è importante. A volte si pensa che solo i minorenni debbano indossarlo, ma non è così. L''età non cambia l''obbligo.', 'Ciclomotore a due ruote, passeggero (qualsiasi età) = casco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24340, 'Questa affermazione è falsa. Il casco è obbligatorio per tutti i conducenti di ciclomotori a due ruote, non solo per i minorenni. L''età non cambia l''obbligo di indossare il casco per la propria sicurezza.', 'La parola ''solo'' è una trappola. Implica una limitazione che non esiste. Il casco è obbligatorio per tutti, a prescindere dall''età.', 'Casco sempre, età non conta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24341, 'Questa affermazione è falsa. Non importa che patente hai (anche la patente B per l''auto). Se guidi un ciclomotore a due ruote, il casco è sempre obbligatorio per la tua sicurezza. La patente B non ti esenta da questa regola.', 'La frase ''non è obbligatorio'' rende falsa l''affermazione. La patente della categoria B non ti dà un''esenzione dall''obbligo del casco sui ciclomotori a due ruote.', 'Patente B non toglie il casco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24342, 'Questa affermazione è falsa. Il casco è sempre obbligatorio per i conducenti di ciclomotori a due ruote. È una regola fondamentale per la sicurezza di chi guida e del passeggero.', 'La negazione ''non è obbligatorio'' è la parola trappola principale. Il casco è sempre obbligatorio per i ciclomotori a due ruote.', 'Ciclomotore a due ruote = casco SEMPRE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24343, 'VERO. Le cinture di sicurezza sono fatte proprio per proteggere chi è in macchina, sia il guidatore che i passeggeri, e per ridurre i danni se succede un incidente.', 'La frase chiave è ''limitare i danni''. Questo è lo scopo principale delle cinture.', 'Cintura = Protezione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24344, 'VERO. La legge dice che tutti devono mettere la cintura: chi guida e tutti i passeggeri, sia davanti che dietro, se l''auto ha le cinture.', 'Attenzione a ''sia dal conducente che dai passeggeri'': l''obbligo è per tutti.', 'Tutti allacciati, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24345, 'VERO. Le cinture, come tutte le parti importanti dell''auto, devono essere controllate ogni tanto. Così si vede se sono ancora buone e funzionano bene, senza essere rovinate.', 'Le parole ''periodico controllo'' e ''usura e efficienza'' indicano che la manutenzione è fondamentale.', 'Controlla la cintura, salva la vita.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24346, 'VERO. Le cinture devono essere ''omologate'', cioè approvate secondo le regole di sicurezza, e devono funzionare sempre perfettamente. Non si possono usare cinture rotte o non a norma.', 'I termini ''omologato'' e ''sempre efficienti'' sono importanti: significano che devono essere a norma di legge e funzionare bene in ogni momento.', 'Omologata e perfetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24347, 'VERO. Se c''è un incidente forte, la cintura ti tiene fermo sul sedile. Così non sbatti contro il volante, il cruscotto o il parabrezza.', 'La frase ''mantenere il corpo attaccato al sedile'' descrive la funzione di contenimento della cintura.', 'Ti tengono fermo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24348, 'VERO. In caso di incidente, la cintura impedisce che tu o i passeggeri colpiate le parti interne dell''auto, come il cruscotto, i sedili o il tetto, riducendo le ferite.', 'La parte ''evitare che... vadano a urtare parti interne'' spiega come la cintura protegge dagli impatti dentro l''abitacolo.', 'No urti interni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24349, 'VERO. La cintura è fondamentale per non essere sbalzati fuori dall''auto in caso di incidente grave. Rimanere dentro il veicolo aumenta molto le possibilità di salvarsi.', 'La frase ''proiettati all''esterno'' è la chiave: la cintura previene l''espulsione dall''auto.', 'Non volare fuori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24350, 'VERO. Non importa dove o a che velocità vai, la cintura va sempre messa. L''obbligo vale in ogni momento in cui l''auto è in movimento.', 'La parola ''qualsiasi'' è importante: non ci sono eccezioni legate alla situazione o al tipo di strada.', 'Sempre, ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24351, 'VERO. Anche chi siede sui sedili posteriori deve mettere la cintura. Non è un obbligo solo per chi sta davanti, ma per tutti i passeggeri.', 'La frase ''anche dai passeggeri dei sedili posteriori'' sottolinea che l''obbligo è esteso a tutti i posti dotati di cintura.', 'Anche dietro, cintura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24352, 'VERO. Le cinture devono essere ''omologate'', cioè approvate secondo le regole di sicurezza, e devono funzionare sempre perfettamente. Non si possono usare cinture rotte o non a norma.', 'I termini ''omologato'' e ''sempre efficienti'' sono importanti: significano che devono essere a norma di legge e funzionare bene in ogni momento.', 'Omologata e perfetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24353, 'FALSO. È FALSO. L''obbligo di usare le cinture vale sempre, a qualsiasi velocità, anche a bassa velocità. Un incidente può accadere anche a 10 km/h e causare danni gravi.', 'La trappola è ''inferiore ai 30 km/h''. La velocità non è una scusa per non mettere la cintura.', 'Velocità non conta, cintura sì.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24354, 'FALSO. È FALSO. È obbligatorio per legge indossare le cinture anche sui sedili posteriori. Non è solo un consiglio, ma una regola da rispettare per la sicurezza di tutti.', 'La trappola è ''Non è obbligatorio, ma è consigliato''. Ricorda che è un obbligo, non una scelta.', 'Dietro è obbligo, non consiglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24355, 'FALSO. È FALSO. L''età non è un motivo per non mettere la cintura. L''obbligo vale per tutti, a meno di specifiche esenzioni mediche certificate da un medico.', 'La trappola è ''persone anziane (età superiore ai 70 anni)''. L''età non esenta dall''obbligo.', 'Età non esenta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24356, 'FALSO. È FALSO. Airbag e cinture lavorano insieme per la tua sicurezza. L''airbag da solo non basta e, anzi, senza cintura può essere molto pericoloso perché l''airbag si apre con grande forza.', 'La trappola è ''veicoli muniti di air-bag''. L''airbag non sostituisce la cintura, la completa.', 'Airbag + cintura = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24357, 'FALSO. È FALSO. La spia serve a ricordarti di mettere la cintura e non può essere spenta dal conducente. È un sistema di sicurezza obbligatorio per legge.', 'La trappola è ''disabilitata dal conducente''. Non si può disattivare un sistema di sicurezza così importante.', 'Spia sempre accesa se non allacci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24358, 'FALSO. È FALSO. La cintura deve aderire bene al corpo per funzionare correttamente. Non si possono usare strumenti che la allontanano. In casi particolari, esistono prolunghe omologate, ma non strumenti che la rendono meno aderente.', 'La trappola è ''evitano che la cintura di sicurezza stia aderente al corpo''. La cintura deve essere aderente per proteggere.', 'Aderenza salva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24359, 'FALSO. È FALSO. L''arrotolatore è una parte importante della cintura che la tiene tesa e la blocca in caso di urto. Non si può modificare o disattivare per nessun motivo, anche se ''crea fastidio''. La sicurezza viene prima di tutto.', 'Le parole ''disattivato o modificato'' e ''se crea fastidio'' sono la trappola. La sicurezza non è un optional.', 'Non toccare l''arrotolatore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24360, 'FALSO. È FALSO. Anche in città, dove le velocità sono più basse, gli incidenti possono causare gravi danni. La cintura è sempre utile e obbligatoria, anche per brevi tragitti urbani.', 'La trappola è ''utilità trascurabile nella circolazione urbana''. La cintura è sempre utile, ovunque.', 'Utile sempre, anche in città.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24361, 'FALSO. È FALSO. La distanza percorsa non cambia l''obbligo. Anche per un tragitto brevissimo, la cintura va messa. Un incidente può succedere anche a pochi metri da casa.', 'La trappola è ''lunghezza inferiore a un chilometro''. La distanza non esenta dall''obbligo.', 'Breve o lungo, allaccia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24362, 'FALSO. È FALSO. I bambini devono essere trasportati su seggiolini omologati e adatti alla loro età e peso, non in braccio, nemmeno con la cintura dell''adulto. È estremamente pericoloso e vietato dalla legge.', 'La frase ''in braccio a un adulto, senza pericoli'' è la trappola. È molto pericoloso e non è mai consentito.', 'Bambini = seggiolino.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24363, 'È VERO. I bambini che non raggiungono 1,50 metri di altezza devono usare un seggiolino o un rialzo (sistema di ritenuta) che sia adatto al loro peso e alla loro statura. Questo è fondamentale per la loro sicurezza in auto.', 'La frase chiave è ''devono essere trattenuti da sistemi di ritenuta omologati, adeguati''. ''Devono'' indica un obbligo, e ''omologati'' significa che devono essere approvati dalla legge.', 'Sotto 1,50m, sempre seggiolino!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24364, 'È VERO. I bambini molto piccoli, sotto i 3 anni, non possono assolutamente viaggiare in auto se non sono assicurati a un seggiolino adatto. È una regola di sicurezza molto importante.', 'Le parole ''non possono viaggiare'' e ''sprovviste'' indicano un divieto assoluto. Non ci sono eccezioni per questa età.', 'Meno di 3 anni? Seggiolino obbligatorio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24366, 'È VERO. Se metti un bambino sul sedile anteriore con un seggiolino, e l''auto ha l''airbag, devi disattivare l''airbag. L''airbag, in caso di incidente, potrebbe essere molto pericoloso per il bambino.', 'La condizione ''solo se il veicolo è dotato di comando per disattivare l''airbag stesso'' è cruciale. Senza questa possibilità, non si può mettere il seggiolino davanti.', 'Airbag anteriore + bambino = disattiva!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24367, 'È VERO. I seggiolini non sono tutti uguali. Sono divisi in gruppi (ad esempio Gruppo 0, 1, 2, 3) in base al peso del bambino, per garantire la massima sicurezza e il giusto supporto.', 'La frase ''in funzione del peso del bambino'' è la chiave. Non sono classificati per età o altezza in generale, ma specificamente per il peso.', 'Seggiolini = gruppi per peso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24368, 'È VERO. I seggiolini devono essere ''omologati'', cioè approvati secondo le norme di sicurezza. Inoltre, devono essere sempre in buone condizioni e funzionanti, non rotti o danneggiati.', 'Le parole ''omologato'' e ''mantenuti sempre efficienti'' sono fondamentali. Un seggiolino non omologato o rotto non è sicuro e non è legale.', 'Seggiolino: omologato e perfetto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24369, 'È FALSO. Come abbiamo visto, i sistemi di ritenuta non sono di un ''unico tipo''. Ci sono diversi gruppi (per peso) e modelli. Non tutti sono adatti per tutti i bambini fino a 1,50 metri, ma devono essere scelti in base alle caratteristiche del bambino.', 'Le parole ''unico tipo'' e ''tutti utilizzabili'' sono le trappole. Queste generalizzazioni estreme sono quasi sempre false nei quiz sulla sicurezza stradale.', 'Non esiste un ''unico tipo'' per tutti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24370, 'È FALSO. I bambini devono essere sempre assicurati con i sistemi di ritenuta, non importa dove si guida. La sicurezza è importante sia in città che fuori città.', 'La frase ''purché su percorsi urbani'' è la trappola. Non ci sono eccezioni per i percorsi urbani; l''obbligo vale sempre.', 'Mai senza seggiolino, neanche in città!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24371, 'È FALSO. Anche a bassa velocità, un incidente può essere pericoloso per un bambino non assicurato. La velocità non è una scusa per non usare il seggiolino.', 'La condizione ''purché si circoli alla velocità massima di 40 km/h'' è la trappola. La velocità non cambia l''obbligo di usare il seggiolino.', 'Velocità bassa non è scusa!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24372, 'È FALSO. Tenere un bambino ''a portata di braccio'' non è un sistema di sicurezza. In caso di frenata improvvisa o incidente, il bambino non sarebbe protetto.', 'La frase ''a portata di braccio del conducente'' è la trappola. Non è un metodo di ritenuta valido e sicuro.', 'Braccio non è seggiolino!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24373, 'È FALSO. Tenere un bambino in braccio, anche se da un adulto, è estremamente pericoloso. In caso di incidente, il bambino verrebbe sbalzato via con forza. È vietato.', 'La frase ''in braccio a persona maggiorenne'' è la trappola. È una pratica molto pericolosa e non consentita dalla legge.', 'Mai in braccio, mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24374, 'È FALSO. La regola generale è che i bambini sotto 1,50 metri di altezza devono usare un sistema di ritenuta. Le cinture di sicurezza normali sono fatte per gli adulti e non proteggono adeguatamente un bambino più basso di 1,50 metri, anche se la domanda indica 1,30 metri.', 'La trappola è ''purché sia di altezza superiore a 1,30 metri''. La soglia corretta per l''uso delle sole cinture di sicurezza (senza rialzo) è 1,50 metri, non 1,30 metri.', '1,30m non basta, serve 1,50m!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24375, 'È FALSO. I seggiolini devono essere prodotti da aziende specializzate e devono essere ''omologati'', cioè approvati ufficialmente secondo le norme di sicurezza. Un seggiolino fatto in casa, anche se ''approvato'' da un esperto, non è legale né sicuro.', 'Le parole ''costruzione artigianale'' e ''approvati da esperto della ASL'' sono le trappole. I seggiolini devono essere omologati da enti specifici, non fatti in casa o approvati da un singolo esperto.', 'Solo seggiolini omologati, mai fai-da-te!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24376, 'L''airbag è un cuscino speciale, fatto di un materiale resistente come il nylon, che si gonfia molto velocemente in caso di incidente per proteggerti.', 'La frase ''o altro materiale sintetico'' è una specificazione, non una trappola. Indica che possono esserci anche altri materiali simili al nylon.', 'Airbag = cuscino protettivo resistente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24377, 'L''airbag si attiva solo quando c''è un impatto molto forte, come in un incidente grave. Non si gonfia per piccoli urti o frenate brusche.', 'La parola chiave è ''urto violento''. Non si attiva per ogni tipo di urto, ma solo per quelli gravi.', 'Airbag = solo per urti forti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24378, 'Se l''airbag si attiva e tu non hai la cintura di sicurezza, potresti essere spinto con molta forza contro l''airbag stesso o contro altre parti dell''auto, facendoti male. La cintura ti tiene nella posizione giusta.', 'La trappola è la condizione ''se non si indossa la cintura di sicurezza''. Senza cintura, l''airbag può diventare pericoloso.', 'Airbag + cintura = sicurezza. Senza cintura = pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24379, 'L''airbag serve a creare un ''cuscino'' tra te e le parti dure dell''auto (come il volante, il cruscotto o il parabrezza) in caso di incidente, per evitare che tu ci sbatta contro e ti faccia male.', 'Le parole ''limitare i danni'' e ''urti contro superfici interne'' spiegano bene la funzione protettiva dell''airbag.', 'Airbag = scudo contro l''interno dell''auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24380, 'In alcune auto, specialmente l''airbag del passeggero, può essere disattivato. Questo è utile, ad esempio, se devi mettere un seggiolino per bambini sul sedile anteriore.', 'La parola ''talvolta'' è importante. Non tutti gli airbag sono disattivabili, ma alcuni sì.', 'Airbag passeggero = a volte OFF (es. per bambini).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24381, 'L''auto ha dei sensori che ''sentono'' l''urto. Quando l''urto è abbastanza forte, i sensori inviano un segnale e l''airbag si gonfia da solo, senza che tu debba fare nulla.', 'Le parole ''automaticamente'' e ''sensore'' sono fondamentali. L''airbag non si attiva manualmente.', 'Sensore = airbag ON automatico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24382, 'L''airbag deve gonfiarsi in un tempo brevissimo, quasi istantaneo, per poterti proteggere subito dopo l''impatto. I millisecondi sono frazioni di secondo, quindi è velocissimo.', 'La precisione ''pochi millisecondi'' è cruciale. Indica una velocità estrema.', 'Airbag = flash, velocissimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24383, 'Se l''airbag si gonfiasse in ''pochi secondi'', sarebbe troppo lento. L''incidente avviene in un attimo, e l''airbag deve essere già gonfio per proteggerti. Deve gonfiarsi in millisecondi, non secondi.', 'La parola ''secondi'' è la trappola. È troppo tempo per la protezione dell''airbag.', 'Non secondi, ma millisecondi!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24384, 'L''airbag non si gonfia premendo un pulsante. Si attiva da solo, automaticamente, grazie ai sensori dell''auto che rilevano un urto violento.', 'La frase ''premendo un pulsante'' è la trappola. L''attivazione è automatica, non manuale.', 'Airbag = automatico, non con pulsante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24385, 'L''airbag è un sistema sigillato che si attiva una sola volta in caso di incidente. Non deve essere gonfiato periodicamente per controllarlo; la sua efficienza viene verificata durante la normale manutenzione dell''auto, senza gonfiarlo.', 'La frase ''gonfiato periodicamente'' è la trappola. L''airbag non è come una gomma che si sgonfia.', 'Airbag = si gonfia solo una volta, non per prova.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24386, 'L''airbag è un sistema di sicurezza utile su qualsiasi strada, sia in città (urbani) che fuori città (extraurbani) o in autostrada. Gli incidenti possono avvenire ovunque.', 'La parola ''soltanto'' è la trappola. L''airbag è utile sempre, non solo in specifici percorsi.', 'Airbag = utile ovunque, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24387, 'È FALSO! L''airbag e le cinture di sicurezza sono progettati per lavorare insieme. Le cinture ti tengono fermo al sedile, e l''airbag ammortizza l''impatto. Insieme offrono la massima protezione.', 'La frase ''non va usato insieme'' è la trappola. Sono un sistema combinato di sicurezza.', 'Airbag + cintura = coppia vincente per la sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24388, 'Il numero di porte di un''auto non ha nulla a che fare con la possibilità di montare gli airbag. Molte auto a 2 o 3 porte hanno regolarmente gli airbag.', 'La condizione ''meno di 4 porte'' è una distrazione e non è rilevante per la presenza degli airbag.', 'Airbag = indipendente dal numero di porte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24389, 'Il conducente non può decidere a quale velocità d''urto l''airbag si deve attivare. Questa è una impostazione tecnica decisa dal costruttore dell''auto per garantire la massima sicurezza e non può essere modificata.', 'La frase ''Il conducente può tarare'' è la trappola. Il guidatore non ha questo controllo sulle impostazioni di sicurezza dell''airbag.', 'Airbag = impostazioni fisse di fabbrica, non modificabili.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24390, 'I materiali di cui è fatto il casco, come la plastica e la resina, si rovinano con il tempo. L''esposizione al sole (luce) e al caldo accelera questo processo, rendendo il casco meno sicuro e meno efficace in caso di urto. Per questo, i caschi hanno una ''data di scadenza'' o un periodo di vita consigliato.', 'La parola ''invecchiamento'' indica che il casco non è eterno e le sue proprietà protettive diminuiscono nel tempo.', 'Sole e caldo, casco rovinato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24391, 'Per pulire il casco, è fondamentale usare prodotti delicati. I detersivi ''non corrosivi'' sono quelli che non contengono sostanze aggressive che potrebbero danneggiare la superficie o la struttura interna del casco, compromettendone la sicurezza.', 'La frase ''non corrosivi'' è la chiave: significa che i prodotti devono essere delicati e non aggressivi per i materiali del casco.', 'Pulizia delicata, casco protetto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24392, 'I solventi sono sostanze chimiche molto forti che possono sciogliere o indebolire i materiali plastici e le resine di cui è fatto il casco. Anche se il danno non è subito visibile, il casco potrebbe perdere la sua capacità di proteggere la testa in caso di incidente.', 'La parola ''solventi'' indica sostanze chimiche aggressive che sono pericolose per la struttura del casco.', 'Solventi lontani dal casco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24393, 'La benzina è un tipo di solvente molto potente e aggressivo. Usarla per pulire il casco può danneggiare gravemente i materiali, rendendoli fragili e meno resistenti agli urti, anche se il danno non è visibile esternamente.', 'La parola ''benzina'' è un esempio specifico di solvente che non deve mai essere usato per la pulizia del casco.', 'No benzina, casco salvo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24394, 'Il casco è progettato per assorbire l''energia di un urto e distribuirla su una superficie più ampia, riducendo così la forza che arriva alla testa. Questo diminuisce il rischio di traumi gravi in caso di caduta o incidente.', 'La frase ''ridurre gli effetti'' è importante: il casco non elimina il rischio, ma lo diminuisce notevolmente.', 'Casco in testa, testa protetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24395, 'Il casco integrale è quello che copre tutta la testa, inclusa la parte del viso (mento e mascella). Questa protezione completa è fondamentale per evitare ferite e lesioni al viso in caso di incidente, oltre a proteggere la parte superiore della testa.', 'La parola ''integrale'' significa che il casco copre interamente la testa, offrendo una protezione completa anche al viso.', 'Integrale = protezione totale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24396, 'La visiera è un elemento essenziale del casco. Protegge gli occhi e il viso da vento, pioggia, polvere, insetti e piccoli sassi che possono colpire mentre si guida, garantendo una visione chiara e sicura.', 'La frase ''è bene che'' indica una caratteristica fondamentale per la sicurezza e il comfort di guida.', 'Visiera sempre, occhi sicuri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24397, 'Quando si guida, soprattutto a velocità elevate, insetti o piccoli detriti possono colpire il viso e gli occhi. La visiera agisce come una barriera protettiva, evitando distrazioni e possibili lesioni che potrebbero compromettere la guida.', 'La frase ''impatti con insetti'' evidenzia un pericolo comune e fastidioso da cui la visiera protegge.', 'Visiera = scudo per occhi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24398, 'Un casco della taglia sbagliata non può proteggere efficacemente. Se è troppo grande, si muove e può sfilarsi. Se è troppo piccolo, stringe e può causare fastidio o mal di testa. Deve aderire bene alla testa senza stringere troppo, per rimanere fermo in caso di urto.', 'La frase ''taglia corretta'' è cruciale per garantire che il casco svolga la sua funzione protettiva al meglio.', 'Taglia giusta, protezione robusta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24399, 'Anche se la parte esterna del casco (calotta) sembra intatta, un forte urto può aver danneggiato la struttura interna, che è quella che assorbe l''energia. Un casco che ha subito un urto non è più sicuro e deve essere sostituito, proprio come un airbag che si è attivato.', 'La frase ''anche se non mostra deformazioni sulla calotta esterna'' è la parte più importante: il danno può essere invisibile ma grave.', 'Un urto = casco da buttare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24400, 'Alcune vernici o colle non adatte per il casco possono contenere solventi. Questi solventi possono indebolire la plastica o la resina della calotta esterna, rendendo il casco meno resistente e meno sicuro in caso di incidente.', 'La frase ''compromessa da solventi'' ribadisce il pericolo delle sostanze chimiche aggressive per la robustezza del casco.', 'No vernici strane, casco sano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24401, 'Se il casco non è allacciato correttamente, in caso di caduta o incidente può sfilarsi dalla testa e non offrire alcuna protezione. L''allacciatura deve essere ben stretta, ma senza causare fastidio.', 'La parola ''sempre'' e ''correttamente allacciato'' sono fondamentali: non basta indossarlo, deve essere fissato bene.', 'Allacciato bene, testa al sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24402, 'Indossare il casco in modo sbagliato (ad esempio, troppo indietro sulla testa) o senza allacciarlo bene lo rende inutile. In caso di incidente, il casco potrebbe spostarsi o volare via, lasciando la testa senza protezione e aumentando il rischio di gravi lesioni.', 'Le frasi ''in modo errato'' e ''senza averlo correttamente allacciato'' sottolineano che non basta avere il casco, ma bisogna usarlo bene.', 'Casco sì, ma bene.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24403, 'Anche per un breve tragitto o a bassa velocità, un incidente può sempre capitare. Le conseguenze di un trauma cranico possono essere molto gravi, quindi la protezione del casco è sempre necessaria, senza eccezioni.', 'La frase ''anche per spostamenti brevi e a bassa velocità'' è importante: non ci sono scuse per non indossare il casco.', 'Sempre casco, sempre sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24404, 'I quadricicli a motore privi di carrozzeria, come i quad, non offrono alcuna protezione in caso di ribaltamento o caduta. Per questo motivo, chi li guida deve indossare il casco per proteggere la testa.', 'La specificazione ''privi di carrozzeria (Quad)'' è importante, perché distingue questi veicoli da altri quadricicli che hanno una carrozzeria chiusa.', 'Quad senza carrozzeria = casco obbligatorio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24405, 'Una visiera rigata o danneggiata può ridurre la visibilità, specialmente di notte, con il sole basso o in condizioni di pioggia. Questo può causare distrazioni e aumentare il rischio di incidenti. Per la sicurezza, è fondamentale avere una visiera sempre perfetta.', 'Le parole ''rigata o danneggiata'' indicano che qualsiasi alterazione della visiera ne compromette la funzionalità e la sicurezza.', 'Visiera chiara, guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24406, 'La visiera deve essere trasparente e pulita per permettere al conducente di vedere chiaramente la strada e l''ambiente circostante in ogni condizione, sia di giorno che di notte, con sole o pioggia. Una visiera che non garantisce una visione perfetta è pericolosa.', 'La frase ''perfetta visione con qualunque condizione di luce o illuminazione'' sottolinea l''importanza di una visibilità ottimale in ogni momento.', 'Visiera perfetta, visione perfetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24407, 'Il sistema di aerazione del casco (le prese d''aria) serve a far circolare l''aria all''interno. Questo aiuta a prevenire che la visiera si appanni a causa del respiro o dell''umidità, mantenendo la visibilità chiara e costante.', 'Le parole ''sistema di aerazione'' e ''appannamento'' sono collegate: l''uno serve a prevenire l''altro.', 'Aria nel casco, visiera chiara.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24408, 'Non indossare il casco quando è obbligatorio è una grave violazione del Codice della Strada. Oltre a una multa, questa infrazione comporta la perdita di punti dalla patente di guida, come previsto dalla legge.', 'La frase ''decurtazione di punti dalla patente di guida'' indica una conseguenza legale importante e diretta della violazione.', 'No casco = meno punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24409, 'FALSO. Non si possono applicare adesivi ''di qualunque tipo''. Alcuni adesivi o vernici non specifici per caschi possono contenere solventi che, anche se non coprono la visiera, possono danneggiare la struttura del casco e comprometterne la sicurezza. Solo adesivi omologati o specifici per caschi sono ammessi.', 'La parola ''qualunque'' è la trappola. Non tutti i tipi di adesivi sono sicuri per il casco.', 'Adesivi? Solo se specifici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24410, 'FALSO. Benzina e acquaragia sono solventi molto aggressivi che danneggiano gravemente i materiali del casco, rendendolo insicuro. Per la pulizia si devono usare solo acqua tiepida e sapone neutro o prodotti specifici e delicati per caschi.', 'Le parole ''benzina o acquaragia'' sono la trappola: sono sostanze assolutamente proibite per la pulizia del casco.', 'No benzina, no acquaragia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24412, 'FALSO. Il casco deve essere sempre allacciato correttamente, in ogni situazione e su ogni tipo di strada, sia in città che fuori. La sicurezza non dipende dal percorso, ma dall''uso corretto del dispositivo di protezione.', 'La parola ''solo'' è la trappola. L''allacciatura corretta è sempre obbligatoria, non solo in alcuni percorsi.', 'Allacciato sempre, ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24413, 'FALSO. L''obbligo di indossare il casco vale sempre, indipendentemente dalla velocità o dal tipo di strada. Anche a bassa velocità, un incidente può causare gravi traumi alla testa, quindi la protezione è sempre necessaria.', 'La frase ''non è obbligatorio'' e la condizione ''inferiore a 30 km/h'' sono la trappola. La velocità non elimina l''obbligo di sicurezza.', 'Velocità bassa? Casco non scappa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24414, 'FALSO. L''uso del casco è obbligatorio solo sui quadricicli a motore ''privi di carrozzeria'' (come i quad aperti). Se il quadriciclo ha una carrozzeria chiusa (come una microcar), non è obbligatorio indossare il casco.', 'La parola ''qualunque'' è la trappola. L''obbligo non si estende a tutti i quadricicli, ma solo a quelli senza carrozzeria.', 'Quadriciclo con carrozzeria? No casco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24415, 'FALSO. I materiali del casco (resine, plastiche, imbottiture) invecchiano e si deteriorano con il tempo, anche se non usato, perdendo le loro capacità protettive. La durata media di un casco è di circa 5-7 anni dalla data di produzione, non ''oltre venti anni''.', 'La frase ''periodi lunghissimi, di oltre venti anni'' è la trappola. I caschi hanno una vita utile limitata.', 'Casco ha scadenza, non dura vent''anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24416, 'FALSO. Il casco integrale offre la massima protezione ed è sempre permesso, anzi consigliato, in qualsiasi condizione di circolazione, inclusi i centri urbani. Non esistono divieti di utilizzo in base al tipo di strada.', 'La frase ''non può essere utilizzato'' è la trappola. Il casco integrale è sempre una scelta sicura e permessa.', 'Integrale sempre, ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24417, 'FALSO. Il casco integrale è il tipo di casco che offre la maggiore protezione, coprendo tutta la testa e il viso. È sempre utile e consigliato per chiunque guidi un veicolo a due ruote, inclusi i ciclomotori, per massimizzare la sicurezza in caso di incidente.', 'La parola ''inutile'' è la trappola. Il casco integrale è sempre la scelta più protettiva.', 'Integrale = massima protezione, mai inutile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24418, 'FALSO. L''obbligo di indossare il casco vale per tutti i conducenti e passeggeri di veicoli a due ruote, senza alcuna eccezione legata all''età o all''esperienza di guida. La sicurezza è un diritto e un dovere per tutti.', 'La frase ''non riguarda i maggiorenni con più di tre anni di esperienza di guida'' è la trappola. Non ci sono esenzioni per esperienza o età.', 'Casco per tutti, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24419, 'FALSO. L''obbligo di indossare il casco non dipende dalla temperatura esterna. È sempre obbligatorio, anche con temperature molto alte, per garantire la sicurezza del conducente e del passeggero in caso di incidente.', 'La frase ''diventa facoltativo'' e la condizione ''temperatura... superiore ai trenta gradi'' sono la trappola. Il caldo non è una scusa per non indossare il casco.', 'Caldo o freddo, casco stretto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24420, 'FALSO. Una visiera pulita e in buone condizioni migliora la visibilità, proteggendo da vento, pioggia, insetti e detriti. È un elemento essenziale per la sicurezza e va usata sempre, non il meno possibile.', 'Le frasi ''peggiora notevolmente la visibilità'' e ''va usata il meno possibile'' sono la trappola. Una visiera efficiente è fondamentale per la sicurezza.', 'Visiera chiara = visione chiara.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24421, 'FALSO. La calotta esterna del casco è la parte più importante per la protezione. Se presenta una rottura, anche piccola, la sua capacità di assorbire gli urti è compromessa. Non può essere riparata con nastro adesivo; il casco deve essere sostituito per garantire la sicurezza.', 'La frase ''riparata con nastro adesivo'' è la trappola. Qualsiasi danno alla calotta richiede la sostituzione del casco.', 'Casco rotto? Casco nuovo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24422, 'FALSO. Una visiera danneggiata, rigata o rotta deve essere sostituita. Anche il nastro adesivo ''ultra trasparente'' altera la visione, crea distorsioni e non ripristina la sicurezza e l''integrità della visiera. La visibilità deve essere perfetta.', 'La frase ''riparata con nastro adesivo'' è la trappola. Una visiera danneggiata va sempre sostituita.', 'Visiera rotta? Visiera nuova.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24423, 'FALSO. Tutti i caschi utilizzati per la guida di veicoli a motore, inclusi i ciclomotori, devono essere omologati. L''omologazione garantisce che il casco abbia superato test di sicurezza e rispetti gli standard previsti dalla legge per proteggere efficacemente la testa.', 'La frase ''non necessitano di omologazione'' è la trappola. L''omologazione è obbligatoria per tutti i caschi da moto/ciclomotore.', 'Casco senza omologazione = casco senza protezione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24424, 'Gli stivali da moto sono progettati proprio per proteggere i piedi e le caviglie. Sono robusti e coprono bene queste parti del corpo, che sono molto esposte in caso di incidente o caduta.', 'La frase ''giusta protezione'' indica che la loro funzione principale è proprio questa, rendendo l''affermazione vera.', 'Stivali moto = piedi e caviglie protetti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24425, 'Questi stivali sono fatti per tenere ferma la caviglia, così è più difficile farsi male (distorsione) se appoggi male il piede. Inoltre, i materiali usati aiutano a tenere i piedi al caldo, proteggendoli dal freddo durante la guida.', 'Le parole chiave sono ''riducono gli effetti di distorsioni'' e ''proteggono... dal freddo'', che descrivono due importanti funzioni di sicurezza e comfort degli stivali da moto.', 'Stivali moto = meno distorsioni + piedi caldi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24426, 'Per la sicurezza, gli stivali da moto non devono avere lacci o nastri che penzolano. Questo evita che si possano impigliare nelle pedivelle o in altre parti della moto mentre guidi, cosa che sarebbe molto pericolosa.', 'La frase ''privi di nastri liberi o stringhe'' è fondamentale e indica una caratteristica di sicurezza essenziale.', 'Niente lacci penzolanti = sicurezza in moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24427, 'Se cadi dalla moto, gli stivali sono fatti con materiali resistenti che proteggono i tuoi piedi dallo sfregamento sull''asfalto. Questo evita ferite gravi come le abrasioni.', 'Il termine ''abrasioni sull''asfalto'' si riferisce a uno dei rischi maggiori in caso di caduta, e gli stivali sono progettati per prevenirle.', 'Caduta = stivali proteggono da asfalto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24428, 'Per essere venduti come stivali da moto, devono superare dei test e rispettare delle regole di sicurezza precise. Questo si chiama ''omologazione'' e significa che sono stati controllati e approvati secondo standard internazionali.', 'La parola ''omologati'' è cruciale. Significa che il prodotto è certificato e rispetta le norme di sicurezza.', 'Stivali moto = certificati (omologati).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24429, 'Gli stivali da moto sono fatti per rimanere ben saldi ai piedi, anche se cadi. Questo è fondamentale perché se si sfilano, il piede rimane senza protezione, aumentando il rischio di lesioni.', 'La frase ''non scalzarsi'' è una caratteristica di sicurezza essenziale per mantenere la protezione in caso di incidente.', 'Stivali moto = restano ai piedi, anche cadendo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24430, 'Le scarpe da trekking sono ottime per camminare in montagna, ma non sono fatte per proteggere in caso di caduta dalla moto. Non hanno le stesse protezioni rigide per caviglie e piedi e non sono progettate per resistere all''abrasione dell''asfalto. Non sono ''di analoga concezione'' per la sicurezza in moto.', 'Le parole trappola sono ''si possono utilizzare'' e ''di analoga concezione''. Le scarpe da trekking non offrono la stessa protezione degli stivali da moto.', 'Trekking NO moto. Solo stivali specifici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24431, 'Abbiamo visto che gli stivali da moto sono ''privi di nastri liberi o stringhe'' proprio per evitare che si impiglino. Quindi, non hanno doppie stringhe. Usano sistemi di chiusura diversi, come cerniere o velcro, per essere sicuri e pratici.', 'La frase ''doppie stringhe'' è la parola trappola. Gli stivali da moto evitano le stringhe per sicurezza.', 'Niente stringhe (singole o doppie) negli stivali da moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24432, 'La suola degli stivali da moto è robusta e antiscivolo, ma non è fatta di acciaio. L''acciaio sarebbe troppo pesante, rigido e non permetterebbe una buona sensibilità sui comandi della moto, oltre a non essere il materiale ideale per l''aderenza.', 'La frase ''suola in acciaio'' è la parola trappola. La suola è robusta ma non di acciaio.', 'Suola moto = robusta, NON acciaio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24433, 'Gli stivali da moto proteggono piedi e caviglie, e a volte parte dello stinco, ma non arrivano fino sopra il ginocchio. Quella protezione è data da pantaloni specifici o protezioni separate. Stivali così alti sarebbero scomodi e limiterebbero i movimenti.', 'La frase ''fin sopra il ginocchio'' è un''esagerazione dell''altezza dello stivale e rende l''affermazione falsa.', 'Stivali moto = non coprono il ginocchio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24434, 'Gli stivali da moto sono fatti con materiali resistenti e protettivi (come pelle, materiali sintetici, protezioni rigide), ma non sono interamente di gomma ignifuga. La gomma ignifuga è un materiale specifico che non brucia, ma non è il materiale principale per uno stivale da moto.', 'La frase ''interamente realizzati in gomma ignifuga'' è troppo specifica e non corretta. Gli stivali usano vari materiali.', 'Stivali moto = materiali vari, NON solo gomma ignifuga.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24435, 'Questa affermazione è completamente falsa. Esistono eccome stivali specifici per la moto, omologati e progettati per la sicurezza su due ruote. Le calzature per caccia, pesca o alpinismo non offrono la stessa protezione in caso di caduta o abrasione sull''asfalto.', 'La frase ''Non esistono specifici stivali ad uso motociclistico'' è la trappola principale. È falso, esistono eccome!', 'Esistono SEMPRE stivali specifici per moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24436, 'È vero che è molto importante usare i guanti quando guidi un ciclomotore o una moto. I guanti proteggono le tue mani in caso di caduta o se urti qualcosa.', 'La parola ''consigliabile'' significa che è una buona idea farlo per la tua sicurezza, anche se non è sempre obbligatorio per legge.', 'Guanti = mani protette.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24437, 'Sì, è vero. I guanti omologati sono fatti apposta per proteggere. Il dorso della mano (la parte superiore) è spesso rinforzato per proteggerti dagli urti, ad esempio se colpisci qualcosa di duro.', 'Le parole ''in particolar modo'' indicano che questa è una funzione importante, ma non l''unica. ''Omologati'' significa che i guanti rispettano le norme di sicurezza.', 'Guanti omologati = dorso al sicuro dagli urti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24438, 'È vero. Il palmo della mano (la parte interna) è la prima cosa che spesso tocca terra in caso di caduta. I guanti hanno materiali resistenti che proteggono la pelle dall''asfalto, evitando graffi e abrasioni.', 'La frase ''strisciamento sull''asfalto'' descrive bene il tipo di danno che i guanti aiutano a prevenire.', 'Guanti = palmo salvo da strisciamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24439, 'Sì, è vero. I guanti specifici per la moto sono fatti per darti la giusta sensibilità per usare i comandi (come i freni e l''acceleratore) e per avere una presa più salda, specialmente se le mani sudano o fa freddo.', 'Le espressioni ''giusta sensibilità'' e ''presa più sicura'' sono importanti: i guanti non devono ostacolare, ma aiutare.', 'Guanti = sensibilità + presa sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24440, 'È vero. Ci sono guanti più leggeri e ventilati per l''estate e guanti più spessi e caldi per l''inverno. Così puoi scegliere quelli giusti per ogni stagione e stare comodo.', 'La frase ''possono avere'' indica una possibilità, non che tutti i guanti siano uguali. Ci sono diverse opzioni.', 'Guanti = diversi per stagione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24441, 'Sì, è vero. Anche d''estate, il rischio di cadere e farsi male alle mani è sempre presente. I guanti estivi sono più leggeri ma offrono comunque una protezione fondamentale in caso di incidente.', 'La parola ''opportuno'' significa che è la cosa giusta e saggia da fare. ''Anche d''estate'' sottolinea che la protezione è sempre necessaria, non solo quando fa freddo.', 'Guanti = sempre, anche d''estate.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24442, 'È vero. Molti guanti da moto hanno un cinturino o un sistema di chiusura sul polso. Questo serve a tenere il guanto ben fermo sulla mano e a evitare che si sfili durante una caduta, così la protezione rimane al suo posto.', 'I ''speciali sistemi di aggancio'' si riferiscono a cinturini, velcro o altri meccanismi per fissare il guanto.', 'Guanti = aggancio anti-sfilamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24443, 'È falso. Esistono eccome guanti da motociclista omologati! Sono guanti che hanno superato test di sicurezza e sono riconoscibili da un''etichetta specifica che ne attesta la conformità alle norme europee.', 'La negazione ''Non esistono'' è la parola trappola. Quando si parla di sicurezza, spesso le affermazioni assolute sono false.', 'Guanti omologati = esistono e sono importanti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24444, 'È falso. I guanti da sci non sono fatti per proteggere come quelli da moto. Non offrono la stessa resistenza all''abrasione sull''asfalto o la stessa protezione dagli impatti. Ogni tipo di guanto ha uno scopo diverso.', 'La frase ''possono essere sostituiti'' è la trappola. L''equipaggiamento specifico per la moto non va sostituito con altro che non sia pensato per la guida su due ruote.', 'Guanti moto = specifici, non da sci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24445, 'È falso. I guanti specifici per la moto sono progettati per non ostacolare i movimenti e, anzi, migliorano la presa e la sensibilità sui comandi. Senza guanti, le mani possono sudare o scivolare, rendendo l''intervento meno sicuro.', 'La frase ''più rapidamente'' è la trappola. I guanti non rallentano, ma migliorano il controllo.', 'Guanti = non rallentano, migliorano la presa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24446, 'È falso. Il colore o un disegno non sono un modo per riconoscere un guanto omologato. I guanti omologati si riconoscono da un''etichetta interna che indica che rispettano le norme di sicurezza europee, non dall''estetica.', 'Le parole ''si riconoscono perché'' sono la trappola, seguite da dettagli estetici come ''colore nero'' e ''sagoma di moto'' che non c''entrano con la sicurezza.', 'Riconosci guanti = etichetta omologazione, non colore/disegno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24447, 'È falso. I guanti da moto coprono solo la mano e una parte del polso. Il gomito è protetto da altre parti dell''abbigliamento, come le protezioni della giacca o un paraschiena specifico.', 'La frase ''coprono anche il gomito'' è l''errore. I guanti non arrivano così in alto.', 'Guanti = solo mani e polsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24448, 'È falso. I guanti da motociclista sono perfetti e consigliati per la guida di qualsiasi veicolo a due ruote, inclusi i ciclomotori. Offrono la stessa protezione e sicurezza per tutti i mezzi a due ruote.', 'La negazione ''non sono idonei'' è la trappola. La protezione è utile per tutti i veicoli a due ruote.', 'Guanti moto = ok anche per ciclomotori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24449, 'È falso. Lo scopo principale dei guanti da moto è proteggere le mani in caso di caduta (da abrasioni e impatti), non solo dal freddo. Per questo è importante usarli anche d''estate, scegliendo modelli più leggeri e ventilati.', 'La frase ''principale scopo quello di proteggere dal freddo'' è una limitazione sbagliata dello scopo. La conclusione ''pertanto è inutile usarli l''estate'' è falsa perché basata su questa premessa errata.', 'Guanti = protezione caduta, non solo freddo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24450, 'VERO. Le giacche da moto sono fatte con materiali speciali che proteggono la pelle se scivoli sull''asfalto. Questo è uno dei loro scopi principali: ridurre i danni da ''abrasione'', cioè lo sfregamento.', 'La parola chiave è ''protezione all''abrasione''. Ricorda che la giacca è un capo di sicurezza, non solo un vestito.', 'Giacca moto = Protezione abrasione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24451, 'VERO. Le buone giacche da moto hanno delle protezioni dure (come delle ''imbottiture'' rigide) sui gomiti, sulle spalle e a volte sulla schiena. Queste protezioni servono a difendere le tue ''articolazioni'' (le parti che si piegano, come gomiti e spalle) in caso di caduta.', 'Fai attenzione a ''inserti rigidi protettivi'' e ''articolazioni''. Sono elementi di sicurezza fondamentali.', 'Giacca moto = Protezioni rigide per articolazioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24452, 'VERO. Quando un indumento da moto è ''omologato'', significa che ha superato dei test di sicurezza molto severi. Questi test verificano proprio quanto il materiale resiste a tagli e a forti sfregamenti (abrasione) in caso di impatto o caduta.', 'La parola ''omologati'' è importante: significa che hanno una certificazione di sicurezza. ''Resistenza al taglio e all''abrasione da impatto'' sono i test specifici.', 'Omologati = Resistono a taglio e abrasione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24453, 'FALSO. L''omologazione di un indumento da moto riguarda la sua capacità di proteggere il motociclista in caso di incidente (resistenza a tagli, abrasioni, impatti). Non riguarda quanto bene resiste ai lavaggi in lavatrice. Certo, deve essere lavabile, ma non è un requisito per la sua certificazione di sicurezza.', 'La ''resistenza al lavaggio'' è una caratteristica pratica, non un requisito di sicurezza per l''omologazione. Non confondere le due cose!', 'Omologazione = Sicurezza, non lavaggio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24454, 'FALSO. Esistono giacche da moto pensate apposta per l''estate! Hanno tessuti più leggeri, prese d''aria e sistemi di ventilazione per farti stare fresco, ma mantengono comunque le protezioni necessarie. La sicurezza in moto è importante tutto l''anno.', 'La frase ''non sono previste per utilizzo estivo'' è una generalizzazione sbagliata. Ci sono giacche per ogni stagione.', 'Giacche moto = Per tutte le stagioni (anche estate).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24455, 'FALSO. Il colore della giacca non ha nessuna importanza per l''omologazione. Una giacca può essere omologata se rispetta gli standard di sicurezza, indipendentemente dal suo colore. Anzi, colori vivaci possono aumentare la tua visibilità sulla strada!', 'La parola ''unicamente'' è una trappola. Non c''è nessun obbligo di colore per l''omologazione.', 'Omologazione = Sicurezza, non colore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24456, 'È assolutamente obbligatorio che ogni veicolo che circola su strada pubblica sia coperto da assicurazione per la responsabilità civile. Senza assicurazione, non si può guidare, perché in caso di incidente i danni non sarebbero coperti e questo è un rischio troppo grande per tutti.', 'La frase ''non è coperto dall''assicurazione'' è la chiave. L''assicurazione è un requisito fondamentale per la circolazione.', 'Assicurazione = Obbligatoria sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24457, 'Per guidare qualsiasi veicolo, è necessario avere la patente di guida specifica per quel tipo di veicolo. Guidare senza patente o con una patente non adatta è molto pericoloso e illegale, perché significa che non si hanno le competenze necessarie.', 'Le parole ''non si possiede la patente di guida necessaria'' indicano chiaramente la mancanza di un requisito legale e di sicurezza.', 'Patente = Permesso di guidare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24458, 'Un veicolo non immatricolato non ha la targa e non è registrato ufficialmente. Questo significa che non può circolare normalmente sulle strade pubbliche. Ci sono eccezioni, come i veicoli con targa prova, ma la regola generale è che l''immatricolazione è obbligatoria.', 'La locuzione ''di norma'' è importante: significa ''solitamente'', ''come regola generale''. ''Non immatricolato'' indica la mancanza della registrazione ufficiale del veicolo.', 'Immatricolazione = Targa e registrazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24459, 'La tassa di possesso, o ''bollo auto'', è una tassa che si paga per avere un veicolo. È obbligatorio pagarla, ma non è obbligatorio avere la ricevuta di pagamento sempre con sé in auto. Le forze dell''ordine possono verificare il pagamento tramite sistemi informatici.', 'La frase ''non si ha con sé la ricevuta'' è la trappola. Non è necessario portare la ricevuta, l''importante è aver pagato.', 'Bollo = Paga, non portare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24460, 'La targa prova è una targa speciale che permette a veicoli non ancora immatricolati (o in fase di test, riparazione, ecc.) di circolare su strada. È usata da concessionari, officine, carrozzieri. Quindi, circolare con la targa prova è permesso, non vietato.', 'La parola ''vietato'' è la trappola. La ''targa prova'' esiste proprio per permettere la circolazione in casi specifici.', 'Targa prova = Permesso speciale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24461, 'La carta di circolazione (oggi parte del Documento Unico) indica chi è il proprietario del veicolo. Non è un problema se chi guida non è il proprietario. Molte persone guidano auto di familiari, amici o aziendali. L''importante è avere la patente e il permesso del proprietario.', 'La frase ''intestata a persona diversa dal conducente'' è la trappola. Non c''è nessun divieto in questo caso.', 'Carta circolazione = Proprietario, non guidatore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24462, 'La garanzia è un accordo commerciale tra te e il venditore o il produttore del veicolo, che ti protegge da eventuali difetti per un certo periodo. La sua scadenza non ha alcuna influenza sulla possibilità di circolare su strada. Puoi guidare un''auto anche se la garanzia è scaduta.', 'Le parole ''garanzia è scaduta'' sono la trappola. La garanzia è un aspetto commerciale, non legale per la circolazione.', 'Garanzia = Acquisto, non strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24463, 'Il certificato di proprietà (oggi parte del Documento Unico di Circolazione e Proprietà) è un documento che attesta chi è il proprietario del veicolo. Non è obbligatorio averlo a bordo dell''auto. Serve per pratiche burocratiche come la vendita o il passaggio di proprietà, ma non per la circolazione quotidiana.', 'La frase ''non si ha con sé il certificato di proprietà'' è la trappola. Non è un documento da tenere in auto.', 'Certificato proprietà = Casa, non auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24464, 'È vero. Ogni veicolo, per poter circolare su strada, deve avere le targhe. Le targhe sono come la ''carta d''identità'' del veicolo e servono per sapere chi è il proprietario e per identificarlo in caso di necessità (ad esempio, multe o incidenti).', 'Non ci sono parole trappola particolari in questa domanda. Il testo è chiaro e diretto.', 'Targhe = Identità del veicolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24465, 'È vero. La carta di circolazione (oggi chiamata anche ''Documento Unico di Circolazione e di Proprietà del veicolo'') è un documento fondamentale. Attesta che il veicolo è idoneo a circolare e contiene tutte le sue caratteristiche tecniche. Senza questo documento, il veicolo non può circolare legalmente.', 'Non ci sono parole trappola. La ''carta di circolazione'' è un requisito base.', 'Carta di circolazione = Permesso di circolare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24467, 'È vero. Il segnale mobile di pericolo, comunemente chiamato ''triangolo'', è un equipaggiamento obbligatorio che deve essere sempre presente nel veicolo. Serve per segnalare un veicolo fermo per guasto o incidente, specialmente fuori dai centri abitati, per avvisare gli altri conducenti e prevenire ulteriori pericoli.', 'Non ci sono parole trappola. Il ''triangolo'' è un dispositivo di sicurezza obbligatorio.', 'Triangolo = Sicurezza in caso di guasto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24468, 'È falso. Per circolare, un''autovettura deve avere la polizza assicurativa obbligatoria, che è la ''Responsabilità Civile Auto'' (RCA). La polizza ''Kasko'' è un tipo di assicurazione facoltativa, cioè non obbligatoria. La Kasko copre i danni alla tua auto anche se la colpa è tua, ma non è necessaria per poter circolare legalmente.', 'La parola trappola è ''del tipo "kasko"''. Questo specifica un tipo di assicurazione che non è obbligatoria. L''assicurazione è obbligatoria, ma non necessariamente la Kasko.', 'Kasko = Facoltativa. RCA = Obbligatoria.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24469, 'Le targhe devono essere fissate bene e nella posizione giusta. Questo è importante perché devono essere sempre visibili e non devono cadere mentre guidi.', 'Le parole chiave sono ''saldamente'' (cioè ben fissate) e ''in posizione corretta'' (cioè nel posto giusto e non storte).', 'Targa: ferma e al suo posto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24470, 'È fondamentale che le targhe siano sempre leggibili, cioè che si possano leggere bene i numeri e le lettere. Questo serve per identificare il veicolo in ogni momento.', 'La parola ''sempre'' è importante qui, perché la leggibilità è un requisito costante. ''Ben leggibili'' significa chiare e facili da leggere.', 'Targa: chiara, sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24471, 'Le targhe non devono essere sporche perché lo sporco le renderebbe illeggibili. Se non si leggono bene, è come se non ci fossero.', 'La frase ''non devono essere sporche'' è diretta. Il concetto è legato alla leggibilità.', 'Targa: pulita.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24472, 'Non si possono modificare le targhe (manomettere) o crearne di false (contraffatte). Le targhe sono documenti ufficiali e devono essere originali e integre.', 'Le parole ''manomesse'' (modificate illegalmente) e ''contraffatte'' (false, non originali) sono le parole chiave che indicano azioni proibite.', 'Targa: originale, non toccare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24473, 'Quando si impara a guidare, l''auto deve avere un pannello con la lettera ''P'' sia davanti che dietro. Questi pannelli sono speciali (retroriflettenti) per essere visti bene, soprattutto di notte, e avvisano gli altri che c''è un principiante alla guida.', 'Attenzione ai dettagli: ''sia anteriormente che posteriormente'' (davanti e dietro) e ''retroriflettenti'' (che riflettono la luce).', 'Guida con la P: davanti e dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24474, 'È FALSO. Le targhe non possono essere piegate o modificate in alcun modo. Devono mantenere la loro forma originale per essere sempre leggibili e non sembrare manomesse.', 'La parola ''possono'' è la trappola. Non ''possono'' essere piegate. Anche ''per adattarle meglio'' è un tentativo di giustificare un''azione non permessa.', 'Targa: mai piegare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24475, 'Sì, è vero. Con la patente AM puoi guidare i quadricicli leggeri, che sono veicoli a quattro ruote con caratteristiche simili ai ciclomotori (ad esempio, le microcar).', 'La frase ''quadricicli leggeri'' è importante. Ricorda che non tutti i quadricicli sono leggeri e guidabili con la AM.', 'AM = Ciclomotori e microcar.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24476, 'Esatto, è vero. La patente AM è fatta proprio per guidare i ciclomotori a due ruote, come gli scooter o i motorini.', 'Nessuna parola trappola. ''Ciclomotori a due ruote'' è la definizione base di ciò che puoi guidare con la AM.', 'AM = Ciclomotori (2, 3, 4 ruote leggere).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24477, 'Sì, è vero. La patente AM ti permette di guidare anche i ciclomotori a tre ruote, non solo quelli a due. Pensa ad alcuni scooter a tre ruote o piccoli veicoli da lavoro.', 'Nessuna parola trappola. ''Ciclomotori a tre ruote'' rientra nella categoria AM.', 'AM = Ciclomotori (2, 3, 4 ruote leggere).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24478, 'Corretto, è vero. L''età minima per poter fare l''esame e ottenere la patente AM è 14 anni.', 'Nessuna parola trappola. ''14 anni'' è l''età giusta.', 'AM = 14 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24479, 'Sì, è vero. I ciclomotori a motore termico (a benzina) non possono avere una cilindrata superiore a 50 cm³. Questo è il limite per la patente AM.', 'La parte ''non superiore a 50 cm3'' è fondamentale. È il limite di cilindrata per i ciclomotori.', 'AM = 50 cm³ (o 4 kW elettrici).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24481, 'Questa affermazione è falsa. Con la patente AM puoi guidare sia i ciclomotori a due ruote che quelli a tre ruote. Non serve la patente A1 per i ciclomotori a tre ruote.', 'La frase ''mentre per condurre i ciclomotori a tre ruote occorre la patente A1'' è la parte sbagliata e quindi la trappola.', 'AM = tutti i ciclomotori (2 o 3 ruote).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24482, 'Questa affermazione è falsa. Anche se puoi prendere la patente AM a 14 anni in Italia, non ''in tutti'' i paesi dell''Unione Europea puoi guidare a quell''età. Alcuni paesi richiedono 16 anni.', 'La parola ''tutti'' è la trappola. Non è valido per tutti i paesi.', 'AM all''estero: attenzione all''età minima locale!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24483, 'Questa affermazione è falsa. La patente AM ti permette di guidare solo i quadricicli LEGGERI. I quadricicli ''non leggeri'' (anche se con potenza limitata) richiedono una patente superiore, come la B1 o la B.', 'Le parole ''quadricicli non leggeri'' sono la trappola. La AM è solo per i leggeri.', 'AM = solo quadricicli LEGGERI.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24484, 'Questa affermazione è falsa. La patente AM è per i ciclomotori, non per i motocicli. I motocicli sono veicoli diversi e richiedono patenti di categoria A (A1, A2, A), anche se hanno un motore elettrico.', 'La parola ''motocicli'' è la trappola. La patente AM non abilita alla guida di motocicli.', 'AM = Ciclomotori, non motocicli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24485, 'Questa affermazione è falsa. Per ottenere la patente AM, come per tutte le patenti, devi sempre superare sia l''esame di teoria che quello di pratica. L''età non cambia questa regola.', 'La frase ''senza dover sostenere gli esami teorici e pratici'' è la trappola. Gli esami sono sempre obbligatori.', 'Ogni patente = esami (teoria + pratica).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24486, 'Questa affermazione è falsa. La patente AM abilita sempre e solo alla guida di ciclomotori. Non ci sono ''promozioni'' o cambiamenti dopo 3 anni che ti permettano di guidare motocicli (anche se di bassa potenza). Per i motocicli serve una patente di categoria A.', 'Le frasi ''conseguita da almeno 3 anni'' e ''abilita alla guida dei motocicli'' sono le trappole. La patente AM non si ''trasforma'' in una patente per motocicli.', 'AM = sempre e solo ciclomotori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24488, 'La patente A1 ti permette di guidare motocicli con una cilindrata massima di 125 cm3, una potenza massima di 11 kW e un rapporto potenza/peso non superiore a 0,1 kW/kg. Questa domanda descrive esattamente i limiti corretti per la patente A1.', 'Le espressioni ''fino a'' e ''non superiore a'' indicano i limiti massimi consentiti. È importante ricordare tutti e tre i limiti (cilindrata, potenza e rapporto potenza/peso).', 'A1 = 125cc, 11kW, 0.1 kW/kg. Ricorda i tre numeri magici!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24489, 'Sì, con la patente A1 puoi guidare anche i tricicli a motore, ma solo se la loro potenza non supera i 15 kW. Se la potenza è maggiore, serve un''altra patente.', 'La frase ''non superiore a 15 kW'' è fondamentale. Indica il limite massimo di potenza per i tricicli che puoi guidare con la A1.', 'Tricicli A1: max 15 kW.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24490, 'La patente A1 ti permette di guidare alcune macchine agricole, ma solo quelle piccole, che hanno dimensioni e peso simili a un motoveicolo. Non puoi guidare tutte le macchine agricole, solo quelle ''leggere''.', 'La parte ''che rientrano nei limiti di sagoma e di massa previsti per i motoveicoli'' è la condizione chiave. Non tutte le macchine agricole sono incluse.', 'A1 = Macchine agricole ''leggere'' (come motoveicoli).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24491, 'Per poter prendere la patente A1, devi aver compiuto almeno 16 anni. È una patente pensata per i giovani conducenti.', 'La parola ''almeno'' significa che 16 anni è l''età minima. Puoi prenderla a 16 anni o più, ma non prima.', 'A1 = 16 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24493, 'Se hai la patente A1, puoi guidare automaticamente anche tutti i veicoli che si possono guidare con la patente AM (ciclomotori e quadricicli leggeri). È come un ''upgrade'': la patente superiore include quella inferiore.', 'La parola ''anche'' è importante. Significa che la A1 copre sia i veicoli specifici della A1 sia quelli della AM.', 'A1 include AM.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24494, 'Non è vero che devi avere per forza la patente AM prima di prendere la A1. Puoi prendere la patente A1 direttamente a 16 anni, senza aver mai avuto la AM.', 'La parola ''solo'' è una trappola! Indica un''esclusività che in questo caso non esiste. Non è un requisito obbligatorio avere la AM per prendere la A1.', '''Solo'' è spesso FALSO. Non serve la AM per la A1.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24495, 'Attenzione! La patente A1 non ti permette di guidare *tutti* i motocicli fino a 125 cm3. Ci sono anche altri limiti importanti da rispettare: la potenza non deve superare 11 kW e il rapporto potenza/peso non deve superare 0,1 kW/kg. Un motociclo da 125 cm3 potrebbe avere una potenza troppo alta per la A1.', 'La parola ''tutti'' è la trappola principale. Non è vero per tutti i motocicli di quella cilindrata, ci sono altri limiti da considerare.', '''Tutti'' è spesso FALSO. Ricorda i limiti di potenza e peso per la A1.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24496, 'Con la patente A1, i tricicli a motore non possono mai superare i 15 kW di potenza. Questo limite vale sempre, indipendentemente dall''età del conducente. Per guidare tricicli più potenti serve la patente A e un''età minima di 21 anni.', 'La frase ''superiore a 15 kW'' è il punto chiave. La patente A1 non permette mai di guidare tricicli con più di 15 kW. L''età del conducente non cambia questo limite per la A1.', 'A1 = Tricicli MAX 15 kW. Mai superiore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24497, 'Le macchine operatrici (come escavatori, pale meccaniche, ecc.) non si possono guidare con la patente A1. Per queste macchine serve almeno la patente B o altre patenti specifiche, non quelle per motocicli.', 'La frase ''macchine operatrici'' è la chiave. Queste macchine non rientrano nelle categorie che puoi guidare con la patente A1.', 'A1 = NO macchine operatrici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24498, 'Un conducente con patente A1 che ha meno di 18 anni non può trasportare passeggeri, non importa l''età del passeggero. Per poter trasportare un passeggero, il conducente deve aver compiuto almeno 18 anni.', 'La parte ''ma solo se lo stesso è maggiorenne'' è una distrazione. Il problema non è l''età del passeggero, ma l''età del conducente, che deve essere maggiorenne per trasportare chiunque.', 'Passeggero A1: conducente DEVE avere 18 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24499, 'Le patenti non ''cambiano'' o si ''aggiornano'' automaticamente. Per passare da una categoria all''altra (ad esempio da A1 ad A2, o da A2 ad A) devi fare un nuovo esame pratico, oppure, in alcuni casi, attendere l''età minima e aver già la patente inferiore da un certo tempo. Non è un processo automatico.', 'La parola ''automaticamente'' è la trappola. Le patenti non si trasformano da sole, richiedono sempre un''azione (esame o attesa dell''età con requisiti specifici).', '''Automaticamente'' è spesso FALSO. Le patenti non si aggiornano da sole.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24500, 'La patente A2 permette di guidare motocicli con una potenza massima di 35 kW e un rapporto potenza/peso non superiore a 0,2 kW/kg. È importante anche che il motociclo non sia una versione ''depotenziata'' di un modello che in origine ha più del doppio della potenza (cioè, se l''originale ha 70 kW, non puoi guidare la versione da 35 kW con la A2).', 'Le parole chiave sono i limiti precisi: ''fino a 35 kW'', ''non superiore a 0,2 kW/kg'' e ''non siano derivati da una versione... che sviluppi oltre il doppio della potenza massima''. Ricorda bene questi numeri!', 'A2 = 35 kW, 0,2 kW/kg, non più del doppio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24501, 'Le patenti di categoria superiore (come la A2) includono sempre le categorie inferiori (come A1 e AM). Quindi, se hai la A2, puoi guidare anche i veicoli che si guidano con la A1 e la AM.', 'La frase ''abilita anche'' è importante perché indica che la A2 copre più veicoli, inclusi quelli delle patenti minori.', 'Patente superiore include quelle inferiori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24502, 'L''età minima per prendere la patente A2 è 18 anni. Quindi, se hai almeno 18 anni, puoi fare l''esame.', 'Il requisito di età è ''almeno 18 anni''.', 'A2 = 18 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24503, 'Indipendentemente dalla patente che hai, puoi trasportare un passeggero solo se il veicolo è omologato per due persone e questo è indicato sulla sua carta di circolazione. Non dipende dalla patente, ma dal veicolo.', 'La condizione fondamentale è ''solo se il posto del passeggero è previsto sulla carta di circolazione''.', 'Passeggero? Controlla la carta di circolazione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24504, 'Se hai la patente A2 da almeno due anni, puoi fare un esame pratico per ottenere la patente A (senza limiti di potenza) anche se non hai ancora 24 anni. Questo è un percorso accelerato per i più esperti.', 'I punti chiave per l''accesso anticipato alla patente A sono ''da almeno due anni'' e ''anche se ha meno di 24 anni''.', 'A2 + 2 anni = A (anche prima dei 24).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24505, 'La patente A2, come le altre patenti di categoria A, permette di guidare anche le macchine agricole che sono piccole e leggere, cioè che rientrano nei limiti di dimensioni e peso dei motoveicoli.', 'Le parole ''anche le macchine agricole'' e ''che rientrano nei limiti di sagoma e di massa dei motoveicoli'' specificano quali macchine agricole sono coperte.', 'Patenti A = anche macchine agricole piccole.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24506, 'Questa affermazione è falsa perché l''età minima per la patente A2 è 18 anni, non 20.', 'La parola ''almeno 20 anni'' è il dato errato che rende la frase falsa.', 'A2 = 18 anni, non 20.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24507, 'Questa affermazione è falsa perché i limiti di potenza per la A2 sono fino a 35 kW, non 25 kW. Inoltre, il limite per la derivazione da un modello più potente è ''oltre il doppio'', non ''oltre il triplo''.', 'Le parole ''fino a 25 kW'' e ''oltre il triplo'' sono i dati sbagliati. Ricorda che i limiti corretti sono 35 kW e ''oltre il doppio''.', 'A2 = 35 kW, non 25 kW; doppio, non triplo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24508, 'Questa affermazione è falsa. Come abbiamo visto, si può passare dalla A2 alla A dopo due anni, anche prima dei 24 anni. Non è necessario avere la patente AM e l''età di 24 anni non è un requisito se si hanno i due anni di A2. La parola ''solo'' rende la frase falsa.', 'Le espressioni ''solo se è già in possesso della patente di categoria AM'' e ''ed ha più di 24 anni di età'' sono errate e rendono la frase falsa. La parola ''solo'' è una trappola comune.', 'A2 + 2 anni = A, senza AM e senza aspettare i 24 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24509, 'Questa affermazione è falsa. La patente A2 permette di guidare motocicli fino a 35 kW, quindi può condurre motocicli con potenza superiore a 25 kW (fino a 35 kW). Non c''è un limite di cilindrata specifico per la A2, solo di potenza e rapporto potenza/peso.', 'Le affermazioni ''non può condurre motocicli di cilindrata superiore a 150 cm3'' e ''di potenza superiore a 25 kW'' sono entrambe sbagliate. La A2 non ha limiti di cilindrata e può superare i 25 kW (fino a 35 kW).', 'A2 = 35 kW, nessun limite di cilindrata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24510, 'Questa affermazione è falsa. Puoi prendere la patente A2 direttamente a 18 anni, senza aver prima conseguito la patente A1. Non è un requisito obbligatorio.', 'La parola ''solo'' è la trappola. Non è vero che devi avere la A1 per prendere la A2.', 'A2 diretta a 18 anni, non serve A1.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24511, 'Questa affermazione è falsa. La patente A2 consente di guidare motocicli fino a 35 kW, oltre ai veicoli delle categorie A1 e AM (che includono ciclomotori e quadricicli leggeri). Quindi, non ''solo'' questi ultimi, ma molto di più.', 'La parola ''solo'' è la trappola. La A2 abilita a una gamma più ampia di veicoli, non si limita a ciclomotori e quadricicli leggeri.', 'A2 = motocicli fino a 35 kW + AM + A1. Non ''solo'' ciclomotori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24512, 'Questa affermazione è falsa. La patente A2 abilita alla guida dei tricicli a motore con potenza non superiore a 15 kW. Quindi, ne consente alcuni, non ''nessuno''.', 'La frase ''non consente di condurre alcun tipo'' è la trappola. La A2 permette di guidare tricicli fino a 15 kW.', 'A2 = tricicli fino a 15 kW. Non ''nessuno''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24513, 'La patente di categoria A è la patente ''completa'' per i motocicli. Questo significa che, una volta conseguita, permette di guidare qualsiasi tipo di moto, senza limiti di cilindrata o potenza, sia con che senza carrozzetta.', 'La frase ''tutti i motocicli'' è la chiave. Indica che non ci sono eccezioni o limiti per i motocicli una volta ottenuta la patente A.', 'Patente A = Moto senza limiti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24514, 'Con la patente A puoi guidare tutti i tricicli a motore. Tuttavia, per i tricicli che hanno una potenza superiore a 15 kW, c''è una condizione di età: devi aver compiuto almeno 21 anni per poterli guidare.', 'La parte ''ma solo se il conducente ha almeno 21 anni'' è fondamentale. Indica una condizione specifica per i tricicli più potenti, non per tutti i veicoli della categoria A.', 'Tricicli potenti (>15kW) con A = 21 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24515, 'La patente A abilita alla guida di tutti i motocicli. I motocicli con cilindrata superiore a 50 cm³ e velocità superiore a 45 km/h sono i motocicli ''veri e propri'', e la patente A li include senza problemi.', 'La frase ''anche se sviluppano una velocità superiore a 45 km/h'' serve a distinguere chiaramente dai ciclomotori, che hanno limiti inferiori. La patente A copre tutto ciò che è ''motociclo''.', 'Patente A = Moto ''grandi'' senza problemi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24516, 'Esistono due modi per prendere la patente A. L''accesso diretto significa che se non hai già la patente A2 da almeno due anni, devi aspettare di compiere 24 anni per poterla conseguire.', 'Le parole ''accesso diretto'' e ''solo se ha compiuto 24 anni di età'' sono cruciali. Indicano la via più lunga per chi non ha esperienza precedente con la patente A2.', 'A diretta = 24 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24517, 'Questo è il metodo dell''accesso graduale. Se hai già la patente A2 da almeno due anni, puoi ''salire'' alla patente A a un''età più giovane, cioè a 20 anni.', 'Le espressioni ''accesso graduale'', ''20 anni di età'' e ''titolare di patente A2 da almeno 2 anni'' sono le condizioni specifiche per questa modalità di conseguimento.', 'A graduale = 20 anni + A2 da 2 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24518, 'La patente A è la categoria più alta per le due ruote. Questo significa che, una volta ottenuta, include automaticamente la possibilità di guidare tutti i veicoli che si possono condurre con le patenti di categoria inferiore (AM, A1, A2).', 'La frase ''abilita anche alla guida dei veicoli che si possono condurre con le patenti A1, A2 e AM'' spiega il concetto di ''scalabilità'' delle patenti: la più grande include le più piccole.', 'A = AM + A1 + A2.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24519, 'Come già visto, la patente A permette di guidare i tricicli. Però, se il triciclo ha una potenza superiore a 15 kW, è obbligatorio che il conducente abbia almeno 21 anni di età.', 'Le parole ''tricicli di potenza superiore a 15 kW'' e ''ma solo se il conducente ha almeno 21 anni di età'' ribadiscono la condizione di età per i tricicli più potenti.', 'Tricicli >15kW con A = 21 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24520, 'Questa affermazione è falsa. Una volta conseguita la patente A, non ci sono limiti di potenza per i motocicli che puoi guidare. Il limite di 35 kW per i primi 2 anni è una condizione della patente A2, non della A.', 'La trappola è ''purché abbiano una potenza inferiore a 35 kW per i primi 2 anni dal conseguimento''. Questo limite non si applica alla patente A, che abilita subito a guidare motocicli di qualsiasi potenza.', 'Patente A = Potenza illimitata (subito).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24521, 'Questa affermazione è falsa. La patente A abilita alla guida di motocicli e tricicli, ma non dei quadricicli non leggeri. Per i quadricicli non leggeri serve la patente B1 o la patente B.', 'La parola chiave è ''quadricicli non leggeri''. La patente A non copre questa categoria di veicoli. La parte ''qualunque sia l''età del conducente'' è un tentativo di distrazione.', 'Patente A = No quadricicli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24522, 'Questa affermazione è falsa. L''accesso graduale alla patente A avviene a 20 anni di età, non a 18. Inoltre, per l''accesso graduale, devi essere titolare della patente A2 da almeno 2 anni, non della A1.', 'Le trappole sono ''18 anni di età'' e ''patente A1''. Le condizioni corrette per l''accesso graduale sono 20 anni e patente A2 da almeno 2 anni.', 'A graduale = 20 anni + A2 da 2 anni (non 18 e non A1).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24523, 'Questa affermazione è falsa. Per guidare tricicli di potenza superiore a 15 kW con la patente A, è obbligatorio aver compiuto almeno 21 anni di età. Non è vero che si possono guidare ''qualunque sia l''età del conducente''.', 'La trappola è ''qualunque sia l''età del conducente''. C''è un limite di età (21 anni) specifico per i tricicli potenti.', 'Tricicli >15kW con A = 21 anni (non qualunque età).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24524, 'Questa affermazione è falsa. L''accesso diretto alla patente A, per chi non ha la patente A2 da almeno 2 anni, richiede di aver compiuto 24 anni di età, non 21. A 21 anni si possono guidare i tricicli potenti, ma non si consegue la patente A per accesso diretto.', 'La trappola è ''21 anni di età''. L''età corretta per l''accesso diretto alla patente A è 24 anni.', 'A diretta = 24 anni (non 21).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24525, 'Questa affermazione è falsa. Le patenti di guida europee, come la patente A italiana, sono valide in tutti i paesi dell''Unione Europea e in molti altri paesi del mondo, senza la necessità di sostenere ulteriori esami o di avere permessi speciali per guidare all''estero.', 'Le frasi ''ma solo in Italia'' e ''per guidare all''estero è necessario sostenere un ulteriore esame'' sono le trappole. Le patenti europee hanno validità internazionale.', 'Patente A = Valida in UE (e oltre).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24526, 'Questa affermazione è falsa. Non è ''in ogni caso'' necessario aver compiuto 24 anni. La patente A può essere conseguita anche a 20 anni, se si segue la procedura di accesso graduale (cioè, se si è già titolari di patente A2 da almeno 2 anni).', 'La trappola è ''in ogni caso''. Questa espressione indica un''assoluta, ma esiste un''eccezione (l''accesso graduale a 20 anni).', 'A = 20 anni (graduale) O 24 anni (diretta). Non ''sempre'' 24.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24527, 'La patente di categoria B1 può essere conseguita già a 16 anni di età. Questo la rende accessibile ai giovani che vogliono iniziare a guidare veicoli specifici come i quadricicli non leggeri.', 'Nessuna parola trappola evidente. La frase è diretta e corretta.', 'B1 = 16 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24530, 'La patente B1 è fatta proprio per guidare i quadricicli non leggeri. Questi veicoli hanno un peso a vuoto massimo di 400 kg (per trasporto persone) o 550 kg (per trasporto merci) e una potenza massima di 15 kW.', 'La frase ''alcuni tipi'' è corretta, perché la B1 non abilita a tutti i quadricicli, ma solo a quelli ''non leggeri'' con le caratteristiche specifiche.', 'B1 = Quadricicli non leggeri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24531, 'I ''Quad'' sono un tipo di quadriciclo non leggero e, come tali, possono essere guidati con la patente B1. Hanno il manubrio e sono spesso usati per il tempo libero.', 'La specificazione ''(Quad)'' aiuta a capire meglio il tipo di veicolo, non è una trappola.', 'B1 = Quad (con manubrio).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24532, 'Questa affermazione è FALSA. La patente B1 non abilita a condurre motocicli. La descrizione dei motocicli (fino a 125 cm3, 11 kW, ecc.) si riferisce ai veicoli che si possono guidare con la patente A1.', 'La parola ''motocicli'' è la trappola principale. La B1 non c''entra nulla con i motocicli.', 'B1 NON è per motocicli (quelli sono A1).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24533, 'Questa affermazione è FALSA. La patente B1 non permette di guidare ''tutti'' i tricicli a motore. Per i tricicli a motore con potenza superiore a 15 kW, serve la patente A (o la B se si hanno 21 anni). La B1 non li copre. Inoltre, la B1 si prende a 16 anni, non a 18.', 'La trappola è ''tutti i tricicli a motore''. La B1 ha limiti specifici. Anche la condizione ''solo se il conducente ha già compiuto i 18 anni'' è fuorviante per la B1.', 'B1 NON copre TUTTI i tricicli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24534, 'Questa affermazione è FALSA. La patente B1 non abilita a condurre autovetture, nemmeno quelle piccole o monoposto. Le autovetture richiedono la patente B.', 'La parola ''autovetture'' è la trappola. La B1 è per quadricicli non leggeri, non per autovetture. La condizione sui passeggeri è un tentativo di confondere.', 'B1 NON è per autovetture.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24535, 'Questa affermazione è FALSA. La patente B1 non include la patente A1. È la patente B che include la A1, ma la B1 è una categoria a sé stante, specifica per i quadricicli non leggeri.', 'La frase ''abilita anche alla guida dei veicoli che si possono condurre con la patente A1'' è la trappola. Questo è vero per la patente B, ma non per la B1.', 'B1 NON include A1 (solo la B include A1).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24536, 'Questa affermazione è FALSA. Per passare dalla patente B1 alla patente B, non basta solo un esame teorico integrativo. Bisogna sostenere anche un esame pratico di guida, oltre all''eventuale esame di teoria se non si è già superato quello della patente B.', 'La trappola è ''solo un esame teorico integrativo''. Manca l''esame pratico, che è fondamentale.', 'B1 a B = Teoria + Pratica (non solo teoria).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24537, 'La patente B ti permette di guidare auto e altri veicoli leggeri che non pesano più di 3,5 tonnellate e che possono portare al massimo 8 passeggeri più il conducente. Questo è il limite standard per la patente B.', 'Attenzione al limite ''non più di otto persone oltre al conducente'', è preciso.', 'Patente B = max 3,5t e 8+1 persone.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24538, 'Con la patente B puoi guidare un''auto e attaccarci un rimorchio piccolo, che pesa al massimo 750 kg. Questo è sempre permesso con la patente B.', 'La definizione di ''rimorchio leggero (massa fino a 750 chilogrammi)'' è importante.', 'Auto + rimorchio leggero (max 750kg) = OK con Patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24539, 'Sì, puoi guidare un camper (autocaravan) con la patente B, a patto che il suo peso massimo autorizzato non superi le 3,5 tonnellate. Se pesa di più, serve un''altra patente.', 'Il limite di peso ''non superiore a 3,5 tonnellate'' è fondamentale anche per i camper.', 'Camper (autocaravan) < 3,5t = Patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24540, 'Con la patente B puoi guidare tutte le macchine agricole, anche quelle grandi o ''eccezionali''. Non c''è un limite di peso o dimensione per le macchine agricole con la patente B.', 'La parte ''comprese quelle definite eccezionali'' è importante perché conferma che non ci sono eccezioni per le macchine agricole.', 'Patente B = Tutte le macchine agricole (anche eccezionali).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24541, 'Puoi guidare un''auto con un rimorchio più pesante di 750 kg, ma c''è una condizione: il peso totale dell''auto più il rimorchio non deve superare le 3,5 tonnellate. Se supera, serve la patente B96 o BE.', 'La condizione sul peso totale del ''complesso'' (''purché la massa massima autorizzata del complesso non superi 3,5 tonnellate'') è la chiave.', 'Auto + rimorchio (>750kg) = OK se complesso < 3,5t.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24542, 'Con la patente B puoi guidare in Italia i veicoli che si guidano con la patente A1 (moto leggere fino a 125cc, 11kW, rapporto potenza/massa 0,1 kW/kg). Questo è un permesso speciale solo per l''Italia.', 'La limitazione ''solo sul territorio nazionale (Italia)'' è importante. Fuori dall''Italia, per la A1 serve la A1.', 'Patente B = A1 in Italia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24543, 'La patente B è ''superiore'' alle patenti AM e B1. Questo significa che se hai la B, puoi guidare anche i veicoli per cui servono la AM (ciclomotori, quadricicli leggeri) e la B1 (quadricicli non leggeri).', 'La frase ''anche alla guida dei veicoli che si possono condurre con le patenti AM e B1'' indica che la B include queste categorie minori.', 'Patente B include AM e B1.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24544, 'Per guidare tricicli a motore potenti (oltre 15 kW) con la patente B, devi avere almeno 21 anni e puoi farlo solo in Italia. Se hai meno di 21 anni, anche con la B, non puoi guidarli.', 'Doppia condizione importante: ''solo sul territorio nazionale (Italia) e se il conducente ha almeno 21 anni''.', 'Tricicli > 15kW = Patente B + 21 anni + Solo Italia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24545, 'Con la patente B puoi guidare autocarri (furgoni) che non superano le 3,5 tonnellate. E puoi anche attaccarci un rimorchio leggero (fino a 750 kg).', 'Il limite di peso per l''autocarro (''non superiore a 3.500 chilogrammi'') e la possibilità del ''rimorchio leggero'' sono i punti chiave.', 'Autocarro < 3,5t (+ rimorchio leggero) = Patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24547, 'La patente B non ti permette di guidare tutte le moto. Per le moto più potenti (quelle della categoria A2 e A) serve la patente specifica per moto. La B include solo la A1 (in Italia) e la AM.', 'Le patenti ''A2 e A'' sono per moto di media e grande cilindrata, non incluse nella B.', 'Patente B NON è per tutte le moto (no A2, no A).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24548, 'La patente B ti permette di guidare veicoli che trasportano al massimo 8 persone più il conducente. Un autobus, anche se piccolo, ha più posti e richiede una patente diversa (come la D1 o D).', 'Il numero di posti (''al massimo 16 posti, escluso il conducente'') è troppo alto per la patente B.', 'Patente B = max 8+1 persone, NON autobus.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24549, 'La patente B ha un limite di peso di 3,5 tonnellate. Se un autocarro pesa più di 3,5 tonnellate, anche se meno di 7,5 tonnellate, non puoi guidarlo con la patente B. Serve la patente C1 o C.', 'La frase ''superiore a 3,5 tonnellate'' è il limite che rende la frase falsa.', 'Patente B = autocarri SOLO fino a 3,5t.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24550, 'Per i primi tre anni di patente B, non puoi guidare auto troppo potenti. Ci sono due limiti: la potenza specifica non deve superare 55 kW per tonnellata E la potenza massima non deve superare 70 kW. La domanda usa ''o'' e dice ''potenza massima di 70 kW'', ma il limite è ''superiore a 70 kW''. Un''auto con esattamente 70 kW è permessa (se rispetta l''altro limite), quindi la frase è falsa.', 'L''uso di ''o'' invece di ''e'' e il ''di 70 kW'' invece di ''superiore a 70 kW'' sono le trappole. Il limite è ''massimo 70 kW'', quindi 70 kW è incluso.', 'Neopatentati: max 55 kW/t E max 70 kW. Attenzione a ''o'' e ''di''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24551, 'Con la patente B puoi guidare le macchine agricole (anche eccezionali), ma NON le macchine operatrici eccezionali. Per queste ultime serve la patente C1 o C. Le macchine operatrici normali (non eccezionali) si possono guidare con la B.', 'La parola ''eccezionali'' qui è la trappola. Le macchine operatrici *non eccezionali* si possono guidare con la B.', 'Patente B = Macchine agricole (tutte), Macchine operatrici (NON eccezionali).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24552, 'La patente B ti permette di guidare autovetture con al massimo 9 posti (8 passeggeri + 1 conducente), ma non ''solo'' autovetture. Puoi guidare anche autocarri leggeri, autocaravan, macchine agricole, ecc. La parola ''solo'' rende la frase falsa.', 'La parola ''solo'' è la trappola. La patente B abilita a guidare molti altri tipi di veicoli.', 'Patente B = NON ''solo'' autovetture.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24553, 'Il peso massimo del rimorchio che puoi trainare con la patente B è limitato. Se il rimorchio pesa più di 3.500 kg, non puoi guidarlo con la sola patente B. Anche con la B96 o BE ci sono limiti sul peso totale del complesso.', 'Un rimorchio con ''massa superiore a 3.500 chilogrammi'' non è permesso con la patente B.', 'Rimorchio > 3,5t = NO Patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24554, 'Con la patente B, il peso totale dell''auto più il rimorchio (il ''complesso veicolare'') non deve superare le 3,5 tonnellate (3.500 kg). 4.500 kg è troppo, per questo serve la patente BE o B96 (con limiti diversi).', 'Il peso ''pari a 4.500 chilogrammi'' è superiore al limite di 3,5 tonnellate per la patente B.', 'Complesso veicolare > 3,5t = NO Patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24555, 'Anche se hai più di 24 anni, la patente B non ti permette di guidare tutti i motocicli. Ti permette di guidare solo quelli della categoria A1 (in Italia). Per le moto più grandi serve la patente A specifica.', 'La parola ''tutti'' è la trappola. La patente B non copre tutte le categorie di moto.', 'Patente B = NON tutti i motocicli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24556, 'Con la patente B puoi guidare i camper, ma solo quelli che non superano le 3,5 tonnellate di massa massima autorizzata. Se un camper è più pesante, serve una patente diversa (come la C1). La parola ''tutti'' rende la frase falsa.', 'La parola ''tutti'' è la trappola. C''è un limite di peso per gli autocaravan.', 'Patente B = NON tutti i camper (solo < 3,5t).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24557, 'La patente B con codice 96 ti permette di guidare un''auto che traina un rimorchio ''pesante'' (che pesa più di 750 kg), a condizione che il peso totale di auto più rimorchio non superi i 4.250 kg. Questa è proprio la definizione principale di questa abilitazione.', 'Le parole chiave sono ''rimorchio non leggero'' (significa che pesa più di 750 kg) e ''massa massima autorizzata del complesso'' (il peso totale di auto e rimorchio).', 'B96: Rimorchio > 750kg E Complesso <= 4250kg.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24558, 'Sì, puoi ottenere il codice 96 sulla tua patente B anche dopo aver già preso la patente B. Devi solo fare un esame pratico di guida con un veicolo adatto (auto con rimorchio).', 'La frase ''anche successivamente'' indica che c''è flessibilità, non è l''unica opzione.', 'B96: Si può prendere anche DOPO la patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24559, 'Sì, puoi ottenere il codice 96 sulla tua patente B anche nello stesso momento in cui prendi la patente B. Farai l''esame per la patente B e poi l''esame pratico specifico per il codice 96.', 'La frase ''anche contestualmente'' significa ''nello stesso momento'', evidenziando la flessibilità.', 'B96: Si può prendere anche INSIEME alla patente B.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24560, 'Questa domanda ripete la stessa informazione della domanda 24557. Il codice 96 sulla patente B ti permette di guidare un''auto con un rimorchio ''pesante'' (più di 750 kg), purché il peso totale di auto e rimorchio non superi i 4.250 kg.', 'Ancora, ''rimorchio non leggero'' e ''massa massima autorizzata del complesso'' sono i termini chiave da capire bene.', 'B96: Rimorchio > 750kg E Complesso <= 4250kg.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24561, 'Questa è la situazione specifica per cui serve il codice 96. Se il peso totale di auto e rimorchio è tra 3.500 kg e 4.250 kg (e il rimorchio è ''pesante''), allora la patente B con codice 96 è sufficiente.', 'La parte ''superiore a 3.500 chilogrammi ma non superiore a 4.250 chilogrammi'' definisce esattamente il ''campo d''azione'' del codice 96 per i rimorchi non leggeri.', 'B96: Per totali tra 3500kg e 4250kg (con rimorchio pesante).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24562, 'Falso. Il codice 96 è per auto con rimorchio, e il peso totale massimo è 4.250 kg. Non serve per gli ''autosnodati'' (che sono veicoli molto più grandi, come autobus o camion articolati) e non permette di guidare veicoli con un peso totale superiore a 4.250 kg.', 'Le parole ''autosnodati'' e ''superiore a 4.250 chilogrammi'' sono le trappole. Il codice 96 non riguarda questi veicoli o questi pesi.', 'B96 NON è per autosnodati o oltre 4250kg.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24563, 'Falso. Il codice 96 è un''estensione della patente B per i rimorchi. Non ha nulla a che fare con le moto. Per guidare le moto servono le patenti di categoria A (A1, A2, A).', 'La parola ''motocicli'' è la trappola principale. Il codice 96 non riguarda le due ruote.', 'B96 = Rimorchi, NON moto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24564, 'Falso. Per ottenere il codice 96 ti serve solo la patente B (o la prendi insieme). Non è necessario avere la patente A (per le moto).', 'La parola ''solo'' è una trappola comune. Spesso, quando c''è ''solo se'', la risposta è falsa perché introduce una condizione troppo restrittiva e non vera. La ''patente A'' è irrilevante.', 'B96 richiede solo la B, non la A.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24565, 'Falso. Il limite massimo di peso totale (auto + rimorchio) per il codice 96 è 4.250 kg. Questa domanda parla di un peso ''superiore a 4.250 chilogrammi'', il che è sbagliato. Per pesi maggiori (fino a 7.000 kg) con rimorchio non leggero, serve la patente BE.', 'La frase ''superiore a 4.250 chilogrammi'' è la trappola. Il limite del B96 è proprio 4.250 kg, non oltre.', 'B96: limite massimo 4250kg totali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24566, 'Falso. Le patenti di guida europee, inclusi i codici armonizzati come il 96, sono valide in tutti i paesi dell''Unione Europea e in molti altri paesi che le riconoscono. Non sono limitate ''solo in Italia''.', 'La parola ''solo'' è una trappola. Le patenti europee hanno validità internazionale (nei paesi che le riconoscono).', 'Patente UE = Valida in Europa, non ''solo in Italia''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24567, 'La patente BE serve proprio per guidare un''auto (fino a 3.500 kg) che traina un rimorchio pesante (fino a 3.500 kg). Questo significa che il peso totale del veicolo più il rimorchio può superare i 4.250 kg, arrivando fino a 7.000 kg. Quindi, l''affermazione è VERA.', 'La frase ''anche se la massa del complesso veicolare è superiore a 4.250 chilogrammi'' è importante perché chiarisce che la BE copre proprio i casi in cui la patente B o B96 non bastano.', 'BE = Auto B + Rimorchio pesante (fino a 3.5t).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24568, 'Con la patente B, puoi guidare un''auto che traina un rimorchio, ma ci sono dei limiti. Se il rimorchio pesa più di 750 kg e il peso totale (auto + rimorchio) supera i 4.250 kg, allora serve la patente BE. In questo caso, il rimorchio è di 2.000 kg e il complesso è di 4.500 kg, quindi superiamo i limiti della patente B e anche della B96. Perciò, l''affermazione è VERA.', 'La ''massa massima autorizzata del complesso veicolare pari a 4.500 chilogrammi'' è il dato chiave. Supera i 4.250 kg, rendendo necessaria la BE.', 'Complesso > 4.250 kg con rimorchio > 750 kg = BE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24569, 'Questa è la definizione esatta della patente BE. Ti permette di guidare un veicolo della categoria B (che pesa al massimo 3.500 kg) che traina un rimorchio, il cui peso può arrivare anch''esso fino a 3.500 kg. Il peso totale del complesso può quindi arrivare fino a 7.000 kg. L''affermazione è VERA.', 'Le parole ''autotreni'' e ''fino a 3.500 chilogrammi'' per entrambi i componenti (autoveicolo e rimorchio) descrivono perfettamente i limiti della BE.', 'BE = Auto B (max 3.5t) + Rimorchio (max 3.5t).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24570, 'Quando si consegue una patente di categoria superiore, questa include automaticamente le categorie inferiori. La patente BE è un''estensione della patente B, quindi ti permette di guidare tutti i veicoli che puoi guidare con la AM, B1, B e anche con la B con codice armonizzato 96. L''affermazione è VERA.', 'La parola ''anche'' indica che la BE include le altre categorie menzionate. È importante sapere quali patenti sono ''inglobate''.', 'BE ''copre'' AM, B1, B, B96.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24571, 'Calcoliamo il peso totale: 3.500 kg (autoveicolo) + 1.000 kg (rimorchio) = 4.500 kg. Con la patente B normale, puoi guidare complessi fino a 4.250 kg solo se il rimorchio non supera i 750 kg. Qui il rimorchio è di 1.000 kg e il complesso è di 4.500 kg, quindi superiamo i limiti della patente B e anche della B96. Perciò, è necessario avere la patente BE. L''affermazione è VERA.', 'La frase ''è necessario aver conseguito la patente di categoria BE'' è diretta e corretta, dato che i pesi superano i limiti delle patenti inferiori.', '3.5t + 1t = 4.5t. Se > 4.25t e rimorchio > 750kg, serve BE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24572, 'La patente BE ti permette di guidare un autoveicolo che rientra nella categoria B, cioè con una massa massima autorizzata fino a 3.500 kg. In questo caso, l''autoveicolo pesa 4.000 kg, quindi è troppo pesante per la patente B e di conseguenza anche per la BE. Per guidare un veicolo di 4.000 kg, avresti bisogno almeno di una patente C1. Perciò, l''affermazione è FALSA.', 'La trappola è ''autoveicolo di massa massima autorizzata pari a 4.000 chilogrammi''. La patente BE non aumenta il limite di peso dell''autoveicolo trainante, che deve rimanere entro i 3.500 kg della categoria B.', 'BE = Auto B (max 3.5t) + Rimorchio. Se auto > 3.5t, non basta la BE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24573, 'Un ''minibus'' è un veicolo che trasporta più di 9 persone (compreso il conducente). Per guidare un minibus, anche se traina un rimorchio leggero, è necessaria una patente di categoria D1 o D, non la patente B o BE. La patente BE è per autoveicoli della categoria B (fino a 9 posti e max 3.5t). Perciò, l''affermazione è FALSA.', 'La parola ''minibus'' è la chiave. I veicoli per il trasporto di persone con più di 9 posti non rientrano nella categoria B.', 'Minibus = Patente D1/D. BE non è per minibus.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24574, 'La patente BE include le categorie AM, B1, B e B96. NON include le categorie A (per motocicli) e C1 (per autocarri medi). Quindi, non puoi guidare una moto o un camion medio con la patente BE. L''affermazione è FALSA.', 'Le categorie ''A'' e ''C1'' sono le parole trappola. La BE non ti abilita a guidare motocicli o autocarri medi.', 'BE non è per moto (A) o camion (C1).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24575, 'La patente BE ti permette di trainare un rimorchio con una massa massima autorizzata fino a 3.500 kg. Se il rimorchio pesa più di 3.500 kg, la patente BE non è sufficiente. Per rimorchi così pesanti, servono altre categorie di patente (come la CE o DE, a seconda del veicolo trainante). L''affermazione è FALSA.', 'La frase ''rimorchio di massa superiore a 3.500 chilogrammi'' è il punto cruciale. Questo peso supera il limite massimo consentito per il rimorchio con la patente BE.', 'Rimorchio BE max 3.5t.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24576, 'L''età minima per conseguire la patente di categoria BE è di 18 anni, non 21 anni. Si può conseguire anche insieme alla patente B, ma l''età indicata nella domanda è sbagliata. Perciò, l''affermazione è FALSA.', 'La frase ''bisogna aver compiuto almeno 21 anni'' è la trappola. L''età corretta è 18 anni.', 'BE = 18 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24577, 'Se commetti una violazione molto grave che prevede la sospensione della patente, gli agenti di polizia te la ritirano subito. Questo serve per impedirti di guidare immediatamente, dato il pericolo o la gravità dell''infrazione.', 'La frase ''sanzioni accessorie della sospensione della patente'' indica che la sospensione non è l''unica punizione, ma una conseguenza aggiuntiva e molto seria.', 'Sospensione = Ritiro immediato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24578, 'Guidare con la patente scaduta significa che non sei più autorizzato a condurre veicoli. Per questo motivo, la patente ti viene ritirata immediatamente, come se non l''avessi valida.', 'La parola ''scaduta'' è la chiave: la patente non è più valida legalmente.', 'Patente scaduta = Ritiro subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24579, 'Guidare in stato di ebbrezza (ubriachi) è estremamente pericoloso per te e per gli altri. Per la sicurezza di tutti, la patente viene ritirata immediatamente per fermarti dal guidare in quelle condizioni.', '''Stato di ebbrezza'' significa essere sotto l''effetto dell''alcol oltre i limiti consentiti dalla legge.', 'Ebbrezza = Ritiro immediato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24580, 'Se il carico sul tuo veicolo è pericoloso e la polizia ti chiede di sistemarlo, ma tu ti rifiuti di farlo, stai mettendo a rischio la sicurezza stradale e disubbidendo a un ordine. Per questo, la patente ti viene ritirata.', 'La parte importante è ''dopo invito degli organi di polizia'' e il rifiuto di sistemare. Non è il carico mal disposto in sé, ma la mancata obbedienza all''ordine di sistemarlo.', 'Carico pericoloso + Disobbedienza = Ritiro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24581, 'Se causi un incidente e ci sono persone ferite, è una situazione molto grave. La patente viene ritirata immediatamente per avviare le indagini e per prevenire ulteriori pericoli.', '''Lesioni a persone'' è la condizione fondamentale. Se ci fossero solo danni materiali, la situazione sarebbe diversa.', 'Incidente con feriti = Ritiro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24582, 'Se ti è stato ordinato di fare un esame di revisione della patente (per esempio, per verificare che sei ancora idoneo a guidare) e non lo fai entro il tempo stabilito, la tua patente non è più considerata valida. Per questo, ti viene ritirata subito.', 'Le parole chiave sono ''obbligato a sostenere un esame di revisione'' e ''non vi si è sottoposto nei termini prescritti''. È la mancata esecuzione dell''obbligo che porta al ritiro.', 'Revisione non fatta = Ritiro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24583, 'La legge punisce il conducente che guida in stato di ebbrezza, non il passeggero. Se il tuo passeggero è ubriaco, non è una tua responsabilità come conducente e non è un motivo per ritirarti la patente.', 'La parola ''passeggero'' è la trappola. La responsabilità è del conducente.', 'Passeggero ubriaco? La tua patente è salva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24584, 'Se sei residente in un altro paese e hai una patente valida di quel paese, puoi guidare in Italia per un certo periodo di tempo (di solito un anno). Non è un motivo per ritirarti la patente immediatamente.', 'La frase ''patente rilasciata da uno stato estero in cui è residente'' indica una situazione regolare, non una violazione.', 'Patente estera valida = Ok (per un periodo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24585, 'Guidare con pneumatici non conformi a quelli indicati sulla carta di circolazione è una violazione che comporta una multa e il fermo del veicolo, ma non il ritiro immediato della patente di guida.', 'La violazione riguarda il veicolo (''pneumatici di dimensioni diverse''), non direttamente la capacità o l''idoneità del conducente a guidare, che giustificherebbe il ritiro della patente.', 'Gomme sbagliate = Multa, non ritiro patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24586, 'Molte infrazioni al Codice della Strada comportano la perdita di punti dalla patente, ma solo le violazioni più gravi prevedono il ritiro immediato della patente. Non tutte le volte che perdi punti ti ritirano la patente.', 'La parola ''tutte le volte'' è una trappola. Non è vero che ogni decurtazione di punti porta al ritiro immediato.', 'Punti persi ≠ Ritiro immediato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24587, 'Se dimentichi a casa la carta di circolazione (il libretto del veicolo), riceverai una multa e dovrai presentare il documento in un ufficio di polizia. Tuttavia, la patente di guida non ti viene ritirata per questa mancanza.', '''Senza avere con sé la carta di circolazione'' è una dimenticanza di un documento, non una violazione grave che mette a rischio la sicurezza immediata.', 'Libretto dimenticato = Multa, non ritiro patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24588, 'Il certificato di proprietà del veicolo non è un documento che devi portare con te quando guidi. Serve per pratiche burocratiche (come la vendita del veicolo), non per la circolazione. Quindi, non ti possono ritirare la patente per questo motivo.', '''Certificato di proprietà'' è il punto chiave. Questo documento non è obbligatorio averlo a bordo del veicolo.', 'Certificato proprietà = Non serve a bordo, nessun ritiro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24589, 'La revisione della patente serve a controllare se il guidatore è ancora in grado di guidare. Se ci sono dubbi sulla sua salute (fisica o mentale), è giusto fare questo controllo per la sicurezza di tutti.', 'La parola chiave è ''dubbi''. Non serve una certezza, basta che ci siano dei sospetti sulla capacità del conducente.', 'Dubbi su salute = Revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24590, 'Sì, sono proprio questi gli enti che hanno l''autorità di chiedere la revisione della patente. L''Ufficio Motorizzazione Civile e il Prefetto sono le figure competenti per queste decisioni.', 'Ricorda che ''Ufficio Motorizzazione civile'' e ''Prefetto'' sono le autorità che possono disporre la revisione.', 'Motorizzazione o Prefetto = Revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24591, 'Un incidente grave con feriti fa pensare che il guidatore potrebbe non essere più idoneo a guidare in sicurezza. Per questo motivo, può essere richiesta la revisione della patente.', 'Attenzione a ''lesioni gravi a persone''. Non un semplice incidente, ma uno con conseguenze importanti per la salute degli altri.', 'Incidente grave = Revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24592, 'Se ci sono dubbi sulla tua capacità di guidare bene (ad esempio, se hai fatto molti incidenti o infrazioni gravi), l''autorità può chiederti di rifare l''esame per verificare la tua ''idoneità tecnica''.', 'Ancora una volta, ''dubbi'' è importante. E ''idoneità tecnica'' si riferisce alla tua abilità pratica e teorica di guidare.', 'Dubbi su capacità = Revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24593, 'Esatto! La revisione consiste proprio in questo: o devi fare una visita medica per controllare la tua salute, oppure devi rifare l''esame di guida (teoria e/o pratica) per dimostrare che sai ancora guidare.', 'Le parole chiave sono ''visita medica'' e ''esame di idoneità tecnica''. Sono le due forme in cui si manifesta la revisione.', 'Revisione = Visita O Esame.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24594, 'Guidare sotto l''effetto di alcol o droghe è estremamente pericoloso e dimostra una grave mancanza di responsabilità. Per questo, è un motivo valido per disporre la revisione della patente.', 'Le espressioni ''stato di ebbrezza'' e ''sostanze stupefacenti'' indicano comportamenti molto gravi alla guida.', 'Alcol/Droga = Revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24595, 'Se perdi tutti i punti della patente, significa che hai commesso troppe infrazioni. In questo caso, la legge prevede che tu debba fare la revisione per dimostrare di essere ancora un guidatore sicuro.', 'La frase ''azzeramento dei ''punti'''' è la condizione specifica che rende la revisione obbligatoria.', 'Punti a zero = Revisione obbligatoria.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24596, 'Se non superi l''esame di revisione, significa che non sei più considerato idoneo a guidare. Di conseguenza, la tua patente ti viene tolta definitivamente (revocata).', 'Le parole ''non supera'' e ''revoca'' sono direttamente collegate. Se non passi, perdi la patente.', 'Revisione fallita = Patente revocata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24597, 'Falso. La revisione della patente riguarda la tua capacità di guidare (salute fisica, mentale e abilità tecnica), non il tuo comportamento morale o la tua condotta generale nella vita. I ''requisiti morali'' sono controllati al momento del primo rilascio della patente, non per la revisione.', 'La trappola è ''requisiti morali''. Questi non sono un motivo per la revisione della patente.', 'Morale NO, solo salute/tecnica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24598, 'Falso. Perdere punti non porta automaticamente alla revisione, a meno che tu non li perda tutti. La revisione scatta solo quando i punti della patente si azzerano completamente, non per due infrazioni da 5 punti.', 'La frase ''per due volte in un anno, in una infrazione che comporta la perdita di almeno 5 punti'' è una condizione specifica che non attiva la revisione. Serve l''azzeramento totale dei punti.', 'Non basta perdere 5 punti due volte, serve azzerare TUTTI i punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24599, 'Falso. Se perdi i requisiti fisici ''permanentemente'' (cioè per sempre), la patente non viene sottoposta a revisione, ma viene direttamente revocata. La revisione serve a verificare se i requisiti ci sono ancora, non quando è già certo che non ci sono più.', 'La parola ''permanentemente (per sempre)'' è la chiave. Se è per sempre, non c''è più nulla da ''revisionare'', si procede con la revoca.', 'Perso per sempre = Revoca, non revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24600, 'Falso. La revisione del veicolo è un controllo tecnico dell''auto, non del guidatore. Se la revisione del veicolo è scaduta, si prende una multa, ma non c''entra nulla con la tua patente di guida.', 'La trappola è ''revisione del veicolo''. Questa riguarda il mezzo, non la tua idoneità a guidare.', 'Revisione veicolo = Multa, non revisione patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24601, 'Falso. Circolare senza i documenti corretti per un''auto storica è una violazione amministrativa che comporta una multa, ma non mette in dubbio la tua capacità di guidare. Non è un motivo per la revisione della patente.', 'La frase ''auto storica senza la prescritta documentazione'' si riferisce a problemi burocratici del veicolo, non del conducente.', 'Documenti auto = Multa, non revisione patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24602, 'Falso. Guidare un veicolo non tuo senza autorizzazione è un problema legale o amministrativo, ma non significa che tu non sia idoneo a guidare. Non è un motivo per la revisione della patente.', 'La trappola è ''veicolo che non è di sua proprietà e non ha un''autorizzazione scritta''. Questo non riguarda la tua idoneità alla guida.', 'Auto non tua = Problema legale, non revisione patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24603, 'Falso. Dimenticare la patente a casa è una semplice infrazione che comporta una multa e l''obbligo di esibirla in un secondo momento. Non significa che non sei idoneo a guidare, quindi non è un motivo per la revisione.', 'La frase ''senza aver con sé la patente'' indica una dimenticanza, non un dubbio sulla tua capacità di guidare.', 'Patente dimenticata = Multa, non revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24604, 'Falso. Se non superi l''esame di revisione della patente, la patente ti viene revocata immediatamente. Non puoi continuare a guidare e non hai la possibilità di ripeterlo più volte con un permesso speciale.', 'La parte ''può ripeterlo altre due volte entro un anno, continuando a guidare con uno speciale permesso'' è completamente falsa. La conseguenza è la revoca immediata.', 'Revisione fallita = Stop alla guida, niente permessi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24605, 'Se ti hanno sospeso la patente, significa che non puoi guidare per un certo periodo. Se guidi lo stesso, è una cosa molto grave e ti tolgono la patente per sempre (revoca).', 'La frase ''nonostante abbia la patente sospesa'' indica un''azione molto grave che porta alla revoca, non solo a una multa.', 'Sospesa + Guida = Revoca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24606, 'In autostrada, invertire la marcia o andare contromano è estremamente pericoloso e può causare incidenti gravissimi. Per questo, è una delle azioni più gravi che portano alla revoca della patente.', 'Le parole ''in autostrada'', ''inverte il senso di marcia'' e ''contro mano'' indicano azioni di estrema pericolosità che comportano la revoca.', 'Autostrada + Contromano = Revoca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24607, 'Per guidare devi avere certi requisiti fisici (ad esempio, vedere bene). Se li perdi per sempre, non puoi più guidare in sicurezza e quindi ti revocano la patente.', 'La parola chiave è ''permanentemente (per sempre)''. Se la perdita dei requisiti è definitiva, si ha la revoca. Se fosse temporanea, sarebbe sospensione.', 'Requisiti fisici persi PER SEMPRE = Revoca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24608, 'Come per i requisiti fisici, anche quelli psichici (mentali) sono importanti per guidare in sicurezza. Se li perdi per sempre, non puoi più guidare e ti revocano la patente.', 'Anche qui, ''permanentemente (per sempre)'' è la parola chiave. Una perdita definitiva dei requisiti psichici porta alla revoca.', 'Requisiti psichici persi PER SEMPRE = Revoca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24609, 'Se decidi di sostituire la tua patente italiana con una di un altro paese, la patente italiana viene ''revocata'' nel senso che non è più valida perché ne hai un''altra. Non è una punizione, ma una procedura amministrativa.', 'La parola ''sostituita'' è importante. Non è una revoca per infrazione, ma una revoca amministrativa perché la patente italiana non serve più.', 'Patente estera = Patente italiana ''revocata'' (sostituita)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24610, 'L''esame di revisione serve a controllare se sei ancora capace di guidare. Se non lo superi, significa che non sei più idoneo e ti revocano la patente.', 'Le parole ''esame di revisione'' e ''non risulti più idoneo'' indicano che non hai superato la verifica delle tue capacità di guida, il che porta alla revoca.', 'Revisione fallita = Revoca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24611, 'Se la patente è scaduta, non è una revoca. Devi solo rinnovarla. Ti fanno una multa, ma non ti tolgono la patente per sempre.', 'La parola ''scaduta di validità'' è la trappola. La scadenza comporta il rinnovo, non la revoca. La revoca è una sanzione molto più grave.', 'Patente scaduta = Rinnovo (non revoca)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24612, 'Se hai la patente ma l''hai dimenticata a casa, ti fanno una multa. Non è una cosa così grave da meritare la revoca, perché la patente ce l''hai.', 'La frase ''senza averla con sè'' significa che la patente esiste ed è valida, ma non è stata portata al momento del controllo. Questo comporta una multa, non la revoca.', 'Dimenticata a casa = Multa (non revoca)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24613, 'Se perdi i requisiti fisici solo per un periodo (ad esempio, dopo un''operazione), la patente viene sospesa, non revocata. Quando stai meglio, puoi tornare a guidare.', 'La parola ''temporaneamente'' è la chiave. Una perdita temporanea dei requisiti porta alla sospensione, non alla revoca, che è definitiva.', 'Requisiti persi TEMPORANEAMENTE = Sospensione (non revoca)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24614, 'Se devi guidare con gli occhiali e non li metti, è una multa e magari ti sospendono la patente per un breve periodo. Non è una revoca, perché puoi rimettere gli occhiali e guidare correttamente.', 'La frase ''senza lenti correttive quando prescritte'' indica una violazione, ma non così grave da portare alla revoca. Si tratta di una multa o sospensione.', 'Occhiali dimenticati = Multa/Sospensione (non revoca)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24615, 'Gli organi di polizia (Carabinieri, Polizia) possono ritirare la patente in certi casi, ma la decisione finale sulla revoca spetta ad altre autorità, come la Prefettura o la Motorizzazione Civile.', 'La frase ''dagli organi di polizia'' è la trappola. La polizia può ritirare la patente, ma non disporre la revoca definitiva. Quella è competenza di altre autorità.', 'Polizia = Ritira (non revoca)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24616, 'Guidare un veicolo di un''altra persona senza una dichiarazione scritta (se lo usi per più di 30 giorni) comporta una multa e l''aggiornamento della carta di circolazione, ma non la revoca della patente. È una questione burocratica, non di sicurezza alla guida.', 'La frase ''veicolo intestato ad altra persona senza avere apposita dichiarazione scritta'' descrive una violazione amministrativa, non legata alla capacità di guida, quindi non porta alla revoca.', 'Auto altrui senza dichiarazione = Multa (non revoca)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24617, 'VERO. La sospensione della patente è una punizione aggiuntiva (accessoria) che si applica quando si commettono infrazioni molto gravi al Codice della Strada, oltre alla multa principale.', 'La parola chiave è ''sanzione accessoria'', che significa una punizione che si aggiunge a quella principale (la multa).', 'Sospensione = Sanzione Accessoria per infrazioni gravi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24618, 'VERO. I neopatentati (chi ha la patente da poco tempo) hanno regole speciali e più severe. Se non le rispettano, ad esempio guidando veicoli troppo potenti o superando certi limiti di velocità, la patente viene sospesa.', 'Attenzione a ''neopatentato'' e ''limitazioni''. Per i nuovi guidatori le regole sono più rigide.', 'Neopatentato + infrazione grave = Sospensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24620, 'VERO. Superare i limiti di velocità di oltre 40 km/h è un''infrazione molto grave e comporta la sospensione della patente. È pericoloso per tutti!', 'Il numero ''oltre 40 km/h'' è fondamentale. Non basta superare di poco il limite.', 'Troppo veloce (>40 km/h) = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24621, 'VERO. La corsia di emergenza in autostrada è solo per vere emergenze. Usarla per altri motivi, come per superare il traffico, è molto pericoloso e vietato, quindi porta alla sospensione della patente.', 'Le parole ''corsia di emergenza'' e ''casi non previsti'' indicano un uso scorretto e grave.', 'Corsia emergenza (uso sbagliato) = Sospensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24622, 'VERO. Guidare sotto l''effetto di droghe è estremamente pericoloso e illegale. La patente viene sempre sospesa in questi casi, e ci sono anche altre gravi conseguenze legali.', 'La frase ''sostanze stupefacenti'' indica un comportamento molto grave e punito severamente.', 'Droga al volante = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24623, 'VERO. Guidare dopo aver bevuto troppo alcol (stato di ebbrezza) è una delle infrazioni più gravi e pericolose. La sospensione della patente è una conseguenza certa.', 'La frase ''stato di ebbrezza alcolica'' è il termine tecnico per indicare la guida in stato di alterazione per l''alcol.', 'Alcol al volante = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24624, 'VERO. Se un conducente si rifiuta di fare i test per controllare se ha bevuto alcol, è come se ammettesse di essere ubriaco. Per questo, la patente viene sospesa, proprio come se fosse stato trovato positivo all''alcol.', 'La parola ''rifiuta'' è la chiave. Non collaborare con le forze dell''ordine è un''infrazione grave.', 'Rifiuto test alcol = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24625, 'VERO. Fuggire dopo aver causato un incidente e non soccorrere una persona ferita è un reato gravissimo. La sospensione della patente è una delle conseguenze, oltre a quelle penali.', 'Le parole ''fugge'' e ''senza prestare soccorso'' indicano un comportamento inaccettabile e criminale.', 'Fuga dopo incidente = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24626, 'VERO. Se un veicolo è stato sequestrato, significa che non può circolare. Guidarlo lo stesso è una violazione diretta di un ordine legale e comporta la sospensione della patente.', 'Le parole ''circola abusivamente'' e ''veicolo sottoposto a sequestro'' sono importanti. Significa usare un veicolo che non dovrebbe essere in strada.', 'Veicolo sequestrato (uso) = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24627, 'VERO. Falsificare o alterare documenti importanti come quelli dell''assicurazione è un reato. Questo comportamento porta alla sospensione della patente, perché dimostra disonestà e mette a rischio la sicurezza stradale.', 'Le parole ''falsificato o contraffatto'' indicano un''azione illegale e fraudolenta.', 'Falso assicurazione = Patente sospesa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24628, 'FALSO. Se un conducente guida con la patente già sospesa, la punizione non è un''altra sospensione. È una violazione ancora più grave, che porta alla revoca della patente (la si perde del tutto) e a conseguenze penali.', 'La trappola è ''circola con patente sospesa''. La sanzione non è una ''sospensione'' ma una ''revoca'' o altre pene più severe.', 'Patente già sospesa + guida = REVOCA (non altra sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24629, 'FALSO. Se una persona perde in modo permanente (definitivo) i requisiti fisici per guidare (ad esempio, la vista), la patente non viene sospesa, ma revocata. La revoca significa che la patente viene tolta per sempre.', 'La parola ''definitivamente'' è la chiave. Se è per sempre, è revoca, non sospensione (che è temporanea).', 'Requisiti fisici persi *definitivamente* = REVOCA.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24630, 'FALSO. Se ci sono dubbi sui requisiti di una persona per guidare (ad esempio, per motivi di salute), l''autorità può chiedere una visita medica di controllo. Non si dispone subito la sospensione della patente, ma si verifica prima la situazione.', 'Le parole ''sorgono dubbi'' non implicano una sospensione immediata, ma un accertamento.', 'Dubbi sui requisiti = Visita medica (non sospensione diretta).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24631, 'FALSO. Quando si azzerano i punti della patente, non si ha una sospensione. Si deve fare un esame di revisione della patente: se lo si supera, si riottengono i punti, altrimenti la patente viene revocata.', 'La frase ''azzeramento dei punti'' porta alla ''revisione'' della patente, non alla sospensione.', 'Punti azzerati = REVISIONE (non sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24632, 'FALSO. Superare i limiti di velocità di 20 km/h (ma meno di 40 km/h) comporta una multa e la decurtazione di punti, ma non la sospensione della patente. La sospensione scatta solo per infrazioni più gravi (oltre 40 km/h).', 'Il numero ''20 km/h'' è la trappola. È una violazione, ma non così grave da sospendere la patente.', '>20 km/h = multa e punti (non sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24633, 'FALSO. Dimenticare la patente a casa non è una sospensione. Si riceve una multa e si deve presentare il documento entro un certo periodo. Non è una violazione grave che mette a rischio la sicurezza.', 'La frase ''senza avere con sè la patente'' si riferisce al dimenticarla, non al non averla mai avuta o al guidare senza patente valida.', 'Patente dimenticata = Multa (non sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24634, 'FALSO. Se la patente è illeggibile o rovinata, devi chiederne un duplicato. Non è una causa di sospensione, ma un problema amministrativo che va risolto per avere un documento valido.', 'Le parole ''illeggibile o deteriorata'' indicano un problema del documento, non una violazione grave della guida.', 'Patente rovinata = Richiedi duplicato (non sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24635, 'FALSO. Non avere il triangolo di pericolo (segnale mobile di pericolo) in auto è una violazione che comporta una multa, ma non la sospensione della patente. È un''infrazione minore rispetto a quelle che causano la sospensione.', 'La frase ''segnale mobile di pericolo'' si riferisce al triangolo. Non averlo è una multa, non una sospensione.', 'Triangolo assente = Multa (non sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24636, 'FALSO. Se una persona perde i requisiti morali (ad esempio, per gravi condanne penali), la patente viene revocata (tolta per sempre), non sospesa. La sospensione è temporanea, la revoca è definitiva.', 'Le parole ''requisiti morali'' sono importanti. La loro perdita porta alla revoca, non alla sospensione.', 'Requisiti morali persi = REVOCA.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24637, 'FALSO. Parcheggiare negli spazi riservati ai disabili senza averne diritto è una grave infrazione che comporta una multa salata e la decurtazione di punti, ma non la sospensione della patente.', 'La frase ''spazi destinati ai disabili'' indica un''infrazione grave ma non tale da sospendere la patente.', 'Sosta disabili (senza permesso) = Multa salata e punti (non sospensione).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24638, 'FALSO. Il bollo dell''auto è una tassa sulla proprietà del veicolo. Non pagarlo comporta sanzioni economiche e interessi, ma non ha nulla a che fare con la sospensione della patente, che riguarda le infrazioni al Codice della Strada.', 'La frase ''bollo dell''auto'' si riferisce a una tassa. Le tasse non pagate non causano la sospensione della patente.', 'Bollo non pagato = Sanzioni fiscali (non sospensione patente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24639, 'Quando ottieni la patente di guida, ti vengono assegnati 20 punti. Questo è il tuo ''saldo'' iniziale.', 'Ogni patente: significa che vale per tutti i tipi di patente.', 'Si parte sempre da 20 punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24640, 'Non tutte le multe tolgono punti, ma solo quelle che riguardano infrazioni più gravi o ''particolari'' al Codice della Strada.', 'particolari infrazioni: non ''qualunque'' infrazione, ma solo quelle specificate dalla legge.', 'Solo infrazioni gravi tolgono punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24641, 'Se perdi tutti i tuoi punti e arrivi a zero, devi rifare gli esami (teoria e pratica) per dimostrare di essere ancora idoneo a guidare. Questo si chiama ''revisione della patente''.', 'esaurito la sua dotazione di punti: significa che hai zero punti. revisione della stessa: non è un ritiro o una revoca, ma l''obbligo di rifare gli esami.', 'Zero punti = esame di revisione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24643, 'Se hai la patente da meno di tre anni (sei un neo-patentato) e commetti un''infrazione che toglie punti, te ne verranno tolti il doppio rispetto a un conducente esperto. È una regola per incentivare maggiore prudenza all''inizio.', 'primi tre anni: questo periodo è importante per i neo-patentati. doppio dei punti: non il triplo o un altro numero.', 'Neo-patentato = punti doppi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24644, 'Se fai più infrazioni contemporaneamente (ad esempio, non rispetti lo stop e superi il limite di velocità), ti verranno tolti i punti per ogni infrazione, ma il totale massimo che possono toglierti è 15 punti. Attenzione: se una di queste infrazioni è così grave da portare alla sospensione della patente, allora non c''è limite ai punti che possono essere tolti.', 'al massimo 15 punti: questo è il limite generale. salvo che si tratti di infrazioni che comportano la sospensione della patente: questa è l''eccezione importante, in questo caso il limite dei 15 punti non vale.', 'Max 15 punti, a meno di sospensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24645, 'Se hai perso dei punti e per due anni consecutivi non commetti nessuna infrazione che ne comporti la perdita, i tuoi punti torneranno automaticamente a 20.', 'due anni: questo è il periodo di ''buona condotta''. rientra in possesso di tutti i 20 punti: significa che torni al punteggio iniziale.', 'Due anni senza infrazioni = torni a 20.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24647, 'La patente di guida parte con 20 punti, non 30. I 30 punti sono il massimo che si può raggiungere con i bonus, ma non il punteggio iniziale.', '30 punti: questo è il numero sbagliato. Il numero corretto è 20.', 'Si parte da 20, non 30.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24648, 'Non tutte le infrazioni al Codice della Strada comportano la perdita di punti. Ad esempio, un divieto di sosta ti fa prendere una multa, ma non ti toglie punti dalla patente.', 'qualunque infrazione: questa parola è la trappola. Non è ''qualunque'', ma solo ''particolari'' infrazioni.', 'Non tutte le multe tolgono punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24649, 'I punti sulla patente diminuiscono anche per infrazioni meno gravi che non comportano la sospensione o il ritiro della patente. Ad esempio, superare di poco il limite di velocità toglie punti ma non sospende la patente.', 'esclusivamente: questa parola è la trappola. Non è ''solo'' in quei casi gravi, ma anche per altre infrazioni.', 'Punti persi anche per infrazioni minori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24650, 'Per i neo-patentati (nei primi tre anni), le violazioni che tolgono punti sono sanzionate con il doppio dei punti previsti, non il triplo.', 'triplo dei punti: questa è la parola sbagliata. Il numero corretto è ''doppio''.', 'Neo-patentato = doppio, non triplo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24651, 'Frequentando un corso specifico e superando un esame, si possono recuperare 6 punti, non 9. Inoltre, il massimo a cui si può arrivare è 20 punti (o 30 con i bonus, ma non tramite il corso).', '9 punti: il numero corretto è 6. arrivando al massimo a 30 punti: il massimo recuperabile con il corso è 6 punti, tornando al massimo a 20.', 'Corso = 6 punti recuperati, max 20.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24652, 'Se si commettono più infrazioni contemporaneamente, il massimo dei punti che possono essere tolti è 15, non 10. L''eccezione a questo limite è se le infrazioni comportano la sospensione della patente, non la revoca.', 'al massimo 10 punti: il numero corretto è 15. revoca della patente: l''eccezione riguarda la ''sospensione'', non la ''revoca''.', 'Max 15 punti, eccezione per sospensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24653, 'Se per due anni non commetti infrazioni che tolgono punti, il tuo punteggio torna a 20, non a 30. I 30 punti si possono raggiungere solo con i bonus di 2 punti ogni due anni di buona condotta, partendo da 20.', '30 punti: questo è il numero sbagliato. Si torna a 20 punti.', 'Due anni senza infrazioni = torni a 20.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24654, 'Quando si esauriscono tutti i punti (si arriva a zero), non viene revocata la patente, ma si deve fare la revisione della patente, cioè rifare gli esami.', 'revocata la patente: questa è la parola sbagliata. La conseguenza è la ''revisione'', non la ''revoca''.', 'Zero punti = revisione, non revoca.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24655, 'Superare il limite di velocità è pericoloso. Se superi il limite di oltre 10 km/h, è un''infrazione grave che ti fa perdere punti sulla patente, perché metti a rischio la sicurezza tua e degli altri.', 'La frase chiave è ''oltre 10 km/h''. Se superi il limite di meno di 10 km/h, ricevi solo una multa, ma non perdi punti. Il superamento ''significativo'' è quello che comporta la perdita di punti.', 'Velocità eccessiva = punti persi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24656, 'Il sorpasso è una manovra che richiede molta attenzione. Se non rispetti le regole (ad esempio, sorpassi dove è vietato o in modo pericoloso), metti a rischio te stesso e gli altri, e per questo si perdono punti sulla patente.', 'La parola ''alcune'' indica che non tutte le infrazioni sul sorpasso comportano la perdita di punti, ma solo quelle più gravi che compromettono la sicurezza.', 'Sorpasso sbagliato = punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24657, 'Usare il telefono cellulare senza auricolare o viva voce ti distrae molto dalla guida. È un comportamento molto pericoloso perché riduce la tua attenzione sulla strada, e per questo si perdono punti sulla patente.', 'La frase ''senza auricolare o viva voce'' è fondamentale. Se usi questi strumenti, puoi parlare al telefono senza perdere punti, perché le mani restano libere e la distrazione è minore.', 'Telefono in mano = punti in meno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24658, 'Il casco ti protegge la testa in caso di incidente. Se non lo usi quando è obbligatorio (ad esempio, su moto o scooter) o lo usi male (non allacciato), rischi la vita e perdi punti, perché è una grave mancanza di sicurezza.', 'Le espressioni ''quando previsto'' e ''mal allacciato'' sono importanti. ''Quando previsto'' si riferisce ai veicoli per cui il casco è obbligatorio. ''Mal allacciato'' significa che anche se lo indossi, non ti protegge correttamente.', 'Casco non sicuro = punti giù.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24659, 'Mantenere la distanza di sicurezza è fondamentale per avere il tempo di frenare ed evitare incidenti. Se non la rispetti e questo causa un incidente, è una grave responsabilità e perdi punti sulla patente.', 'La parte cruciale è ''da cui sia derivato un incidente''. Se non rispetti la distanza ma non succede nulla, di solito è solo una multa. Se c''è un incidente, la sanzione è più grave e include la perdita di punti.', 'Distanza zero, incidente = punti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24660, 'Le luci servono per vedere la strada ed essere visti dagli altri veicoli, specialmente di notte o in condizioni di scarsa visibilità. Non usarle o usarle male (ad esempio, abbaglianti dove non si deve) è pericoloso e comporta la perdita di punti.', 'Le parole ''mancato utilizzo'' e ''uso improprio'' coprono entrambe le situazioni in cui le luci non vengono usate correttamente, mettendo a rischio la sicurezza.', 'Luci sbagliate = punti tolti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24661, 'Trasportare troppe persone (sovrannumero) o troppo peso (sovraccarico) rende il veicolo meno stabile e più difficile da controllare. Questo aumenta il rischio di incidenti, e per questo si perdono punti sulla patente.', 'Le parole ''sovraccarico'' e ''sovrannumero'' indicano entrambe situazioni di pericolo dovute al superamento dei limiti di capacità del veicolo.', 'Troppo peso/persone = punti meno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24662, 'Se la tua patente indica che devi guidare con gli occhiali o le lenti a contatto, significa che ne hai bisogno per vedere bene la strada. Non usarle è pericoloso perché riduce la tua capacità visiva e ti fa perdere punti.', 'La frase ''se prescritte'' è essenziale. L''obbligo vale solo se è specificato sulla tua patente di guida.', 'Occhiali obbligatori = punti persi se non li usi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24663, 'La corsia di emergenza in autostrada è riservata solo a situazioni di vera emergenza (ad esempio, un guasto al veicolo o un malore). Usarla per superare o per evitare il traffico è molto pericoloso e vietato, e perdi punti sulla patente.', 'La frase ''al di fuori dei casi previsti'' è la chiave. Indica che l''uso improprio di questa corsia è sanzionato con la perdita di punti.', 'Emergenza solo per emergenza = punti salvi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24664, 'Guidare sotto l''effetto di sostanze stupefacenti è estremamente pericoloso, perché altera gravemente la tua capacità di guidare e reagire. È una delle infrazioni più gravi e comporta una pesante perdita di punti sulla patente, oltre ad altre sanzioni penali.', 'L''espressione ''sostanze stupefacenti'' sottolinea la gravità dell''infrazione, che è considerata un reato.', 'Droghe al volante = punti azzerati (o quasi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24665, 'Gareggiare in velocità su piste private non è un''infrazione del Codice della Strada, perché non sei su una strada aperta al pubblico. Le regole del Codice della Strada e la perdita di punti si applicano solo sulle strade pubbliche.', 'La parola ''private'' è la trappola. Se la gara fosse su strada pubblica, sarebbe una gravissima infrazione con perdita di punti e altre sanzioni.', 'Pista privata = no Codice della Strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24666, 'Parcheggiare davanti a un passo carrabile è vietato e ti fa prendere una multa, ma non comporta la perdita di punti sulla patente. È un''infrazione amministrativa, meno grave rispetto a quelle che mettono a rischio diretto la sicurezza della circolazione.', 'Il termine ''sosta'' indica un''infrazione legata al parcheggio. Le infrazioni di sosta, anche se vietate, raramente comportano la perdita di punti.', 'Sosta sbagliata = multa, non punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24668, 'Devi sempre avere con te i documenti del veicolo quando guidi. Se non hai la carta di circolazione, prendi una multa e devi portarla in un secondo momento, ma non perdi punti sulla patente. L''importante è che il documento esista e sia valido.', 'La frase ''senza avere con sé'' indica che il documento esiste ma è stato dimenticato. Se il documento non fosse valido o non esistesse, le conseguenze sarebbero più gravi.', 'Documenti dimenticati = multa, non punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24669, 'Il certificato di proprietà non è un documento che devi portare con te quando guidi. Serve per dimostrare chi è il proprietario del veicolo, ma non è richiesto per la circolazione su strada.', 'La frase ''certificato di proprietà'' è la chiave. Questo documento non è obbligatorio averlo a bordo del veicolo.', 'Certificato di proprietà = non serve a bordo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24670, 'Puoi guidare un veicolo che non è tuo senza chiedere il permesso alla Motorizzazione Civile, purché tu abbia una patente valida per quel tipo di veicolo e il proprietario te lo abbia permesso. Non si perdono punti per questo.', 'La frase ''senza autorizzazione della Motorizzazione Civile'' è la trappola. Non è richiesta alcuna autorizzazione speciale per guidare un veicolo altrui, a meno di casi particolari di uso prolungato da parte di non proprietari.', 'Auto altrui = ok con patente giusta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24671, 'La perdita di punti sulla patente raddoppia solo per i neopatentati (nei primi tre anni dal conseguimento della patente B, A1, A2 o A). Non dipende dalla potenza del motociclo che stai guidando.', 'La frase ''motociclo di potenza superiore a 35 kW'' è un dettaglio irrilevante per il raddoppio dei punti. La regola del raddoppio è legata all''essere neopatentato, non al tipo di veicolo.', 'Punti raddoppiati = solo neopatentati.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24672, 'Anche in questo caso, la potenza dell''autovettura non c''entra con il raddoppio dei punti. I punti raddoppiano solo per i neopatentati nei primi tre anni dal conseguimento della patente.', 'La frase ''autovettura di potenza superiore a 115 kW'' è un dettaglio che non influisce sul raddoppio dei punti. La regola è legata all''essere neopatentato.', 'Punti raddoppiati = solo neopatentati.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24673, 'Un''autovettura con 8 posti più il conducente (quindi 9 in totale) si può guidare con la patente B. Se hai la patente C, puoi guidare anche veicoli più grandi, quindi puoi guidare tranquillamente anche un''autovettura. Non perdi punti per questo.', 'La frase ''patente di categoria C'' è la chiave. Avere una patente di categoria superiore ti permette di guidare anche i veicoli delle categorie inferiori (se non ci sono limitazioni specifiche), quindi non è un''infrazione.', 'Patente superiore = puoi guidare anche inferiore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24674, 'I neopatentati hanno delle limitazioni (ad esempio, di velocità o di potenza del veicolo), ma non c''è un divieto di circolare in autostrada o su strade extraurbane principali nei primi sei mesi. Non si perdono punti per questo tipo di circolazione.', 'La frase ''meno di sei mesi'' è la trappola. Non esiste una limitazione specifica per l''accesso a queste strade in base a questo periodo. Le limitazioni per i neopatentati sono altre (velocità massima, potenza del veicolo).', 'Neopatentato in autostrada = ok (con limiti).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24675, 'I divieti di circolazione nei giorni festivi riguardano gli autocarri con massa complessiva superiore a 7,5 tonnellate (o altre categorie specifiche). Un autocarro sotto le 3,5 tonnellate non ha questi divieti. Anche se ci fosse un divieto, la sanzione sarebbe una multa, non la perdita di punti.', 'La frase ''inferiore a 3,5 tonnellate'' è la chiave. I divieti di circolazione per i festivi riguardano veicoli più pesanti. Inoltre, le violazioni dei divieti di circolazione raramente comportano la perdita di punti.', 'Autocarro leggero = no divieto festivo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24676, 'La revisione è obbligatoria per garantire che il veicolo sia sicuro e in buone condizioni. Se non l''hai fatta, prendi una multa e il veicolo non può circolare finché non viene revisionato, ma non perdi punti sulla patente.', 'La frase ''non sia stato sottoposto alla prescritta revisione'' indica una violazione amministrativa legata allo stato del veicolo, non alla condotta di guida, e per questo non comporta la perdita di punti.', 'Revisione scaduta = multa, non punti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24677, 'Per rinnovare la patente, devi dimostrare di essere ancora in buona salute, sia fisicamente che mentalmente. È una condizione fondamentale per guidare in sicurezza.', 'Le parole ''requisiti fisici e psichici prescritti'' indicano le condizioni di salute necessarie stabilite dalla legge.', 'Rinnovo = Salute ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24678, 'La patente viene rinnovata solo dopo aver superato una visita medica specifica, fatta da un dottore che è autorizzato a fare questi controlli. Se la visita va bene (''esito favorevole''), la patente è confermata.', 'Attenzione a ''medico autorizzato'': non un medico qualsiasi, ma uno specifico per le patenti. ''Esito favorevole'' significa che la visita deve avere un risultato positivo.', 'Rinnovo = Visita medica ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24679, 'Il Ministero delle Infrastrutture e dei Trasporti è l''ente che gestisce il rinnovo, ma la parte pratica della visita la fa un medico autorizzato. L''importante è che il medico confermi la tua ''idoneità psicofisica'', cioè che sei adatto a guidare.', 'Il ''Ministero delle infrastrutture e dei trasporti'' è l''organo di riferimento, ma l''azione pratica è del ''medico autorizzato''. ''Idoneità psicofisica'' significa essere adatti fisicamente e mentalmente.', 'Ministero + Medico = Patente rinnovata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24680, 'Se hai meno di 50 anni, la tua patente di categoria B dura 10 anni. Ci sono delle piccole eccezioni, ad esempio se hai problemi di salute o se la scadenza viene allineata al tuo compleanno.', 'Le frasi ''salvo diversa limitazione'' e ''salvo allineamento alla data del compleanno'' indicano le eccezioni. I numeri chiave sono ''dieci anni'' e ''non ha superato i 50 anni''.', 'B < 50 anni = 10 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24681, 'Se hai tra i 50 e i 70 anni, la tua patente di categoria B dura 5 anni. Anche in questo caso, ci sono le solite piccole eccezioni.', 'I numeri chiave sono ''cinque anni'' e ''fra i 50 e i 70 anni''.', 'B 50-70 anni = 5 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24682, 'Se hai tra i 70 e gli 80 anni, la tua patente di categoria B dura 3 anni. Le eccezioni sono sempre le stesse.', 'I numeri chiave sono ''tre anni'' e ''fra i 70 e gli 80 anni''.', 'B 70-80 anni = 3 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24683, 'Se hai più di 80 anni, la tua patente di categoria B dura 2 anni. Le eccezioni sono sempre le stesse.', 'I numeri chiave sono ''due anni'' e ''superato gli 80 anni''.', 'B > 80 anni = 2 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24684, 'La patente di categoria BE (che serve per guidare veicoli con rimorchi pesanti) segue le stesse regole di validità della patente B. Quindi, se hai meno di 50 anni, dura 10 anni.', 'La ''categoria BE'' ha le stesse regole di validità per età della categoria B. I numeri chiave sono ''dieci anni'' e ''non ha superato i 50 anni''.', 'BE = B per validità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24685, 'Anche la patente di categoria A (per le moto) segue le stesse regole di validità della patente B. Quindi, se hai meno di 50 anni, dura 10 anni.', 'La ''categoria A'' ha le stesse regole di validità per età della categoria B. I numeri chiave sono ''dieci anni'' e ''non ha superato i 50 anni''.', 'A = B per validità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24686, 'La patente di categoria B SPECIALE (BS), che è per persone con disabilità, ha regole di validità leggermente diverse. Dura 5 anni se non hai superato i 70 anni di età.', 'Attenzione a ''B SPECIALE (BS)'': è diversa dalla patente B normale. I numeri chiave sono ''cinque anni'' e ''non ha superato i 70 anni''.', 'BS < 70 anni = 5 anni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24687, 'La patente si rinnova con una visita medica che controlla la tua salute fisica e mentale, non con il Prefetto. E non si controllano i ''requisiti morali'', cioè se sei una brava persona, ma solo la tua idoneità a guidare.', 'Le parole ''Prefetto'' e ''requisiti morali'' sono le trappole. Il rinnovo è compito del medico e riguarda i requisiti fisici e psichici.', 'Rinnovo = Medico, non Prefetto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24688, 'Se la patente è scaduta, non puoi guidare nemmeno per un giorno. È come se non l''avessi e potresti ricevere una multa salata.', 'La frase ''tre giorni'' è una trappola comune. Non esiste nessun periodo di tolleranza per la patente scaduta.', 'Scaduta = Stop subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24689, 'Per rinnovare la patente non devi rifare l''esame di guida. Devi solo fare la visita medica. L''esame di guida si fa solo la prima volta per ottenere la patente.', 'La frase ''prova tecnica di guida (esame di guida) periodica'' è la trappola. Non c''è un esame di guida periodico per il rinnovo.', 'Rinnovo = Medico, non esame.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24690, 'Se hai più patenti (ad esempio, la A per la moto e la B per l''auto), ti basta fare una sola visita medica. Questa visita sarà valida per tutte le patenti che possiedi.', 'La frase ''due specifiche visite mediche, ognuna abilitante alla singola categoria'' è la trappola. Una sola visita è sufficiente per tutte le patenti.', 'Una visita per tutte le patenti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24691, 'Questa affermazione è falsa. Abbiamo imparato che per chi ha tra i 50 e i 70 anni, la patente di categoria B dura 5 anni, non 8.', 'Il numero ''otto anni'' è la trappola. La validità corretta è di 5 anni.', 'B 50-70 anni = 5 anni (non 8).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24692, 'Questa affermazione è falsa. La patente di categoria BE segue le stesse regole della B. Per chi non ha superato i 50 anni, dura 10 anni, non 5.', 'Il numero ''cinque anni'' è la trappola. La validità corretta è di 10 anni.', 'BE < 50 anni = 10 anni (non 5).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24693, 'Questa affermazione è falsa. La patente di categoria B può essere rinnovata anche dopo gli 80 anni, ma la validità è di 2 anni e la visita medica è più frequente. Non c''è un limite di età massimo per il rinnovo.', 'La frase ''non può essere rinnovata'' è la trappola. Si può rinnovare, ma con validità ridotta e controlli più frequenti.', 'Si rinnova anche dopo gli 80.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24694, 'Questa affermazione è falsa. Per chi non ha superato i 50 anni, la patente di categoria B dura 10 anni, non 5.', 'Il numero ''cinque anni'' è la trappola. La validità corretta è di 10 anni.', 'B < 50 anni = 10 anni (non 5).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24695, 'Questa affermazione è falsa. La validità della patente di categoria B cambia in base all''età del titolare (10, 5, 3 o 2 anni). Non vale sempre 10 anni ''in ogni caso''.', 'La frase ''in ogni caso'' è la trappola. La validità dipende dall''età.', 'Validità B = dipende dall''età.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24696, 'Questa affermazione è falsa. La patente di categoria B ha sempre una scadenza, anche prima dei 50 anni. Dura 10 anni fino ai 50 anni, poi la validità cambia. Non è ''senza scadenza''.', 'La frase ''non ha scadenza di validità'' è la trappola. Ha una scadenza di 10 anni fino ai 50 anni.', 'Patente = Sempre una scadenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24697, 'Una strada stretta rende difficile il passaggio dei veicoli, specialmente quando si incrociano, aumentando il rischio di collisioni. Per questo, la ristrettezza della strada è una causa probabile di incidenti.', 'La parola ''ristrettezza'' indica che la strada è poco larga, quindi non c''è molto spazio per i veicoli.', 'Strada stretta = più pericoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24698, 'Se un incrocio non è segnalato, i conducenti non sanno che devono fare attenzione e possono scontrarsi. La mancanza di segnalazione è un difetto della strada che causa incidenti.', 'La frase ''mancata segnalazione'' significa che i segnali (cartelli) che avvisano dell''incrocio non ci sono.', 'Incrocio senza segnali = pericolo nascosto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24699, 'La segnaletica orizzontale (le linee e i simboli disegnati sull''asfalto) serve a guidare i veicoli e a separare le corsie. Se manca, c''è confusione e aumenta il rischio di incidenti.', 'La ''mancanza'' significa che non c''è. La ''segnaletica orizzontale'' sono le strisce bianche o gialle sulla strada.', 'Linee sull''asfalto mancano = caos.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24700, 'Un fondo stradale deformato, con buche o avvallamenti, può far perdere il controllo del veicolo, specialmente se si va veloci o in curva. Questo è un difetto della strada che può causare incidenti.', 'La parola ''deformato'' significa che la strada non è liscia, ma ha buche o dislivelli.', 'Strada rovinata = guida instabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24701, 'Un fondo stradale scivoloso (per pioggia, ghiaccio, olio) riduce l''aderenza delle gomme. Questo rende difficile frenare o curvare e può causare incidenti.', 'La parola ''scivoloso'' indica che la superficie della strada non offre una buona presa alle gomme.', 'Strada scivolosa = meno controllo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24702, 'Una strettoia è un punto dove la strada si restringe. Se non è segnalata, i conducenti non si preparano e possono scontrarsi. È un pericolo dovuto alla struttura della strada.', 'Le ''strettoie'' sono punti dove la strada diventa più stretta. ''Non segnalate'' significa che non ci sono cartelli per avvisare.', 'Strettoia a sorpresa = pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24703, 'Una strada divisa in carreggiate separate (ad esempio, con uno spartitraffico) è più sicura. I veicoli che vanno in direzioni opposte non si incontrano direttamente, riducendo il rischio di incidenti frontali. Quindi, non è una causa di incidenti, ma un elemento di sicurezza.', 'La frase ''suddivisa in carreggiate'' significa che ci sono due strade separate per i due sensi di marcia. Questo è un vantaggio per la sicurezza.', 'Carreggiate separate = più sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24704, 'Avere più corsie nella stessa direzione aiuta il traffico a scorrere meglio e permette sorpassi più sicuri. Non è una causa di incidenti, ma una soluzione per migliorare la circolazione e la sicurezza.', 'La frase ''suddivisa in corsie'' significa che ci sono più spazi per i veicoli nella stessa direzione. Questo è un elemento positivo.', 'Più corsie = traffico più fluido.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24705, 'Una carreggiata a senso unico significa che tutti i veicoli vanno nella stessa direzione. Questo elimina il rischio di scontri frontali e rende la circolazione più semplice e sicura. Non è una causa di incidenti.', 'La frase ''senso unico di circolazione'' indica che tutti i veicoli si muovono nella stessa direzione. Questo aumenta la sicurezza.', 'Senso unico = niente frontali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24706, 'Una strada pianeggiante è più facile da percorrere rispetto a una in salita o in discesa, dove bisogna fare più attenzione. Quindi, una strada piatta non è una causa di incidenti, ma una condizione più sicura.', 'La parola ''pianeggiante'' significa che la strada è piatta, senza salite o discese ripide. Questo è un vantaggio per la guida.', 'Strada piatta = guida più facile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24707, 'I guardrail sono installati proprio per aumentare la sicurezza. Servono a contenere i veicoli in caso di uscita di strada, evitando cadute o impatti più gravi. Sono una protezione, non una causa di incidenti.', 'Le ''barriere laterali ad assorbimento d''urto (guardrails)'' sono le protezioni ai lati della strada. Sono lì per proteggere, non per causare incidenti.', 'Guardrail = protezione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24708, 'La regolamentazione semaforica (i semafori) serve a gestire il traffico agli incroci, indicando chi deve passare e chi deve fermarsi. Questo riduce il rischio di collisioni, non lo aumenta. Quindi, non è una causa di incidenti.', 'La ''regolamentazione semaforica'' significa che ci sono i semafori. I semafori servono a organizzare il traffico e prevenire incidenti.', 'Semaforo = ordine, non caos.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24709, 'La ''mancanza di curve pericolose'' significa che la strada non ha curve difficili o rischiose. Questo è un bene, perché le curve pericolose sono una causa di incidenti. Quindi, la loro assenza rende la strada più sicura, non più pericolosa.', 'La frase ''mancanza di curve pericolose'' è una doppia negazione. Significa che NON ci sono curve pericolose. Questo è un fattore positivo per la sicurezza.', 'Niente curve pericolose = strada più sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24710, 'Quando piove, la strada diventa scivolosa e l''aderenza degli pneumatici diminuisce. Ridurre la velocità ti permette di avere più controllo sul veicolo e di reagire meglio a eventuali imprevisti, riducendo il rischio di aquaplaning e migliorando la capacità di frenata.', 'La parola ''occorre'' significa ''è necessario'' o ''bisogna''. Indica un''azione obbligatoria per la sicurezza.', 'Pioggia = meno aderenza = meno velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24711, 'I tergicristalli sono essenziali per mantenere il parabrezza pulito dalla pioggia e garantire una buona visibilità. Senza di essi, la tua capacità di vedere la strada e gli altri veicoli sarebbe gravemente compromessa, rendendo la guida estremamente pericolosa.', 'L''espressione ''tenere in funzione'' significa ''far funzionare'' o ''lasciare accesi''.', 'Pioggia = tergicristalli accesi per vedere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24712, 'Su strada bagnata, lo spazio necessario per frenare aumenta notevolmente perché l''attrito tra pneumatici e asfalto è minore. Aumentare la distanza di sicurezza ti dà più tempo e spazio per reagire e frenare senza tamponare il veicolo che ti precede.', 'L''espressione ''aumentare la distanza di sicurezza'' significa lasciare più spazio tra la tua auto e quella davanti.', 'Pioggia = più spazio per frenare = più distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24713, 'L''umidità e la differenza di temperatura tra l''interno e l''esterno dell''auto possono causare l''appannamento dei vetri, riducendo drasticamente la visibilità. È importante usare il sistema di ventilazione, l''aria condizionata o il disappannatore per mantenere i vetri puliti e chiari.', 'L''espressione ''evitare l''appannamento'' significa ''fare in modo che i vetri non si sporchino di condensa''.', 'Pioggia = vetri chiari per vedere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24714, 'Su una superficie bagnata, manovre brusche dello sterzo possono facilmente far perdere aderenza alle ruote e causare una sbandata o la perdita di controllo del veicolo. È fondamentale guidare con movimenti dolci e graduali per mantenere la stabilità.', 'L''espressione ''manovrare con prudenza'' significa ''guidare con attenzione, senza movimenti improvvisi o bruschi''.', 'Pioggia = sterzo dolce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24715, 'Passare velocemente sulle pozzanghere è molto pericoloso. Potresti perdere il controllo del veicolo a causa dell''aquaplaning (le ruote ''galleggiano'' sull''acqua), schizzare acqua sui pedoni o su altri veicoli, o non vedere buche nascoste. È sempre meglio rallentare e attraversarle con cautela.', 'La parola ''velocemente'' è la trappola. L''espressione ''rimanere impantanati'' significa ''bloccati nel fango o nell''acqua'', ma non è il rischio principale delle pozzanghere in velocità.', 'Pozzanghere = rallenta, non accelerare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24716, 'Coprire il radiatore con una mascherina è una pratica che si adotta in condizioni di freddo estremo, per aiutare il motore a raggiungere più velocemente la temperatura di esercizio e mantenerla. Non ha alcuna utilità in caso di pioggia e potrebbe addirittura ostacolare il normale raffreddamento del motore.', 'L''azione di ''coprire il radiatore'' è specifica per il freddo intenso, non per la pioggia. La ''mascherina'' è un accessorio per l''inverno.', 'Radiatore coperto = solo con freddo estremo, non con pioggia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24717, 'Frenare energicamente (cioè con molta forza e all''improvviso) su strada bagnata è estremamente pericoloso. Le ruote potrebbero bloccarsi facilmente, facendoti perdere il controllo del veicolo e causando una sbandata. Bisogna frenare dolcemente e gradualmente, anticipando la frenata.', 'La parola ''energicamente'' è la trappola. Significa ''con molta forza'' o ''bruscamente''.', 'Pioggia = frenata dolce, mai energica.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24718, 'La segnalazione luminosa di pericolo (le ''quattro frecce'') deve essere usata solo in caso di pericolo immediato, come un guasto al veicolo, un rallentamento improvviso e inaspettato, o un veicolo fermo che crea intralcio. Non deve essere usata durante la normale marcia sotto la pioggia, perché potrebbe confondere gli altri conducenti sulla tua intenzione di svoltare o sulla presenza di un pericolo reale.', 'L''espressione ''durante la marcia'' significa ''mentre si guida''. Le ''quattro frecce'' sono la ''segnalazione luminosa di pericolo''.', 'Quattro frecce = solo per pericolo o fermo, non per pioggia normale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24719, 'Procedere con il pedale della frizione abbassato (cioè premuto) significa che il motore è scollegato dalle ruote (''in folle'' o ''a ruota libera''). In questa condizione, non hai il controllo del motore e non puoi usare il freno motore, il che è molto pericoloso, specialmente su strada bagnata dove hai bisogno del massimo controllo sul veicolo.', 'L''espressione ''di norma'' significa ''solitamente'', ''normalmente''. ''Pedale della frizione abbassato'' significa ''frizione premuta''.', 'Frizione abbassata = mai in marcia, specialmente con pioggia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24720, 'L''aquaplaning è proprio questo: le ruote non toccano più l''asfalto ma scivolano su uno strato d''acqua che si forma tra il pneumatico e la strada. Questo fa perdere il controllo del veicolo.', 'La frase ''fa scivolare le ruote sullo strato di acqua'' descrive esattamente il fenomeno. Non ci sono vere e proprie parole trappola, è una definizione diretta.', 'Aquaplaning = scivolare sull''acqua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24721, 'Se il pneumatico è consumato, il suo battistrada (il disegno sulla gomma) è meno profondo. Questo significa che non riesce a espellere bene l''acqua. Perciò, il cuscino d''acqua si forma più facilmente e a velocità più basse, causando l''aquaplaning prima.', 'La parola chiave è ''consumato''. Un pneumatico consumato è meno efficace. ''Più bassa'' è importante perché indica che il rischio aumenta anche a velocità moderate.', 'Gomme lisce = aquaplaning facile e precoce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24722, 'I veicoli più leggeri hanno meno peso che ''spinge'' le ruote sull''asfalto. Questo rende più facile per lo strato d''acqua sollevare il veicolo e far perdere il contatto tra pneumatici e strada, causando l''aquaplaning.', 'La frase ''più facilmente nei veicoli più leggeri'' è cruciale. Meno peso significa meno pressione sull''asfalto e quindi più facilità a ''galleggiare'' sull''acqua.', 'Veicolo leggero = galleggia prima sull''acqua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24723, 'L''aquaplaning si verifica più facilmente ad ALTA velocità, non a bassa. Quando si va veloci, l''acqua non ha il tempo di essere espulsa dal battistrada e si crea il cuscino d''acqua. A bassa velocità, di solito, le gomme riescono a ''tagliare'' l''acqua.', 'La parola trappola è ''bassa velocità''. È il contrario: l''aquaplaning è un rischio maggiore ad alta velocità.', 'Aquaplaning = alta velocità + acqua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24724, 'L''aquaplaning fa perdere il contatto delle ruote con la strada, quindi il veicolo non risponde più ai comandi (sterzo, freno). Questo causa proprio lo sbandamento e la perdita di controllo, non lo riduce.', 'La parola ''riduce'' è la trappola. L''aquaplaning non riduce, ma AUMENTA il rischio di sbandamento.', 'Aquaplaning = perdita di controllo = sbandamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24725, 'Le carreggiate con forte pendenza laterale (chiamata anche ''bombatura'') sono fatte apposta per far scorrere via l''acqua ai lati. Questo impedisce all''acqua di accumularsi e quindi RIDUCE, non aumenta, il rischio di aquaplaning.', 'La parola ''aumenta'' è la trappola. La pendenza laterale serve proprio a drenare l''acqua e quindi a diminuire il rischio.', 'Pendenza laterale = acqua via = meno aquaplaning.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24726, 'L''aquaplaning crea uno strato d''acqua tra il pneumatico e la strada, eliminando il contatto diretto. Questo significa che l''aderenza (la ''presa'' della gomma sulla strada) viene drasticamente RIDOTTA, non aumentata.', 'La parola ''aumenta'' è la trappola. L''aquaplaning è la perdita di aderenza, quindi la diminuisce.', 'Aquaplaning = zero aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24727, 'L''aquaplaning forma un cuscino d''acqua che separa il pneumatico dall''asfalto. Questo non rafforza il contatto, ma lo interrompe o lo riduce moltissimo, facendo perdere il controllo del veicolo.', 'La parola ''rafforza'' è la trappola. L''aquaplaning fa esattamente il contrario: indebolisce o elimina il contatto.', 'Aquaplaning = contatto interrotto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24728, 'Lo spessore e il disegno del battistrada sono FONDAMENTALI per prevenire l''aquaplaning! Servono proprio a espellere l''acqua. Se il battistrada è consumato o non adatto, l''aquaplaning si verifica molto più facilmente. Quindi, dipende eccome!', 'La frase ''non dipende'' è la trappola. Il battistrada è uno dei fattori più importanti per l''aquaplaning.', 'Battistrada = chiave anti-aquaplaning.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24729, 'Per guidare in sicurezza sulla neve, è fondamentale avere una buona aderenza. Questo si ottiene montando pneumatici specifici per la neve su tutte le ruote, oppure, in alternativa, usando le catene da neve, che vanno messe sulle ruote che danno la spinta al veicolo (le ruote motrici).', 'La parola chiave è ''oppure'', che indica che entrambe le soluzioni sono valide e alternative tra loro, non è necessario fare entrambe le cose contemporaneamente.', 'Neve = gomme invernali O catene.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24730, 'Sulla neve, l''aderenza delle gomme è molto ridotta. Moderare la velocità significa andare più piano del solito. Questo ti dà più tempo per reagire a imprevisti e riduce il rischio di perdere il controllo del veicolo.', '''Moderare la velocità'' significa ridurre l''andatura, andare più lentamente. Non significa fermarsi, ma adattare la velocità alle condizioni difficili.', 'Neve = velocità ridotta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24731, 'Quando la strada è coperta di neve, lo spazio necessario per frenare aumenta molto. Aumentare la distanza di sicurezza dal veicolo che ti precede ti dà più spazio e tempo per fermarti senza tamponare, in caso di frenata improvvisa.', '''Aumentare'' significa rendere più grande, più lunga. Quindi, lasciare più spazio tra la tua auto e quella davanti.', 'Neve = più spazio tra le auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24732, 'Sulla neve, ogni movimento improvviso del volante o cambio di direzione (manovre brusche) può far perdere aderenza alle ruote e causare uno sbandamento. È importante guidare con movimenti dolci e graduali.', '''Evitare brusche manovre'' significa non fare movimenti improvvisi e veloci con il volante o con i pedali. La parola ''brusche'' è la chiave.', 'Neve = movimenti dolci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24733, 'Accelerare troppo velocemente sulla neve fa sì che le ruote motrici girino a vuoto (slittino) e l''auto può perdere il controllo o non riuscire a partire. È meglio accelerare molto dolcemente e gradualmente.', '''Evitare brusche accelerazioni'' significa non premere il pedale dell''acceleratore con forza e all''improvviso. ''Brusche'' è la parola da notare.', 'Neve = accelerare piano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24734, 'Frenare con ''maggiore energia'' significa frenare forte. Sulla neve, una frenata forte blocca le ruote e fa sbandare il veicolo, rendendolo incontrollabile. Bisogna frenare dolcemente, a piccoli colpetti (se non si ha l''ABS) o con una pressione leggera e costante (se si ha l''ABS).', 'La trappola è ''maggiore energia'', che significa ''più forte''. Sulla neve, frenare forte è sempre sbagliato.', 'Neve = frenare piano, mai forte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24735, 'Alla partenza, accelerare al massimo sulla neve fa slittare le ruote e l''auto non si muove o sbanda. Per partire sulla neve, è consigliabile usare una marcia alta (come la seconda) e accelerare con estrema delicatezza.', 'La frase ''accelerare al massimo'' è la trappola. Significa dare tutto il gas, cosa assolutamente da evitare sulla neve.', 'Neve = partenza dolce, non a tavoletta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24736, 'Sterzare bruscamente (cioè girare il volante di colpo) sulla neve è molto pericoloso. L''auto perde aderenza e sbanda, rendendo impossibile evitare l''ostacolo. È sempre meglio cercare di frenare dolcemente e, se proprio necessario, fare movimenti minimi e graduali con il volante.', 'La trappola è ''sterzare bruscamente''. Sulla neve, ogni movimento improvviso del volante è rischioso.', 'Neve = mai sterzare di colpo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24737, 'Se il veicolo sbanda sulla neve, frenare a fondo peggiora la situazione. Le ruote si bloccano e si perde completamente il controllo. La cosa giusta da fare è togliere il piede dall''acceleratore, tenere il volante dritto o girarlo leggermente nella direzione dello sbandamento e frenare solo molto dolcemente, se indispensabile.', 'La trappola è ''frenare a fondo''. In caso di sbandamento sulla neve, frenare forte è la cosa peggiore da fare.', 'Sbandamento sulla neve = mai frenare a fondo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24738, 'Quando la strada è ghiacciata, l''auto scivola molto facilmente. Andare piano (velocità moderata) ti aiuta a mantenere il controllo del veicolo e a fermarti in sicurezza, riducendo il rischio di sbandare.', 'La parola ''opportuno'' significa ''è giusto fare'' o ''è consigliabile''. Non è un obbligo assoluto, ma la scelta migliore per la sicurezza.', 'Ghiaccio = velocità moderata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24739, 'Sul ghiaccio, l''auto ha bisogno di molto più spazio per frenare. Aumentare la distanza dagli altri veicoli ti dà più tempo per reagire a imprevisti e più spazio per fermarti senza causare incidenti.', '''Aumentare la distanza di sicurezza'' significa lasciare più spazio tra la tua auto e quella che ti precede. È una misura preventiva fondamentale.', 'Ghiaccio = più distanza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24740, 'Quando incroci un altro veicolo su strada ghiacciata, è saggio lasciare più spazio laterale tra voi. Sia tu che l''altro veicolo potreste perdere aderenza e sbandare, quindi è più sicuro stare lontani l''uno dall''altro.', '''Distanziarsi dalla traiettoria'' significa allontanarsi dal percorso che l''altro veicolo potrebbe fare, per avere un margine di sicurezza maggiore.', 'Ghiaccio + incrocio = spazio laterale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24741, 'In discesa, le marce basse (come la prima o la seconda) permettono al motore di ''frenare'' l''auto (freno motore). Questo ti aiuta a controllare la velocità senza dover usare troppo i freni, che sul ghiaccio potrebbero farti sbandare.', '''Marce basse'' si riferisce alla prima o alla seconda marcia. Il ''freno motore'' è l''effetto frenante che il motore produce quando si rilascia l''acceleratore con una marcia inserita.', 'Ghiaccio + discesa = marcia bassa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24742, 'Accelerare troppo velocemente sul ghiaccio fa perdere aderenza alle ruote, facendole slittare. Questo ti fa perdere il controllo dell''auto. È sempre meglio accelerare dolcemente e gradualmente.', '''Brusche accelerazioni'' significa accelerare di colpo, in modo improvviso e forte. Questo è molto pericoloso sul ghiaccio.', 'Ghiaccio = accelerare dolcemente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24743, 'Le zone in ombra (ad esempio sotto i ponti o vicino a muri alti) ricevono meno sole. Per questo, il ghiaccio si scioglie più lentamente o non si scioglie affatto, rimanendo più a lungo e rendendo la strada più pericolosa in quei punti.', '''Zone in ombra'' sono le aree dove non batte il sole. ''Transito'' significa il passaggio o l''attraversamento.', 'Ombra = ghiaccio nascosto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24744, 'La doppia trazione (o 4x4) fa sì che tutte e quattro le ruote ricevano potenza dal motore. Questo aumenta l''aderenza e il controllo dell''auto su superfici scivolose come il ghiaccio, rendendo la guida più sicura.', '''Doppia trazione'' (o 4x4) significa che tutte le ruote del veicolo spingono. ''Innestare'' significa attivare questa funzione.', 'Ghiaccio + 4x4 = più aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24745, 'Marciare molto vicino alla barriera laterale è pericoloso. Se l''auto sbanda sul ghiaccio, potresti sbattere contro la barriera. È sempre meglio mantenere una posizione centrale e sicura sulla carreggiata, lontano dagli ostacoli.', 'La frase ''molto vicino'' è la parola trappola. Sul ghiaccio, è fondamentale mantenere una distanza di sicurezza da tutto, anche dalle barriere laterali.', 'Ghiaccio = stare al centro, lontano dagli ostacoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24746, 'Questa affermazione è falsa. Le catene da neve sono un dispositivo molto efficace e spesso obbligatorio sul ghiaccio e sulla neve. Le gomme chiodate, invece, sono vietate in Italia, tranne in casi molto specifici e con regole precise, e non sono un''alternativa generale alle catene.', 'Le parole ''non usare le catene'' e ''gomme chiodate'' sono le trappole. Le catene sono utili, le gomme chiodate sono vietate in Italia.', 'Ghiaccio = catene sì, chiodate no (in Italia).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24747, 'Frenare energicamente (cioè forte e di colpo) sul ghiaccio è estremamente pericoloso perché fa perdere il controllo dell''auto e la fa sbandare. Bisogna sempre frenare dolcemente e gradualmente, anticipando le manovre.', 'Le parole ''frenare energicamente'' e ''ogni volta'' sono le trappole. Frenare di colpo è sempre sbagliato sul ghiaccio, e non si frena ogni volta che si incrocia un veicolo.', 'Ghiaccio = frenare piano, mai di colpo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24748, 'Procedere con il cambio in folle (senza marcia inserita) significa che non hai il controllo del freno motore. Questo rende l''auto più difficile da controllare, specialmente in discesa o se devi frenare, perché non hai l''aiuto del motore per rallentare in modo controllato.', '''Cambio in folle'' significa che non c''è nessuna marcia inserita. Questo toglie il controllo del veicolo in situazioni di scarsa aderenza.', 'Ghiaccio = marcia inserita per controllo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24749, 'Quando c''è molta nebbia e si vede poco, le strisce bianche o gialle sull''asfalto (la segnaletica orizzontale) sono un aiuto importante per capire dove finisce la strada e dove si può guidare. Ti aiutano a mantenere la direzione giusta.', 'La frase ''lasciarsi guidare'' significa usarla come riferimento utile, non che devi seguirla senza pensare o che sia l''unico aiuto.', 'Nebbia = Strisce amiche.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24750, 'Se la nebbia è fitta e vedi poco, devi andare molto piano. La velocità deve essere sempre adatta a quanto riesci a vedere, così hai il tempo di frenare se c''è un ostacolo.', 'La parola ''adeguata'' è importante: significa che la velocità non è fissa, ma cambia in base a quanto è fitta la nebbia e quanto si vede.', 'Meno vedi, più piano vai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24751, 'Se la nebbia è così fitta che non puoi proprio continuare a guidare, la cosa più sicura è fermarsi. Ma devi farlo fuori dalla strada (carreggiata), per non essere un pericolo per gli altri veicoli che potrebbero non vederti.', 'Le parole ''se necessario'' e ''fuori dalla carreggiata'' sono fondamentali. Indica che è una soluzione estrema e che il luogo dove fermarsi è importante per la sicurezza.', 'Fermo? Fuori strada!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24752, 'Se sei costretto a fermarti sulla strada (per esempio per un guasto improvviso) e non puoi spostarti, devi assolutamente accendere le quattro frecce lampeggianti. Questo avvisa gli altri guidatori che c''è un pericolo e che il tuo veicolo è fermo.', 'La frase ''se costretti a fermarsi sulla carreggiata'' indica che è una situazione di emergenza e non una scelta. Le ''quattro frecce'' sono la segnalazione corretta.', 'Fermo in strada? Quattro frecce!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24753, 'Fermarsi sulla strada quando c''è nebbia è molto pericoloso perché gli altri veicoli potrebbero non vederti in tempo. Devi farlo solo se non hai proprio altra scelta, come un guasto grave e improvviso.', 'Le parole ''evitare'' e ''se non per cause di forza maggiore'' sottolineano che è una cosa da non fare assolutamente, a meno di emergenze inevitabili.', 'Mai fermo in strada, se puoi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24754, 'Con la nebbia, devi accendere le luci giuste per vedere e farti vedere. I proiettori fendinebbia sono i migliori. Se la tua auto non li ha, devi accendere almeno gli anabbaglianti.', 'La parte ''o, in mancanza'' è importante: indica che i fendinebbia sono la prima scelta, ma se non ci sono, gli anabbaglianti sono l''alternativa minima.', 'Nebbia = Fendinebbia (o anabbaglianti).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24755, 'La luce posteriore per nebbia è una luce rossa molto forte che si trova dietro l''auto. Serve a farti vedere bene da chi ti segue, così eviti che ti tamponino (che ti vengano addosso da dietro).', 'La frase ''luce posteriore per nebbia'' specifica esattamente quale luce usare per la parte posteriore del veicolo.', 'Nebbia = Fatti vedere anche dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24756, 'Guidare con la nebbia è una delle situazioni più difficili e pericolose. Devi essere estremamente attento, concentrato sulla strada e guidare con molta cautela per evitare incidenti.', 'Le parole ''massima prudenza e concentrazione'' indicano il livello di attenzione e cautela richiesto in una situazione così pericolosa.', 'Nebbia = Occhi aperti e testa lucida.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24757, 'Le luci di posizione sono molto deboli e non bastano per farti vedere bene dagli altri veicoli o per illuminare la strada quando c''è nebbia fitta. Devi usare luci più potenti come i fendinebbia o gli anabbaglianti.', 'La parola ''sole'' è la trappola: indica che solo quelle luci non sono sufficienti. Servono luci più forti.', 'Posizioni = Non bastano con la nebbia.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24758, 'L''indicatore di direzione (la freccia) serve per segnalare che stai per svoltare o cambiare corsia. Tenerlo acceso continuamente senza motivo confonde gli altri guidatori e non serve a farti notare meglio nella nebbia.', 'La frase ''mantenere in funzione'' significa tenerlo acceso sempre, il che è sbagliato. La freccia si usa solo per segnalare una manovra.', 'Freccia = Solo per svoltare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24759, 'Andare a zig zag (muoversi a destra e sinistra) è estremamente pericoloso, soprattutto con la nebbia. Non ti aiuta a farti notare, ma aumenta il rischio di perdere il controllo dell''auto o di causare un incidente.', 'Le parole ''procedere a zig zag'' e ''per far meglio notare'' sono la trappola. L''azione è pericolosa e la motivazione è sbagliata.', 'Zig zag = Pericolo, non visibilità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24760, 'Con la nebbia, la visibilità è ridotta e hai meno tempo per reagire. Per questo, devi aumentare la distanza di sicurezza dal veicolo che ti precede, non diminuirla! Essere troppo vicino è molto pericoloso.', 'La frase ''quanto più vicino possibile'' è la trappola principale. È l''esatto contrario di quello che si deve fare in caso di nebbia.', 'Nebbia = Lontano dal veicolo davanti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24761, 'Il clacson (il ''segnale acustico'') si usa solo in caso di pericolo immediato per avvisare. Suonarlo continuamente nella nebbia non aiuta a guidare, crea solo rumore e disturba gli altri, senza migliorare la sicurezza.', 'La parola ''continuativamente'' è la trappola. Il clacson non va mai usato in modo continuo, ma solo per brevi avvisi di pericolo.', 'Clacson = Solo per emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24762, 'La cintura di sicurezza è fondamentale per la tua sicurezza in caso di incidente. Non devi mai sganciarla, nemmeno per un secondo, perché ti protegge dagli urti. L''idea di abbandonare il veicolo non è una priorità rispetto alla protezione durante l''impatto.', 'Le parole ''sganciata'' e ''più pronti ad abbandonare'' sono concetti pericolosi e completamente sbagliati. La cintura deve essere sempre allacciata.', 'Cintura = Sempre allacciata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24763, 'In caso di incidente con feriti, è un dovere legale e morale fermarsi e aiutare le persone coinvolte. Non farlo è un reato.', 'La parola ''obbligo'' è forte, ma in questo caso è assolutamente vera e fondamentale per la sicurezza e la legge.', 'Incidente con feriti? Fermati e aiuta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24764, 'Dopo un incidente, devi scambiare i tuoi dati (nome, patente, targa, assicurazione) con le altre persone coinvolte. Questo serve per la gestione dell''incidente e per le assicurazioni.', 'Anche qui, ''deve fornire'' indica un obbligo preciso per la corretta gestione dell''incidente.', 'Dati e assicurazione: sempre da dare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24765, 'Se è necessario capire come è avvenuto l''incidente, non devi toccare o spostare nulla (come pezzi di veicolo, segni di frenata) per non alterare la scena. Questo aiuta le autorità a ricostruire i fatti.', 'La frase ''deve evitare che vengano modificate'' significa che devi fare in modo che la scena rimanga intatta.', 'Tracce? Non toccare, per capire!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24766, 'Per denunciare un incidente alla tua assicurazione, puoi usare il ''modulo blu'' (chiamato anche CAI - Constatazione Amichevole di Incidente) che ti fornisce la compagnia assicurativa. È un modo semplice per raccogliere i dati.', 'La frase ''può avvalersi'' significa che hai la possibilità di usarli, non è un obbligo esclusivo, ma è molto consigliato.', 'Modulo blu: per l''assicurazione, sì!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24767, 'Il segnale mobile di pericolo (il triangolo) va posizionato a terra, a una certa distanza dal veicolo, per avvisare gli altri conducenti. Non va mai messo sul lunotto posteriore del veicolo.', 'La trappola è ''sul lunotto posteriore''. Ricorda che il triangolo va sempre a terra.', 'Triangolo? A terra, non sul vetro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24768, 'Non c''è nessuna legge che ti obbliga a coprire il veicolo con un telo di plastica dopo un incidente. Non è una procedura prevista dal Codice della Strada.', 'La parola ''obbligatorio'' rende questa affermazione falsa. Non è un obbligo.', 'Telo? No, non è un obbligo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24769, 'Il segnale mobile di pericolo (triangolo) deve essere usato quando il veicolo fermo non è ben visibile, sia di giorno che di notte. Non è ''solo di notte''.', 'La trappola è ''solo di notte''. Il triangolo si usa sempre quando la visibilità è scarsa, indipendentemente dall''ora.', 'Triangolo? Non solo di notte!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24770, 'Non è obbligatorio spostare subito il veicolo sul marciapiede dopo un incidente. Anzi, a volte è meglio non spostarlo per non alterare la scena o per non creare altri pericoli. Si sposta solo se è possibile e necessario per la circolazione, e in sicurezza.', 'La frase ''obbligatorio collocare subito il veicolo sul marciapiede'' è falsa. Non è un obbligo e potrebbe essere pericoloso.', 'Marciapiede? No, non è la regola!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24771, 'Nei centri abitati, se la strada è illuminata e il veicolo è ben visibile, non è obbligatorio usare il segnale mobile di pericolo. L''obbligo scatta solo se il veicolo non è visibile a distanza di sicurezza.', 'La trappola è ''anche nei centri abitati''. In città, se c''è buona visibilità e illuminazione, non è sempre obbligatorio.', 'Triangolo in città? Solo se non si vede!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24772, 'La pompa di iniezione è un componente molto complesso del motore. La sua manutenzione richiede conoscenze tecniche specifiche e attrezzi particolari. Deve essere fatta da un meccanico specializzato, non dal conducente.', 'La frase ''esegua personalmente'' è la trappola. Alcune manutenzioni sono per esperti.', 'Pompa iniezione? Lascia fare al meccanico!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24773, 'La distanza percorsa durante il tempo di reazione (il tempo che impieghi a decidere di frenare) aumenta con la velocità. Se vai più veloce, in quel secondo di reazione farai più strada.', 'La trappola è ''non varia con la velocità''. In realtà, varia eccome: più veloce vai, più strada percorri prima di iniziare a frenare.', 'Velocità alta? Reazione lunga!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24774, 'Se la spia rossa dell''olio di lubrificazione rimane accesa, significa che c''è un problema grave al motore, come una pressione dell''olio insufficiente. In questo caso, devi fermarti subito e far controllare il veicolo. Non indica un ''corretto funzionamento''.', 'Le parole ''corretto funzionamento'' e ''spia rossa... accesa'' sono in contraddizione. Una spia rossa accesa indica sempre un problema.', 'Spia olio rossa? Fermati, c''è un guaio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24775, 'Modificare la cilindrata del motore per aumentare le prestazioni non è consentito. Queste modifiche alterano le caratteristiche originali del veicolo e richiedono una nuova omologazione, che è molto difficile da ottenere.', 'La parola ''consentito'' è la trappola. Le modifiche strutturali al motore non sono permesse senza procedure specifiche e costose.', 'Cilindrata? Non si tocca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24776, 'I freni devono essere sempre in perfetto stato ed equilibrati. Non puoi compensare un problema ai freni agendo sullo sterzo, è estremamente pericoloso e compromette la sicurezza del veicolo.', 'La frase ''Non è necessario'' e l''idea di ''correggere agendo sullo sterzo'' sono la trappola. La sicurezza dei freni è fondamentale e non si può improvvisare.', 'Freni squilibrati? Riparali subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24777, 'Su strada sdrucciolevole (bagnata, ghiacciata, con ghiaia), premere a fondo il pedale del freno può bloccare le ruote e farti perdere il controllo del veicolo. Devi frenare dolcemente e gradualmente.', 'La frase ''premere a fondo il pedale del freno'' è la trappola. Su superfici scivolose, questa azione è sbagliata e pericolosa.', 'Sdrucciolevole? Frena piano piano!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24778, 'Modificare le impostazioni elettroniche della centralina del motore (il cosiddetto ''chiptuning'') per aumentare le prestazioni non è consentito. Queste modifiche alterano le caratteristiche tecniche del veicolo e non sono omologate, rendendo il veicolo non conforme alle norme.', 'La parola ''consentito'' è la trappola. Come per la cilindrata, le modifiche non omologate alla centralina sono vietate.', 'Centralina? Non si modifica!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24779, 'Quando un passeggero sale o scende, la cosa più sicura è farlo dal lato del marciapiede, perché lì non c''è traffico. Se non c''è un marciapiede, bisogna scegliere il lato dove non passano le macchine, cioè il lato opposto al traffico, per evitare pericoli.', 'La parte ''o, in mancanza, dal lato opposto al traffico'' è importante. Significa che se non c''è il marciapiede, devi comunque cercare il lato più sicuro, lontano dalle auto.', 'Marciapiede è sicurezza. Se non c''è, lontano dal traffico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24780, 'Aprire la portiera di un veicolo può essere pericoloso per chi passa, come ciclisti o pedoni. Per questo, devi sempre controllare bene che non ci sia nessuno prima di aprirla, per non causare incidenti.', 'La frase ''solamente quando non si causa pericolo'' è la chiave. Indica che la sicurezza è la priorità assoluta e l''apertura è permessa solo in assenza di rischio.', 'Prima di aprire, guarda sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24781, 'È molto pericoloso far salire o scendere un passeggero se il veicolo è ancora in movimento, anche se va piano. Il passeggero potrebbe cadere o farsi male. Bisogna aspettare che l''auto sia completamente ferma.', 'La parola ''completamente'' è fondamentale. Non basta che il veicolo rallenti, deve essere del tutto immobile.', 'Veicolo fermo = passeggero sicuro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24782, 'I bambini non sempre capiscono i pericoli del traffico e possono fare movimenti improvvisi. Per la loro sicurezza, è sempre meglio che un adulto li aiuti e li controlli quando salgono o scendono dall''auto.', 'La parola ''opportuno'' significa che è la cosa giusta e migliore da fare, anche se non è un obbligo assoluto. È una buona pratica di sicurezza.', 'Bambini e traffico? Sempre con un adulto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24783, 'Questa affermazione è falsa. Anche la portiera di destra può essere pericolosa. Per esempio, un ciclista o un pedone potrebbe passare proprio in quel momento. Non esiste un''apertura ''priva di qualsiasi rischio''. Bisogna sempre fare attenzione.', 'La frase ''priva di qualsiasi rischio e pericolo'' è una trappola. Nel traffico, quasi nulla è ''privo di qualsiasi'' rischio. Questa esagerazione rende l''affermazione falsa.', 'Ogni portiera ha un rischio. Controlla sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24784, 'Quando la tua auto è bloccata nella neve o nella sabbia e le ruote girano a vuoto (slittano), mettere qualcosa sotto la ruota che slitta, come un tappeto o un pezzo di legno, aiuta la ruota a fare più ''presa'' (attrito) sul terreno. Così l''auto può muoversi e uscire dall''infossamento.', 'La frase ''è consigliabile'' significa che è una buona idea, una cosa utile da fare, non un obbligo. ''Attrito'' è la forza che permette alle ruote di fare presa e non scivolare.', 'Se slitti, metti sotto qualcosa per fare grip!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24785, 'Se la tua auto è bloccata nella neve o nella sabbia e non riesci a partire con la prima marcia (perché le ruote slittano troppo), è meglio usare una marcia più alta, come la seconda o la terza. Le marce alte danno meno ''spinta'' alle ruote, che così girano più lentamente e riescono a fare più presa sul terreno senza slittare.', 'La parola ''opportuno'' significa che è la cosa giusta o migliore da fare in quella situazione. La ''prima marcia'' di solito è per partire, ma in questo caso specifico è controproducente.', 'Sabbia/neve: marcia alta per partire piano e non slittare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24786, 'Questa affermazione è falsa. L''aderenza (la ''presa'' delle gomme sulla strada) è molto più bassa su una strada ghiacciata che su una strada innevata. Il ghiaccio è estremamente scivoloso e offre pochissima aderenza, rendendo la guida molto più pericolosa rispetto alla neve, che offre un po'' più di grip.', 'La frase ''minore che'' è una comparazione. La domanda dice che l''aderenza sulla neve è ''minore'' (meno) di quella sul ghiaccio, ma è il contrario: l''aderenza sul ghiaccio è molto più bassa di quella sulla neve.', 'Ghiaccio è peggio della neve: meno aderenza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24787, 'È VERO. Se vai troppo veloce, hai meno tempo per reagire e la tua auto ha bisogno di più spazio per fermarsi. Questo aumenta il rischio di tamponare l''auto davanti a te se frena all''improvviso.', 'La parola ''principalmente'' significa che è una delle cause più importanti, ma non l''unica.', 'Velocità alta = spazio di frenata lungo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24788, 'È VERO. La distanza di sicurezza è lo spazio che devi lasciare tra la tua auto e quella davanti. Se sei troppo vicino, non hai il tempo e lo spazio necessari per frenare in sicurezza e quindi tamponi.', 'La parola ''maggiormente'' indica che questa è una delle cause principali e più frequenti dei tamponamenti.', 'Poca distanza = rischio tamponamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24789, 'È VERO. Se sei distratto (guardi il telefono, parli, pensi ad altro), non vedi cosa succede sulla strada. Questo ti impedisce di reagire in tempo e frenare, causando un tamponamento.', 'Anche qui ''principalmente'' sottolinea che la disattenzione è una causa molto comune e grave.', 'Disattenzione = pericolo immediato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24790, 'È FALSO. Il ''freno di stazionamento'' (o freno a mano) si usa quando l''auto è ferma, per non farla muovere. Non si usa mentre si guida. Un guasto al freno di stazionamento non può causare un tamponamento mentre sei in marcia.', 'La frase ''freno di stazionamento'' è la parola chiave. Ricorda che è diverso dal freno di servizio (il pedale del freno).', 'Freno di stazionamento = auto ferma.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24791, 'È FALSO. Il ''servosterzo'' è un sistema che ti aiuta a girare il volante più facilmente, rendendo la guida meno faticosa. Non ha nulla a che fare con la frenata o con la distanza di sicurezza, che sono le cause dei tamponamenti. Quasi tutte le auto moderne hanno il servosterzo.', 'La parola ''servosterzo'' è la trappola. Non confonderla con i sistemi di frenata o di sicurezza attiva.', 'Servosterzo = sterzo leggero, non frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24792, 'In un tunnel, se ci sono molte macchine ferme in fila, è molto importante lasciare più spazio tra un veicolo e l''altro. Questo spazio extra serve a prevenire che, in caso di incendio, le fiamme si diffondano rapidamente da una macchina all''altra, aumentando la sicurezza per tutti.', 'La frase ''è opportuno aumentare'' significa che è la cosa giusta e utile da fare per la sicurezza, non un obbligo assoluto ma una buona pratica. ''Scongiurare'' significa evitare o prevenire.', 'Tunnel + fila = più spazio = meno rischio incendio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24793, 'Se c''è un incendio in un tunnel, la prima cosa da fare è lasciare subito la tua auto. Poi devi cercare e seguire i cartelli che ti indicano le uscite di emergenza o i luoghi sicuri, che spesso sono protetti da porte speciali (tagliafuoco) che bloccano il fuoco e il fumo.', '''Abbandonare velocemente'' sottolinea l''urgenza dell''azione. ''Vie di fuga'' e ''luoghi sicuri protetti da porte tagliafuoco'' sono termini specifici per le procedure di emergenza nei tunnel.', 'Incendio tunnel = lascia auto, segui cartelli fuga.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24794, 'In caso di incendio in un tunnel, è fondamentale ascoltare e seguire attentamente quello che ti dicono le persone che lavorano lì (il personale di servizio) o i vigili del fuoco. Loro sono lì per aiutarti e sanno qual è la strada più sicura, così eviti di sbagliare direzione.', '''Attenersi alle istruzioni vocali'' significa seguire esattamente quello che viene detto. ''Personale di servizio o dei vigili del fuoco'' sono le autorità competenti in caso di emergenza.', 'Incendio tunnel = ascolta vigili/personale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24798, 'Questa affermazione è falsa. Se c''è un incendio in un tunnel, devi sempre dare la precedenza agli ordini che ti vengono dati a voce dai vigili del fuoco o dal personale di servizio. Loro sono sul posto, hanno le informazioni più aggiornate e sanno come gestire al meglio la situazione, anche se i cartelli indicano una cosa diversa. Le istruzioni dirette sono sempre più importanti della segnaletica fissa.', 'La frase trappola è ''anche se in netto contrasto''. Questo indica un conflitto tra due fonti di informazione. In caso di conflitto, le istruzioni umane (vigili del fuoco) hanno sempre la precedenza sulla segnaletica fissa.', 'Ordini vigili > cartelli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24799, 'I motocicli sono più stretti e piccoli delle auto. Per questo, da lontano, sono più difficili da vedere e quindi ''meno visibili''.', 'La frase ''ridotta sagoma frontale'' significa che il veicolo è stretto e piccolo se visto da davanti. Questo è il motivo per cui è ''meno visibile''.', 'Piccolo = Meno visibile da lontano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24800, 'I conducenti delle auto devono fare molta attenzione alle moto e agli scooter. Questi veicoli sono più piccoli e possono essere difficili da vedere, specialmente negli specchietti o negli angoli ciechi.', 'La frase ''in generale'' indica una regola valida nella maggior parte delle situazioni. ''Meno facilmente visibili'' è la ragione principale per cui serve attenzione.', 'Moto = Attenzione extra, sono ''nascoste''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24801, 'Quando apri la portiera della tua auto, devi sempre guardare bene, soprattutto dietro. Una moto o uno scooter potrebbero arrivare e, essendo meno visibili, potresti non notarli in tempo e causare un incidente.', 'L''azione ''nell''aprire le portiere'' è il momento critico. La ragione è sempre che sono ''meno visibili''.', 'Apri portiera = Guarda bene, soprattutto per le moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24802, 'Agli incroci, anche se vedi auto ferme, devi pensare che una moto potrebbe arrivare velocemente, sorpassando le auto in coda. Essendo piccola, potresti non vederla subito. Sii sempre molto prudente.', 'La frase ''sempre considerare la possibilità'' significa che devi pensarci ogni volta. ''Senza che sia visibile a distanza'' e ''ha sorpassato i veicoli fermi'' descrivono il pericolo specifico.', 'Incrocio + Auto ferme = Occhio alla moto che sorpassa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24803, 'Nel traffico intenso, se le auto sono in coda, una moto potrebbe passare a destra per superare. Se apri la portiera per scendere senza guardare, potresti colpirla. Devi sempre controllare.', '''Intenso traffico con incolonnamento'' descrive la situazione. ''Sorpassando a destra'' è la manovra pericolosa che le moto a volte fanno. ''Sempre considerare la possibilità'' è l''atteggiamento richiesto.', 'Coda + Portiera = Guarda a destra per le moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24804, 'Quando superi una moto, devi lasciare molto spazio laterale. Le moto possono sbandare o essere spinte dal vento, e se vai veloce, l''aria che sposti può farle perdere l''equilibrio. Mantenere una buona distanza è fondamentale per la sicurezza.', '''Soprattutto se ad elevata velocità'' rafforza l''importanza di lasciare spazio. ''Buona distanza laterale di sicurezza'' è la chiave.', 'Sorpasso moto = Ampio spazio laterale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24805, 'Le moto devono tenere le luci anabbaglianti accese anche di giorno. Questo le rende più visibili agli altri veicoli e aumenta la sicurezza sulla strada.', '''Per rendersi maggiormente visibili'' è lo scopo. ''Anche di giorno'' è la condizione che rende la regola speciale per le moto.', 'Moto = Luci accese sempre (anche di giorno).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24806, 'Nei centri abitati, il clacson (avvisatore acustico) si usa solo in caso di pericolo immediato, per evitare un incidente. Non si può usare ''in ogni caso'' solo perché si arriva a un incrocio, altrimenti si fa rumore inutile e si disturba.', 'La parola ''in ogni caso'' è una trappola. Il clacson ha regole precise e non si può usare liberamente.', 'Clacson = Solo per pericolo, non ''in ogni caso''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24808, 'Se c''è l''obbligo di catene o pneumatici invernali per la neve, le moto non possono circolare. È troppo pericoloso per loro guidare sulla neve o sul ghiaccio, anche se le auto possono farlo con l''equipaggiamento giusto.', 'La frase ''è comunque concesso'' è una trappola. Non è affatto concesso alle moto in queste condizioni.', 'Neve + Obbligo catene = Moto ferme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24809, 'Anche se alcune moto fanno rumore, non è il rumore che le rende più facili da vedere o ''percepibili''. La loro piccola dimensione le rende difficili da vedere, e il rumore non sempre aiuta a capire dove sono o quanto sono vicine. La visibilità è il fattore chiave, non il rumore.', 'La frase ''più facilmente percepibili'' è falsa. La giustificazione ''perché più rumorosi'' non è corretta per la percezione visiva.', 'Rumore moto = Non significa più visibili.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24810, 'È il contrario! Essendo piccoli e stretti (hanno una ''ridotta sagoma frontale''), i veicoli a due ruote sono MENO visibili da lontano, non ''più visibili''.', 'La parola ''più visibili'' è la trappola. La ''ridotta sagoma frontale'' li rende meno visibili, non di più.', 'Piccolo = Meno visibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24811, 'Di notte, le moto devono usare le luci anabbaglianti. Le luci abbaglianti si usano solo fuori dai centri abitati e quando non ci sono altri veicoli davanti o che vengono in senso opposto, per non accecare nessuno. Non si possono usare ''in ogni caso''.', 'La frase ''in ogni caso'' è la trappola. L''uso dei ''proiettori abbaglianti'' è regolamentato e non è sempre permesso.', 'Abbaglianti = Non ''in ogni caso'', solo se non accechi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24812, 'L''abbigliamento è molto importante per i motociclisti! Vestiti chiari, riflettenti o con colori vivaci rendono il motociclista molto più visibile agli altri, specialmente di notte o con poca luce. Quindi, l''abbigliamento ''incide'' eccome sulla visibilità.', 'La frase ''non incide'' è la trappola. Invece, l''abbigliamento ha un grande impatto sulla visibilità.', 'Abbigliamento = Scegli colori chiari per essere visto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24813, 'Le rotaie del tram sono fatte di metallo e possono essere scivolose, specialmente per le ruote strette di una moto o di una bicicletta. È facile perdere l''equilibrio e cadere.', 'La parola ''pericoloso'' è corretta in questo contesto, perché le rotaie rappresentano un rischio reale.', 'Rotaie = scivolo per due ruote.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24814, 'Le strisce pedonali sono dipinte con vernice che, soprattutto quando è bagnata o usurata, può essere molto scivolosa per i veicoli a due ruote. Passarci sopra può far perdere aderenza.', 'Anche qui, ''pericoloso'' è la parola chiave. Non sottovalutare mai la scivolosità delle strisce.', 'Strisce bianche = attenzione, possono scivolare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24815, 'I tombini sono coperture metalliche che si trovano sulla strada. Sono lisci e, come le rotaie, possono essere molto scivolosi per le ruote di moto e biciclette, causando la perdita di controllo.', 'La parola ''pericoloso'' descrive bene il rischio dei tombini per i vecoli a due ruote.', 'Tombino = ghiaccio per moto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24816, 'Quando piove, l''acqua rende le rotaie del tram ancora più scivolose. Il rischio di cadere o perdere il controllo del veicolo a due ruote aumenta moltissimo.', 'Le parole ''particolarmente pericolose'' e ''quando il fondo stradale è bagnato'' sono importanti. Il pericolo aumenta con la pioggia.', 'Rotaie + bagnato = pericolo raddoppiato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24817, 'La vernice delle strisce pedonali, quando è bagnata dalla pioggia, diventa estremamente scivolosa per le gomme dei veicoli a due ruote. È come passare sul sapone.', 'Anche qui, ''particolarmente pericolose'' e ''quando il fondo stradale è bagnato'' indicano un aumento del rischio.', 'Strisce + bagnato = saponetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24818, 'Il metallo dei tombini, quando è bagnato dalla pioggia, offre pochissima aderenza alle gomme. Passarci sopra può facilmente causare uno sbandamento o una caduta.', 'Le parole ''particolarmente pericolosi'' e ''quando il fondo stradale è bagnato'' sottolineano l''aggravarsi del pericolo.', 'Tombino + bagnato = pattinaggio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24819, 'Frenare su superfici già scivolose come rotaie, strisce o tombini, e ancora di più se sono bagnate, è molto rischioso. Le ruote possono bloccarsi o perdere aderenza, causando una caduta.', 'La frase ''particolarmente pericolosa'' evidenzia che la frenata in queste condizioni è ad alto rischio.', 'Frenare su scivoloso e bagnato = caduta quasi certa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24820, 'Andare veloci su tombini o rotaie aumenta il rischio di perdere il controllo del veicolo. Le ruote possono scivolare o incastrarsi, causando sbandamenti o cadute.', 'La frase ''in velocità'' è la chiave. La velocità amplifica il pericolo su queste superfici.', 'Velocità + ostacolo = pericolo maggiore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24821, 'Le rotaie del tram e i tombini sono sempre un pericolo per i veicoli a due ruote, perché sono scivolosi e possono far perdere l''equilibrio. Non è mai vero che ''non costituiscono un pericolo''.', 'La parola trappola è ''non costituiscono un pericolo''. È FALSO, perché invece lo sono sempre.', 'Rotaie e tombini = sempre attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24822, 'Accelerare su superfici scivolose e bagnate è molto pericoloso, perché si rischia di perdere aderenza e cadere. Bisogna invece rallentare e passare con cautela.', 'La frase ''accelerare decisamente'' è la trappola. È l''azione sbagliata da fare.', 'Bagnato + scivoloso = rallenta, non accelerare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24823, 'Alzarsi in piedi sulle pedivelle rende il veicolo a due ruote meno stabile e più difficile da controllare, aumentando il rischio di caduta, specialmente su superfici scivolose.', 'La frase ''alzarsi in piedi sulle pedivelle'' è la trappola. Questa manovra riduce la stabilità.', 'Stabilità = seduto, non in piedi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24824, 'Fare un''impennata è una manovra estremamente pericolosa e illegale. Fa perdere il controllo del veicolo e non serve a evitare i pericoli della strada, anzi, li aumenta enormemente.', 'La frase ''in impennata'' è la trappola. È una manovra da non fare mai in strada.', 'Impennare = cadere e multa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24825, 'Il pericolo delle rotaie e dei tombini non dipende dal tipo di cambio del veicolo (automatico o manuale). È un rischio per tutti i veicoli a due ruote a causa della loro natura scivolosa.', 'La frase ''nella sola eventualità che il suo veicolo sia dotato di cambio automatico'' è la trappola. Il pericolo esiste per tutti i veicoli a due ruote, indipendentemente dal cambio.', 'Pericolo = per tutti, non solo per il cambio automatico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24826, 'Circolare con le ruote nel solco della rotaia è molto pericoloso. Le ruote possono incastrarsi o scivolare, causando una perdita di controllo e una caduta. È meglio cercare di attraversarle con un angolo il più possibile perpendicolare.', 'La frase ''circolare con entrambe le ruote nel solco della rotaia del tram'' è la trappola. È una manovra molto pericolosa.', 'Solco rotaia = trappola, non entrarci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24827, 'Se ti senti stanco mentre guidi, è molto importante fermarsi. Raggiungere la piazzola di sosta più vicina e riposare è la cosa giusta da fare per la tua sicurezza e quella degli altri. Guidare stanchi è pericoloso perché si può perdere la concentrazione o addormentarsi.', 'La parola ''opportuno'' significa ''giusto'' o ''consigliabile''. Non è un obbligo di legge, ma è la scelta più saggia e sicura per evitare incidenti.', 'Stanco al volante? Sosta e riposa!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24828, 'Questa affermazione è falsa. Se sei stanco, la tua attenzione e i tuoi riflessi sono più lenti. Avvicinarsi al veicolo che ti precede è molto pericoloso perché aumenti il rischio di un incidente (tamponamento). Devi sempre mantenere una distanza di sicurezza adeguata, e ancora di più se sei stanco.', 'La frase ''avvicinarsi il più possibile'' è la trappola. Quando si è stanchi, si deve fare esattamente il contrario: aumentare la distanza di sicurezza per avere più tempo per reagire.', 'Stanco? Aumenta la distanza, non diminuirla!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24829, 'È vero. Il nostro corpo ha bisogno di tempo, cioè diverse ore, per eliminare l''alcol. Non si può recuperare subito la capacità di guidare dopo aver bevuto troppo.', 'La parola chiave è ''alcune ore''. Significa che ci vuole tempo, non è un processo immediato.', 'Alcol: solo il tempo lo smaltisce.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24830, 'È vero. L''alcol non sparisce velocemente dal corpo. Se poi si prendono anche dei farmaci, la situazione peggiora e il recupero è ancora più lento e pericoloso.', 'Attenzione a ''non può recuperare velocemente'' e ''specie se ha assunto anche dei farmaci''. I farmaci possono aumentare gli effetti negativi dell''alcol.', 'Alcol + farmaci = pericolo doppio, recupero lento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24831, 'È falso. Mangiare cibi salati non aiuta il corpo a eliminare l''alcol più velocemente. L''alcol deve essere smaltito dal fegato e questo richiede tempo, indipendentemente da cosa si mangia.', 'La trappola è ''recuperare velocemente'' e ''cibi piuttosto salati''. Non esiste una scorciatoia per smaltire l''alcol.', 'Cibo salato non ''lava via'' l''alcol.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24832, 'È falso. Bere caffè amaro può farti sentire più sveglio, ma non elimina l''alcol dal tuo corpo e non ti rende idoneo a guidare. L''alcol rimane nel sangue e i tuoi riflessi sono comunque rallentati.', 'Le parole chiave sono ''recuperare velocemente'' e ''caffè amaro''. Il caffè non annulla gli effetti dell''alcol.', 'Caffè non ''sveglia'' la sobrietà.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24833, 'I farmaci sedativi rallentano i tuoi riflessi e possono farti sentire sonnolento. Guidare in queste condizioni è molto pericoloso perché non reagisci in tempo agli imprevisti.', 'La parola ''alcuni'' è importante: non tutti i farmaci, ma quelli che hanno effetti sul sistema nervoso e causano sonnolenza o rallentamento.', 'Sedativi = sonno = non guidare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24834, 'Anche alcuni farmaci antidepressivi possono causare effetti collaterali come sonnolenza, vertigini o difficoltà di concentrazione. Questi effetti possono rendere la guida meno sicura. È fondamentale leggere il foglietto illustrativo o chiedere al medico.', 'Anche qui, ''farmaci antidepressivi'' non significa tutti, ma molti possono avere effetti sulla guida. ''Compromessa'' significa che la tua capacità di guidare è peggiorata.', 'Antidepressivi = attenzione agli effetti collaterali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24835, 'Gli allucinogeni sono droghe che alterano gravemente la tua percezione della realtà, i tuoi riflessi e la tua capacità di giudizio. Guidare sotto l''effetto di queste sostanze è estremamente pericoloso e illegale.', 'La parola ''allucinogeni'' indica sostanze che alterano profondamente la mente. ''Compromessa'' qui significa che la capacità di guidare è completamente annullata o resa folle.', 'Droghe = mai al volante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24836, 'L''alcol riduce i tuoi riflessi, la tua vista e la tua capacità di prendere decisioni rapide. Anche una piccola quantità può aumentare il rischio di incidenti. Per la tua sicurezza e quella degli altri, è meglio non bere se devi guidare.', 'La frase ''bevande alcoliche'' include qualsiasi tipo di alcol. ''Compromessa'' significa che la tua abilità di guidare è ridotta e meno sicura.', 'Alcol = zero alla guida.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24837, 'Il caffè contiene caffeina, che è uno stimolante. Non compromette la tua idoneità alla guida, anzi, può aiutarti a rimanere sveglio. Ovviamente, non sostituisce il riposo necessario.', 'La parola ''amaro'' non cambia l''effetto della caffeina. ''Compromessa'' qui è la parola chiave: il caffè non peggiora la tua guida.', 'Caffè = sveglio, non compromesso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24838, 'Le bevande gassate, come la cola o l''aranciata, non contengono sostanze che alterano la tua capacità di guidare. Sono bevande comuni e non pericolose per la guida.', 'La frase ''bevande gassate'' si riferisce a bibite normali. ''Compromessa'' è la parola da notare: queste bevande non peggiorano la tua guida.', 'Bibite gassate = nessun problema.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24839, 'Gli integratori di sali minerali servono a reintegrare le sostanze perse, ad esempio dopo l''attività fisica. Non hanno effetti negativi sulla tua capacità di guidare.', 'La frase ''integratori di sali minerali'' indica prodotti per la salute che non sono farmaci con effetti sedativi o alteranti. ''Compromessa'' è la parola chiave: non peggiorano la tua guida.', 'Sali minerali = energia, non pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24840, 'Gli integratori alimentari, in generale, sono prodotti che completano la dieta e non contengono sostanze che compromettono la guida. È sempre bene leggere l''etichetta, ma di solito non creano problemi.', 'La frase ''integratori alimentari'' è un termine generico per prodotti che non sono farmaci. ''Compromessa'' è la parola chiave: di solito non peggiorano la tua guida.', 'Integratori = di solito ok.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24841, 'L''hashish e la marijuana sono droghe che alterano la tua percezione, i tuoi riflessi e la tua capacità di giudizio. Guidare sotto il loro effetto è molto pericoloso perché non sei lucido e non reagisci in tempo. Quindi, la frase è VERA.', 'La parola ''può'' indica una possibilità, ma in questo caso è una possibilità molto alta e quasi una certezza che la guida sarà compromessa.', 'Droghe (anche leggere) = Guida NO!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24842, 'L''eroina e la cocaina sono droghe molto potenti e pericolose. Alterano gravemente la mente e il corpo, rendendo impossibile guidare in sicurezza. I tuoi riflessi sono lenti o incontrollati, e non puoi prendere decisioni giuste. Quindi, la frase è VERA.', 'Anche qui, ''può'' indica una possibilità, ma con droghe così forti, la compromissione è certa e grave.', 'Droghe pesanti = Guida MAI!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24843, 'I farmaci sedativi sono quelli che ti fanno sentire rilassato o ti aiutano a dormire. Queste sostanze possono rallentare i tuoi riflessi, diminuire la tua attenzione e farti sentire assonnato. Per questo, è fondamentale leggere il foglietto illustrativo di ogni farmaco e chiedere al medico o al farmacista se puoi guidare. Quindi, la frase è VERA.', 'Le parole ''alcune sostanze'' e ''possono compromettere'' sono importanti: non tutti i farmaci sedativi hanno lo stesso effetto, ma molti sì. È un rischio reale da considerare.', 'Farmaci sedativi = Attenzione doppia! Leggi il bugiardino.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24844, 'L''LSD e l''anfetamina sono droghe molto pericolose. L''LSD provoca allucinazioni e altera completamente la realtà, mentre l''anfetamina rende iperattivi e poi causa un forte crollo. Entrambe rendono la guida estremamente pericolosa e impossibile. La frase dice che ''non compromette'' la facoltà di guida, il che è FALSO.', 'La parola trappola è ''non''. Le droghe come LSD e anfetamina compromettono SEMPRE la facoltà di guida.', 'Droghe = Guida sempre compromessa. ''Non'' è la trappola!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24845, 'Come abbiamo visto nella domanda 24841, l''hashish e la marijuana alterano la percezione, i tempi di reazione e la capacità di giudizio. Guidare sotto il loro effetto è pericoloso. Quindi, la frase che dice ''non compromette'' la facoltà di guida è FALSO.', 'Anche qui, la parola trappola è ''non''. È l''opposto della verità. Qualsiasi droga compromette la guida.', 'Droghe (leggere o pesanti) = Guida sempre a rischio. ''Non'' è sbagliato!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24846, 'Mangiare troppo e cibi pesanti prima di guidare non è una buona idea. Il corpo deve lavorare molto per digerire, e questo può farti sentire stanco o assonnato, rendendoti meno attento alla strada.', 'La parola ''sconsigliata'' significa che è meglio non farlo. Non è un divieto assoluto, ma un forte consiglio per la tua sicurezza.', 'Pancia piena, attenzione meno buona.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24847, 'Quando mangi cibi difficili da digerire, il tuo corpo usa molta energia per questo processo. Questo può farti sentire meno sveglio, meno concentrato e più lento a reagire a quello che succede sulla strada. È pericoloso perché potresti non vedere un pericolo in tempo.', 'Le parole ''diminuzione dell''attenzione'' e ''aumento dei tempi di reazione'' indicano proprio i pericoli: sei meno attento e più lento a rispondere. ''Può provocare'' significa che è una possibilità concreta e da considerare seriamente.', 'Digestione difficile = guida difficile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24848, 'Questa affermazione è falsa. Anche se mangi un pasto abbondante, l''alcol, specialmente quello delle bevande superalcoliche, influisce sempre sulla tua capacità di guidare. Il cibo può rallentare un po'' l''assorbimento dell''alcol, ma non elimina i suoi effetti negativi sulla tua attenzione, sui riflessi e sulla capacità di giudizio.', 'La frase ''non compromette'' è la parola trappola principale. Significa ''non danneggia'', ma in realtà l''alcol danneggia sempre la guida. ''Superalcoliche'' sottolinea che il pericolo è ancora maggiore.', 'Alcol + guida = mai bene, anche a stomaco pieno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24849, 'L''alcool, anche in piccole quantità, può farti sentire più sicuro e meno preoccupato, ma questo è un effetto ingannevole. Ti fa sottovalutare i pericoli della strada, rendendoti meno attento e più propenso a prendere rischi. Per questo la risposta è VERO.', 'Le parole chiave sono ''euforia'' (sentirsi troppo bene e sicuri) e ''sottovalutazione del pericolo'' (non capire quanto sia rischioso).', 'Alcool = Falsa sicurezza, meno attenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24850, 'Guidare dopo aver bevuto troppo alcool è un reato grave. La legge prevede sanzioni molto severe, che possono includere multe salate, la sospensione o revoca della patente e, nei casi più gravi, anche l''arresto. Per questo la risposta è VERO.', 'La frase ''rischia l''arresto'' indica una delle conseguenze più serie previste dalla legge per chi guida in stato di ebbrezza.', 'Guida ubriaco = Rischio arresto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24851, 'Quando sei arrabbiato, triste, molto stressato o euforico, la tua mente non è completamente concentrata sulla guida. Le tue reazioni possono essere più lente o potresti prendere decisioni sbagliate. È sempre meglio aspettare di essere calmi e lucidi prima di mettersi al volante. Per questo la risposta è VERO.', 'La parola ''sconsigliabile'' significa che è meglio non farlo. ''Stato emotivo alterato'' si riferisce a quando le tue emozioni sono molto forti e ti distraggono.', 'Emozioni forti = Non guidare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24852, 'Anche se guidi un veicolo senza motore, come una bicicletta, sei comunque considerato un utente della strada. Se vieni trovato con un tasso alcolemico superiore al limite, sei soggetto alle stesse sanzioni previste per chi guida veicoli a motore, anche se le sanzioni sulla patente (se non ce l''hai) saranno diverse. Non c''è immunità! Per questo la risposta è FALSO.', 'La frase ''non è soggetto ad alcuna sanzione'' è la trappola. ''Alcuna'' significa ''nessuna'', e questo è sbagliato. La legge sull''alcool vale per tutti i conducenti di veicoli, anche quelli senza motore.', 'Alcool = Sanzioni per tutti i veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24853, 'L''alcool rallenta il cervello e il corpo. Questo significa che i tuoi tempi di reazione diventano più lenti, non più rapidi. Ci metti più tempo a vedere un pericolo e a reagire, ad esempio frenando o sterzando. Per questo la risposta è FALSO.', 'La parola ''più rapidi'' è la trappola. L''alcool fa esattamente il contrario: rende i tempi di reazione ''più lenti''.', 'Alcool = Reazioni lente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24854, 'Sì, è vero. La legge italiana (il Codice della Strada e il Codice Penale) ti obbliga a fermarti e prestare soccorso se vedi un incidente con feriti. Non farlo è un reato chiamato ''omissione di soccorso''.', 'La frase ''obbligatorio per legge'' è il punto chiave. Non è una scelta, ma un dovere legale.', 'Ferito = Obbligo Legale!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24855, 'È vero. Un aiuto rapido, anche solo chiamare subito il 112 o il 118, può essere fondamentale per salvare la vita a una persona ferita gravemente. Ogni minuto conta!', 'La parola ''può'' indica una possibilità, che in questo caso è molto reale e importante.', 'Pronto Soccorso = Vita!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24856, 'Sì, è vero. Intervenire subito e in modo corretto (ad esempio, mettendo in sicurezza il luogo, coprendo il ferito per il freddo, o non spostandolo se non strettamente necessario) può evitare che la situazione peggiori e che il ferito subisca altri danni.', 'Anche qui, ''può evitare'' indica una possibilità concreta. ''Ulteriori danni'' significa danni in più rispetto a quelli iniziali.', 'Subito = Meno Danni!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24857, 'No, è falso. Soccorrere un ferito non è solo una questione di ''buona educazione'' o ''morale'', ma è un preciso obbligo imposto dalla legge. Se non lo fai, puoi avere problemi legali.', 'Le parole ''non è un obbligo imposto dalla legge'' e ''solo un dovere morale'' sono le trappole. La legge lo impone!', 'Non solo morale, ma LEGALE!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24858, 'No, è falso. L''obbligo di soccorso vale sempre quando ci sono feriti, non importa se l''incidente ti sembra grave o leggero. Non sei tu a dover giudicare la gravità, ma devi chiamare i soccorsi.', 'La parola ''solo'' è una trappola. Non spetta a te decidere la gravità dell''incidente per soccorrere.', 'Ferito = Soccorso, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24859, 'No, è falso. L''obbligo di soccorso è prioritario. Devi fare il possibile per soccorrere e, allo stesso tempo, segnalare l''incidente per evitare che si crei intralcio o altri pericoli. Non puoi non soccorrere per paura di bloccare il traffico.', 'La frase ''Non è obbligatorio'' è la trappola. L''intralcio va gestito, ma non è una scusa per non soccorrere.', 'Intralcio? Segnala, ma Soccorri!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24860, 'No, è falso. L''obbligo di soccorso è per tutti i cittadini, non solo per chi fa il medico o l''infermiere. Certo, loro hanno più competenze, ma il dovere di chiamare aiuto e, se possibile, prestare le prime cure è di tutti.', 'La parola ''solo'' è la trappola. L''obbligo è generale, non limitato a categorie professionali.', 'Tutti Soccorrono, non solo i Dottori!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24861, 'No, è falso. La tua sicurezza è importante, ma non annulla l''obbligo di soccorso. Devi agire con prudenza, mettere in sicurezza la zona se puoi, ma devi comunque chiamare i soccorsi e, se possibile e senza rischi, aiutare il ferito. Non puoi ignorarlo.', 'La frase ''Non è obbligatorio'' è la trappola. La sicurezza è fondamentale, ma non è una scusa per non agire affatto.', 'Sicurezza sì, ma Soccorso sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24862, 'Il primo soccorso ha come obiettivo principale quello di aiutare il ferito a rimanere in vita, usando azioni semplici e veloci, prima che arrivino i medici professionisti. È un aiuto immediato per le emergenze.', 'La frase ''cercare di mantenere in vita'' e ''semplici e immediati interventi'' descrive esattamente lo scopo del primo soccorso: agire subito per la sopravvivenza.', 'Primo soccorso = Salvare la vita subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24863, 'Il primo soccorso serve a dare assistenza al ferito nel miglior modo possibile, in attesa che arrivino i soccorsi medici specializzati. Non sostituisce il medico, ma è un ponte per la sua arrivo.', 'Le parole ''assistere il ferito, come meglio possibile'' e ''in attesa che arrivi il soccorso medico'' sono chiare e definiscono il ruolo temporaneo e di supporto del primo soccorso.', 'Primo soccorso = Aspettare i medici, aiutando.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24864, 'Quando si presta il primo soccorso, è fondamentale fare attenzione a non causare altri danni al ferito. Ad esempio, non bisogna spostarlo se non è strettamente necessario, per non peggiorare le sue condizioni.', 'La frase ''evitare, per quanto possibile, che il ferito subisca ulteriori danni'' è cruciale. Il principio è ''non nuocere''.', 'Primo soccorso = Non peggiorare la situazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24865, 'Nelle operazioni di primo soccorso, devi fare solo ciò che sai fare e che è sicuro. Non devi provare interventi che non conosci bene, perché potresti fare più male che bene al ferito.', 'La parte ''evitare che al ferito vengano praticati interventi sbagliati o dannosi'' sottolinea l''importanza di agire con conoscenza e prudenza, evitando improvvisazioni pericolose.', 'Primo soccorso = Solo interventi sicuri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24866, 'Il primo obiettivo del primo soccorso non è chiedere subito al ferito cosa è successo. La priorità è la sua salute e sicurezza. Le domande sull''incidente possono aspettare che la persona sia stabile.', 'La parola ''subito'' è la trappola. La priorità è salvare la vita, non raccogliere informazioni sull''incidente.', 'Primo soccorso = Prima la vita, poi le domande.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24867, 'Non bisogna spostare il ferito dal luogo dell''incidente ''in ogni caso''. Si sposta solo se c''è un pericolo immediato (es. incendio, crollo). Spostare una persona ferita senza necessità può causare danni gravi, specialmente alla colonna vertebrale.', 'La frase ''in ogni caso'' è la parola trappola. Spostare un ferito è quasi sempre sconsigliato, a meno di pericoli imminenti.', 'Primo soccorso = Non spostare, se non c''è pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24868, 'Non è vero che non si deve toccare il ferito prima dell''arrivo della polizia. Il primo soccorso è un dovere e va prestato immediatamente, senza aspettare l''arrivo di altre autorità.', 'Le parole ''non bisogna mai toccare'' e ''se non è ancora arrivata la polizia'' sono le trappole. Il soccorso è immediato e non dipende dalla presenza delle forze dell''ordine.', 'Primo soccorso = Aiuta subito, non aspettare nessuno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24869, 'Quando una persona ha una ferita che sanguina, è importante coprirla. Usare materiale pulito, come una garza sterile o un panno pulito, aiuta a fermare il sangue e a proteggere la ferita da sporco e germi. Questo è un gesto fondamentale di primo soccorso.', 'La frase ''quanto più possibile pulito'' significa che se non hai materiale sterile, va bene usare la cosa più pulita che trovi a portata di mano, l''importante è agire.', 'Copri e premi, il sangue fermi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24870, 'Se una ferita sanguina ed è sporca, ad esempio con della terra, è molto importante pulirla. Lavarla con acqua pulita aiuta a rimuovere lo sporco e a prevenire infezioni. Fai attenzione a non strofinare troppo forte.', 'Le parole ''quanto prima'' indicano l''urgenza di pulire la ferita per evitare che lo sporco causi problemi. ''Acqua pulita'' è essenziale, non usare acqua sporca.', 'Ferita sporca? Acqua pulita!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24871, 'Se vedi un oggetto (come un pezzo di vetro o un coltello) conficcato in una ferita, non devi mai toglierlo. Rimuovere l''oggetto potrebbe causare più danni, aumentare il sanguinamento o creare altre complicazioni. È meglio lasciare l''oggetto e aspettare l''arrivo dei soccorsi professionali.', 'La frase ''non bisogna toglierli'' è la chiave: è un divieto assoluto. ''Corpi estranei conficcati'' si riferisce a oggetti che sono penetrati nella pelle.', 'Oggetto conficcato? Non toccarlo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24872, 'Per fermare una ferita che sanguina, devi applicare pressione. Questo si fa ''tamponando'' la ferita, cioè premendo sopra con garze sterili o, se non le hai, con panni puliti. La pressione aiuta il sangue a coagulare e a fermarsi.', '''Tamponarla'' significa applicare una pressione diretta sulla ferita. Anche qui, ''garze sterili o panni puliti'' sottolinea l''importanza dell''igiene.', 'Sanguina? Tampona e premi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24873, 'Questa affermazione è falsa perché, come abbiamo visto, non si devono mai togliere i corpi estranei conficcati in una ferita. Togliere un oggetto potrebbe peggiorare la situazione, causando più dolore, più sangue o danni maggiori. Devi lasciare l''oggetto e coprire la ferita intorno ad esso, se possibile.', 'La parola ''subito'' rende l''azione ancora più sbagliata. ''Togliere subito gli eventuali corpi estranei'' è l''errore principale.', 'Corpi conficcati? Mai estrarre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24874, 'Se una persona è incosciente (cioè non risponde e non è sveglia), non devi mai darle da bere nulla, nemmeno acqua o tè. Potrebbe soffocare o il liquido potrebbe andare nei polmoni, causando gravi problemi. Aspetta sempre l''arrivo dei soccorsi.', 'La parola ''incosciente'' è la chiave. Una persona incosciente non può deglutire in modo sicuro. ''Dargli da bere'' è un errore grave in questa situazione.', 'Incosciente? Niente bocca!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24875, 'Questa affermazione è falsa. Non coprire una ferita sanguinante è sbagliato. Coprire la ferita e applicare pressione è il modo corretto per aiutare a fermare il sanguinamento e proteggere la ferita. Lasciarla scoperta non ''facilita l''arresto spontaneo'', ma aumenta il rischio di infezioni e di perdita di sangue.', 'La frase ''non bisogna coprirla'' è l''errore. Il motivo ''per facilitare l''arresto spontaneo'' è una giustificazione sbagliata.', 'Ferita aperta? Copri e proteggi!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24876, 'Questa affermazione è falsa. Versare acqua calda su una ferita sanguinante non serve a fermare il sangue e potrebbe addirittura peggiorare la situazione, causando ustioni o aumentando il dolore. Per fermare il sanguinamento si usa pressione e materiale pulito, non acqua calda.', 'La combinazione ''acqua calda'' e ''per fermare il sanguinamento'' è completamente sbagliata. L''acqua calda non ha questa proprietà nel primo soccorso.', 'Acqua calda? Mai sulla ferita!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24877, 'In caso di un''abbondante emorragia esterna, è fondamentale agire subito. Tamponare la ferita significa fare pressione per fermare il sangue. Chiamare i soccorsi è essenziale per un aiuto professionale. Entrambe le azioni sono corrette e necessarie.', 'Le parole ''bisogna'' e ''subito'' indicano l''urgenza e la necessità di queste azioni.', 'Tampona e Chiama: le prime due azioni!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24878, 'Per tamponare correttamente una ferita con emorragia, devi fare pressione direttamente sulla ferita. Usare materiale pulito o, se possibile, sterile, aiuta a prevenire infezioni. Questa è la procedura corretta di primo soccorso.', 'La frase ''facendo pressione con del materiale pulito o possibilmente sterile'' spiega il modo corretto di tamponare. ''Possibilmente'' significa che se non hai materiale sterile, va bene anche pulito.', 'Pressione pulita per fermare il sangue.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24879, 'L''obiettivo principale in caso di emorragia abbondante è fermare la perdita di sangue. ''Arrestare la fuoriuscita del sangue'' è esattamente ciò che si deve fare per salvare la vita dell''infortunato.', 'La frase ''bisogna cercare di arrestare'' sottolinea l''importanza di questa azione come priorità assoluta.', 'Stop al sangue, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24880, 'Mettere il ferito in una posizione comoda (seduta o sdraiata) aiuta a mantenerlo calmo, a ridurre lo shock e a gestire meglio la situazione in attesa dei soccorsi. È una buona pratica di primo soccorso.', 'La frase ''è opportuno, se possibile'' indica che è un consiglio utile, ma non sempre fattibile in ogni situazione. L''importante è non peggiorare la situazione.', 'Posizione comoda, attesa calma.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24881, 'In caso di emorragia abbondante, ''solo medicare la ferita'' non è sufficiente. Prima di tutto bisogna fermare il sangue (tamponare con pressione) e chiamare i soccorsi. La medicazione è un passo successivo, non l''unico e non il primo.', 'La parola ''solo'' è la trappola. Indica che è l''unica cosa da fare, il che è sbagliato in una situazione di emergenza grave come un''emorragia abbondante.', '''Solo'' è quasi sempre FALSO in primo soccorso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24882, 'Far camminare una persona con un''emorragia abbondante è molto pericoloso. Il movimento può aumentare la perdita di sangue, peggiorare lo stato di shock o causare svenimenti. L''infortunato deve rimanere fermo.', 'La frase ''far camminare l''infortunato'' è l''azione sbagliata e pericolosa. Il ferito deve stare a riposo.', 'Non muovere chi sanguina!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24883, 'Non è vero che non si può assolutamente dare acqua a un infortunato con emorragia esterna. Se la persona è cosciente e in grado di bere, piccole quantità d''acqua possono aiutarla a reidratarsi e a sentirsi meglio. La regola di non dare da bere è più legata a casi di incoscienza o interventi chirurgici imminenti.', 'La parola ''assolutamente'' è spesso una trappola nei quiz di primo soccorso. Non è una regola così rigida in questo caso.', '''Assolutamente'' spesso è FALSO. L''acqua, se cosciente, può aiutare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24884, 'Se un oggetto entra nell''occhio, è importante coprirlo (bendarglielo) per proteggerlo e non fare altro. Questo evita di peggiorare la situazione prima che arrivi un medico specialista.', 'La frase chiave è ''senza procedere ad altre manovre''. Significa che non devi cercare di togliere l''oggetto o fare altre cose che potrebbero danneggiare l''occhio.', 'Copri e non toccare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24885, 'È fondamentale dire all''infortunato di non toccare l''occhio. Se lo tocca, potrebbe spingere l''oggetto più a fondo o graffiare l''occhio, causando un danno maggiore.', 'La parte importante è ''non toccare l''occhio danneggiato''. Questa è la prima e più importante raccomandazione per evitare complicazioni.', 'Non toccare mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24886, 'Questa domanda riassume le azioni corrette: bendare l''occhio per proteggerlo e non toccarlo. Bisogna aspettare che un medico specialista (oculista) intervenga, perché solo lui sa come rimuovere l''oggetto in sicurezza.', 'Le parole ''evitando di toccarlo'' e ''fino all''intervento dello specialista'' sono cruciali. Sottolineano l''importanza di non agire da soli e di attendere un professionista.', 'Benda e aspetta il medico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24887, 'È assolutamente sbagliato cercare di togliere un corpo estraneo dall''occhio. Potresti causare lesioni gravi, come graffi alla cornea o spingere l''oggetto più in profondità. Solo un medico deve farlo.', 'Le parole ''sempre e comunque di toglierglielo'' sono una ''parola trappola''. In situazioni di primo soccorso, azioni assolute come ''sempre'' o ''mai'' sono spesso false se si riferiscono a interventi diretti e non professionali.', 'Non togliere mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24888, 'Non bisogna mai forzare una persona a tenere gli occhi aperti se ha un oggetto nell''occhio. Questo può causare più dolore e, se l''oggetto è appuntito, può provocare ulteriori lesioni mentre l''occhio si muove.', 'La parola ''costringerlo'' è la trappola. Non si deve mai forzare un infortunato a fare qualcosa che gli causa dolore o che potrebbe peggiorare la situazione.', 'Non forzare mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24889, 'Massaggiare la palpebra, anche delicatamente, è molto pericoloso. Potrebbe spostare l''oggetto, graffiare la superficie dell''occhio (cornea) o spingerlo più a fondo, causando danni permanenti.', 'Anche se dice ''delicatamente'', ''massaggiargli la palpebra'' è l''azione sbagliata. Non si deve mai massaggiare un occhio con un corpo estraneo.', 'Non massaggiare mai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24890, 'Questa affermazione è falsa perché, come abbiamo visto, bendare l''occhio ferito è una delle prime cose da fare. Serve a proteggerlo da ulteriori danni e a impedire all''infortunato di toccarlo.', 'La parola ''mai'' rende questa affermazione falsa. In realtà, bendare l''occhio è proprio quello che si deve fare per proteggerlo.', 'Benda sempre.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24891, 'Quando una persona è in stato di shock, il corpo non riesce a mandare abbastanza sangue a tutti gli organi, inclusa la pelle. Per questo motivo, la pelle diventa molto pallida e fredda al tatto.', 'Nessuna parola trappola evidente. La descrizione è diretta e corrisponde ai sintomi tipici.', 'Shock = pelle pallida e fredda.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24892, 'Sì, la presenza di sudore freddo, specialmente sulla fronte, è un altro segno comune dello stato di shock. Il corpo reagisce allo stress e alla mancanza di sangue con questa sudorazione anomala.', 'Nessuna parola trappola evidente. ''Sudore freddo'' è un sintomo chiave.', 'Shock = sudore freddo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24893, 'Questa domanda riassume più sintomi veri dello shock: i brividi (perché il corpo è freddo), la pelle molto pallida e la sudorazione fredda alla fronte. Sono tutti segnali che il corpo è in grave difficoltà.', 'Nessuna parola trappola evidente. La combinazione di sintomi è corretta.', 'Shock = brividi, pallore, sudore freddo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24894, 'Oltre alla pelle pallida e al sudore freddo, il cuore di una persona in shock batte più velocemente (frequenti battiti) per cercare di pompare più sangue e ossigeno agli organi vitali, compensando la situazione di emergenza.', '''Frequenti battiti del cuore'' significa che il cuore batte più velocemente del normale, un tentativo del corpo di compensare.', 'Shock = cuore veloce, pallore, sudore freddo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24895, 'Quando il cervello non riceve abbastanza ossigeno a causa dello shock, la persona può diventare confusa, disorientata e dire frasi o parole che non hanno senso. È un segno di alterazione delle funzioni cerebrali.', '''Può manifestarsi'' indica una possibilità, non una certezza, rendendo l''affermazione più plausibile. ''Senza senso'' descrive la confusione mentale.', 'Shock = anche confusione mentale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24896, 'FALSO. Nello stato di shock, la temperatura corporea tende a diminuire o a rimanere normale, e la pelle è fredda. Un forte aumento della temperatura è tipico della febbre, non dello shock.', 'La parola ''sempre'' è una parola trappola molto forte. In medicina, quasi nulla accade ''sempre''. Nello shock, la pelle è fredda, non calda.', '''Sempre'' è quasi sempre FALSO. Shock = pelle fredda, non calda.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24897, 'FALSO. Le ampie macchie scure sulla pelle non sono un sintomo tipico dello stato di shock. Nello shock, la pelle è pallida e fredda, non macchiata di scuro.', '''Ampie macchie scure'' non corrisponde ai sintomi visibili dello shock, che sono pallore e freddo.', 'Shock = pallore, non macchie scure.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24898, 'FALSO. Questo è l''esatto contrario dei sintomi dello shock. La pelle diventa pallida e fredda, non rossa e calda con vampate. Il colorito rosso e il calore sono segni di altre condizioni, non di shock.', '''Colorito rosso'' e ''forti vampate di calore'' sono l''opposto dei sintomi dello shock, che sono pallore e freddo.', 'Shock = pallore e freddo, non rosso e caldo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24899, 'Quando una persona è in stato di shock, è importante aiutarla a far arrivare più sangue al cervello. Metterla a terra e sollevare le gambe aiuta il sangue a fluire meglio verso la testa e il cuore.', 'La frase ''se possibile'' significa che se non riesci a sollevare le gambe per qualche motivo, non è un problema grave, ma è la cosa migliore da fare.', 'Shock = Gambe su, testa giù.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24900, 'Le persone in shock spesso sentono molto freddo e il loro corpo perde calore. Coprirle con una coperta, una giacca o qualsiasi cosa disponibile aiuta a mantenere la temperatura corporea e a farle sentire più al sicuro.', 'La frase ''come meglio possibile'' significa che devi usare quello che hai a disposizione in quel momento per coprire il ferito.', 'Shock = Copri e riscalda.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24901, 'Questa domanda ripete il concetto della prima. Distendere il ferito e sollevare le gambe è la posizione migliore per aiutarlo in caso di shock, perché favorisce il ritorno del sangue agli organi vitali.', 'La parola ''possibilmente'' ha lo stesso significato di ''se possibile'': è la cosa giusta da fare, ma se non riesci, non preoccuparti troppo.', 'Shock = Disteso e gambe su.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24902, 'È FALSO. Far camminare una persona in shock è molto pericoloso! Potrebbe svenire, cadere e farsi ancora più male, o peggiorare la sua condizione. Deve stare fermo e disteso.', 'La frase ''farlo camminare'' è la parola trappola. Mai far muovere un ferito in shock. Anche la motivazione ''per riattivargli la circolazione'' è sbagliata.', 'Shock = Non muovere, non camminare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24903, 'È FALSO. Mettere il ferito in posizione seduta è sbagliato. In questa posizione, il sangue fa più fatica ad arrivare al cervello, peggiorando lo shock. Deve stare disteso.', 'La frase ''posizione seduta'' è la trappola. La posizione corretta è sempre distesa, con le gambe sollevate.', 'Shock = Mai seduto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24904, 'È FALSO. Dare schiaffi a una persona in shock non serve a nulla e può solo spaventarla o farla stare peggio. Non è un modo per riattivare la circolazione del sangue.', 'La frase ''piccoli schiaffi'' è la trappola. Non si deve mai colpire un ferito. La motivazione ''per riattivargli la circolazione'' è falsa.', 'Shock = Non picchiare, non scuotere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24905, 'È FALSO. Dare alcolici a una persona in shock è molto pericoloso. L''alcol può peggiorare lo shock e causare altri problemi. Non dare mai da bere alcolici a un ferito, né acqua o cibo.', 'La parola ''superalcolici'' è la trappola. In generale, non si deve dare nulla da bere o mangiare a una persona in shock.', 'Shock = Niente alcol, niente da bere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24906, 'È vero. Se una persona è incosciente, la prima cosa da fare è controllare se respira. Mettere una mano sul torace o sull''addome aiuta a sentire i movimenti della respirazione e capire se la persona sta respirando.', 'La frase chiave è ''verificare se respira ancora''. È l''azione più importante e immediata da compiere per valutare le condizioni del ferito.', 'Incosciente = Controlla il respiro (torace/addome).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24907, 'È vero. Muovere un ferito incosciente è molto pericoloso, specialmente se potrebbe avere un danno alla schiena (colonna vertebrale). Se non sei assolutamente certo che non ci siano traumi, non devi muoverlo per non peggiorare la situazione. L''unica eccezione è se c''è un pericolo immediato (es. incendio).', 'La parola ''solo'' è una parola trappola che indica una condizione molto specifica e restrittiva. ''Se si è certi'' rafforza questa condizione: devi essere sicuro al 100%.', 'Incosciente = Non muovere, a meno di certezza no traumi schiena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24908, 'È vero. Se una persona incosciente ha difficoltà a respirare, potrebbe avere qualcosa che blocca il naso o la bocca (come vomito, sangue o la lingua stessa). È fondamentale liberare queste vie respiratorie per permetterle di respirare meglio e prevenire il soffocamento.', 'Le parole ''liberare subito'' indicano l''urgenza dell''azione. ''Eventuali ostruzioni'' si riferisce a qualsiasi cosa blocchi il passaggio dell''aria.', 'Incosciente + Fatica a respirare = Libera naso/bocca.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24909, 'È vero. Le condizioni di un ferito incosciente possono cambiare rapidamente. È fondamentale continuare a controllare come sta (se respira, se reagisce, il colore della pelle) fino a quando non arrivano i soccorsi professionali. Non devi mai lasciare il ferito da solo.', 'La frase ''controllare spesso'' sottolinea la necessità di un monitoraggio continuo. ''Fino all''arrivo dell''ambulanza'' indica la durata dell''azione di soccorso.', 'Incosciente = Monitora sempre fino ai soccorsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24910, 'È falso. Non si deve mai dare da bere o da mangiare a una persona incosciente, specialmente bevande alcoliche. Potrebbe soffocare (il liquido potrebbe andare nei polmoni) o le bevande potrebbero peggiorare la sua condizione. L''alcool è particolarmente dannoso in queste situazioni.', 'La parola ''somministrargli'' è importante: significa dare qualcosa. ''Bevande alcooliche'' è la parte che rende l''affermazione chiaramente falsa, ma in generale non si dà nulla da bere a un incosciente.', 'Incosciente = Niente da bere/mangiare (mai alcool!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24911, 'È falso. Non c''è alcun motivo per bloccare le mani a un ferito incosciente. Questa azione è inutile e potrebbe spaventarlo se si riprende, o causargli ulteriori lesioni se si agita. Bisogna mantenere la calma e non fare azioni non necessarie.', 'La frase ''bloccargli le mani'' descrive un''azione che non ha alcuna utilità nel primo soccorso e può essere dannosa.', 'Incosciente = Non bloccare, non legare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24912, 'È falso. Fasciare la testa a un ferito incosciente senza sapere se ci sono traumi specifici o emorragie può essere pericoloso. Potrebbe aumentare la pressione all''interno del cranio o nascondere lesioni importanti. Si interviene solo su ferite evidenti e sanguinanti, e con le tecniche corrette.', 'La frase ''fasciargli la testa'' è troppo generica e non è una procedura standard per un incosciente, a meno di ferite specifiche che richiedano una fasciatura.', 'Incosciente = Non fasciare la testa a caso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24913, 'È falso. Un ferito incosciente non va messo in posizione semiseduta. Questa posizione può essere pericolosa perché la lingua potrebbe ostruire le vie respiratorie o il vomito potrebbe essere inalato. La posizione corretta, se non si sospettano traumi alla colonna, è la posizione laterale di sicurezza, per evitare il soffocamento.', 'La frase ''posizione semiseduta'' è la parola trappola principale. È la posizione sbagliata per un incosciente.', 'Incosciente = Mai semiseduto, pensa alla posizione laterale di sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24914, 'Se una persona è cosciente e ha male al torace (gabbia toracica), metterla semi-seduta (cioè con la schiena un po'' sollevata) aiuta a respirare meglio. In questa posizione, il peso degli organi interni non preme sui polmoni, facilitando l''atto respiratorio.', 'La parola ''semi-seduto'' è importante: significa non completamente sdraiato, ma con la schiena leggermente alzata, per aiutare la respirazione.', 'Trauma toracico + cosciente = semi-seduto per respirare meglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24915, 'Se c''è una ferita visibile e profonda sul torace, è fondamentale fermare il sanguinamento. Comprimere la ferita con un panno pulito aiuta a ridurre l''emorragia e protegge la zona da sporco e infezioni, in attesa dei soccorsi.', 'Le parole ''comprimere subito'' indicano l''urgenza dell''azione. ''Panno pulito'' è essenziale per evitare di introdurre germi nella ferita.', 'Ferita profonda = comprimi subito con panno pulito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24916, 'Un trauma alla gabbia toracica può essere molto grave e le condizioni dell''infortunato possono cambiare rapidamente. È cruciale non lasciare mai sola la persona e continuare a darle assistenza (ad esempio, parlandole, controllando che respiri) finché non arrivano i professionisti del soccorso medico.', 'La frase ''fino all''arrivo del soccorso medico'' sottolinea la continuità e l''importanza dell''assistenza costante.', 'Trauma grave = assisti sempre fino ai soccorsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24917, 'Se una persona ha un trauma al torace, chiederle di fare respiri profondi può causare più dolore, peggiorare eventuali lesioni interne (come costole rotte) o rendere la respirazione ancora più difficile. È meglio che respiri normalmente, senza sforzo.', 'La trappola è ''profondi respiri''. In caso di trauma, lo sforzo respiratorio è dannoso e va evitato.', 'Trauma toracico = no respiri profondi, respira normalmente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24918, 'Mettere una persona con trauma toracico completamente distesa può rendere la respirazione più difficile, perché il diaframma e gli organi interni premono sui polmoni. La posizione semi-seduta è quella più indicata. La posizione con le gambe sollevate è utile per lo shock o svenimento, ma non è la migliore per chi ha difficoltà respiratorie a causa di un trauma al torace.', 'La frase ''posizione distesa, con le gambe sollevate'' è la trappola. Questa posizione non è adatta per chi ha un trauma toracico e difficoltà a respirare.', 'Trauma toracico = no disteso, sì semi-seduto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24919, 'Far stare una persona completamente in piedi o seduta dritta con un trauma toracico può essere molto pericoloso. Potrebbe svenire, cadere e peggiorare le sue condizioni. La posizione non influenza in modo significativo la fuoriuscita di sangue da una ferita interna. La priorità è la stabilità e la facilitazione della respirazione.', 'La trappola è ''farlo stare alzato''. Un infortunato grave non deve essere messo in piedi. Anche la motivazione ''per diminuire la fuoriuscita di sangue'' è errata in questo contesto.', 'Trauma toracico = non farlo stare alzato, pericolo di caduta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24920, 'Se una persona ha una frattura, non bisogna mai muovere l''arto rotto. Muoverlo può causare più dolore e peggiorare il danno. La cosa giusta è tenerlo fermo.', 'La frase ''non bisogna muovere'' è un divieto chiaro. Ricorda che in caso di frattura, la parola chiave è ''immobilità''.', 'Frattura? Non muovere!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24921, 'È fondamentale bloccare l''arto fratturato per evitare che si muova e causi ulteriori danni. Non devi fare altre manovre complicate, solo immobilizzare l''arto come puoi (ad esempio, con una stecca improvvisata o legandolo al corpo).', 'La parte ''senza procedere ad altre manovre'' significa che non devi fare cose complesse o che non sai fare. L''importante è bloccare.', 'Blocca l''arto, non fare l''eroe.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24922, 'Se la frattura ha causato una ferita aperta (ad esempio, l''osso è visibile), è molto importante coprirla con qualcosa di pulito. Questo serve a proteggere la ferita dai germi e prevenire infezioni.', 'La parola ''pulito'' è essenziale. Non usare mai materiale sporco per coprire una ferita.', 'Ferita aperta? Copri con pulito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24923, 'Dopo aver bloccato l''arto, devi osservare l''infortunato. Se mostra segni di shock (ad esempio, è pallido, sudato, ha freddo), devi attuare le misure anti-shock, come coprirlo con una coperta per tenerlo al caldo e sdraiarlo con le gambe leggermente sollevate.', 'La frase ''se necessario'' è importante: non tutti gli infortunati vanno in shock, ma devi essere pronto. ''Normali misure anti-shock'' si riferisce alle azioni base di primo soccorso.', 'Prima blocca, poi pensa allo shock.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24924, 'Far camminare una persona con una frattura è molto pericoloso. Aumenta il dolore, può peggiorare la frattura e causare danni maggiori. Non si deve mai fare.', 'Le parole ''cercare di farlo camminare'' e ''per diminuire il dolore'' sono completamente sbagliate. Camminare aumenta il dolore e il danno.', 'Frattura? Non camminare mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24925, 'Chiedere a un infortunato di muovere un arto fratturato è sbagliato. Provoca dolore inutile e può peggiorare la lesione. La valutazione del tipo di lesione spetta ai medici, non a te.', 'Le espressioni ''chiedergli di muoverli'' e ''per valutare il tipo di lesione'' sono azioni e motivazioni che non spettano al primo soccorritore.', 'Non muovere, non chiedere di muovere.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24926, 'Se un osso è uscito dalla pelle (frattura esposta), non devi mai cercare di rimetterlo a posto. Questo può causare infezioni gravi e danni ai tessuti. Devi solo coprire la ferita con materiale pulito e aspettare i soccorsi.', 'La frase ''cercare di riposizionarlo'' è un''azione assolutamente da evitare. È un compito per i medici specialisti.', 'Osso fuori? Non toccare, copri e aspetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24927, 'Non si deve mai dare alcol a un infortunato. Le bevande alcoliche possono peggiorare lo stato di shock, interferire con eventuali farmaci o rendere più difficile la diagnosi da parte dei medici.', 'La parola ''superalcolica'' indica una bevanda che non va mai data a un ferito, così come qualsiasi altra bevanda alcolica.', 'Ferito? Niente alcol!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24928, 'Se un ferito ha ancora fiamme addosso, la prima cosa da fare è spegnerle subito. Soffocarle con una coperta è un modo efficace per fermare il fuoco e prevenire ulteriori danni.', 'La frase chiave è ''residue fiamme'', che indica un pericolo attivo. ''Bisogna spegnerle'' è l''azione immediata e corretta.', 'Fiamme = Soffoca subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24929, 'È molto importante non togliere i vestiti che si sono attaccati alla pelle bruciata. Rimuoverli potrebbe causare più dolore e peggiorare la ferita, strappando la pelle danneggiata. Meglio aspettare i soccorsi.', 'La parola chiave è ''non togliere''. Indica un''azione da evitare per non fare ulteriori danni.', 'Vestiti attaccati = Non toccare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24930, 'L''acqua fredda (non ghiacciata) è un ottimo rimedio immediato per le ustioni. Aiuta a rinfrescare la zona, diminuire il dolore e limitare l''estensione del danno ai tessuti.', 'La frase ''acqua fredda'' è il consiglio pratico e corretto. ''Se possibile'' significa che è la cosa giusta da fare quando le condizioni lo permettono.', 'Ustione = Acqua fredda!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24931, 'Coprire le ustioni con un materiale pulito, e se possibile sterile, è fondamentale. Questo protegge la ferita da sporco e infezioni, e aiuta a mantenere la temperatura corporea del ferito.', 'Le parole ''materiale pulito, possibilmente sterile'' sono essenziali per una corretta gestione dell''ustione e per prevenire complicazioni.', 'Ustioni = Copri pulito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24932, 'È assolutamente FALSO! Aspettare che le fiamme si spengano da sole è estremamente pericoloso e può causare ustioni molto più gravi. Bisogna intervenire immediatamente per spegnerle.', 'La trappola è ''aspettare che si spengano da sole''. In caso di fiamme, l''intervento deve essere immediato, non passivo.', 'Fiamme = MAI aspettare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24933, 'È FALSO. Come abbiamo visto, togliere i vestiti attaccati alla pelle ustionata può peggiorare la ferita e causare più dolore. Non bisogna mai farlo, ma lasciare che siano i soccorritori a gestire la situazione.', 'La parola ''sempre'' è una trappola. Non è mai corretto togliere vestiti attaccati a ustioni. L''azione corretta è l''opposto.', 'Vestiti attaccati = MAI togliere!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24934, 'È FALSO. L''alcool non va mai usato sulle ustioni. Brucia e irrita la pelle già danneggiata, peggiorando la situazione e causando un dolore intenso. Per le ustioni si usa acqua fredda, non disinfettanti aggressivi.', 'La trappola è ''disinfettare con l''alcool''. L''alcool non è adatto per le ustioni e può fare più male che bene.', 'Ustioni = NO alcool!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24935, 'VERO. Dopo un incidente, la prima cosa da fare è mettere in sicurezza il luogo per evitare altri pericoli (ad esempio, altre auto che arrivano o incendi). Questo serve a proteggere sia te che gli infortunati.', 'La frase ''valutare bene la situazione, per proteggere gli infortunati da altri pericoli'' è fondamentale. Non ci sono vere e proprie parole trappola, ma è un principio base di sicurezza.', 'Prima la sicurezza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24936, 'VERO. Devi aiutare gli infortunati con quello che sai fare e puoi fare, ma non devi mai fare cose che solo un medico o un infermiere possono fare (come dare farmaci o fare manovre complesse).', 'La parte chiave è ''senza però prendere iniziative di specifica competenza medica''. Questo significa che devi aiutare, ma non devi improvvisarti medico.', 'Aiuta, ma non fare il dottore!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24937, 'VERO. Questa domanda ripete un concetto simile alle precedenti. Devi dare aiuto in base a quello che conosci e alle tue capacità, senza esagerare o fare cose che non sai gestire.', 'La frase ''secondo le proprie possibilità e conoscenze'' è la chiave. Indica il limite del tuo intervento.', 'Aiuta con ciò che sai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24938, 'FALSO. Chi è coinvolto in un incidente non deve mai allontanarsi subito, specialmente se ci sono feriti. È obbligatorio fermarsi, mettere in sicurezza il luogo e chiamare i soccorsi. Andarsene è un reato (omissione di soccorso).', 'Le parole ''sempre e subito'' e ''allontanarsi'' sono le trappole. Non devi mai allontanarti, ma fermarti e aiutare.', 'Non scappare, aiuta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24939, 'FALSO. Non devi solo aspettare i soccorsi senza fare nulla. Mentre aspetti, devi mettere in sicurezza il luogo, chiamare aiuto e, se puoi e sai come fare, dare un primo soccorso di base agli infortunati.', 'Le parole ''solo l''arrivo dei soccorsi, senza fare nulla'' sono la trappola. Non devi essere passivo, ma agire per quanto possibile.', 'Non stare fermo, agisci!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24940, 'FALSO. La prima cosa da fare non è chiedere nome e cognome. La priorità assoluta è mettere in sicurezza il luogo, chiamare i soccorsi e poi, se possibile, dare un primo aiuto. L''identificazione è importante, ma non è la prima cosa da fare in un''emergenza.', 'La frase ''la prima cosa che deve fare il soccorritore è identificare l''infortunato'' è la trappola. Le priorità sono sicurezza e soccorso, non l''identità.', 'Prima la vita, poi l''identità!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24941, 'FALSO. Se non sei un medico o un infermiere, non devi mai dare farmaci a una persona ferita. Potresti causare più danni, ad esempio se la persona è allergica o se il farmaco interagisce con altre medicine che prende.', 'La frase ''somministrare farmaci'' è la trappola. Dare medicine è una competenza medica specifica e non deve essere fatta da chi non è professionista.', 'Niente medicine, solo soccorso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24942, 'Lo stato di shock è una reazione grave del corpo a situazioni di stress intenso. Un dolore molto forte può stressare il corpo al punto da causare uno shock, perché il sistema nervoso e circolatorio reagiscono in modo anomalo.', 'La parola ''può'' indica una possibilità, non una certezza assoluta. Significa che il dolore forte è una delle cause possibili, non l''unica.', 'Dolore forte = shock possibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24943, 'Anche le emozioni molto intense, sia positive (come una gioia improvvisa ed eccessiva) sia negative (come una rabbia o paura estrema), possono alterare il funzionamento del corpo e portare a uno stato di shock. Il corpo reagisce allo stress emotivo come a uno stress fisico.', 'Anche qui, ''può essere causato'' sottolinea che le emozioni sono un fattore scatenante possibile, non l''unico. Non sottovalutare l''impatto delle emozioni sul corpo.', 'Emozioni estreme = shock possibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24944, 'Se una persona perde molto sangue, il cuore non ha abbastanza liquido da pompare in tutto il corpo. Questo significa che gli organi non ricevono abbastanza ossigeno e nutrienti, e il corpo va in shock per proteggersi, ma è una condizione molto pericolosa.', 'La ''forte perdita di sangue'' è una delle cause più comuni e dirette di shock (chiamato shock ipovolemico). È importante riconoscerla.', 'Poco sangue = poco ossigeno = shock.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24945, 'Un trauma è un danno fisico al corpo, come quello causato da un incidente o una caduta. Un trauma forte può causare dolore intenso, perdita di sangue, danni agli organi o altre lesioni che possono scatenare lo stato di shock.', 'Il ''forte trauma'' è un evento che spesso combina più cause di shock (dolore, perdita di sangue, ecc.).', 'Trauma = danno = shock.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24946, 'Questa affermazione è FALSA. Come abbiamo visto nella domanda 24943, le forti emozioni (gioia, rabbia, paura) possono assolutamente causare uno stato di shock. Dire che ''non può dipendere'' è sbagliato.', 'La parola ''non'' unita a ''può dipendere'' rende l''affermazione assoluta e quindi falsa. Le emozioni sono un fattore importante.', '''Non può'' è spesso FALSO per lo shock.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24947, 'Questa affermazione è FALSA. Come abbiamo visto nella domanda 24945, un trauma è una causa molto comune di shock. Dire che ''non si verifica mai'' è completamente sbagliato e pericoloso.', 'La parola ''mai'' è una parola trappola molto forte. Nei quiz di primo soccorso, le affermazioni che usano ''mai'' o ''sempre'' sono spesso false, perché ci sono quasi sempre delle eccezioni o possibilità.', '''Mai'' è quasi sempre FALSO per lo shock.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24948, 'Questa affermazione è FALSA. Come abbiamo visto nella domanda 24944, la perdita di sangue è una delle cause principali e più pericolose di shock. Dire che ''non si verifica mai'' è un errore grave.', 'Ancora una volta, la parola ''mai'' è la trappola. La perdita di sangue è una causa diretta e frequente di shock.', '''Mai'' è quasi sempre FALSO per lo shock.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24949, 'Questa affermazione è FALSA. Lo stato di shock è una condizione medica molto grave e rappresenta un pericolo enorme per la salute. Se non viene curato rapidamente, può portare a danni permanenti agli organi e persino alla morte.', 'La frase ''non rappresenta un pericolo'' è la trappola. Lo shock è sempre un''emergenza medica che richiede attenzione immediata.', 'Shock = PERICOLO grave.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24950, 'L''alcool può farti sentire più coraggioso o meno preoccupato, ma questo ti porta a guidare in modo pericoloso e senza pensare ai rischi. Per questo, la guida diventa meno sicura.', 'Le parole ''eccitazione'' e ''imprudenza'' sono importanti. Indicano che l''alcool può farti agire senza pensare alle conseguenze, il che è molto pericoloso al volante.', 'Alcool = Falsa sicurezza e imprudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24951, 'I riflessi sono la velocità con cui reagisci a qualcosa, come frenare o sterzare. L''alcool ti fa reagire più lentamente, quindi non riesci a intervenire in tempo se c''è un pericolo sulla strada.', 'La frase ''rallentare i riflessi'' è la chiave. Significa che il tuo corpo e la tua mente sono più lenti a rispondere, rendendo la guida molto rischiosa.', 'Alcool = Riflessi lenti, pericolo certo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24952, 'Anche se all''inizio l''alcool può sembrare che ti dia energia, dopo un po'' ti fa sentire molto stanco e assonnato. Guidare con sonno è pericolosissimo, come guidare bendati.', 'La parola ''sonnolenza'' è fondamentale. Ricorda che l''alcool non ti sveglia, ma alla fine ti rende più stanco e ti fa venire sonno.', 'Alcool = Sonno al volante, mai!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24953, 'Guidare richiede molta attenzione alla strada, ai segnali, agli altri veicoli e a tutto ciò che ti circonda. L''alcool ti impedisce di concentrarti bene, rendendo la guida molto pericolosa perché non vedi o non capisci i pericoli.', 'La frase ''modificare pericolosamente la capacità di concentrazione e attenzione'' è cruciale. Significa che l''alcool cambia in peggio la tua capacità di stare attento.', 'Alcool = Meno attenzione, più rischio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24954, 'Questa domanda ripete un concetto importante: l''alcool ti rende meno attento a quello che succede intorno a te mentre guidi. Non riesci a notare i pericoli o a reagire in tempo.', 'La frase ''far diminuire il livello di attenzione'' è chiara. ''Diminuire'' significa ridurre, quindi la tua attenzione cala.', 'Alcool = Attenzione giù.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24955, 'Falso! L''alcool non annulla la stanchezza, anzi, dopo un po'' ti fa sentire ancora più stanco e assonnato. Non rende la guida più sicura, ma molto più pericolosa.', 'Le parole ''più sicura'' e ''annulla la stanchezza'' sono le trappole. L''alcool non rende MAI la guida più sicura e non elimina la stanchezza, la aumenta.', 'Alcool NON annulla stanchezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24956, 'Falso! L''alcool non facilita la guida e non aumenta la concentrazione. Al contrario, la diminuisce, rendendo difficile guidare bene e in sicurezza.', 'Le frasi ''facilita la guida'' e ''aumentare la capacità di concentrazione'' sono le trappole. L''alcool fa l''esatto contrario di quello che dicono queste frasi.', 'Alcool MAI aumenta concentrazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24957, 'Falso! L''alcool non ti rende più vigile (cioè più sveglio e attento) o più attento. Ti rende meno reattivo e meno concentrato, quindi più pericoloso al volante.', 'Le parole ''facilita la guida'' e ''più vigili e attenti'' sono le trappole. L''alcool ha l''effetto opposto: ti rende meno vigile e meno attento.', 'Alcool MAI rende più attenti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24958, 'Falso! Guidare non è un gioco. L''alcool non rende la guida più sicura, ma molto più pericolosa. Non importa se ti senti più allegro, la sicurezza è la cosa più importante e l''alcool la mette a rischio.', 'Le parole ''più sicura'', ''più allegra'' e ''meno noiosa'' sono le trappole. Cercano di farti credere che l''alcool abbia effetti positivi, ma per la guida sono tutti negativi e pericolosi.', 'Guida = Serietà, non allegria da alcool.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24959, 'Falso! L''alcool non migliora la vista, anzi, può renderla meno chiara, farti vedere doppio o farti avere difficoltà a capire le distanze. Questo è molto pericoloso per guidare.', 'La frase ''migliora la vista'' è la trappola. L''alcool non ha nessun effetto positivo sulla vista, solo negativi.', 'Alcool = Vista peggiore, non migliore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24960, 'È VERO. Se sulla tua patente c''è scritto che devi usare gli occhiali o le lenti a contatto, allora sei obbligato a farlo ogni volta che guidi. È una condizione per la tua sicurezza e quella degli altri.', 'La frase chiave è ''se nella patente si trova indicato tale obbligo''. Questo è l''unico motivo per cui sei obbligato.', 'Patente dice ''sì'', occhiali ''sì''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24961, 'È VERO. Il codice armonizzato ''01'' sulla patente indica proprio l''obbligo di ''correzione della vista''. Quindi, se hai questo codice, devi usare occhiali o lenti a contatto mentre guidi.', 'Il ''codice armonizzato ''01'''' è un''informazione specifica che conferma l''obbligo di correzione della vista.', 'Codice ''01'' = Occhiali Obbligatori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24962, 'È VERO. Non importa se l''obbligo è scritto per intero (ad esempio ''obbligo di lenti'') o con un codice (come il ''01''). Se è presente sulla patente, devi rispettarlo.', 'Le parole ''per esteso o sotto forma di codice'' significano che qualsiasi modo sia indicato l''obbligo sulla patente, è valido.', 'Scritto o codice, se c''è l''obbligo, li metti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24963, 'È VERO. Questa domanda riassume le precedenti. La regola è semplice: se la tua patente indica che devi usare occhiali o lenti a contatto, allora devi farlo.', 'La condizione ''quando è indicato sulla patente'' è l''unica che conta per l''obbligo.', 'Patente comanda, tu obbedisci.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24964, 'È FALSO. L''obbligo di usare occhiali o lenti a contatto non dipende da un numero specifico di diottrie (come ''6 diottrie''). Dipende da quello che decide il medico durante la visita per la patente e da quello che viene poi scritto sul documento.', 'La parola ''solo'' e il riferimento a ''6 diottrie'' sono le trappole. L''obbligo non è legato a un valore preciso, ma alla prescrizione medica sulla patente.', 'Non è questione di diottrie, ma di patente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24965, 'È FALSO. L''obbligo di usare occhiali o lenti a contatto, se indicato sulla patente, vale sempre, a qualsiasi ora del giorno o della notte. Non è legato a orari specifici come quelli del tramonto o dell''alba.', 'La parte ''da mezz''ora dopo il tramonto del sole a mezz''ora prima del suo sorgere'' è una distrazione. Questi orari sono importanti per le luci del veicolo, non per gli occhiali.', 'Occhiali sempre, non solo di notte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24966, 'È FALSO. Se hai l''obbligo di usare occhiali o lenti a contatto, devi farlo sempre, non ''soltanto in caso di scarsa visibilità''. Il tuo problema di vista esiste sempre, non solo quando c''è nebbia o piove forte.', 'La parola ''soltanto'' è una trappola. L''obbligo è continuo, non limitato a condizioni di scarsa visibilità.', 'Visibilità buona o cattiva, se c''è l''obbligo, li metti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24967, 'È FALSO. L''obbligo di usare occhiali o lenti a contatto, se indicato sulla patente, vale su tutte le strade: in città, in autostrada, su strade extraurbane. Non è limitato solo ad alcuni tipi di strada.', 'La parola ''soltanto'' e il riferimento a ''autostrade e strade extraurbane principali'' sono le trappole. L''obbligo è generale, non specifico per tipo di strada.', 'Obbligo ovunque, non solo in autostrada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24968, 'Se hai causato un incidente e devi pagare i danni (obbligo civile), una volta che hai pagato o riparato il danno alla persona che lo ha subito, il tuo obbligo finisce. È come saldare un debito.', 'La frase ''si libera dall''obbligo'' significa che l''impegno di pagare finisce una volta che il risarcimento è stato effettuato.', 'Paga il danno = Obbligo civile finito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24969, 'Sì, le due persone coinvolte nell''incidente (chi ha causato il danno e chi lo ha subito) possono parlare e trovare un accordo su quanti soldi pagare o come riparare il danno. Non è sempre necessario andare in tribunale.', 'La parola ''può accordarsi'' indica la possibilità di trovare un''intesa amichevole, non un obbligo di seguire una procedura rigida.', 'Accordo tra le parti = Sempre possibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24970, 'Se hai causato un incidente e devi risarcire i danni agli altri, questo non ti impedisce di far riparare anche la tua macchina, se si è danneggiata. Sono due cose diverse: l''obbligo verso terzi e la gestione del proprio bene.', 'La frase ''il proprio autoveicolo'' si riferisce alla macchina di chi ha causato l''incidente. Il fatto che sia obbligato a risarcire non gli toglie il diritto di riparare la sua auto.', 'La tua auto è tua = Puoi ripararla.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24971, 'Sì, se sei coinvolto in un incidente e devi pagare i danni, puoi chiedere aiuto a un esperto (un consulente) che ti aiuti a gestire la situazione, i documenti e i rapporti con l''assicurazione o l''altra parte. È un tuo diritto.', 'La frase ''può farsi assistere'' indica la possibilità di ricevere aiuto professionale per gestire la pratica, non un obbligo.', 'Chiedi aiuto = È un tuo diritto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24972, 'L''obbligo di pagare i danni (responsabilità civile) non ha nulla a che fare con la patente di guida. Non puoi scegliere di farti togliere la patente invece di pagare i danni. Sono due tipi di sanzioni o conseguenze diverse.', 'La parola ''in alternativa'' è la trappola. Non c''è alternativa tra risarcimento civile e revoca della patente; sono conseguenze di natura diversa.', 'Patente e soldi = Non sono alternative.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24973, 'Pagare i danni (responsabilità civile) ti libera solo dall''obbligo di risarcire economicamente. Se l''incidente ha causato reati (come lesioni gravi o omicidio stradale), la responsabilità penale rimane e non sparisce pagando i soldi. Sono due tipi di responsabilità diverse.', 'La frase ''ogni forma di responsabilità penale'' è la trappola. Il pagamento copre solo la responsabilità civile, non quella penale, che riguarda i reati.', 'Paga i danni = Solo civile, non penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24974, 'Se sei responsabile di un incidente e hai commesso un reato (ad esempio, lesioni gravi o omicidio stradale), la legge ti punisce con le pene previste dal Codice Penale. Quindi, se c''è una responsabilità penale, ci sono anche le pene penali.', 'La parola ''penalmente'' indica che si è commesso un reato e quindi si è soggetti alle leggi del Codice Penale.', 'Penalmente = Pene del Codice Penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24975, 'Se sei responsabile di un incidente, devi pagare i danni che hai causato ad altre persone o alle loro cose. Questo pagamento si chiama ''risarcimento dei danni'' ed è la conseguenza della responsabilità civile.', 'La parola ''civilmente'' si riferisce all''obbligo di risarcire i danni economici o materiali causati.', 'Civilmente = Risarcimento danni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24976, 'Se hai causato un incidente perché non hai rispettato le regole della strada (ad esempio, sei passato con il rosso o andavi troppo veloce), oltre alle responsabilità penali e civili, riceverai anche le multe e le sanzioni previste dal Codice della Strada.', 'La frase ''qualora abbia violato norme del Codice della strada'' è importante: le sanzioni del CdS si applicano se c''è stata una violazione specifica.', 'Violazione CdS = Sanzioni CdS.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24977, 'Sì, se sei responsabile di un incidente grave o hai commesso infrazioni importanti, la tua patente può essere sospesa per un certo periodo. Questo significa che non potrai guidare per un po'' di tempo.', 'La frase ''può incorrere'' significa che è una possibilità, non una certezza. Dipende dalla gravità dell''incidente e delle infrazioni.', 'Incidente grave = Patente sospesa (possibile).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24978, 'In casi molto gravi, come incidenti con lesioni gravissime o omicidio stradale, la patente può essere revocata, cioè tolta definitivamente. Non potrai più guidare, a meno che tu non rifaccia tutti gli esami dopo un certo periodo.', 'Anche qui ''può incorrere'' indica una possibilità, ma la revoca è una misura più severa della sospensione, riservata ai casi più gravi.', 'Incidente gravissimo = Patente revocata (possibile).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24979, 'Dopo un incidente, le autorità possono chiedere di fare di nuovo gli esami (teoria e pratica) per verificare che tu sia ancora idoneo a guidare. Questa è la ''revisione della patente''.', 'Ancora una volta, ''può incorrere'' sottolinea che non è automatico, ma una possibilità. La ''revisione'' significa un controllo delle tue capacità di guida.', 'Incidente = Revisione patente (possibile).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24980, 'No, l''arresto preventivo (cioè essere arrestati subito e messi in carcere prima del processo) non avviene ''sempre''. Succede solo in casi molto gravi e specifici, non per ogni incidente stradale.', 'La parola ''sempre'' è una parola trappola molto forte. Raramente qualcosa è ''sempre'' vero in queste situazioni legali. Fai attenzione a termini assoluti.', '''Sempre'' = Attenzione! (Spesso FALSO).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24981, 'No, questa affermazione è falsa. Se la patente non viene sospesa o revocata, puoi continuare a guidare i veicoli per cui sei abilitato. Non c''è una regola che ti obbliga a guidare solo veicoli di categoria inferiore dopo un incidente.', 'La frase ''non può continuare... ma solo di categoria inferiore'' introduce una restrizione specifica che non esiste nella legge.', 'Nessuna regola su ''categoria inferiore''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24982, 'No, la revoca della patente è una misura molto grave e non succede ''in ogni caso''. Avviene solo per incidenti gravissimi o reati molto seri, non per qualsiasi responsabilità in un sinistro.', 'La frase ''in ogni caso'' è una parola trappola, simile a ''sempre''. Indica una certezza assoluta che è quasi sempre falsa quando si parla di sanzioni.', '''In ogni caso'' = Attenzione! (Spesso FALSO).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24983, 'Questa è falsa. Se hai violato le regole del Codice della Strada causando l''incidente, sei assolutamente soggetto anche alle sanzioni (multe, decurtazione punti, ecc.) previste dal Codice della Strada. Le responsabilità penali e civili si aggiungono, non sostituiscono, le sanzioni del CdS.', 'La negazione ''non è assoggettato'' rende falsa l''affermazione. Ricorda che le sanzioni del Codice della Strada si applicano se hai violato le sue norme.', 'Violazione CdS = Sanzioni CdS (anche con altre responsabilità).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24984, 'La responsabilità penale riguarda i reati, cioè le azioni gravi che la legge punisce con la prigione o multe pesanti. Se in un incidente ci sono solo danni alle cose (macchine, guardrail, ecc.) e nessuno si fa male, di solito non c''è un reato. Quindi, non c''è responsabilità penale, ma solo responsabilità civile (l''obbligo di pagare i danni).', 'La frase chiave è ''danni involontari alle sole cose''. ''Sole cose'' significa che non ci sono persone ferite, e questo è fondamentale per escludere la responsabilità penale.', 'Danni solo a cose = no penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24985, 'La responsabilità penale esiste solo se quello che è successo è considerato un reato dalla legge. Se l''incidente o l''azione non rientra nelle definizioni di reato (ad esempio, un piccolo incidente con solo danni materiali e nessuna infrazione grave), allora non c''è responsabilità penale.', 'La frase ''non sia considerato un reato'' è la definizione stessa di quando la responsabilità penale non si applica. È un concetto base del diritto.', 'No reato = no penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24986, 'La ''causa di forza maggiore'' è un evento imprevedibile e irresistibile che non si poteva evitare (ad esempio, un malore improvviso e imprevedibile del conducente, un fulmine che colpisce l''auto, un terremoto). Se l''incidente è causato da qualcosa che non potevi controllare o prevedere, non hai colpa e quindi non c''è responsabilità penale.', 'La frase ''causa di forza maggiore'' è la parola chiave. Indica un evento eccezionale e inevitabile che esclude la colpa del conducente.', 'Forza maggiore = non è colpa tua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24987, 'Prestare soccorso è un dovere morale e legale, e può attenuare (diminuire) la pena o evitare un''accusa aggiuntiva (omissione di soccorso), ma non elimina la responsabilità penale per l''incidente stesso se hai commesso un reato (ad esempio, lesioni gravi o omicidio stradale). Se hai causato un incidente grave, sei comunque responsabile penalmente, anche se hai aiutato la vittima.', 'La parola trappola è ''è esclusa''. Il soccorso non esclude la responsabilità penale, al massimo la attenua o evita un''altra accusa (quella di omissione di soccorso).', 'Soccorrere è un dovere, non una scusa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24988, 'Il risarcimento del danno (pagare per i danni) riguarda la responsabilità civile. La responsabilità penale riguarda i reati. Anche se paghi tutti i danni (responsabilità civile), se hai commesso un reato (ad esempio, lesioni gravi o omicidio stradale), la responsabilità penale rimane. Il risarcimento può influenzare la pena, ma non la elimina.', 'La frase ''ogni qualvolta'' è una parola trappola molto forte, significa ''sempre''. Non è vero che sempre il risarcimento esclude la responsabilità penale. Inoltre, ''risarcimento del danno'' è legato alla responsabilità civile, non penale.', 'Pagare non cancella il reato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24989, 'Questa domanda è simile alla precedente. L''assicurazione paga i danni (responsabilità civile) per conto tuo. Ma se hai commesso un reato (ad esempio, lesioni gravi o omicidio stradale), la responsabilità penale è personale e non può essere ''pagata'' o eliminata dall''assicurazione. L''assicurazione non ti toglie la responsabilità penale.', 'Le parole chiave sono ''è esclusa'' e ''impresa di assicurazione che risarcisca''. L''assicurazione gestisce il risarcimento civile, non la responsabilità penale. La responsabilità penale è personale.', 'L''assicurazione paga i danni, non i reati.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24990, 'La responsabilità penale sorge quando un incidente stradale causa ferite gravi a una persona. Questo perché causare lesioni gravi è considerato un reato dalla legge.', 'La frase ''lesioni gravi'' è la chiave. Non basta un piccolo graffio, ma un danno importante alla salute.', 'Lesioni gravi = reato penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24991, 'L''omicidio colposo significa causare la morte di una persona per sbaglio o per negligenza (senza volerlo). Questo è un reato molto grave e comporta sempre responsabilità penale.', 'Il termine ''omicidio colposo'' indica chiaramente un reato grave che porta a responsabilità penale.', 'Morte per sbaglio = reato grave.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24992, 'La responsabilità penale nasce quando si commette un reato. I reati sono descritti nel Codice Penale. Quindi, se un incidente viola una regola del Codice Penale (come causare lesioni gravi o la morte), c''è responsabilità penale.', 'Il ''Codice Penale'' è il libro delle leggi che definisce i reati. Se si viola una sua norma, si risponde penalmente.', 'Codice Penale = reato = penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24993, 'Non tutte le violazioni del Codice della Strada portano a responsabilità penale. Molte violazioni (come un divieto di sosta o un eccesso di velocità lieve) comportano solo sanzioni amministrative (multe, punti). La responsabilità penale sorge solo se la violazione del Codice della Strada causa un reato (es. lesioni gravi o morte).', 'La parola trappola è ''in ogni caso''. Non è vero che ogni violazione del Codice della Strada è un reato penale.', 'Non ''ogni caso'' del Codice della Strada è penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24994, 'La responsabilità penale riguarda i reati contro le persone o contro la sicurezza pubblica. La distruzione di un veicolo è un danno materiale (alle cose), che di solito comporta responsabilità civile (risarcimento), non penale, a meno che non sia collegato a un reato contro persone.', 'La frase ''veicolo vada completamente distrutto'' si riferisce solo a un danno materiale. I danni materiali non sono reati penali di per sé.', 'Danno al veicolo = civile, non penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24995, 'Non ''tutti i casi'' di danni alle persone o alle cose portano a responsabilità penale. Per le persone, solo se ci sono lesioni gravi o morte. Per le cose, quasi mai è penale, ma civile. Un piccolo graffio a una persona o un danno lieve a un''auto non portano a responsabilità penale.', 'La parola trappola è ''in tutti i casi''. Non è vero che ogni danno, anche minimo, porta a responsabilità penale.', 'Non ''tutti i casi'' di danno sono penali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24996, 'La responsabilità penale è personale. Significa che risponde solo chi ha commesso il reato (il conducente che ha causato l''incidente). Il proprietario del veicolo risponde per la responsabilità civile (pagare i danni) o per alcune sanzioni amministrative, ma non per la responsabilità penale se non era lui a guidare.', 'La frase ''nei confronti del proprietario del veicolo'' è la trappola. La responsabilità penale è sempre del conducente, non del proprietario, a meno che il proprietario non fosse anche il conducente.', 'Penale = chi guida, non chi possiede.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24997, 'VERO. La responsabilità civile significa che se causi un incidente, devi pagare per i danni. Questi danni possono essere sia alle persone (per esempio, ferite) sia alle cose (per esempio, la macchina o altri oggetti danneggiati).', 'La frase chiave è ''sia alle persone che alle cose''. Questo significa che la responsabilità civile copre entrambi gli aspetti, non solo uno.', 'Civile = Persone + Cose.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24998, 'VERO. In caso di incidente, la responsabilità civile ricade sia su chi guidava il veicolo (il conducente) sia su chi ne è il proprietario. Questo perché il proprietario è responsabile del suo veicolo, anche se non lo guidava lui al momento dell''incidente.', 'Attenzione alla congiunzione ''e''. Significa che la responsabilità è di entrambi, non solo di uno dei due.', 'Responsabili: Guida + Possiede.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (24999, 'VERO. Se sei civilmente responsabile di un incidente, hai l''obbligo, cioè il dovere, di pagare per i danni che hai causato. Questo pagamento si chiama ''risarcimento''.', 'La parola ''obbliga'' è importante: significa che non è una scelta, ma un dovere legale.', 'Responsabilità = Obbligo di risarcire.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25000, 'VERO. Ci sono diversi tipi di responsabilità: civile (pagare i danni), penale (se hai commesso un reato, come lesioni gravi) e amministrativa (se hai violato il Codice della Strada, come eccesso di velocità). Anche se un incidente può causare tutte e tre, sono considerate separate e indipendenti l''una dall''altra.', 'La parola ''indipendente'' è fondamentale. Significa che ogni tipo di responsabilità ha le sue regole e conseguenze, anche se possono derivare dallo stesso evento.', 'Civile, Penale, Amministrativa: Ognuna per sé.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25001, 'VERO. Il principio fondamentale della responsabilità civile è che chi causa un danno a un altro deve ripararlo, cioè risarcirlo. Non importa l''entità del danno, l''importante è che sia stato causato.', 'La frase ''ogni danno causato deve essere risarcito'' sottolinea che non ci sono eccezioni per la natura del danno.', 'Danno causato = Danno risarcito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25002, 'FALSO. Se una persona muore a causa di un incidente, la responsabilità civile non scompare. I danni (come le spese funerarie o il mancato guadagno per la famiglia) devono comunque essere risarciti agli eredi della persona deceduta.', 'La parola ''esclusa'' è la trappola. La responsabilità non è mai esclusa in questi casi, anzi, può diventare ancora più complessa.', 'Morte non cancella il debito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25003, 'FALSO. Come abbiamo visto, la responsabilità civile copre sia i danni alle persone (lesioni, morte) sia i danni alle cose (veicoli, proprietà). Non si limita ''solo'' alle cose.', 'La parola ''sole'' (solo) è la trappola. La responsabilità civile è più ampia e include anche le persone.', 'Non solo cose, anche persone!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25004, 'FALSO. Anche un danno piccolo, di ''lieve entità'', deve essere risarcito. Non esiste una soglia minima al di sotto della quale la responsabilità civile non si applica.', 'Le parole ''esclusa'' e ''lieve entità'' sono le trappole. Ogni danno, per quanto piccolo, comporta una responsabilità.', 'Ogni danno, anche piccolo, va risarcito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25005, 'FALSO. La responsabilità civile (cioè l''obbligo di risarcire il danno) rimane la stessa. Quello che cambia, se non hai l''assicurazione, è che dovrai pagare tu direttamente tutti i danni di tasca tua, senza l''aiuto dell''assicurazione. Non è la responsabilità ad essere ''aggravata'', ma le conseguenze economiche per te.', 'La parola ''aggravata'' è la trappola. La responsabilità non aumenta, ma le conseguenze economiche per il responsabile diventano molto più pesanti.', 'Senza assicurazione: paghi tu, non è ''più'' responsabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25006, 'FALSO. L''impresa assicuratrice paga i danni fino a un limite massimo stabilito nel contratto, chiamato ''massimale''. Se i danni sono superiori a questo massimale, la parte che eccede il massimale deve essere pagata dal responsabile dell''incidente (il conducente o il proprietario del veicolo).', 'La parola ''anche'' è la trappola. L''assicurazione paga ''fino a'' un certo limite, non ''oltre'' o ''anche per'' danni superiori.', 'Assicurazione = Fino al massimale. Il resto lo paghi tu.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25007, 'L''assicurazione RCA (Responsabilità Civile Auto) serve proprio a coprire i danni che il tuo veicolo può causare ad altri. Questo include anche i passeggeri che trasporti, a patto che il veicolo sia autorizzato a trasportare persone (come un''auto normale). Quindi, se un passeggero subisce un danno mentre è a bordo, l''assicurazione lo copre.', 'La frase ''se il veicolo è autorizzato al trasporto di persone'' è una condizione importante, ma non è una trappola. Significa semplicemente che se trasporti persone legalmente, sono coperte.', 'RCA = copre i passeggeri (se il trasporto è legale).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25008, 'L''assicurazione RCA è obbligatoria proprio per questo motivo: coprire i danni che il tuo veicolo può causare a persone o cose che si trovano in luoghi pubblici (come strade, piazze) o aperti al pubblico (come parcheggi di supermercati). È la sua funzione principale.', 'Non ci sono parole trappola evidenti. ''Aree pubbliche o aperte al pubblico'' definisce bene il campo di applicazione dell''assicurazione.', 'RCA = copre danni a terzi in luoghi pubblici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25009, 'Il risarcimento diretto è una procedura più veloce per ottenere i soldi dopo un incidente. Si applica quando ci sono danni al tuo veicolo e, se il conducente si è fatto male, le sue ferite devono essere ''di lieve entità'', cioè non gravi. Se le ferite sono gravi, la procedura è diversa.', 'La frase ''lesioni di lieve entità'' è fondamentale. Se le lesioni fossero gravi, il risarcimento diretto non si applicherebbe.', 'Risarcimento diretto = danni auto + piccole ferite.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25010, 'La procedura di risarcimento diretto è pensata per incidenti semplici. Se ci sono più di due veicoli coinvolti in un incidente, la situazione diventa più complessa e non si può usare il risarcimento diretto. In quel caso, si segue la procedura normale.', 'La condizione ''più di due veicoli coinvolti'' è la chiave. Se sono due o meno, si può fare il risarcimento diretto.', 'Risarcimento diretto = massimo 2 veicoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25011, 'Questa affermazione è falsa. Il risarcimento diretto non è escluso se c''è un motociclo coinvolto. Anche i motocicli sono veicoli e possono rientrare nella procedura di risarcimento diretto, purché siano rispettate le altre condizioni (ad esempio, non più di due veicoli coinvolti e lesioni di lieve entità).', 'La parola ''escluso'' è la trappola. Non è vero che i motocicli sono sempre esclusi.', 'Moto = veicolo, quindi risarcimento diretto possibile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25012, 'Questa affermazione è falsa. Le fotografie sono molto utili e consigliate per dimostrare i danni e facilitare la pratica, ma non sono ''obbligatoriamente'' richieste dalla legge per presentare la richiesta di risarcimento diretto. Puoi fare la richiesta anche senza foto, anche se è meno facile dimostrare i danni.', 'La parola ''obbligatoriamente'' è la trappola. Le foto sono utili, ma non un obbligo legale.', 'Foto utili, ma non obbligatorie.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25013, 'Questa affermazione è falsa. L''assicurazione obbligatoria RCA copre i danni subiti da tutti i terzi trasportati legalmente, non ''solo'' quelli sui taxi. Copre i passeggeri di qualsiasi veicolo autorizzato al trasporto di persone, come un''auto privata, un autobus, ecc.', 'La parola ''solo'' è la trappola. Restringe troppo il campo di applicazione dell''assicurazione, rendendo l''affermazione falsa.', 'RCA = tutti i passeggeri, non solo taxi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25014, 'Quando si parla di ''responsabilità civile'', significa che se c''è un incidente e qualcuno subisce un danno (ad esempio, la macchina si rompe o una persona si fa male), sia chi guidava (il conducente) sia chi possiede la macchina (il proprietario) possono essere chiamati a pagare i danni. Entrambi sono responsabili in questo caso.', 'La parola chiave è ''responsabilità civile''. Ricorda che questa riguarda il risarcimento dei danni economici e coinvolge sia il conducente che il proprietario.', 'Civile = Conducente + Proprietario.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25015, 'La ''responsabilità penale'' è diversa. Riguarda reati più gravi, come causare lesioni gravi o la morte di una persona. In questi casi, la legge punisce solo la persona che ha commesso l''azione, cioè chi era alla guida e ha causato il reato. Il proprietario del veicolo non è responsabile penalmente se non era lui a guidare.', 'La parola chiave è ''responsabilità penale''. Questa è sempre personale, quindi riguarda solo chi ha commesso il reato (il conducente).', 'Penale = Solo Conducente (chi ha guidato).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25016, 'Se il proprietario di un veicolo riesce a dimostrare che la sua macchina è stata usata senza il suo permesso, ad esempio perché è stata rubata, allora non è responsabile per i danni causati da chi l''ha usata. In questo caso, la circolazione è avvenuta ''contro la sua volontà''.', 'La frase ''contro la sua volontà'' è fondamentale. Se il proprietario non voleva che la macchina circolasse (es. furto), non ha responsabilità.', 'Proprietario non responsabile se ''contro volontà'' (es. furto).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25017, 'Questa affermazione è falsa perché, come abbiamo visto, la ''responsabilità penale'' è sempre personale. Questo significa che solo la persona che ha commesso il reato (il conducente) può essere punita penalmente. Il proprietario del veicolo non può essere punito penalmente se non era lui alla guida e non ha commesso il reato.', 'Attenzione all''abbinamento ''responsabilità penale'' con ''proprietario''. La responsabilità penale non ricade mai sul proprietario se non era lui il conducente che ha commesso il reato.', 'Penale = MAI il proprietario (se non guidava).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25018, 'Questa affermazione è falsa. Quando ci sono ''danni alle cose'' (ad esempio, un''altra macchina o un palo), si rientra nella ''responsabilità civile''. Per la responsabilità civile, sono responsabili sia il conducente che il proprietario del veicolo. Quindi, non è ''solo'' il conducente a essere responsabile.', 'La parola trappola è ''solo''. I danni alle cose rientrano nella responsabilità civile, che coinvolge sia il conducente che il proprietario, non solo uno dei due.', 'Danni a cose = Responsabilità civile = Conducente + Proprietario (non ''solo'' conducente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25019, 'È assolutamente vietato guidare un veicolo su strade pubbliche se non ha l''assicurazione. L''assicurazione è obbligatoria per legge per proteggere te e gli altri in caso di incidente.', 'La parola ''vietato'' significa ''non permesso''. ''Privo di copertura assicurativa'' significa ''senza assicurazione''.', 'Senza assicurazione, non si guida!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25020, 'Se la tua assicurazione auto è scaduta, non puoi né guidare (circolare) né lasciare l''auto parcheggiata (in sosta) sulle strade pubbliche. Se lo fai, riceverai una multa (sanzione).', '''Scaduta di validità'' significa che non è più valida. ''Si incorre in una sanzione'' significa che si riceve una multa. ''Circola o si lascia in sosta'' include sia il movimento che la fermata.', 'Assicurazione scaduta = multa, anche da fermo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25021, 'Se ti fermano con l''assicurazione scaduta, oltre alla multa, la tua auto può essere sequestrata e, in casi gravi, anche confiscata. Confiscare significa che lo Stato ti toglie l''auto in modo definitivo.', '''Confisca del veicolo'' è una conseguenza molto grave: perdi la proprietà dell''auto.', 'Assicurazione scaduta = auto a rischio confisca.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25022, 'Falso! Non puoi usare il veicolo per nessun tragitto, nemmeno breve, se l''assicurazione è scaduta. La legge lo vieta sempre, non importa quanto sia corto il percorso.', 'La frase ''solo per brevi tragitti'' è la trappola. Non c''è nessuna eccezione per la lunghezza del viaggio.', 'Assicurazione scaduta = stop totale, non importa il tragitto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25023, 'Falso! Non puoi usare il veicolo in nessun luogo, né in Italia né all''estero, se l''assicurazione è scaduta. Il divieto è generale.', 'La frase ''solo sul territorio italiano'' è la trappola. Il divieto è valido ovunque.', 'Assicurazione scaduta = stop ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25024, 'Falso! Non puoi lasciare il veicolo parcheggiato (in sosta) sulle strade pubbliche se l''assicurazione è scaduta. Anche se l''auto è ferma, è una violazione della legge.', 'La frase ''è possibile lasciare il veicolo in sosta'' è la trappola. Non è possibile.', 'Assicurazione scaduta = via dalla strada, anche da fermo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25025, 'Falso! La scadenza dell''assicurazione non ha nulla a che fare con il ''collaudo tecnico'' (che è la revisione del veicolo). Se l''assicurazione è scaduta, devi rinnovare quella, non fare un collaudo. Sono due cose diverse.', '''Collaudo tecnico'' è la parola trappola. Non è una conseguenza della scadenza dell''assicurazione.', 'Assicurazione e collaudo sono due cose diverse.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25026, 'Falso! Non puoi usare il veicolo se l''assicurazione è scaduta, anche se dici di voler pagare i danni di tasca tua. La legge lo vieta per proteggere tutti, perché non è detto che tu abbia i soldi per coprire danni molto gravi.', 'La frase ''solo se si è disposti a pagare personalmente'' è la trappola. La legge non permette questa scelta personale.', 'Assicurazione scaduta = divieto assoluto, non è una scelta personale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25027, 'Il Fondo di Garanzia per le vittime della strada serve proprio a questo: se un veicolo causa un incidente e non ha l''assicurazione obbligatoria, il Fondo paga i danni alle persone coinvolte.', 'La frase chiave è ''non coperti da assicurazione''. Questa è una delle situazioni principali in cui il Fondo interviene.', 'Senza assicurazione, paga il Fondo (per le persone).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25028, 'Sì, è vero. Se un veicolo causa un incidente e scappa via senza essere identificato (il cosiddetto ''pirata della strada''), il Fondo di Garanzia interviene per risarcire i danni subiti dalle persone.', 'La parola ''non identificati'' è importante. Significa che non si sa chi ha causato l''incidente.', 'Pirata della strada? Paga il Fondo (per le persone).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25029, 'No, questo è falso. Il Fondo di Garanzia risarcisce i danni causati dall''incidente, ma non garantisce un ''vitalizio'', cioè una somma di denaro che viene pagata per tutta la vita. Il suo scopo è coprire le spese e i danni specifici dell''incidente.', 'La parola ''vitalizio'' è la trappola. Il Fondo non è una pensione o un''assicurazione sulla vita.', 'Il Fondo risarcisce, non pensiona.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25030, 'Falso. Il Fondo di Garanzia non è un ''premio'' per chi guida bene o non fa incidenti. È un sistema di protezione per le vittime di incidenti causati da veicoli che non hanno l''assicurazione o che non sono stati identificati.', 'La parola ''premio'' è la trappola. Il Fondo non premia, ma aiuta chi ha subito un danno.', 'Il Fondo non premia, ma protegge le vittime.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25031, 'Falso. Il Fondo di Garanzia non è una ''convenzione facoltativa'', cioè qualcosa che si può scegliere di avere o meno. È un sistema obbligatorio, previsto dalla legge, per dare una protezione minima alle vittime della strada in casi particolari.', 'La parola ''facoltativa'' è la trappola. Il Fondo è obbligatorio, non una scelta.', 'Il Fondo è obbligatorio, non a scelta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25032, 'Falso. Il Fondo di Garanzia non interviene in base all''età del conducente. Interviene se il veicolo che ha causato l''incidente non è assicurato o non è stato identificato. Se un minorenne causa un incidente con un veicolo regolarmente assicurato, paga l''assicurazione del veicolo, non il Fondo.', 'La frase ''conducenti minorenni'' è la trappola. L''età non è un criterio per l''intervento del Fondo.', 'Il Fondo guarda l''assicurazione, non l''età.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25033, 'Le polizze come furto, incendio, kasko, atti vandalici o eventi naturali sono assicurazioni facoltative, cioè non obbligatorie per legge. L''unica assicurazione obbligatoria è la Responsabilità Civile Auto (RC Auto), che copre i danni che potresti causare ad altri.', 'La frase chiave è ''non sono obbligatorie''. Questo ''non'' è fondamentale per capire che si tratta di assicurazioni che puoi scegliere di fare o meno.', 'RC Auto SÌ, le altre NO (se non vuoi).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25034, 'L''assicurazione ti risarcisce sempre per il valore effettivo del veicolo al momento del danno. Non puoi ricevere più di quanto valeva l''auto quando è stata rubata o ha preso fuoco, perché l''assicurazione serve a coprire una perdita, non a farti guadagnare.', 'La parte importante è ''non può essere superiore''. Significa che c''è un limite massimo al risarcimento, che è il valore reale del veicolo.', 'Mai più del valore reale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25035, 'Se la tua auto viene rubata all''estero, devi fare subito denuncia alla polizia locale. Ma per far valere l''assicurazione italiana, devi poi ''ripetere'' la denuncia anche in Italia, ad esempio ai Carabinieri o alla Polizia di Stato, quando torni o tramite le procedure previste.', 'La parola ''ripetere'' indica che devi fare un secondo passaggio burocratico anche in Italia, oltre alla denuncia fatta all''estero.', 'Denuncia estera + Denuncia italiana = Assicurazione attiva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25036, 'Questa affermazione è falsa. L''assicurazione contro furto o incendio ti dà un risarcimento una tantum, cioè una somma di denaro per il valore del veicolo. Non ti garantisce una ''rendita vitalizia'', che sarebbe un pagamento regolare per tutta la vita, come una pensione.', 'La ''parola trappola'' è ''rendita vitalizia''. Questo tipo di rendita non c''entra nulla con le assicurazioni auto per furto o incendio.', 'Auto = risarcimento, non pensione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25037, 'Non è vero. Non c''è nessun obbligo di legge che ti imponga di avere un meccanismo staccabatteria automatico per poter fare un''assicurazione contro l''incendio. Potrebbe essere un dispositivo utile per la sicurezza, ma non è una condizione necessaria per stipulare la polizza.', 'La frase ''occorre che il veicolo sia munito'' è la parte da notare. ''Occorre'' significa ''è necessario'', ma in questo caso non lo è.', 'Nessun obbligo di staccabatteria per l''assicurazione incendio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25038, 'Anche questa affermazione è falsa. Non è obbligatorio avere un antifurto installato sul veicolo per poter stipulare una polizza contro il furto. Le compagnie assicurative potrebbero offrire sconti se hai un antifurto, ma non è una condizione indispensabile per fare l''assicurazione.', 'Ancora una volta, ''occorre che il veicolo sia dotato'' è la frase chiave. Non è una condizione obbligatoria per l''assicurazione.', 'Antifurto non obbligatorio per l''assicurazione furto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25039, 'Questa affermazione è falsa e confonde i termini. Le polizze incendio coprono normalmente sia gli incendi accidentali (causati per sbaglio) sia quelli dolosi (causati intenzionalmente da terzi). Non coprono invece gli incendi dolosi causati dal proprietario stesso. La domanda dice l''esatto contrario, cioè che coprono ''solo'' quelli dolosi e ''non'' quelli accidentali, il che è sbagliato.', 'Le parole ''solo'' e ''non'' sono le trappole principali. La frase ''solo i danni causati da incendi dolosi... e non quelli provocati da incendi accidentali'' ribalta completamente la realtà.', 'Assicurazione = eventi casuali, non solo intenzionali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25040, 'VERO. I massimali sono l''importo massimo di denaro che la tua assicurazione si impegna a pagare per i danni che potresti causare in un incidente. Se il danno è più grande di questo importo, la parte extra la devi pagare tu.', 'La parola chiave è ''importi massimi''. Indica il limite di copertura dell''assicurazione.', 'Massimale = limite di pagamento dell''assicurazione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25041, 'VERO. La legge stabilisce un importo minimo obbligatorio per i massimali. Questo serve a garantire che le persone danneggiate in un incidente ricevano sempre un risarcimento adeguato, anche se il responsabile ha un''assicurazione ''base''.', 'Le parole ''cifra minima'' e ''stabilita dalla legge'' sono importanti. Significa che non puoi assicurarti con un massimale inferiore a quello imposto per legge.', 'C''è un minimo legale per i massimali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25042, 'VERO. Puoi scegliere di aumentare i massimali oltre il minimo stabilito dalla legge. Questo ti offre una maggiore protezione in caso di incidenti gravi, ma dovrai pagare un ''premio assicurativo'' (il costo dell''assicurazione) più alto.', 'Le frasi ''a scelta del cliente'' e ''pagando una maggiore somma di denaro'' sono fondamentali. Sottolineano la possibilità di personalizzare la polizza.', 'Più protezione (massimale), più costo (premio).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25043, 'FALSO. I massimali non sono i soldi che tu paghi all''assicurazione. I soldi che tu paghi ogni anno si chiamano ''premio assicurativo''. I massimali sono invece la somma massima che l''assicurazione paga a te o a terzi in caso di incidente.', 'La parola trappola è ''riscuote''. Confonde il ''premio'' (che paghi tu) con il ''massimale'' (che paga l''assicurazione in caso di danno).', 'Massimale = paga l''assicurazione. Premio = paghi tu.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25044, 'FALSO. I massimali non aumentano automaticamente ogni anno. Rimangono quelli che hai scelto o quelli minimi di legge, a meno che tu non decida di modificarli o che la legge non cambi i minimi obbligatori.', 'La frase ''aumentano ogni anno'' è la trappola. I massimali sono fissi per la durata del contratto, salvo tua richiesta o modifiche legislative.', 'I massimali non crescono da soli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25045, 'FALSO. I massimali non sono soldi che ti vengono restituiti. Sono un limite di copertura. Il ''premio assicurativo'' che paghi ogni anno è il costo del servizio di protezione e non viene restituito, anche se non fai incidenti.', 'La frase ''vengono restituiti'' è la trappola. L''assicurazione è un servizio di protezione, non un conto di risparmio.', 'L''assicurazione non restituisce soldi (né massimali, né premio).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25046, 'Questa affermazione è VERA. Il sistema ''bonus malus'' è proprio così: ogni anno il costo della tua assicurazione (il ''premio'') cambia. Se non fai incidenti, ricevi un ''bonus'' e paghi meno. Se invece causi incidenti, ricevi un ''malus'' e paghi di più. È un modo per premiare i guidatori prudenti.', 'La frase chiave è ''variazione annuale del premio di assicurazione, in base al numero di incidenti causati''. Questo descrive esattamente il funzionamento del ''bonus malus''.', 'Bonus Malus: meno incidenti = meno paghi; più incidenti = più paghi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25047, 'Questa affermazione è FALSA. La formula ''bonus malus'' si applica a tutti i veicoli a motore, quindi anche ai motocicli. Non è una cosa solo per le auto.', 'La parola ''non'' è la trappola qui. Il ''bonus malus'' si applica ANCHE ai motocicli. Non è un''esclusiva delle auto.', 'Bonus Malus: vale per auto E moto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25048, 'Questa affermazione è FALSA. Se causi più incidenti, il tuo premio assicurativo aumenterà molto (riceverai un ''malus''), ma il contratto non viene ''automaticamente annullato''. L''assicurazione continua, ma ti costerà di più. Solo in casi eccezionali o per gravi violazioni il contratto potrebbe essere interrotto, ma non ''automaticamente'' per un certo numero di incidenti.', 'Le parole ''automaticamente annullato'' sono la trappola. Il contratto non si annulla da solo, ma il costo aumenta.', 'Incidenti: premio sale, contratto resta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25049, 'Questa affermazione è FALSA. Il contratto di assicurazione, inclusa la formula ''bonus malus'', è un accordo tra te (l''assicurato) e la compagnia di assicurazione. Non è il giudice a stabilirlo. Il giudice interviene solo in caso di liti o problemi, non per creare il contratto.', 'La frase ''stabilito dal giudice'' è completamente sbagliata. Il contratto è un accordo privato tra le parti.', 'Contratto: tu e assicurazione, non giudice!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25050, 'VERO. L''assicurazione RCA è valida non solo in Italia, ma anche in tutti i Paesi dell''Unione Europea e in alcuni altri Stati che hanno accordi specifici. Questo significa che se fai un incidente, ad esempio, in Francia o in Germania, la tua assicurazione ti copre.', 'La parola ''anche'' è importante qui. Non limita la validità solo all''Italia, ma la estende ad altri Paesi.', 'RCA = Europa inclusa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25051, 'FALSO. L''assicurazione RCA copre la ''responsabilità civile'', cioè i danni economici che causi ad altri. Non copre la ''responsabilità penale'', che riguarda i reati (come lesioni gravi o omicidio stradale) e le relative conseguenze legali, come la prigione o multe penali. Queste sono personali e non assicurabili.', 'Attenzione a ''responsabilità penale''. La RCA è solo per la ''civile''. Anche ''in base al premio pagato'' è una distrazione, la responsabilità penale non è negoziabile con l''assicurazione.', 'RCA = Civile, non Penale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25052, 'FALSO. L''assicurazione RCA serve a risarcire i danni che causi a terzi. Le ''sanzioni amministrative pecuniarie'' sono le multe (ad esempio per eccesso di velocità o divieto di sosta) che devi pagare allo Stato per aver infranto una regola del Codice della Strada. Queste multe sono una tua responsabilità personale e non sono coperte dall''assicurazione.', 'La frase ''sanzioni amministrative pecuniarie'' è la parola chiave. Significa ''multe''. La RCA non paga le tue multe.', 'RCA = Danni, non Multe.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25053, 'FALSO. Ogni polizza RCA ha un ''massimale'', che è la cifra massima che l''assicurazione pagherà in caso di incidente. Se i danni causati sono superiori a questo massimale, la parte eccedente deve essere pagata da chi ha causato l''incidente (il conducente o il proprietario del veicolo).', 'La parola ''ogni'' è una trappola. Non copre ''ogni'' danno senza limiti. ''Anche se superiore al massimale'' è l''elemento che rende la frase falsa.', 'RCA ha un Massimale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25054, 'FALSO. L''assicurazione RCA copre sia la responsabilità del conducente (chi guida al momento dell''incidente) sia quella del proprietario del veicolo. Il proprietario è sempre responsabile del suo mezzo, a meno che non dimostri che il veicolo è stato usato contro la sua volontà (ad esempio, in caso di furto).', 'La parola ''solo'' è una trappola. La RCA non copre ''solo'' il conducente, ma anche il proprietario. ''Ma non quella del proprietario'' è l''errore.', 'RCA = Conducente + Proprietario.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25055, 'FALSO. L''assicurazione RCA è obbligatoria proprio per coprire i danni che il tuo veicolo può causare a ''terzi'', sia che si tratti di ''persone'' (lesioni fisiche) sia che si tratti di ''cose'' (danni ad altri veicoli, edifici, oggetti). Non serve un contratto separato per i danni alle cose.', 'La parola ''solo'' è una trappola. La RCA non copre ''solo'' i danni alle persone. La frase ''perché per i danni alle cose occorre un altro tipo di contratto'' è sbagliata.', 'RCA = Persone + Cose.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25057, 'Quando firmi il contratto di assicurazione R.C.A., la compagnia assicurativa è obbligata a darti un documento che prova che il tuo veicolo è assicurato. Questo documento si chiama ''certificato di assicurazione'' ed è molto importante.', 'La frase ''deve rilasciare'' indica un obbligo preciso per l''assicurazione, non una scelta.', 'Contratto RCA = Certificato obbligatorio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25059, 'Sì, in Italia, è obbligatorio per legge che ogni veicolo a motore abbia l''assicurazione per la responsabilità civile auto (R.C.A.). Senza questa assicurazione, non puoi circolare su strada.', 'La parte ''obbligatoria per legge'' è la chiave. Non è una scelta, ma una necessità legale.', 'RCA = Obbligo di legge.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25060, 'È fondamentale avere sempre con te il certificato di assicurazione quando guidi. Se ti fermano per un controllo, devi essere in grado di mostrarlo alle autorità.', 'La parola ''sempre'' è importante: significa che non devi mai dimenticarlo a casa quando usi il veicolo.', 'Certificato = Sempre in auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25061, 'L''impresa assicuratrice ti fornisce il contratto e il certificato di assicurazione, ma non è obbligata a darti un elenco di carrozzerie convenzionate. Puoi scegliere tu dove portare la tua auto in caso di incidente.', 'La frase ''deve rilasciare un elenco delle autocarrozzerie convenzionate'' è la parte sbagliata. L''assicurazione non ha questo obbligo.', 'RCA = Non elenco carrozzerie.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25062, 'L''assicurazione R.C.A. si occupa di coprire i danni in caso di incidente. Non è compito dell''assicurazione darti un libretto sul pronto soccorso; queste informazioni si imparano al corso di guida o in corsi specifici.', 'La frase ''deve rilasciare un libretto sulle nozioni di pronto soccorso'' è la parte trappola. Non è una responsabilità dell''assicurazione.', 'RCA = Non pronto soccorso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25063, 'L''assicurazione R.C.A. non ti fornisce un manuale su come evitare incidenti. Imparare a guidare in sicurezza e prevenire incidenti è qualcosa che si apprende a scuola guida e con l''esperienza.', 'La frase ''deve rilasciare un manuale su come evitare incidenti'' è la parte sbagliata. L''assicurazione non ha questo compito.', 'RCA = Non manuale incidenti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25064, 'L''assicurazione R.C.A. copre i danni causati dal veicolo, indipendentemente da chi lo sta guidando, purché la persona abbia la patente e non stia commettendo infrazioni gravi (come guidare ubriaco). Non è necessario che sia il proprietario a guidare.', 'La frase ''purché guidato dal proprietario'' è la parola trappola. L''assicurazione copre il veicolo, non solo il proprietario alla guida.', 'RCA = Copre il veicolo, non solo il proprietario.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25065, 'Tutti gli apparecchi elettrici (come la radio, le luci o il lunotto termico) hanno bisogno di energia per funzionare. Questa energia viene prodotta dal motore del veicolo, che per farlo deve bruciare più carburante. Quindi, più apparecchi elettrici usi, più carburante consumi.', 'La frase ''fanno aumentare'' indica una relazione diretta di causa-effetto. Ricorda che ogni cosa che ''prende'' energia dal veicolo, la prende dal motore, che a sua volta consuma carburante.', 'Elettricità accesa = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25066, 'Guidare a una velocità costante, senza accelerare o frenare spesso, aiuta il motore a lavorare in modo più efficiente. Quando il motore lavora in modo regolare, consuma meno carburante rispetto a quando deve cambiare continuamente regime per accelerazioni e frenate.', 'La parola chiave è ''costante''. Mantenere la velocità costante significa evitare sbalzi che fanno lavorare di più il motore.', 'Velocità costante = meno consumi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25067, 'Un veicolo più pesante ha bisogno di più forza per muoversi. Questa forza extra viene dal motore, che deve lavorare di più per spostare il peso aggiuntivo. Lavorando di più, il motore consuma una maggiore quantità di carburante.', 'La relazione ''aumenta con l''aumentare'' è diretta. Più peso c''è, più il motore fatica.', 'Più peso = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25068, 'Andare più piano, soprattutto se si evita di correre troppo, fa sì che il motore faccia meno sforzo. Un motore che lavora a un regime più basso e senza stress consuma meno carburante. È un modo semplice per risparmiare.', 'La parola ''opportunamente'' significa in modo giusto, non troppo poco o troppo. L''importante è ridurre la velocità in modo sensato.', 'Meno velocità = meno consumi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25069, 'Quando i finestrini sono aperti, l''aria entra nell''abitacolo e crea una resistenza aerodinamica. Questa resistenza è come una ''frenata'' invisibile che il motore deve vincere, specialmente quando vai veloce. Per vincere questa resistenza, il motore deve fare più sforzo e quindi consuma più carburante.', 'La frase ''specie quando si viaggia ad alta velocità'' è importante. A basse velocità l''effetto è minore, ma ad alta velocità diventa significativo.', 'Finestrini chiusi (ad alta velocità) = meno resistenza = meno benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25070, 'Su strade pianeggianti e senza curve strette o traffico, il motore può mantenere una velocità più costante e lavorare in modo più regolare. Questo riduce lo sforzo del motore e di conseguenza il consumo di carburante. Le salite e le continue frenate/accelerazioni aumentano i consumi.', 'La frase ''per quanto possibile'' indica che non è sempre fattibile, ma è la scelta migliore quando si può.', 'Strade facili = meno benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25071, 'Se le gomme non sono gonfiate alla giusta pressione (sono sgonfie), la parte dello pneumatico che tocca la strada è maggiore. Questo aumenta l''attrito (la ''frizione'') tra la gomma e l''asfalto. Per vincere questo attrito extra, il motore deve fare più forza e quindi consuma più carburante.', 'La frase ''insufficiente pressione di gonfiaggio'' è la causa del problema. Controlla sempre la pressione delle gomme!', 'Gomme sgonfie = più attrito = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25072, 'Mettere i bagagli sul tetto del veicolo ha due effetti negativi: primo, aumenta il peso totale del veicolo (e più peso significa più consumo, come visto nella domanda 25067); secondo, rende il veicolo meno aerodinamico, aumentando la resistenza all''aria. Entrambi questi fattori fanno aumentare il consumo di carburante.', 'La frase ''comporta un maggior consumo'' indica chiaramente un aumento. Non è mai un vantaggio per i consumi.', 'Bagagli sul tetto = più peso + più resistenza = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25073, 'Questa affermazione è FALSA. Proprio come i finestrini aperti, anche il tettuccio scorrevole aperto crea resistenza all''aria, specialmente quando si viaggia a velocità più elevate. Questa resistenza costringe il motore a lavorare di più per mantenere la velocità, aumentando il consumo di carburante, non diminuendolo.', 'La parola ''minor'' è la trappola. L''effetto è l''opposto: un ''maggior'' consumo.', 'Tettuccio aperto = come finestrini aperti = più resistenza = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25074, 'Questa affermazione è FALSA. Il climatizzatore è un apparecchio che consuma molta energia. Questa energia viene prodotta dal motore del veicolo, che deve lavorare di più per alimentarlo. Di conseguenza, l''uso del climatizzatore aumenta il consumo di carburante, non lo diminuisce.', 'Anche qui, la parola ''minor'' è la trappola. L''uso del climatizzatore comporta sempre un ''maggior'' consumo.', 'Climatizzatore acceso = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25075, 'Questa affermazione è FALSA. I veicoli ibridi sono stati progettati proprio per ridurre l''inquinamento e i consumi. Usano il motore elettrico a basse velocità o in città (dove si inquina di più con il motore a scoppio) e il motore a scoppio quando serve più potenza o per ricaricare la batteria. Questo sistema combinato ottimizza l''efficienza e riduce le emissioni inquinanti.', 'La frase ''inquinano di più'' è la trappola. L''obiettivo principale dei veicoli ibridi è proprio quello di inquinare ''di meno''.', 'Ibridi = meno inquinamento (non di più).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25076, 'Questa affermazione è FALSA. Come spiegato nella domanda 25072, collocare i bagagli sul tetto del veicolo aumenta sia il peso che la resistenza all''aria. Entrambi questi fattori fanno aumentare il consumo di carburante, non lo diminuiscono. Per consumare meno, i bagagli vanno messi nel bagagliaio o, se possibile, lasciati a casa.', 'La frase ''Per consumare meno carburante è opportuno collocare i bagagli sul tetto'' è una contraddizione. La seconda parte annulla la prima.', 'Bagagli sul tetto = più benzina (non meno).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25077, 'Questa affermazione è FALSA. Accelerare forte e frenare all''improvviso (guidare ''energeticamente'') fa lavorare il motore in modo molto inefficiente. Il motore consuma molta più benzina durante le accelerazioni brusche e l''energia della frenata viene sprecata. Per risparmiare carburante, è meglio guidare in modo fluido e costante, anticipando le situazioni.', 'La frase ''accelerare e frenare energicamente'' descrive un comportamento di guida che aumenta i consumi, non li diminuisce.', 'Guida aggressiva = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25078, 'È vero. La marmitta è il dispositivo che serve a ridurre il rumore del motore. Se non funziona bene, fa molto rumore. Per questo è importante controllarla.', 'La parola ''silenziatore'' ti aiuta a capire la funzione: serve a rendere silenzioso. ''Efficienza'' significa che funziona bene.', 'Marmitta sana, guida serena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25079, 'È vero. Usare il clacson o le trombe troppo spesso e senza necessità crea molto rumore, che è un tipo di inquinamento chiamato ''acustico''.', '''Eccessivo'' significa ''troppo''. I ''dispositivi di segnalazione acustica'' sono gli strumenti che fanno rumore per avvisare, come il clacson.', 'Clacson con misura, meno rumore in città.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25080, 'È vero. Frenare all''improvviso (''bruscamente'') può far fischiare le gomme o i freni, creando rumore. È meglio frenare dolcemente, a meno che non ci sia un pericolo reale (''strettamente necessario'').', '''Bruscamente'' significa ''all''improvviso, con forza''. ''Strettamente necessario'' significa ''solo se è proprio indispensabile''.', 'Frena dolce, guida in pace.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25081, 'È vero. Accelerare il motore quando il veicolo è fermo, senza motivo e più volte, produce rumore inutile e spreca carburante.', '''Inutilmente e ripetutamente'' sono le parole chiave: significa ''senza ragione e più volte''.', 'Motore fermo, gas non dare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25082, 'È vero. Il clacson è uno strumento di sicurezza. Va usato solo per avvisare di un pericolo immediato o in situazioni urgenti, come il trasporto di persone ferite o malate. Usarlo solo quando serve riduce il rumore.', '''Solamente per motivi di sicurezza stradale'' è la parte più importante. Gli esempi tra parentesi chiariscono quando è permesso.', 'Clacson solo per pericolo, mai per capriccio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25083, 'È falso. Mantenere il motore acceso e accelerare quando si è fermi nel traffico crea molto rumore e inquinamento. Se la sosta è lunga, è meglio spegnere il motore.', 'La frase ''mantenere il motore acceso, accelerando ripetutamente'' descrive proprio un comportamento che causa rumore, non che lo evita.', 'Traffico fermo, motore spento (o al minimo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25084, 'È falso. Chiudere le portiere con forza provoca un rumore forte e fastidioso. Bisogna chiuderle delicatamente.', 'La parola ''con forza'' è la trappola: chiudere con forza crea rumore, non lo evita.', 'Portiera chiusa piano, rumore lontano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25085, 'È falso. Non si può sostituire il clacson con le luci lampeggianti. Il clacson ha una funzione specifica di avviso sonoro, e le luci lampeggianti hanno altri scopi. Inoltre, la restrizione ''solamente di notte'' non ha senso.', '''Sostituire il clacson con le luci ad intermittenza'' è l''errore principale. Sono due dispositivi diversi con funzioni diverse.', 'Clacson è clacson, luci sono luci. Non si scambiano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25086, 'Il silenziatore, o marmitta, serve proprio a ridurre il rumore del motore. Se si rovina, non riesce più a fare il suo lavoro e quindi il rumore aumenta. È come un filtro che si rompe.', 'La frase ''man mano che si va rovinando'' significa che il rumore aumenta gradualmente, un po'' alla volta, mentre il silenziatore si danneggia.', 'Marmitta rovinata = più rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25087, 'Guidare in modo tranquillo, senza accelerare o frenare di colpo, fa lavorare il motore in modo più dolce. Questo riduce il rumore generale del veicolo. Le accelerazioni e frenate brusche, invece, fanno ''sforzare'' di più il motore e i freni, creando più rumore.', 'La parola ''si può diminuire'' indica che è possibile ridurre il rumore con una guida attenta, non che sia l''unico modo o che il rumore sparisca del tutto.', 'Guida dolce = meno rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25088, 'Questa affermazione è falsa perché il rumore di un veicolo non viene solo dal motore. Ci sono anche altri rumori, come quelli delle gomme sull''asfalto, dell''aria che sbatte contro la carrozzeria (specialmente ad alta velocità), dello scarico e a volte anche dei freni o della trasmissione.', 'La parola ''solo'' è una parola trappola molto comune nei quiz. Quando vedi ''solo'', ''sempre'', ''mai'', ''esclusivamente'', fai attenzione: spesso la risposta è FALSO perché ci sono quasi sempre più fattori o eccezioni.', 'Mai ''solo'' rumore dal motore! Ci sono anche gomme, aria, scarico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25089, 'Per ridurre il rumore del veicolo, la marmitta (il silenziatore) deve funzionare bene e deve essere del tipo giusto, cioè approvata per quel veicolo. Se è rovinata o non approvata, farà più rumore.', 'Le parole chiave sono ''efficiente'' (che funziona bene) e ''di tipo approvato'' (che rispetta le regole e le specifiche del veicolo).', 'Marmitta OK = Meno rumore e legale!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25090, 'Se la marmitta è rovinata, non riesce più a ridurre il rumore. Per questo, è importante cambiarla con una nuova che sia ''approvata'' (cioè, fatta apposta e omologata) per il tuo veicolo. Così il rumore diminuisce e rispetti la legge.', 'Attenzione a ''rovinata'' (danneggiata) e ''approvata per quel tipo di veicolo'' (non una qualsiasi, ma quella giusta e legale).', 'Marmitta rotta? Sostituisci con l''originale!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25091, 'Quando il veicolo è fermo, accelerare (dare gas) non serve a nulla se non a fare rumore inutile. È un comportamento che disturba e non aiuta a diminuire l''inquinamento acustico.', 'La frase ''non si deve accelerare quando il veicolo è fermo'' indica un comportamento da evitare per rispetto degli altri e dell''ambiente.', 'Da fermo, non ''sgasare''!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25092, 'I freni che fischiano o fanno rumore quando freni non solo sono fastidiosi, ma potrebbero indicare un problema. Farli controllare e, se necessario, sostituirli, non solo migliora la sicurezza ma riduce anche il rumore generale del veicolo.', 'Le parole ''se emettono rumore'' e ''sostituendoli se necessario'' sottolineano che il rumore è un segnale di un possibile problema che va risolto.', 'Freni rumorosi? Controlla e ripara!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25093, 'Questa domanda rafforza il concetto precedente. Controllare e riparare i freni rumorosi ha un doppio vantaggio: rende la guida più sicura (perché i freni funzionano meglio) e rende il veicolo meno rumoroso, contribuendo a diminuire l''inquinamento acustico.', 'La frase ''oltre ad aumentare la sicurezza può ridurre la rumorosità'' evidenzia i due benefici principali di questa azione.', 'Freni silenziosi = Sicurezza + Meno rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25094, 'Il clacson serve per avvisare in caso di pericolo, non per salutare o per esprimere impazienza. Usarlo solo quando è strettamente necessario aiuta a ridurre il rumore generale nelle strade.', 'La frase ''il meno possibile'' è la chiave: significa usarlo solo in caso di vera necessità, non per abitudine.', 'Clacson solo se serve!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25095, 'Fare dei fori nella marmitta è una modifica sbagliata e illegale. Invece di diminuire il rumore, lo aumenta moltissimo, rendendo il veicolo non conforme alle norme e molto fastidioso per gli altri.', 'La parola ''praticare dei fori'' è la trappola: questa azione ha l''effetto opposto a quello desiderato e rende il veicolo irregolare.', 'Fori nella marmitta? Più rumore, non meno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25096, 'Sostituire il tubo di scarico con uno di diametro più piccolo non è una soluzione per diminuire il rumore. Anzi, potrebbe creare problemi al motore o non essere omologato, aumentando il rumore o causando malfunzionamenti. La riduzione del rumore dipende dalla marmitta, non dal diametro del tubo.', 'La frase ''usandone uno di diametro più piccolo'' è la parte sbagliata. Non è una pratica corretta per ridurre il rumore.', 'Diametro scarico? Non è la soluzione al rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25097, 'Eliminare una parte della marmitta è assolutamente sbagliato e illegale. La marmitta è fatta per silenziare il rumore del motore; se ne togli una parte, il rumore aumenterà in modo eccessivo e il veicolo non potrà circolare.', 'La frase ''eliminare la parte finale della marmitta'' è la trappola. Questa azione ha l''effetto opposto e rende il veicolo fuori legge.', 'Marmitta incompleta = Rumore eccessivo e multa!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25098, 'Quando si affronta una curva ad alta velocità, le gomme non rotolano perfettamente ma tendono a ''scivolare'' un po'' sull''asfalto. Questo scivolamento, chiamato strisciamento, crea attrito e, di conseguenza, produce rumore. È come il suono che fanno le gomme quando si frena bruscamente o si gira velocemente.', 'La parola ''strisciamento'' è la chiave: indica proprio quel movimento laterale delle gomme che genera rumore. ''Forte velocità'' è la condizione che lo provoca.', 'Curva veloce = gomme che strisciano = rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25099, 'Un rimorchio vuoto è molto più leggero. Quando si viaggia su strade non perfettamente lisce, un rimorchio leggero tende a ''saltare'' o ''sobbalzare'' di più. Questi sobbalzi possono far sbattere le parti del rimorchio tra loro o contro il veicolo che lo traina, generando rumore.', 'Le parole ''vuoti'' e ''sobbalzano eccessivamente'' sono importanti. Un rimorchio vuoto è leggero e quindi più propenso a sobbalzare. ''Eccessivamente'' sottolinea che il movimento è tale da causare un problema, in questo caso il rumore.', 'Rimorchio vuoto + sobbalzi = rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25100, 'Accelerare piano e dolcemente all''inizio aiuta il motore a lavorare meglio e a consumare meno carburante, quindi produce meno inquinamento. Evitare accelerazioni brusche è un buon comportamento per l''ambiente.', 'La frase chiave è ''non bisogna accelerare bruscamente''. ''Bruscamente'' significa ''all''improvviso, con forza''. Evitare questo comportamento è positivo.', 'Partenza dolce = meno fumo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25101, 'Le marce basse (come la prima o la seconda) fanno girare il motore a regimi più alti e consumano più carburante, aumentando l''inquinamento. È meglio passare a marce più alte appena possibile per ridurre i consumi e le emissioni.', 'Il punto cruciale è ''evitare di tenere inserita per troppo tempo una marcia bassa''. Le marce basse servono per poco tempo, poi bisogna cambiare.', 'Marcia alta = meno inquina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25102, 'La marmitta catalitica è un componente fondamentale che serve proprio a ridurre le sostanze inquinanti prodotte dal motore. Se è rotta, vecchia o non funziona più bene (''deteriorata o esausta''), il veicolo inquina molto di più. Sostituirla è essenziale.', 'La condizione ''deteriorata o esausta'' indica che la marmitta non funziona più. In questo caso, la sostituzione è obbligatoria per l''ambiente.', 'Catalitica rotta = più inquina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25103, 'La frizione e il differenziale sono componenti importanti per il funzionamento del veicolo e la sicurezza di guida, ma non hanno un impatto diretto sull''inquinamento dell''aria, che è legato principalmente al motore e al sistema di scarico.', 'Le parole ''frizione e il differenziale'' sono la chiave. Questi componenti non sono direttamente responsabili delle emissioni inquinanti.', 'Frizione/differenziale = non inquinano (direttamente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25104, 'Gli ammortizzatori (organi di sospensione) sono fondamentali per la stabilità, il comfort e la sicurezza del veicolo, ma non influenzano direttamente la quantità di gas inquinanti emessi dal motore. Il loro controllo non serve a diminuire l''inquinamento dell''aria.', 'Le parole ''organi di sospensione (ammortizzatori)'' sono il focus. Questi componenti non sono collegati alle emissioni del motore.', 'Ammortizzatori = non inquinano (direttamente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25105, 'Al contrario! Se la pressione dei pneumatici è troppo bassa, il veicolo fa più fatica a muoversi, aumenta l''attrito con la strada, consuma più carburante e quindi inquina di più. La pressione corretta è importante per la sicurezza e per ridurre i consumi e l''inquinamento.', 'La parola trappola è ''ridurre la pressione di gonfiaggio''. La pressione va mantenuta corretta, non ridotta. Ridurla è sbagliato per l''ambiente e la sicurezza.', 'Pressione bassa = più consumi = più inquina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25106, 'Accelerare ripetutamente da fermo (''sgasare'') è uno spreco di carburante e aumenta inutilmente l''inquinamento. Il motore si scalda guidando normalmente e non ha bisogno di essere ''tenuto caldo'' in questo modo per migliorare il rendimento.', 'La frase ''accelerare ripetutamente da fermo'' descrive un''azione sbagliata e controproducente sia per i consumi che per l''ambiente.', 'Sgasare da fermo = spreco e inquina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25107, 'La marmitta catalitica funziona bene solo quando raggiunge una certa temperatura. Appena si accende il motore, è fredda e non riesce a ridurre gli inquinanti in modo efficace. Per questo, i primi minuti di guida sono quelli in cui il veicolo inquina di più.', 'La parola trappola è ''minore''. L''inquinamento è in realtà MAGGIORE subito dopo l''accensione, quando la catalitica è fredda.', 'Catalitica fredda = inquina di più.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25108, 'Se il motore del veicolo non funziona bene, brucia il carburante in modo inefficiente. Questo significa che produce più sostanze inquinanti e quindi aumenta l''inquinamento dell''aria. Un motore che ''tossisce'' inquina di più.', 'La parola chiave è ''può dipendere''. Indica una possibilità, non una certezza assoluta, rendendo l''affermazione vera. Un malfunzionamento è una causa possibile di maggiore inquinamento.', 'Motore ''stanco'' = aria ''sporca''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25109, 'Un veicolo che è sempre controllato e mantenuto bene, con un buon consumo di carburante e un motore efficiente, inquina meno. Fare la manutenzione regolare aiuta a ridurre le emissioni nocive.', 'Anche qui, ''può essere ridotto'' indica che è un modo efficace per diminuire l''inquinamento, non eliminarlo del tutto. ''Condizioni ottimali'' significa che il veicolo funziona al meglio.', 'Auto in forma = meno inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25110, 'Guidare in modo tranquillo, senza accelerazioni improvvise o frenate brusche, fa consumare meno carburante. Meno carburante bruciato significa meno gas inquinanti rilasciati nell''aria.', '''È possibile ridurre'' sottolinea che il nostro comportamento alla guida ha un impatto positivo. ''Limiti i consumi'' è direttamente collegato a meno inquinamento.', 'Guida ''dolce'' = aria ''pulita''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25111, 'Il filtro dell''aria serve a pulire l''aria che entra nel motore. Se è sporco o intasato, il motore non riceve abbastanza aria pulita, brucia male il carburante e produce più inquinamento. Un filtro pulito aiuta il motore a funzionare meglio e a inquinare meno.', '''Può essere ridotto'' è la solita indicazione che l''azione ha un effetto positivo. ''Non sia sporco o intasato'' significa che un filtro pulito è la condizione ideale.', 'Filtro pulito = motore respira meglio = meno fumo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25112, 'Accelerare a fondo fa consumare molto più carburante e aumenta l''inquinamento, non lo fa scomparire. Nessun veicolo smette di inquinare completamente solo accelerando.', 'Le parole ''scompare del tutto'' sono una trappola! L''inquinamento non scompare mai del tutto, specialmente accelerando a fondo. Questa è una frase assoluta che rende l''affermazione falsa.', '''Del tutto'' + accelerare a fondo = FALSO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25113, 'Il climatizzatore usa energia dal motore per funzionare. Quando è acceso, il motore deve lavorare di più, consumando più carburante. Più carburante consumato significa più inquinamento, non meno.', 'La parola ''diminuisce'' è la trappola. Accendere il climatizzatore fa aumentare il consumo di carburante e quindi l''inquinamento, non lo diminuisce.', 'Clima acceso = più benzina = più inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25114, 'Nessun veicolo ha un inquinamento ''nullo'', cioè zero. Anche i veicoli più moderni producono un minimo di emissioni. La normativa ''Euro 0'' si riferisce a veicoli molto vecchi, che inquinano molto di più rispetto a quelli con normative più recenti (come Euro 6).', 'La frase ''è nullo'' è la trappola principale. È una frase assoluta che è quasi sempre falsa quando si parla di inquinamento dei veicoli. ''Euro 0'' indica veicoli molto inquinanti, non il contrario.', '''Nullo'' + Euro 0 = FALSO. Nessun veicolo ha zero inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25115, 'Se gli iniettori del motore non funzionano bene (sono difettosi), il carburante non viene bruciato correttamente. Questo significa che il motore produce più sostanze inquinanti e quindi l''inquinamento dell''aria aumenta. È come se il motore ''tossisse'' e sporcasse di più.', 'La parola ''difettosi'' è la chiave. Indica un malfunzionamento che porta sempre a un peggioramento, in questo caso, dell''inquinamento.', 'Iniettori difettosi = più inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25116, 'Quando vedi molto fumo uscire dallo scarico di un veicolo, è un segnale che il motore non sta lavorando bene. Questo fumo extra contiene più sostanze nocive e quindi indica un maggiore inquinamento dell''aria. Un motore sano produce poco fumo, quasi invisibile.', 'La frase ''maggiore emissione di fumo'' è il segnale. ''Sintomo'' significa ''segno di un problema''.', 'Più fumo = più inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25117, 'Il colore del fumo di scarico ci dice molto. Se il fumo è scuro (nero o blu), significa che il motore sta bruciando male il carburante o sta bruciando olio. Entrambe le situazioni producono molte più sostanze inquinanti rispetto a un motore che funziona bene e produce fumo quasi trasparente.', 'Le parole ''colore scuro'' sono importanti. Indicano un problema di combustione e quindi un aumento dell''inquinamento.', 'Fumo scuro = motore sporco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25118, 'I gas di scarico dei veicoli contengono molte sostanze chimiche dannose. Respirare quest''aria inquinata può irritare la gola, i polmoni e causare problemi respiratori. Anche gli occhi possono bruciare o lacrimare a causa di queste sostanze.', 'La frase ''può causare'' indica una possibilità, ma in questo caso è una certezza scientifica che l''inquinamento ha effetti negativi sulla salute.', 'Inquinamento = danni a occhi e polmoni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25119, 'L''inquinamento prodotto dai veicoli è una delle cause principali di problemi ambientali globali. Contribuisce alla formazione dello smog nelle città, alle piogge acide che danneggiano foreste e edifici, e all''aumento dell''effetto serra, che causa il riscaldamento del pianeta.', 'Le parole ''fa aumentare'' collegano direttamente l''inquinamento dei veicoli a questi fenomeni ambientali negativi. Sono tutti effetti noti.', 'Veicoli = smog, piogge acide, effetto serra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25120, 'La maggior parte dell''inquinamento che un veicolo produce viene dai gas che escono dal tubo di scarico. Questi gas si formano quando il carburante (benzina o diesel) brucia dentro il motore. È il processo di combustione che genera le sostanze inquinanti.', 'La frase ''per la maggior parte'' è importante. Significa che non è l''unica fonte, ma è la più grande e significativa. ''Gas di scarico'' è il termine tecnico.', 'Inquinamento = gas di scarico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25121, 'L''inquinamento prodotto dai veicoli dipende principalmente da come funziona il motore, dal tipo di carburante usato e da come si guida. L''umidità nell''aria non è il fattore principale che determina quanto un veicolo inquina. L''umidità può influenzare come gli inquinanti si disperdono, ma non quanto ne vengono prodotti dal motore.', 'La parola ''principalmente'' è la trappola. L''umidità ha un ruolo molto marginale nella produzione di inquinamento da parte del veicolo, non è la causa principale. I fattori principali sono legati al motore e alla combustione.', 'Inquinamento veicoli = motore, non meteo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25122, 'Un veicolo più leggero ha bisogno di meno energia per muoversi. Meno energia significa che il motore brucia meno carburante e, di conseguenza, produce meno gas inquinanti. Quindi, alleggerire il veicolo aiuta a ridurre l''inquinamento.', 'La frase ''alleggerisce il peso'' significa rendere il veicolo meno pesante. Meno peso = meno sforzo per il motore.', 'Meno peso = meno benzina = meno smog.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25123, 'I veicoli elettrici non producono gas di scarico direttamente. I veicoli a metano o GPL, invece, producono meno sostanze inquinanti rispetto ai veicoli a benzina o diesel tradizionali. Scegliere queste alternative è un buon modo per ridurre l''inquinamento dell''aria.', 'Le parole ''elettrica, a metano o GPL'' indicano tipi di alimentazione del veicolo che sono considerate più ecologiche rispetto ai carburanti fossili classici.', 'Alternative pulite = meno inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25124, 'Se il motore è spento, non brucia carburante e non produce gas di scarico. Quindi, in situazioni come lunghe code, passaggi a livello o semafori molto lunghi, spegnere il motore è un''azione efficace per diminuire l''inquinamento e risparmiare carburante.', 'La frase ''arresto prolungato'' è la chiave: significa fermarsi per un tempo considerevole, non solo per pochi secondi.', 'Motore spento = zero emissioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25125, 'Nei brevi percorsi, il motore non ha il tempo di raggiungere la sua temperatura ideale di funzionamento e, in questa fase, inquina di più. Inoltre, per distanze molto corte, è spesso possibile camminare o usare la bicicletta, evitando del tutto l''uso del veicolo a motore.', 'La frase ''brevi percorsi'' si riferisce a tragitti corti, per i quali l''auto non è la scelta più efficiente né ecologica.', 'Percorsi brevi? A piedi o bici!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25126, 'La legge prevede controlli sulle emissioni dei veicoli. Se un veicolo emette troppi gas inquinanti, significa che non è in regola con le normative ambientali. In questi casi, il conducente può essere multato (sanzione amministrativa) e la carta di circolazione (il documento che permette al veicolo di circolare) può essere ritirata.', 'Le parole ''sanzione amministrativa'' e ''ritiro della carta di circolazione'' indicano le conseguenze legali per chi non rispetta le norme sulle emissioni.', 'Troppo smog = multa e documenti via.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25127, 'Mettere i bagagli sul tetto dell''auto aumenta la resistenza dell''aria (l''auto fa più fatica a ''tagliare'' l''aria). Questa maggiore resistenza costringe il motore a lavorare di più, consumando più carburante e, di conseguenza, aumentando l''inquinamento, non diminuendolo.', 'La frase ''sistemano i bagagli sul tetto'' è la parte cruciale. Questa azione, contrariamente a quanto si potrebbe pensare, peggiora l''efficienza aerodinamica.', 'Bagagli sul tetto = più fatica = più inquina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25128, 'Circolare sempre con marce basse (come la prima o la seconda) fa sì che il motore lavori a giri molto alti, consumando più carburante del necessario e producendo più inquinamento. Per ridurre l''inquinamento, è meglio usare marce alte quando la velocità lo permette, mantenendo il motore a bassi regimi.', 'La parola ''sempre'' è spesso una trappola nei quiz. Le marce basse sono utili solo per la partenza o a velocità molto ridotte. L''uso costante è inefficiente.', 'Marce basse = motore ''sotto sforzo'' = più inquina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25129, 'Accelerare tenendo premuto il pedale della frizione (o ''slittare la frizione'') è una pratica di guida scorretta. In questo modo, il motore gira a vuoto, sprecando carburante senza trasmettere potenza alle ruote. Questo non solo non riduce l''inquinamento, ma lo aumenta a causa dello spreco di carburante e usura la frizione.', 'La frase ''accelerare tenendo premuto il pedale della frizione'' descrive un''azione che disperde energia e non è efficiente per la guida.', 'Frizione premuta + acceleri = spreco e usura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25130, 'Accelerare con il cambio in folle significa far girare il motore senza che sia collegato alle ruote. Questo è uno spreco di carburante inutile, poiché l''energia prodotta non viene usata per muovere il veicolo. Di conseguenza, non si riduce l''inquinamento, ma si consuma carburante senza scopo.', 'La frase ''accelera con il cambio in folle'' indica un''azione che non ha alcuna utilità pratica per la guida e porta solo a spreco di carburante e rumore.', 'Folle + acceleri = rumore e spreco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25131, 'Il filtro dell''aria pulisce l''aria che il motore usa per bruciare il carburante. Se il filtro è sporco, il motore non funziona bene, consuma di più e produce più gas inquinanti. Sostituirlo regolarmente aiuta a ridurre l''inquinamento.', 'La parola ''periodicamente'' significa ''ogni tanto, regolarmente''. Non basta farlo una volta sola, ma con la giusta frequenza.', 'Filtro aria pulito = motore efficiente = meno inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25132, 'Nei motori diesel, la pompa di iniezione e gli iniettori sono fondamentali per spruzzare il carburante nel motore. Se non funzionano bene, il carburante non brucia completamente, creando più fumo e inquinamento. Controllarli aiuta a mantenere il motore pulito e a inquinare meno.', 'La frase ''motore diesel'' indica che questa regola è specifica per quel tipo di motore. Il ''sistema di alimentazione'' include le parti che portano il carburante al motore.', 'Diesel: iniettori ok = combustione pulita.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25133, 'Se dal tubo di scarico esce fumo troppo scuro, significa che il motore non sta bruciando bene il carburante. Questo è un segnale che il veicolo sta inquinando più del dovuto. Far controllare il motore è necessario per risolvere il problema e ridurre l''inquinamento.', 'La frase ''fumo dello scarico risulta troppo scuro'' è un chiaro indicatore di un problema al motore che causa maggiore inquinamento.', 'Fumo scuro = problema = inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25134, 'Accelerare e frenare spesso, con una guida ''a scatti'', fa consumare più carburante e produce più gas di scarico. Una guida fluida, senza brusche accelerazioni o frenate, è più efficiente, consuma meno e inquina meno l''aria.', 'La frase ''non bisogna accelerare e frenare spesso'' si riferisce a una guida irregolare e poco efficiente.', 'Guida fluida = meno consumi = meno inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25135, 'Dare un ''colpo di acceleratore'' a vuoto prima di cambiare marcia è una vecchia abitudine che non serve nei veicoli moderni. Questa azione fa solo aumentare il consumo di carburante e, di conseguenza, l''inquinamento, senza alcun beneficio per la guida.', 'La frase ''breve colpo di acceleratore'' descrive un''azione inutile e dannosa per l''ambiente nei veicoli attuali.', 'Colpo di acceleratore a vuoto = spreco e inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25136, 'Usare il motore al ''massimo numero di giri'' significa ''tirare'' le marce, cioè far salire molto i giri del motore prima di cambiare. Questo fa consumare tantissimo carburante e produce molti più gas inquinanti. Per inquinare meno, bisogna guidare con marce alte e a un numero di giri moderato.', 'La frase ''massimo numero di giri'' indica una guida aggressiva e non ecologica, che è l''opposto di ciò che serve per diminuire l''inquinamento.', 'Giri alti = più consumo = più inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25137, 'Il filtro antipolline serve a pulire l''aria che entra nell''abitacolo del veicolo, per proteggere i passeggeri da polvere e pollini. Non ha nessun effetto sui gas di scarico che escono dal motore e quindi non diminuisce l''inquinamento atmosferico.', 'La parola ''filtro antipolline'' è la chiave: questo filtro è per l''aria interna, non per i gas di scarico del motore.', 'Antipolline = aria interna, non scarico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25138, 'Il filtro dell''olio serve a mantenere pulito l''olio che lubrifica il motore. È importante cambiarlo, ma non ''ad ogni cambio di stagione''. Si cambia insieme all''olio, secondo le indicazioni del costruttore (di solito ogni 10.000-20.000 km o una volta all''anno), non quattro volte all''anno. Inoltre, il filtro dell''olio non ha un impatto diretto sull''inquinamento dei gas di scarico.', 'La frase ''ad ogni cambio di stagione'' indica una frequenza sbagliata e troppo alta. Il filtro dell''olio non influisce direttamente sui gas di scarico, ma sulla salute del motore.', 'Filtro olio = lubrificazione, non gas di scarico. ''Ogni stagione'' è troppo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25139, 'È VERO. Il climatizzatore usa energia dal motore, quindi consuma più carburante e produce più inquinamento. Usarlo solo quando è davvero necessario aiuta a risparmiare e a proteggere l''ambiente.', 'Le parole chiave sono ''il meno possibile'' e ''soltanto quando serve effettivamente''. Indicano un uso moderato e consapevole, che è sempre la scelta giusta per l''ambiente e il portafoglio.', 'Climatizzatore = Consumo. Usalo con giudizio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25140, 'È FALSO. Quando il motore è freddo, premere l''acceleratore più volte non aiuta, anzi. Aumenta il consumo di carburante e le emissioni inquinanti, perché il motore non è ancora alla sua temperatura ideale di funzionamento. È meglio partire dolcemente.', 'La frase ''premere più volte il pedale dell''acceleratore quando il veicolo è freddo'' è la trappola. Questa azione è sbagliata per l''ambiente e per il motore.', 'Motore freddo? Partenza dolce, non accelerare a vuoto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25141, 'È FALSO. Accelerare ''diverse volte e a fondo'' per scaldare il motore velocemente è un errore. Non solo non è efficace, ma fa consumare più carburante e inquina di più. Il motore si scalda meglio guidando con calma e senza brusche accelerazioni.', 'Le parole ''diverse volte e a fondo'' e ''in fretta'' sono le trappole. Indicano un comportamento aggressivo che è l''opposto di una guida ecologica.', 'Riscaldare il motore? Guida tranquilla, non a fondo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25142, 'È FALSO. Quando cambi marcia, premere ''a fondo'' l''acceleratore non è una buona pratica. Aumenta il rumore (inquinamento acustico), il consumo di carburante e le emissioni inquinanti. Bisogna cambiare marcia in modo fluido e senza far salire troppo i giri del motore.', 'La frase ''premere a fondo il pedale dell''acceleratore'' è la trappola. Questa azione è dannosa sia per l''ambiente (atmosferico e acustico) che per il consumo.', 'Cambio marcia? Accelera con calma, non a fondo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25143, 'È VERO. Quando viaggi a velocità elevate con i finestrini aperti, l''aria che entra nell''abitacolo crea resistenza (come un freno) e il motore deve lavorare di più per mantenere la velocità. Questo fa aumentare il consumo di carburante.', 'La parola chiave è ''turbolenze''. Le turbolenze sono movimenti disordinati dell''aria che creano resistenza e ''frenano'' il veicolo, aumentando lo sforzo del motore.', 'Finestrini aperti ad alta velocità = più resistenza = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25144, 'È VERO. Il portapacchi sul tetto cambia la forma aerodinamica dell''auto, creando più resistenza all''aria. Questo costringe il motore a sforzarsi di più e, di conseguenza, aumenta il consumo di carburante. È sempre meglio mettere i bagagli dentro l''auto se possibile.', 'La frase ''non conviene fare uso del portapacchi'' è importante. Il ''non'' indica che è sconsigliato per risparmiare carburante.', 'Portapacchi sul tetto = più resistenza = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25145, 'È VERO. Uno strato spesso di neve sul tetto aggiunge peso al veicolo e ne modifica l''aerodinamica. Sia il peso extra che la forma meno aerodinamica aumentano lo sforzo del motore e quindi il consumo di carburante.', 'La parola ''spesso'' è importante. Un piccolo strato non fa molta differenza, ma uno ''spesso strato'' ha un impatto significativo.', 'Neve sul tetto = più peso + più resistenza = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25146, 'È VERO. Similmente ai finestrini aperti, anche il tettuccio aperto a forte velocità crea resistenza all''aria e turbolenze. Questo fa lavorare di più il motore e aumenta il consumo di carburante.', 'Le parole ''forte velocità'' sono cruciali. A basse velocità l''effetto è minimo, ma ad alta velocità diventa significativo.', 'Tettuccio aperto ad alta velocità = più aria = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25147, 'È FALSO. In una situazione di traffico fermo in galleria, ci sono molti gas di scarico. Azionare il ricircolo dell''aria significa che l''auto smette di prendere aria dall''esterno e fa circolare solo l''aria già presente nell''abitacolo. Questo serve proprio a non far entrare i gas inquinanti dall''esterno, quindi è utile per la salute, non dannoso.', 'La parola ''dannoso'' è la trappola. Il ricircolo è utile in queste situazioni, non dannoso.', 'Ricircolo in galleria = aria pulita dentro = SALUTE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25148, 'È FALSO. Le normative ''Euro'' indicano quanto un veicolo inquina. Più alto è il numero ''Euro'' (es. Euro 4), meno inquina il veicolo. Quindi, un veicolo Euro 4 inquina molto meno di un Euro 0 (che è il più vecchio e inquinante).', 'La parola ''maggiore'' è la trappola. Un Euro 4 emette una quantità di gas inquinanti MINORE, non maggiore, rispetto a un Euro 0.', 'Euro più ALTO = meno inquinamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25149, 'È FALSO. Trainare un rimorchio aggiunge molto peso al veicolo e aumenta la resistenza all''aria. Il motore deve fare molta più fatica per muovere tutto questo peso extra, e di conseguenza, il consumo di carburante aumenta in modo significativo.', 'La frase ''non comporta un aumento'' è la trappola. Il ''non'' rende l''affermazione falsa.', 'Rimorchio = più peso + più resistenza = più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25150, 'È vero che se guidi un veicolo con motore e marmitta modificati senza autorizzazione, puoi ricevere multe molto salate. Le modifiche al veicolo devono essere approvate e registrate, altrimenti il veicolo non è più conforme alle norme di sicurezza e inquinamento.', 'La frase ''si può incorrere in pesanti sanzioni amministrative'' significa che è molto probabile ricevere multe severe. Non è un''opzione, ma una conseguenza legale.', 'Modifiche non autorizzate = Multe sicure.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25151, 'È falso. Non puoi modificare liberamente il motore o la marmitta del tuo veicolo, nemmeno se pensi di ridurre l''inquinamento. Ogni modifica deve essere autorizzata e certificata da esperti per garantire che il veicolo sia sicuro e rispetti le leggi.', 'La parola ''liberamente'' è la chiave: non si può fare nulla ''liberamente'' che cambi le caratteristiche tecniche del veicolo. Anche se l''intenzione ''per diminuire l''inquinamento'' sembra buona, il metodo è sbagliato se non autorizzato.', 'Modifiche al veicolo? Solo con permesso e certificazione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25152, 'È assolutamente vietato scaricare il liquido antigelo nelle fognature. Questo liquido è inquinante e può causare gravi danni all''ambiente e ai sistemi di depurazione dell''acqua, anche se non è specificato che non sia biodegradabile.', 'La frase ''potrebbe non essere biodegradabile'' non è la ragione principale del divieto, ma rafforza l''idea che sia dannoso. Il punto chiave è che è VIETATO a prescindere.', 'Antigelo = Mai in fognatura!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25153, 'Le batterie delle auto contengono sostanze chimiche molto pericolose, come l''acido solforico e il piombo. Se abbandonate, queste sostanze possono inquinare gravemente il terreno e le falde acquifere, cioè l''acqua che si trova sotto terra.', 'La parola ''può'' indica una possibilità, ma in questo caso è una certezza: l''abbandono di batterie causa sempre danni all''ambiente.', 'Batteria = Veleno per l''acqua.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25154, 'Quando compri una nuova batteria per la tua auto, il rivenditore è obbligato per legge a ritirare la tua vecchia batteria usata. Questo servizio è gratuito, non devi pagare nulla in più.', 'La frase ''senza ulteriori costi aggiuntivi'' è importante. Significa che il ritiro della batteria usata è incluso nel servizio e non ha un costo extra.', 'Batteria usata = Al rivenditore, gratis.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25155, 'Se vuoi demolire o rottamare la tua auto, devi portarla in un centro specializzato. Questi centri, chiamati autodemolitori autorizzati, sanno come smontare il veicolo in modo sicuro e smaltire correttamente tutti i materiali, anche quelli pericolosi.', 'La parola ''deve'' indica un obbligo. Non puoi rottamare l''auto da solo o in un posto qualsiasi.', 'Rottamare = Solo autodemolitore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25156, 'L''olio motore usato contiene molte sostanze chimiche che possono essere dannose per la pelle. È importante evitare il contatto prolungato per prevenire irritazioni o altri problemi di salute.', 'La parola ''prolungato'' è chiave. Anche un contatto breve non è l''ideale, ma un contatto lungo è decisamente più rischioso.', 'Olio motore = Non sulla pelle.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25157, 'Le autocaravan (camper) producono residui organici e acque sporche. Questi devono essere scaricati solo in aree apposite, chiamate impianti di smaltimento igienico-sanitari, per non inquinare l''ambiente e rispettare le norme igieniche.', 'La frase ''deve avvenire'' sottolinea l''obbligo. Non è una scelta, ma una regola da seguire.', 'Camper = Scarico solo in aree dedicate.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25158, 'È FALSO. Abbandonare sul terreno rifiuti pericolosi o tossici, come oli o altri liquidi di scarto, è un reato grave. Chi lo fa viene sempre sanzionato con multe salate e, in alcuni casi, anche con conseguenze penali.', 'La frase ''non viene sanzionato'' è la trappola. In realtà, l''abbandono di rifiuti pericolosi è sempre punito dalla legge.', 'Rifiuti pericolosi = Sempre sanzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25159, 'È FALSO. Per demolire o rottamare un veicolo, non devi consegnarlo ''esclusivamente'' al concessionario della casa costruttrice. Puoi portarlo anche a un qualsiasi autodemolitore autorizzato, che è un centro specializzato nella rottamazione.', 'La parola ''esclusivamente'' è la trappola. Non è l''unica opzione; ci sono anche gli autodemolitori autorizzati.', 'Rottamare = Non solo concessionario.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25160, 'È VERO. È fondamentale rispettare e non danneggiare le infrastrutture stradali, come guardrail, segnaletica o semafori. Danneggiarle è un comportamento sbagliato e illegale, perché mette a rischio la sicurezza di tutti.', 'La parola ''vietato'' indica un''azione proibita dalla legge. In questo caso, è un divieto assoluto e logico.', 'Rispetta la strada, è di tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25161, 'È VERO. Gettare oggetti o rifiuti dal veicolo è pericoloso per gli altri utenti della strada (potrebbe causare incidenti) e inquina l''ambiente. È un comportamento sanzionabile.', 'Anche qui, ''vietato'' è chiaro. Non ci sono eccezioni per questo tipo di azione.', 'Non sporcare, non rischiare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25162, 'È VERO. Sporcare la strada con rifiuti o altri materiali è proibito. Mantiene la carreggiata pulita è importante per la sicurezza e l''igiene pubblica. I rifiuti possono essere un pericolo per i veicoli a due ruote o causare scivolamenti.', 'Il termine ''vietato'' è diretto. Non ci sono situazioni in cui è permesso sporcare la carreggiata.', 'Strada pulita = guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25163, 'È VERO. Immettersi sulla strada con le ruote sporche di fango è vietato perché il fango può staccarsi e depositarsi sulla carreggiata, rendendola scivolosa e pericolosa per gli altri veicoli, specialmente per le moto.', 'La frase ''è vietato'' indica un divieto chiaro. Non è una questione di ''un po'' di fango'', ma di evitare di sporcare la strada.', 'Fango in strada = pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25164, 'È FALSO. Non è vietato esercitarsi alla guida su tutte le strade. Con il ''foglio rosa'' e un istruttore o una persona con i requisiti richiesti, si può fare pratica su molte strade, purché non siano autostrade o strade extraurbane principali. La chiave è ''tutte le strade''.', 'La parola ''tutte'' è una parola trappola molto comune. Raramente una regola si applica a ''tutte'' le situazioni o ''tutte'' le strade senza eccezioni.', '''Tutte'' o ''sempre''? Attenzione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25165, 'È FALSO. Gli avvisatori acustici (clacson) non sono vietati su tutte le strade. Nelle aree urbane sono vietati, tranne in caso di pericolo immediato. Fuori dai centri abitati, invece, possono essere usati per segnalare la propria presenza, ad esempio prima di un sorpasso o in curva. Quindi, non ''su tutte'' le strade.', 'Ancora una volta, ''tutte le strade'' è la parola trappola. Il clacson ha un uso specifico e limitato, ma non è vietato ovunque.', 'Clacson: solo se serve davvero!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25166, 'È FALSO. Non è vietato il transito dei veicoli che superano 10 m di lunghezza su tutte le strade. Ci sono strade dove questi veicoli (come camion o autobus lunghi) possono circolare, anche se con limiti e percorsi specifici. Il divieto si applica solo su alcune strade, non su ''tutte''.', 'La frase ''tutte le strade'' è la trappola. I veicoli lunghi hanno percorsi e regole, ma non sono banditi da ogni strada.', 'Non tutte le strade sono uguali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25167, 'È FALSO. Non è vietato parcheggiare nelle zone residenziali in generale. Si può parcheggiare, ma bisogna rispettare la segnaletica (strisce blu, bianche, gialle), gli orari e le eventuali tariffe. Il divieto è solo in specifici punti o in assenza di spazi regolamentari, non in tutta la zona.', 'La parola ''vietato'' qui è troppo generica. Parcheggiare è permesso, ma con delle regole. Non c''è un divieto assoluto per tutte le zone residenziali.', 'Parcheggio: con regole, non vietato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25168, 'La forza aderente è quella che permette alle ruote di ''aggrapparsi'' all''asfalto. Senza questa forza, le ruote girerebbero a vuoto e il veicolo non si muoverebbe. È fondamentale per partire, accelerare e frenare.', 'La frase ''consente il movimento'' significa che lo permette, lo rende possibile. È un concetto chiave per capire l''importanza dell''aderenza.', 'Aderenza = Movimento del veicolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25169, 'Quando fai una curva, c''è una forza che tende a spingerti fuori (la forza centrifuga). La forza aderente tra pneumatici e strada è quella che ti tiene ''incollato'' alla traiettoria e impedisce al veicolo di scivolare verso l''esterno della curva.', 'La frase ''si oppone allo slittamento'' significa che lo impedisce, lo contrasta. ''Verso l''esterno della curva'' indica la direzione in cui il veicolo tenderebbe a scivolare senza aderenza.', 'In curva, l''aderenza ti tiene in strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25170, 'La traiettoria voluta è la strada che tu vuoi fare con il veicolo. La forza aderente è ciò che permette alle ruote di seguire la direzione che imposti con il volante, senza scivolare o andare dritte.', 'La ''traiettoria voluta'' è la direzione che il conducente decide di seguire. ''Consente'' significa permette.', 'Aderenza = Guida precisa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25171, 'Questa è la definizione base di forza aderente. È la forza che impedisce alla gomma di scivolare (slittare) sulla superficie della strada, sia in accelerazione, frenata o curva.', 'La frase ''si oppone allo slittamento'' è proprio il suo scopo principale e definisce la funzione dell''aderenza.', 'Aderenza = No slittamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25172, 'Il vento laterale spinge il veicolo di lato. La forza aderente tra le gomme e la strada è proprio quella che contrasta questa spinta, mantenendo il veicolo sulla sua traiettoria. Se non ci fosse aderenza, il vento ti sposterebbe facilmente. Quindi, la forza aderente *si* oppone allo slittamento causato dal vento.', 'La parola trappola è ''non''. La forza aderente *si* oppone allo slittamento causato dal vento laterale, aiutando a mantenere la stabilità del veicolo.', 'Vento laterale? L''aderenza ti stabilizza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25173, 'La forza aderente è la ''presa'' tra gomma e strada. Il surriscaldamento dei freni avviene quando si usano troppo i freni, non è direttamente legato a una ''eccessiva'' forza aderente. Anzi, una buona aderenza aiuta i freni a essere più efficaci senza doverli surriscaldare. Se l''aderenza è poca, i freni possono bloccarsi e le ruote slittare, ma non è l''aderenza in sé a surriscaldare i freni.', 'La frase ''se eccessiva'' è fuorviante, perché l''aderenza è sempre un bene. La conseguenza ''comporta il surriscaldamento dei freni'' è errata; il surriscaldamento è causato da un uso prolungato o intenso dei freni.', 'Aderenza = Bene. Surriscaldamento freni = Troppo uso freni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25174, 'VERO. La forza aderente è la ''presa'' che le gomme hanno sull''asfalto. Se l''asfalto è rugoso, cioè non liscio, le gomme hanno più punti a cui aggrapparsi, e quindi la presa aumenta.', 'La parola chiave è ''rugoso'', che significa non liscio, con una superficie irregolare. Questo aiuta l''aderenza.', 'Rugoso = più presa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25175, 'VERO. Quando l''asfalto è bagnato, c''è uno strato d''acqua tra le gomme e la strada. Questo strato fa scivolare le gomme più facilmente, riducendo la ''presa'' e quindi la forza aderente.', 'Il termine ''diminuisce'' è importante: significa che la forza aderente diventa meno forte, non più forte.', 'Bagnato = meno presa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25176, 'FALSO. Questa affermazione è l''opposto di quella vera. L''acqua sull''asfalto rende la strada più scivolosa, non meno. Quindi, la forza aderente diminuisce, non aumenta.', 'La parola ''aumenta'' è la trappola qui. Ricorda che l''acqua è un pericolo per l''aderenza.', 'Acqua = pericolo, non più presa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25177, 'FALSO. Le foglie, specialmente se sono bagnate o umide, creano uno strato scivoloso sull''asfalto. Le gomme non riescono ad avere una buona ''presa'', e quindi la forza aderente diminuisce, non aumenta.', 'La condizione ''coperto di foglie'' è la chiave. Le foglie non migliorano l''aderenza, la peggiorano.', 'Foglie = scivoloso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25178, 'FALSO. Il ghiaccio è estremamente scivoloso. Quando l''asfalto è coperto di ghiaccio, le gomme non hanno quasi nessuna ''presa'' sulla strada. La forza aderente diminuisce moltissimo, rendendo la guida molto pericolosa.', 'La parola ''ghiaccio'' indica una condizione di pericolo estremo per l''aderenza. Non può mai aumentare l''aderenza.', 'Ghiaccio = zero presa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25179, 'FALSO. Il fango, come l''acqua o le foglie, crea uno strato tra le gomme e l''asfalto. Questo strato rende la superficie scivolosa e riduce la ''presa'' delle gomme. Quindi, la forza aderente diminuisce, non aumenta.', 'La condizione ''coperto dal fango'' è importante. Il fango è un elemento che peggiora l''aderenza.', 'Fango = scivoloso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25180, 'Se c''è meno aderenza (cioè le gomme ''attaccano'' meno alla strada, per esempio su ghiaccio o bagnato), le ruote motrici (quelle che danno la spinta) possono girare a vuoto senza far avanzare bene il veicolo. Questo si chiama ''pattinare''. Quindi, è VERO.', 'La parola ''potrebbero'' indica una possibilità, non una certezza assoluta, il che è corretto. Non è detto che pattinino sempre, ma il rischio aumenta molto.', 'Meno aderenza = più scivoli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25181, 'L''aderenza è quanto bene le gomme si ''aggrappano'' alla strada. Se l''aderenza diminuisce (per esempio, strada bagnata o sporca), le gomme fanno più fatica a fermare il veicolo. Per questo, serve più spazio per frenare completamente. Quindi, è VERO.', 'La parola chiave è ''aumenta''. Ricorda che meno aderenza significa più difficoltà a fermarsi.', 'Meno aderenza = più strada per fermarsi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25182, 'Quando l''aderenza è bassa (strada scivolosa), è molto più facile perdere il controllo del veicolo, pattinare o non riuscire a frenare in tempo. Ridurre la velocità ti dà più tempo per reagire e aiuta le gomme a mantenere un contatto migliore con la strada, rendendo la guida più sicura. Quindi, è VERO.', 'Il termine ''bisogna'' indica un''azione necessaria per la sicurezza. Non è un consiglio, ma un obbligo per la tua incolumità.', 'Poco grip = piano vai.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25183, 'Questa domanda è il contrario della 25181. Se l''aderenza diminuisce, le gomme fanno più fatica a fermare il veicolo. Di conseguenza, lo spazio necessario per frenare non si riduce, ma ''aumenta''. Quindi, è FALSO.', 'La parola ''si riduce'' è la trappola. Ricorda che meno aderenza significa sempre più difficoltà a fermarsi, quindi più spazio.', 'Meno aderenza = più strada per fermarsi (non meno!).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25184, 'Quando l''aderenza è bassa (per esempio, per pioggia o ghiaccio), la strada è pericolosa ovunque, non ''solo'' in curva. Devi ridurre la velocità sia in rettilineo, sia in frenata, sia in accelerazione, non solo quando affronti una curva. Le curve sono più rischiose, ma il pericolo è generale. Quindi, è FALSO.', 'La parola ''solo'' è una classica parola trappola. Spesso, quando vedi ''solo'', ''sempre'', ''mai'', ''esclusivamente'', la risposta è FALSO perché limita troppo una situazione generale.', 'Poco grip = piano sempre, non solo in curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25185, 'Se il coefficiente di aderenza è basso, significa che le gomme fanno meno ''presa'' sulla strada. Questo rende più difficile controllare il veicolo, specialmente in curva. Per guidare in sicurezza, devi andare più piano, quindi la velocità è limitata.', 'La parola ''limita'' è importante: significa che la velocità massima sicura diminuisce. ''In sicurezza'' sottolinea che è per evitare pericoli.', 'Meno aderenza = meno velocità in curva.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25186, 'Quando l''aderenza è bassa, le gomme scivolano più facilmente. In curva, questo significa che il veicolo può ''slittare'', cioè perdere il controllo e andare dritto o di traverso. Quindi, un''aderenza bassa favorisce, cioè aiuta, lo slittamento.', 'La parola ''favorisce'' indica che rende più probabile un evento. ''Slittamento'' significa scivolamento incontrollato.', 'Meno aderenza = più slittamento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25187, 'Se le gomme hanno poca aderenza, quando freni, ci vuole più tempo e più strada per fermare il veicolo. Questo perché le gomme non riescono a ''aggrapparsi'' bene all''asfalto per rallentare. Perciò, lo spazio di frenatura, cioè la distanza per fermarsi, aumenta.', 'La parola ''aumenta'' è fondamentale: significa che lo spazio necessario per frenare diventa più grande. ''Spazio di frenatura'' è la distanza per fermarsi.', 'Meno aderenza = più spazio per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25188, 'Con poca aderenza, una frenata improvvisa e forte (brusca) può far bloccare le ruote e far perdere il controllo del veicolo, rendendo la situazione molto pericolosa. È meglio frenare dolcemente e gradualmente.', 'Le parole ''pericolose'' e ''brusche'' sono chiavi. ''Brusche'' significa improvvise e forti.', 'Meno aderenza = no frenate brusche.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25189, 'Questa affermazione è falsa. Come abbiamo visto, un''aderenza bassa ti obbliga a ridurre la velocità, specialmente in curva o quando freni, per guidare in sicurezza. Quindi, condiziona eccome la velocità del veicolo!', 'La negazione ''non condiziona'' è la parola trappola. Significa ''non influenza''. Invece, l''aderenza bassa influenza molto la velocità.', 'Meno aderenza = sì, condiziona la velocità!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25190, 'Questa affermazione è falsa. È il contrario! Se l''aderenza è bassa, le gomme scivolano di più e ci vuole più strada per fermarsi. Quindi, lo spazio di frenatura aumenta, non si riduce.', 'La parola ''riduce'' è la trappola. Significa ''diminuisce''. Ricorda che con poca aderenza lo spazio di frenatura aumenta.', 'Meno aderenza = più spazio per frenare, non meno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25191, 'Questa affermazione è falsa. Il coefficiente di aderenza riguarda la ''presa'' delle gomme sulla strada e la sicurezza di guida. Non ha un effetto diretto e significativo sui consumi di carburante, che dipendono più dallo stile di guida e dal motore.', 'La frase ''diminuisce i consumi di carburante'' è un concetto estraneo all''aderenza. È una distrazione.', 'Aderenza = sicurezza, non carburante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25192, 'Questa affermazione è falsa. Se l''aderenza è bassa, le gomme fanno meno presa e quindi è più facile che il veicolo slitti in curva, non meno facile. Quindi, lo slittamento aumenta, non si riduce.', 'La parola ''riduce'' è la trappola. Significa ''diminuisce''. In realtà, con poca aderenza lo slittamento aumenta.', 'Meno aderenza = più slittamento, non meno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25193, 'Quando guidi un motociclo, devi fare molta attenzione alle rotaie (come quelle del tram o del treno). Sono fatte di metallo e, specialmente quando piove, diventano molto scivolose. La tua moto ha meno contatto con la strada rispetto a un''auto, quindi è più facile perdere l''equilibrio. Per questo, l''aderenza (la capacità delle gomme di ''aggrapparsi'' alla strada) diminuisce.', 'La parola ''specialmente'' ti fa capire che il pericolo è maggiore in caso di pioggia, ma le rotaie sono comunque un punto critico anche senza pioggia.', 'Rotaie + Pioggia = Scivolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25194, 'Le strisce bianche o gialle che vedi sull''asfalto (come gli attraversamenti pedonali o le linee di stop) sono fatte con vernici o materiali che sono più lisci dell''asfalto. Quando piove, queste strisce diventano molto scivolose per le gomme della moto. Per questo, l''aderenza diminuisce e devi fare attenzione.', 'Anche qui, ''in caso di pioggia'' evidenzia la condizione più pericolosa, ma le strisce sono sempre meno aderenti dell''asfalto normale.', 'Strisce bagnate = Attenzione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25195, 'Questa affermazione è falsa. L''aderenza delle gomme dipende moltissimo dal tipo di strada su cui guidi. L''asfalto, il cemento, la ghiaia, il pavé (strade con pietre) e anche se la strada è asciutta o bagnata, cambiano tutti la capacità delle gomme di fare presa. Dire che ''non dipende'' è sbagliato.', 'La parola ''non'' è la chiave. Se la frase fosse stata ''l''aderenza dipende dal tipo di pavimentazione'', sarebbe stata vera. Il ''non'' la rende falsa.', 'Aderenza = Tipo strada!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25196, 'Questa affermazione è falsa. Quando trasporti un passeggero, il peso totale della moto aumenta. Questo peso extra, in realtà, tende a ''schiacciare'' di più le gomme sull''asfalto, e questo generalmente aumenta l''aderenza. Certo, la moto si guida in modo diverso e lo spazio di frenata può cambiare, ma l''aderenza in sé non diminuisce, anzi, può migliorare.', 'La parola ''diminuisce'' è l''errore. Il peso aggiuntivo di un passeggero non riduce l''aderenza, ma cambia la dinamica di guida.', 'Più peso = Più aderenza (ma guida diversa)!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25197, 'La forza aderente è la capacità delle gomme di ''attaccarsi'' alla strada. Se la strada è sporca di olio, le gomme scivolano di più e quindi la forza aderente diminuisce. È come camminare su una buccia di banana!', 'La parola ''diminuisce'' è importante: significa che la forza aderente diventa minore. ''Sporca di olio'' indica una condizione di pericolo.', 'Olio = scivola, aderenza giù.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25198, 'Quando l''asfalto è asciutto e pulito, le gomme hanno il massimo contatto con la strada. Questo significa che la forza aderente è maggiore, e l''auto ha più stabilità e controllo.', 'Le parole ''maggiore'', ''asciutto'' e ''pulito'' indicano le condizioni ideali per una buona aderenza.', 'Asciutto e pulito = massima aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25199, 'Il ghiaccio rende la strada estremamente scivolosa. Le gomme non riescono a fare presa sull''asfalto, quindi la forza aderente diminuisce moltissimo, non aumenta. È molto pericoloso guidare sul ghiaccio.', 'La parola ''aumenta'' è la trappola qui. Il ghiaccio fa l''esatto contrario, riduce l''aderenza.', 'Ghiaccio = zero aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25200, 'Anche il fango, come il ghiaccio o l''olio, rende la strada scivolosa. Le gomme non riescono ad avere un buon contatto con l''asfalto, quindi la forza aderente diminuisce, non aumenta.', 'Ancora una volta, ''aumenta'' è la parola trappola. Il fango riduce la presa delle gomme.', 'Fango = poca aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25201, 'La pressione dei pneumatici è fondamentale per la forza aderente! Se la pressione è sbagliata (troppo alta o troppo bassa), la gomma non tocca bene la strada e l''aderenza diminuisce. Per questo è importante controllarla spesso.', 'La frase ''non dipende'' è la trappola. La forza aderente dipende eccome dalla pressione dei pneumatici!', 'Pressione giusta = aderenza perfetta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25202, 'Quando un veicolo gira in curva, c''è una forza che lo spinge sempre verso l''esterno della curva. È come quando giri velocemente e senti che vieni spinto fuori.', 'La frase ''assoggettato ad una forza'' significa che il veicolo subisce una forza. La parola chiave è ''verso l''esterno'', che indica la direzione della spinta.', 'In curva, la forza ti spinge SEMPRE FUORI.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25203, 'Se vai troppo veloce in curva, le ruote possono perdere aderenza con la strada e il veicolo può scivolare, cioè ''sbandare''. È molto pericoloso.', 'La parola ''eccessiva'' significa ''troppa''. ''Sbandamento'' è quando il veicolo perde il controllo e scivola lateralmente.', 'Troppa velocità in curva = sbandi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25204, 'Andare troppo veloce in curva può essere così pericoloso che il veicolo, specialmente se è alto o carico, può perdere l''equilibrio e capovolgersi, cioè ''ribaltarsi''.', 'Anche qui, ''eccessiva'' significa ''troppa''. ''Ribaltamento'' è quando il veicolo si capovolge.', 'Troppa velocità in curva = ti ribalti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25205, 'Questa affermazione è falsa. La forza che agisce sul veicolo in curva lo spinge sempre verso l''esterno, mai verso l''interno della curva.', 'La parola trappola è ''verso l''interno''. Ricorda che la forza centrifuga spinge sempre ''verso l''esterno''.', 'In curva, la spinta è FUORI, mai DENTRO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25206, 'Questa affermazione è falsa. Aumentare la velocità in curva è molto pericoloso perché aumenta il rischio di perdere aderenza e slittare, non lo evita. Bisogna sempre rallentare prima di una curva.', 'La frase ''aumentare la velocità'' è l''errore. Per ''evitare lo slittamento'' devi fare il contrario, cioè rallentare.', 'In curva, MAI aumentare la velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25207, 'Questa affermazione è falsa. Aumentare la velocità in curva è estremamente pericoloso e aumenta il rischio di ribaltarsi, non lo evita. È fondamentale ridurre la velocità prima di affrontare una curva.', 'Anche qui, ''aumentare la velocità'' è l''errore. Per ''evitare il ribaltamento'' devi rallentare, non accelerare.', 'In curva, MAI aumentare la velocità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25208, 'Se il carico è posizionato in alto, il centro di gravità del veicolo si alza. Questo rende il veicolo meno stabile e più facile da ribaltare, specialmente quando si affronta una curva.', 'La parola ''favorito'' significa ''reso più facile''. Quindi, un carico in alto rende più facile il ribaltamento.', 'Carico in alto = veicolo instabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25209, 'Se il carico non è ben fissato, si muove all''interno del veicolo, soprattutto in curva. Questo movimento improvviso sposta il peso e può far perdere l''equilibrio al veicolo, aumentando il rischio di ribaltamento.', 'L''espressione ''non stabilmente fissato'' indica che il carico non è sicuro e può muoversi liberamente.', 'Carico che si muove = pericolo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25210, 'Una carreggiata stretta significa che la distanza tra le ruote dello stesso asse è ridotta. Questo rende il veicolo meno stabile lateralmente, proprio come una sedia con le gambe troppo vicine, e quindi più propenso a ribaltarsi in curva.', 'Le espressioni ''ridotta distanza'' e ''carreggiata stretta'' sono sinonimi e indicano una minore stabilità del veicolo.', 'Carreggiata stretta = meno stabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25211, 'Una curva stretta (con un raggio di curvatura piccolo) richiede al veicolo di cambiare direzione più bruscamente. Questo genera una forza maggiore che spinge il veicolo verso l''esterno della curva, aumentando il rischio di ribaltamento.', 'Le espressioni ''raggio di curvatura piccolo'' e ''curva stretta'' sono sinonimi e indicano una curva più impegnativa e pericolosa.', 'Curva stretta = più rischio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25212, 'Questa affermazione è FALSA. Una carreggiata larga significa che le ruote dello stesso asse sono più distanti tra loro. Questo aumenta la stabilità del veicolo, rendendolo meno propenso a ribaltarsi, non il contrario.', 'La parola ''favorito'' è la chiave. Una ''ampia distanza'' o ''carreggiata larga'' *sfavorisce* il ribaltamento, non lo favorisce.', 'Carreggiata larga = più stabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25213, 'Questa affermazione è FALSA. Se il carico è posizionato in basso, il centro di gravità del veicolo si abbassa. Questo rende il veicolo più stabile e quindi meno facile da ribaltare in curva.', 'Anche qui, ''favorito'' è la parola trappola. Un carico in basso *sfavorisce* il ribaltamento, perché rende il veicolo più stabile.', 'Carico in basso = veicolo stabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25214, 'Questa affermazione è FALSA. Una curva larga (con un raggio di curvatura ampio) è meno impegnativa per il veicolo. La forza che spinge il veicolo verso l''esterno è minore, quindi è più difficile che si ribalti.', 'Le espressioni ''raggio di curvatura ampio'' e ''curva larga'' sono sinonimi. La domanda usa ''favorito'', ma una curva larga *riduce* il rischio di ribaltamento, non lo aumenta.', 'Curva larga = meno rischio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25215, 'Quando vai più veloce in curva, la macchina viene spinta verso l''esterno con più forza (forza centrifuga). Questa spinta può far sì che la macchina si inclini e si ribalti. Quindi, più è alta la velocità, più è grande la forza che può far ribaltare il veicolo.', 'La frase ''aumenta all''aumentare'' indica una relazione diretta. Non è una parola trappola, ma è importante capire che una cosa cresce con l''altra.', 'Velocità alta in curva = più forza ribaltante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25216, 'Questa affermazione è falsa. È il contrario! Se aumenti la velocità in curva, la forza che può far ribaltare il veicolo (forza ribaltante) non diminuisce, ma aumenta. Andare troppo veloci in curva è pericoloso proprio per questo motivo.', 'La parola trappola è ''diminuisce''. Fa pensare che il pericolo si riduca con l''aumento della velocità, ma è falso.', 'Velocità alta in curva = pericolo alto, non basso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25217, 'L''ABS (Sistema Antibloccaggio) è un sistema di sicurezza che, quando freni forte, evita che le ruote si fermino completamente (si blocchino). Questo ti permette di mantenere il controllo del veicolo e di sterzare anche durante una frenata di emergenza.', 'La parola ''impedisce'' significa che l''ABS non permette che le ruote si blocchino. È la sua funzione principale.', 'ABS = Anti Bloccaggio Ruote.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25218, 'Grazie all''ABS, le ruote non si bloccano del tutto. Questo significa che puoi ancora girare il volante e cambiare direzione (correggere la traiettoria) per evitare un ostacolo, anche mentre stai frenando molto forte.', 'La frase ''consente di correggere'' significa che l''ABS ti dà la possibilità di cambiare direzione. Non ti blocca la possibilità di sterzare.', 'ABS = Freno + Sterzo (contemporaneamente).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25219, 'L''ABS fa in modo che le ruote non si blocchino, ma continuino a girare un po''. Questo permette al pneumatico di ''aggrapparsi'' meglio all''asfalto, usando tutta la forza che può per fermare l''auto nel modo più efficace e nel minor spazio possibile.', 'La ''massima forza aderente'' è la migliore presa possibile tra la gomma e la strada. L''ABS aiuta a sfruttarla al massimo.', 'ABS = Massima aderenza in frenata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25220, 'L''ABS è un sistema intelligente che controlla ogni ruota separatamente. Se una ruota sta per bloccarsi, l''ABS agisce solo su quella ruota per farla girare un po'' di nuovo, senza bloccare le altre. Così la frenata è più stabile.', '''Di volta in volta'' significa che l''ABS interviene solo quando e dove serve, su ogni singola ruota.', 'ABS = Controllo singolo per ogni ruota.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25221, 'L''ABS funziona sempre, anche se le gomme sono un po'' vecchie o consumate. Certo, con gomme usurate la frenata sarà comunque meno efficace in generale, ma l''ABS farà comunque il suo lavoro per evitare il bloccaggio.', '''Anche quando'' indica che la condizione (pneumatici usurati) non impedisce il funzionamento dell''ABS. L''ABS è sempre attivo.', 'ABS funziona sempre, ma gomme buone sono meglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25222, 'L''ABS è molto utile proprio quando la strada è scivolosa, come sul bagnato. In queste condizioni, le ruote si bloccano più facilmente, e l''ABS aiuta a evitarlo, rendendo la frenata più sicura e controllabile.', '''Anche quando'' indica che la condizione (asfalto bagnato) non impedisce il funzionamento dell''ABS, anzi, lo rende ancora più importante.', 'ABS = Amico sul bagnato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25223, 'Questa domanda riassume il concetto principale dell''ABS. Non bloccando le ruote, l''ABS ti permette di mantenere il controllo del veicolo e di fermarti in modo più stabile, rendendo la frenata complessivamente più sicura.', '''Rende la frenata più sicura'' è il beneficio diretto dell''azione dell''ABS di impedire il bloccaggio delle ruote.', 'ABS = Sicurezza in frenata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25224, 'Questa affermazione è falsa perché l''ABS è stato creato proprio per EVITARE che le ruote si blocchino, non per aiutarle a bloccarsi. ''Anti-bloccaggio'' è nel suo nome!', 'La parola ''favorisce'' significa ''aiuta a''. È una parola trappola perché è l''esatto contrario di quello che fa l''ABS.', 'ABS = Anti-bloccaggio, non pro-bloccaggio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25225, 'Questa affermazione è falsa. L''ABS ti permette proprio di modificare la traiettoria (cioè di sterzare) mentre freni. Se le ruote si bloccassero, non potresti più sterzare e l''auto andrebbe dritta.', 'La frase ''impedisce di modificare'' è la trappola. L''ABS, al contrario, *permette* di modificare la traiettoria.', 'ABS = Sterzi anche frenando.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25226, 'Questa affermazione è falsa. L''ABS, al contrario, aiuta a usare la massima forza aderente tra le gomme e la strada. Se le ruote si bloccassero, l''aderenza sarebbe minore e la frenata meno efficace.', 'La frase ''impedisce di utilizzare'' è la trappola. L''ABS *consente* di utilizzare la massima forza aderente.', 'ABS = Massima aderenza, non minima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25227, 'Questa affermazione è falsa. L''ABS agisce su TUTTE le ruote del veicolo, sia quelle motrici (che danno la spinta) sia quelle non motrici, per garantire una frenata stabile e sicura su tutto il veicolo.', 'La parola ''non'' rende l''affermazione falsa. L''ABS agisce su tutte le ruote.', 'ABS = Tutte le ruote.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25228, 'Questa affermazione è falsa. L''ABS si attiva sempre quando serve, indipendentemente dallo stato degli pneumatici. Certo, con gomme usurate la frenata sarà meno efficace in generale, ma l''ABS farà comunque il suo lavoro per evitare il bloccaggio.', 'La frase ''non si attiva se'' è la trappola. L''ABS si attiva sempre, anche con pneumatici usurati.', 'ABS = Funziona sempre, anche con gomme usurate.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25229, 'È vero. Controllare la pressione delle gomme è molto importante per la tua sicurezza e per non rovinare i pneumatici. Non dimenticare di controllare anche la ruota di scorta, così è sempre pronta se ti serve.', 'La parola ''periodicamente'' significa ''ogni tanto, regolarmente''. ''Compresa quella della ruota di scorta'' è un dettaglio importante che spesso si dimentica.', 'Pressione = Sicurezza. Controlla anche la scorta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25230, 'È vero. Se il veicolo è più pesante (per esempio, hai molti bagagli o passeggeri), le gomme devono avere una pressione un po'' più alta. Questo aiuta a sostenere meglio il peso e a mantenere il veicolo stabile.', 'La frase ''va adeguata alle condizioni di peso'' significa che la pressione non è sempre la stessa, ma cambia in base a quanto è carico il veicolo.', 'Più peso = più pressione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25231, 'È vero. Il ''carico'' (cioè i bagagli o le cose che trasporti) e il ''numero dei passeggeri'' aumentano il peso totale del veicolo. Per questo, la pressione delle gomme deve essere regolata per sopportare questo peso extra e garantire una guida sicura.', 'La parola ''dipende'' indica che la pressione non è fissa, ma cambia in base a questi fattori.', 'Carico e passeggeri cambiano la pressione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25232, 'È vero. Se la gomma è sgonfia (pressione insufficiente), tocca di più la strada. Questo aumenta l''attrito (la ''resistenza'' al movimento), il motore deve fare più fatica, consuma più benzina e la gomma si usura più velocemente.', 'Le parole ''insufficiente pressione'' sono la causa. ''Aumentare l''attrito'' e ''anche i consumi di carburante'' sono le conseguenze negative.', 'Gomma sgonfia = più attrito, più benzina.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25233, 'È vero. Quando la gomma è calda (dopo aver guidato), l''aria al suo interno si espande e la pressione sembra più alta di quella reale. Per avere una misurazione precisa e sapere la vera pressione, devi controllare quando la gomma è fredda, cioè quando non hai guidato per un po''.', 'La frase chiave è ''quando la gomma è fredda''. Questo è il momento giusto per misurare.', 'Pressione si misura a freddo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25234, 'È vero. Questo sistema (chiamato TPMS) ti avvisa se una gomma si sta sgonfiando. Così puoi intervenire subito, evitando problemi di guida o incidenti. Questo rende la guida più sicura.', 'Il ''sistema automatico di rilevamento'' è una tecnologia che ''fa aumentare la sicurezza''.', 'TPMS = più sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25235, 'È falso. Come abbiamo detto, quando la gomma è calda, l''aria al suo interno si espande e la pressione che misuri è più alta di quella reale. Quindi, la lettura non è corretta e non ti dà il valore giusto.', 'Le parole ''quando la gomma è calda'' e ''corretta lettura'' sono in contraddizione. Se è calda, la lettura non è corretta.', 'Caldo = lettura sbagliata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25236, 'È falso. Questo è l''esatto contrario di quello che si deve fare! La pressione va controllata a freddo, non dopo aver guidato o quando la gomma è calda. Misurare a caldo ti darebbe un valore sbagliato.', 'Le frasi ''dopo aver percorso alcuni chilometri'' e ''appena la gomma si è surriscaldata'' indicano le condizioni sbagliate per il controllo.', 'Mai a caldo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25237, 'È falso. La pressione delle gomme dipende dal tipo di veicolo, dal suo peso e dal numero di passeggeri, non dal materiale dei cerchioni (che sono la parte metallica della ruota). I cerchioni supportano la gomma, ma non influenzano la pressione interna.', 'La frase ''in base al materiale con cui sono realizzati i cerchioni'' è la parte sbagliata della domanda.', 'Cerchioni non contano per la pressione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25238, 'È falso. Non si deve ''aumentare'' la pressione in modo generico. Si deve ''adeguare'' la pressione al carico previsto per il viaggio. Se il veicolo è più carico (più bagagli, più passeggeri), allora sì, la pressione va aumentata un po'' rispetto al valore normale. Ma se il carico è leggero o normale, non si aumenta. Una pressione eccessiva è pericolosa quanto una insufficiente.', 'La parola ''aumentare'' è la trappola. Non è un aumento automatico, ma un ''adeguamento'' al carico.', 'Non ''aumentare'', ma ''adeguare al carico''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25239, 'È falso. Il veicolo che traina (l''auto) e il rimorchio sono due mezzi diversi, con pesi, carichi e spesso tipi di gomme diversi. Per questo, anche le pressioni di gonfiaggio saranno diverse e devono essere controllate separatamente, seguendo le indicazioni del produttore per ciascuno.', 'La parola ''uguale'' è la trappola. Le pressioni non sono uguali.', 'Auto e rimorchio: pressioni diverse.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25240, 'È vero. La legge stabilisce che il battistrada degli pneumatici di un autoveicolo (come un''auto) non deve essere più basso di 1,6 millimetri. Questo spessore è importante per la sicurezza, specialmente quando piove, per garantire una buona aderenza alla strada.', 'La parola ''minimo'' è fondamentale: indica il limite più basso consentito. Non si può scendere sotto questo valore.', 'Auto = 1,6 mm minimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25241, 'È vero. Anche se gli pneumatici non sembrano consumati, la gomma invecchia con il tempo. Dopo alcuni anni, la gomma può diventare più dura e perdere elasticità, riducendo l''aderenza e la sicurezza. Per questo è consigliabile cambiarli.', 'La frase ''anche se non sono consumati'' è la chiave. Non è solo l''usura visibile a contare, ma anche l''età della gomma. ''Consigliabile'' significa che è una buona pratica per la sicurezza, non un obbligo legale basato solo sull''età.', 'Gomme: non solo usura, ma anche età!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25242, 'È vero. Per i motocicli, la legge prevede uno spessore minimo del battistrada di 1,0 millimetri. È un valore diverso rispetto alle auto, ma altrettanto importante per la sicurezza.', 'Anche qui, ''minimo'' indica il limite legale. È importante distinguere i valori per auto e moto.', 'Moto = 1,0 mm minimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25243, 'È vero. Se un chiodo si conficca in uno pneumatico ''tubeless'' (senza camera d''aria), l''aria esce lentamente. Questo ti permette di guidare con prudenza per un breve tratto, fino a un luogo sicuro o da un gommista, per far riparare il danno senza fermarti in un posto pericoloso.', 'Le parole ''con le necessarie cautele'' e ''quanto prima'' sono importanti. Non significa che puoi guidare a lungo o velocemente, ma che hai il tempo di raggiungere un posto sicuro per la riparazione.', 'Chiodo tubeless: piano fino al gommista.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25244, 'È falso. Gli pneumatici ''tubeless'' possono essere riparati in diversi modi da un professionista, non ''solo'' con le bombolette. Le bombolette sono una soluzione temporanea per emergenze, ma non l''unico metodo di riparazione e spesso non quello definitivo.', 'La parola ''solo'' è una parola trappola molto comune. Spesso, quando vedi ''solo'', ''sempre'', ''mai'', ''esclusivamente'', la risposta è falsa perché di solito ci sono più opzioni o eccezioni.', '''Solo'' = Attenzione, spesso FALSO!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25245, 'È vero. La caratteristica principale degli pneumatici ''tubeless'' è che, in caso di foratura, l''aria non esce di colpo ma ''lentamente''. Questo ti dà il tempo di accorgerti del problema e di fermarti in sicurezza.', 'La parola ''lentamente'' è la chiave per capire il vantaggio del tubeless in caso di foratura.', 'Tubeless = sgonfiaggio lento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25246, 'È falso. Gli pneumatici con ''camera d''aria'' (il tipo più vecchio) si sgonfiano molto rapidamente e improvvisamente in caso di foratura. Questo può essere pericoloso perché si perde subito il controllo del veicolo.', 'La parola ''lentamente'' è la trappola qui. È l''opposto di ciò che accade con una camera d''aria, che si sgonfia ''rapidamente''.', 'Camera d''aria = sgonfiaggio RAPIDO.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25247, 'È falso. Se estrai subito il chiodo da un tubeless, l''aria uscirà più velocemente. È meglio lasciarlo dentro e andare con cautela dal gommista. Lo pneumatico non esplode per un chiodo, ma si sgonfia.', 'Le frasi ''estrarlo subito'' e ''possa esplodere'' sono trappole. Estrarlo subito peggiora la situazione, e l''esplosione è un''esagerazione non vera.', 'Chiodo tubeless: NON togliere subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25248, 'È falso. La pressione di gonfiaggio raccomandata per gli pneumatici è la stessa, sia che siano gonfiati con aria compressa che con azoto. L''azoto ha altri vantaggi (come una minore variazione di pressione con la temperatura), ma non cambia la pressione consigliata.', 'La frase ''minore pressione'' è l''errore. La pressione deve essere quella indicata dal costruttore, indipendentemente dal gas usato.', 'Azoto o aria = stessa pressione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25249, 'Gli pneumatici chiodati sono speciali e si possono usare solo in un periodo specifico dell''anno, di solito in inverno (dal 15 novembre al 15 marzo), quando c''è neve o ghiaccio. Non si possono usare sempre.', 'La frase chiave è ''limitatamente ad un predeterminato periodo''. Significa che c''è un limite di tempo, non si possono usare tutto l''anno.', 'Chiodati = solo in inverno, per legge.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25250, 'Per avere la massima sicurezza e stabilità quando guidi con neve o ghiaccio, è sempre meglio montare i pneumatici invernali su tutte e quattro le ruote. Così l''auto frena e sterza meglio.', 'La parola ''consigliabile'' indica che è una buona pratica per la sicurezza, anche se non sempre obbligatoria per legge su tutte le ruote.', 'Invernali = tutte le ruote per massima sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25251, 'Le catene da neve devono essere ''omologate'', cioè devono avere un marchio che certifica che sono state testate e sono sicure. Se usi catene senza questa certificazione, è come se non le avessi e puoi prendere una multa.', 'La parte importante è ''non omologate''. Significa che non sono approvate e non rispettano le norme di sicurezza.', 'Catene = sempre omologate, altrimenti multa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25252, 'Per garantire la stabilità e la sicurezza del veicolo, gli pneumatici chiodati, proprio come quelli invernali, devono essere montati su tutte e quattro le ruote, non solo su due.', 'La frase ''solo su due ruote dello stesso asse'' è la parte che rende la risposta FALSO. Devono essere su tutte e quattro.', 'Chiodati = tutte e quattro le ruote.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25253, 'Nei veicoli 4x4, le catene da neve vanno montate sulle ruote che danno la trazione principale. Questo può essere l''asse anteriore, o tutte e quattro le ruote, a seconda del modello del veicolo. Non è corretto dire che vanno montate ''solo'' sulle ruote posteriori.', 'La parola ''solo'' rende la frase falsa. Non è detto che siano sempre e solo le posteriori.', '4x4 catene = sull''asse motore principale (spesso anteriore), non solo posteriori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25254, 'Le catene da neve sono fatte per essere usate solo su neve o ghiaccio. Se le usi su strada asciutta, senza neve, possono rovinare l''asfalto, le catene stesse, le gomme, i cerchioni e anche le sospensioni dell''auto a causa delle forti vibrazioni.', 'La frase ''non si danneggiano'' è la parte sbagliata. In realtà, si danneggiano eccome!', 'Catene = solo su neve, mai su asfalto asciutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25255, 'I veicoli con pneumatici invernali (M+S) non devono per forza rispettare limiti di velocità inferiori a quelli normali. Questo succede solo se l''indice di velocità del pneumatico invernale è più basso di quello indicato sul libretto dell''auto. Molti pneumatici invernali hanno indici di velocità adeguati alle velocità ordinarie.', 'La frase ''devono rispettare limiti di velocità massima inferiori a quelli ordinari'' è troppo generale. Non è sempre vero per tutti i pneumatici invernali. Dipende dall''indice di velocità specifico del pneumatico.', 'Invernali = velocità normale, a meno che l''indice del pneumatico sia più basso (e c''è un adesivo).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25256, 'È fondamentale per la tua sicurezza e per la stabilità del veicolo che il terreno sia piatto e fermo. Così eviti che l''auto si muova o cada mentre lavori.', 'La parola ''conviene'' indica che questa è la scelta migliore e più sicura da fare.', 'Terreno piatto e stabile = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25257, 'Queste azioni bloccano il veicolo e impediscono che si muova accidentalmente mentre lo sollevi con il martinetto. È una misura di sicurezza indispensabile.', 'La parola ''bisogna'' sottolinea che è un''azione obbligatoria per la tua sicurezza.', 'Freno a mano + marcia = veicolo bloccato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25258, 'È molto più facile allentare i bulloni quando la ruota è ancora a terra e può fare presa. Se provi ad allentarli dopo aver sollevato il veicolo, la ruota potrebbe girare a vuoto e faresti più fatica.', 'Ricorda ''leggermente'': non devi toglierli del tutto, solo allentarli un po''. ''Conveniente'' significa che è la procedura migliore.', 'Bulloni: prima allenti (a terra), poi sollevi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25259, 'Il martinetto (cric) può cedere e il veicolo potrebbe cadere. Mettersi sotto il veicolo è estremamente pericoloso e può causare gravi infortuni.', 'La parola ''evitare'' significa che è un divieto assoluto per la tua incolumità.', 'Sotto il veicolo MAI, è pericoloso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25260, 'Stringere completamente i bulloni a veicolo sollevato è difficile e meno sicuro. La stretta finale, quella forte, si fa a terra per garantire il massimo serraggio e la stabilità della ruota.', 'La sequenza è importante: ''stringere leggermente'' a veicolo sollevato e ''completarne il bloccaggio solo dopo averlo abbassato''.', 'Bulloni: prima avviti (sollevato), poi stringi forte (a terra).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25261, 'I passeggeri potrebbero essere in pericolo se il veicolo si muove o se c''è traffico. È molto più sicuro che stiano in un luogo protetto, lontano dalla strada.', 'La parola ''opportuno'' indica che è una buona e saggia pratica per la sicurezza di tutti. ''Fuori dalla carreggiata'' è il luogo sicuro.', 'Passeggeri fuori, sicurezza prima di tutto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25262, 'No, non devi togliere i bulloni prima di sollevare il veicolo! Devi solo allentarli leggermente (come abbiamo visto nella domanda 25258). Se li togli, la ruota potrebbe cadere o il veicolo perdere stabilità.', 'La trappola è ''togliere i bulloni''. Ricorda: vanno solo allentati, non tolti del tutto, prima di sollevare.', 'Bulloni: prima allenti, poi sollevi, MAI togliere prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25263, 'Assolutamente no! Il martinetto deve essere posizionato in punti specifici e rinforzati del telaio, indicati nel manuale del veicolo. Metterlo in un punto qualsiasi può danneggiare l''auto o, peggio, far cadere il veicolo.', 'La trappola è ''in un punto qualsiasi''. Non è un punto a caso, ma uno specifico e sicuro.', 'Cric: punto specifico, MAI a caso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25264, 'È il contrario! Il martinetto va posizionato vicino alla ruota che devi sostituire, nei punti indicati dal costruttore. Posizionarlo lontano sarebbe inutile o addirittura pericoloso perché non solleverebbe correttamente la parte interessata.', 'La trappola è ''il più lontano possibile''. Ricorda che deve essere posizionato vicino alla ruota.', 'Cric: vicino alla ruota, non lontano.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25265, 'Falso! Il ruotino è una soluzione temporanea e ha limiti di velocità molto inferiori, solitamente 80 km/h. Non è progettato per alte velocità o lunghe distanze.', 'La trappola è ''120 km/h''. Ricorda che la velocità massima consentita con il ruotino è molto più bassa.', 'Ruotino: velocità ridotta, MAI 120 km/h.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25266, 'No, è consentito trasportare passeggeri, ma devi guidare con maggiore prudenza e rispettare i limiti di velocità e distanza imposti dal ruotino. Non è un divieto assoluto.', 'La trappola è ''non è consentito trasportare passeggeri''. In realtà, è consentito, ma con molta cautela.', 'Ruotino: passeggeri sì, ma con prudenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25267, 'Quando freni forte e l''ABS si attiva, devi continuare a premere il pedale del freno con tutta la forza. L''ABS ti aiuta a non bloccare le ruote, quindi non devi togliere il piede o diminuire la pressione. Devi solo premere forte e lasciare che il sistema faccia il suo lavoro.', 'La frase chiave è ''senza allentare la pressione''. Significa che non devi diminuire la forza con cui premi il pedale.', 'ABS = Piede forte, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25268, 'Il motore può aiutare a rallentare il veicolo, specialmente in discesa. Questa si chiama ''frenata di motore''. Più la marcia è bassa (come la prima marcia), più il motore ''trattiene'' l''auto e la rallenta. È come se il motore facesse più fatica a girare e quindi frena di più.', 'La parola ''massima'' indica che la prima marcia offre il maggiore aiuto dal motore per frenare.', 'Marcia bassa = Freno motore massimo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25269, 'Se usi i freni troppo spesso o per molto tempo, ad esempio in una lunga discesa, questi si scaldano molto (surriscaldamento). Quando i freni sono troppo caldi, non funzionano più bene come dovrebbero, la loro capacità di frenare diminuisce. Questo è molto pericoloso perché l''auto frena meno efficacemente.', 'La frase ''diminuzione dell''efficienza frenante'' è il punto cruciale. Significa che i freni funzionano peggio.', 'Freni caldi = Freni deboli.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25270, 'Quando scendi da una strada lunga e ripida, è importante mettere una marcia bassa. In questo modo, il motore aiuta a rallentare l''auto (freno motore) e tu non devi usare i freni a pedale troppo spesso. Così eviti che i freni si surriscaldino e perdano efficienza.', 'L''obiettivo è ''evitare di surriscaldare i freni''. La marcia bassa è la soluzione.', 'Discesa ripida + Marcia bassa = Freni salvi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25271, 'Dopo aver lavato l''auto, l''acqua può bagnare i dischi o i tamburi dei freni. I freni bagnati non funzionano bene all''inizio. Fare una piccola prova di frenata a bassa velocità aiuta ad asciugarli e a controllare che funzionino correttamente prima di ripartire normalmente.', 'La parola ''opportuno'' significa che è una buona pratica, è consigliabile farlo.', 'Lavaggio = Freni bagnati = Prova per asciugare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25272, 'Questa affermazione è falsa. In caso di frenata di emergenza con l''ABS attivo, devi continuare a premere il pedale del freno con la massima forza. Non devi diminuire la pressione, altrimenti l''ABS non può lavorare al meglio e la frenata sarà meno efficace. L''ABS è fatto per permetterti di frenare forte senza bloccare le ruote.', 'La frase ''diminuire la pressione'' è la parola trappola. È l''azione sbagliata da fare con l''ABS.', 'ABS = Pressione costante e forte.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25273, 'Questa affermazione è falsa. Tutti i veicoli hanno il freno di stazionamento (il ''freno a mano''), ma non tutti si azionano con un comando manuale, cioè con una leva. Molti veicoli moderni hanno un freno di stazionamento elettronico, che si attiva premendo un pulsante.', 'Le parole ''Tutti i veicoli'' e ''comando manuale'' insieme rendono la frase falsa. Non tutti i comandi sono manuali.', 'Non tutti i freni a mano sono a leva!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25274, 'Questa affermazione è falsa. Il freno di stazionamento (freno a mano) serve per tenere fermo il veicolo quando è parcheggiato o in sosta. Non si deve usare per frenare mentre l''auto è in movimento, perché potrebbe bloccare le ruote posteriori e farti perdere il controllo del veicolo. Per frenare in marcia si usa il pedale del freno.', 'La frase ''durante la marcia'' è la parola trappola. Il freno di stazionamento non si usa mai mentre si guida.', 'Freno a mano = Solo da fermo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25275, 'Questa affermazione è falsa e molto pericolosa! Andare in folle (con il cambio in folle) in una lunga e ripida discesa è estremamente rischioso. L''auto prende troppa velocità e non hai il controllo del motore. Non si risparmia carburante in folle, anzi, il motore consuma per rimanere acceso. Inoltre, dovresti usare i freni a pedale molto di più, facendoli surriscaldare e diminuendo la loro efficienza. Devi sempre tenere una marcia inserita (bassa) per usare il freno motore e controllare la velocità.', 'Le parole ''cambio in folle'' e ''risparmiare carburante e freni'' sono le trappole. Entrambe le azioni sono sbagliate e pericolose in discesa.', 'Folle in discesa = Pericolo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25276, 'Se c''è un rischio di incendio dopo un incidente, spegnere il quadro elettrico è fondamentale. Questo interrompe l''alimentazione elettrica e riduce la possibilità di scintille che potrebbero causare o alimentare le fiamme.', 'La parola ''opportuno'' significa che è la cosa giusta e saggia da fare in quella situazione.', 'Rischio incendio? Via la corrente!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25277, 'In caso di un piccolo incendio e se non hai un estintore, gettare sabbia o terra alla base delle fiamme può aiutare a spegnerle. Questo perché la sabbia o la terra tolgono l''ossigeno, che è necessario al fuoco per bruciare.', 'La frase ''in mancanza di estintore'' indica che è una soluzione di emergenza, non la prima scelta.', 'Senza estintore, soffoca con terra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25278, 'Anche una coperta bagnata può essere usata per soffocare un principio d''incendio, togliendo l''ossigeno alle fiamme. L''acqua sulla coperta aiuta anche a raffreddare la zona.', 'Ancora una volta, ''in mancanza di estintore'' sottolinea che è un metodo alternativo in caso di necessità.', 'Coperta bagnata = Fuoco spento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25279, 'Svuotare il serbatoio del carburante durante un incendio è estremamente pericoloso. Il carburante potrebbe spargersi e alimentare ancora di più le fiamme, o addirittura esplodere. Non è una procedura sicura da fare in emergenza.', 'La parola ''immediatamente'' rende l''azione ancora più rischiosa e sbagliata. Non si deve mai tentare di svuotare un serbatoio in fiamme.', 'Mai svuotare serbatoi in fiamme!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25280, 'L''interruttore inerziale è un dispositivo di sicurezza. In caso di incidente, blocca automaticamente il flusso di carburante al motore. Questo serve proprio a RIDURRE il rischio di incendio, non ad aumentarlo.', 'La parola ''maggiore'' è la trappola qui. L''interruttore inerziale fa esattamente il contrario, diminuisce il rischio.', 'Interruttore inerziale = Più sicurezza, meno fuoco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25281, 'Smontare il serbatoio del GPL (o di qualsiasi altro carburante) durante un incendio è estremamente pericoloso. Potrebbe causare esplosioni o fughe di gas incontrollate. Questa operazione deve essere fatta solo da personale specializzato e in condizioni di sicurezza, non in emergenza.', 'Le parole ''smontare subito il serbatoio'' indicano un''azione pericolosa e non appropriata in una situazione di emergenza con incendio.', 'Non toccare serbatoi GPL in fiamme!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25282, 'È vero che non bisogna mettere oggetti sotto il sedile del conducente. Se scivolano, possono finire sotto i pedali e impedirti di frenare o accelerare, creando una situazione molto pericolosa.', 'La parola ''sconsigliabile'' significa che è meglio non farlo, perché è pericoloso. ''Intralciare'' significa ostacolare, bloccare.', 'Spazio libero sotto i pedali: la sicurezza prima di tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25283, 'È vero. Non puoi tenere il telefono in mano mentre guidi. Devi usare il viva-voce o l''auricolare per parlare, così le tue mani restano libere per il volante.', '''Senza l''ausilio'' significa ''senza l''aiuto di''. ''Vietato'' significa proibito, non permesso.', 'Mani sul volante, non sul cellulare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25284, 'È vero. Quando ci sono bambini in auto, è una buona idea attivare la sicurezza per le portiere posteriori. Così i bambini non possono aprirle da soli mentre l''auto è in movimento.', '''Consigliabile'' significa che è una buona pratica, è utile farlo. ''Impedisce l''apertura'' significa che blocca la possibilità di aprire.', 'Bambini a bordo? Blocco portiere!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25285, 'È vero. Il climatizzatore non serve solo per il freddo d''estate. In inverno, aiuta a togliere l''umidità dall''aria e a sbrinare più velocemente il parabrezza appannato o ghiacciato.', '''Anche nel periodo invernale'' è importante, perché molti pensano che serva solo d''estate. ''Sbrinare'' significa togliere il ghiaccio o l''appannamento.', 'Clima: freddo d''estate, sbrina d''inverno!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25286, 'È falso. Non è permesso usare il cellulare per scrivere messaggi mentre guidi. Anche se hai il viva-voce, digitare distrae molto e ti impedisce di concentrarti sulla strada.', '''Consentito'' significa permesso. ''Comporre sms'' significa scrivere un messaggio.', 'SMS? Solo da fermo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25287, 'È falso. Non devi programmare il navigatore mentre l''auto è in movimento. È molto pericoloso perché ti distrae dalla guida. Devi farlo prima di partire o quando sei fermo in sicurezza.', '''Devono essere programmati'' è una frase forte che indica un obbligo. ''Mentre il veicolo è in movimento'' è la condizione che rende la frase falsa.', 'Navigatore? Programma da fermo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25288, 'È falso. I pannelli a messaggio variabile non danno solo informazioni di pericolo. Possono anche mostrare segnali di obbligo o divieto, come limiti di velocità o chiusure di corsie, e questi segnali hanno valore legale.', 'La parte ''ma non possono avere valore prescrittivo'' è la trappola. ''Prescrittivo'' significa che impone una regola, un obbligo o un divieto.', 'Pannelli variabili: non solo info, anche regole!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25289, 'È falso. Se la strada è bagnata e l''auto davanti ti sporca il parabrezza, non devi sorpassarla subito. È pericoloso perché la visibilità è ridotta e la strada è scivolosa. Devi mantenere la distanza di sicurezza e usare i tergicristalli.', 'La parola ''immediatamente'' è la trappola. In situazioni di scarsa visibilità o pericolo, agire ''immediatamente'' con un sorpasso è quasi sempre sbagliato.', 'Acqua sul parabrezza? Distanza e tergicristallo, non sorpasso!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25290, 'Se metti adesivi, ciondoli o altri oggetti sui vetri dell''auto, questi possono coprire una parte della tua visuale. Questo rende più difficile vedere bene la strada e gli altri veicoli, aumentando il rischio di incidenti. Per questo è VERO.', 'La frase ''possono ridurre'' indica una possibilità, non una certezza assoluta, ma è un rischio concreto per la sicurezza. Anche un piccolo oggetto può distrarre o coprire un punto importante.', 'Vetri liberi = visibilità chiara.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25291, 'Avere i vetri puliti e trasparenti è fondamentale per guidare in sicurezza. Se i vetri sono sporchi o opachi, non puoi vedere bene cosa succede fuori dall''auto, specialmente in condizioni di luce scarsa o pioggia. Per questo è VERO.', 'Il termine ''garantiscono'' sottolinea l''importanza di questa condizione per la sicurezza. È un requisito base per una buona visibilità.', 'Vetri puliti = guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25292, 'Le spazzole del tergicristallo sono essenziali per pulire il parabrezza quando piove o c''è sporco. Se sono vecchie, rotte o consumate, non puliscono bene e lasciano aloni, riducendo la tua visibilità. Per la tua sicurezza, devi controllarle e cambiarle se necessario. Per questo è VERO.', 'La frase ''Occorre verificare... per sostituirle se sono consumate'' indica una manutenzione necessaria e periodica per mantenere l''efficienza del veicolo e la sicurezza.', 'Spazzole ok = pioggia non fa paura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25293, 'Il serbatoio del lavacristallo deve contenere sempre il liquido apposito per pulire i vetri. Se finisce, non puoi lavare il parabrezza da polvere, insetti o fango, e la tua visibilità sarà compromessa. È una buona abitudine controllare spesso il livello. Per questo è VERO.', 'La parola ''sempre'' evidenzia l''importanza di avere costantemente il liquido disponibile per ogni evenienza, non solo quando si parte per un lungo viaggio.', 'Liquido lavavetri = vetri sempre puliti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25294, 'Se il parabrezza è rotto o ha una crepa, il nastro adesivo non è una soluzione sicura e non ripara il danno in modo adeguato. Il vetro potrebbe rompersi del tutto, o la visibilità potrebbe essere compromessa. Devi portare l''auto da un professionista per una riparazione o sostituzione. Per questo è FALSO.', 'La trappola è ''ripararlo con del nastro adesivo trasparente''. Il nastro adesivo non ha la resistenza e la sicurezza necessarie per un vetro del veicolo.', 'Vetro rotto? Dal meccanico, non col nastro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25295, 'Il dispositivo di disappannamento serve a togliere la condensa (l''appannamento) dai vetri, che si forma per l''umidità o la differenza di temperatura. Se il parabrezza è coperto dalla polvere, devi usare il lavacristallo con le spazzole, non il disappannamento. Per questo è FALSO.', 'La parola chiave è ''dispositivo di disappannamento''. Questo sistema ha una funzione specifica (contro l''appannamento), non è per la polvere.', 'Disappannamento = condensa. Polvere = lavavetri.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25296, 'È vero. Per la tua sicurezza e per essere in regola con la legge, devi usare solo pneumatici che hanno le dimensioni approvate per il tuo veicolo. Non puoi montare gomme di misure diverse.', 'La parola ''esclusivamente'' qui è corretta, perché non ci sono altre opzioni: devi usare solo quelle approvate.', 'Omologazione = Sicurezza e Legge.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25297, 'È vero. Per guidare in sicurezza, le due gomme sullo stesso asse (ad esempio, le due gomme davanti o le due gomme dietro) devono essere identiche. Devono avere la stessa marca, lo stesso tipo e lo stesso disegno del battistrada. Questo garantisce che il veicolo sia stabile e abbia una buona aderenza.', 'La parola ''uguali'' è fondamentale. Non basta che siano della stessa misura, devono essere proprio identiche per tipo e disegno.', 'Stesso asse = Stessi pneumatici.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25298, 'È vero. Non devi controllare solo la parte che tocca la strada (il battistrada), ma anche i lati del pneumatico. Tagli, rigonfiamenti o crepe sui lati possono essere molto pericolosi e causare lo scoppio improvviso della gomma.', 'La frase ''anche sui lati'' ti ricorda che il controllo deve essere completo, non solo sulla parte centrale.', 'Controlla tutto il pneumatico, anche i lati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25299, 'È vero. La pressione giusta degli pneumatici è molto importante per la tua sicurezza. Se la pressione è quella consigliata dal produttore del veicolo, le gomme aderiscono bene alla strada e il veicolo è stabile. Trovi i valori corretti nel libretto di uso e manutenzione o su un adesivo all''interno della portiera.', 'La frase ''consigliata dalla casa costruttrice'' indica la fonte più affidabile per la pressione corretta.', 'Pressione = Casa costruttrice.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25300, 'È vero. Se la pressione di gonfiaggio è troppo bassa, il pneumatico si ''schiaccia'' di più e la parte centrale si solleva leggermente. Di conseguenza, i bordi del pneumatico toccano di più la strada e si consumano più velocemente del centro.', 'La frase ''ai bordi'' è la chiave per capire l''effetto della bassa pressione.', 'Pressione bassa = Consumo ai bordi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25301, 'È falso. È una buona pratica invertire la posizione degli pneumatici (ad esempio, spostare quelli anteriori dietro e viceversa) ogni tanto. Questo serve proprio a farli consumare in modo più uniforme e a farli durare più a lungo, non a ''non adattarsi''.', 'La frase ''Non bisogna mai'' è una parola trappola comune. Spesso, le affermazioni assolute (mai, sempre, solo) sono false. Anche ''permettere loro di adattarsi meglio'' è una motivazione sbagliata.', 'Invertire = Usura uniforme.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25302, 'È falso. Devi controllare la pressione di gonfiaggio di TUTTI gli pneumatici, non solo di quelli delle ruote motrici (quelle che danno la spinta al veicolo). Anche le ruote non motrici sono fondamentali per la stabilità e la sicurezza del veicolo.', 'La parola ''solo'' è la trappola. Indica una limitazione che non è vera in questo contesto di sicurezza.', 'Tutte le ruote contano!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25303, 'È falso. Diminuire la pressione di gonfiaggio fa sì che il pneumatico si deformi di più mentre gira, aumentando l''attrito con la strada e, di conseguenza, la temperatura. Quindi, una pressione bassa fa surriscaldare il pneumatico, non lo raffredda.', 'La frase ''diminuire la pressione di gonfiaggio'' è l''azione sbagliata per l''obiettivo indicato. Ha l''effetto opposto.', 'Pressione bassa = Più calore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25304, 'È falso. Come abbiamo visto, la pressione troppo bassa provoca un consumo anomalo SOLO ai bordi del pneumatico. Il consumo della parte centrale è causato da una pressione TROPPO ALTA. Questa domanda mescola due effetti diversi, rendendola falsa.', 'La congiunzione ''e'' che unisce ''parte centrale'' e ''bordi'' è la trappola. La bassa pressione consuma solo i bordi.', 'Bassa = Bordi. Alta = Centro. Mai entrambi!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25305, 'Il servofreno è un sistema che aiuta il conducente a frenare con meno forza sul pedale. È molto comune nei veicoli moderni per rendere la guida più comoda e sicura.', 'La parola ''spesso'' indica che è una caratteristica comune, ma non obbligatoria per tutti i veicoli.', 'Servofreno = meno fatica per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25306, 'Quando freni, le pastiglie o le ganasce sfregano contro i dischi o i tamburi. Questo sfregamento (attrito) trasforma l''energia del movimento (energia cinetica) in calore, rallentando il veicolo fino a fermarlo.', 'Ricorda che l''''energia cinetica'' è l''energia del movimento. L''''attrito'' è la forza che si oppone al movimento e genera calore.', 'Freno = attrito = calore = stop.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25307, 'Le guarnizioni di attrito (cioè le pastiglie o le ganasce dei freni) sono le parti che sfregano direttamente contro i dischi o i tamburi. Per questo motivo, sono quelle che si scaldano di più durante la frenata.', 'L''espressione ''maggiormente sollecitate'' significa che sono le parti che subiscono il maggiore stress o sforzo a causa delle alte temperature.', 'Guarnizioni = sfregamento = più calore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25308, 'Il freno di stazionamento, o freno a mano, serve principalmente per tenere fermo il veicolo quando è parcheggiato. In caso di emergenza, se il freno a pedale non funziona, può essere usato con molta cautela per rallentare il veicolo.', 'La frase ''deve essere utilizzato'' indica l''uso corretto. ''o per situazioni di emergenza'' aggiunge un uso secondario ma importante.', 'Freno a mano = sosta + emergenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25309, 'Il liquido dei freni è essenziale per il corretto funzionamento dell''impianto frenante. Se il livello è troppo basso, i freni potrebbero non funzionare bene o per niente. Per questo, è importante controllarlo regolarmente.', 'La parola ''periodicamente'' significa che il controllo deve essere fatto a intervalli regolari, non solo una volta.', 'Liquido freni = controllo regolare = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25310, 'Il freno di stazionamento deve essere abbastanza forte da bloccare il veicolo e impedirgli di muoversi, anche se è parcheggiato su una strada in salita o in discesa. Questo garantisce la sicurezza del veicolo e degli altri.', 'La frase ''anche su strade in pendenza'' sottolinea che la sua efficacia deve valere anche in condizioni più difficili.', 'Freno a mano = tiene fermo ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25311, 'Il servofreno a depressione funziona grazie al vuoto (depressione) creato dal motore quando è acceso. Se il motore è spento, non c''è depressione e il servofreno non può aiutare a frenare, rendendo il pedale molto più duro da premere.', 'La frase ''non può funzionare'' è chiara: senza motore acceso, il servofreno non ha l''energia per agire.', 'Servofreno = motore acceso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25312, 'Il freno di servizio è il pedale del freno che usi normalmente per rallentare o fermare il veicolo mentre guidi. Il freno di stazionamento (freno a mano) non è progettato per questo uso quotidiano e non deve essere usato per frenare durante la marcia.', 'La frase ''non deve essere utilizzato'' è un divieto. ''Frenatura di servizio'' si riferisce all''uso normale del freno a pedale.', 'Freno a mano = solo sosta/emergenza, non guida.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25313, 'Anche se il circuito frenante è sigillato, il liquido dei freni può diminuire leggermente nel tempo a causa dell''usura delle pastiglie o di piccole perdite. Per la tua sicurezza, è sempre necessario controllare il livello periodicamente.', 'La parte ''pertanto non è necessario un periodico controllo'' è la trappola. Anche se sigillato, il controllo è fondamentale per la sicurezza.', 'Sigillato non significa eterno; controlla sempre il liquido.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25314, 'Usare il freno a mano per frenare mentre si guida, specialmente in discesa, è molto pericoloso. Può bloccare le ruote posteriori e farti perdere il controllo del veicolo. Per le discese lunghe si usano le marce basse (freno motore).', 'La frase ''deve essere utilizzato per la frenatura di servizio'' è l''errore principale. L''intenzione di ''ridurre il surriscaldamento'' è buona, ma il metodo è sbagliato e pericoloso.', 'Freno a mano = mai in movimento (tranne emergenza estrema).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25315, 'Il servofreno a depressione ha bisogno del motore acceso per creare la depressione necessaria al suo funzionamento. La sola chiave inserita nel quadro non basta ad attivarlo.', 'La parte ''purché sia inserita la chiave di accensione nel quadro'' è la trappola. La chiave non attiva il servofreno, il motore sì.', 'Servofreno = motore acceso, non solo chiave.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25316, 'In caso di frenata di emergenza, devi usare il pedale del freno. Inserire la retromarcia mentre il veicolo è in movimento è estremamente pericoloso, può danneggiare gravemente il cambio e farti perdere il controllo del veicolo.', 'La frase ''inserire rapidamente la retromarcia'' è la parte assurda e molto pericolosa della domanda.', 'Retromarcia = solo da fermo. Frenata = pedale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25318, 'La presenza di aria o vapore nel circuito idraulico dei freni rende il pedale ''spugnoso'' e la frenata meno potente o irregolare, perché il liquido non riesce a trasmettere bene la forza. Questo è un problema serio per la sicurezza.', 'Il ''circuito frenante idraulico'' è il sistema dei freni che usa un liquido per funzionare. Aria o vapore non dovrebbero esserci.', 'Aria/vapore nei freni = freni ''molli''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25319, 'Le guarnizioni frenanti (pastiglie o ganasce) sono le parti che creano attrito per fermare il veicolo. Se sono troppo consumate, non riescono a fare abbastanza presa e la frenata diventa debole e meno efficace.', 'Le ''guarnizioni frenanti'' sono le pastiglie dei freni (per i dischi) o le ganasce (per i tamburi).', 'Guarnizioni consumate = frena poco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25320, 'Se i tamburi o i dischi dei freni non si consumano in modo uniforme, le pastiglie non riescono a fare presa bene su tutta la superficie. Questo causa una frenata debole o che tira da un lato, rendendola ''squilibrata''.', 'Il ''consumo irregolare'' significa che le superfici non sono lisce e uniformi, ma hanno avvallamenti o rigature.', 'Dischi/tamburi irregolari = frenata storta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25321, 'Se le gomme sullo stesso asse (ad esempio, le due ruote anteriori) hanno pressioni diverse, una ruota avrà più aderenza dell''altra. Questo può far sì che il veicolo tiri da un lato durante la frenata, rendendola ''squilibrata''.', 'Lo ''stesso asse'' si riferisce alle ruote che si trovano sulla stessa linea orizzontale (es. le due ruote davanti o le due ruote dietro).', 'Pressione gomme diversa = frenata sbilanciata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25322, 'Quando si frena molto e a lungo, specialmente in discesa, le guarnizioni dei freni si scaldano troppo. Questo calore eccessivo riduce l''attrito e la capacità di frenare, un fenomeno chiamato ''fading''.', 'L''''eccessivo riscaldamento'' dei freni è un problema comune in discesa o con frenate intense.', 'Freni caldi = frenano meno.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25323, 'Un veicolo troppo carico o con il peso distribuito male (ad esempio, tutto il peso su un lato) cambia il modo in cui le ruote toccano la strada. Questo può rendere la frenata meno efficace o far sbandare il veicolo.', 'Il ''carico mal ripartito'' significa che il peso non è distribuito in modo equilibrato sul veicolo.', 'Carico sbagliato = frenata instabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25324, 'Frenare troppo spesso e con forza, specialmente in discesa, surriscalda i freni e ne riduce l''efficienza. È meglio usare il freno motore e frenare a intermittenza.', 'Le ''eccessive e ripetute frenate'' indicano un uso prolungato e intenso dei freni, che li affatica.', 'Troppe frenate = freni stanchi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25325, 'Se i freni non funzionano allo stesso modo su tutte le ruote (sono ''squilibrati''), una ruota potrebbe bloccarsi prima delle altre, specialmente quelle di un solo lato. Questo è molto pericoloso e può far perdere il controllo del veicolo.', 'I ''freni squilibrati'' significano che i freni non agiscono con la stessa forza su tutte le ruote.', 'Freni squilibrati = ruote bloccate a caso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25326, 'Se una ruota frena molto più forte o si blocca prima delle altre, il veicolo tenderà a ''tirare'' o sbandare verso quel lato. Questo rende difficile mantenere la traiettoria e può causare un incidente.', 'Il veicolo ''sbanda, dirigendosi verso il lato della ruota che si blocca per prima'' descrive proprio la perdita di controllo.', 'Freni squilibrati = veicolo tira.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25327, 'Se i freni non agiscono in modo uniforme, alcune ruote potrebbero ''strusciare'' di più o bloccarsi più spesso. Questo causa un consumo anomalo e non uniforme del battistrada delle gomme.', 'L''''usura irregolare e non omogenea dei battistrada'' significa che le gomme si consumano male e in modo diverso tra loro.', 'Freni squilibrati = gomme consumate male.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25328, 'Il freno di stazionamento (freno a mano) è un sistema separato usato per tenere fermo il veicolo quando è parcheggiato. Non influisce sulla frenata di servizio (quella che usi mentre guidi).', 'Il ''freno di stazionamento'' è il freno a mano. Non è usato per frenare durante la marcia.', 'Freno a mano = solo per parcheggio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25329, 'I tamburi e i dischi dei freni devono essere asciutti e puliti per funzionare bene, non lubrificati. La lubrificazione ridurrebbe l''attrito e renderebbe la frenata inefficace o addirittura pericolosa.', 'La ''lubrificazione'' è l''opposto di ciò che serve ai freni. I freni hanno bisogno di attrito per fermare il veicolo, non di scivolare.', 'Freni = attrito, non olio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25330, 'La frizione serve a cambiare marcia e a collegare o scollegare il motore dalle ruote. Non ha nessun legame diretto con il sistema frenante, quindi un suo problema non influisce sulla frenata.', 'Il ''pedale della frizione'' è parte del sistema di trasmissione, non dei freni.', 'Frizione = cambio, non freni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25331, 'Il servosterzo è un sistema che aiuta a girare il volante più facilmente. Non ha nulla a che fare con il sistema frenante o con la cilindrata del veicolo.', 'Il ''servosterzo'' aiuta a sterzare, non a frenare.', 'Servosterzo = sterzo facile, non freni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25332, 'I freni a disco sono un tipo di freno moderno ed efficiente. Averli anche sull''asse posteriore è un vantaggio per la frenata, perché migliora la sicurezza e l''efficienza, non è una causa di problemi.', 'La ''presenza di freni a disco sull''asse posteriore'' è una buona caratteristica, non un difetto.', 'Freni a disco = bene, non male.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25333, 'I pneumatici invernali sono progettati per migliorare l''aderenza su neve e ghiaccio. Montarli su tutte e quattro le ruote è la procedura corretta e migliora la sicurezza in inverno, non peggiora la frenata.', 'I ''pneumatici invernali montati su tutte e quattro le ruote'' sono la condizione ideale per la guida invernale.', 'Gomme invernali su 4 ruote = sicurezza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25334, 'Anche se i pneumatici invernali si consumano più velocemente su asfalto asciutto e possono avere prestazioni leggermente diverse dagli estivi, la loro presenza non è una causa diretta di un malfunzionamento del sistema frenante.', 'Le ''strade non innevate'' indicano una condizione in cui le gomme invernali non sono al loro massimo, ma non causano un guasto ai freni.', 'Gomme invernali su asciutto = non è un guasto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25335, 'Il tipo di carburante (metano) e il tipo di strada (montagna) non hanno alcun legame diretto con l''efficienza o l''equilibrio del sistema frenante. Sono due aspetti completamente diversi del veicolo e della guida.', 'L''''alimentazione a metano'' e le ''strade di montagna'' sono elementi irrilevanti per il funzionamento dei freni.', 'Carburante/strada = non freni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25336, 'I freni e il sistema di raffreddamento del motore sono due sistemi completamente separati nel veicolo. Un problema ai freni non causa il surriscaldamento del liquido refrigerante del motore.', 'Il ''liquido refrigerante del motore'' è parte del sistema di raffreddamento del motore, non dei freni.', 'Freni e motore = sistemi diversi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25337, 'Usare il freno a mano (freno di stazionamento) durante la marcia, anche parzialmente, è molto pericoloso. Provoca un surriscaldamento eccessivo, usura rapida e può bloccare le ruote posteriori, causando una perdita di controllo. In discesa si usa il freno motore e il freno di servizio a intermittenza.', 'Il ''freno a mano inserito parzialmente'' è una pratica scorretta e pericolosa.', 'Freno a mano = solo da fermo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25338, 'Il cambio delle pastiglie dei freni è un''operazione delicata che richiede conoscenze tecniche specifiche e attrezzi particolari. Deve essere fatta da personale specializzato (un meccanico) per garantire la sicurezza del veicolo, non da ''qualunque conducente''.', 'La frase ''qualunque conducente'' è la parola trappola. Non tutti hanno le competenze e gli strumenti per farlo in sicurezza.', 'Freni = meccanico esperto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25339, 'Le sospensioni sono un elemento fondamentale del veicolo e si trovano proprio tra il telaio (la struttura principale dell''auto) e le ruote. Servono a collegare queste due parti e a permettere che si muovano in modo indipendente.', 'La frase ''tra il telaio e le ruote'' indica la posizione esatta e corretta delle sospensioni.', 'Sospensioni = Ponte tra telaio e ruote.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25340, 'Uno degli scopi principali delle sospensioni è rendere il viaggio più comodo. Assorbono i colpi e le vibrazioni della strada, così tu e i passeggeri sentite meno scossoni e viaggiate più rilassati.', 'La parola ''confort'' è la chiave. Le sospensioni sono fatte per migliorare la comodità di chi è a bordo.', 'Sospensioni = Comfort per tutti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25341, 'Le sospensioni sono cruciali per la sicurezza. Aiutano le ruote a seguire la forma della strada, anche quando ci sono buche o dossi, mantenendo sempre il contatto con l''asfalto. Questo garantisce una migliore aderenza e controllo del veicolo.', 'La frase ''rimangano aderenti al fondo stradale'' è fondamentale. Senza aderenza, si perde il controllo.', 'Sospensioni = Ruote sempre incollate alla strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25342, 'Le sospensioni hanno il compito di ''smorzare'', cioè ridurre la forza degli urti. Quando incontri una buca o una strada sconnessa, le sospensioni assorbono il colpo, evitando che arrivi direttamente al veicolo e ai passeggeri.', 'Le parole ''smorzare gli urti'' e ''asperità del terreno'' descrivono perfettamente la funzione di assorbimento delle irregolarità della strada.', 'Sospensioni = Ammortizzano i colpi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25343, 'Questa domanda riassume i benefici delle sospensioni. Rendono la guida più comoda (comfort) perché assorbono gli urti e più sicura perché le ruote aderiscono meglio alla strada, garantendo maggiore stabilità e controllo.', 'Le parole ''confortevole e sicura'' sono la sintesi dei vantaggi offerti dalle sospensioni.', 'Sospensioni = Guida comoda e sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25345, 'Questa affermazione è falsa. Un veicolo ha bisogno di stabilità e comfort su tutte le ruote, sia davanti che dietro. Per questo motivo, le sospensioni sono presenti su tutte e quattro le ruote (o su tutte le ruote in caso di veicoli con più assi).', 'La parte ''ma non su quelle posteriori'' è la trappola. Le sospensioni sono sempre su tutte le ruote.', 'Sospensioni = Davanti E dietro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25346, 'Questa affermazione è falsa perché descrive l''esatto contrario della funzione delle sospensioni. Le sospensioni non servono a ''irrigidire'' il veicolo, ma a renderlo più ''morbido'' per assorbire gli urti. Il loro scopo è proprio quello di non farti sentire tutti i saltellamenti, ma di ridurli al minimo.', 'Le parole ''irrigidire il veicolo'' e ''percepisca chiaramente tutti i saltellamenti'' sono le trappole. Le sospensioni fanno l''opposto: ammorbidiscono e filtrano.', 'Sospensioni = Ammorbidiscono, non irrigidiscono.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25347, 'Questa affermazione è falsa. Anche su una strada che sembra perfettamente dritta e liscia, ci sono sempre piccole imperfezioni o variazioni. Le sospensioni lavorano continuamente per mantenere il comfort e l''aderenza delle ruote, anche quando non ci sono curve o grandi buche evidenti.', 'La frase ''non entrano in funzione'' è la trappola. Le sospensioni sono sempre attive per garantire stabilità e comfort.', 'Sospensioni = Sempre attive, anche sul dritto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25348, 'Le sospensioni sono fatte per assorbire gli urti, ma col tempo si consumano (usura) o possono danneggiarsi se prendono colpi molto forti, come buche profonde o incidenti. Quando si rovinano, non funzionano più bene.', 'La parola ''possono'' indica una possibilità, non una certezza assoluta, rendendo l''affermazione vera.', 'Usura e urti forti rovinano le sospensioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25349, 'Se le sospensioni non lavorano bene, l''auto non riesce a mantenere un buon contatto con la strada. Questo significa che in curva, in frenata o su strade sconnesse, l''auto può diventare instabile e difficile da controllare, perdendo la ''tenuta di strada''.', 'L''espressione ''problemi di tenuta di strada'' è una conseguenza diretta e importante delle sospensioni inefficienti.', 'Sospensioni rotte = auto instabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25350, 'Ogni veicolo ha un limite di peso che può trasportare. Se si supera questo limite (sovraccarico), le sospensioni sono costrette a lavorare troppo e con uno sforzo eccessivo, e questo può causarne la rottura, specialmente su strade irregolari.', 'Anche qui, ''può comportare'' indica una possibilità, non che si romperanno sempre, ma che il rischio è concreto.', 'Troppo peso = rischio rottura sospensioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25351, 'Quando un veicolo è sovraccarico, le sospensioni si comprimono più del normale e non riescono ad assorbire bene gli urti. Questo le rende meno efficaci per il tempo in cui il veicolo è troppo carico, anche se non si rompono subito.', 'La parola ''temporanea'' è importante: l''inefficienza dura finché c''è il sovraccarico.', 'Peso eccessivo = sospensioni ''strette''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25352, 'Se si carica spesso il veicolo con troppo peso, le sospensioni sono sempre sotto sforzo. Questo le fa invecchiare e rovinare molto più velocemente del normale, accorciando la loro vita utile.', 'Le parole ''ripetuto'' e ''rapida usura'' indicano un danno che si accumula nel tempo a causa di un comportamento scorretto.', 'Carico frequente = usura accelerata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25353, 'Le sospensioni servono a rendere il viaggio più comodo, assorbendo le vibrazioni e gli urti della strada. Se non funzionano bene, sentirai di più ogni buca e ogni scossone, rendendo il viaggio meno confortevole per tutti i passeggeri.', 'Il ''confort di marcia'' si riferisce alla comodità e alla piacevolezza del viaggio.', 'Sospensioni rotte = viaggio scomodo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25354, 'Guidare un veicolo con sospensioni inefficienti è più faticoso. Il conducente deve fare più attenzione per mantenere il controllo, sente più vibrazioni e scossoni, e questo porta a una maggiore stanchezza fisica e mentale durante la guida.', 'L''''affaticamento alla guida'' è la stanchezza che prova il conducente, che può ridurre la sua attenzione e reattività.', 'Sospensioni rotte = guidatore stanco.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25355, 'Se le sospensioni sono danneggiate, il veicolo potrebbe non essere più livellato correttamente. Questo può far sì che i fari anabbaglianti puntino troppo in alto o troppo in basso, illuminando male la strada o, peggio, abbagliando gli altri conducenti.', 'L''''anomalo orientamento'' significa che i fari non sono regolati correttamente e non puntano nella direzione giusta.', 'Sospensioni rotte = fari storti.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25356, 'Questa affermazione è falsa. Come abbiamo visto nelle domande precedenti, il sovraccarico del veicolo è una delle cause principali di problemi alle sospensioni, che vanno dall''inefficienza temporanea alla rottura vera e propria.', 'La parola ''non'' rende l''affermazione falsa. Il sovraccarico comporta eccome problemi per le sospensioni.', 'Troppo peso = SEMPRE problemi alle sospensioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25357, 'Questa affermazione è falsa. Aumentare la pressione dei pneumatici può aiutare a sostenere meglio il carico e migliorare leggermente la tenuta di strada, ma non risolve i problemi di stress e usura che il sovraccarico provoca direttamente alle sospensioni. Le sospensioni hanno un limite di carico strutturale.', 'La parola ''sufficiente'' è la trappola. Non è sufficiente, è solo una piccola parte della soluzione, e non risolve il problema principale delle sospensioni.', 'Pressione gomme NON basta per sospensioni sovraccariche.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25358, 'Questa affermazione è falsa. Non esiste un chilometraggio fisso (come 30.000 km) per la sostituzione delle sospensioni. La loro durata dipende da molti fattori: stile di guida, tipo di strade percorse, qualità delle sospensioni stesse. Vanno controllate periodicamente e sostituite solo se usurate o danneggiate.', 'Il numero ''trentamila chilometri'' è una cifra specifica e arbitraria che rende l''affermazione falsa, non c''è una regola universale.', 'Nessun km fisso per cambiare le sospensioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25359, 'Questa affermazione è falsa. È vero che il sovraccarico comporta maggiori difficoltà di guida, ma è falso che ''non comporta problemi per le sospensioni''. Il sovraccarico è una delle cause principali di usura, inefficienza e rottura delle sospensioni.', 'La parte ''mentre non comporta problemi per le sospensioni'' è quella che rende l''intera frase falsa.', 'Troppo peso = difficoltà + problemi sospensioni.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25360, 'Questa affermazione è falsa. Anche se le sospensioni sono fatte con materiali elastici per assorbire gli urti, non sono indistruttibili. Urti molto forti, come prendere una buca profonda a velocità elevata, possono comunque danneggiarle o romperle.', 'La frase ''non subiscono danni'' è un''affermazione troppo assoluta e quindi falsa. L''elasticità ha un limite.', 'Elastiche sì, ma NON indistruttibili.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25361, 'Questa affermazione è falsa. Tutte le parti di un veicolo, incluse le sospensioni, necessitano di controlli e manutenzione periodica, anche durante il periodo di garanzia. La garanzia copre i difetti di fabbrica, non esclude la normale manutenzione per mantenere il veicolo efficiente e sicuro.', 'La frase ''non necessitare di verifiche e manutenzioni per tutta la durata della garanzia'' è la trappola. La manutenzione è sempre necessaria.', 'Garanzia NON significa zero manutenzione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25362, 'Questa affermazione è falsa. Le sospensioni sono fondamentali per la ''dirigibilità'' del veicolo, cioè la sua capacità di seguire la traiettoria voluta dal conducente. Collaborano attivamente con lo sterzo per mantenere le ruote a contatto con la strada e garantire il controllo del veicolo. Se le sospensioni sono inefficienti, l''auto è difficile da guidare.', 'Le parole ''non collaborano'' e ''assicurata unicamente'' sono le trappole. La dirigibilità è un lavoro di squadra tra molti componenti.', 'Sospensioni = controllo e dirigibilità.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25363, 'Questa affermazione è falsa. Anche se ogni ruota ha la sua sospensione, il sistema lavora in modo coordinato. La rottura di una sola sospensione compromette gravemente l''equilibrio, la stabilità e la tenuta di strada dell''intero veicolo, rendendo la guida pericolosa e difficile.', 'La frase ''non comporta problemi per la guida'' è pericolosamente falsa. Un problema a una sospensione è un problema serio per la sicurezza.', 'Anche una rotta = problemi seri di guida.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25364, 'Gli ammortizzatori sono componenti fondamentali che servono proprio a ''smorzare'' e ridurre i movimenti su e giù (le oscillazioni) che le sospensioni fanno quando l''auto incontra buche o dossi, garantendo così una guida più stabile e confortevole.', 'La frase ''ridurre le oscillazioni'' descrive esattamente la funzione primaria degli ammortizzatori.', 'Ammortizzatore = meno ''salti'' dell''auto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25365, 'Se le ruote di un veicolo ''saltano'' troppo a causa delle oscillazioni, perdono il contatto con la strada. Gli ammortizzatori, controllando questi movimenti, aiutano le ruote a rimanere sempre ben aderenti al terreno, migliorando così la sicurezza e la stabilità del veicolo.', 'Il termine ''collaborano'' indica che gli ammortizzatori sono uno degli elementi che contribuiscono alla tenuta di strada, non l''unico.', 'Ammortizzatori = ruote incollate alla strada.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25366, 'Questa domanda ribadisce un concetto chiave. Oltre a rendere la guida più confortevole riducendo le oscillazioni, gli ammortizzatori sono essenziali per mantenere le ruote a contatto con la strada, il che è fondamentale per la sicurezza e la capacità del veicolo di curvare e frenare correttamente.', 'La locuzione ''tra l''altro'' significa che questa è una delle funzioni importanti degli ammortizzatori, ma non l''unica.', 'Ammortizzatori = sicurezza e aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25367, 'Quando un veicolo è sovraccarico, gli ammortizzatori devono sostenere un peso maggiore e lavorare molto di più per controllare i movimenti. Questo sforzo extra li affatica e li rende meno efficaci nel loro compito di ''smorzare'' le oscillazioni.', 'La parola ''può'' indica una possibilità molto concreta. Il sovraccarico quasi sempre influisce negativamente.', 'Troppo peso = ammortizzatori stanchi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25368, 'Il lavoro eccessivo e lo stress a cui sono sottoposti gli ammortizzatori a causa del sovraccarico fanno sì che i loro componenti si consumino più rapidamente del normale. Questo significa che si rovinano prima del previsto e devono essere sostituiti prima.', 'L''espressione ''usura precoce'' significa che i componenti si consumano e si deteriorano in anticipo rispetto alla loro vita utile normale.', 'Troppo peso = ammortizzatori rotti prima.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25369, 'FALSO. Anche se un veicolo è nuovo e in garanzia, tutti i suoi componenti, inclusi gli ammortizzatori, necessitano di controlli e manutenzione periodica. La garanzia copre i difetti di fabbrica, non esonera dalla normale manutenzione necessaria per il buon funzionamento e la sicurezza del veicolo.', 'La trappola è ''non necessitano... fino a quando dura la garanzia''. La manutenzione è sempre necessaria, a prescindere dalla garanzia.', 'Garanzia non è manutenzione zero.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25370, 'FALSO. Anche se guidi con la massima prudenza, il peso eccessivo sul veicolo mette comunque sotto forte stress gli ammortizzatori. Il sovraccarico è un problema meccanico e strutturale che affatica i componenti, indipendentemente da come si guida.', 'La frase ''non causa problemi... se il conducente adotta uno stile di guida prudente'' è la trappola. Il sovraccarico è un problema a prescindere dallo stile di guida.', 'Peso eccessivo = sempre un problema.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25371, 'FALSO. Aumentare la pressione dei pneumatici è una buona pratica quando il veicolo è sovraccarico, perché aiuta i pneumatici a sostenere meglio il peso e a mantenere una buona tenuta di strada. Tuttavia, non è ''sufficiente'' a risolvere lo stress e l''usura che il sovraccarico provoca agli ammortizzatori.', 'La parola ''sufficiente'' è la trappola. Non basta solo quello per proteggere gli ammortizzatori dal sovraccarico.', 'Gomme gonfie non salvano gli ammortizzatori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25372, 'FALSO. Non tutti i veicoli permettono al conducente di regolare la rigidità degli ammortizzatori. Questa è una funzione avanzata, presente solo su alcuni modelli specifici (spesso sportivi o di alta gamma), e non è una caratteristica universale di tutte le auto.', 'La locuzione ''in ogni caso'' è la trappola. Non è sempre possibile per tutti i veicoli.', 'Non tutti gli ammortizzatori sono regolabili.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25373, 'FALSO. La regolazione o il controllo della rigidità degli ammortizzatori, anche sui veicoli che lo permettono, è un''operazione complessa che richiede conoscenze tecniche specifiche e attrezzi particolari. Deve essere eseguita da un meccanico specializzato in officina, non può essere fatta dal proprietario ''fai da te''.', 'La frase ''senza ricorrere ad un''officina specializzata'' è la trappola. È un lavoro da professionisti.', 'Ammortizzatori = meccanico specializzato.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25374, 'Gli ammortizzatori servono a tenere le ruote ben attaccate alla strada. Se sono ''scarichi'' (rovinati), le ruote non aderiscono bene, specialmente quando freni, e il veicolo può comportarsi in modo strano, ad esempio ''saltellando'' o sbandando. Per questo, un comportamento anomalo in frenata è un segno di ammortizzatori scarichi.', 'La parola ''anomalo'' significa ''strano'', ''non normale''. Indica un comportamento del veicolo che non è quello previsto e sicuro.', 'Ammortizzatori scarichi = frenata instabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25375, 'Come per la frenata, anche in curva gli ammortizzatori rovinati non riescono a tenere le ruote ferme sulla strada. Questo è ancora più pericoloso perché il veicolo si inclina e le ruote potrebbero perdere aderenza, rendendo la guida difficile e rischiosa. Quindi, un comportamento anomalo in curva è un chiaro segnale di ammortizzatori scarichi.', 'La parola ''particolarmente'' significa ''soprattutto'', ''specialmente''. Sottolinea che il problema si manifesta in modo più evidente in curva.', 'Ammortizzatori scarichi = curva pericolosa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25376, 'Se gli ammortizzatori non funzionano bene, le ruote ''saltellano'' sulla strada invece di rotolare in modo fluido e costante. Questo fa sì che alcune parti del pneumatico si consumino più velocemente di altre, creando un''usura ''non uniforme'' (irregolare) del battistrada.', 'La frase ''usura non uniforme'' è importante. Significa che il pneumatico si consuma in modo irregolare, a macchie o solo da un lato, non in modo omogeneo.', 'Ammortizzatori scarichi = gomme consumate male.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25377, 'Gli ammortizzatori e le molle lavorano insieme nel sistema delle sospensioni. Le molle assorbono i colpi, e gli ammortizzatori ''frenano'' il movimento delle molle. Se gli ammortizzatori sono scarichi, le molle lavorano troppo e senza controllo, subendo uno stress maggiore che può portarle a rompersi più facilmente.', 'La frase ''aumentano il rischio'' significa che rendono più probabile che succeda qualcosa di negativo, in questo caso la rottura delle molle.', 'Ammortizzatori scarichi = molle sotto stress.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25378, 'Gli ammortizzatori servono proprio a rendere il viaggio più comodo, assorbendo le vibrazioni e i colpi della strada. Se sono scarichi, sentirai di più ogni buca e ogni irregolarità, rendendo il viaggio scomodo e meno piacevole per te e i passeggeri.', 'La frase ''diminuzione del comfort'' significa che si sta meno comodi, si percepiscono di più le asperità della strada.', 'Ammortizzatori scarichi = viaggio scomodo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25379, 'La ''tenuta di strada'' è la capacità del veicolo di rimanere stabile e aderente alla strada. Gli ammortizzatori scarichi fanno sì che le ruote non siano sempre ben a contatto con l''asfalto, riducendo questa capacità e rendendo il veicolo meno sicuro e più difficile da controllare.', 'Il verbo ''peggiorano'' significa che rendono la situazione ''meno buona'', ''più brutta'' o ''più pericolosa''.', 'Ammortizzatori scarichi = meno aderenza.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25380, 'Gli ammortizzatori fanno parte del sistema delle sospensioni e servono a gestire i movimenti del veicolo sulla strada (come assorbire le buche). Non hanno nessun collegamento diretto con il motore, che è la parte che produce la forza per far muovere l''auto. Quindi, non possono causare problemi al motore.', 'La frase ''anomalo funzionamento del motore'' è la parte da notare. Gli ammortizzatori non influenzano il motore, ma la stabilità e il comfort del veicolo.', 'Ammortizzatori = sospensioni, non motore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25381, 'Il lubrificante (o olio motore) serve a far funzionare bene le parti interne del motore, riducendo l''attrito. Gli ammortizzatori, invece, sono esterni al motore e non usano il lubrificante del motore. Quindi, non c''è nessun legame tra ammortizzatori scarichi e un maggior consumo di olio motore.', 'La frase ''maggior consumo di lubrificante'' è la trappola. Il lubrificante è per il motore, non per gli ammortizzatori.', 'Ammortizzatori = non olio motore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25382, 'Questa è una domanda ''trappola''. Gli ammortizzatori scarichi non abbassano l''altezza del telaio in modo controllato per migliorare la tenuta. Al contrario, rendono il veicolo instabile, le ruote perdono aderenza e il veicolo ''saltella'', quindi la tenuta di strada peggiora, non migliora, specialmente in curva.', 'La frase ''migliorano la tenuta di strada'' è la parte falsa. Gli ammortizzatori scarichi la peggiorano drasticamente.', 'Scarichi = peggio, non meglio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25383, 'Gli ammortizzatori sono una parte specifica e fondamentale del sistema di sospensione. Non puoi semplicemente ''sostituirli con una sospensione rinforzata'' perché sono componenti diversi che lavorano insieme. Se gli ammortizzatori sono rotti, devi sostituire gli ammortizzatori con altri ammortizzatori nuovi e adatti al veicolo, non l''intero sistema di sospensione con qualcosa di generico.', 'La frase ''sostituiti con una sospensione rinforzata'' è imprecisa e fuorviante. Si sostituiscono gli ammortizzatori con ammortizzatori nuovi.', 'Ammortizzatori = ammortizzatori, non ''sospensione''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25384, 'Questa è una frase molto ingannevole. Le ''sospensioni'' sono un sistema complesso che include sia le molle (che assorbono i colpi) sia gli ammortizzatori (che controllano il movimento delle molle). Tutti i veicoli moderni hanno sia molle che ammortizzatori, perché lavorano insieme per garantire comfort e sicurezza. Non è ''o uno o l''altro''.', 'La frase ''oppure... ma difficilmente di tutti e due'' è la trappola. I veicoli hanno SEMPRE entrambi, perché sono due componenti che lavorano in sinergia.', 'Sospensioni = molle + ammortizzatori (sempre insieme).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25385, 'Anche se un ammortizzatore è ''a circuito sigillato'' (cioè non si può aprire o riempire), questo non significa che non si usuri o non si rovini con il tempo e l''uso. Tutti i componenti di un veicolo sono soggetti a usura e devono essere controllati e, se necessario, sostituiti. La frase ''non necessitano di manutenzione'' è quasi sempre falsa per qualsiasi componente meccanico di un veicolo.', 'La frase ''non necessitano di manutenzione'' è la chiave da considerare falsa. Anche i componenti sigillati hanno una vita utile e possono guastarsi.', 'Tutto si usura, anche se ''sigillato''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25386, 'Il servosterzo è un sistema che ti aiuta a girare il volante con meno fatica. Se non funziona bene, il volante diventa più difficile da muovere, cioè ''pesante''.', 'La frase ''mal funzionamento'' indica che il sistema non lavora come dovrebbe. ''Pesante'' descrive la sensazione al volante.', 'Servosterzo rotto = sterzo pesante.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25387, 'Quando un pneumatico si fora, perde pressione e la macchina tende a ''cadere'' da quel lato. Questo fa sì che lo sterzo tiri (giri da solo) verso la ruota sgonfia.', 'La parola chiave è ''tira nella direzione della ruota forata'', che descrive il comportamento del veicolo.', 'Gomma forata = sterzo tira verso la foratura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25388, 'I ''giochi anomali'' allo sterzo significano che c''è troppo movimento libero del volante prima che le ruote inizino a girare. Questo rende la guida meno precisa e può essere pericoloso. Controllare spesso è fondamentale per la sicurezza.', '''Giochi anomali'' si riferisce a un movimento eccessivo o non voluto. ''Periodicamente'' significa regolarmente, ogni tanto.', 'Niente giochi allo sterzo = guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25389, 'Se i pneumatici non hanno abbastanza aria (pressione insufficiente), fanno più attrito con la strada. Questo rende più difficile girare il volante, facendolo sentire ''duro''.', '''Durezza'' indica la difficoltà a girare il volante. ''Insufficiente pressione'' significa che le gomme sono sgonfie.', 'Gomme sgonfie = sterzo duro.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25390, 'Il servosterzo idraulico funziona grazie a una pompa che è collegata al motore. Se il motore è spento, la pompa non gira e il servosterzo non può aiutarti a girare il volante.', '''Idraulico'' indica che usa un liquido e una pompa. ''Motore è spento'' è la condizione che impedisce il funzionamento.', 'Motore spento = servosterzo spento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25391, 'Se il volante ha troppo ''gioco'' (movimento a vuoto), quando lo giri un po'', le ruote non rispondono subito. Questo rende difficile mantenere la macchina dritta o fare curve precise, rendendo la traiettoria ''imprecisa''.', '''Eccessivi giochi'' significa troppo movimento a vuoto. ''Imprecisa la traiettoria'' significa che il veicolo non segue la linea desiderata.', 'Troppo gioco = guida imprecisa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25392, 'La convergenza è l''angolo con cui le ruote sono allineate tra loro. Se non sono allineate correttamente, la macchina non va dritta e lo sterzo non è preciso, influenzando la sterzata.', '''Convergenza'' è il termine tecnico per l''allineamento delle ruote. ''Influenza sulla precisione'' significa che ha un effetto diretto sulla capacità di sterzare bene.', 'Convergenza ok = sterzo preciso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25393, 'Se senti il volante vibrare, è molto probabile che le ruote anteriori non siano bilanciate correttamente. La bilanciatura serve a distribuire il peso della ruota in modo uniforme.', '''Vibra'' si riferisce al tremolio del volante. ''Bilanciatura delle ruote anteriori'' è l''operazione per equilibrare il peso delle ruote davanti.', 'Sterzo vibra = controlla bilanciatura ruote anteriori.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25394, 'In caso di foratura, lo sterzo tende a tirare. Il servosterzo, rendendo il volante più leggero, ti permette di contrastare meglio questa forza e mantenere il controllo del veicolo, aiutandoti a controllare la traiettoria.', '''Aiuta a controllare'' significa che facilita la gestione del veicolo. ''Traiettoria'' è la direzione in cui si muove il veicolo.', 'Servosterzo = più controllo anche con gomma forata.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25395, 'Il servosterzo serve solo a rendere più facile girare il volante. Non ha nessun legame con il sistema frenante e quindi non migliora la capacità del veicolo di frenare.', 'La frase ''migliora l''azione frenante'' è una parola trappola. Il servosterzo non ha alcuna funzione legata ai freni.', 'Servosterzo = solo per sterzare, non per frenare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25396, 'Quando un pneumatico si fora, lo sterzo tira sempre nella direzione della ruota sgonfia, non in quella opposta. Questo perché la macchina ''cade'' e si sbilancia verso il lato della foratura.', 'La parola ''opposta'' è la trappola. Ricorda che tira sempre verso la ruota forata.', 'Gomma forata = tira VERSO la foratura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25397, 'Le vibrazioni che si sentono al volante (sterzo) sono quasi sempre causate da problemi alle ruote anteriori. Se le ruote posteriori non sono bilanciate, le vibrazioni si sentono più sul sedile o sulla carrozzeria, non direttamente sullo sterzo.', 'La frase ''ruote posteriori'' è la trappola. Le vibrazioni allo sterzo sono legate alle ruote anteriori.', 'Sterzo vibra = ruote ANTERIORI.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25398, 'Se il servosterzo si rompe, non ricevi più l''aiuto per girare il volante. Questo lo rende molto più ''pesante'' e difficile da manovrare, non più facile.', 'L''espressione ''eccessiva facilità di manovra'' è una trappola. È il contrario di ciò che accade.', 'Servosterzo rotto = sterzo PESANTE.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25399, 'Per avere il massimo controllo e sicurezza, il volante deve essere impugnato nella parte alta, di solito nella posizione ''9 e 15'' (come le lancette dell''orologio), con i pollici appoggiati sulle razze. Impugnarlo in basso riduce il controllo.', 'Le espressioni ''parte bassa'' e ''sotto le razze'' sono trappole, indicano una posizione di guida scorretta e meno sicura.', 'Volante = mani in ALTO (9 e 15).')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25400, 'Molte auto moderne permettono di regolare il volante sia in altezza che in profondità. Questo serve per permettere al guidatore di trovare la posizione più comoda e sicura.', 'La frase ''non può essere regolato'' è una trappola. Nella maggior parte delle auto attuali è possibile regolarlo.', 'Volante = spesso regolabile.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25401, 'Sospensioni e ammortizzatori in cattive condizioni rendono la macchina meno stabile, specialmente in curva o su strade sconnesse. Questo rende la sterzata meno precisa e più difficile da controllare.', 'La negazione ''non è influenzata'' è la trappola. Le condizioni di sospensioni e ammortizzatori influenzano molto la precisione della sterzata.', 'Sospensioni/ammortizzatori rotti = sterzo impreciso.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25402, 'La pressione dell''olio di lubrificazione è fondamentale per il buon funzionamento del motore, ma non ha un effetto diretto sulla precisione dello sterzo. Lo sterzo è influenzato da altri elementi come pneumatici, sospensioni, convergenza.', 'La frase ''scarsa pressione dell''olio di lubrificazione'' è una trappola. Questo problema riguarda il motore, non lo sterzo.', 'Olio motore = non c''entra con lo sterzo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25403, 'L''eccessiva temperatura del liquido di raffreddamento indica un problema di surriscaldamento del motore. Questo è un problema grave per il motore, ma non influenza direttamente la precisione con cui giri il volante.', 'La frase ''eccessiva temperatura del liquido di raffreddamento'' è una trappola. Questo problema riguarda il motore, non lo sterzo.', 'Liquido raffreddamento = non c''entra con lo sterzo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25404, 'Se la marmitta è rotta o vecchia, non riesce più a ''silenziare'' bene il rumore del motore. Quindi, il veicolo fa più rumore e aumenta l''inquinamento acustico.', 'La parola ''deteriorata'' significa rovinata, non più in buone condizioni. Questo è il punto chiave che porta all''aumento del rumore.', 'Marmitta rotta = più rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25405, 'Quando la marmitta è rotta, devi cambiarla. È importante usare una marmitta che sia stata ''approvata'', cioè che sia fatta apposta per il tuo modello di veicolo e rispetti le regole di sicurezza e inquinamento. Non puoi metterne una qualsiasi.', 'La frase ''di tipo approvato'' è fondamentale. Non puoi montare un pezzo qualsiasi, ma solo quello specifico e omologato per il tuo veicolo.', 'Marmitta nuova? Solo quella approvata!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25406, 'L''impianto di scarico non solo porta via i gas dal motore, ma grazie al catalizzatore (che fa parte dell''impianto), rende questi gas meno ''velenosi'' (meno tossici) prima che escano nell''aria.', 'La parte ''dopo averne abbassato la tossicità'' si riferisce al lavoro del catalizzatore, che trasforma i gas nocivi in sostanze meno dannose.', 'Scarico = gas fuori e meno velenosi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25407, 'I gas che escono dal motore hanno molta pressione. L''impianto di scarico, con i suoi tubi e la marmitta, aiuta a ridurre questa pressione prima che i gas escano, rendendo il flusso più controllato e meno rumoroso.', 'La frase ''dopo averne abbassato la pressione'' indica una funzione tecnica dell''impianto che gestisce la forza con cui i gas vengono espulsi.', 'Scarico = gas fuori e meno pressione.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25408, 'I gas che escono dal motore sono molto caldi. L''impianto di scarico, essendo lungo e fatto di metallo, permette ai gas di raffreddarsi un po'' prima di uscire, riducendo il rischio di scottature o incendi.', 'La parte ''dopo averne abbassato la temperatura'' descrive un effetto naturale del percorso dei gas attraverso l''impianto, che li raffredda prima dell''espulsione.', 'Scarico = gas fuori e meno caldi.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25409, 'La marmitta, che è una parte fondamentale dell''impianto di scarico, serve proprio a ''silenziare'' il rumore forte che fa il motore quando i gas vengono espulsi. Senza marmitta, il rumore sarebbe fortissimo.', 'L''espressione ''ridurre la rumorosità'' è la funzione principale del silenziatore (la marmitta stessa).', 'Scarico = meno rumore.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25410, 'Grazie al catalizzatore, che è parte dell''impianto di scarico, i gas ''velenosi'' (come monossido di carbonio, ossidi di azoto) vengono trasformati in sostanze meno dannose prima di essere rilasciati nell''aria. Questo riduce l''inquinamento.', 'La frase ''ridurre l''inquinamento atmosferico'' si riferisce al compito del catalizzatore, che purifica i gas di scarico.', 'Scarico = meno inquinamento nell''aria.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25411, 'Il cambio del lubrificante (olio motore) si fa spesso, ogni tot chilometri. L''impianto di scarico non si cambia così spesso, ma solo quando è rotto o molto usurato. Sono due cose diverse e non legate.', 'Le parole ''integralmente sostituito a ogni cambio di lubrificante'' sono la trappola. ''Integralmente'' (tutto) e ''a ogni cambio'' (sempre) sono esagerazioni che rendono la frase falsa.', 'Olio e scarico: due manutenzioni diverse.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25412, 'I veicoli elettrici non hanno un motore a scoppio e quindi non producono gas di scarico. Per questo motivo, non hanno un impianto di scarico come quello dei veicoli a benzina o diesel. Quindi, non necessitano di manutenzione per qualcosa che non hanno.', 'La chiave è ''veicoli elettrici''. Essi non hanno un impianto di scarico tradizionale, quindi non può richiedere manutenzione.', 'Elettrico = no scarico, no manutenzione scarico.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25413, 'Il silenziatore (marmitta) è obbligatorio sempre, sia in città che fuori. Serve a ridurre il rumore e l''inquinamento acustico, ed è una parte essenziale per la circolazione legale del veicolo.', 'La frase ''anche senza silenziatore'' è la parte sbagliata. Il silenziatore è un componente obbligatorio per legge, sempre.', 'Silenziatore sempre, ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25414, 'Riparazioni ''fai da te'' con nastro isolante o lana di vetro non sono sicure né efficaci per l''impianto di scarico. I gas sono caldi e sotto pressione, e una riparazione non professionale non terrebbe. È pericoloso e illegale. Bisogna andare in officina.', 'I materiali ''lana di vetro e nastro isolante'' sono la trappola. Non sono adatti per una riparazione sicura e duratura di un impianto di scarico, che richiede interventi professionali.', 'Scarico rotto? Solo officina, no ''fai da te''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25415, 'La sostituzione di parti importanti come l''impianto di scarico richiede competenze tecniche specifiche e l''uso di ricambi approvati. È meglio farla fare da un''officina specializzata per garantire sicurezza e conformità alle norme.', 'La frase ''anche personalmente, senza rivolgersi ad un''officina autorizzata'' è l''errore. Per la sicurezza, l''efficacia e la legalità, è sempre consigliabile rivolgersi a un professionista.', 'Scarico: lavoro da meccanico, non da solo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25416, 'Non puoi modificare l''impianto di scarico a tuo piacimento. Le modifiche sono permesse solo se sono approvate e omologate, e non basta una tua ''autocertificazione''. Le modifiche non autorizzate possono alterare rumore, emissioni e prestazioni, e sono illegali.', 'La trappola è ''purché si autocertifichi''. Non basta la tua parola o una tua dichiarazione; servono omologazioni e approvazioni ufficiali da parte delle autorità competenti.', 'Scarico modificato? Solo con omologazione, mai ''fai da te''.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25417, 'Manomettere l''impianto di scarico (cioè modificarlo in modo non autorizzato) è sempre illegale e comporta sanzioni, multe e a volte anche il ritiro del libretto. Non importa dove circoli, la legge è uguale per tutti.', 'Le frasi ''non comporta alcuna sanzione'' e ''purché si circoli solo nei centri urbani'' sono entrambe false. La manomissione è sempre sanzionabile, ovunque.', 'Scarico manomesso = multa sicura, ovunque.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25419, 'VERO. L''interruttore di emergenza, chiamato anche ''kill switch'', si trova sul manubrio e serve proprio per spegnere il motore rapidamente, soprattutto in caso di pericolo o necessità immediata. È una funzione di sicurezza importante.', 'La frase ''anche tramite'' significa che è uno dei modi per spegnere il motore, non l''unico. Questo è corretto.', 'Kill switch = spegnimento rapido.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25420, 'VERO. Se l''interruttore di emergenza è su ''OFF'' (spento), il motore non può avviarsi perché non riceve corrente. Per accendere la moto, devi assicurarti che sia su ''ON'' (acceso/avviamento).', 'La parola ''necessario'' sottolinea che è una condizione indispensabile per l''avviamento del motore.', 'ON per partire, OFF per fermare.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25421, 'VERO. Questo è uno dei vantaggi principali dell''interruttore di emergenza. Essendo sul manubrio, ti permette di spegnere il motore senza togliere le mani dalle manopole, mantenendo il controllo del veicolo in situazioni critiche.', 'La frase ''senza staccare le mani dal manubrio'' evidenzia la comodità e la sicurezza di questo dispositivo.', 'Mani sul manubrio, motore spento.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25422, 'VERO. Immagina di fermarti su una salita o discesa molto ripida: le tue mani sono impegnate a tenere i freni per non far muovere la moto. In questa situazione, l''interruttore di emergenza ti permette di spegnere il motore facilmente, senza dover lasciare le leve dei freni.', 'La descrizione ''qualora ci si arresti su strade a forti pendenze avendo le mani occupate sulle leve di comando'' spiega una situazione specifica in cui l''interruttore è molto utile.', 'Pendenza e mani occupate? Kill switch!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25423, 'VERO. L''interruttore di emergenza è un dispositivo di sicurezza. Se non funziona bene (è guasto), la tua moto non è sicura al 100%. Per questo motivo, è fondamentale farlo riparare il prima possibile per garantire la tua sicurezza e quella degli altri.', 'La frase ''deve essere riparato al più presto'' indica l''urgenza e l''importanza della riparazione per la sicurezza.', 'Sicurezza non aspetta, ripara subito.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25424, 'VERO. L''interruttore di emergenza è pensato per le emergenze. Per spegnere la moto normalmente, quando non c''è fretta o pericolo, è meglio usare la chiave di accensione. Questo aiuta a preservare l''interruttore di emergenza e spesso blocca anche lo sterzo, aumentando la sicurezza del veicolo parcheggiato.', 'Le parole ''situazioni ordinarie'' e ''è preferibile'' indicano che c''è un modo migliore per le situazioni normali, anche se l''interruttore di emergenza può comunque spegnere il motore.', 'Ordinario = chiave. Emergenza = kill switch.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25425, 'FALSO. L''interruttore di emergenza non sostituisce la chiave. La chiave serve per accendere la moto, bloccare lo sterzo e spegnere il motore in modo normale. L''interruttore di emergenza è un dispositivo aggiuntivo per spegnere il motore velocemente in caso di necessità, ma non può fare tutte le funzioni della chiave.', 'La parola ''sostituisce'' è la parola trappola. L''interruttore di emergenza non prende il posto della chiave, ma la affianca.', 'Non sostituisce, ma aiuta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25426, 'FALSO. L''interruttore di emergenza si trova sul manubrio, non sulla pedivella del cambio. La pedivella del cambio serve per cambiare le marce con il piede.', 'La frase ''sulla pedivella del cambio'' indica una posizione sbagliata per l''interruttore di emergenza.', 'Kill switch sul manubrio, non sul cambio.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25427, 'FALSO. L''interruttore di emergenza serve solo a spegnere il motore. Non ha nessuna funzione che blocca le ruote. Bloccare le ruote all''improvviso sarebbe molto pericoloso e causerebbe una caduta.', 'La frase ''blocco istantaneo delle ruote'' è completamente sbagliata e pericolosa. L''interruttore non fa questo.', 'Spegne il motore, non blocca le ruote.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25428, 'FALSO. L''interruttore di emergenza è sul manubrio. Sul cavalletto laterale a volte c''è un sensore che spegne il motore se provi a partire con il cavalletto abbassato, ma non è l''interruttore di emergenza e non serve per le pendenze.', 'La frase ''posto sul cavalletto laterale'' è la parte sbagliata. L''interruttore di emergenza non si trova lì.', 'Kill switch sul manubrio, non sul cavalletto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25429, 'FALSO. L''interruttore di emergenza si aziona con la mano, perché si trova sul manubrio. Non si usa con il piede.', 'La frase ''azionabile con la pressione del piede destro'' è errata. Si usa la mano.', 'Kill switch a mano, non a piede.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25430, 'FALSO. L''interruttore di emergenza serve solo a spegnere il motore. Non ha nulla a che fare con i freni o con il freno di stazionamento (che blocca la moto quando è ferma, come il freno a mano in auto).', 'La frase ''funzione di freno di stazionamento'' è una funzione completamente diversa da quella dell''interruttore di emergenza.', 'Spegne il motore, non frena.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25431, 'FALSO. L''interruttore di emergenza è un sistema per spegnere il motore. L''antifurto è un sistema per proteggere la moto dai furti (ad esempio, con un allarme o un blocco motore). Sono due sistemi diversi e non sono collegati tra loro.', 'La frase ''collegato con l''antifurto del veicolo'' è la parte sbagliata. Sono funzioni separate.', 'Spegne il motore, non è un antifurto.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25432, 'Per la tua sicurezza e quella degli altri, è importante controllare spesso se la catena della moto è consumata. Una catena consumata può rompersi o funzionare male, creando pericoli.', 'La frase ''è opportuno verificare periodicamente'' significa che è una buona pratica farlo regolarmente, non solo una volta, per mantenere la sicurezza.', 'Catena consumata = pericolo. Controlla sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25433, 'Se la catena non ha abbastanza olio (non è lubrificata), si ''grippa'' e si usura più velocemente. Questo aumenta molto il rischio che si rompa mentre guidi, causando un incidente.', 'La condizione ''se non lubrificata'' è la chiave. La mancanza di lubrificazione è la causa principale di usura e rottura.', 'Catena secca = catena rotta. Olio sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25434, 'La catena serve a portare la forza dal motore (tramite il pignone, che è un piccolo ingranaggio) alla ruota posteriore (tramite la corona, che è un ingranaggio più grande), facendo muovere la moto.', 'La frase ''collega il pignone motore alla corona della ruota'' descrive esattamente la funzione e i componenti che la catena unisce.', 'Catena = ponte tra motore e ruota.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25435, 'Controllare spesso che la catena abbia l''olio giusto è fondamentale per la sicurezza. Una catena ben lubrificata dura di più, funziona meglio e riduce il rischio di rotture improvvise.', 'Le parole ''ben lubrificata'' e ''opportuno verificare periodicamente'' sottolineano l''importanza della manutenzione regolare e fatta nel modo corretto.', 'Catena lubrificata = guida sicura.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25436, 'La catena non deve essere né troppo tesa né troppo lenta. Se è troppo tesa, si usura e può rompersi. Se è troppo lenta, può saltare o cadere. Per questo, devi controllare la sua tensione regolarmente.', 'Le parole ''corretta tensione'' e ''opportuno verificare periodicamente'' indicano che la tensione deve essere giusta e controllata spesso, non a caso.', 'Tensione giusta = catena felice.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25437, 'Se la catena si rompe all''improvviso, può incastrarsi e bloccare la ruota posteriore. Questo ti farebbe perdere il controllo della moto, con un grande pericolo di caduta.', 'La sequenza ''rottura improvvisa'' che causa il ''bloccaggio della ruota posteriore, con conseguente perdita del controllo'' descrive un evento molto pericoloso.', 'Catena rotta = ruota bloccata = caduta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25438, 'Se vedi che la catena è vecchia, arrugginita, allungata o ha altri segni di usura, non aspettare. Devi cambiarla subito per evitare problemi e pericoli durante la guida.', 'La frase ''mostra segni di usura'' è il segnale che ''occorre sostituirla'' immediatamente, senza rimandare.', 'Catena usurata = cambia subito!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25439, 'Questa affermazione è falsa. Le catene delle moto hanno sempre bisogno di essere lubrificate con olio specifico. Non sono ''autolubrificanti'' e l''acciaio da solo non basta a proteggerle dall''usura.', 'Le parole trappola sono ''non necessita di lubrificazione'' e ''acciaio autolubrificante''. Nessuna catena di trasmissione per moto è autolubrificante.', 'Catena = olio. Sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25440, 'Questa affermazione è falsa. La rottura della catena non solo ti ferma (quindi pregiudica la velocità), ma è anche molto pericolosa perché può bloccare la ruota e farti cadere. La sicurezza è assolutamente compromessa.', 'La parte ''ma non la sicurezza'' è la trappola. La rottura della catena è un grave problema di sicurezza, non solo un inconveniente.', 'Catena rotta = pericolo, non solo stop.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25441, 'Questa affermazione è falsa. Non si può ''riparare'' una catena usurata con del filo di ferro. È una soluzione improvvisata, pericolosissima e non efficace. Una catena usurata va sempre sostituita con una nuova.', 'La frase ''rinforzarla con filo di ferro di tipo idoneo'' è la trappola. È una pratica assolutamente sbagliata e pericolosa.', 'Catena usurata = sostituisci, non rattoppa.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25442, 'Questa affermazione è falsa. Quando la catena è molto usurata, anche il pignone (ingranaggio piccolo) e la corona (ingranaggio grande) si consumano. Per avere un sistema di trasmissione efficiente e sicuro, è quasi sempre consigliabile cambiare tutti e tre i componenti insieme (il ''kit trasmissione'').', 'La parola ''mai'' è la trappola. Spesso è necessario, anzi, consigliabile sostituire tutti i componenti del kit trasmissione.', 'Catena usurata = kit completo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25443, 'Questa affermazione è falsa. La maggior parte delle moto non ha un tenditore automatico per la catena di trasmissione. È sempre necessario controllare e regolare manualmente la tensione della catena periodicamente.', 'Le frasi ''non è necessario il periodico controllo'' e ''tenditore automatico'' sono le trappole. Il controllo è sempre necessario e il tenditore automatico è raro.', 'Tensione = controllo manuale.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25444, 'Questa affermazione è falsa. È vero che la catena va pulita con un detergente sgrassante, ma dopo la pulizia è FONDAMENTALE lubrificarla. La lubrificazione non fa slittare il cambio, anzi, è essenziale per il buon funzionamento e la durata della catena.', 'La parte ''assolutamente non lubrificata per non far slittare il cambio'' è completamente sbagliata e pericolosa. La lubrificazione è vitale.', 'Pulisci e poi lubrifica. Sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25445, 'Questa affermazione è falsa. Anche se tecnicamente si può cambiare il pignone e la corona per modificare come la moto prende velocità, questa modifica non è permessa dalla legge se non è stata approvata per il tuo veicolo. Fare modifiche non autorizzate è illegale e può rendere la moto meno sicura.', 'La frase ''è possibile sostituire... in modo da modificare il rapporto di trasmissione'' è la trappola. Pur essendo tecnicamente fattibile, non è legalmente consentito farlo liberamente senza omologazione.', 'Modifiche tecniche = solo se legali.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25446, 'Per controllare il livello dell''olio in modo corretto, la moto deve essere dritta, come se ci fossi seduto sopra, con entrambe le ruote a terra. Se la metti sul cavalletto, la moto è inclinata e il livello dell''olio non sarà quello vero.', 'Le parole chiave sono ''perfettamente orizzontale'' e ''non sul cavalletto''. Indicano la posizione esatta del veicolo.', 'Olio: moto dritta, ruote a terra.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25447, 'Sì, è molto importante controllare regolarmente l''olio del motore e il liquido dei freni. Questi liquidi sono fondamentali per il buon funzionamento e la sicurezza della moto. Un controllo periodico evita problemi.', 'La parola ''periodicamente'' significa ''ogni tanto'', ''regolarmente''. Non basta controllare una sola volta.', 'Olio e freni: controlla sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25448, 'Il liquido dei freni si trova in una piccola vaschetta, di solito trasparente, che si trova sul manubrio. Guardando questa vaschetta puoi vedere se il livello è tra il minimo e il massimo.', 'La frase ''vaschetta trasparente'' è la chiave per capire dove si controlla il liquido dei freni.', 'Liquido freni: guarda la vaschetta trasparente.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25449, 'Alcune moto hanno una piccola finestra trasparente sul motore (sulla ''coppa'') dove puoi vedere il livello dell''olio senza usare l''astina. È un metodo alternativo e comodo.', 'Le parole ''In alcuni motori'' e ''finestrella'' sono importanti. Non tutte le moto hanno questa finestrella, ma alcune sì.', 'Olio: astina o finestrella.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25450, 'Per un controllo corretto, la moto deve essere dritta (in piano) e il motore deve essere spento da un po'' di tempo (alcuni minuti). Questo permette all''olio di scendere tutto nella coppa e di dare una lettura precisa.', 'Le condizioni ''in piano'' e ''dopo aver spento il motore da alcuni minuti'' sono entrambe essenziali per un controllo accurato.', 'Olio: moto dritta, motore freddo.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25451, 'Questa affermazione è falsa. Anche sulle moto ci sono liquidi importanti da controllare, come l''olio motore, il liquido dei freni e, se la moto è raffreddata a liquido, anche il liquido di raffreddamento. I serbatoi non sono sigillati per sempre.', 'Le frasi ''non vi sono liquidi'' e ''serbatoi sono sigillati'' sono le parole trappola che rendono la frase falsa. Ci sono liquidi e i serbatoi sono controllabili.', 'Moto: tanti liquidi da controllare!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25452, 'Questa affermazione è falsa. L''olio motore si controlla con il motore spento (perché l''olio deve scendere nella coppa) e con la moto dritta, non sul cavalletto (perché il cavalletto la inclina e la lettura non è corretta).', 'Le condizioni ''motore in funzione al minimo'' e ''moto sistemata sul cavalletto'' sono entrambe sbagliate per il controllo dell''olio.', 'Olio: motore spento, moto dritta.')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25453, 'Questa affermazione è falsa. La maggior parte dei motocicli moderni ha freni idraulici, che usano un liquido per funzionare. Quindi, hanno un serbatoio per il liquido dei freni. Solo alcuni freni molto vecchi o particolari sono puramente meccanici.', 'Le frasi ''non sono dotati'' e ''puramente meccanico'' sono le parole che rendono la frase falsa. I freni sono quasi sempre idraulici.', 'Freni moto: quasi sempre idraulici, con liquido!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (25454, 'Questa affermazione è falsa. Se una moto è ''raffreddata ad aria'', significa che non usa un liquido per raffreddare il motore, ma solo l''aria che passa sulle alette. Quindi, non c''è nessun ''liquido di raffreddamento'' da controllare.', 'C''è una contraddizione tra ''raffreddati ad aria'' e ''liquido di raffreddamento''. Se è raffreddata ad aria, non ha liquido di raffreddamento.', 'Raffreddamento ad aria = no liquido!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31011, 'È assolutamente vero. Ogni distrazione (cellulare, passeggeri, pensieri) aumenta il rischio di incidenti, anche molto gravi.', 'Le parole ''può causare'' e ''possono comportare'' indicano una possibilità, non una certezza, ma il rischio è altissimo e reale.', 'Distrazione = Rischio incidente!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31012, 'Gli incroci sono punti molto pericolosi. Devi essere concentratissimo per vedere altri veicoli, pedoni e rispettare le precedenze.', 'La frase ''massima concentrazione'' è corretta e sottolinea l''importanza di essere molto attenti.', 'Incrocio = Concentrazione massima!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31013, 'Anche un attimo di distrazione può essere fatale. A velocità elevate, in pochi millisecondi si percorrono molti metri senza vedere la strada.', 'La frase ''anche per pochi millisecondi'' sottolinea quanto sia pericolosa anche una minima distrazione.', 'Occhi sulla strada = Sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31014, 'È fondamentale osservare e cercare di capire cosa faranno gli altri (pedoni, ciclisti, altri veicoli) per anticipare pericoli e guidare in sicurezza.', 'La frase ''valutare attentamente il comportamento degli altri'' è una parte essenziale della guida preventiva.', 'Guida sicura = Prevedi gli altri!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31015, 'Condizioni come pioggia, nebbia, buio o sole basso rendono più difficile vedere i pericoli e rallentano i tempi di reazione.', 'La frase ''sono influenzate'' è corretta, le condizioni ambientali hanno un grande impatto.', 'Ambiente difficile = Reazione lenta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31016, 'L''ansia ti rende meno lucido, ti distrae e ti impedisce di concentrarti bene sui pericoli della strada.', 'La frase ''può ridurre'' indica una possibilità reale e negativa per l''attenzione.', 'Ansia = Attenzione giù!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31017, 'È importante essere umili e riconoscere che a volte ci si può sopravvalutare, specialmente quando si è stanchi o sotto stress.', 'La frase ''non sempre è in grado di valutare correttamente'' è un invito all''autocritica e alla prudenza.', 'Conosci i tuoi limiti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31018, 'La musica troppo alta può distrarre, impedirti di sentire rumori importanti (clacson, sirene) e aumentare lo stress.', 'La frase ''può essere influenzata anche'' indica che è un fattore di distrazione, tra gli altri.', 'Musica alta = Meno attenzione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31019, 'Una discussione accesa o una conversazione troppo coinvolgente ti distrae dalla strada e può farti perdere la concentrazione.', 'La frase ''può influenzare negativamente'' indica che le distrazioni verbali sono un rischio.', 'Parla meno, guida meglio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31020, 'In caso di dubbio, la sicurezza viene prima di tutto. Meglio fermarsi e aspettare che la situazione sia chiara e sicura.', 'Le frasi ''Se non si è certi'' e ''è necessario arrestarsi'' sottolineano che la prudenza è d''obbligo.', 'Dubbio = Fermati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31021, 'Rumori forti o comportamenti vivaci dei passeggeri sono una fonte di distrazione che può ridurre la tua attenzione alla guida.', 'La frase ''può influenzare'' indica una possibile causa di distrazione.', 'Silenzio = Concentrazione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31022, 'Devi avere una visione completa: guardare avanti, ma anche ai lati (pedoni, ciclisti, veicoli che escono) e usare gli specchietti per il dietro.', 'La struttura ''sia a... sia a...'' indica la necessità di un''attenzione a 360 gradi.', 'Occhi ovunque!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31023, 'Anche se utile, guardare troppo il navigatore ti distoglie dalla strada. Meglio ascoltare le indicazioni vocali o guardarlo solo quando sei fermo.', 'La frase ''può rappresentare un elemento di distrazione'' è corretta, è una possibilità reale.', 'Navigatore = Ascolta, non guardare troppo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31024, 'È importante essere realisti sulle proprie capacità. Sopravvalutarsi porta a prendere rischi inutili e pericolosi.', 'La frase ''non deve mai sopravvalutare'' è un principio di prudenza fondamentale.', 'Umiltà al volante!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31025, 'Le regole del Codice della Strada esistono proprio per proteggere tutti: conducenti, pedoni, ciclisti, rendendo la strada più sicura.', 'La frase ''per garantire una maggior sicurezza'' è lo scopo principale delle norme.', 'Norme = Sicurezza per tutti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31026, 'Le regole valgono per tutti (auto, moto, bici, pedoni) e il loro rispetto riduce i pericoli per tutti.', 'La frase ''tutti i veicoli, sia di quelli a motore, sia di quelli che ne sono privi'' sottolinea l''universalità delle norme.', 'Norme = Meno rischi per tutti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31027, 'Rispettare le regole (es. parcheggio, precedenze) aiuta il traffico a scorrere meglio e a evitare code e rallentamenti.', 'La frase ''limitare l’intralcio'' è un beneficio aggiuntivo del rispetto delle norme.', 'Norme = Traffico fluido!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31028, 'È una delle principali cause di incidenti. Il cellulare distrae la vista, la mente e le mani dalla guida.', 'La frase ''riduce l’attenzione'' è la conseguenza diretta e pericolosa dell''uso del cellulare.', 'Cellulare = Attenzione zero!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31029, 'Anche se hai le mani libere, parlare al telefono (anche in vivavoce) impegna la tua mente e riduce la tua concentrazione sulla guida.', 'Le frasi ''anche se con impianto viva-voce'' e ''può ridurre'' indicano che la distrazione mentale è comunque presente.', 'Viva-voce = Mente distratta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31030, 'È un dato di fatto. Moltissimi incidenti avvengono perché il conducente non era concentrato sulla strada.', 'La frase ''una delle principali cause'' è un''affermazione corretta e importante da ricordare.', 'Distrazione = Causa incidenti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31031, 'La stanchezza riduce i riflessi, la capacità di concentrazione e aumenta il rischio di addormentarsi al volante.', 'La frase ''diminuisce quando si è affaticati'' è corretta, la stanchezza è un nemico dell''attenzione.', 'Stanco = Fermati!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31032, 'Guardare lo schermo e toccare i comandi del navigatore mentre si è in movimento distrae la vista e la mente dalla guida.', 'La frase ''riduce l’attenzione'' è la conseguenza diretta di questa azione.', 'Navigatore in marcia = Distrazione!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31033, 'Con la pratica e l''esperienza, si può migliorare la propria capacità di concentrazione e di anticipare i pericoli.', 'La parola ''allenare'' indica che l''attenzione è una capacità che si può sviluppare e migliorare.', 'Pratica = Attenzione migliore!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31034, 'I nostri sensi hanno dei limiti. Non possiamo percepire ogni singolo dettaglio o stimolo, specialmente se siamo distratti o l''ambiente è complesso.', 'La frase ''non riescono a cogliere tutti gli stimoli'' è corretta, è una limitazione umana.', 'Sensi = Limiti, non tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31035, 'Emozioni forti (rabbia, tristezza, euforia) possono distrarci, farci perdere la concentrazione e influenzare negativamente la guida.', 'La parola ''influenzano'' è corretta, le emozioni hanno un impatto diretto sull''attenzione.', 'Emozioni forti = Guida a rischio!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31036, 'È vero, a volte per imprudenza o sopravvalutazione delle proprie capacità, si affrontano situazioni troppo pericolose.', 'La frase ''A volte'' indica una possibilità, ma reale, di esporsi a rischi eccessivi.', 'Non rischiare troppo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31037, 'Non devi mai distogliere lo sguardo dalla strada, nemmeno per un attimo. Un pericolo può presentarsi all''improvviso, anche quando non te lo aspetti.', 'La frase ''quando ritiene che non ci sia pericolo imminente'' è la trappola. Il tuo giudizio non è sufficiente, il pericolo è sempre possibile.', 'Occhi sulla strada = Sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31038, 'Anche se sei fermo a un incrocio, sei comunque alla guida. Usare il cellulare è vietato e distrae, anche per un ''rapido messaggio''.', 'La frase ''può inviare un rapido messaggio'' è la trappola. Anche un messaggio rapido è una distrazione vietata quando si è alla guida, anche se fermi nel traffico.', 'Cellulare = Solo a veicolo spento!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31039, 'La precedenza agli incroci si basa su regole precise (segnali, destra), non sulla velocità. Arrivare veloci è pericoloso e può causare incidenti.', 'La frase ''deve sopraggiungervi più velocemente'' è la trappola. La precedenza non si ''conquista'' con la velocità, ma si rispetta secondo le regole.', 'Precedenza = Regole, non velocità!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31040, 'Usare il cellulare (anche solo per comporre un numero) mentre si guida è sempre vietato e pericoloso, perché distrae l''attenzione dalla strada, anche se non vedi un pericolo immediato.', 'Le espressioni ''qualora il conducente ritenga non vi sia pericolo imminente'' e ''senza fermarsi'' sono le parole trappola. Il tuo giudizio sul pericolo non annulla il divieto e il rischio.', 'Cellulare al volante = MAI!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31041, 'È molto importante osservare e prevedere cosa fanno gli altri (pedoni, ciclisti, altri veicoli) per guidare in sicurezza e prevenire incidenti.', 'La parola ''ininfluente'' è la trappola. Il comportamento degli altri è sempre molto influente per la sicurezza.', 'Guida sicura = Occhi su tutti!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31042, 'Anche se gli altri sbagliano, tu devi sempre stare attento e prevedere i loro errori per evitare incidenti. La sicurezza è la tua responsabilità.', 'La frase ''può non tenere conto'' è la trappola. Devi sempre tenere conto di tutti, anche di chi sbaglia, per la tua sicurezza e quella degli altri.', 'Prevedi gli errori altrui!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31043, 'Le condizioni ambientali (pioggia, nebbia, buio) influenzano molto quanto velocemente vedi un pericolo e come reagisci. Riducono la visibilità e i tempi di reazione.', 'La negazione ''non sono influenzate'' è la trappola. È il contrario, sono molto influenzate.', 'Ambiente difficile = Attenzione doppia!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31044, 'Devi sempre valutare i pericoli in modo realistico, senza sottovalutarli. Sottostimare un pericolo significa non essere preparato ad affrontarlo.', 'La parola ''sottostimare'' è la trappola. Mai sottovalutare i pericoli, ma valutarli correttamente per essere pronti a reagire.', 'Pericolo = Valuta, non sottovaluta!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31045, 'La tua priorità è la sicurezza. Non devi mai farti influenzare dai passeggeri a guidare in modo pericoloso o a superare i limiti di velocità.', 'La frase ''deve accogliere gli inviti'' è la trappola. Non devi mai cedere a pressioni che mettono a rischio la sicurezza.', 'Guida tu, non i passeggeri!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31046, 'Devi guardare lontano, non solo i pochi metri davanti a te. Questo ti permette di vedere i pericoli in anticipo e avere tempo per reagire.', 'La frase ''prevalentemente sul tratto di strada non superiore a tre metri'' è la trappola. È troppo poco, devi avere una visione d''insieme e guardare lontano.', 'Guarda lontano, pensa in anticipo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31047, 'Programmare il navigatore mentre guidi ti distrae dalla strada ed è pericoloso. Fallo sempre prima di partire o quando sei fermo in sicurezza.', 'La frase ''in qualsiasi momento'' è la trappola. No, solo quando sei fermo e in sicurezza.', 'Navigatore = Fermo e sicuro!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31048, 'Tutti gli specchi retrovisori sono importanti per tutti i conducenti, esperti e non. Servono per vedere cosa succede dietro e di lato al veicolo.', 'La frase ''solo da conducenti esperti'' è la trappola. È un''affermazione esclusiva e falsa; tutti devono usarli.', 'Specchi = Per tutti, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31049, 'Gli specchi vanno regolati prima di partire, quando il veicolo è fermo. Regolarli in movimento ti distrae e ti fa perdere il controllo.', 'La frase ''devono essere regolati mentre il veicolo è in movimento'' è la trappola. È pericoloso e sbagliato.', 'Regola specchi = Veicolo fermo!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31050, 'Le norme servono per la sicurezza di tutti, non solo per evitare multe. Rispettarle salva vite e previene incidenti, indipendentemente dalla multa.', 'La frase ''solo se la loro violazione comporta una sanzione economica elevata'' è la trappola. La sicurezza è la ragione principale, non la multa.', 'Norme = Sicurezza, non solo multe!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31051, 'Le norme sono importanti per TUTTI gli utenti della strada, sia per i pedoni e ciclisti (utenti deboli) sia per i conducenti di auto, per garantire la sicurezza di tutti.', 'La frase ''ma non per i conducenti degli autoveicoli'' è la trappola. È una distinzione falsa, le norme valgono per tutti.', 'Norme = Per tutti, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31052, 'Le norme vanno rispettate sempre, in ogni condizione di traffico. Anche con traffico scorrevole, non rispettarle può causare incidenti gravi.', 'La frase ''ma non quando si è in condizioni di circolazione scorrevole'' è la trappola. Le norme valgono sempre.', 'Norme = Sempre, non solo nel traffico!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31053, 'Un divieto di sorpasso è un divieto. Non puoi decidere tu di ignorarlo, anche se sei in coda o pensi sia sicuro. Le regole vanno rispettate.', 'Le frasi ''può non essere osservato'' e ''si ritiene di poter sorpassare senza pericoli'' sono le trappole. Il tuo giudizio personale non annulla un divieto.', 'Divieto = Divieto, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31054, 'La posizione sulla carreggiata è una norma fondamentale per la sicurezza e la fluidità del traffico. Non è ''secondaria'' e va sempre rispettata.', 'Le frasi ''norma secondaria'' e ''può, se del caso, non essere osservata'' sono le trappole. È una norma primaria e obbligatoria.', 'Posizione = Fondamentale, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31055, 'L''attenzione alla guida deve essere massima in ogni momento, non solo durante manovre ''pericolose''. Anche una semplice rettilinea può nascondere pericoli.', 'La parola ''solo'' è la trappola. L''attenzione è sempre necessaria, non solo in situazioni specifiche.', 'Attenzione = Sempre, non solo in manovra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31056, 'L''alcol, anche in piccole quantità, riduce sempre l''attenzione e i riflessi, non li migliora. È molto pericoloso bere e guidare.', 'La frase ''permette di migliorare l’attenzione'' è la trappola. L''alcol fa l''esatto contrario.', 'Alcol = Mai al volante!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31057, 'Qualsiasi azione che ti distoglie dalla guida (anche sintonizzare l''autoradio) riduce l''attenzione, anche se sei abituato a farla.', 'Le frasi ''non comporta perdita di attenzione'' e ''perché è un compito che si è abituati a svolgere'' sono le trappole. Ogni distrazione è pericolosa.', 'Distrazione = Pericolo, sempre!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31058, 'Anche una piccola quantità di alcol (ebbrezza lieve) riduce le tue capacità di guida e la tua sicurezza. Non si guida mai in sicurezza sotto l''effetto dell''alcol.', 'La frase ''si riesce a guidare comunque in sicurezza'' è la trappola. È falso, l''alcol compromette sempre la sicurezza.', 'Alcol = Zero sicurezza!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31059, 'La nostra attenzione è limitata. Non possiamo concentrarci su troppe cose contemporaneamente. Per questo le distrazioni sono pericolose.', 'La parola ''illimitata'' è la trappola. La nostra attenzione è sempre limitata.', 'Attenzione = Limitata, non sprecarla!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31060, '0,5 g/l è il limite legale in Italia per i conducenti esperti, ma anche a questo livello l''alcol riduce le capacità di guida, non le migliora. Per i neopatentati il limite è 0.', 'La frase ''si riesce a concentrarsi meglio'' è la trappola. L''alcol non migliora mai la concentrazione alla guida.', 'Alcol = Concentrazione zero!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31061, 'I nostri sensi hanno dei limiti. Non possiamo percepire tutto ciò che ci circonda, specialmente quando siamo distratti o stanchi.', 'La frase ''tutti gli stimoli'' è la trappola. È impossibile cogliere proprio tutto.', 'Sensi = Limiti, non tutto!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31062, 'I nostri sensi hanno una soglia. Non possiamo percepire stimoli troppo deboli o troppo forti.', 'La frase ''di qualunque intensità'' è la trappola. I sensi hanno limiti di intensità.', 'Sensi = Limiti di intensità!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31063, 'Lo stress, specialmente se eccessivo, riduce la capacità di attenzione e reazione, rendendo la guida più pericolosa, non più vigile.', 'La frase ''può aiutare il conducente a mantenersi vigile'' è la trappola. Lo stress eccessivo fa l''opposto.', 'Stress = Nemico della guida!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;

insert into spiegazioni (numero_domanda, spiegazione, focus_linguistico, regola_chiave)
VALUES (31064, 'L''udito è molto importante! Ti permette di sentire clacson, sirene, rumori del motore o di altri veicoli, aiutandoti a percepire pericoli.', 'La negazione ''non è un senso importante'' è la trappola. È un senso fondamentale.', 'Udito = Allerta extra!')
ON CONFLICT(numero_domanda) DO UPDATE SET
    numero_domanda = excluded.numero_domanda,
    spiegazione = excluded.spiegazione,
    focus_linguistico = excluded.focus_linguistico,
    regola_chiave = excluded.regola_chiave;


